local P = LoreForeverPacks.Begin("LoreForever_Lang_deDE")
P.entries["topic:syndicate"] = {n="Syndikat",s="Im nördlichen Lordaeron hält das Syndikat Festungen und kämpft um die Rückeroberung Alteracs. Enteignete Adlige führen diese menschliche Verbrecherorganisation gegen die Allianz und die Horde, um ihre verlorene Adelsherrschaft wiederherzustellen.",h="Im nördlichen Lordaeron hält das Syndikat Festungen und kämpft um die Rückeroberung Alteracs.",kw={"aliden perenolde","alterac","bandanas","burg durnholde","falconcrest","rabenholdt","strahnbrad","stromgarde","syndikat","das oberland"},ang={["class:Rogue"]="Rabenholdt bezahlt Diebe dafür, hinter die feindlichen Linien zu schleichen und Banditen des Syndikats Embleme zu stehlen, und nutzt dabei deren Angst vor einem Rangverlust aus.",["faction:Alliance"]="Agenten des Syndikats ermordeten den früheren Magistrat von Süderstade und treiben die bedrängte Stromgarde-Miliz im Arathihochland weiter an den Rand der Vernichtung.",["faction:Horde"]="Kriegshäuptling Thrall und Lady Sylvanas haben beide weiterhin Kopfgelder auf das Syndikat ausgesetzt. Sie entsenden Späher, um seine Lager zu zerstören und gestohlene Relikte zurückzuholen.",["race:Orc"]="Das Syndikat betrachtet Euer Volk als Bestien, denen Ketten und Internierung bestimmt sind. Gefangene Brüder in Strahnbrad und Durnholde zu befreien, ist eine Frage der Ehre."},sec={{t="Gefallener Adel",b="Nach dem Verrat von König Aiden Perenolde während des Zweiten Krieges brach das Königreich Alterac in Schande zusammen. Sein Adel verlor Land und Titel, doch die überlebenden Adligen weigerten sich, das Exil hinzunehmen. Sie scharten sich um den Sohn des verstorbenen Königs, Prinz Aliden Perenolde, und gründeten das Syndikat.\n\nSie trugen orangefarbene Bandanas als Erkennungszeichen und füllten ihre Reihen mit angeheuerten Schlägern, Straßenräubern und selbsternannten Zauberern. Für Außenstehende sind sie Banditen, die Karawanen überfallen, Reisenden auflauern und Menschen erpressen. Doch ihre Verbrechen dienen allein dazu, einen organisierten Versuch zu finanzieren, ihre angestammten Ländereien zurückzuerobern und die umliegenden Regionen zu unterwerfen."},{t="Festungen des Nordens",b="Im nördlichen Lordaeron hält das Syndikat befestigte Stellungen. Im verschneiten Alteracgebirge befestigten sie die zerstörte Stadt Strahnbrad und errichteten Lager im Oberland und in Dandreds Senke. Weiter südlich halten sie die verfallende Burg Durnholde im Vorgebirge des Hügellands. Von dort aus setzen sie Süderstade zu und überfallen Versorgungsrouten.\n\nWeiter östlich, jenseits von Thoradinswall, befehligt Lord Falconcrest eine Besatzungsarmee des Syndikats in den geschichtsträchtigen Ruinen von Burg Stromgarde. Dort kämpfen sie gegen die angeschlagene Stromgarde-Miliz um die Kontrolle über das Arathihochland."},{t="Feinde an allen Fronten",b="Die Ambitionen des Syndikats reichen über gewöhnliches Banditentum hinaus und bringen ihm den Hass fast aller Fraktionen der Region ein. Sie nennen die Allianz ihren Todfeind und glauben, sie habe ihnen ihr rechtmäßiges Erbe gestohlen. Ihre Angriffe richten sich oft gegen Amtsträger aus Süderstade wie Magistrat Henry Maleb.\n\nDer Horde begegnen sie mit offener Verachtung. Der Philosophie von Aedelas Blackmoore folgend betrachten sie Orcs als Bestien, die sich zur Sklavenarbeit eignen, und wollen die Internierungslager wiedererrichten. Sylvanas Windläufers Verlassene richten gefangene Mitglieder des Syndikats auf der Stelle hin. Die geheime Diebesgilde von Rabenholdt führt einen Schattenkrieg gegen Agenten des Syndikats, die sie für nachlässig und arrogant hält."},{t="Marionetten des Schattenrats",b="Die adligen Anführer des Syndikats glauben, für die Vorherrschaft der Menschen und ihr Geburtsrecht zu kämpfen. Doch Kultisten des Argus Wake haben die oberen Ränge unterwandert und lenken Männer wie Lord Falconcrest dahin, Burg Stromgarde einzunehmen.\n\nDer Argus Wake untersteht dem Schattenrat in Jaedenar im Teufelswald. Er nutzt die Armeen und geraubten Ländereien des Syndikats als sterbliche Vorhut, die der Brennenden Legion den Weg ebnet."}},faq={{q="Wer ist das Syndikat?",a="Das Syndikat ist eine Verbrecherorganisation aus enteigneten Adligen, Banditen und Söldnern des gefallenen Alterac. Verbannte Aristokraten wie Prinz Aliden Perenolde und Lord Falconcrest führen sie an. Durch Straßenraub, Meuchelmord und militärische Besatzung versuchen sie, Alterac wiederaufzubauen.",al={"was ist das syndikat","hintergrund des syndikats","wer sind diese kerle in orange"}},{q="Warum hasst das Syndikat die Allianz?",a="Alterac verriet die Allianz von Lordaeron während des Zweiten Krieges, und die Allianz zerschlug das Königreich und entzog seinen Adligen ihre Ländereien. Die Anführer des Syndikats betrachten die Allianz als ihren Todfeind und sabotieren ihre Städte, Handelskarawanen und Garnisonen wie Burg Stromgarde.",al={"warum greift das syndikat die allianz an","beziehung zwischen syndikat und allianz","alterac gegen allianz"}},{q="Warum nimmt das Syndikat Orcs gefangen und versklavt sie?",a="Das Syndikat folgt der harten Philosophie des ehemaligen Kommandanten von Durnholde, Aedelas Blackmoore, der Orcs als wilde Bestien betrachtete, die nur zur unbezahlten Knechtschaft taugten. Prinz Aliden Perenolde wollte die Internierungslager der Allianz wiedererrichten und im Vorgebirge des Hügellands und in Alterac gefangene, versklavte Orcs als Zwangsarbeiter einsetzen.",al={"orcsklaven des syndikats","warum sind orcs in strahnbrad in käfigen","sklaverei beim syndikat"}},{q="Wie steht das Syndikat zu Rabenholdt?",a="Rabenholdt ist eine angesehene Gilde professioneller Meuchelmörder und Diebe im Alteracgebirge. Ihre Mitglieder halten das Syndikat für dilettantisch und undiszipliniert und beauftragen Schurken damit, Embleme des Syndikats zu stehlen. Die Anführer des Syndikats lassen Agenten, die ihr Emblem verlieren, erbarmungslos töten.",al={"rabenholdt gegen syndikat","warum hasst rabenholdt das syndikat","embleme des syndikats"}},{q="Wer zieht hinter dem Syndikat wirklich die Fäden?",a="Nach außen untersteht das Syndikat verbannten Adligen aus Alterac wie Prinz Aliden Perenolde und Lord Falconcrest. Sie glauben, für die Rückgewinnung ihrer verlorenen Titel zu kämpfen. Doch Gerüchte im Arathihochland deuten auf finstere Mächte hinter ihrer Herrschaft über Stromgarde hin, und Reisende können dem in den dortigen Festungen des Syndikats nachgehen.",al={"wer führt das syndikat an","argus wake syndikat","schattenrat syndikat"}},{q="Wo liegen die wichtigsten Festungen des Syndikats?",a="Die wichtigsten Festungen des Syndikats verteilen sich über das Alteracgebirge, das Vorgebirge des Hügellands und das Arathihochland. Sie halten Strahnbrad und Dandreds Senke in Alterac, Burg Durnholde in Hillsbrad und den Nordhof in Arathi. Unter Lord Falconcrest besetzen sie außerdem einen großen Teil von Burg Stromgarde.",al={"wo sind die stützpunkte des syndikats","standorte des syndikats","wo ist das syndikat zu finden"}}},fx={["1053e6ff"]={q="Warum ist das Syndikat Reisenden gegenüber feindselig?",a="Das Syndikat betrachtet alle Außenstehenden als Bedrohung für seine kriminellen Pläne und territorialen Ambitionen. Sie verachten die Allianz dafür, dass sie Alterac nach dem Zweiten Krieg zerschlagen hat, betrachten die Horde lediglich als rohe Gewalt, die nur zur Zwangsarbeit taugt, und dulden keine Einmischung in ihre Banditentum, Attentate und Überfälle.",al={"warum greift das syndikat an","syndikat feindselig","warum greift das syndikat spieler an"}},["8dd05730"]={q="Wer führt das Syndikat?",a="Die Organisation wurde im Alteracgebirge von Prinz Aliden Perenolde, dem Sohn des verräterischen verstorbenen Königs von Alterac, gegründet und angeführt. Im Arathihochland werden die Operationen von Lord Falconcrest von den Ruinen von Burg Stromgarde aus geleitet, unterstützt von regionalen Aufsehern wie Baron Vardus und Meister Ryson.",al={"anführer des syndikats","wer leitet das syndikat","boss des syndikats"}},c949a5e9={q="Mit wem ist das Syndikat verbündet?",a="Offen verlassen sie sich auf schurkische Söldner, Banditen und korrupten menschlichen Adel, während sie fast jede etablierte Fraktion bekämpfen. Im Geheimen jedoch wird das Syndikat von den Argus Wake manipuliert, einem finsteren Hexenmeisterzirkel, der dem Schattenrat in Jaedenar dient und versprach, die Herrschaft von Alterac im Austausch für Stützpunkte in ganz Nord-Lordaeron wiederherzustellen.",al={"verbündete des syndikats","wer arbeitet mit dem syndikat zusammen","partner des syndikats"}},ff7f041a={q="Woher kommt das Syndikat?",a="Das Syndikat entstand aus den Ruinen des Königreichs Alterac. Nachdem König Aiden Perenolde die Allianz während des Zweiten Krieges verraten hatte, wurde Alterac die Souveränität entzogen und es verfiel. Abgesetzte Adlige und verärgerte Aristokraten schlossen sich unter Prinz Aliden Perenolde zusammen und wandten sich Schmuggel, Banditentum und Terrorismus zu, um ihr verlorenes Land zurückzuerobern.",al={"ursprung des syndikats","geschichte des syndikats","wie entstand das syndikat"}}},fp="9,231,15.622.0,24.554.0,21.649.0,29.411.2,22.286.0,41.283.0,48.314.1,53.278.0,55.331.2,46.303.0"}
P.entries["topic:tauren"] = {n="Tauren",s="Im zentralen Kalimdor bauen die Tauren eine Heimat in Mulgore auf und bewahren dabei ihre alten Bräuche. Sie nennen sich Shu'halo und ehren die Erdenmutter, den Schamanismus und die Natur. Zentaurenklans hätten sie beinahe vernichtet, bevor sie sich Thralls New Horde anschlossen. Oberhäuptling Cairne Bluthuf führt sie nun von Mulgore und Donnerfels aus.",h="Im zentralen Kalimdor bauen die Tauren eine Heimat in Mulgore auf und bewahren dabei ihre alten Bräuche.",kw={"brachland","cairne bluthuf","zentauren","erdenmutter","hamuul runetotem","kodo","magatha grimmtotem","mulgore","shu'halo","tauren","donnerfels"},ang={["class:Druid"]="Durch Erzdruide Hamuul Runetotem arbeiten Taurendruiden mit den Nachtelfen des Zirkels des Cenarius daran, das Land zu heilen und den Smaragdgrünen Traum zu schützen.",["class:Shaman"]="Die schamanischen Traditionen der Tauren zählen zu den ältesten Azeroths. Ihre Lehren halfen den Orcs, nach der dämonischen Verderbnis vergangener Kriege ihre heilige Verbindung zu den Elementen wiederzuentdecken.",["faction:Horde"]="Die Tauren geben der Horde moralische Orientierung und tiefe spirituelle Wurzeln und zügeln die aggressiven Instinkte von Orcs und Trollen mit uralter Weisheit und Ehre.",["race:Tauren"]="Als Shu'halo habt Ihr erlebt, wie die uralten nomadischen Wanderungen Eures Volkes einer Heimat in Mulgore wichen, gesichert durch die brüderliche Verbundenheit zwischen Cairne und Thrall."},sec={{t="Nomaden des Brachlands",b="Seit unzähligen Generationen durchstreiften die Tauren mit den Jahreszeiten das trockene Brachland. Sie jagten die großen Kodos und lauschten auf die Stimme der Erdenmutter. Dann setzten die Zentaurenstämme ihren friedlichen Wanderungen ein Ende. Die wilden Zentauren, hervorgegangen aus der tragischen Verbindung von Zaetar und Prinzessin Theradras, führten einen unerbittlichen Krieg gegen sie. Ohne eine befestigte Heimat und nicht gewillt, endlos zu kämpfen, wurden die Tauren an den Rand der Vernichtung getrieben."},{t="Die New Horde und Donnerfels",b="Ein Bündnis von jenseits des Meeres gab den Tauren eine Chance zu überleben. Während des Dritten Krieges begegnete Cairne Bluthuf Kriegshäuptling Thrall und den neu angekommenen Orcs. Die Anführer erkannten ihre gemeinsame Ehre und Sehnsucht nach ihrem schamanischen Erbe und schlossen sich zusammen.\n\nMit der Hilfe der Horde besiegten die Tauren die marodierenden Zentauren und beanspruchten das geschützte Grasland von Mulgore. Cairne gründete Donnerfels auf Mulg ores windgepeitschten Tafelbergen. Aus Dankbarkeit zogen die Tauren mit der Horde zum Hyjal und halfen, die Brennende Legion zurückzuschlagen."},{t="Spirituelle Hüter und innere Spannungen",b="Die Tauren bringen eine friedliche, besonnene Stimme in die Horde ein. Ihre Beherrschung der Natur und der Elemente half, den Schamanismus der Orcs wiederzubeleben. Erzdruide Hamuul Runetotem pflegt zudem seltene diplomatische und spirituelle Bande mit Nachtelfendruiden, während sie die wachsende Verderbnis im Smaragdgrünen Traum untersuchen.\n\nDoch die Einheit der Stämme bleibt zerbrechlich. Die meisten verehren Cairnes Weisheit, doch der fremdenfeindliche und skrupellose Klan der Grimmtotem lebt in Donnerfels. Seine Anführerin, die intrigante Greisin Magatha, plant heimlich, die Führung an sich zu reißen und die Shu'halo zur Vorherrschaft zu führen."}},faq={{q="Warum schlossen sich die Tauren der Horde an?",a="Skrupellose Zentaurenklans hätten die Tauren im Brachland beinahe ausgelöscht. Während des Dritten Krieges kämpften Kriegshäuptling Thrall und seine Orcs an Cairne Bluthufs Seite, drängten die Zentauren zurück und halfen, Mulgore zu sichern. Verbunden durch Ehre und gemeinsame spirituelle Werte, schwor Cairne der New Horde aus Dankbarkeit die Treue seines Volkes.",al={"warum der horde beitreten","tauren bündnis mit der horde","warum sind tauren in der horde"}},{q="Wer führt die Tauren?",a="Oberhäuptling Cairne Bluthuf führt die Tauren und steht dem Bloodhoof-Stamm vor. Für seine Stärke und sein besonnenes Urteil geachtet, vereint er die Stämme von Donnerfels aus, unterstützt von Erzdruide Hamuul Runetotem und der Greisin Magatha Grimmtotem.",al={"anführer der tauren","häuptling der tauren","wer herrscht über donnerfels"}},{q="Was ist die Erdenmutter?",a="Die Erdenmutter ist die zentrale Gottheit im Glauben der Tauren. Die Shu'halo glauben, dass sie die Welt, die Sonne und den Mond erschaffen hat. Sie ehren sie durch ein Leben im Einklang mit dem Gleichgewicht der Natur, jahreszeitliche Wanderungen, die Jagd und Achtung vor den Elementen.",al={"erdenmutter","wer ist die erdenmutter","religion der tauren"}},{q="Warum hassen die Tauren die Zentauren?",a="Zentauren jagten die Tauren zum Vergnügen und führten jahrhundertelang im zentralen Kalimdor Krieg gegen sie. Sie sahen die friedliche Spiritualität der Tauren als Schwäche, trieben sie von Ort zu Ort und hätten die Shu'halo beinahe ausgelöscht, bevor die Orcs eingriffen.",al={"krieg zwischen tauren und zentauren","fehde mit den zentauren"}},{q="Können Tauren Druiden sein?",a="Ja. Erzdruide Hamuul Runetotem führt die Taurendruiden, die gemeinsam mit Nachtelfen die Wege der Wildnis erlernen. Taurendruiden sind eine tragende Säule des Zirkels des Cenarius.",al={"geschichte der taurendruiden","wie wurden tauren zu druiden"}},{q="Sind alle Tauren Cairne Bluthuf treu?",a="Die meisten Taurenstämme verehren Cairne, doch die Grimmtotem sind eine erbitterte Ausnahme. Unter Magatha Grimmtotems Führung halten sie Tauren für allen anderen Völkern überlegen und verachten Cairnes Bündnis mit der Horde. Im Stillen arbeiten sie daran, seine friedliche Herrschaft zu untergraben.",al={"treue der grimmtotem","bürgerkrieg der tauren"}},{q="Welche Klassen können Tauren spielen?",a="Tauren lassen sich zu Kriegern, Jägern, Schamanen und Druiden ausbilden.",al={"klassen der tauren","welche klassen können tauren spielen"}}},fp="6,342,21.443.0,31.534.0,41.562.1,34.311.0,21.251.0,25.240.0,35.246.0,21.166.0,41.250.0,28.53.0"}
P.entries["topic:terenas-menethil-ii"] = {n="Terenas Menethil II.",s="In ganz Lordaeron trägt Terenas Menethil II. die Last des Krieges und seiner Folgen. Mehr als fünf Jahrzehnte regierte er als weiser und diplomatischer König, schmiedete im Zweiten Krieg die Allianz von Lordaeron und gewährte dem jungen Prinzen Varian Wrynn Zuflucht. Sein korrumpierter Sohn, Prinz Arthas, ermordete ihn, und Lordaeron begann, der Geißel anheimzufallen.",h="In ganz Lordaeron trägt Terenas Menethil II.",kw={"allianz von lordaeron","arthas","capital city","frostmourne","lordaeron","menethil","zweiter krieg","terenas","dritter krieg","uther"},ang={["class:Paladin"]="Als Paladin folgt Ihr einem Weg, den Terenas gemeinsam mit Erzbischof Alonsus Faol und Uther dem Lichtbringer mitgestaltete. Gemeinsam förderten sie die Ritter der Silbernen Hand. Terenas führte seinen eigenen Sohn in den Orden.",["faction:Alliance"]="Als Mitglied der Allianz erbt Ihr die Koalition, die Terenas mit Anduin Lothar schmiedete, um die Alte Horde im Zweiten Krieg zu besiegen.",["race:Human"]="Als Mensch erinnert Ihr Euch an König Terenas als legendären Patriarchen, der die sieben Königreiche trotz schier aussichtsloser Lage vereinte. Der unvermittelte Verrat und seine Ermordung durch den eigenen Sohn bleiben eine nationale Tragödie.",["race:Undead"]="Als Verlassener nanntet Ihr Capital City unter Terenas, Eurem letzten lebenden Herrscher, einst Eure Heimat. Sein Sturz lieferte das Reich der Geißel aus."},sec={{t="Baumeister der Allianz",b="Als Flüchtlinge aus Sturmwind mit Sir Anduin Lothar den Norden erreichten, erhörte König Terenas Menethil II. ihren Ruf. Er versammelte die Monarchen der zerstrittenen Menschenkönigreiche und Gesandte aus Eisenschmiede und Quel'Thalas. Gemeinsam gründeten sie die Allianz von Lordaeron. Terenas übertrug Lothar als ihrem Oberbefehlshaber das Kommando über ihre Heere, statt es selbst zu beanspruchen. Zum ersten Mal seit Jahrtausenden standen die Königreiche der Menschheit vereint. Gemeinsam besiegten sie die Alte Horde."},{t="Die Last des Sieges",b="Nach dem Zweiten Krieg bestand Terenas darauf, überlebende Orcs in Internierungslagern festzuhalten, statt sie hinzurichten. Er glaubte, der Frieden könne Bestand haben, sobald ihre dämonische Wut verflogen sei. Doch die Lager bürdeten Lordaerons Verbündeten hohe Steuern auf. Gilneas schottete sich hinter dem Greymane-Wall ab, Stromgarde verließ die Allianz wegen politischer Streitigkeiten, und die Hochelfen zogen sich vollständig zurück. Während die Koalition zerbrach, trug Terenas ihre Kosten."},{t="Der Sturz des Thrones",b="Terenas sah sich Orc-Aufständen unter Thrall, Gerüchten über Todeskulte im Norden und einer geheimnisvollen Seuche gegenüber. Ein wandernder Prophet drängte ihn, Lordaeron aufzugeben und über das Meer nach Kalimdor zu fliehen. Terenas tat den Propheten als verrückt ab.\n\nKurz darauf kehrte Prinz Arthas von seinem Feldzug im Norden zurück und wurde als Sieger gefeiert. Während der königlichen Feierlichkeiten kniete Arthas vor seinem Vater nieder, zog die Runenklinge Frostmourne und stieß sie Terenas ins Herz. Das Königreich lag in Trümmern."}},faq={{q="Wer war König Terenas Menethil II.?",a="König Terenas Menethil II. regierte Lordaeron mehr als fünfzig Jahre lang und prägte die Politik des Nordens. Im Zweiten Krieg gründete er die Allianz von Lordaeron, um die Horde zu bekämpfen. Bis zu seiner Ermordung regierte er von Capital City aus.",al={"wer ist terenas","terenas menethil","könig von lordaeron"}},{q="Wie starb Terenas?",a="Terenas starb im Thronsaal durch die Hand seines Sohnes, Prinz Arthas Menethil. Auf seiner Expedition nach Northrend von der Runenklinge Frostmourne korrumpiert, kehrte Arthas als gefeierter Sieger nach Capital City zurück. Er stieß die Klinge durch das Herz seines Vaters.",al={"wie starb terenas","arthas tötet vater","terenas tod"}},{q="Welche Beziehung hatte Terenas zu Sturmwind?",a="Terenas half Sturmwind zu überleben. Nachdem das südliche Königreich im Ersten Krieg gefallen war, gewährte er seinen Überlebenden Zuflucht und zog Prinz Varian Wrynn zusammen mit seinem eigenen Sohn Arthas auf. Er behandelte Varian wie einen zweiten Sohn, bis Sturmwind zurückerobert und wiederaufgebaut werden konnte.",al={"terenas und sturmwind","terenas und varian","half terenas sturmwind"}},{q="Warum zerbrach die Allianz von Lordaeron unter seiner Herrschaft?",a="Nach dem Zweiten Krieg entschied Terenas, gefangene Orcs in Internierungslagern festzuhalten, statt sie hinzurichten. Deren hohe Kosten schürten den Zorn der Mitgliedsreiche. Gilneas errichtete den Greymane-Wall und schottete sich ab, Stromgarde trat wegen politischer Streitigkeiten aus, und die Elfen von Quel'Thalas zogen sich vollständig zurück.",al={"warum zerbrach die allianz","warum verließen die königreiche lordaeron","steuern für internierungslager"}},{q="Wusste Terenas von der Plague of Undeath?",a="Terenas wusste von seltsamen Kulten und einer sich ausbreitenden Krankheit im Norden, unterschätzte jedoch die Gefahr. Dalaran drängte ihn, die Städte im Norden unter Quarantäne zu stellen, doch er zögerte aus Furcht vor weiterem Leid für sein Volk. Er schickte Prinz Arthas und Uther den Lichtbringer aus, um Nachforschungen anzustellen, ohne von der Falle zu ahnen, die sie erwartete.",al={"wusste terenas von der seuche","terenas reaktion auf die seuche"}},{q="Warum hörte Terenas nicht auf den geheimnisvollen Propheten?",a="Ein verhüllter Prophet kam in Terenas’ Ratssaal und drängte ihn, die Bevölkerung Lordaerons nach Westen, nach Kalimdor, zu evakuieren. Terenas tat ihn als wirren Eiferer ab. Er glaubte, seine Heere, Paladine und sein gefestigtes Königreich könnten den bevorstehenden Prüfungen standhalten.",al={"terenas und prophet","medivh und terenas","warum floh terenas nicht"}}},fx={be9b83e5={q="Wer waren die engsten Verbündeten von König Terenas?",a="Während seiner Herrschaft zählte Terenas König Thoras Trollbane von Stromgarde und Uther der Lichtbringer zu seinen engsten persönlichen Freunden und betrachtete Uther fast wie einen Bruder. Er nahm auch Prinz Varian Wrynn und Sir Anduin Lothar als Flüchtlinge auf und zog Varian zusammen mit Prinz Arthas wie einen zweiten Sohn auf. Obwohl Nationen wie Gilneas und Quel'Thalas die Allianz schließlich wegen Steuern und Grenzen verließen, behielt Terenas die standhafte Loyalität von Sturmwind, Eisenschmiede, Kul Tiras und den Kirin Tor von Dalaran bis zu seinem Tod.",al={"verbündete von terenas","wer unterstützte terenas","verbündete von könig terenas"}},aa06bf27={q="Was ist die Geschichte von König Terenas Menethil II.?",a="Geboren in die königliche Menethil-Dynastie, die Lordaeron über Generationen hinweg regierte, beaufsichtigte Terenas über fünf Jahrzehnte des Friedens und Wohlstands. Als Sturmwind im Ersten Krieg fiel, versammelte er die Menschenreiche, Hochelfen und Zwerge, um die ursprüngliche Allianz von Lordaeron zu bilden, und schlug die Horde im Zweiten Krieg erfolgreich zurück. Terenas plädierte dafür, besiegte Orks zu internieren, anstatt sie hinzurichten, was die Kassen der Allianz belastete und einige Königreiche vertrieb. Seine lange, edle Herrschaft endete abrupt, als sein eigener Sohn, Prinz Arthas, korrumpiert aus Nordend zurückkehrte und ihn im königlichen Thronsaal ermordete.",al={"geschichte von terenas","herrschaft von terenas menethil","geschichte von könig terenas"}}},fp="19,341,25.472.0,22.428.0,22.475.2,33.224.0,20.256.0,47.256.0,61.298.0,45.304.0,52.248.0"}
P.entries["topic:third-war"] = {n="Dritter Krieg",s="In Lordaeron und Kalimdor endete der Dritte Krieg erst, nachdem Sterbliche der Brennenden Legion die Stirn geboten hatten. Der Krieg begann mit der Seuche des Untods des Lichkönigs und brachte Lordaeron und Quel'Thalas vor der Verteidigung des Hyjal zu Fall.",h="In Lordaeron und Kalimdor endete der Dritte Krieg erst, nachdem Sterbliche der Brennenden Legion die Stirn...",kw={"archimonde","arthas","hyjal","mannoroth","medivh","nordrassil","geißel","stratholme","terenas","dritter krieg"},ang={["class:Paladin"]="Die Ritter der Silbernen Hand wurden im Krieg auseinandergerissen. Arthas löste ihren Orden auf, ermordete Uther den Lichtbringer und verwandelte ihre heiligen Hallen in Leichenhäuser.",["faction:Alliance"]="Lordaerons Fall verlagerte die Führung der Allianz nach Süden, nach Sturmwind und Eisenschmiede. Überlebende blicken nach Norden und sehnen sich danach, ihre Heimat zurückzuerobern.",["faction:Horde"]="Für Thralls Horde brachte der Krieg Erlösung. Grommash Hellscream erschlug Mannoroth und brach den dämonischen Blutfluch, sodass die Orcs in Kalimdor eine souveräne Nation aufbauen konnten.",["race:NightElf"]="Die Verteidigung Nordrassils kostete die Kaldorei ihre Unsterblichkeit. Sie öffnete auch ihre uralte Heimat zum ersten Mal seit zehntausend Jahren für die übrige Welt.",["race:Undead"]="Die Verlassenen sind die Menschen Lordaerons, von der Seuche getötet und zum Dienst an der Geißel gezwungen. Sie befreiten sich und nahmen die Unterstadt in Besitz."},sec={{t="Die Seuche und der Prinz",b="Der Dritte Krieg begann mit einer Seuche im nördlichen Lordaeron. Verseuchtes Getreide aus Andorhal verbreitete eine Krankheit, die ihre Opfer tötete und als Ghule erhob, gebunden an den Willen des Lichkönigs. Prinz Arthas Menethil und Jaina Prachtmeer, eine Zauberin der Kirin Tor, versuchten, sie aufzuhalten.\n\nSchreckenslords lenkten Arthas' Trauer und Angst auf Stratholme. Er säuberte die Stadt von ihren infizierten Bewohnern und verfolgte dann seinen Feind nach Nordend. Dort ergriff Arthas die verfluchte Runenklinge Frostgram und gab seine Seele auf. Er kehrte nach Süden zurück und ermordete seinen Vater, König Terenas. Lordaeron fiel daraufhin in die Hände der Geißel."},{t="Die Invasion der Legion",b="Arthas setzte die Toten ein, um Quel'Thalas zu zerschmettern und den Nekromanten Kel'Thuzad am Sonnenbrunnen wiederzuerwecken. Die Geißel belagerte daraufhin Dalaran und erbeutete die Zauberbücher, die benötigt wurden, um den Dämonenfürsten Archimonde nach Azeroth zu beschwören. Als Archimonde sterblichen Boden betreten hatte, wurde Dalaran durch arkane Verwüstung dem Erdboden gleichgemacht. Die Geißel hatte als Vorhut der Legion gedient. Nun wandte sich die Brennende Legion der ewigen Macht jenseits des großen Meeres zu."},{t="Die Flucht gen Westen und der Hyjal",b="Der geheimnisvolle Prophet sandte rätselhafte Warnungen an Kriegshäuptling Thrall und Lady Jaina Prachtmeer. Thrall führte die New Horde über das große Meer, während Jaina überlebende Flüchtlinge der Allianz in Sicherheit brachte. Im uralten Kalimdor gerieten die Neuankömmlinge mit den zurückgezogen lebenden Nachtelfen aneinander.\n\nDann erkannten die drei Fraktionen die Bedrohung, der sie gegenüberstanden. Auf dem Gipfel des Hyjal vereinten die Sterblichen ihre Kräfte unter dem Weltbaum Nordrassil. Als Archimonde den Baum erreichte, vernichteten ihn die Irrwische der Ahnen. Die Vorhut der Legion war zerschlagen, und der Krieg endete."},{t="Eine gezeichnete Welt",b="Archimondes Fall brachte keinen dauerhaften Frieden. Die Allianz von Lordaeron besteht nicht mehr. Sturmwind und Eisenschmiede bilden nun die Stützen der südlichen Allianz, während das alte Königreich als Pestländer vor sich hin modert. In Kalimdor hat sich Thralls Horde Durotar erkämpft, doch die Spannungen mit den neuerdings verbündeten Nachtelfen bleiben explosiv.\n\nDie Geißel hält weiterhin die nördlichen Ruinen. Die befreiten Untoten, die Verlassenen genannt werden, beherrschen die Katakomben der Hauptstadt. Sie kämpfen gegen ihre früheren Herren und rachsüchtige Kreuzfahrer um ihr Überleben."}},faq={{q="Wann fand der Dritte Krieg statt?",a="Der Dritte Krieg begann mit dem Ausbruch der Seuche des Untods in Lordaeron und endete mit der Schlacht am Hyjal. Die Verwüstung liegt erst vier Jahre zurück, daher sind die Ruinen noch frisch und fast jeder lebende Erwachsene hat im Krieg gekämpft oder Angehörige verloren.",al={"wann war der dritte krieg","wie lange ist der krieg her","daten des dritten krieges"}},{q="Wie unterschied sich der Dritte Krieg vom Ersten und Zweiten Krieg?",a="Der Erste und der Zweite Krieg waren hauptsächlich Kämpfe zwischen der Old Horde und den Königreichen der Allianz. Der Dritte Krieg brachte eine dämonische Invasion, die ganze Nationen zerschmetterte. Sterbliche kämpften auf drei Kontinenten gegen die Brennende Legion und ihre untote Geißel, was Feinde zu einem verzweifelten Waffenstillstand zwang.",al={"unterschied zwischen drittem und zweitem krieg","warum war der dritte krieg anders","horde gegen allianz im dritten krieg"}},{q="Was geschah mit dem Königreich Lordaeron?",a="Lordaeron wurde von innen heraus zerstört. Der Kult der Verdammten verseuchte das Getreide der Region mit der Seuche des Untods, die Menschen tötete und als Monster wiedererweckte. Prinz Arthas verfiel der Verderbnis, ermordete seinen Vater, König Terenas den Zweiten, und lieferte das zerschlagene Königreich der Geißel aus.",al={"schicksal von lordaeron","warum ist lordaeron zerstört","was geschah mit terenas"}},{q="Wer war der Prophet, der alle warnte, nach Kalimdor zu gehen?",a="Der Prophet war Medivh, der Last Guardian of Tirisfal. Er suchte Sühne dafür, dass er das Dunkle Portal geöffnet hatte, und reiste als Wanderer in einem Rabenmantel umher. Er warnte, dass Lordaeron dem Untergang geweiht sei, und drängte seine Anführer, sich in Kalimdor zu vereinen.",al={"wer war der prophet","rabenprophet","medivh im dritten krieg"}},{q="Warum gehören die Nachtelfen jetzt zur Allianz?",a="Die Nachtelfen hatten zehntausend Jahre lang in strenger Abgeschiedenheit gelebt. Der Dritte Krieg brachte die Legion zurück in ihre heiligen Wälder und zwang sie, ihre Unsterblichkeit zu opfern, um Archimonde am Weltbaum zu töten. In einer veränderten Welt, mit zunehmenden Rohstoffkonflikten zwischen ihnen und Thralls Horde und der noch immer gegenwärtigen Verderbnis der Geißel, verließen sie ihre Abgeschiedenheit und verbündeten sich mit den Völkern der Östlichen Königreiche.",al={"warum traten die nachtelfen der allianz bei","nachtelfen im dritten krieg","beitritt der kaldorei zur allianz"}},{q="Wie entkam die Horde dem Krieg in Lordaeron?",a="Kriegshäuptling Thrall vertraute Medivhs prophetischen Träumen. Er sammelte die befreiten Clans aus den Internierungslagern, überfiel menschliche Häfen, um Segelschiffe zu erbeuten, und überquerte das große Meer, bevor die Geißel oder die Legion Lordaeron vollständig verschlungen hatten.",al={"wie verließ thrall lordaeron","orcs segeln nach westen","flucht der horde nach kalimdor"}}},fx={["4a458aae"]={q="Warum wird er Dritter Krieg genannt?",a="Er wird Dritter Krieg genannt, weil er auf den Ersten und Zweiten Krieg folgte, die zwischen der ursprünglichen orcischen Horde und der Großen Allianz von Lordaeron ausgefochten wurden. Da diese Invasion beispiellose weltweite Verwüstungen und Dämonenarmeen mit sich brachte, ist er auch als Dritter Großer Krieg, Chaoskrieg und Reign of Chaos bekannt.",al={"dritter krieg namensursprung","warum dritter krieg","reign of chaos name"}},b67a3dac={q="Was war der Dritte Krieg?",a="Der Dritte Krieg war ein katastrophaler globaler Konflikt, bei dem die dämonische Brennende Legion ihre zweite Invasion von Azeroth startete, unterstützt von der untoten Geißel. Beginnend mit der Seuche des Untodes im nördlichen Lordaeron und dem Verrat von Prinz Arthas Menethil, breitete sich der Krieg schnell über die Östlichen Königreiche bis nach Kalimdor aus. Im Gegensatz zu früheren Konflikten zwischen nur Orks und Menschen, verschlang er fast jedes bedeutende Volk auf Azeroth, bevor er in einem verzweifelten, vereinten Standpunkt auf dem Hyjal gipfelte.",al={"was ist der dritte krieg","zusammenfassung dritter krieg","erkläre den dritten krieg"}}},fp="9,234,25.585.0,26.419.0,31.524.0,15.492.0,30.238.0,63.284.0,42.279.0,59.222.0,49.409.0,46.223.0"}
P.entries["topic:titan"] = {n="Titanisch",s="Durch die Große Dunkelheit reisen die Titanen von Welt zu Welt und suchen Orte, die sie formen und ordnen können. Vor langer Zeit kamen sie nach Azeroth, besiegten die Alten Götter, errichteten gewaltige Werke und bereiteten die Welt auf das Leben vor, ehe sie zu den Sternen aufbrachen.",h="Durch die Große Dunkelheit reisen die Titanen von Welt zu Welt und suchen Orte, die sie formen und ordnen...",kw={"aman'thul","earthen","eonar","khaz'goroth","makers","norgannon","ordnung","pantheon","titan"},ang={["class:Mage"]="Als Magier wirkt Ihr arkane Magie, die grundlegende Lebenskraft der Titanen. Ihre geordneten Prinzipien gehen auf Verzauberungen zurück, die das Pantheon über die Welt wob.",["profession:Mining"]="Als Bergarbeiter grabt Ihr tief in der Erde und könnt unversehrtes titanengeschmiedetes Metall und Fundamente entdecken, die älter sind als die Geschichtsschreibung.",["race:Dwarf"]="Als Zwerg verehrt Ihr die Titanen als die göttlichen Makers. Die Explorers' League und König Magni Bronzebart suchen in titanischen Relikten nach Euren Ursprüngen.",["race:Gnome"]="Als Gnom teilt Ihr ein mechanisches Erbe, das auf titanische Schöpfungen zurückgeht. Dieses Erbe begründet Eure Vorliebe für Uhrwerkkonstruktionen und Ausgrabungen."},sec={{t="Architekten des Kosmos",b="Gewaltig sind die Titanen, kosmische Riesen aus ursprünglicher Materie und arkaner Magie. Sie tragen die Kräfte der Ordnung und Schöpfung in sich und suchen schlummernde Welten, um sie zu kultivieren. Dort heben sie Kontinente empor, besänftigen die Elemente und formen Leben. Konstrukte aus Stein, Eisen und Meer bewachen ihre Werke und wahren das Gleichgewicht, das sie anstrebten."},{t="Die Ordnung Azeroths",b="Als das Pantheon vor langer Zeit Azeroth fand, hielten chaotische Elementarlords und die schrecklichen Alten Götter die Welt in ihrem Griff. Die Titanen verbannten die Elementare in Taschendimensionen und versiegelten die Alten Götter unter der Erde. Sie formten große Biome und errichteten Gewölbe wie Uldaman. Dann vertrauten sie fünf großen Drachen, den Drachenaspekten, das Land, die Magie, die Zeit und das Leben an und brachen wieder zu den Sternen auf."},{t="Der gefallene Streiter",b="Sargeras stand einst als größter Krieger und Verteidiger unter den Titanen. Doch die tiefe kosmische Dunkelheit und die dämonische Bosheit, die er bekämpfte, erfüllten ihn mit Furcht und Verzweiflung. Er verwarf das Werk seinesgleichen und verschrieb sich dem Nihilismus. Um die gesamte Schöpfung auszulöschen, statt sie der Verderbnis anheimfallen zu lassen, gründete er die Brennende Legion."}},faq={{q="Leben die Titanen noch und sind sie auf Azeroth?",a="Die Titanen verließen Azeroth vor langer Zeit in Richtung der Großen Dunkelheit, nachdem sie die Alten Götter besiegt und die Welt geordnet hatten. Sie hinterließen Wächter, Konstrukte aus Stein und Eisen sowie verborgene Gewölbe unter der Erde, um über ihr Werk zu wachen.",al={"wo sind die titanen","sind titanen auf azeroth","aufenthaltsorte der titanen"}},{q="Warum sind den Zwergen die Titanen so wichtig?",a="Zwerge stammen von den earthen ab, unterirdischen Steinwesen, die die Titanen schufen, um die Fundamente der Welt herauszuarbeiten. Durch Archäologie und Ausgrabungen in Ruinen wie Bael Modan und Uldaman suchen Zwerge nach ihrer vergessenen Abstammung.",al={"verbindung zwischen zwergen und titanen","warum zwerge graben","zwerge und die schöpfer"}},{q="Was ist das Pantheon?",a="Das Pantheon ist der herrschende Rat der Titanen, angeführt von Highfather Aman'Thul. Zu seinen Mitgliedern zählen Khaz'goroth, der Weltenformer, Eonar, die Lebensbinderin, Norgannon, der Hüter himmlischer Magie, Golganneth, der Herr der Himmel, und Aggramar, der Sargeras als Streiter ablöste.",al={"pantheon der titanen","wer führt die titanen","anführer der titanen"}},{q="Haben die Titanen die Drachenaspekte erschaffen?",a="Ja. Bevor das Pantheon Azeroth verließ, leitete es seine Macht durch die Hüter, um fünf Protodrachen zu segnen. Alexstrasza, Ysera, Malygos, Nozdormu und Neltharion erhielten ungeheure Macht, um das Leben, die Natur, die Magie, die Zeit und die Erde zu beschützen.",al={"titanen und drachen","ursprünge der aspekte","wer erschuf die aspekte"}},{q="Ist Sargeras ein Titan?",a="Sargeras war einst der Streiter des Pantheons und verteidigte den Kosmos gegen Chaos und Dämonen. Die Dunkelheit, die er erlebte, trieb ihn in Verzweiflung und Wahnsinn. Er brach mit seinen Brüdern, um die Brennende Legion zu gründen und das geordnete Universum niederzubrennen.",al={"wer ist sargeras","ist sargeras ein gott","sargeras' ursprung"}},{q="Ist ein Titan in Silithus gefallen?",a="Qiraji Prophet Skeram hielt Prophezeiungen fest, denen zufolge ein Titan in den südlichen Wüsten von Silithus gegen ein uraltes Übel kämpfte und fiel. Gelehrte und Entdecker streiten noch immer darüber, ob das gefallene Wesen ein wahrer Titan oder eines ihrer Konstrukte war.",al={"titan in silithus","prophezeiung über c'thun und einen titanen","hat c'thun einen titanen getötet"}}},fx={f6eb9ea0={q="Was sind die Titanen?",a="Die Titanen sind kolossale, gottgleiche Wesen des Kosmos, die höchsten Vorkämpfer für Ordnung und Schöpfung. Sie durchwandern das Große Dunkle Jenseits, bringen Struktur in formlose Welten und fördern das Leben, wo immer sie auch hinreisen.",al={"wer sind die titanen","was ist ein titan","titanen-lore"}},["23c22d21"]={q="Woher kamen die Titanen?",a="Kein Sterblicher weiß, woher die Titanen kamen. Sie sind uralte Wesen des Großen Dunklen Jenseits, die den Kosmos durchreisen, um neugeborenen Welten Ordnung zu bringen, so wie sie es taten, als sie nach Azeroth kamen, die Alten Götter besiegten und das Land formten.",al={"titanen-herkunft","ursprung der titanen","wie wurden titanen erschaffen"}},["91d84aea"]={q="Wer führt die Titanen an?",a="Die Titanen werden vom Allvater Aman'Thul angeführt, dem Ältesten unter ihnen und dem Oberhaupt ihres regierenden Rates, dem Pantheon. Mit der Macht über Zeit und Kosmos ausgestattet, leitet Aman'Thul ihre Mission durch das Große Dunkle Jenseits, um Welten zu ordnen.",al={"wer ist der titanen-anführer","anführer der titanen","anführer des pantheons"}}},fp="5,244,24.304.0,23.408.0,19.320.0,42.206.0,49.232.0,21.277.0,41.237.0,20.239.0,29.238.0"}
P.entries["topic:trogg"] = {n="Trogg",s="Aus den Tiefen der Erde haben sich Troggs ihren Weg an die Oberfläche gebahnt. Zwergische Ausgrabungen störten ihre uralten Gewölbe, und nun überrennen sie Steinbrüche und halten Gnomeregan besetzt, nachdem sie dessen Gnome vertrieben haben.",h="Aus den Tiefen der Erde haben sich Troggs ihren Weg an die Oberfläche gebahnt.",kw={"caverndeep","irdene","gnomeregan","grubbis","flintauge","rockjaw","stonesplinter","trogg","uldaman"},ang={["faction:Alliance"]="Die Verteidigung von Dun Morogh, Loch Modan und Gnomeregan gegen Troggplagen hilft, das Bergkönigreich und seine Flüchtlinge zu schützen.",["profession:Mining"]="Troggs besetzen oft reiche Erzadern und tiefe Minen wie Gol'Bolar. Bergleute müssen ihre Schürfrechte mit Spitzhacken und Hämmern verteidigen.",["race:Dwarf"]="Euer Volk grub diese wilden Verwandten aus, als es nach seinen titanischen Ursprüngen suchte. Ihre Einfälle in ganz Khaz Modan waren eine Folge zwergischer Archäologie.",["race:Gnome"]="Troggs sind eine bittere Geißel Eures Volkes. Sie zerstörten Eure unterirdische Heimat und zerstreuten die Überlebenden nach Tüftlerstadt in Eisenschmiede."},sec={{t="Die misslungenen Vorläufer",b="Die ersten steinernen Diener waren ein misslungener Entwurf. Lange bevor sterbliche Völker Aufzeichnungen führten, versuchten titanengeschmiedete Hüter, Diener aus Stein zu formen. Sie erschufen grobschlächtige Wesen mit steinerner Haut, wenig Verstand und wildem Temperament. Die Hüter verfeinerten ihren Entwurf zu den Irdenen, den Vorfahren der Zwerge. Die Riesin Ironaya verschonte die misslungenen Troggs und versiegelte sie tief in Uldaman, in der Hoffnung, sie würden endlos schlafen."},{t="Von der Spitzhacke geweckt",b="Zwergische Ausgrabungen weckten die Troggs nach unzähligen Jahrtausenden. Die Forscherliga von Eisenschmiede drang in uralte unterirdische Anlagen in Khaz Modan ein, und wütende Schwärme strömten heraus, um ihre entfernten zwergischen Verwandten zu jagen. Die helle Oberflächenwelt trieb sie dazu, Tunnel unter Dun Morogh, Loch Modan und dem Ödland zu graben. Von unten überfielen sie Steinbrüche, archäologische Ausgrabungsstätten und Handelsposten."},{t="Die Katastrophe von Gnomeregan",b="Troggs folgten unterirdischen Erschütterungen und Geräuschen nach Gnomeregan. An Zahl und Stärke unterlegen, bekämpften die Gnome sie in den Korridoren der Stadt. Robogenieur Thermaplugg ersann einen verzweifelten Plan. Großtüftler Gelbin Mekkadrill setzte radioaktives Gas frei, um die Eindringlinge zu töten, doch es tötete rund achtzig Prozent des gnomischen Volkes und erzürnte die Troggs nur. Die große Stadt blieb verstrahlt und unter der Kontrolle der Troggs zurück."}},faq={{q="Was genau sind Troggs?",a="Troggs sind unterirdische Humanoide, die ersten misslungenen steinernen Diener der titanengeschmiedeten Hüter. Die Hüter versiegelten sie in Stasisgewölben wie Uldaman, statt sie zu vernichten. Zwergische Bergleute gruben sie später aus.",al={"ursprung der troggs","was ist ein trogg","geschichte der troggs"}},{q="Sind Troggs mit Zwergen verwandt?",a="Ja. Die Hüter der Titanen formten beide Völker. Troggs waren ihr erster, grober Entwurf, während die Irdenen, die Vorfahren der Zwerge, der verfeinerte Entwurf waren.",al={"sind zwerge und troggs verwandt","verbindung zwischen troggs und zwergen"}},{q="Wie eroberten die Troggs Gnomeregan?",a="Troggs folgten den Erschütterungen schwerer Maschinen und gruben sich hinauf nach Gnomeregan. Ihre Überzahl überwältigte die Gnome trotz ihrer Erfindungen zur Verteidigung. Radioaktives Gas, das die Eindringlinge vertreiben sollte, tötete die meisten Gnome und ließ die Stadt in den Händen der Troggs zurück.",al={"warum sind troggs in gnomeregan","troggangriff auf gnomeregan"}},{q="Können Troggs sprechen oder eine entwickelte Kultur hervorbringen?",a="Troggs besitzen wenig Verstand und verständigen sich meist durch Grunzen und Brüllen. Sie schätzen rohe Kraft und bestimmen ihre Stammeshäuptlinge durch Gewalt. Manche zeigen einfache schamanistische Magie, doch ihre Handwerkskunst bleibt grob, von Keulen und Steinpfeilen bis hin zu gestohlenen Relikten.",al={"können troggs sprechen","kultur der troggs","intelligenz der troggs"}},{q="Warum sammeln Troggs uralte Relikte?",a="Forscher glauben, dass Troggs uralte Titanenrelikte horten, weil ein Instinkt aus ihrer Entstehungszeit in ihnen fortlebt. Troggs verstehen diese Gegenstände nur selten und nutzen unbezahlbare Artefakte als Keulen oder einfache Glücksbringer.",al={"warum horten troggs artefakte","troggschätze"}},{q="Gibt es Troggs außerhalb von Khaz Modan?",a="Ja. Troggclans leben überall in Azeroth unter der Erde, darunter die Ragefire-Troggs tief im Flammenschlund unter Orgrimmar, die Gravelflint-Troggs an der Dunkelküste und Gruppen im Ödland und in Alterac.",al={"aufenthaltsorte der troggs","troggs in durotar","troggs in kalimdor"}}},fx={["0f8118fe"]={q="Warum sind Troggs anderen Völkern gegenüber so feindselig?",a="Troggs werden fast vollständig von rohem Instinkt, Hinterlist und schierer Aggression angetrieben. Nachdem sie aus ihrem uralten Schlummer tief unter der Erde gestört wurden, war ihr unmittelbarer Impuls, ihre Wut an den Oberflächenbewohnern auszulassen, insbesondere an ihren dwarven Vettern, die in ihre Gewölbe eingebrochen waren. Da sie einfältig und territorial sind, betrachten sie andere Lebewesen entweder als Bedrohungen, die vernichtet werden müssen, oder als Mahlzeiten, die verspeist werden sollen, und greifen bereitwillig ohne Provokation zu Gewalt und sogar Kannibalismus.",al={"warum greifen troggs an","sind troggs aggressiv","warum hassen troggs zwerge"}},["9c157b85"]={q="Wer führt die Troggs an?",a="Troggs haben keinen vereinigten Herrscher oder eine zentrale Zivilisation. Stattdessen organisieren sie sich in verstreuten Stämmen und Clans, wie den Rockjaw-, Stonesplinter- und Stonevault-Troggs. Innerhalb jedes Stammes liegt die Führung allein bei dem stärksten, größten und bösartigsten Tier, das seine Herrschaft durch Einschüchterung und Blutvergießen durchsetzen kann, wie etwa Grimlok innerhalb von Uldaman.",al={"trogg-anführer","trogg-häuptling","trogg-könig"}},["21373546"]={q="Haben Troggs irgendwelche Verbündete?",a="Fast universell kämpfen Troggs allein. Ihre Wildheit, ihre kannibalischen Tendenzen und ihre Feindseligkeit gegenüber anderen Rassen machen Diplomatie unmöglich, und sie verachten Außenstehende. Eine seltene Ausnahme bildet der Stonesplinter-Clan, der lockere Verbindungen zu den Kobolden der Tunnel Rats geknüpft hat, aber echte Bündnisse über ihre eigene Art hinaus sind praktisch nicht existent.",al={"trogg-verbündete","wer arbeitet mit troggs","trogg-fraktionen"}},["638bdf0a"]={q="Woher kamen die Troggs?",a="Troggs waren die erste Generation von titanengeschmiedeten Wesen, die von den titanischen Wächtern erschaffen wurden. Der Entwurf erwies sich als fehlerhaft und zu komplex, wodurch steinhäutige, brutale Kreaturen ohne höheren Intellekt entstanden. Über das Ergebnis bekümmert, verfeinerten die Wächter ihre nachfolgenden Bemühungen zu den Irdenen und versiegelten die defekten Troggs in Stasisgewölben wie Uldaman. Über Jahrtausende schliefen sie unter Azeroth, bis dwarven Bergleute unwissentlich ihre Gräber ausgruben.",al={"herkunft der troggs","trogg-geschichte","wie wurden troggs erschaffen"}}},fp="5,206,23.418.0,23.401.0,29.421.1,24.221.0,30.151.0,34.263.0,49.260.0,37.199.0,39.198.0"}
P.entries["topic:troll"] = {n="Troll",s="Über ganz Azeroth sind die Trollreiche zersplittert, während die Dunkelspeer heute in Thralls Horde leben. Trolle zählen zu den ältesten Völkern der Welt und entstanden vor der Zerschlagung nahe dem Brunnen der Ewigkeit. Sie heilen rasch und ehren durch Voodoo Urgeister, die sie Loa nennen.",h="Über ganz Azeroth sind die Trollreiche zersplittert, während die Dunkelspeer heute in Thralls Horde leben.",kw={"amani","aqir","dunkelspeer","gurubashi","loa","regeneration","troll","trolle","voodoo","zandalari"},ang={["class:Priest"]="Trollpriester sind den Loa und der Schattenjagd verbunden. Sie treten mit Tiergeistern und urtümlichen dunklen Mächten in Verbindung statt mit dem Heiligen Licht.",["faction:Horde"]="Die Dunkelspeertrolle bringen als Späher, Schattenjäger und Schamanen List, Gewandtheit und spirituelle Stärke unter das Banner des Kriegshäuptlings.",["race:NightElf"]="Die Geschichte der Elfen und uralte Mythen führen erbitterte Rivalitäten auf Trollkönigreiche zurück. Elfen betrachten das Voodoo und die Opferriten der Trolle mit tiefem Misstrauen.",["race:Troll"]="Euer Erbe reicht weiter zurück als das fast jeder anderen Zivilisation auf Azeroth. Während Eure Vettern in Zul'Gurub und Zul'Aman an erbittertem, abschottendem Stolz festhalten, tragen die Dunkelspeer ihr Erbe durch die Stärke der Horde weiter."},sec={{t="Kinder der Wildnis",b="Trolle entstanden nahe dem Brunnen der Ewigkeit, lange bevor die Große Zerschlagung das uralte Kalimdor zerbrach. Sie lebten als flinke, wendige Jäger und Sammler, und ihre Körper heilten schwere Wunden mit erstaunlicher Geschwindigkeit. Mit genügend Zeit konnten ihnen sogar abgetrennte Gliedmaßen nachwachsen. Rund um die heiligen Berge von Zandalar wandten sie sich Urgeistern zu, die sie Loa nannten. Schattenjäger und Hexendoktoren leiteten diese Riten, aus denen Voodoo entstand."},{t="Krieg gegen die Aqir",b="In uralten Zeiten führten Trollreiche einen langen Krieg gegen die insektoiden Aqir, deren Schwärme den Kontinent zu überrennen drohten. Die Amani und Gurubashi führten den Kampf an und trieben die Aqir in die entlegensten Winkel des Landes. Einige flohen nach Norden in das spätere Azjol-Nerub. Andere zogen nach Süden in die Wüsten, wo Ahn'Qiraj entstehen sollte."},{t="Ein zersplittertes Erbe",b="Als die Aqir zerschlagen und eingedämmt waren, verloren die Trolle ihr gemeinsames Ziel. Ihre großen Fraktionen zogen sich in getrennte Reiche zurück und entwickelten eigene Kulturen, körperliche Merkmale und Stammesordnungen für Wälder, Dschungel und gefrorene Einöden. Jahrtausende der Trennung und Rivalität folgten, begleitet von Gebietskriegen gegen jüngere Völker.\n\nDiese Kämpfe schwächten die Vorherrschaft der Trolle. Die meisten verbliebenen Trollkönigreiche begegnen anderen Völkern heute mit erbitterter Feindseligkeit und klammern sich an die Ruinen ihrer einstigen Größe. Die Dunkelspeer, ins Exil getriebene Dschungeltrolle, wählten einen anderen Weg und schlossen sich mit Orcs und Tauren der Horde an."}},faq={{q="Können Trollen wirklich verlorene Gliedmaßen nachwachsen?",a="Ja. Trolle heilen körperliche Wunden schneller als die meisten anderen sterblichen Völker. Mit genügend Zeit können ihnen verlorene Finger und sogar ganze Gliedmaßen nachwachsen.",al={"heilung der trolle","nachwachsende trollgliedmaßen","wie heilen trolle"}},{q="Was sind Loa?",a="Loa sind urtümliche Gottheiten, die von fast allen Trollstämmen verehrt werden. Viele nehmen die Gestalt mächtiger Tiergeister an, die mit Opfergaben, Meditation und ritueller Magie geehrt werden. Priester und Schattenjäger rufen sie um Segen, Führung und Stärke im Kampf an.",al={"wer sind die loa","trollgötter","was verehren trolle"}},{q="Warum sind die meisten Trolle Spielern gegenüber feindselig?",a="Viele Trollstämme, darunter die Waldtrolle der Amani und die Dschungeltrolle der Gurubashi, pflegen abgeschottete Traditionen und tiefe Feindseligkeit gegenüber Außenstehenden. Lange Konflikte mit vordringenden Völkern haben sie zu erbitterten Verteidigern ihrer angestammten Gebiete gemacht, und sie greifen Eindringlinge sofort an.",al={"warum sind trolle böse","feindselige trolle","böse trolle"}},{q="Wie schlossen sich die Dunkelspeer der Horde an?",a="Die Dschungeltrolle der Dunkelspeer wurden aus ihren angestammten Gebieten vertrieben und saßen auf einer Insel fest, angegriffen von Murlocs und Meerhexen. Kriegshäuptling Thrall und seine Orcflotte retteten sie vor der Vernichtung. Aus Dankbarkeit und gemeinsamer Not verpflichtete ihr Häuptling den Stamm zur Treue gegenüber der neu gegründeten Horde.",al={"warum gehören trolle zur horde","beitritt der dunkelspeer zur horde","thrall und trolle"}},{q="Was ist Voodoo?",a="Voodoo ist eine uralte Praxis spiritueller und dunkler Magie, die Hexendoktoren, Schattenjäger und Priester der Trolle anwenden. Sie verbindet den Austausch mit Ahnen und die Verehrung der Loa mit Flüchen, Verwünschungen und wirksamen Kräutergebräuen, um Feinden zu schaden und Verbündete zu stärken.",al={"trollvoodoo","wie funktioniert voodoo","magie der hexendoktoren"}},{q="Welche Klassen können Trolle spielen?",a="Trolle lassen sich zu Kriegern, Jägern, Schurken, Priestern, Schamanen, Magiern und Hexenmeistern ausbilden.",al={"trollklassen","welche klassen können trolle spielen","können trolle hexenmeister sein"}}},fp="5,266,21.429.0,20.319.0,18.600.0,40.133.0,13.263.0,39.277.0,37.303.0,15.245.0,28.80.0"}
P.entries["topic:twilight-s-hammer"] = {n="Schattenhammer",s="In Kalimdor und den Östlichen Königreichen arbeitet der Schattenhammer heimlich am Ende Azeroths. Sein Glaubenssatz fordert das Erwachen der Alten Götter und das Ende aller Dinge.",h="In Kalimdor und den Östlichen Königreichen arbeitet der Schattenhammer heimlich am Ende Azeroths.",kw={"aku'mai","tiefschwarze grotte","cho'gall","kelris","die meistergleve","alte götter","silithus","schattenhammer","void"},ang={["class:Priest"]="Als Priester schöpft Ihr aus demselben Void und derselben Shadow Magic, die der Schattenhammer manipuliert. Der Kult zeigt, was geschehen kann, wenn die Zwiesprache mit dem Flüstern den Verstand Sterblicher überwältigt.",["class:Warlock"]="Als Hexenmeister teilt Ihr die einstigen Verbindungen des Kults zu Gul'dans Schattenrat. Der Schattenhammer gab die Beherrschung dämonischer Teufelsmagie für den urzeitlichen Wahnsinn der Alten Götter auf, wodurch seine Anhänger zu unberechenbaren Rivalen statt Verbündeten wurden.",["faction:Horde"]="Als Mitglied der Horde erbt Ihr ein schändliches Relikt aus den dunkelsten Tagen der Alten Horde. Thralls neue Horde lehnt den Wahnsinn des Kults ab und richtet Eiferer hin, die junge Orcs wieder in den Nihilismus ziehen wollen.",["race:NightElf"]="Als Nachtelf seht Ihr, wie fremde Kultisten heilige Stätten im nördlichen Kalimdor entweihen, darunter die Tiefschwarze Grotte und die Meistergleve. Ihre Gegenwart greift diese Lande an Leib und Seele an."},sec={{t="Ursprünge im Schatten",b="Auf Draenor begann der Schattenhammer als Orcclan der Alten Horde. Der zweiköpfige Ogermagier Cho'gall führte den Clan und diente als einer von Gul'dans obersten Leutnants im Schattenrat. Unter Cho'gall verschrieben sich seine Mitglieder einem düsteren Glauben, der auf das Ende aller Dinge ausgerichtet war. Sie sahen die Horde schließlich als eine Kraft der Zerstörung, die diesem Zweck diente."},{t="Ankunft auf Azeroth",b="Der Schattenhammer durchschritt während des Ersten Krieges das Dunkle Portal, und sein apokalyptischer Eifer vertiefte sich auf Azeroth. Seine Kultisten hörten das wahrhaftige Flüstern der Alten Götter, uralter Schrecken, die unter der Erde angekettet waren. Schwarzfaust duldete ihre unberechenbaren Rituale, weil Cho'gall ihren Blutrausch zügelte. Er schickte sie mit Kilrogg Totauges Clan des Blutenden Auges zu frühen Angriffen auf Burg Sturmwind.\n\nWährend des Zweiten Krieges arbeitete der Clan tief im Inneren von Grim Batol und beaufsichtigte entscheidende Raffinerien, bis Gul'dans Verrat die Horde spaltete. Orgrim Schicksalshammer befahl, den verräterischen Clan nahe dem Grabmal des Sargeras abzuschlachten. Ein Kern von Eiferern überlebte."},{t="Ein wucherndes Krebsgeschwür",b="An Kalimdors vergessenen Küsten wurde der Schattenhammer aus einem zerschlagenen Orcclan zu einer geheimen, vielvölkrigen Verschwörung. Er zieht desillusionierte Mitglieder der Allianz wie der Horde an und rekrutiert jede Seele, die zerbrochen genug ist, um das Vergessen willkommen zu heißen. Im nördlichen Kalimdor führt Zwielichtfürst Kelris Kultisten an, die sich in den versunkenen Hallen der Tiefschwarzen Grotte verschanzt haben. Dort verfüttern sie Opfer an Aku'mai, einen monströsen Diener eines Alten Gottes.\n\nWeiter nördlich an der Dunkelküste stören ihre Ausgräber die gewaltigen versteinerten Überreste bei der Meistergleve. In den südlichen Wüsten von Silithus kümmern sich Fanatiker in Roben um Tiefenwindsteine und lauschen auf uralte Schrecken, die sich unter dem Sand regen."}},faq={{q="Was will der Schattenhammer erreichen?",a="Sie wollen allem Leben und aller Ordnung auf Azeroth ein Ende setzen. Der Kult nennt das Vergessen einen heiligen Segen, keinen Weg zu Eroberung oder Reichtum. Er arbeitet daran, die uralten Alten Götter zu befreien, die unter der Welt angekettet sind.",al={"was wollen kultisten","schattenhammer ziel","schattenhammer zweck"}},{q="Sind sie ein Orcclan oder ein Kult?",a="Sie begannen auf Draenor als Orcclan unter Cho'galls Führung. Nach ihrer Flucht aus dem Zweiten Krieg ließen sie die Grenzen des Clans hinter sich und wurden zu einem geheimen, vielvölkrigen Kult. Sie rekrutieren Menschen, Nachtelfen, Zwerge und jeden, der bereit ist, den Void anzubeten.",al={"sind sie orcs","ist der schattenhammer ein clan","schattenhammer völker"}},{q="Wer führt den Schattenhammer an?",a="Cho'gall gründete und beaufsichtigte den Kult. Er ist ein gerissener, zweiköpfiger Ogermagier und ehemaliger Schüler Gul'dans. Regionale Befehlshaber führen örtliche Gruppen an, darunter Zwielichtfürst Kelris in der Tiefschwarzen Grotte.",al={"wer ist der boss des schattenhammers","schattenhammer anführer","cho'gall"}},{q="Warum sind sie in der Tiefschwarzen Grotte?",a="Zwielichtfürst Kelris führt Kultisten an, die einen versunkenen Nachtelfentempel am Zoramstrand besetzen. Sie beten Aku'mai an und verfüttern Opfer an die urzeitliche dreiköpfige Hydra, einen Diener eines Alten Gottes.",al={"tiefschwarze grotte kultisten","kelris tiefschwarze grotte","was tun sie im eschental"}},{q="Was tun sie bei der Meistergleve an der Dunkelküste?",a="Die Meistergleve ist eine gewaltige Gleve, die im Schädel einer kolossalen Kreatur steckt. Onu, der Ancient of Lore, sagt, dort sei ein alter, uralter Herr der Erde gefallen. Kultisten versammeln sich, um mit verbliebenen dunklen Energien Zwiesprache zu halten und nach Zeichen für das Erwachen ihrer Meister zu suchen.",al={"meistergleve kultisten","dunkelküste schattenhammer"}},{q="Warum versuchte Orgrim Schicksalshammer, sie auszulöschen?",a="Während des Zweiten Krieges verließen Cho'gall und Gul'dan den Marsch der Horde auf Lordaeron, um am Grabmal des Sargeras nach Göttlichkeit zu streben. Ihr Verrat kostete die Horde den Sieg. Kriegshäuptling Schicksalshammer schickte loyale Truppen aus, um die abtrünnigen Clans abzuschlachten.",al={"schicksalshammer schattenhammer","zweiter krieg verrat"}}},fx={["4ab30bd1"]={q="Warum sind die Twilight's Hammer Außenstehenden gegenüber feindselig?",a="Die Twilight's Hammer dient den Alten Göttern und strebt die völlige Vernichtung Azeroths an. Sie betrachten alle Zivilisationen von außen – Allianz, Horde und Neutral gleichermaßen – als Hindernisse für ihren apokalyptischen großen Plan. Jeder, der sich nicht ihrer nihilistischen Sache verschrieben hat, ist ein Feind, der eliminiert oder in ihren dunklen Ritualen geopfert werden muss.",al={"warum ist twilight's hammer feindselig","twilight's hammer greift bei sicht an","warum greifen kultisten mich an"}},["23bd082e"]={q="Woher stammt der Clan Twilight's Hammer?",a="Sie begannen auf Draenor als Orc-Clan der Alten Horde, angeführt von dem zweiköpfigen Oger-Magier Cho'gall, einem der wichtigsten Leutnants von Gul'dan. Unter ihm nahm der Clan ein apokalyptisches Glaubensbekenntnis an und überquerte mit dem Rest der Horde das Dunkle Portal nach Azeroth.",al={"twilight's hammer ursprung","woher kam twilight's hammer","geschichte von twilight's hammer"}},["74c580c8"]={q="Warum heißt die Twilight's Hammer so?",a="Der Name stammt aus den Tagen des Clans in der Alten Horde unter Cho'gall. Sein Ursprung ist nicht aufgezeichnet, aber er passt zu einem Glaubensbekenntnis, das darauf ausgelegt ist, das Ende der Welt herbeizuführen.",al={"warum heißt es twilight's hammer","bedeutung des namens twilight's hammer","ursprung des namens twilight's hammer"}},["301a24e8"]={q="Für wen arbeitet der Schattenhammer?",a="Ihre wahren Meister sind die Alten Götter, uralte Wesen der Leere und der Schatten, die tief unter Azeroth eingekerkert sind. Der Kult arbeitet daran, diese Gefängnisse zu zertrümmern, und erweckt Wesenheiten wie C'Thun in Silithus. Sie verehren auch die Diener dieser dunklen Meister, wie etwa die Hydra Aku'mai in der Tiefschwarzen Grotte.",al={"wem dient der schattenhammer","meister des schattenhammers","mit wem ist der schattenhammer verbuendet"}}},fp="17,170,17.346.0,18.644.0,18.668.0,48.189.0,31.238.0,32.204.0,34.210.0,56.253.0,47.249.0"}
P.entries["topic:varian-wrynn"] = {n="Varian Wrynn",s="Auf dem großen Meer ist Varian Wrynn während der Überfahrt nach Theramore verschwunden. Sein zehnjähriger Sohn Anduin trägt Sturmwinds Krone unter der Führung von Hochlord Bolvar Fordragon und Lady Katrana Prestor.",h="Auf dem großen Meer ist Varian Wrynn während der Überfahrt nach Theramore verschwunden.",kw={"anduin","könig","vermisst","steinmetze","sturmwind","theramore","varian","wrynn"},ang={["class:Warrior"]="Als Krieger wisst Ihr, dass König Varian mit erfahrenen Rittern trainierte und die Schrecken des Ersten Krieges durchstand. In der gesamten Allianz wird er als mächtiger Krieger und entschlossener Heerführer bewundert.",["faction:Alliance"]="Als Mitglied der Allianz steht Ihr durch Varians Abwesenheit vor einem politischen Machtvakuum. Seine Abwesenheit ermutigt Aufrührer und bedroht die Sicherheit der Grenzen von Westfall bis zum Rotkammgebirge.",["race:Human"]="Als Mensch aus Sturmwind erinnert Ihr Euch an Varian als König Llanes geliebten Sohn, der aus dem Exil zurückkehrte, um Eure Heimat wiederaufzubauen. Sein plötzliches Verschwinden erfüllt das Reich mit Furcht."},sec={{t="Eine Kindheit in Asche",b="Varians Kindheit endete, als der Erste Krieg sein Leben erschütterte. Er sah mit an, wie die Attentäterin Garona Halforcen König Llane Wrynn tötete, während die Alte Horde die Hauptstadt stürmte. Anduin Lothar rettete den verwaisten Prinzen und floh mit den Überlebenden des Königreichs nach Norden nach Süderstade.\n\nIn Capital City nahm König Terenas Menethil II. Varian wie einen zweiten Sohn auf. Der junge Prinz wuchs an der Seite von Prinz Arthas Menethil im Exil auf und trug die Erinnerung an seine niedergebrannte Heimat in sich. Dann bezwang die Allianz von Lordaeron die Horde und eroberte Sturmwind zurück."},{t="Ein schwieriger Wiederaufbau",b="Mit achtzehn Jahren bestieg Varian den Thron und stellte sich der gewaltigen Aufgabe, sein zerstörtes Königreich wiederaufzubauen. Er beauftragte Edwin van Cleef und die Stonemasons Guild damit, die Hauptstadt wiederherzustellen. Als das große Werk vollendet war, weigerte sich das korrupte House of Nobles, die versprochenen Löhne zu zahlen.\n\nDie Steinmetze wollten nicht nachgeben, und Varian konnte den Streit zwischen dem unnachgiebigen Adel und den wütenden Handwerkern nicht schlichten. Bald herrschte Gewalt auf Sturmwinds Straßen."},{t="Der verschwundene König",b="Varian segelte kürzlich von Sturmwind zur Insel Theramore, um an Friedensgesprächen teilzunehmen, die Lady Jaina Prachtmeer arrangiert hatte. Er wollte die Spannungen jenseits des Meeres lindern, erreichte das Gipfeltreffen jedoch nie. Während der Überfahrt verschwand der König spurlos.\n\nSturmwind bleibt verwundbar zurück. Am Hof verbreiten sich Gerüchte über eine Verschwörung, und Hochlord Bolvar führt die Regentschaft."}},faq={{q="Wo ist König Varian gerade?",a="Niemand in Sturmwind weiß, wo Varian ist. Er verschwand auf der Überfahrt über das große Meer nach Theramore, wo er geheime diplomatische Gespräche führen sollte.",al={"wo ist varian","wohin ist der könig gegangen","lebt varian","varians aufenthaltsort"}},{q="Wer regiert Sturmwind derzeit an seiner Stelle?",a="Anduin Wrynn, Varians zehnjähriger Sohn, sitzt als Kindkönig auf dem Thron. Hochlord Bolvar Fordragon übt als Regent die tatsächliche Verwaltungs- und Militärgewalt aus, stark beeinflusst von der königlichen Beraterin Lady Katrana Prestor.",al={"wer regiert sturmwind","wer ist jetzt könig","sturmwinds herrscher"}},{q="Was erschwerte Varians Wiederaufbau von Sturmwind?",a="Als die Stonemasons Guild den Wiederaufbau von Sturmwind vollendet hatte, weigerte sich das House of Nobles, die versprochenen Löhne zu zahlen. Ihr Streit entlud sich in gewaltsamen Unruhen auf den Straßen der Stadt, und die verbannten Steinmetze wurden später zur Bruderschaft der Defias.",al={"varian steinmetze","steinmetzunruhen varian","varian und die adligen"}},{q="Warum war Varian auf dem Weg nach Theramore?",a="Varian reiste auf Einladung von Lady Jaina Prachtmeer zu einem hochrangigen diplomatischen Gipfeltreffen auf der Insel Theramore. Die Gespräche sollten die Feindseligkeiten zwischen der Allianz und Thralls Horde eindämmen.",al={"warum ist varian aufgebrochen","gipfeltreffen in theramore","varian friedensgespräche"}},{q="Wie entkam Varian dem Ersten Krieg?",a="Nachdem König Llane ermordet worden war und die Horde Sturmwind niedergebrannt hatte, evakuierte Oberbefehlshaber Anduin Lothar Prinz Varian und die übrigen überlebenden Zivilisten über See. Sie segelten nach Norden nach Lordaeron, wo König Terenas Menethil II. den jungen Prinzen an seinem Hof aufnahm.",al={"varian erster krieg","junger varian","sturmwinds fall varian"}},{q="In welchem Verhältnis stand Varian zu Arthas Menethil?",a="Varian und Arthas Menethil wuchsen in Lordaeron als enge Gefährten und Rivalen auf, während Varian im Exil lebte. Die beiden Prinzen übten oft gemeinsam den Zweikampf. Arthas' Verfall in den Wahnsinn, der Mord an seinem Vater Terenas und sein Verrat an Lordaeron verwandelten ihre einstige Freundschaft in bitteren Hass.",al={"kannte varian arthas","varian und arthas","waren arthas und varian freunde"}}},fx={["4f50c804"]={q="Wer ist Varian Wrynn?",a="König Varian Wrynn ist der rechtmäßige Herrscher des Königreichs Sturmwind und der Erbe des Hauses Wrynn. Als Junge erlebte er während des Ersten Krieg den Fall seines Königreichs und die Ermordung seines Vaters, König Llane. Er wurde nach Lordaeron verbannt und kehrte Jahre später zurück, nachdem die Allianz seine Heimat zurückerobert hatte, um mit achtzehn Jahren den Thron zu besteigen und Sturmwind wieder aufzubauen. Kürzlich jedoch verschwand der König unter mysteriösen Umständen, als er auf einer diplomatischen Reise war, was das Königreich in Aufruhr versetzte.",al={"wer ist varian","könig varian","könig von sturmwind","wer ist könig wrynn"}},["4a21f8ea"]={q="Wer sind die Verbündeten von Varian Wrynn?",a="Varian steht im Zentrum der Großen Allianz. Zu seinen engsten Beratern und Beschützern zählen Hochlord Bolvar Fordragon, der während seiner Abwesenheit als Regent regiert, und die königliche Beraterin Lady Katrana Prestor. Seine größten historischen Bindungen bestehen zu den Königreichen der Allianz von Lordaeron, gefördert durch König Terenas Menethil II., der den jungen Varian nach dem Fall von Sturmwind aufnahm. Als König von Sturmwind befehligt er dessen Armeen und Ritter.",al={"varian verbündete","mit wem arbeitet varian zusammen","varian wrynn fraktion"}}},fp="12,201,16.519.0,22.441.0,17.358.1,31.131.0,47.224.0,47.235.1,34.189.0,36.264.0,52.289.0"}
P.entries["topic:venture-company"] = {n="Venture Company",s="In ganz Kalimdor und den Östlichen Königreichen betreiben Trupps der Venture Company Tagebau und Kahlschlag, ohne Rücksicht auf Bevölkerung und Natur. Mogul Razdunk lenkt das skrupellose Goblinkartell aus der Ferne. Seine Trupps suchen mit schweren Maschinen nach Rohstoffen, fernab großer Goblinhäfen wie Beutebucht und Ratschet.",h="In ganz Kalimdor und den Östlichen Königreichen betreiben Trupps der Venture Company Tagebau und Kahlschlag...",kw={"fizsprocket","gerenzo","puzik gallywix","razdunk","samophlange","schredder","das schlickermoor","super reaper","venture co","venture company","die scherwindklippe"},ang={["class:Druid"]="Als Druide erkennt Ihr die Schäden durch den massiven Holzschlag der Venture Company im Steinkrallengebirge und ihre Verschmutzung natürlicher Quellen in Mulgore und im Brachland.",["class:Rogue"]="Als Schurke wisst Ihr, dass die Shattered Hand und der SI:7 den Gifthandel der Venture Company genau beobachten. Ihre Agenten dringen in deren Türme ein und sabotieren hochrangige Vorarbeiter, um tödliche chemische Mischungen zu erbeuten.",["profession:Engineering"]="Als Ingenieur wisst Ihr, dass die Venture Company einige der besten Schredder und mechanischen Regler Azeroths baut. Andere Unternehmen schätzen ihre Baupläne und versuchen, sie zu stehlen.",["race:Tauren"]="Als Tauren wisst Ihr, dass die Venture Company ohne Erlaubnis in die heiligen Hügel Mulg ores eindrang. Ihre Trupps vergifteten die Brunnen der Ahnen und schlugen gegen den Willen der Earth Mother Holz."},sec={{t="Industrielle Plünderung",b="Trupps der Venture Company reißen das Land auf der Suche nach Rohstoffen auf. Mogul Razdunk lenkt das Kartell aus der Ferne, und seine Arbeiter setzen überall auf Azeroth schwere Maschinen ein. Schredder ernten Holz, Bohranlagen dringen in die Erde ein, und Raffinerien verarbeiten die Funde. Das Kartell eignet sich Rohstoffe mit Gewalt an und missachtet dabei Verträge, Grenzen und die Rechte der Einheimischen."},{t="Vorstoß nach Kalimdor",b="In ganz Kalimdor haben sich die Trupps der Venture Company Feinde gemacht. In Mulgore schickte Supervisor Fizsprocket Bohrer und Bergbaugeräte in die östlichen Klippen, obwohl die Tauren dem Kartell die Schürfrechte verweigert hatten. Die Arbeiten verschmutzten Wasserbrunnen in den gesamten Ebenen. Weiter nördlich verwandelte das Kartell das Schlickermoor im Brachland in eine chemische Kloake für seine Ölpumpen. Es beanspruchte auch die ehemalige Felsadermine der Horde, wo es gefährliche Experimente mit Samophlanchen und giftigen Gebräuen durchführte.\n\nAn der Scherwindklippe im Steinkrallengebirge leitet Gerenzo Pfeifzang die Holzfällertrupps. Die gewaltigen Super Reaper 6000-Maschinen des wahnsinnigen Lepragnoms haben ganze Haine gefällt."},{t="Firmenfehden und zwielichtige Verträge",b="Die Venture Company hat andere Goblins gegen sich aufgebracht und sich weitere Feinde gemacht. Baron Revilgaz aus Beutebucht heuert oft Trupps an, um das Basislager und die Bohrinsel des Kartells am Nazferitisee anzugreifen. Er will ihre Übergriffe stoppen und ihre fortschrittlichen Schredder-Treibstoffregler erbeuten. Die Tüftlergewerkschaft in Ratschet spioniert das Kartell aus, um Konstruktionspläne zu stehlen.\n\nDer SI:7 und die Shattered Hand haben den Handel des Kartells mit gefährlichen alchemistischen Verbindungen aufgedeckt. Es verkauft Zanzils bewusstseinsverändernde Gifte an Nekromanten der Defias in Westfall. Giftige Dämpfe helfen ihm außerdem dabei, mutierte Drohnenarbeiter heranzuzüchten."}},faq={{q="Wer führt die Venture Company?",a="Mogul Razdunk führt die Venture Company aus der Ferne und lenkt ihre größeren Unternehmungen. Regionale Aufseher, Vorarbeiter und angeheuerte Aufpasser leiten die Arbeitsstätten in ganz Azeroth. Zu ihnen gehören Supervisor Fizsprocket in Mulgore, Supervisor Lugwizzle im Schlickermoor und Gerenzo Pfeifzang im Steinkrallengebirge.",al={"venture co anführer","venture company boss","wer leitet venture co","mogul razdunk"}},{q="Warum hasst die Horde die Venture Company?",a="Die Horde hasst die Venture Company, weil sie Gebiete ausbeutet, die sie als Land ihrer Ahnen betrachtet. In Mulgore drang das Kartell ohne Erlaubnis in die östlichen Berge ein und verschmutzte die heiligen Wasserbrunnen der Tauren. Im Brachland riss es die Felsadermine der Horde an sich und verschmutzte das Schlickermoor mit einem giftigen Ölteppich.",al={"tauren venture co","warum hasst die horde venture co","mulgore venture company"}},{q="Sind sie mit dem Steamwheedle Cartel oder Beutebucht verbunden?",a="Nein. Die Venture Company ist vom Steamwheedle Cartel unabhängig, und die beiden Unternehmen sind erbitterte Feinde. Baron Revilgaz aus Beutebucht heuert oft Söldner an, um ihre Holzfällerarbeiten im Schlingendorntal zu stören. Stotterspritter aus Ratschet schickt Agenten los, um ihre Schredder zu sabotieren und ihre Baupläne zu stehlen.",al={"gehören sie zu steamwheedle","venture co beutebucht","ratschet venture co"}},{q="Warum leitet ein Lepragnom die Arbeiten an der Scherwindklippe?",a="Die Venture Company heuerte Gerenzo Pfeifzang wegen seines skrupellosen technischen Geschicks und seines Entwurfs des gewaltigen Super Reaper 6000 an. Seine Einstellung erzürnte Gobliningenieure wie Ziz Fizziks und die Trade Princes in Undermine. Sie missbilligten Razdunks Geschäfte mit dem ausgestoßenen Gnom.",al={"gerenzo wrenchwhistle","gnom im steinkrallengebirge","warum lepragnom venture"}},{q="Was macht die Venture Company in Westfall?",a="Die Venture Company trieb illegalen Handel mit der Bruderschaft der Defias. Das Kartell beschaffte Zanzilli-Gifte und verkaufte die Mischung an den Defias-Agenten Klaven Mortwake in Westfall. Er nutzte sie, um willenlose Defias Drones zu erschaffen, wie die Arbeiter an den Arbeitsstätten der Venture Company.",al={"venture co westfall","klaven mortwake venture co","venture defias"}},{q="Was wird im Schlickermoor hergestellt?",a="Die Venture Company errichtete eine industrielle Bohranlage über einer einst klaren Quelle. Sie fördert und raffiniert Öl und leitet dabei giftigen Schlamm ins gesamte nördliche Brachland. Die dortigen Forscher erproben außerdem komplexe mechanische Samophlanchen und stellen giftige Mischungen her.",al={"schlickermoor öl","brachland venture co bohrinsel","samophlanche schlickermoor"}}},fx={f7d6a0aa={q="Was ist die Venture Company?",a="Die Venture Company ist ein skrupelloses, von Goblins geführtes Kartell, das sich darauf spezialisiert hat, Azeroths natürliche Ressourcen für maximalen Profit zu plündern. Spezialisiert auf schwere Maschinen, Bergbau und Kahlschlag ist ihre Philosophie einfach: Wenn man es ausgraben, abholzen oder aus einem Berg sprengen kann, dann tun sie es. Sie operieren völlig außerhalb lokaler Gesetze und traditioneller Ethik und nutzen Schredder, Bohrer und bewaffnete Vollstrecker, um Wohlstand aus den Wildnisgrenzen zu extrahieren.",al={"wer ist die venture company","was ist die venture company","venture company lore"}},["36300444"]={q="Warum ist die Venture Company Reisenden gegenüber feindselig?",a="Die Venture Company betreibt illegale, aggressive Ressourcengriffe in umkämpften und souveränen Gebieten, von den heiligen Hügeln von Mulgore bis zu den Wäldern von Steinkrallengebirge. Da sie routinemäßig unbefugt eindringen, Ansprüche stehlen und Konkurrenten ausschalten, sind ihre Betriebe schwer befestigt. Ihre Vorarbeiter betrachten jeden Außenstehenden als Industriespion, rivalisierenden Anspruchsteller oder rachsüchtigen Einheimischen, der gekommen ist, um ihre Maschinen zu sabotieren, und sie weisen ihre Vollstrecker an, zuerst zu schießen.",al={"warum greift venture company an","venture company aggro","warum ist die venture company feindselig"}},["48d27ccb"]={q="Mit wem ist die Venture Company verbündet?",a="Die Venture Company arbeitet in erster Linie für ihren eigenen Profit, schließt aber häufig zwielichtige Geschäfte mit externen Fraktionen ab, wenn Geld auf dem Spiel steht. Sie haben geheimen Handel mit The Defias Brotherhood etabliert und ihnen von Zanzil abgeleitete alchemistische Mischungen und giftige Gebräue verkauft. Abgesehen von solchen Söldnergeschäften unterhalten sie kaum Freunde, treten routinemäßig den neutralen Kartellen wie dem Steamwheedle Cartel auf die Füße und erregen den Zorn der Handelsprinzen in Unterstadt.",al={"venture company verbündete","mit wem arbeitet die venture company zusammen","venture company partnerschaften"}}},fp="15,297,18.336.0,23.645.1,39.564.2,30.289.0,44.300.0,62.294.0,58.278.0,46.260.1,41.255.0"}
P.entries["topic:war-of-the-ancients"] = {n="Krieg der Ahnen",s="Als Königin Azshara und ihre Hochgeborenen den Brunnen der Ewigkeit öffneten, drang die Brennende Legion nach Azeroth ein. Malfurion Sturmgrimm, Illidan und Tyrande Wisperwind führten den Widerstand an, der die Dämonen zurücktrieb. Die Zerstörung des Brunnens löste die Große Zerschlagung aus, die das uralte Kalimdor zerbrach und die Welt veränderte.",h="Als Königin Azshara und ihre Hochgeborenen den Brunnen der Ewigkeit öffneten, drang die Brennende Legion nach...",kw={"azshara","brennende legion","cenarius","hochgeborene","malfurion","sargeras","zerschlagung","tyrande","krieg der ahnen","brunnen der ewigkeit"},ang={["class:Druid"]="Als Druide tretet Ihr das Erbe eines Weges an, der in diesem Konflikt entstand. Malfurion Sturmgrimm lernte die Wege der Wildnis von Cenarius und zeigte, dass die Macht der Natur kosmische Zerstörung bezwingen konnte.",["class:Mage"]="Als Magier wisst Ihr, dass die rücksichtslose Arroganz der Hochgeborenen in ganz Azeroth vor den Gefahren ungezügelter arkaner Macht warnt.",["class:Priest"]="Als Priester folgt Ihr einer Tradition, die Tyrande Wisperwind geprägt hat. Ihre Beherrschung von Elune's Grace rückte die Priesthood of the Moon ins Zentrum der militärischen und zivilen Führung der Nachtelfen.",["race:NightElf"]="Als Nachtelf kennt Ihr den Krieg, auf den das tiefe Misstrauen Eures Volkes gegenüber arkaner Magie, seine Verehrung für Cenarius und seine beständige Führung unter Malfurion und Tyrande zurückgehen.",["race:Tauren"]="Als Tauren könnt Ihr Cenarius und die Halbgötter der Wildnis ehren. Ihre Waldgeister kämpften vor zehntausend Jahren an der Seite der Nachtelfen gegen die Legion."},sec={{t="Die Torheit der Hochgeborenen",b="Auf dem Höhepunkt des uralten Kaldorei-Imperiums schöpften Königin Azshara und ihre hochgeborenen Zauberer ausgiebig aus der arkanen Macht des Brunnens der Ewigkeit. Ihre Zauber reichten bis in das Große Dunkle Jenseits und erregten die Aufmerksamkeit von Sargeras, dem Gebieter der Brennenden Legion. Er versprach Macht und Vollkommenheit. Dann öffneten Azshara und ihr Berater Xavius einen Riss im Brunnen.\n\nTeufelshunde, Teufelswachen, Verdammniswachen und monströse Befehlshaber strömten nach Zin-Azshari. Sie schlachteten alle ab, die keine Hochgeborenen waren, und begannen einen Kreuzzug, um die Welt von allem Leben zu säubern."},{t="Der Widerstand der Kaldorei",b="Nachtelfen außerhalb der Kaste der Hochgeborenen erhoben sich gegen das Gemetzel. Drei bemerkenswerte Anführer sammelten den Widerstand: Malfurion Sturmgrimm, der erste sterbliche Druide; Tyrande Wisperwind, eine ergebene Priesterin der Elune; und Illidan, Malfurions begabter Bruder. Gemeinsam führten sie einfache Nachtelfen an eine verzweifelte Front gegen den Ansturm der Legion."},{t="Der Preis des Sieges",b="Der Krieg nahm welterschütternde Ausmaße an, als Cenarius die uralten Wilden Götter und Drachenschwärme zum Kampf rief. Um Sargeras daran zu hindern, Azeroth zu betreten, versuchten Malfurion und der Widerstand, das Portal über dem Brunnen der Ewigkeit zum Einsturz zu bringen. Ihr verzweifeltes Wagnis schleuderte das Dämonenheer zurück in den Wirbelnden Nether, doch die Belastung erwies sich als zu groß.\n\nDer Brunnen implodierte mit gewaltiger Wucht und löste die Große Zerschlagung aus. Kalimdor zerbrach in einzelne Kontinente, das Zentrum der Welt wurde überflutet und bildete das große Meer, und die Kultur der Kaldorei veränderte sich für immer."}},faq={{q="Was löste den Krieg der Ahnen aus?",a="Königin Azshara und ihre hochgeborenen Zauberer schöpften aus der arkanen Macht des Brunnens der Ewigkeit. Ihre Zauber reichten durch den Kosmos und lockten den dunklen Titanen Sargeras an. Er überredete die Hochgeborenen, ein Tor im Brunnen zu öffnen, damit die Brennende Legion nach Azeroth eindringen konnte.",al={"warum begann der krieg","wer verursachte den krieg der ahnen","brunnen der ewigkeit portal"}},{q="Was war die Große Zerschlagung?",a="Die Große Zerschlagung war die Katastrophe, die den Krieg beendete. Um Sargeras daran zu hindern, die Welt zu betreten, brachte der Widerstand das Portal im Brunnen der Ewigkeit zum Einsturz. Der Brunnen implodierte, zerriss Kalimdors einzigen Superkontinent in getrennte Landmassen und ließ das große Meer entstehen.",al={"was ist die zerschlagung","wie zerbrach kalimdor","brunnen der ewigkeit explosion"}},{q="Wer führte die sterblichen Streitkräfte gegen die Legion an?",a="Malfurion Sturmgrimm, sein Bruder Illidan und die Priesterin Tyrande Wisperwind scharten die Nachtelfen gegen Azshara und die Legion um sich. Der Halbgott Cenarius brachte die uralten Geister der Wildnis an ihre Seite.",al={"wer führte den widerstand an","anführer des kaldorei-widerstands"}},{q="Kämpften andere Völker an der Seite der Nachtelfen?",a="Ja. Die großen Drachenschwärme schlossen sich dem Kampf an, und Cenarius führte seine wilden Brüder an der Seite der Nachtelfen gegen die dämonische Invasion in die Schlacht.",al={"tauren im krieg der ahnen","wer half den nachtelfen"}},{q="Was geschah während des Krieges mit Königin Azshara?",a="Königin Azshara blieb bis zum bitteren Ende in ihrem Palast in Zin-Azshari, besessen davon, Sargeras nach Azeroth zu bringen. Als der Brunnen implodierte und die Ozeane die Hauptstadt verschlangen, versanken die Königin und ihre überlebenden hochgeborenen Getreuen in den tosenden Tiefen.",al={"wo ist azshara","starb königin azshara"}},{q="Warum misstrauen die Nachtelfen heute der arkanen Magie?",a="Die Kaldorei sahen, wie der ungezügelte Hunger der Hochgeborenen nach arkaner Magie die Brennende Legion heraufbeschwor und das uralte Kalimdor zerstörte. Danach verboten die Nachtelfen arkane Zauberei und wandten sich dem Druidentum und dem Glauben an Elune zu, um ihre Lande zu schützen.",al={"warum hassen nachtelfen magier","magieverbot der kaldorei"}}},fx={c481acb5={q="Was war der Krieg der Ahnen?",a="Der Krieg der Ahnen war der erste große Krieg Azeroths gegen die dämonische Brennende Legion, der vor etwa zehntausend Jahren stattfand. Von Versprechungen gottgleicher Macht korrumpiert, wirkten Königin Azshara und ihre Hochgeborenen Zauber durch den Brunnen der Ewigkeit, um Sargeras und seine dämonischen Legionen in die Welt zu bringen. Der Widerstand der Nachtelfen, unterstützt durch frühe sterbliche Völker, die Drachenschwärme und die Wilden Götter, kämpfte verzweifelt, um die Invasion aufzuhalten, was in der Zerstörung des Brunnens und der Großen Teilung gipfelte.",al={"was ist der krieg der ahnen","krieg der ahnen erklärt","erste legion-invasion"}},["9e83d11f"]={q="Warum wird er Krieg der Ahnen genannt?",a="Der Konflikt erhielt seinen Namen sowohl von der uralten Ära, in der er stattfand – zehntausend Jahre vor dem modernen Zeitalter –, als auch von der zentralen Rolle, die die Ahnen selbst spielten. Halbgötter und Wilde Götter wie Cenarius marschierten an der Seite der sterblichen Verteidiger in den Krieg, um Azeroth vor der dämonischen Vernichtung zu bewahren.",al={"warum krieg der ahnen genannt","bedeutung name krieg der ahnen","name krieg der ahnen"}}},fp="19,302,21.530.0,23.352.0,20.554.0,36.259.0,29.276.0,45.211.0,48.149.0,46.257.0,52.239.0"}
P.entries["topic:warlock"] = {n="Hexenmeister",s="Überall auf Azeroth wirken Hexenmeister verbotene Kräfte, die Furcht und Misstrauen hervorrufen. Sie befehligen Dämonen und wirken Flüche, Feuer und Shadow Magic. Manche wenden diese Künste gegen die Brennende Legion und ihre Diener.",h="Überall auf Azeroth wirken Hexenmeister verbotene Kräfte, die Furcht und Misstrauen hervorrufen.",kw={"gebrechen","dämonologie","zerstörung","teufel","teufelsjäger","gul'dan","wichtel","schattenrat","sukkubus","twisting nether","leerwandler","hexenmeister"},ang={["class:Mage"]="Als Magier blickt Ihr vielleicht mit Verachtung und Furcht auf Hexenmeister. Ihr Umgang mit dem Nether wirkt undiszipliniert und gefährdet alles sterbliche Leben.",["class:Paladin"]="Als Paladin betrachtet Ihr das Beschwören von Dämonen als abscheuliche Ketzerei. Hexenmeister, die es praktizieren, begegnet Ihr mit offener Feindseligkeit.",["class:Shaman"]="Als Schamane erinnert Ihr Euch daran, wie Gul'dans Teufelszauberei die Bande Eurer Vorfahren zu den Geistern zerriss und Draenors Land tötete. Darum verabscheuen Schamanen Hexenmeistermagie mehr als alles andere.",["race:Orc"]="Als Orc tragt Ihr beim Praktizieren der Dämonologie den bitteren Makel des Blutfluchs der Alten Horde. Manche Orcs bewahren diese Künste, um in einer feindseligen Welt zu überleben.",["race:Troll"]="Als Troll beginnt Ihr Eure Ausbildung zum Hexenmeister an der Seite orcischer Anwärter im Tal der Prüfungen. Thralls Horde begegnet jedem Anwender von Teufelsmagie mit derselben Vorsicht."},sec={{t="Verbotene Künste",b="Wo gewöhnliche Zauberwirker Verderben sehen, erkennen Hexenmeister einen Weg zum Sieg. Sie greifen aus der Ferne mit Schatten und Feuer an und entziehen ihren Feinden Lebenskraft und Seelen, um ihre mächtigsten Rituale zu nähren. Schwefel regnet vom Himmel, und qualvolle Flüche zerrütten den Verstand.\n\nHexenmeister tragen einfache Stoffkleidung und haben wenig Kraft, um einem Schlag standzuhalten. Sie beschwören Schrecken, die sich der Gefahr stellen, und opfern dämonische Knechte, um ihr eigenes Leben zu bewahren."},{t="Dämonische Knechtschaft",b="Die Herrschaft eines Hexenmeisters über den Twisting Nether beginnt mit kleinen Abmachungen und wächst zu eiserner Macht heran. Neulinge befehligen schelmische Wichtel, die Flammen schleudern. Mit tieferem Wissen um Teufelsmagie binden sie Leerwandler aus schattenhaften Tiefen, die körperliche Schläge abfangen, Sukkuben, die den Verstand von Feinden betören, und gefräßige Teufelsjäger, die magische Energie verschlingen.\n\nJede Beschwörung erfordert gefährliche Konzentration. Die Bewohner des Nethers prüfen ihre Meister ständig auf Schwäche."},{t="Ein Vermächtnis des Verderbens",b="Die orcische Dämonologie nahm auf Draenor ihren Anfang, als Kil'jaeden, ein Dämonenfürst, Gul'dan mit dem Versprechen höchster Macht verführte. Gul'dan gründete den geheimen Schattenrat und machte viele Schamanen zu Meistern der Teufelsmagie. Dämonische Magie ließ Draenors fruchtbare Ebenen zu kargem roten Ödland verdorren, und die Alte Horde fiel durch das Dunkle Portal ein.\n\nUnter den Menschen verboten die Kirin Tor die Dämonologie und machten Jagd auf unerlaubte Beschwörungen. Doch ehrgeizige Magier erlagen weiterhin dem Reiz ungezähmter Zauberei."},{t="Geduldete Ausgestoßene",b="Hexenmeister wandeln heute auf einem schmalen Grat zwischen Nützlichkeit und Hinrichtung. In Sturmwind treffen sie sich versteckt in düsteren Tavernenkellern, fernab der wachsamen Augen der Kathedrale des Lichts. In Orgrimmar versammeln sie sich in den schattigen Klüften der Kluft der Schatten, überwacht von Thralls schamanistischem Regime.\n\nIhre Methoden rufen Abscheu hervor, doch weder die Allianz noch die Horde kann den Vorteil leugnen, den Hexenmeistermagie auf einem feindlichen Schlachtfeld bietet."}},faq={{q="Was unterscheidet einen Hexenmeister von einem Magier?",a="Magier nutzen die geordnete Struktur arkaner Magie, um Feuer, Frost und Energie zu formen. Hexenmeister überschreiten deren sichere Grenzen und greifen zu chaotischer Teufelsmagie, Schatten und Dämonen. Viele begannen als Magier, wurden dann ungeduldig mit akademischen Grenzen und suchten verbotene Abkürzungen zur Macht.",al={"hexenmeister oder magier","unterschied zwischen hexenmeister und magier","magier oder hexenmeister"}},{q="Sind alle Hexenmeister böse?",a="Nicht jeder Hexenmeister ist bösartig, auch wenn Hexenmeistermagie gefährlich ist und verderbt. Viele verfallen dem Wahnsinn oder schließen sich dämonischen Kulten an. Andere schwören ihrer Fraktion die Treue und setzen dunkle Zauberei, gestohlene Seelen und gebundene Dämonen gegen Bedrohungen wie die Geißel und die Brennende Legion ein.",al={"sind hexenmeister böse","können hexenmeister gut sein","warum erlaubt die allianz hexenmeister"}},{q="Wie beschwören und kontrollieren Hexenmeister Dämonen?",a="Hexenmeister ziehen mit Ritualkreisen, dunklen Beschwörungen und Seelenenergie Kreaturen aus dem Twisting Nether herbei. Sie müssen den Willen jedes Dämons brechen und ihn mit schierer geistiger Überlegenheit binden. Lässt ihre Konzentration nach, kann der Dämon seinen Meister abschlachten.",al={"wie funktionieren begleiter von hexenmeistern","überlieferung zu dämonischen beschwörungen","dämonen binden"}},{q="Woher stammen orcische Hexenmeister?",a="Orcische Hexenmeister nahmen auf Draenor ihren Anfang, als Kil'jaeden Gul'dan vom Schamanismus zur dämonischen Zauberei verführte. Gul'dan gründete den Schattenrat und bildete andere Orcs aus. Teufelsverderbnis breitete sich über ihre Heimat aus, bis Draenors Boden verdorrte und starb.",al={"wie wurden orcs zu hexenmeistern","gul'dan und hexenmeister","ursprung orcischer teufelsmagie"}},{q="Warum dulden Allianz und Horde Hexenmeister in ihren Städten?",a="Keine der beiden Fraktionen vertraut Hexenmeistern. In Sturmwind und Eisenschmiede praktizieren sie in geheimen Kellern und vergessenen Tunneln, um öffentlichen Aufruhr zu vermeiden. In Orgrimmar hält man sie in der Kluft der Schatten. Anführer dulden sie, weil ihre Flüche und Beschwörungen im Krieg wirksame Waffen sind.",al={"warum sind hexenmeister erlaubt","sind hexenmeister legal","rechtmäßigkeit von hexenmeistern"}},{q="Wozu dienen Seelensplitter?",a="Hexenmeister entziehen besiegten Feinden ihre Lebenskraft und erschaffen daraus kristallisierte Seelensplitter. Diese Fragmente bergen rohe Macht, mit der sie die natürlichen Gesetze der Magie umgehen, monströse Dämonen beschwören und ihre zerstörerischsten Zauber wirken können.",al={"warum nehmen hexenmeister seelen","überlieferung zu seelensplittern","seelen ernten"}},{q="Welche Völker können Hexenmeister sein?",a="Menschen und Gnome praktizieren als Hexenmeister in der Allianz. In der Horde sind es Orcs, Trolle und die Verlassenen. Zwerge, Nachtelfen, Tauren und die Skyborne tun es nicht. Wo immer sie leben, werden Hexenmeister geduldet, aber nicht als vertrauenswürdig angesehen.",al={"wer kann hexenmeister sein","völker der hexenmeister","können trolle hexenmeister sein","troll-hexenmeister"}}},fp="7,204,14.431.0,17.443.0,16.483.0,17.429.0,43.258.0,22.278.0,42.241.0,33.238.0,64.282.0,30.219.0,28.223.0"}
P.entries["topic:warrior"] = {n="Krieger",s="In ganz Azeroth stehen Krieger mit Stahl, Disziplin und Kampfwut an vorderster Front. Sie tragen schwere Plattenrüstung und führen viele Waffen, um Verbündete zu schützen oder feindliche Reihen zu durchbrechen. Jedes Volk und jede Zivilisation hat Krieger, von Stadtwachen und königlichen Streitern bis hin zu umherziehenden Söldnern.",h="In ganz Azeroth stehen Krieger mit Stahl, Disziplin und Kampfwut an vorderster Front.",kw={"waffen","berserker","furor","nahkampf","plattenrüstung","schutz","wut","schild","vorhut","krieger"},ang={["class:Warrior"]="Jeder Kampf stellt Eure Ausdauer und Euren Mut auf die Probe. Wandelt den Schmerz eingehender Schläge in Wut um, dann könnt Ihr die Front halten.",["faction:Alliance"]="Als Krieger der Allianz schließt Ihr Euch den Fußsoldaten und Rittern an, die menschliche Königreiche, zwergische Berghochburgen und elfische Wälder verteidigen.",["faction:Horde"]="Als Krieger der Horde folgt Ihr einer Lebensweise des Kampfes, in der Grunzer-Sturmtruppen und Taurenkämpfer jeden Vorstoß ins Feindesgebiet anführen.",["profession:Blacksmithing"]="Als Krieger seid Ihr auf Schmiede angewiesen, die Euch mit schwerer Plattenrüstung, stabilen Rundschilden und scharfen Klingen für den Kampf versorgen."},sec={{t="Meister von Stahl und Schild",b="Krieger verlassen sich auf Stärke, Disziplin und Waffenkunst, nicht auf Gebete oder Zauber. Schwere Plattenrüstung hilft ihnen, die Front zu halten. Einige verschanzen sich hinter hohen Schilden, halten Angriffen stand und lenken die Gefahr von Zauberkundigen und Bogenschützen ab. Andere führen zweihändige Stangenwaffen, Äxte oder Großschwerter. Manche kämpfen mit je einer Klinge in jeder Hand und schlagen sich durch feindliche Reihen."},{t="Die Macht der Kampfwut",b="Im Kampf entfachen Schmerz und Blut die Wut eines Kriegers. Sie wächst, wenn Krieger Feinde treffen und deren Angriffe aushalten. Erfahrene Kämpfer formen diese Kraft zu vernichtenden Hieben und weiten Waffenschwüngen. Ihre Schlachtrufe stärken Verbündete in der Nähe und brechen die Moral des Feindes."},{t="Eine Tradition aller Völker",b="Jedes Volk Azeroths hat seine Krieger. Sturmwind stellt disziplinierte Ritter und Fußsoldaten auf, während Eisenschmiede seine stämmige Gebirgsgarde ruft. Die Horde schart orkische Klingenmeister, Taurenkrieger und Todeswachen der Verlassenen um sich.\n\nEhre, die Verteidigung ihrer Lande oder die Aussicht auf Münzen kann Krieger zu den Waffen rufen. Sie bilden das Rückgrat jedes stehenden Heeres."}},faq={{q="Was verleiht Kriegern Kraft, wenn sie keine Magie einsetzen?",a="Krieger schöpfen ihre Kraft aus Kampfkunst, Ausbildung und Wut. Sie bauen Wut auf, indem sie Feinde treffen und Schläge einstecken, und entfesseln sie dann in weiten Angriffen, Schildschlägen und lautem Gebrüll.",al={"wie kämpfen krieger","ressource des kriegers","was ist wut"}},{q="Welche Völker können Krieger werden?",a="Jedes Volk Azeroths kann Krieger werden. Alle sterblichen Kulturen brauchen gepanzerte Kämpfer an vorderster Front, von den zwergischen Verteidigern Khaz Modans bis zu den orkischen Sturmtruppen Durotars.",al={"wer kann krieger werden","krieger-völker","kann jedes volk krieger werden"}},{q="Welche Rolle übernehmen Krieger in einer Kampfgruppe?",a="Krieger kämpfen meist an vorderster Front. Wer Schutz bevorzugt, nutzt Plattenrüstung und Schilde, um Angriffen standzuhalten und gefährliche Feinde auf sich zu ziehen. Wer Waffen oder Furor bevorzugt, führt schwere Zweihandwaffen oder gepaarte Klingen, um Feinde mit roher Kraft zu überwältigen.",al={"rolle des kriegers","tanken krieger","waffen oder furor oder schutz"}},{q="Welche Waffen können Krieger führen?",a="Krieger führen fast alle Waffen, die in den Kriegen der Sterblichen zum Einsatz kommen: Schwerter, Streitkolben, Äxte, Stangenwaffen, Dolche und Stäbe, ein- oder zweihändig. Außerdem tragen sie schwere Schilde und verwenden Bögen, Schusswaffen und Armbrüste.",al={"waffen des kriegers","können krieger bögen benutzen","was können krieger ausrüsten"}},{q="Wer sind einige berühmte Krieger aus der Geschichte Azeroths?",a="Zu den berühmten Kriegern zählen Lord Anduin Lothar, Champion von Sturmwind und Oberster Befehlshaber der Allianz von Lordaeron; Grommash Höllschrei, Häuptling des Kriegshymnenklans; und Cairne Bluthuf, Hochhäuptling der vereinten Taurenstämme.",al={"berühmte krieger","legendäre krieger","wer sind helden der krieger"}},{q="Wo erhalten neue Krieger ihre formelle Ausbildung?",a="Krieger trainieren überall dort, wo sich Soldaten versammeln. Menschliche Rekruten üben in der Abtei von Nordhain; Zwerge und Gnome lernen in Ambossar im Coldridgetal; und Nachtelfen trainieren im Laubschattental. Orcs und Trolle üben im Tal der Prüfungen, Kämpfer der Verlassenen melden sich in den Kasernen von Todesend, und die Himmelsgeborenen beginnen auf der Insel Zephras.",al={"krieger-ausbilder","wo lernen krieger","standorte der krieger-ausbilder"}}},fx={["2a49f247"]={q="Was ist ein Krieger?",a="Krieger sind die quintessentiellen Frontkämpfer Azeroths, die sich eher auf schiere körperliche Leistungsfähigkeit, Waffenbeherrschung und schwere Rüstung als auf mystische Künste verlassen. Sie stammen aus allen Kulturen und Hintergründen und dienen als standhafte Stadtwachen, furchterregende Berserker, Söldnersoldaten und erfahrene Befehlshaber. Ausgestattet mit Schilden und einer riesigen Auswahl an Waffen stürmen Krieger direkt in das Getümmel, um den Zorn des Feindes auf sich zu ziehen und ihre zerbrechlicheren Gefährten vor Schaden zu schützen.",al={"was ist ein krieger in der lore","krieger lore identität","wer sind krieger"}},["2e549509"]={q="Was bedeutet es, den Pfad des Kriegers zu beschreiten?",a="Das Leben eines Kriegers zu wählen bedeutet, sich ständigem Training, Disziplin und kompromissloser kriegerischer Perfektion zu widmen. Ihr betretet das Schlachtfeld ohne Zauber, die Euch schützen, und setzt Euren gesamten Glauben in schwere Plattenrüstung, Euren gewählten Stahl und Eure Instinkte. Ob Ihr nun nach Ruhm sucht, als Söldner ein Vermögen verdienen wollt oder Euer Volk vor drohenden Gefahren verteidigen möchtet – Ihr seid die lebende Mauer, die sich der Gefahr direkt entgegenstellt und rohe Kampfwut in entscheidende Schläge verwandelt.",al={"krieger werden","was bedeutet es krieger zu sein","das leben eines kriegers"}}},fp="7,292,27.348.0,24.257.0,21.356.0,47.185.0,31.179.0,46.263.0,40.208.0,50.237.0,52.320.0"}
P.entries["topic:warsong-clan"] = {n="Kriegshymnenklan",s="Auf ganz Kalimdor schlägt der Kriegshymnenklan Holz für die junge Horde. Einst führte ihn der verehrte Häuptling Grommash Hellscream. Der Klan überstand Exil, Internierungslager und dämonische Verderbnis. Heute ist seine Vorhut vor allem im Eschental im Einsatz, wo sie unablässig mit den Nachtelfen aneinandergerät.",h="Auf ganz Kalimdor schlägt der Kriegshymnenklan Holz für die junge Horde.",kw={"eschental","cenarius","grommash","hellscream","mannoroth","vorhuten des kriegshymnenklans","splitterholz","kriegshymnenklan"},ang={["faction:Alliance"]="Für viele in der Allianz zeigt die unerbittliche Aggression des Kriegshymnenklans, dass Frieden zwischen den Fraktionen unmöglich bleibt, solange seine Äxte im Eschental geschwungen werden.",["faction:Horde"]="The New Horde ist auf das Holz angewiesen, das die Vorhuten des Kriegshymnenklans im Eschental schlagen, um Siedlungen zu befestigen und sich über ganz Kalimdor auszubreiten.",["race:NightElf"]="Die Nachtelfen hassen den Kriegshymnenklan dafür, dass er heilige Wälder im Eschental abholzt und den Halbgott Cenarius getötet hat.",["race:Orc"]="Für die Orcs verkörpert der Kriegshymnenklan sowohl die tiefste Schande als auch die größte Erlösung ihres Volkes. Sie waren die Ersten, die Mannoroths Blut tranken, und ihr Häuptling starb, um den Griff des Dämons über alle Orcs zu brechen."},sec={{t="Ein Erbe des Widerstands",b="Auf den offenen Ebenen Draenors machte sich der Kriegshymnenklan mit schnellen Angriffen seiner Wolfsreiter einen Namen. Nach dem Fall der Horde entging der Klan der Gefangennahme, während andere Orcs in Internierungslagern der Allianz dahinsiechten. Der Kriegshymnenklan streifte durch die Wildnis und hielt an seiner kriegerischen Lebensweise fest. Schließlich schloss Thrall sich mit Hellscream zusammen, und gemeinsam schmiedeten sie The New Horde."},{t="Blut und Erlösung",b="Während des Dritten Krieges erreichte der Kriegshymnenklan Kalimdor. Thrall schickte Hellscream und seinen Klan ins Eschental, um Holz zu schlagen und einen Außenposten zu errichten. Ihr Eindringen erzürnte die Nachtelfen und den Waldhalbgott Cenarius. Als die Vernichtung drohte, trank der Kriegshymnenklan erneut vom dämonischen Blut Mannoroths und erschlug Cenarius in einem Rausch aus Teufelsverderbnis.\n\nThrall und seine Verbündeten befreiten Hellscream vom Fluch. Grom gab dann in einem schicksalhaften Kampf sein Leben und vernichtete Mannoroth. Sein Opfer brach den Dämonenblutfluch für immer und sicherte dem Kriegshymnenklan einen Platz in der Geschichte der Horde."},{t="Der Krieg um das Eschental",b="Heute führen die Vorhuten des Kriegshymnenklans Grommashs Auftrag im Eschental fort. Vom Splitterholzposten und den Holzfällerlagerstätten aus schlagen sie Holz für die junge Horde in den trockenen Einöden Durotars. Ihre Anwesenheit hat sie in einen erbitterten Konflikt mit den nachtelfischen Schildwachen der Silberschwingen gebracht. Der Kriegshymnenklan hält die Kriegshymnenschlucht und dringt trotz endloser Hinterhalte weiter in den uralten Wald vor."}},faq={{q="Wer führt den Kriegshymnenklan derzeit an?",a="Seit Grommash Hellscream am Ende des Dritten Krieges starb, hat sich der Kriegshymnenklan größtenteils Thralls The New Horde angeschlossen. Im Einsatz unterstehen die Vorhuten des Kriegshymnenklans im Eschental den örtlichen Befehlshabern und letztlich Kriegshäuptling Thrall.",al={"anführer des kriegshymnenklans","wer ist häuptling des kriegshymnenklans","aktueller häuptling des kriegshymnenklans"}},{q="Warum schlägt der Kriegshymnenklan im Eschental Holz?",a="The New Horde hat ihren Sitz in den trockenen Ebenen Durotars und des Brachlands, wo es kaum größere Holzvorkommen gibt. Der Kriegshymnenklan sammelt im Eschental Holz, um Städte wie Orgrimmar zu errichten, militärische Befestigungen instand zu halten und die wachsende Horde zu unterstützen.",al={"warum im eschental ernten","holz des kriegshymnenklans","orcs fällen bäume im eschental"}},{q="Wie hat der Kriegshymnenklan Cenarius getötet?",a="Während des Dritten Krieges führte Cenarius die Nachtelfen bei der erbitterten Verteidigung des Eschentals an und trieb den Kriegshymnenklan zur Verzweiflung. Der Klan trank aus einem Teich, der mit dem Blut des Grubenlords Mannoroth verseucht war. Das Blut verwandelte sie in dämonisch wahnsinnige Chaosorcs. Ihre entfesselte Wut überwältigte Cenarius und tötete ihn.",al={"cenarius' tod","wer hat cenarius getötet","kriegshymnenklan gegen cenarius"}},{q="Wie entkam der Kriegshymnenklan nach dem Zweiten Krieg den Internierungslagern?",a="Nach dem Zweiten Krieg versteckten sich Grommash Hellscream und der Kriegshymnenklan in den abgelegenen Wildnissen Lordaerons und entgingen der Gefangennahme durch die Allianz. Sie führten einen Guerillakrieg und bewahrten ihren Kampfgeist, bis Thrall sie fand.",al={"internierungslager des kriegshymnenklans","groms flucht","flucht des kriegshymnenklans"}},{q="Was ist die Kriegshymnenschlucht?",a="Die Kriegshymnenschlucht ist ein Tal in einer Schlucht im Süden des Eschentals, wo die Vorhuten des Kriegshymnenklans mit den nachtelfischen Schildwachen der Silberschwingen aneinandergeraten. Die Vorhuten kämpfen, um ihre Holzfällerlager zu schützen, während die Schildwachen die Orcs aus ihrem heiligen Wald vertreiben wollen.",al={"kriegshymnenschlucht hintergrundgeschichte","was ist die kriegshymnenschlucht","schlachtfeld des kriegshymnenklans"}},{q="Wer war Grommash Hellscream?",a="Grommash „Grom“ Hellscream war der legendäre Häuptling des Kriegshymnenklans und ein Mentor Thralls. Er war der erste Orc, der auf Draenor Dämonenblut trank, doch später erlöste er sich, indem er Mannoroth erschlug und alle Orcs aus dämonischer Knechtschaft befreite. Bei dieser Tat gab er sein Leben.",al={"wer ist grom","grom hellscream","grommash"}}},fx={ab40120e={q="Was ist der Kriegshymnenklan?",a="Der Kriegshymnenklan ist ein erbittert kriegerischer Orc-Clan, der für seine aggressive Natur und seine mobilen Wolfsreiter bekannt ist. Lange Zeit vom legendären Häuptling Grom Hellscream geführt, dient der Clan heute als eine wesentliche Säule von Thralls Horde und führt Holzfällerarbeiten sowie militärische Kampagnen in den dichten Wäldern des Eschental an.",al={"wer ist der kriegshymnenklan","wer sind die warsong","infos zum kriegshymnenklan"}},f1dd8797={q="Mit wem ist der Kriegshymnenklan verbündet?",a="Der Kriegshymnenklan ist Thralls Neuer Horde voll und ganz verpflichtet. Sie kämpfen Schulter an Schulter mit ihren Orc-Brüdern, den Dunkelspeeren, den Tauren von Mulgore und den neu aufgenommenen Verlassene, wobei sie lebenswichtiges Bauholz ernten, um die wachsenden Siedlungen der Horde in Durotar und dem Brachland zu versorgen.",al={"verbündete der warsong","für wen kämpfen die warsong","fraktion der warsong"}},["5b3f6a6c"]={q="Warum ist der Kriegshymnenklan gegenüber Reisenden der Allianz feindselig?",a="Als eine zentrale militärische Kraft der Horde betrachtet der Kriegshymnenklan Mitglieder der Allianz als Todfeinde. Ihr tief verwurzelter Hass wird im Eschental weiter geschürt, wo die Schildwachen der Silberschwingen der Nachtelfen und ihre Verbündeten den aggressiven Kahlschlag der heiligen, uralten Wälder durch den Clan erbittert bekämpfen.",al={"warum greifen warsong an","warum sind warsong feindselig","sind warsong feinde"}},b8b233bd={q="Woher stammt der Kriegshymnenklan?",a="Die Kriegshymnen stammten ursprünglich aus den Ebenen von Draenor, wo sie als wilde, bewegliche Wolfsreiter Berühmtheit erlangten, und zogen unter Grom Höllschrei mit der Horde nach Azeroth. Nachdem sie nach dem Zweiten Krieg den Internierungslagern der Menschen entgangen waren, folgten sie später Thrall über das große Meer nach Kalimdor.",al={"geschichte des kriegshymnenklans","ursprung der kriegshymnen","woher stammt der kriegshymnenklan"}}},fp="12,283,20.345.0,20.563.0,21.372.0,37.222.0,41.244.0,34.299.0,69.208.0,22.259.0,28.261.0"}
P.entries["topic:westfall-brigade"] = {n="Volksmiliz",s="In Westfall hält die Volksmiliz gegen die Bruderschaft der Defias stand. Gryan Starkmantel scharte die Freiwilligen auf der Späherkuppe um sich, nachdem Sturmwind seine Truppen abgezogen hatte. Gemeinsam mit örtlichen Bauern und durchreisenden Abenteurern verteidigen sie die Region gegen Banditentum.",h="In Westfall hält die Volksmiliz gegen die Bruderschaft der Defias stand.",kw={"bruderschaft der defias","edwin van cleef","gryan starkmantel","mondbruch","volksmiliz","späherkuppe","sentinel tower","westfalls brigade"},ang={["class:Warrior"]="Als Krieger seht Ihr, wie Gryan Starkmantel und seine Beschützer an vorderster Front vorangehen. Gegen eine erdrückende Übermacht behelfen sie sich mit abgenutzten Klingen und notdürftigen Rüstungen.",["faction:Alliance"]="Als Held der Allianz seht Ihr, wie Westfalls Krise gefährliche Risse im Königreich offenlegt und zeigt, wie zerbrechlich der Frieden in seinen Kernlanden ist.",["race:Human"]="Als Mensch seht Ihr, wie Sturmwinds Landbevölkerung ihre Heimat verteidigt, wenn der königliche Hof die Augen verschließt."},sec={{t="Eine verlassene Region",b="Westfall ernährte einst das Königreich Sturmwind. Dann zog das Königreich seine Truppen ab und ließ die Bevölkerung wehrlos zurück. Die Bruderschaft der Defias breitete sich über die Ebenen aus, beschlagnahmte Familienhöfe, übernahm Eisenminen und erpresste örtliche Bauern. Ohne Aussicht auf königliche Verstärkung scharte der erfahrene Krieger Gryan Starkmantel Bürger und Soldaten im Ruhestand um sich, um die Volksmiliz zu gründen."},{t="Die Späherkuppe halten",b="Der Sentinel Tower auf der Späherkuppe ist der Stützpunkt der Miliz. Von dort aus patrouillieren Freiwillige mit spärlicher militärischer Ausrüstung und unregelmäßigem Nachschub auf den Hauptstraßen der Region. Gryan Starkmantel führt sie gegen die wachsenden Scharen von Wegelagerern, Dieben und Plünderern der Defias. Als das Rotkammgebirge um gegenseitigen Beistand bittet, muss die Miliz ablehnen. Schon eine Handvoll Männer zu entsenden könnte bedeuten, Westfall zu verlieren."},{t="Die Verschwörung aufdecken",b="Durch Aufklärung und Hilfe von außen erfährt die Volksmiliz, wie groß die Bedrohung durch die Defias ist. Die Bruderschaft ist mehr als eine Bande von Dieben auf dem Land. Sie steht unter Edwin van Cleef, dem ehemaligen Gildenmeister der Steinmetze, die Sturmwind wiederaufbauten. Von den Todesminen unter Mondbruch aus planen die Defias, das Königreich zu stürzen. Die bedrängte Miliz ist das einzige Hindernis zwischen der Hauptstadt und einem offenen Aufstand."}},faq={{q="Warum kämpft die Volksmiliz allein, ohne Sturmwinds Armee?",a="Sturmwind zog seine Truppen aus Westfall ab und ließ die Bevölkerung wehrlos zurück, und niemand auf dem Land hat erfahren, warum. Gryan Starkmantel scharte die Volksmiliz um sich, um zu verteidigen, was von dem Land übrig war.",al={"warum keine wache aus sturmwind","wo ist sturmwinds armee","warum wurde westfall aufgegeben"}},{q="Wer führt die Volksmiliz an?",a="Gryan Starkmantel, ein erfahrener menschlicher Veteran, gründete die Volksmiliz und führt sie an.",al={"wer führt westfalls brigade","anführer der miliz","gryan starkmantels rolle"}},{q="Wo liegt ihr Hauptquartier?",a="Die Volksmiliz hat ihren Stützpunkt auf der Späherkuppe, rund um den hohen steinernen Wachturm im Herzen von Westfall.",al={"stützpunkt der miliz","wo ist die späherkuppe","stützpunkt der miliz in westfall"}},{q="Kann die Miliz anderen bedrängten Regionen wie dem Rotkammgebirge helfen?",a="Nein. Als Magistrat Solomon aus Seenhain um militärische Reserven bat, musste Gryan Starkmantel ablehnen, weil die Miliz den Defias kaum noch standhielt.",al={"warum helfen sie seenhain nicht","solomons bitte an starkmantel"}},{q="Wer ist der Hauptfeind der Miliz?",a="Die Volksmiliz kämpft gegen die Bruderschaft der Defias, ein Verbrechersyndikat aus ehemaligen Steinmetzen, Schurken und Wegelagerern unter der Führung von Edwin van Cleef.",al={"gegen wen kämpfen sie","feind der miliz","feind der defias"}}},fx={e3ac0fe0={q="Woher kam die Westfall Brigade?",a="Es gibt keine Westfall Brigade in Westfall; die Verteidiger von Späherkuppe sind The People's Militia. Gryan Starkmantel versammelte dort lokale Bauern, Veteranen und einfache Bürger, nachdem The Defias Brotherhood Westfall eingenommen hatte und Sturmwind nicht eingriff, damit sie zu den Waffen greifen konnten, um ihre eigenen Häuser und Ackerflächen zu verteidigen.",al={"geschichte der westfall brigade","ursprung der westfall brigade","ursprung der peoples militia"}}},fp="16,259,18.383.0,21.378.0,25.408.1,68.209.0,31.84.0,36.106.0,58.163.0,41.136.1"}
P.entries["topic:wildhammer-clan"] = {n="Wildhammerklan",s="Im Hinterland hält der Wildhammerklan zwischen bewaldeten Gipfeln an seiner Freiheit fest. Vor Jahrhunderten aus Grim Batol vertrieben, machten die Zwerge Nistgipfel zu ihrer Heimat und lernten, wilde Greifen zu reiten. Sie sind weiterhin Freunde der Allianz und bereit, deren Himmel zu verteidigen.",h="Im Hinterland hält der Wildhammerklan zwischen bewaldeten Gipfeln an seiner Freiheit fest.",kw={"nistgipfel","falstad","grim batol","greif","hinterland","khardros","kurdran","sturmhämmer","wildhammer"},ang={["class:Hunter"]="Die Bindung, die Wildhammer-Bergsteiger mit wilden Greifen teilen, zeigt Tierbeherrschung, die auf lebenslanger Partnerschaft statt auf bloßer Herrschaft beruht.",["class:Shaman"]="Die Wildhammertradition kanalisiert rohe Sturmenergie durch mystische Hämmer und pflegt eine Verbindung zu elementarer Blitzkraft und zur Natur, die älter ist als die modernen kirchlichen Traditionen Eisenschmiedes.",["faction:Alliance"]="Die Allianz verdankt den Greifenreitern der Wildhämmer einen großen Teil ihrer Stärke am Himmel. Ihre blitzdurchdrungenen Reittiere halfen, während des Zweiten Krieges das Blatt gegen die roten Drachen der Horde zu wenden.",["race:Dwarf"]="Als Zwerg aus Eisenschmiede bist Du durch alte Schwüre mit den Wildhämmern verbunden. Sie bevorzugen windige Klippen und offene Himmel statt tiefer Minen, und ihr mutiger Umgang mit Sturmhämmern gebietet großen Respekt."},sec={{t="Verbannung aus Grim Batol",b="Vor dem Krieg der drei Hämmer lebten die Wildhämmer nahe Eisenschmiede. Als Hochkönig Modimus Ambossar starb, folgte ein Bürgerkrieg, und die siegreichen Bronzebeards erhoben Anspruch auf die Stadt. Than Khardros führte seinen Klan nach Norden und errichtete eine Festung in Grim Batol. Bald belagerten die besiegten Dunkeleisenzwerge die Festung.\n\nKhardros erschlug die Zauberin Modgud, doch ihr Fluch im Sterben verdarb den Berg und machte seine Hallen unbewohnbar. Die Wildhämmer lehnten eine Einladung ab, unter die Herrschaft der Bronzebeards zurückzukehren. Sie entschieden sich für ihre Freiheit und zogen nach Norden in die Wälder und felsigen Klippen des Hinterlands."},{t="Reiter des Sturms",b="Die Wildhämmer errichteten Nistgipfel im Hochland ihrer neuen Heimat. Anders als ihre Vettern unter der Erde nahmen sie den offenen Himmel und den lebendigen Fels an und gingen eine tiefe spirituelle Verbindung mit den einheimischen Greifen ein. In abgeschiedenen Volieren schmiedeten sie verzauberte Sturmhämmer und wurden zu Azeroths bester Luftkavallerie.\n\nWährend des Zweiten Krieges marschierte Kriegshäuptling Orgrim Schicksalshammer auf Quel'Thalas zu und griff Nistgipfel an. Oberster Kommandant Anduin Lothar und die Allianz kamen dem Klan zu Hilfe. Aus Dankbarkeit verpflichtete Hochthan Kurdran Wildhammer seine Greifenreiter der Koalition. Sie kämpften über Lordaeron und dem großen Meer gegen die versklavten roten Drachen der Horde."},{t="Bis zum Ende loyal",b="Als sich Das Dunkle Portal erneut öffnete, führte Kurdran Wildhammer seine Reiter mit der Expedition der Allianz nach Draenor. Er verzichtete auf seine Rückkehr, um den Riss zu versiegeln, und eine kolossale Statue im Tal der Helden in Sturmwind ehrt seine Tat. In Nistgipfel übernahm Hochthan Falstad das Kommando.\n\nDie menschlichen Königreiche gerieten später in Streit und zerfielen, doch die Wildhämmer blieben loyale Partner von König Terenas Menethil II. Während des Dritten Krieges fegte die Geißel über Lordaeron hinweg. Die Flieger der Wildhämmer stiegen erneut in den Himmel auf und kämpften, um verbündete Länder und unschuldige Flüchtlinge vor den wandelnden Toten zu schützen."}},faq={{q="Wo hat der Wildhammerklan derzeit seinen Sitz?",a="Der Wildhammerklan hat seinen Sitz in Nistgipfel im Hinterland, nördlich des Sumpflands und des Thandol-Übergangs.",al={"heimat der wildhämmer","wo leben die wildhämmer","standort der wildhämmer"}},{q="Warum leben die Wildhämmer nicht in Eisenschmiede?",a="Die Wildhämmer verloren nach dem Tod von Hochkönig Modimus Ambossar den Bürgerkrieg um Eisenschmiede gegen die Bronzebeards. Than Khardros führte den Klan nach Grim Batol, statt unter der Herrschaft der Bronzebeards zu leben.",al={"warum verließen die wildhämmer eisenschmiede","krieg der drei hämmer wildhämmer"}},{q="Was geschah mit ihrer Festung in Grim Batol?",a="Die Dunkeleisenzwerg-Zauberin Modgud belagerte Grim Batol während des Krieges der drei Hämmer. Than Khardros erschlug sie, doch ihre Zauberei verdarb die Hallen und machte den Berg unbewohnbar. So trieb sie den Klan ins Hinterland.",al={"warum ist grim batol verlassen","fluch von grim batol","modgud grim batol"}},{q="Wer führt den Wildhammerklan heute an?",a="Hochthan Falstad Wildhammer führt den Klan von Nistgipfel aus. Er übernahm das Kommando, nachdem Kurdran Wildhammer sich durch Das Dunkle Portal der Expedition der Allianz angeschlossen hatte.",al={"anführer der wildhämmer","hochthan wildhammer","wer herrscht über nistgipfel"}},{q="Wie schlossen sich die Wildhämmer der Allianz an?",a="Während des Zweiten Krieges griff Orgrim Schicksalshammer das Hinterland an, als er auf Quel'Thalas zumarschierte. Oberster Kommandant Anduin Lothar führte die Allianz bei der Verteidigung von Nistgipfel und schlug die Horde und die Waldtrolle zurück. Aus Dankbarkeit für ihre Hilfe schlossen sich die Wildhämmer der Allianz von Lordaeron an.",al={"warum gehören die wildhämmer zur allianz","geschichte der wildhämmer und der allianz"}},{q="Sind die Wildhammerzwerge eng mit Eisenschmiede verbündet?",a="Ja. Obwohl die Klans während des Krieges der drei Hämmer kämpften, vereinten sie sich gegen die Dunkeleisenzwerge. Sie errichteten das Tal der Könige in Loch Modan, um ihre Freundschaft zu ehren, und halten seitdem fest zusammen.",al={"beziehung zwischen bronzebeards und wildhämmern","verstehen sich eisenschmiede und wildhämmer"}}},fx={eadee6c6={q="Was ist der Wildhammer clan?",a="Der Wildhammer clan ist eines der drei großen Zwergenvölker Azeroths, bekannt für ihre enge Bindung zur Natur, ihre Unabhängigkeit und ihre furchtlose Meisterschaft in der Luft. Anders als ihre Cousins von den Bronzebärten, die unterirdische Hallen bevorzugen, leben die Wildhammer offen zwischen hohen Gipfeln und üppigen Wäldern. Weltweit bekannt als unvergleichliche Greifenreiter, ziehen sie mit mystischen, blitzgeladenen Sturmhämmern in den Himmel, um ihre Heimat zu verteidigen und ihren langjährigen Verbündeten zu helfen.",al={"wer sind die wildhammer","überblick über den wildhammer clan","wildhammerzwerge"}},f21b0698={q="Woher stammt der Wildhammer clan?",a="Vor langer Zeit lebten die Wildhammer in den Felsen und Ausläufern um Eisenschmiede unter Hochkönig Modimus Anvilmar. Nach seinem Tod brach der Bürgerkrieg des Krieges der Drei Hämmer aus. Von den siegreichen Bronzebärten aus Eisenschmiede verbannt, führte Than Khardros seinen Clan nach Norden, um die große Festung Grim Batol zu errichten. Nachdem sie eine erschütternde Belagerung durch die Dunkeleisenzwerge überlebt hatten, die Grim Batol verflucht und unbewohnbar hinterließ, wanderten die Wildhammer weiter nach Norden in Lordaeron und siedelten sich schließlich in den bewaldeten Bergen des Hinterland an.",al={"geschichte der wildhammer","ursprünge des wildhammer clans","ursprung des wildhammer clans"}}},fp="15,269,21.580.0,19.651.0,16.568.0,45.106.0,44.196.0,46.222.0,36.158.0,42.292.0,57.214.0"}
P.entries["topic:worgen"] = {n="Worg",s="Im Silberwald, im Eschental und im Dämmerwald jagen Worgen nun mit tierischer Schnelligkeit und unbezähmbarer Wut. Einst für Albträume aus einem anderen Reich gehalten, bleibt ihr Ursprung ungewiss.",h="Im Silberwald, im Eschental und im Dämmerwald jagen Worgen nun mit tierischer Schnelligkeit und unbezähmbarer...",kw={"arugal","pyrewood","sichel von elune","burg shadowfang","silberwald","ur","velinde starsong","worgen"},ang={["class:Druid"]="Worgen zeigen, wie gefährlich es ist, wilde Macht zu beschwören, ohne sie weise zu lenken. Ihre Ausbreitung in den Wäldern Kalimdors beunruhigt den Zirkel des Cenarius.",["class:Mage"]="Die Kirin Tor von Dalaran debattierten lange über die Forschung in Urs mystischen Abhandlungen. Arugals katastrophale Beschwörung bestätigte Urs Warnungen, dass diese Albtraumkreaturen niemals herbeigerufen werden sollten.",["race:NightElf"]="Für die Kaldorei bleiben Worgen ein beunruhigendes Rätsel. Sentinels entdecken die Bestien nun im Eschental und im Teufelswald.",["race:Undead"]="Im Silberwald kämpfen die Verlassenen gegen wilde Worgenrudel und Arugals verdrehte Kultisten um die Kontrolle über das Gebiet südlich der Ruinen von Lordaeron."},sec={{t="Geflüster und Volkssagen",b="Lange bevor Worgen in Lordaeron und Kalimdor auftauchten, erzählte man Volkssagen und Schauergeschichten von Wolfsmenschen. Ihr Ursprung bleibt ein Rätsel. Gelehrte, die sie erforscht haben, glauben, dass sie aus einem anderen Reich nach Azeroth kamen. Sowohl Erzmagier Arugal als auch die Sichel von Elune der Nachtelfen haben sie nachweislich herbeigerufen."},{t="Arugals Torheit",b="Während des Dritten Krieges überrannte die Geißel Lordaeron, und gefallene Magier der Kirin Tor erhoben sich als Untote. Erzmagier Arugal suchte eine Waffe, um Dalarans schwindende Reihen zu stärken. Mit verbotenen Forschungen des Dalaraner Magiers Ur durchdrang er den Schleier und beschwor Worgen in den Silberwald. Sie fielen über die untoten Eindringlinge her, doch Arugal konnte ihre Wut nicht zügeln. Die Bestien wandten sich gegen die Magier und verbreiteten ihren Fluch mit Fangzähnen und Klauen.\n\nWahnsinnig vor Schuld und Faszination nahm Arugal die Ungeheuer als seine Kinder an. Er bemächtigte sich des Stammsitzes von Baron Silberlein und benannte ihn in Burg Shadowfang um. Dort verfluchte er die Bewohner naher Dörfer zu monströser nächtlicher Knechtschaft."},{t="Die Sichel erwacht",b="Jenseits des Meeres in Kalimdor wollte die Nachtelfen-Sentinel Velinde Sternensang die verbliebenen dämonischen Überreste der Brennenden Legion aus dem Teufelswald tilgen. Sie entdeckte die Sichel von Elune und beschwor mit dem uralten Relikt Worgen gegen die dämonischen Satyrn.\n\nWährend die Kämpfe tobten, erkannte Velinde, dass die Sichel ihrer Kontrolle entglitten war. Worgen erschienen nun ohne ihre Zustimmung und drangen in die dunklen Wälder des Eschentals und darüber hinaus vor. Wilde Rudel streifen umher und verbreiten überall Schrecken, wohin ihre mondbeschienenen Jagden sie führen."}},faq={{q="Was sind Worgen?",a="Worgen sind wilde, aufrecht gehende wolfsartige Humanoide mit furchterregender Stärke, räuberischen Sinnen und dunkler Shadow Magic. Sie leben vor allem in abgelegenen Wäldern und Ruinen und jagen in Rudeln, angetrieben von unbezähmbarer tierischer Wut.",al={"was ist ein worgen","worgen-lore","wolfsmenschen"}},{q="Woher stammen die Worgen ursprünglich?",a="Niemand weiß mit Sicherheit, woher Worgen stammen. Sie scheinen aus einem anderen Reich zu kommen: Erzmagier Arugal beschwor sie von jenseits des Schleiers in den Silberwald, und die Sichel von Elune der Nachtelfen rief sie in Kalimdor herbei.",al={"ursprung der worgen","wer erschuf die worgen","wie wurden worgen erschaffen"}},{q="Wie kamen Worgen in den Silberwald?",a="Während des Dritten Krieges beschwor Erzmagier Arugal Worgen mithilfe der Forschungen des verstorbenen Dalaraner Magiers Ur. Er hoffte, sie würden die Kirin Tor im Kampf gegen die Geißel stärken, doch die Bestien wandten sich gegen alle.",al={"worgen im silberwald","warum sind worgen im silberwald","wer beschwor die worgen"}},{q="Wie wird man zum Worgen?",a="Worgen verbreiten ein übernatürliches Leiden. Ein Biss oder Kratzer eines aktiven Worgen infiziert Humanoide. Schließlich erliegen die Opfer wilden Trieben und werden zu Wolfsbestien, sofern sie nicht durch starke Willenskraft oder besondere Zauberei aufgehalten werden.",al={"worgenfluch","kann man zum worgen werden","worgenbiss"}},{q="Was ist die Sichel von Elune?",a="Die Sichel von Elune ist ein mächtiges Relikt der Nachtelfen. Sie gebietet auf tiefgreifende, unberechenbare Weise über Worgen und kann sie herbeirufen und aufwiegeln.",al={"sichel von elune","lore zur sichel von elune"}},{q="Wer ist Erzmagier Arugal?",a="Erzmagier Arugal war ein Erzmagier der Kirin Tor aus Dalaran. Nachdem er Worgen im Kampf gegen die Geißel beschworen hatte, verfiel er dem Wahnsinn und herrschte mit seinen monströsen Kindern über die heimgesuchten Ruinen von Burg Shadowfang.",al={"arugal","wer ist arugal"}},{q="Warum sind Worgen im Eschental und in Kalimdor?",a="Worgenrudel durchstreifen nun das Eschental und den Teufelswald, und die Sentinels von Darnassus versuchen noch immer herauszufinden, wie sie nach Kalimdor gelangten. Ihre Suche folgt der Spur der verschollenen Sentinel Velinde Sternensang und der Sichel von Elune.",al={"worgen im eschental","worgen in kalimdor","terrowulf"}}},fx={d99a4888={q="Warum sind Worgen feindselig gegenüber Reisenden?",a="Die meisten Worgen, denen Ihr begegnet, sind von wilder, urtümlicher Wut verzehrt. Der Fluch raubt Vernunft und Selbstbeherrschung und treibt die Befallenen in einen Rausch, in dem sie Außenstehende als Beute oder Bedrohungen ansehen, die in Stücke gerissen werden müssen. Selbst diejenigen, die dem wahnsinnigen Erzmagier Arugal folgen, betrachten Sterbliche als Feinde, die abgeschlachtet oder verflucht werden müssen, damit sie sich ihren Rudeln anschließen.",al={"warum greifen worgen an","sind worgen feindselig","warum sind worgen aggressiv"}},["92f4d7ca"]={q="Wer führt die Worgen an?",a="Die Worgen antworten keinem einzigen Meister, sondern sammeln sich in Rudeln unter mächtigen Figuren. Im Silberwald dienen viele dem Erzmagier Arugal in Burg Shadowfang, der sie in die Welt beschwor. Unabhängige Rudel streifen wild durch Lordaeron, Dämmerwald und Kalimdor und antworten nur ihrem Alpha oder ihren instinktiven Trieben.",al={"worgen anführer","wer kontrolliert die worgen","worgen meister"}},["52984533"]={q="Mit wem sind die Worgen verbündet?",a="Die Worgen haben keine umfassenden Allianzen. Im Silberwald antworten bestimmte Rudel dem abtrünnigen Erzmagier Arugal aus Burg Shadowfang. Ansonsten streifen diese wilden Bestien ungezügelt durch die Wildnis und greifen Geißel, Allianz und Verlassene unterschiedslos an. Sie dienen nur ihrem urtümlichen Hunger und den Anführern ihrer individuellen Rudel.",al={"verbündete der worgen","wem dienen worgen","worgen fraktionen"}},b6544cd9={q="Woher kamen die Worgen?",a="Ihre wahren Ursprünge sind unbekannt. Die Bestien scheinen aus einem anderen Reich zu stammen: Erzmagier Arugal beschwor sie während des Dritten Krieges von jenseits herbeigeführt nach Silberwald, und wie Rudel dazu kamen, die Wälder von Kalimdor zu durchstreifen, ist ein Mysterium, dem die Nachtelfen immer noch nachgehen.",al={"geschichte der worgen","hintergrundgeschichte der worgen","wie wurden worgen erschaffen"}}},fp="6,201,22.315.0,14.663.0,17.501.1,16.228.0,42.211.0,43.199.0,33.230.0,28.128.0,23.204.0,41.221.0"}
P.entries["topic:world-of-warcraft-forever"] = {n="World of Warcraft: Forever",s="World of Warcraft: Forever spielt im Jahr nach dem Dritten Krieg. Thralls Horde hat sich in Durotar niedergelassen, und ein Regent herrscht in Sturmwind für seinen jungen König. Die Verlassenen halten die Unterstadt. Die Welt reicht von den Skyborne der Insel Zephras über die umkämpften Flusslande und Shen'dralas bis zum heiligen Hyjal und zur Stadt Dalaran, die aus ihren Ruinen im Alteracgebirge wieder emporsteigt.",h="World of Warcraft: Forever spielt im Jahr nach dem Dritten Krieg.",kw={"klassenkombinationen","dalaran","darkspear islands","hyjal","flusslande","shen'dralas","skyborne","world of warcraft forever","wow forever","insel zephras"},ang={["race:Dwarf"]="Die Zwerge von Eisenschmiede beschreiten auch den Pfad des Schamanen und rufen sowohl das Licht als auch Stein und Sturm an.",["race:Skyborne"]="Euer Volk hat gerade erst begonnen, nach Azeroth zurückzukehren. Sowohl die Allianz als auch die Horde haben Skyborne in ihre Reihen aufgenommen.",["race:Undead"]="Manche Verlassene wirken noch immer als Paladine das Heilige Licht, obwohl es sie verbrennt. Tyrs Wacht hält die Bandarionfestung im Westen von Tirisfal."},sec={{t="Die Welt nach dem Dritten Krieg",b="Die Brennende Legion wurde am Hyjal zurückgedrängt, doch die Welt trägt die Wunden, die sie hinterlassen hat. Thralls Horde aus Orcs, Trollen und Tauren hat sich in Durotar und Mulgore niedergelassen. Die Verlassenen unter Sylvanas Windläufer haben sich ihnen aus den Ruinen von Lordaeron angeschlossen.\n\nIn Sturmwind herrscht Hochlord Bolvar Fordragon als Regent für den Knabenkönig Anduin Wrynn, während König Varian verschollen ist. Die Zwerge von Eisenschmiede, die verbannten Gnome und die Nachtelfen von Teldrassil stehen an der Seite der Allianz. Die Geißel hält noch immer die Pestländer."},{t="Die Skyborne",b="Die Skyborne oder Shen'dorei stammen von Nachtelfen ab, die gegen Prinz Tortheldrin von Eldre'Thalas rebellierten. Windgeister trugen ihre Insel, die Insel Zephras, in den Himmelswall, die Elementarebene der Luft, und die Skyborne entkamen mit ihr. Nach Zeitaltern dort wurden sie zu Hochelfen, und inzwischen werden immer mehr von ihnen mit blauer Haut geboren.\n\nDie Geister verschwanden vor Jahrhunderten, und die Insel Zephras zerfällt langsam. Die Skyborne blicken zurück nach Azeroth. Ihre Luftschiffe erreichen das Alteracgebirge nahe Dalaran und das Himmelsschauerplateau in Mulgore. Sie kämpfen sowohl für die Allianz als auch für die Horde."},{t="Länder zum Erkunden",b="Die Insel Zephras schwebt im Himmelswall und ist die Heimat der Skyborne. Östlich der Brennenden Steppe liegen die Flusslande, eine alte Grenzregion Sturmwinds, die im Ersten Krieg verloren ging. Die Loyalisten in Burg Farholde halten den Wildnissen, Außenposten der Horde und dem Schattenhammer in Sonnengrund stand.\n\nShen'dralas ist ein zerklüftetes Grenzland zwischen Desolace, Feralas und Mulgore, umkämpft von Zentauren, Quilboar und Ausgestoßenen. Hyjal, heilig für die Nachtelfen, trägt noch immer die Narben von Archimondes Niederlage. Im Alteracgebirge haben die Kirin Tor Dalarans Schild gesenkt und bauen ihre Stadt wieder auf. Vor der Küste Kalimdors kämpfen Horde und Allianz um die Darkspear Islands."},{t="Dungeons und Schlachtzüge",b="Gefahren lauern unter Städten und in den entlegensten Winkeln der Welt. Tief unter Eisenschmiede liegt die Halle der Thanen, über der Unterstadt die heimgesuchten Ruinen von Lordaeron. Eine Ausgrabungsstätte befindet sich im Sumpfland, ebenso wie die Stadt Dalaran selbst.\n\nWeiter entfernt liegen die Versunkene Stadt im Schlingendorntal, die Feste Krol'dok in den Flusslanden, das Gefängnis Alcaz in den Düstermarschen, die Schwarzschlundfeste in Azshara und die Terrasse des Formers im Krater von Un'Goro. Auf Hyjal stellen die Barrow Deeps und der Hyjal Summit die mächtigsten Kriegerscharen auf die Probe."},{t="Wer welchen Pfad beschreitet",b="Krieger gibt es aus jedem Volk. Paladine sind Menschen, Zwerge oder Verlassene, während Schamanen Orcs, Tauren, Trolle, Zwerge oder Skyborne der Horde sind. Priester sind Menschen, Zwerge, Gnome, Nachtelfen, Trolle oder Verlassene. Magier sind Menschen, Gnome, Orcs, Trolle, Verlassene oder Skyborne der Allianz.\n\nHexenmeister sind Menschen, Gnome, Orcs, Trolle oder Verlassene. Jäger sind Menschen, Zwerge, Nachtelfen, Orcs, Tauren, Trolle oder Skyborne. Schurken gibt es aus jedem Volk außer den Tauren. Druiden sind Nachtelfen, Tauren oder Skyborne."}},faq={{q="Wann spielt World of Warcraft: Forever?",a="World of Warcraft: Forever spielt im Jahr nach dem Dritten Krieg, nachdem die Verlassenen die Unterstadt beansprucht haben. Thrall führt die Horde von Orgrimmar aus. Hochlord Bolvar Fordragon ist Regent von Sturmwind für den Knabenkönig Anduin, und die Geißel hält noch immer die Pestländer.",al={"wann spielt wow forever","wow forever zeitleiste","in welchem jahr spielt wow forever","wann spielt forever"}},{q="Welche Länder kann ich in WoW Forever erkunden?",a="Ihr könnt die Insel Zephras erkunden, die schwebende Heimat der Skyborne im Himmelswall, sowie die alte Grenzregion Sturmwinds, die Flusslande. Shen'dralas liegt zwischen Desolace, Feralas und Mulgore, während Hyjal den Nachtelfen heilig ist. Dalaran erhebt sich im Alteracgebirge erneut, und Horde und Allianz kämpfen um die Darkspear Islands.",al={"was ist neu in wow forever","was ist neu in forever","neue gebiete in wow forever","wow forever gebiete","was gibt es in wow forever"}},{q="Wer sind die Skyborne?",a="Die Skyborne sind Hochelfen, die von Nachtelfen abstammen, die vor Zeitaltern aus Eldre'Thalas flohen und auf der Insel Zephras im Himmelswall lebten, der Elementarebene der Luft. Während ihre Insel zerfällt, blicken sie zurück nach Azeroth und kämpfen für die Allianz und die Horde.",al={"skyborne","shen'dorei","neues volk wow forever"}},{q="Wo liegt Dalaran?",a="Dalaran liegt am Ufer des Lordameresees im Alteracgebirge. Archimonde zerstörte die Stadt im Dritten Krieg. Die Kirin Tor errichteten einen Schild über ihren Ruinen und haben ihn nun gesenkt, während sie die Stadt wieder aufbauen.",al={"dalaran wow forever","wird dalaran wieder aufgebaut","dalaran alterac"}},{q="Welche Dungeons und Schlachtzüge gibt es?",a="Zu den Dungeons gehören die Halle der Thanen unter Eisenschmiede, die Ruinen von Lordaeron über der Unterstadt, eine Ausgrabungsstätte im Sumpfland und die Stadt Dalaran. Weitere sind die Versunkene Stadt im Schlingendorntal, die Feste Krol'dok in den Flusslanden, das Gefängnis Alcaz in den Düstermarschen, die Schwarzschlundfeste in Azshara und die Terrasse des Formers im Krater von Un'Goro. Die Schlachtzüge sind die Barrow Deeps und der Hyjal Summit auf Hyjal sowie Onyxias Hort in den Düstermarschen.",al={"wow forever dungeons","wow forever schlachtzüge","neue dungeons in wow forever","neue schlachtzüge"}},{q="Welche Klassen kann jedes Volk spielen?",a="Menschen können Krieger, Paladine, Jäger, Schurken, Priester, Magier oder Hexenmeister sein. Zwerge können Krieger, Paladine, Jäger, Schurken, Priester oder Schamanen sein. Nachtelfen können Krieger, Jäger, Schurken, Priester oder Druiden sein. Gnome können Krieger, Schurken, Priester, Magier oder Hexenmeister sein.\n\nOrcs können Krieger, Jäger, Schurken, Schamanen, Magier oder Hexenmeister sein. Verlassene können Krieger, Paladine, Schurken, Priester, Magier oder Hexenmeister sein. Tauren können Krieger, Jäger, Schamanen oder Druiden sein. Trolle können Krieger, Jäger, Schurken, Priester, Schamanen, Magier oder Hexenmeister sein.\n\nSkyborne können Krieger, Jäger, Schurken oder Druiden sein. Skyborne der Allianz können außerdem Magier sein, und Skyborne der Horde können außerdem Schamanen sein.",al={"volk klassen kombinationen","welche klasse kann ich spielen","können untote paladine sein","untoter paladin","zwerg schamane","gnom priester","menschenjäger","orc magier","troll hexenmeister","skyborne klassen"}}},fp="26,376,29.535.0,12.561.0,16.657.0,18.526.0,20.468.0,39.270.0,40.336.0,21.257.0,17.215.0,34.463.0,31.671.0"}
P.entries["zone:alterac"] = {n="Alteracgebirge",s="Im Alteracgebirge bieten zerklüftete Gipfel Ogern, Gesetzlosen und den Überresten arkaner Macht Zuflucht. Einst Heimat des Menschenkönigreichs Alterac und der gelehrten Magokratie von Dalaran, lockt das Hochland Reisende aus den Siedlungen des nahen Vorgebirges und der wiederaufgebauten Stadt an.",h="Im Alteracgebirge bieten zerklüftete Gipfel Ogern, Gesetzlosen und den Überresten arkaner Macht Zuflucht.",kw={"alterac","crushridge","dalaran","perenolde","rabenholdt","strahnbrad","syndikat","das oberland"},ang={["class:Mage"]="Als Magier könnt Ihr durch Dalarans wiederaufgebaute Straßen wandeln, wo arkane Strömungen nachhallen und Magier der Kirin Tor arbeiten. Die Stadt bleibt das verwüstete Herz menschlicher Zauberkunst.",["class:Rogue"]="Als Schurke könnt Ihr das Rabenholdtanwesen entdecken, verborgen in Alteracs östlichen Klippen. Lord Jorach Rabenholdt wacht über Aufträge für Elitekräfte, Schlossknackübungen und die Geheimnisse der Gilde.",["faction:Alliance"]="Als Reisender der Allianz begegnet Ihr Crushridge-Ogern und Gesetzlosen des Syndikats im ehemaligen Königreich.",["faction:Horde"]="Als Mitglied der Horde findet Ihr den Frostwolfklan in den abgeschiedenen Bergen. Verlassene-Agenten aus Tarrens Mühle nehmen Oger und Gesetzlose des Syndikats ins Visier.",["profession:Herbalism"]="Als Kräuterkundiger findet Ihr Winterbiss in Alteracs eisigen Klippen, seinem einzigen natürlichen Lebensraum. Das Kraut ist eine unverzichtbare Zutat für wirksame Mixturen gegen Kälte."},sec={{t="Das gefallene Königreich",b="Während des Zweiten Krieges zählte Alterac zu den Sieben Königreichen der Menschheit. König Aiden Perenolde verriet die Allianz von Lordaeron und schloss sich der Alten Horde an, um sein Reich zu retten. Sein Verrat wurde aufgedeckt und niedergeschlagen, und das Königreich zerfiel in umstrittene Grenzgebiete. Nach der Auflösung Alteracs brachte der Dritte Krieg neues Grauen. Seine prächtige steinerne Hauptstadt liegt heute in Trümmern.\n\nDie Crushridge-Oger besetzen unter der Führung von Mug'thol die Ruinen von Alterac. Alteracs überlebende menschliche Adlige gründeten das Syndikat, eine ruchlose Verbrecherbande. Mit Gewalt kämpfen sie darum, ihre verlorenen Ländereien zurückzuerobern."},{t="Die wiederaufgebaute Stadt",b="Am westlichen Rand des Gebirges bauen Dalarans überlebende Magier neben dem Lordameresee wieder auf. Der Dämonenlord Archimonde verwüstete den großen Stadtstaat während des Dritten Krieges. Seine Magier errichteten eine gewaltige, undurchsichtige violette Kuppel über den Ruinen, doch der Schild wurde inzwischen entfernt. Die Kirin Tor bauen ihr Sanktuarium nun unter freiem Himmel wieder auf. Erzmagier Ansirem Runenweber ist in der Violet Citadel anzutreffen."},{t="Grenzland im Konflikt",b="Süderstade und Tarrens Mühle dienen als Ausgangspunkte für Reisen in die Gipfel. Yetis, Berglöwen und Syndikat-Schergen streifen hier umher. Unterhalb der Schneegrenze tobt ein größerer Konflikt.\n\nTief in den Gebirgspässen kämpfen die zwergische Stormpikegarde und der zurückgezogen lebende Frostwolfklan der Orks um das Alteractal. Sie streiten um uralte Gebiets- und Schürfrechte."}},faq={{q="Was geschah mit dem Königreich Alterac?",a="Während des Zweiten Krieges verriet König Aiden Perenolde die Allianz, um der Horde zu helfen. Lordaeron und Stromgarde schlugen den Aufstand nieder und besetzten das Land. Als die Geißel während des Dritten Krieges Lordaeron überrannte, versank Alterac im Chaos, und Crushridge-Oger nahmen die zerstörte Hauptstadt ein.",al={"warum ist alterac zerstört","was geschah mit perenolde","alterac königreich hintergrundgeschichte"}},{q="Wer ist das Syndikat?",a="Das Syndikat ist eine Bande von Gesetzlosen, die aus dem enteigneten Adel Alteracs hervorging. Ehemalige Mitglieder der Königsfamilie Alteracs wie Lord Aliden Perenolde führen die Bande an. Meuchelmörder, Straßenräuber und in Ungnade gefallene Lords terrorisieren die umliegenden Lande und vertreiben Rivalen, während sie um die Rückeroberung ihrer angestammten Gebiete kämpfen.",al={"wer ist das syndikat","warum gibt es menschliche banditen in alterac","hintergrundgeschichte des syndikats"}},{q="Was geschah mit Dalarans leuchtender Kuppel?",a="Nachdem Archimonde Dalaran während des Dritten Krieges verwüstet hatte, errichteten die überlebenden Kirin Tor einen schützenden magischen Schild über den Ruinen. Der Schild wurde inzwischen entfernt, und die Stadt wird unter freiem Himmel wiederaufgebaut. Erzmagier Ansirem Runenweber ist in der Violet Citadel anzutreffen.",al={"violette kuppel alterac","was ist die violette blase","dalarans schild"}},{q="Wo finde ich Flugrouten oder sichere Gasthäuser in Alterac?",a="Süderstade und Tarrens Mühle im Vorgebirge des Hügellands sind die üblichen Ausgangspunkte für Reisen in die verschneiten Gipfel. Dalaran am westlichen Rand steht Reisenden der Allianz offen, während die Kirin Tor die Stadt wiederaufbauen, doch dort gibt es keinen Flugmeister. Die Horde ist den Kirin Tor verhasst und wird in der Stadt sofort angegriffen.",al={"flugroute alterac","gasthaus alterac","questzentrum alterac"}},{q="Was ist das Alteractal?",a="Das Alteractal ist ein abgelegenes, verschneites Tal, um das die zwergische Stormpikegarde und der Frostwolfklan der Orks kämpfen. Die Stormpikes kamen zu einer archäologischen Expedition und lösten damit einen umfassenden Gebietskrieg mit den Frostwölfen aus. Die Frostwölfe hatten seit ihrer Verbannung im Ersten Krieg friedlich im Tal gelebt.",al={"eingang zum alteractal","frostwolf gegen stormpike","wo liegt das alteractal"}},{q="Was ist das Rabenholdtanwesen?",a="Das Rabenholdtanwesen liegt verborgen in einer abgelegenen Bergfalte östlich der Hauptstraße. Lord Jorach Rabenholdt führt das abgeschottete Gildenhaus der Liga der Assassinen, einen Übungsplatz und Zufluchtsort für geschickte Schurken aus ganz Azeroth.",al={"wo liegt rabenholdt","assassinenanwesen alterac","diebesgilde alterac"}}},fp="17,268,18.592.0,19.393.0,21.359.0,40.283.0,22.287.0,40.271.0,54.308.0,23.313.0,25.231.0"}
P.entries["zone:alteracvalley"] = {n="Alteractal",s="Im Alteractal kämpfen Frostwölfe und Stormpike-Zwerge um die Kontrolle über den Schnee. Die Zwerge suchen nach Reichtümern und Relikten, die sie mit ihren Ahnen verbinden sollen, während die Frostwölfe sie vertreiben wollen. Beide Seiten kämpfen sich durch Türme und Friedhöfe bis zum gegnerischen General vor: Vanndar Sturmlanze in Dun Baldar oder Drek'Thar in der Burg Frostwolf.",h="Im Alteractal kämpfen Frostwölfe und Stormpike-Zwerge um die Kontrolle über den Schnee.",kw={"alteractal","schlachtfeld","frostwolfklan","stormpikegarde","drek'thar","vanndar sturmlanze","dun baldar","burg frostwolf","durotan","thrall"},ang={["faction:Alliance"]="Soldaten der Allianz marschieren mit der Stormpikegarde, um die Minen und Geheimnisse des Tals gegen die Frostwolf-Horde zu verteidigen.",["faction:Horde"]="Der Schnee des Alteractals liegt in der Heimat des Kriegshäuptlings. Jeder Kämpfer der Horde verteidigt dort den Ort, an dem Thrall sein Volk fand.",["race:Dwarf"]="Die Stormpike-Zwerge sehen in den Relikten des Tals eine Verbindung zu ihren Ahnen. Kein Orc-Klan wird sie von ihren Ausgrabungen vertreiben.",["race:Orc"]="Die Frostwölfe sind Durotans Klan und Thralls eigenes Blut. Für einen Orc bedeutet die Verteidigung ihres Tals, das Herz der neuen Horde zu verteidigen."},sec={{t="Heimat der Frostwölfe",b="Gul'dan verbannte Durotans Frostwolfklan, weil er sich ihm widersetzte, und die Orcs fanden Zuflucht in diesem kalten Tal. Sie machten es zu ihrer Heimat. Lange danach fand der junge Thrall hier das Volk seines Vaters und lernte vom Ältesten Drek'Thar die Wege des Schamanen.\n\nThrall führt nun die Horde in Kalimdor an. Viele Frostwölfe leben unter Drek'Thars Führung weiterhin im Tal und verteidigen ihre Heimat erbittert."},{t="Die Stormpike-Expedition",b="Unter dem Befehl von Vanndar Sturmlanze ist die Stormpikegarde eine Expedition von Zwergen aus Eisenschmiede, die in der nördlichen Festung Dun Baldar stationiert ist. Sie kamen wegen der Minen des Tals und der Relikte, die sie mit ihren Ahnen verbinden sollen.\n\nMit Bunkern und Türmen haben sie sich eingegraben und halten mit sturem Stolz stand. Die Frostwölfe nennen sie Eindringlinge; die Zwerge beanspruchen die Geheimnisse des Tals, weil sie sie ihrer Ansicht nach zuerst entdeckt haben."},{t="Krieg im Schnee",b="Im Kampf um das Alteractal stehen sich zwei Heere gegenüber. Kämpfer stürmen Türme und Bunker, nehmen Friedhöfe ein und beanspruchen die Minen des Tals für ihre Seite.\n\nJede Seite muss zum gegnerischen General durchbrechen und ihn zu Fall bringen. Die Horde steht Vanndar Sturmlanze in Dun Baldar gegenüber; die Allianz kämpft gegen Drek'Thar in der Burg Frostwolf."}},faq={{q="Was ist das Alteractal?",a="Verborgen im Alteracgebirge liegt das Alteractal, die Heimat der Frostwolf-Orcs. Dort führen der Frostwolfklan und die Stormpike-Zwerge einen offenen Krieg und wollen jeweils den gegnerischen General besiegen.",al={"was ist das alteractal","schlachtfeld alteractal","alteractal"}},{q="Warum kämpfen die Frostwölfe im Alteractal?",a="Das Tal ist die Heimat der Frostwölfe, wo sich Durotans Klan im Exil niederließ und Thrall sein Volk fand. Sie lassen die Stormpike-Zwerge dort nicht graben, und die Horde kämpft an ihrer Seite, um die Expedition zu vertreiben.",al={"frostwolfklan","interessen der horde im alteractal","warum kämpft die horde im alteractal"}},{q="Warum sind die Stormpike-Zwerge im Alteractal?",a="Die Stormpike-Expedition kam aus Eisenschmiede, um die Reichtümer des Tals abzubauen und Relikte zu suchen, die sie mit ihren Ahnen verbinden sollen. Unter Vanndar Sturmlanzes Führung halten sie von Dun Baldar aus an ihrem Anspruch fest, während die Allianz an ihrer Seite kämpft.",al={"stormpikegarde","interessen der allianz im alteractal","stormpike-expedition"}},{q="Wer ist Drek'Thar?",a="Drek'Thar ist der Schamanenälteste des Frostwolfklans und lehrte den jungen Thrall die Wege des Schamanen. Er befehligt die Frostwölfe von der Burg Frostwolf aus, und die Allianz muss ihn besiegen, um die Schlacht zu gewinnen.",al={"drek'thar","general der frostwölfe","schamanenältester der frostwölfe"}},{q="Wer ist Vanndar Sturmlanze?",a="Vanndar Sturmlanze ist ein Zwerg und der Befehlshaber der Stormpikegarde. Er führt die Expedition von Dun Baldar aus an, und die Horde muss ihn besiegen, um die Schlacht zu gewinnen.",al={"vanndar sturmlanze","general der stormpikegarde","dun baldar"}},{q="Wie gewinnt man die Schlacht im Alteractal?",a="Jedes Heer kämpft sich durch die Türme, Bunker und Friedhöfe des Gegners bis zu dessen Festung vor. Die Schlacht endet, wenn eine Seite den gegnerischen General besiegt: Vanndar Sturmlanze in Dun Baldar oder Drek'Thar in der Burg Frostwolf.",al={"ziele im alteractal","wie gewinnt man im alteractal","generäle des alteractals"}}},fp="14,352,23.380.0,24.395.0,15.327.0,23.208.0,47.222.0,48.239.0,17.204.0,25.156.0,40.214.0"}
P.entries["zone:arathi"] = {n="Arathihochland",s="In Arathi hinterlässt das zerstörte Stromgarde das Hochland an mehreren Fronten im Krieg. Die Überreste des Königreichs, die Horde, Adlige des Syndikats und einfallende Oger kämpfen um die uralte Wiege des Imperiums von Arathor im Südosten Lordaerons.",h="In Arathi hinterlässt das zerstörte Stromgarde das Hochland an mehreren Fronten im Krieg.",kw={"arathi","arathihochland","arathor","boulderfist","galen trollbane","hammerfall","die zuflucht","stromgarde","syndikat","thandol-übergang","thoradinswall"},ang={["class:Warrior"]="Als Krieger folgt Ihr der gefeierten Kampftradition Stromgardes. Die rauen Schlachtfelder sind eine ehrwürdige Prüfung im Waffenkampf.",["faction:Horde"]="Als Mitglied der Horde kennt Ihr Hammerfall als heiligen Boden. Der Ort ehrt Orgrim Schicksalshammers Opfer, mit dem er ein versklavtes Volk aus der Internierung befreite.",["profession:Mining"]="Als Bergarbeiter findet Ihr in den zerklüfteten Kämmen des Arathihochlands Eisen und Mithril. Die Schlucht der Trockenstoppel ist die einzige bekannte Quelle für geringes Blutsteinerz.",["race:Human"]="Als Mensch teilt Ihr Eure Wurzeln mit jedem Königreich des Imperiums von Arathor. Zu sehen, wie dessen uralter Sitz zerbrochen ist und von Ogern und Dieben überrannt wird, ist ein schwerer kultureller Verlust."},sec={{t="Wiege der Menschheit",b="Die trockenen Ebenen des Arathihochlands bildeten einst das Herz eines vereinten Menschenreichs. Vor Jahrtausenden sammelte König Thoradin die zersplitterten Stämme unter dem Banner der Arathi und errichtete ihre Hauptstadt Strom an einem leicht zu verteidigenden Ort. Während der Trollkriege schloss die Menschheit hier ihren Pakt mit den Hochelfen und erlernte die arkanen Künste, um die Amani zurückzudrängen.\n\nSpäter breiteten sich Adelsgeschlechter nach Norden bis nach Lordaeron und nach Süden in Richtung Sturmwind aus. Die kaiserliche Garde blieb zurück und gründete Stromgarde, ein kriegerisches Königreich, das jahrhundertelang die Grenze gegen Waldtrolle verteidigte."},{t="Ein zerschlagenes Königreich",b="Unter König Thoras Trollbane half Stromgarde der Allianz während des Zweiten Krieges bei der Verteidigung. Der Dritte Krieg und seine Folgen zerschlugen das Königreich. Es blieb von den schlimmsten Auswirkungen der Seuchenplage der Geißel verschont, doch der rätselhafte Tod von König Thoras stürzte das Reich ins Chaos. Boulderfist-Oger kamen aus den Hügeln herab, während Adlige aus Alterac im Syndikat weite Gebiete der Burg Stromgarde an sich rissen.\n\nPrinz Galen Trollbane und seine Getreuen halten nun einen kleinen Teil der Stadt und ihren Zufluchtsort bei der Zuflucht. Trotz der gewaltigen Übermacht führen sie einen erbitterten Guerillakrieg."},{t="Der Krieg um das Hochland",b="Im Arathihochland kämpfen Kräfte mit unterschiedlichen Ansprüchen um die Vorherrschaft. Im Nordosten errichtete die Horde Hammerfall in einem verlassenen Internierungslager der Menschen und benannte es nach Kriegshäuptling Orgrim Schicksalshammer. Der Außenposten sichert ihre nördlichen Besitzungen und schützt ihre Verbündeten in Hillsbrad. Die Witherbarktrolle sinnen auf Rache an den Menschen, die sie einst verfolgten, während die Arguswacht die Besetzung durch das Syndikat lenkt.\n\nIm Zentrum des Plateaus halten die uralten Kreise der Bindung Elementare fest. Sie bändigen eine alte Macht, die unter dem Stein begraben liegt."}},faq={{q="Was geschah mit Burg Stromgarde?",a="Nach dem Tod von König Thoras Trollbane erfasste ein Aufruhr Stromgarde, während die Angreifer näher rückten. Boulderfist-Oger eroberten die äußeren Bezirke, während das Syndikat das Heiligtum der Burg einnahm. Prinz Galen Trollbane und seine schwindende Garnison halten eine befestigte Ecke und kämpfen um ihre Hauptstadt.",al={"warum ist stromgarde zerstört","wer kontrolliert stromgarde","zustand von stromgarde"}},{q="Was ist Hammerfall?",a="Hammerfall ist ein Außenposten der Horde in den Überresten eines menschlichen Internierungslagers, in dem Orcs nach dem Zweiten Krieg festgehalten wurden. Sein Name ehrt den ehemaligen Kriegshäuptling Orgrim Schicksalshammer, der bei einem Feldzug zur Befreiung der Gefangenen aus Lagern in ganz Lordaeron fiel.",al={"hordenstützpunkt im arathihochland","geschichte von hammerfall","warum heißt es hammerfall"}},{q="Wo ist die Allianz im Arathihochland aktiv?",a="Soldaten der Allianz und Verteidiger von Stromgarde operieren von der Zuflucht aus, einer natürlich befestigten Schlucht im Zentrum des Hochlands. Von dort aus greifen sie an, um Burg Stromgarde zurückzuerobern und Oger sowie Trolle zurückzudrängen.",al={"allianzstützpunkt im arathihochland","die zuflucht","wo sind die menschen von stromgarde"}},{q="Was sind die Steinkreise in den Ebenen?",a="Die Inneren, Äußeren, Östlichen und Westlichen Kreise der Bindung sind uralte magische Siegel, die von abtrünnigen Elementaren bewacht und instand gehalten werden. Sie sperren ein unbekanntes, urzeitliches Wesen tief unter dem Hochland ein.",al={"kreise der bindung","elementare im arathihochland","steinkreise"}},{q="Wie gelangt Ihr ins Arathihochland?",a="Aus dem Norden und Westen überquert Ihr den Durchbruch in Thoradinswall vom Vorgebirge des Hügellands aus. Aus Khaz Modan im Süden führt Euch die Zwergenbrücke des Thandol-Übergangs über die Schlucht zwischen dem Hochland und dem Sumpfland.",al={"zum arathihochland gelangen","wie kommt man ins arathihochland","zugang zum arathihochland"}},{q="Was treibt das Syndikat im Arathihochland?",a="Das Syndikat besteht aus verbannten Adligen aus Alterac, die durch die Plünderung gefallener Reiche neue Gebiete erobern wollen. Im Arathihochland haben sie große Teile der Burg Stromgarde und nahegelegene Bauernhöfe eingenommen, darunter den Nordhof.",al={"warum ist das syndikat im arathihochland","syndikat in stromgarde","wer führt das syndikat hier an"}}},fp="16,232,18.553.0,19.544.0,25.539.1,33.281.0,19.247.0,42.214.0,45.192.0,38.235.0,38.202.1"}
P.entries["zone:arathibasin"] = {n="Arathibecken",s="Im Arathibecken kämpfen der Bund von Arathor und die Entweihten um den Reichtum des Tals. Der Bund will Arathors verlorene Ländereien für Sturmwind zurückerobern, während die Verlassenen die Menschen von ihren zwergischen Verbündeten im Süden abschneiden wollen. Sein Bauernhof, seine Ställe, sein Sägewerk, seine Schmiede und seine Goldmine nähren den Krieg.",h="Im Arathibecken kämpfen der Bund von Arathor und die Entweihten um den Reichtum des Tals.",kw={"arathibecken","schlachtfeld","bund von arathor","entweihte","varimathras","bauernhof","ställe","sägewerk","schmiede","goldmine"},ang={["faction:Alliance"]="Jeder Stützpunkt, den der Bund hält, ist ein zurückerobertes Stück Land von Arathor, dessen Getreide und Eisen für Sturmwinds Soldaten bestimmt sind.",["faction:Horde"]="An der Seite der Entweihten entzieht die Horde den Menschen dringend benötigte Ressourcen und hält sie von den Zwergen im Süden abgeschnitten.",["race:Human"]="Diese Bauernhöfe ernährten Stromgarde einst über Generationen hinweg. Als Mensch seht Ihr im Becken eine Heimat, die es zurückzuerobern gilt, keine Beute.",["race:Undead"]="Die Verlassenen erinnern sich an die Königreiche der Lebenden, die sie verstoßen haben. Als einer der Ihren mögt Ihr es als kalte und angemessene Rache ansehen, Arathors Erben das Becken zu entreißen."},sec={{t="Die Vorratskammer Arathors",b="Lange vor dem Dritten Krieg versorgten die Felder, Mühlen und Minen des Arathibeckens Stromgarde, den Erben des alten Arathor. Als Lordaeron fiel und Stromgarde zerfiel, blieb das Tal fast unverteidigt zurück, obwohl seine Gehöfte und Werkstätten noch standen.\n\nWer sie heute hält, verfügt über Getreide, Holz, Eisen und Gold. Diese Vorräte halten eine Armee im Feld und machen dieses ruhige Tal zu einem der umkämpftesten Orte im Hochland."},{t="Der Bund und die Entweihten",b="Der Bund von Arathor ist eine Kompanie der Allianz, gebildet aus den Überlebenden von Stromgarde und ihren Freunden. Unterstützt von Sturmwind, operiert er von der Zuflucht aus und hat geschworen, die Ländereien zurückzuerobern, die seine Vorfahren aufgebaut haben.\n\nDie Entweihten sind die Antwort der Verlassenen: abgehärtete Truppen aus der Unterstadt unter dem wachsamen Auge von Varimathras. Sie kämpfen an der Seite der Horde in Hammerfall. Ihr Ziel ist es, die Reichtümer des Beckens an sich zu bringen und die Straße zwischen den Menschen im Norden und den Zwergen im Süden abzuschneiden."},{t="Das Becken halten",b="Fünf Stützpunkte entscheiden die Schlacht: der Bauernhof, die Ställe, das Sägewerk, die Schmiede und die Goldmine. Jede Seite eilt herbei, um ihr Banner über ihnen zu hissen und zu verteidigen, was sie einnimmt. Jeder gehaltene Stützpunkt vergrößert ihren Ressourcenvorrat.\n\nAngreifer schleichen zwischen den Stützpunkten umher, um einen einzunehmen, während der Feind andernorts beschäftigt ist. Die Seite, die zuerst genügend Ressourcen sammelt, gewinnt das Becken für eine Weile."}},faq={{q="Was ist das Arathibecken?",a="Das Arathibecken ist ein Tal im Arathihochland, in dem der Bund von Arathor und die Entweihten der Verlassenen um die Vorherrschaft kämpfen. Sein Bauernhof, seine Ställe, sein Sägewerk, seine Schmiede und seine Goldmine liefern Ressourcen für den Krieg.",al={"was ist das arathibecken","arathibecken schlachtfeld","ab"}},{q="Wer ist der Bund von Arathor?",a="Der Bund von Arathor ist eine Kompanie der Allianz aus Überlebenden von Stromgarde und ihren Verbündeten. Unterstützt von Sturmwind und in der Zuflucht stationiert, kämpft er darum, Arathors verlorene Ländereien und die Reichtümer des Beckens zurückzuerobern.",al={"bund von arathor","allianz im arathibecken","arathor bund"}},{q="Wer sind die Entweihten?",a="Die Entweihten sind Elitetruppen der Verlassenen unter dem Schreckenslord Varimathras, dem Stellvertreter von Lady Sylvanas. Sie kämpfen an der Seite der Horde in Hammerfall, um die Ressourcen des Beckens zu gewinnen und die Verbindung zwischen den Menschen im Norden und ihren zwergischen Verbündeten zu kappen.",al={"die entweihten","verlassene im arathibecken","entweihte varimathras"}},{q="Warum kämpfen die Allianz und die Verlassenen um das Arathibecken?",a="Die Bauernhöfe, Mühlen und Minen des Beckens können eine Armee ernähren und bewaffnen. Für den Bund ist seine Rückeroberung ein Schritt zur Rückgewinnung von Arathors Ländereien; für die Entweihten bedeutet sie, den Menschen Ressourcen vorzuenthalten und sie von ihren zwergischen Verbündeten im Süden abzuschneiden.",al={"was im arathibecken auf dem spiel steht","warum um das arathibecken kämpfen","arathibecken krieg"}},{q="Wie wird die Schlacht im Arathibecken gewonnen?",a="Beide Seiten kämpfen darum, die fünf Stützpunkte des Beckens einzunehmen und zu halten: den Bauernhof, die Ställe, das Sägewerk, die Schmiede und die Goldmine. Jeder liefert seiner Seite Ressourcen, und wer zuerst genug sammelt, gewinnt.",al={"arathibecken ziele","arathibecken ressourcen","wie das arathibecken gewinnen"}}},fp="12,307,21.422.0,27.477.0,17.392.0,21.209.0,30.203.0,21.252.0,61.253.0,38.195.0"}
P.entries["zone:ashenvale"] = {n="Eschental",s="Die heiligen Wälder des Eschentals sind zum Schlachtfeld geworden, seit die Horde Holz für Orgrimmar schlägt. Zwischen dem Brachland und der Dunkelküste steht der uralte Wald weiterhin unter dem Schutz der Schildwachen und Cenarius'. Sein Blätterdach birgt Mondbrunnen und alte Ruinen, während dämonische Verderbnis, feindselige Stämme und eine umkämpfte Grenze den Wald bedrohen.",h="Die heiligen Wälder des Eschentals sind zum Schlachtfeld geworden, seit die Horde Holz für Orgrimmar schlägt.",kw={"eschental","astranaar","bough shadow","cenarius","grommash","mannoroth","silberschwingen","splitterholz","kriegshymne","zoram"},ang={["class:Druid"]="Als Druide seht Ihr, wie das Gleichgewicht der Natur von vielen Seiten bedroht wird. Holzfällerlager, verdorbene Pelzbolgnester und das von Albträumen heimgesuchte Portal bei Bough Shadow lassen das Eschental auf Wiederherstellung durch den Zirkel des Cenarius hoffen.",["profession:Herbalism"]="Als Kräuterkundiger findet Ihr im Eschental reiche Sammelgebiete, genährt von uralten magischen Leylinien und stetigem Regen. Hier wachsen Wilddornrose, Würgetang und Königsblut, während seltenes Gromsblut nahe dämonischer Narben gedeiht.",["race:NightElf"]="Als Nachtelf ist das Eschental Eure spirituelle Heimat und das Vermächtnis des Cenarius. Seine Haine vor den Äxten des Kriegshymnenklans zu verteidigen und die Mondbrunnen von Satyrverderbnis zu reinigen, sind Fragen der Kaldorehre.",["race:Orc"]="Als Orc versorgt dieses Holz die Mauern und Belagerungstürme Orgrimmars. Das Eschental ist auch heiliger Boden, auf dem Grommash Hellscream Blut vergoss, um das orkische Volk aus dämonischer Knechtschaft zu befreien."},sec={{t="Das flüsternde Blätterdach",b="Unterhalb des Hyjal gehört das Eschental seit Jahrtausenden den Kaldorei und den Kindern des Cenarius. Gewaltige Bäume bilden über Euch ein dichtes Blätterdach. Der tägliche Regen sammelt sich darunter als Nebel, und Zwielicht legt sich über den Waldboden.\n\nMoos bedeckt die Ruinen elfischer Siedlungen, in denen wandelnde Uralte und Dryaden Wache halten. Tausende Jahre lang errichteten die Nachtelfen hier keine echten Städte. Sie jagten mit leichter Hand und hielten das wilde Gebiet im Gleichgewicht."},{t="Krieg um den Wald",b="Der Dritte Krieg zerstörte den Frieden des Eschentals. Grommash Hellscream und der Kriegshymnenklan drangen auf der Suche nach Bauholz in den Wald ein, und ihr dämonischer Blutdurst führte dazu, dass sie Cenarius erschlugen. Nun ist der Kampf ein umfassender Gebietskrieg.\n\nVom Splitterholzposten und dem südlichen Mor'shan-Schutzwall aus schicken die Vorhut des Kriegshymnenklans Äxte und Schredder in die östlichen Wälder, um Orgrimmar zu versorgen. Die Schildwachen der Silberschwingen halten Astranaar, eine Zufluchtsstadt. Sie haben geschworen, jeden orkischen Holzfäller aus dem heiligen Hain zu vertreiben."},{t="Verweilende Schatten",b="Der Holzkrieg ist nur eine der Gefahren im Eschental. Die Brennende Legion hinterließ vernarbte Verderbnis am Dämonenhügel und im Demonfall-Canyon, wo Mannoroth starb. Satyrn haben ihre Lager in Ruinen wie Satyrnaar und Xavian aufgeschlagen und verderben Wasserwege und Tierwelt.\n\nPelzbolgstämme, einst Freunde der Elfen, sind weitgehend dem dunklen Wahnsinn verfallen. Geheimnisvolle Worgen durchstreifen den nördlichen Schrein nahe dem Teufelswald. Verfluchte Drachenbrut streift durch Bough Shadow und bewacht ein Portal in den bedrängten Smaragdgrünen Traum."}},faq={{q="Warum kämpfen Horde und Allianz im Eschental?",a="Die Horde braucht das Holz des Eschentals, um Orgrimmar zu errichten und ihre junge Nation zu erhalten. Die Orcs aus Durotar haben in ihrer trockenen Heimat kaum Holz, während die Nachtelfen das Eschental als heilige Heimat ihrer Ahnen betrachten, die von Naturgottheiten beschützt wird. Die Schildwachen der Silberschwingen sehen das Kahlschlagen durch den Kriegshymnenklan als Entweihung, und der Streit führt zu Scharmützeln und erbitterten Kämpfen in der Kriegshymnenschlucht.",al={"warum die horde bäume fällt","grund für den krieg im eschental","kriegshymnenklan gegen silberschwingen"}},{q="Was geschah Cenarius in diesem Wald?",a="Während des Dritten Krieges führte Grommash Hellscream den Kriegshymnenklan auf der Suche nach Bauholz ins Eschental. Cenarius griff an, um den heiligen Hain zu verteidigen. Um den Halbgott zu besiegen, tranken Grommash und sein Klan verzweifelt aus einem Brunnen, der vom Grubenlord Mannoroth verdorben war. Die dämonische Wut, die sie dadurch gewannen, erlaubte ihnen, Cenarius zu erschlagen. Grom brach später den Fluch, indem er Mannoroth im Demonfall-Canyon tötete, doch die Elfen haben den Mord an ihrem Schutzpatron und Halbgott nicht vergessen.",al={"wie cenarius starb","grom tötete cenarius","cenarius' schicksal"}},{q="Was ist die Tiefschwarze Grotte?",a="Die Tiefschwarze Grotte liegt unter dem Zoramstrand an der Nordwestküste des Eschentals. Der versunkene Tempel war einst ein uralter Kaldorei-Tempel für Elune und stürzte während der Großen Teilung ins Meer. Wilde Naga, Kultisten des Schattenhammerklans und Wasserbestien haben ihn nun überrannt und verehren die uralte Hydra Aku'mai.",al={"wo liegt die tiefschwarze grotte","geschichte der tiefschwarzen grotte"}},{q="Was ist der Große Baum bei Bough Shadow?",a="Bei Bough Shadow steht einer von vier Großen Bäumen, die der Zirkel des Cenarius vor Tausenden von Jahren pflanzte, um Zugänge zum Smaragdgrünen Traum zu verankern. Der Baum ist weiterhin ein aktives Tor zwischen Azeroth und dem Traum. Grüne Drachkin bewachen das Gebiet, doch eine unheilvolle Verderbnis im Traum schickt bisweilen monströse Alptraumdrachen durch das Portal.",al={"baum bei bough shadow","portal bei bough shadow","grüne drachen im eschental"}},{q="Warum sind die Pelzbolgs im Eschental feindselig?",a="Die Pelzbolgs des Eschentals waren jahrhundertelang friedliche Verbündete der Nachtelfen, bis dämonische Verderbnis während des Einfalls der Brennenden Legion ihren Verstand zerrüttete. Teufelsmagie, die an Orten wie dem Teufelswald, Satyrnaar und dem Demonfall-Canyon zurückblieb, trieb Stämme wie die Dornenpelze in gewaltsamen Wahnsinn. Sie wandten sich gegen Fremde und die eigenen Sippenmitglieder.",al={"verrückte pelzbolgs im eschental","verderbnis der dornenpelze","warum pelzbolgs angreifen"}},{q="Wer ist im Demonfall-Canyon begraben?",a="Im Demonfall-Canyon standen sich Grommash Hellscream und Thrall dem Grubenlord Mannoroth gegenüber. Grom versetzte dem Dämonenlord einen tödlichen Schlag und befreite das orkische Volk um den Preis seines Lebens vom dämonischen Blutfluch. Dort steht ein Denkmal für Grom Hellscream, und viele Orcs pilgern dorthin, um den Krieger zu ehren, der ihr Volk befreite.",al={"mannoroth im canyon","grommashs grab im eschental","denkmal im demonfall-canyon"}},{q="Wie reise ich durch das Eschental?",a="Reisende der Allianz betreten das Eschental gewöhnlich durch den nördlichen Gebirgspass von Auberdine in der Dunkelküste und folgen dann der Hauptstraße nach Osten in Richtung Astranaar. Reisende der Horde marschieren vom Brachland aus durch den befestigten Mor'shan-Schutzwall nach Norden zum Splitterholzposten oder nach Westen zum Außenposten von Zoram'gar am Zoramstrand. Beide Fraktionen unterhalten Flugmeister in ihren großen Festungen.",al={"wie man ins eschental kommt","reisen im eschental","flugrouten im eschental"}}},fx={["97bd7929"]={q="Was ist das Eschental?",a="Das Eschental ist ein uralter, weitläufiger primordialer Regenwald, der südlich der Dunkelküste und des Teufelswald und direkt nördlich des Brachland und des Steinkrallengebirge liegt. Bekannt als die angestammte Heimat der Nachtelfen, wurde es von ihnen über Jahrtausende hinweg gehegt und bewahrt. Sein Blätterdach ist so massiv und dicht, dass fast ständig sanfter Regen fällt, der kaum den Waldboden erreicht. Heute ist es eine umkämpfte Wildnis, in der uralte Geister und Schildwachen der Kaldorei gegen vordringende Holzfällerexpeditionen, eindringende dämonische Überreste und wilde Bestien kämpfen.",al={"was ist das eschental","über das eschental","erzähl mir vom eschental","zone eschental"}},d00ef10f={q="Was geschah im Eschental während des Dritter Krieg?",a="Während des Dritter Krieg erlitt das Eschental katastrophale Umwälzungen. Der Kriegshymnenklan unter Grommash Hellscream drang zuerst ein, um Holz zu ernten, und provozierte dabei versehentlich den Halbgott Cenarius. Von dämonischem Einfluss getäuscht, trank Grom Dämonenblut und erschlug Cenarius. Kurz darauf fiel Archimonde mit der Brennenden Legion in voller Stärke ein, ließ Infernale auf den Wald regnen und stieß in Richtung Hyjal vor. Die Schreckenslords der Legion entfesselten abscheuliche Seuchen, die Teile der Wildnis zu dem korrupten Ödland vernarbten, das als Teufelswald bekannt ist, und hinterließen bleibende dämonische Narben, die bis heute im Wald fortbestehen.",al={"geschichte des eschental","was passierte im eschental","dritter krieg eschental"}},["3f2d3290"]={q="Wer lebt im Eschental?",a="Über Jahrtausende hinweg wurde der Wald in einem wilden Zustand bewahrt, vornehmlich bewohnt von Waldtieren, Dryaden, Hütern des Hains und fühlenden Uralten, und bewacht von umherstreifenden Nachtelf-Schildwachen statt von städtischen Siedlungen. Heute unterhalten die Nachtelfen befestigte Außenposten wie Astranaar und Maestras Posten. Im Osten und entlang der Westküste hat die Horde Enklaven wie den Splitterholzposten und den Außenposten von Zoram'gar errichtet. Das wilde Innere bietet Furbolgstämmen, feindseligen Satyrn, Harpyien und verbliebenen dämonischen Brutstätten Schutz.",al={"wer lebt im eschental","bewohner des eschentals","wer lebt hier"}},["24f461e0"]={q="Warum wird der Wald abgeholzt?",a="Die Orcs der Horde, angeführt vom Kriegshymnenklan, benötigen Holz, um ihre Siedlungen zu erhalten und ihre Expansion in den trockenen Ebenen von Durotar und dem Brachland voranzutreiben. Für die Nachtelfen sind die uralten Bäume und lebenden Uralten des Eschentals heilig und beseelt. Das Fällen dieser Bäume wird als unverzeihliche Schändung betrachtet, was jedes Holzfällerlager und jede Säge zu einer offenen Provokation macht, die endloses Blutvergießen heraufbeschwört.",al={"warum bäume fällen","warum wird abgeholzt","warsong holzfällerei grund","entwaldung eschental"}},d5bfe513={q="Ist das Eschental gefährlich?",a="Äußerst gefährlich. Die Straßen sind zugewuchert und von Schatten verdeckt, durchstreift von riesigen Bären, Raubkatzen und Wildtieren. Jenseits der Bestien suchen gewalttätige Satyrn alte Ruinen heim, korrumpierte Furbolgs greifen jeden an, der sich nähert, und Taschen brennender Teufelskorruption beherbergen Dämonen. Reisende müssen sich auch mit dem offenen Fraktionskrieg auseinandersetzen: Die Schildwachen der Silberschwingen und die Vorhut des Kriegshymnenklans jagen aktiv feindliche Späher durch das Blätterdach.",al={"ist das eschental gefährlich","wie gefährlich ist das eschental","gefahren im eschental"}},["534156e4"]={q="Wer hat das Sagen im Eschental?",a="Keine einzelne Autorität besitzt die ungeteilte Herrschaft über das Eschental. Hohepriesterin Tyrande Wisperwind und die Schildwachen der Nachtelfen beanspruchen die rechtmäßige Verwaltung über ihr angestammtes Land, befehligen Außenposten wie Astranaar und bewachen die Haine mit umherziehenden Uralten. Die Horde bestreitet jedoch erbittert den Osten des Eschentals durch den Kriegshymnenklan und den Splitterholzposten, was das Herz des Waldes in eine erbittert umkämpfte Frontlinie verwandelt.",al={"wer regiert das eschental","wer hat hier das sagen","führung im eschental"}},["0575374f"]={q="Was sind die Schildwachen?",a="Die Schildwachen sind die Elite, der ständige militärische Orden der Nachtelfen, bestehend aus engagierten weiblichen Kriegerinnen, Jägerinnen und Bogenschützinnen. Gegründet nach dem Krieg der Ahnen, unternahmen sie die Lange Wacht unter Hohepriesterin Tyrande Wisperwind, während die männlichen Druiden im Smaragdgrünen Traum schlummerten. Sie patrouillieren die Wälder auf tödlichen Pantherreittieren und mit unübertroffener Heimlichkeit und strecken jeden Eindringling nieder, der die Natur schändet.",al={"was sind die schildwachen","nachtelf-schildwachen","wer sind die schildwachen"}},["42b1a6f5"]={q="Was ist Astranaar?",a="Astranaar ist die wichtigste Stadt der Nachtelfen im zentralen Eschental und die Hauptbasis für Operationen der Allianz in der Region. Erbaut auf einer Insel inmitten eines Sees und nur über Brücken erreichbar, die die Waldstraße überspannen, dient sie als Handelszentrum, Zufluchtsort und Verteidigungsbastion gegen unaufhörliche Angriffe der Horde und benachbarter korrumpierter Furbolgs.",al={"was ist astranaar","stadt astranaar","erzähle mir von astranaar"}},["56b6ce63"]={q="Was ist der Splitterholzposten?",a="Der Splitterholzposten ist die befestigte Festung der Horde im östlichen Eschental. Er wurde nach dem Dritten Krieg errichtet und dient als primäre militärische Vorhut, die die ausgedehnten Holzfällarbeiten des Kriegshymnenklans im Holzfällerlager des Kriegshymnenklans schützt und die Straße deckt, die nach Süden zum Mor'shan-Schutzwall und dem Brachland führt.",al={"was ist der splitterholzposten","splitterholzposten","splitterholz horde"}},["64786646"]={q="Was sind Satyrn und woher kommen sie?",a="Satyrn sind abscheuliche, gehörnte dämonische Humanoide, die aus uralten Hochgeborenen-Nachtelfen hervorgingen, die während des Krieges der Ahnen, beginnend mit Lord Xavius, ihre Dienste der Brennenden Legion verschrieben. Als geschworene Feinde aller Kaldorei lauern sie in alten Elfenruinen wie Xavian, Nachtflucht und Satyrnaar, schwingen üble Shadow Magic und arbeiten daran, Korruption über die unberührten Haine zu verbreiten.",al={"was sind satyrn","ursprung der satyrn","woher kommen satyrn"}},e95425a8={q="Was ist die Zoram-Strand?",a="Die Zoram-Strand ist ein Streifen rauer Küste, der die nordwestliche Grenze des Eschentals entlang der Verschleierten See bildet. Einst Teil der elfischen Küste vor der Zerschlagung, ist sie heute von feindseligen Naga und Murlocs befallen und beherbergt den ruinierten Eingang zur Tiefschwarzen Grotte sowie das isolierte Küstenbollwerk der Horde, den Außenposten von Zoram'gar.",al={"was ist die zoram-strand","der zoramstrand","zoram strand"}},["273c413f"]={q="Wie bin ich im Eschental gelandet?",a="Ihr Weg hierher hängt von Eurer Loyalität ab. Wenn Ihr für die Allianz kämpft, seid Ihr wahrscheinlich der Straße der Schildwachen südlich von Auberdine an der Dunkelküste gefolgt und in die schattigen Zweige in Richtung Maestras Posten und Astranaar eingedrungen. Wenn Ihr mit der Horde reitet, seid Ihr die staubige Goldstraße vom Wegekreuz im Brachland entlang nach Norden marschiert und direkt durch die befestigten Barrikaden des Mor'shan-Schutzwalls in den dichten Wald gelangt.",al={"wie bin ich hierher gekommen","wie erreiche ich das eschental","ins eschental gelangen"}},["023178b1"]={q="Was soll ich im Eschental tun?",a="Ihr befindet Euch in einer umkämpften Wildnis, gefangen zwischen uralten Wächtern und kühnen Eindringlingen. Champions der Allianz versammeln sich in Astranaar, um das angestammte Heimatland der Nachtelfen zu verteidigen, die Holzfälloperationen der Horde zurückzuschlagen, korrumpierte Furbolgs zu reinigen und verbliebene Dämonenkulte anzugreifen. Abenteurer der Horde drängen vom Splitterholzposten und dem Außenposten von Zoram'gar aus nach vorne, um dringend benötigtes Holz für Durotar zu sichern, territoriale Besitztümer zu erweitern und dem Zorn der Waldgeister und Schildwachen zu überleben.",al={"warum bin ich hier","was tue ich im eschental","was ist mein ziel hier"}}},fp="9,328,21.445.0,17.489.0,17.472.0,53.389.0,41.434.0,26.315.0,39.340.0,42.344.0,35.325.0,34.374.0"}
P.entries["zone:azshara"] = {n="Azshara",s="Entlang der nordöstlichen Küste Kalimdors erstreckt sich Azsharas zerklüftete Küste von herbstlichen Wäldern bis zu versunkenen Ruinen und gefährlichen Gewässern. Außenposten der Horde und der Allianz liegen nahe den Grenzen, während Naga, Geister und andere Gefahren das Land heimsuchen.",h="Entlang der nordöstlichen Küste Kalimdors erstreckt sich Azsharas zerklüftete Küste von herbstlichen Wäldern...",kw={"azshara","azuregos","die bucht der stürme","korallenmeer","eldarath","hochgeborene","spitelash","talrendisspitze","valormok","xylem"},ang={["class:Mage"]="Als Magier findet Ihr vergessene Zauberkunst der Hochgeborenen, die durch die zertrümmerten Steine Eldaraths knistert. Hoch über den Klippen prüft Erzmagier Xylem jene, die die arkane Teleportation und Zauberkunst meistern wollen.",["profession:Herbalism"]="Als Kräuterkundiger findet Ihr seltene, kraftvolle Kräuter, die Azsharas endloser Herbst gedeihen lässt. Dazu gehören Traumblatt, Goldener Sansam, Bergsilberweisling und Lila Lotus zwischen den Ruinen.",["profession:Mining"]="Als Bergbauer findet Ihr wertvolle Erzadern in Azsharas steilen Küstenklippen und zerklüfteten Gebirgskämmen. Mithril, Echtsilber und Thorium gibt es reichlich.",["race:NightElf"]="Als Nachtelf seht Ihr versunkene Säulen und heulende Schatten der Hochgeborenen. Sie erinnern an Königin Azsharas rücksichtslosen Hochmut und den Untergang der uralten Kaldorei-Zivilisation."},sec={{t="Ein versunkenes Reich",b="Die Küste von Zin-Azshari lag einst im Herzen der Kaldorei-Zivilisation. Vor zehntausend Jahren riefen Königin Azshara und ihr Hofstaat der Hochgeborenen die Brennende Legion nach Azeroth. So begann der Krieg der Ahnen. Der Brunnen der Ewigkeit brach zusammen, und das Meer verschlang den Großteil der prächtigen Stadt. Zerklüftete Klippen, gefährliche Korallenriffe und wasserbedeckte Türme blieben zurück. Die Überlebenden benannten das zerstörte Land nach ihrer gefallenen Monarchin, deren Hochmut und Verrat es für immer veränderten."},{t="Herbstpracht und verborgene Gefahren",b="Karmesinrote, orangefarbene und goldene Blätter bedecken Azsharas Wälder in einem endlosen Herbst. Doch unter dem stillen Blätterdach verbirgt sich eine erbarmungslose Wildnis. Satyren vollziehen dunkle Rituale in Waldsenken, Erscheinungen der Hochgeborenen spuken an versunkenen Fundamenten, und Spitelash-Naga durchstreifen die seichten Riffe des Korallenmeeres. Wilde Bestien, riesige Hydren und Bergriesen ziehen durch das Hochland und über elfenbeinfarbene Strände."},{t="Ein Reich der Verbannten und Ausgestoßenen",b="Azsharas Abgeschiedenheit und raues Gelände ziehen jene an, die vergessenen Künsten nachgehen oder gefährliche Mächte beobachten. Erzmagier Xylem lebt in einem abgelegenen Turm hoch über den Klippen. Dort prüft er vielversprechende Zauberwirker und gerissene Schurken. Weiter entlang der Küste beobachtet der Dämonenjäger Loramus Thalipedes von einer kargen Insel aus die Wellen. In einem Tempel über den tosenden Wassern fordert der gewaltige Meeresriese Lord Arkkoroc Blutopfer."}},faq={{q="Warum sind hier alle Bäume rot und orange?",a="Azsharas Wälder tragen in einem endlosen Herbst karmesinrote, orangefarbene und goldene Blätter. Das Blätterdach verliert sie nie, und dieser eindrucksvolle, schwermütige Anblick währt seit Tausenden von Jahren.",al={"warum ist azshara herbstlich","warum sind die bäume rot","herbstlaub in azshara"}},{q="Wie wurde Azshara zu einer Ruine?",a="Die Küste bildete einst den Stadtrand von Zin-Azshari, der Hauptstadt der Kaldorei. Während des Krieges der Ahnen implodierte der Brunnen der Ewigkeit bei der Großen Zerschlagung. Der Kontinent zerbrach, und weite Teile der Stadt versanken im Meer.",al={"was geschah mit azshara","warum ist azshara zerstört","geschichte von azshara"}},{q="Wer herrscht heute über Azshara?",a="Keine der beiden Fraktionen beherrscht ganz Azshara. Die Allianz hält nahe dem Eschental einen kleinen Wachposten an der Talrendisspitze, und die Horde operiert von Valormok aus. Gefährliche Spitelash-Naga, gewalttätige Satyren und ungezähmte Monster beherrschen das umliegende Land.",al={"wer kontrolliert azshara","wer herrscht über azshara","ist azshara allianz oder horde"}},{q="Wer ist Erzmagier Xylem?",a="Erzmagier Xylem ist ein exzentrischer menschlicher Zauberer in einem abgelegenen Turm mit Blick auf Azsharas Klippen. Er hält sich aus der regionalen Politik heraus und führt Besucher unter den Magiern und Schurken durch Prüfungen, die ihr Kampfgeschick und ihr arkanes Potenzial entfalten.",al={"xylem in azshara","magierturm in azshara","zauberer in azshara"}},{q="Was macht der blaue Drache in den Ruinen?",a="Azuregos und seine Brut wachen über die uralten Ruinen von Eldarath. Der mächtige blaue Drache bewacht die kraftvollen magischen Artefakte der Hochgeborenen, die im Geröll begraben liegen, mit aller Macht vor Sterblichen.",al={"azuregos in azshara","blauer drache in azshara","drache in eldarath"}},{q="Warum halten die Nachtelfen dieses Land für verflucht?",a="Die Kaldorei halten Azshara für verflucht, weil es den Namen und das architektonische Erbe von Königin Azshara trägt. Ihr Pakt mit der Brennenden Legion zerschmetterte ihr Reich und brachte der Welt den Untergang.",al={"ist azshara verflucht","warum hassen nachtelfen azshara","fluch der nachtelfen in azshara"}}},fp="7,220,16.460.0,33.382.0,30.428.0,42.182.0,30.229.0,24.237.0,22.233.0,43.180.0,49.189.0"}
P.entries["zone:badlands"] = {n="Ödland",s="Staubstürme fegen über das Ödland, wo rivalisierende Streitkräfte im zwergischen Khaz Modan ihre Stellungen halten. Dunkeleisenzwerge, Troggs, Dustbelcher-Oger und schwarze Drachenwesen drängen sich an dieser Grenze zwischen Loch Modan und der Sengenden Schlucht. Die Titanenruinen von Uldaman und die Hordenfestung Kargath machen die Gegend zu einem Knotenpunkt.",h="Staubstürme fegen über das Ödland, wo rivalisierende Streitkräfte im zwergischen Khaz Modan ihre Stellungen...",kw={"festung angor","ödland","dustbelcher","irdene","bluthauer","kargath","lethlor","troggs","uldaman"},ang={["faction:Horde"]="Als Mitglied der Horde findet Ihr Euer militärisches Refugium in Kargath, tief in Khaz Modan. Die Festung steht an vorderster Front gegen die Dunkle Horde im Schwarzfels.",["profession:Mining"]="Als Bergarbeiter findet Ihr in diesem trockenen Land Eisen, Gold, Echtsilber und Mithril. Seltene Induriumvorkommen liegen in Uldaman und der umliegenden Gegend.",["race:Dwarf"]="Als Zwerg könnt Ihr in Uldaman nach Antworten über Eure Abstammung suchen. Entdeckungen über die titangeschaffenen Irdenen veränderten das Geschichtsverständnis der Zwerge."},sec={{t="Eine trostlose Grenzregion",b="Südlich der grünen Hügel von Loch Modan betretet Ihr ein heißes Becken aus kargen Ebenen und schroffen Schluchten. Kojoten, Pumas und Geier durchstreifen das Land, und heftige Sandstürme können den Horizont verschleiern. Dustbelcher-Oger unterhalten primitive Lager auf den Hochebenen. In der Festung Angor befestigt der Dunkeleisenclan seine Stellung und legt sich mit allen an, die eindringen."},{t="Die Geheimnisse von Uldaman",b="Zwischen den nördlichen Steilhängen liegt Uldaman, ein unterirdischer Komplex, den die titangeschaffenen Irdenen ausgehöhlt haben. Prospektoren aus Eisenschmiede legten ihn vor Kurzem frei und enthüllten monumentale Geheimnisse über die uralte Abstammung der Zwerge. Ihre Grabungen weckten Horden bösartiger Troggs der Felsenmasch und belebte irdene Wächter. Die Kreaturen metzelten die Archäologenteams nieder und verwandelten die Ausgrabungsstätten im Freien in blutige Schauplätze von Scharmützeln."},{t="Die Schatten von Kargath und Lethlor",b="Die Horde hält hier einen ihrer unsichersten Stützpunkte in den südlichen Östlichen Königreichen. Kargath im Nordwesten bietet den Streitkräften von Kriegshäuptling Thrall eine Basis, um die abtrünnige Dunkle Horde im nahen Schwarzfels im Auge zu behalten. Weit im Osten schneidet Die Lethlorklamm eine tückische Schlucht durch das Land. Im Schatten der Berge bewachen schwarze Welpen und gefährliche schwarze Drachenwesen ihre Brutstätten."}},faq={{q="Warum ist die Horde im Ödland stationiert?",a="Kriegshäuptling Thrall befahl dem Expeditionskorps von Kargath, Kargath zu errichten. Unter Kriegsherr Bluthauer bietet der Außenposten der Horde einen Sammelpunkt für Angriffe auf Rend Schwarzfaust und seinen abtrünnigen Schwarzfelsklan im Schwarzfels.",al={"warum kargath","horde im ödland","was ist kargath"}},{q="Wie gelangt Ihr ins Ödland?",a="Reisende der Allianz können von Loch Modan aus durch den Pass an der Terrasse des Schöpfers nach Süden gehen. Reisende der Horde müssen weiter durch die südlichen Hügel von Loch Modan marschieren oder die Sengende Schlucht über ihren westlichen Gebirgspass durchqueren. Danach können sie den Flugmeister von Kargath nutzen.",al={"ins ödland gelangen","wie erreicht man das ödland","eingang zum ödland"}},{q="Was ist Uldaman?",a="Uldaman ist ein riesiges unterirdisches Gewölbe, das von den uralten Titanen und ihren irdenden Dienern erbaut wurde. Zwergische Prospektoren gruben es vor Kurzem auf der Suche nach den Geheimnissen der zwergischen Herkunft aus und weckten dabei begrabene irdene Konstrukte und primitive Troggs der Felsenmasch. Die Ruine ist nun ein tödliches Schlachtfeld.",al={"was ist uldaman","geschichte des uldaman-dungeons","wer erschuf uldaman"}},{q="Was tun die schwarzen Drachen in der Lethlorklamm?",a="Schwarze Drachen nutzen Die Lethlorklamm im Osten als Schlucht zum Brüten und Nisten. Drachen und Welpen bewachen das Gelege, das Wanderer jagt und die östlichen Gebiete gegen Eindringlinge verteidigt.",al={"drachen im ödland","drachen in der lethlorklamm","schwarzer drachenschwarm im ödland"}},{q="Wer kontrolliert die Festung Angor?",a="Der feindselige Dunkeleisenclan hält die Festung Angor südlich von Uldaman. Von dort aus betreibt der Clan Aufklärung, beansprucht die Ausgrabungsstätten der Titanen und bekämpft benachbarte Oger und Erkundende an der Oberfläche.",al={"festung angor","festung im ödland","dunkeleisenzwerge im ödland"}},{q="Gibt es hier freundliche Siedlungen für Spieler der Allianz?",a="Im Ödland gibt es keine befestigten Siedlungen oder Flugmeister der Allianz. Prospektoren aus Eisenschmiede und einsame Einsiedler unterhalten verstreute, schutzlose Lager nahe den Ausgrabungsstätten. Reisende der Allianz müssen sich für umfangreiche Vorräte auf Loch Modan oder die Sengende Schlucht verlassen.",al={"allianzstadt im ödland","flugroute der allianz im ödland","freundliche allianz im ödland"}}},fp="8,296,16.335.0,22.421.0,34.395.0,43.231.0,31.249.0,16.286.0,51.191.0,28.193.0,61.250.0"}
P.entries["zone:barrens"] = {n="Brachland",s="Im Brachland sichern Vorposten der Horde die Straßen, während rivalisierende Mächte von allen Seiten vorrücken. Einst war diese Ebene im Herzen Kalimdors vor der Großen Zerschlagung bewaldet. Heute ist sie trockenes Land aus rotem Staub, Gestrüpp und umherziehender Tierwelt. Das Wegekreuz bündelt den Verkehr der Horde, doch Stacheleber, Zentauren und schleichende Verderbnis bedrohen ihren Einfluss.",h="Im Brachland sichern Vorposten der Horde die Straßen, während rivalisierende Mächte von allen Seiten...",kw={"brachland","das wegekreuz","goldstraße","kolkar","naralex","stacheleber","ratschet","taurajo","die höhlen des wehklagens"},ang={["class:Druid"]="Die veränderten Wasser der Höhlen des Wehklagens zeugen von einer Tragödie. Naralex' Versuch, das Brachland wiederherzustellen, scheiterte an einem Albtraum.",["class:Shaman"]="Diese trockenen Ebenen stellen Eure Verbundenheit mit den Elementen auf die Probe, von den Geistern der ausgedörrten Erde bis zu verzauberten Wassern, die in abgelegenen Oasen sprudeln.",["faction:Horde"]="Das Brachland ist die Nachschubstraße Eures Reiches. Haltet das Wegekreuz und schützt die Konvois entlang der Goldstraße, damit Orgrimmar und Donnerfels bestehen können.",["race:Tauren"]="Eure nomadischen Vorfahren durchstreiften diese Savannen seit Generationen, bevor die Orcs Kalimdor erreichten. Sie jagten heiliges Wild und kämpften ums Überleben gegen die gnadenlosen Kolkarzentauren."},sec={{t="Herz der Neuen Horde",b="Seit Generationen jagen nomadische Tauren auf diesen Ebenen Kodos und Zhevras. Außerdem führen sie immer wieder Verteidigungskriege gegen die Kolkarzentauren. Während des Dritten Krieges führte Thrall die Orcs nach Kalimdor. Er half Cairne Bluthuf, die Zentauren zurückzudrängen, und durchquerte dann mit ihm die Savanne nach Mulgore. Das Brachland verbindet heute Durotar, Mulgore und Eschental.\n\nDas Wegekreuz und Camp Taurajo sichern den Handel entlang der Goldstraße. Orcische Gehöfte trotzen dem rauen Klima, während die Horde sich eine dauerhafte Heimat aufbaut."},{t="Ein belagertes Land",b="Die Kontrolle der Horde über die Savanne ist weiterhin umkämpft. Razormane-Stacheleber überfallen von ihren dornigen Festungen aus Höfe und Nachschublinien. Ihre Borsten gleichen Stachelschweinstacheln. Im Süden überragen die Höhlen des Krals der Klingenhauer das Land. An der Ostküste halten Truppen aus Theramore die Feste Northwatch, während Zwergenforscher in den Titankomplex von Bael Modan graben. Die Goblins von Ratschet bewahren eine angespannte Neutralität im Handel und heißen Reisende willkommen, die Münzen mitbringen."},{t="Die Verderbnis des Smaragdgrünen Traums",b="Oasen durchbrechen die nördlichen Ebenen, und ihr Wasser schwillt mit unnatürlicher Kraft an. Die Quelle liegt in den Höhlen des Wehklagens. Dort suchte der Nachtelfendruide Naralex den Smaragdgrünen Traum auf und hoffte, das Brachland in seinen uralten Waldzustand zurückzuverwandeln. Ein Albtraum verdrehte seine Vision. Nun fließt verderbtes Wasser durch Die Vergessenen Teiche und Die Brackige Oase. Es lässt seltsame Deviatpflanzen, unnatürliche Bestien und die abtrünnigen Druiden des Giftzahns entstehen."}},faq={{q="Warum gibt es üppige Oasen mitten in einer Wüste?",a="Die Vergessenen Teiche und Die Blühende Oase beziehen ihr Wasser aus unterirdischen Quellen, die aus den Höhlen des Wehklagens fließen. Der Nachtelfendruide Naralex versuchte, diese Quellen durch den Smaragdgrünen Traum zu leiten und das trockene Land zu begrünen. Sein Vorhaben ging schief und erfüllte das nördliche Brachland mit mächtiger, unberechenbarer Naturmagie.",al={"oasen im brachland","warum gibt es wasser im brachland","wasser der höhlen des wehklagens"}},{q="Wer kontrolliert das Wegekreuz?",a="Die Horde hält das Wegekreuz mit Garnisonstruppen besetzt, vor allem mit Orc- und Taurenkriegern, die Kriegshäuptling Thrall dienen. Dort treffen die wichtigsten Handelsrouten aufeinander. Das macht es zum wichtigsten Militär- und Verkehrsknotenpunkt der Horde in Zentralkalimdor. Vom Wegekreuz aus verbinden diese Routen Durotar, Mulgore und Eschental.",al={"wer führt das wegekreuz","horde am wegekreuz","wachen am wegekreuz"}},{q="Warum greifen die Stacheleber alle an?",a="Die Stacheleber beanspruchen das Brachland als ihr angestammtes Erbe. Sie glauben, seine mächtigen Dornbüsche seien während des Krieges der Ahnen aus dem Blut ihres Halbgottes Agamaggan gewachsen. Für sie sind die Horde und die einheimischen Tauren Eindringlinge, die ihnen heilige Sammelgründe und Jagdgebiete wegnehmen.",al={"geschichte der stacheleber","warum sind stacheleber aggressiv","motive der razormane"}},{q="Warum sind Allianzsoldaten im Brachland?",a="Die Allianz hält die Ränder der Savanne. Menschliche Truppen aus Theramore besetzen die Feste Northwatch, um die Bewegungen der Horde zu beobachten. In den südlichen Hügeln graben Zwerge bei Bael Modan und Burg Bael'dun nach uralten Artefakten der Titanen.",al={"allianz in der feste northwatch","zwerge in bael modan","allianz im brachland"}},{q="Gehört Ratschet zur Horde?",a="Nein. Ratschet ist ein unabhängiger Goblinhafen unter der Führung von Gazlowe. Für den Seehandel heißt er Reisende der Horde und der Allianz, Schmuggler und Abenteurer willkommen, solange sie goblinischen Handel respektieren und ihre Waffen in der Stadt stecken lassen.",al={"gehört ratschet zur horde","fraktion von ratschet","gazlowe und ratschet"}},{q="Was ist mit den Silithiden im Süden los?",a="Silithiden sind aus Erdbauten im südlichen Brachland hervorgekommen, besonders nahe dem Feld der Riesen. Diese insektenartigen Kreaturen sind plötzlich aufgetaucht, und ihre Kolonien wachsen schnell. Sie bedrohen Reisende und nahe gelegene Vorposten, während die Horde ihren Ursprung untersucht.",al={"käfer im brachland","käfer beim feld der riesen","silithiden im südlichen brachland"}}},fx={["08031609"]={q="Was ist das Brachland?",a="Das Brachland ist eine riesige, sonnenverbrannte Savanne, die das zentrale Kalimdor dominiert. Begrenzt von niedrigen Bergen bildet es das territoriale Kernland der Horde und verbindet Durotar, Mulgore, das Eschental und die südlichen Regionen. Während es größtenteils aus trockenen Ebenen und dürrem Grasland besteht, ist es mit gelegentlichen Oasen übersät, die von unterirdischen Wassern gespeist werden, sowie von weitläufigen Handelsrouten, die entfernte Siedlungen miteinander verbinden.",al={"was ist das brachland","zone brachland","erzähle mir vom brachland"}},d0091816={q="Warum ist das Brachland so trocken und leer?",a="Vor langer Zeit war dieses Gebiet ein üppiger, grüner Wald, der von den Nachtelfen gepflegt wurde. Vor zehntausend Jahren rissen die katastrophale Verwüstung durch die Große Zerschlagung und die Kriege um die Brennende Legion die Wälder auseinander. Katastrophen und Feuer verwüsteten die Landschaft, entzogen ihr den fruchtbaren Boden und hinterließen die trockenen, sonnengebackenen Ebenen, die man heute sieht.",al={"warum ist es kahl","warum ist es trocken und leer","ursprung des brachlands"}},d67a8142={q="Wer lebt im Brachland?",a="Seit Generationen waren nomadische Taurenstämme die Hauptbewohner, die gemeinsam mit Kodos und Zhevras umherzogen. Heute unterhält die Horde bedeutende Siedlungen wie das Wegekreuz und Camp Taurajo, neben verstreuten Orc-Farmerfamilien. Die wilden Ebenen werden auch von feindseligen Stacheleberstämmen, Kolkar-Zentaurenclans, Harpyien, neutralen Goblins in Ratschet und archäologischen Expeditionen der Zwerge bewohnt.",al={"wer lebt hier","bewohner des brachlands","wer lebt im brachland"}},["8675aa57"]={q="Ist das Brachland gefährlich?",a="Äußerst. Neben wilden einheimischen Raubtieren wie Raptoren und Donnerechsen sehen sich Reisende unaufhörlichen Überfällen von Stachelebern der Dornenmähnen und Borstennacken gegenüber, die ihre dornigen Bauten verteidigen. Plündernde Kolkar-Zentauren und bösartige Harpyien überfallen Reisende entlang der Bergrücken, während Truppen der Allianz und bewaffnete Ausgrabungen der Zwerge im Süden heftig das Territorium der Horde bestreiten.",al={"ist das brachland gefährlich","bedrohungen im brachland","gefahr im brachland"}},ba0a3e81={q="Warum hat mich die Horde zum Wegekreuz geschickt?",a="Das Wegekreuz ist der zentrale Bereitstellungsraum für alle Operationen der Horde im zentralen Kalimdor. Abenteurer, die aus Durotar oder Mulgore ankommen, werden hierher geleitet, um die Nachschubwege zu unterstützen, gefährdete Außenposten vor aggressiven lokalen Stämmen zu verteidigen und eine feste militärische Präsenz in der weiten Wildnis zu etablieren.",al={"warum zum wegekreuz schicken","warum bin ich am wegekreuz","zweck des wegekreuzes"}},["2ec69a3c"]={q="Wofür ist das Wegekreuz?",a="Es dient als geschäftiger Handels- und Logistikknotenpunkt des Brachlands. Direkt am Schnittpunkt der Nord-Süd-Goldstraße und der Ost-West-Route zwischen Ratschet und dem Steinkrallengebirge gelegen, bietet es wichtige Handelsstände, Wyvern-Flugrouten und Verteidigungskasernen, die fast jeden Außenposten der Horde auf dem Kontinent verbinden.",al={"was ist das wegekreuz","wofür ist das wegekreuz","zweck des wegekreuzes"}},["23c4dfc8"]={q="Wer hat das Wegekreuz erbaut?",a="Die Horde errichtete den Außenposten nach dem Dritten Krieg. Als Thrall die Orcs und Dunkelspeertrolle anführte, um Durotar aufzubauen und das zentrale Kalimdor zu sichern, errichteten sie die Siedlung am Zusammenfluss alter Handelsrouten, um ihre Versorgungsketten zu verankern und sich gegen umherstreifende Zentauren und Stacheleber zu verteidigen.",al={"wer baute das wegekreuz","ursprung des wegekreuzes","wie wurde das wegekreuz erbaut"}},e472d007={q="Wer sind die Zentauren und warum hassen sie uns?",a="Die Zentauren sind aggressive, vierbeinige Plünderer, die seit Generationen in diesen Ebenen mit den Tauren zusammenstoßen. Stämme wie die lokalen Kolkar betrachten andere Völker als Eindringlinge oder als Beute, die zum Vergnügen gejagt werden muss. Ihre angestammten Blutfehden mit den Tauren sorgen für ständiges Blutvergießen, wo immer ihre Raubtrupps auf die Horde treffen.",al={"warum hassen uns zentauren","wer sind die zentauren","zentaurenbedrohung"}},e2564dbf={q="Was machen die Harpyien hier draußen?",a="Bösartige vogelartige Humanoide nisten entlang der nördlichen Bergrücken und Schluchten des Brachlands. Sie schlagen ohne Vorwarnung zu, suchen nach Aas und überfallen vorbeiziehende Karawanen entlang der Straßen. Unter Anführern wie Serena Bloodfeather stellen ihre organisierten Überfälle eine ständige Bedrohung für die Nachschubwege der Horde dar, die die nördlichen Pässe durchqueren.",al={"harpyien im brachland","warum sind harpyien hier","harpyien brachland"}},["909ebb4b"]={q="Wer sind die Zwerge bei Bael Modan und wonach graben sie?",a="Es handelt sich um eine Expedition aus Eisenschmiede, die unter General Twinbraid operiert und sich in Burg Bael'dun verschanzt hat. Sie graben tief unter der Erde einen begrabenen Forschungsstützpunkt der Titanen aus und suchen nach alten Relikten und historischem Wissen. Durch ihren exzessiven Einsatz von Sprengpulver und Maschinen wurden die einheimischen Stonespire-Tauren vertrieben.",al={"zwerge von bael modan","wonach graben die zwerge","ausgrabungsstätte bael modan"}},["52bcea79"]={q="Warum ist Gann Steinkeil so wütend auf die Zwerge?",a="Bael Modan wurde direkt über dem angestammten Land errichtet, das die Stonespire-Tauren als heilig betrachteten. Als die Zwerge ankamen, vertrieben oder schlachteten sie den Stamm ab und rissen das Dorf mit schweren Ausgrabungsmaschinen nieder. Nachdem diplomatische Versuche völlig gescheitert waren, verschrieb sich Gann einer blutigen Rache an der Ausgrabungsstätte.",al={"gann steinkeil wütend","warum hasst gann die zwerge","gann steinkeil rache"}},["918bbb4f"]={q="Was ist Ratschet und warum sind Goblins neutral?",a="Ratschet ist eine geschäftige Hafenstadt an der Händlerküste, die von Gazlowe nach seiner Ingenieursarbeit in Orgrimmar gegründet wurde. Das Steamwheedle Cartel betreibt den Hafen strikt für den Handel und den Seeverkehr mit Orten wie Beutebucht. Sie wahren ihre Neutralität, um vom Handel mit allen zu profitieren, und heißen Reisende der Horde und der Allianz willkommen, solange das Gold fließt.",al={"was ist ratschet","warum sind die goblins in ratschet neutral","goblins in ratschet"}},["50dbd02f"]={q="Wohin führt all dies nach dem Brachland?",a="Das Brachland fungiert als Kreuzungspunkt für ganz Kalimdor. Pfade im Norden führen durch den Mor'shan-Schutzwall in die dichten, umkämpften Wälder des Eschentals. Gebirgspässe im Westen schlängeln sich in Richtung Steinkrallengebirge, während die Südliche Goldstraße am Camp Taurajo vorbei in Richtung der Sumpfgebiete der Düstermarschen und der hoch aufragenden Klippen von Tausend Nadeln führt.",al={"wohin nach dem brachland","nächstes gebiet nach dem brachland","was kommt nach dem brachland"}},["06412399"]={q="Was liegt südlich hinter Camp Taurajo?",a="Wenn Ihr die Goldstraße nach Süden reist, kommt Ihr an den massiven zwergischen Befestigungsanlagen von Bael Modan vorbei und in die umstrittenen Grenzgebiete. Weiter südlich liegen die dornigen Festungen Kral der Klingenhauer und Hügel der Klingenhauer, gefolgt vom Großen Aufzug, der in die Schluchten von Tausend Nadeln hinabführt.",al={"südlich von camp taurajo","was liegt südlich von taurajo","hinter camp taurajo"}},["9b9beaa0"]={q="Wie bin ich im Brachland gelandet?",a="Ihr seid den natürlichen Straßen gefolgt, die aus der Heimat Eures Volkes hinausführen. Orcs und Dunkelspeere zogen westwärts aus Durotar hinaus und passierten die Fernwacht jenseits des Südstroms. Tauren wagten sich durch den Gebirgspass von Mulgore nach Osten und kamen zuerst im Camp Taurajo an. Reisende aus ferneren Ländern, darunter die Verlassenen und seltene Eindringlinge der Allianz, kommen oft auf dem Seeweg durch den Goblinhafen Ratschet an. Wie auch immer Ihr angekommen seid, die riesige Savanne eröffnet sich vor Euch im Herzen von Zentral-Kalimdor.",al={"wie bin ich hierher gekommen","wie bin ich ins brachland gekommen","warum bin ich im brachland"}},f4aa7870={q="Was soll ich im Brachland tun?",a="Als Mitglied der Horde seid Ihr hier, um dieses weitläufige Grenzgebiet zu sichern und zu zähmen. Orcs und Tauren haben Siedlungen wie das Wegekreuz und das Camp Taurajo errichtet, doch sie werden ständig belagert. Ihr habt die Aufgabe, aggressive Stacheleber der Razormane und Bristleback zurückzudrängen, Zentaurenplünderer zu bekämpfen und das bizarre, korrumpierte Leben zu untersuchen, das rund um die Wüstenoasen entsteht. Ihr müsst außerdem Wache halten gegen vordringende Außenposten der Allianz bei der Feste Northwatch und Bael Modan, um das Kernland zu sichern.",al={"was tue ich hier","was ist mein ziel im brachland","was mache ich hier"}}},fp="11,327,22.499.0,18.441.0,22.440.1,51.304.1,28.279.0,40.290.0,41.217.0,29.221.0,48.281.0"}
P.entries["zone:blackfathom"] = {n="Tiefschwarze Grotte",s="In den überfluteten Hallen der Tiefschwarzen Grotte versammeln sich Kultisten des Schattenhammers an der Nordwestküste des Eschentals. Einst war der Tempel Elune geweiht, der Mondgöttin der Nachtelfen. Nun verehren Naga und Satyrn Aku'mai, eine urzeitliche Hydra und Diener eines Alten Gottes.",h="In den überfluteten Hallen der Tiefschwarzen Grotte versammeln sich Kultisten des Schattenhammers an der...",kw={"aku'mai","tiefschwarze grotte","blackfathom","tiefen","gelihast","ghamoo-ra","kelris","sarevess","zoram"},ang={["class:Shaman"]="Als Schamane, der Je'neu und dem Irdenen Ring dient, müsst Ihr in die wässrige Finsternis hinabsteigen, um die Verderbnis der Elemente aufzuhalten und den chaotischen Einfluss der Alten Götter zu bannen.",["faction:Alliance"]="Als Held der Allianz dringt Ihr ein, um Späher Thaelrid zu retten, verlorenes Wissen der Hochgeborenen zu bergen und den Nachtelfen dabei zu helfen, ihre heilige Heimat von der Schreckensherrschaft des Kults zu reinigen.",["faction:Horde"]="Vom Außenposten von Zoram'gar aus will die Horde die Nordküste des Eschentals gegen die Aggression der Naga sichern und verhindern, dass die dunklen Rituale ihre Außenposten bedrohen.",["race:NightElf"]="Als Nachtelf seht Ihr, wie ein geliebter Teil Eures Erbes entweiht wird: ein uralter Schrein Elunes und sein heiliger Mondbrunnen, besudelt von Leerenkultisten und monströsen Abscheulichkeiten."},sec={{t="Versunkenes Heiligtum Elunes",b="Die Tiefschwarze Grotte liegt versunken unter den Küstengewässern des verhüllten Meeres. Vor der Großen Zerschlagung errichteten hochgeborene Steinmetze mit Edelsteinen besetzte Brücken durch ihre Hallen, und Königin Azshara bewachte die Gewässer rund um den heiligen Mondbrunnen. Sie hielt die Salzwassermeere und Gebirgsbäche voneinander getrennt. Als die Zerschlagung vor zehntausend Jahren das uralte Kalimdor zerschmetterte, versank der Tempel. Jahrtausendelang blieb er ungestört, bis finstere Einflüsterungen aus der Tiefe aufstiegen."},{t="Ein Hort uralter Schrecken",b="Kultisten des Schattenhammers kamen zu den versunkenen Ruinen, angelockt von wahnsinnigen Träumen und dunklen Vorzeichen. Im Inneren schlossen sie einen unheiligen Waffenstillstand mit Küstennaga unter der Führung von Lady Sarevess und herumstreifenden Satyrn. Gemeinsam entweihten sie den Mondbrunnen und versklavten die Kreaturen der Umgebung.\n\nJahrelange Qualen trieben die riesige Meeresschildkröte Ghamoo-ra in den Wahnsinn. Der brutale Murloc Gelihast errichtete einen Blutschrein, und die Höhlen füllten sich mit neuen Opfern. Unter Zwielichtfürst Kelris machten die Kultisten die Ruinen zu einem Aufmarschgebiet für die bevorstehende Rückkehr der Alten Götter."},{t="Die Bestie in der Tiefe",b="Aku'mai haust im tiefsten Herzen des versunkenen Tempels. Die uralte dreiköpfige Hydra dient einem Alten Gott und stieg aus den Wassern empor, nachdem Verderbnis den Mondbrunnen des Tempels befleckt hatte. Zwielichtfürst Kelris und seine Kultisten opfern Aku'mai Unschuldige, um Macht zu erlangen. Streckt Kelris nieder und entzündet die Ritualkerzen in seinem Heiligtum, um den Weg zum Hort der Bestie zu öffnen. Dort können Champions Aku'mai erschlagen, bevor sich sein Unheil über Kalimdor ausbreitet."}},faq={{q="Was war die Tiefschwarze Grotte, bevor sie der Dunkelheit anheimfiel?",a="Die Tiefschwarze Grotte begann als prächtiger Nachtelfentempel, der Elune, der Mondgöttin, geweiht war. Kristallklare Becken, mit Edelsteinen besetzte Brücken und ein gesegneter Mondbrunnen füllten ihre Hallen unter der Aufsicht von Königin Azshara. Dann zerbrach die Große Zerschlagung den Tempel und versenkte ihn unter dem Meer.",al={"geschichte der tiefschwarzen grotte","wer erbaute die tiefschwarze grotte","ursprünglicher tempel"}},{q="Warum sind die Kultisten des Schattenhammers hier?",a="Albtraumhafte Visionen und flüsternde Stimmen aus den Tiefen Azeroths verleiteten die Kultisten dazu, die Alten Götter anzubeten. Unter Zwielichtfürst Kelris bemächtigten sie sich der versunkenen Ruinen und nähren Aku'mai mit lebenden Opfern, in der Hoffnung, die Rückkehr ihrer chaotischen Gebieter zu beschleunigen.",al={"kultisten in der tiefschwarzen grotte","warum ist der schattenhammer hier","was wollen die kultisten"}},{q="Wer ist Zwielichtfürst Kelris?",a="Zwielichtfürst Kelris führt die Zelle des Schattenhammers in der Tiefschwarzen Grotte an. Er strebt die Rückkehr der Alten Götter an, lenkt die Opfergaben des Kults an Aku'mai und überwacht die Entweihung des Tempels.",al={"wer ist kelris","kelris geschichte","anführer der tiefschwarzen grotte"}},{q="Was tun die Naga und Satyrn in den Ruinen?",a="Naga und Satyrn wurden von uralten magischen Energien angezogen, die im ertrunkenen Tempel zurückgeblieben waren. Unter Lady Sarevess schlossen die Naga einen Pakt mit dem Schattenhammer. Die Kultisten liefern Gefangene und dunkles Wissen, während ihre Meereshexen sie vor den Schrecken der Tiefe schützen.",al={"warum sind die naga hier","warum satyrn in der tiefschwarzen grotte","lady sarevess"}},{q="Warum kümmern sich der Irdene Ring und die Argentumdämmerung um diesen Ort?",a="Die Argentumdämmerung entsandte Späher Thaelrid, um mutmaßliche Bündnisse zwischen den Naga und den Kultisten zu untersuchen. Er fand Beweise für ihre mörderischen Rituale. Der Irdene Ring eilte ins Eschental, weil die Anrufung der Alten Götter das elementare Gleichgewicht und die Sicherheit der Welt bedroht.",al={"irder ring eschental","argentumdämmerung tiefschwarze grotte","späher thaelrid"}},{q="Was geschieht, wenn Aku'mai besiegt wird?",a="Aku'mais Tod kappt den unmittelbaren körperlichen Einfluss der Alten Götter im Eschental. Er beendet die Hoffnung des Kults, ihre Herrschaft mithilfe der uralten Hydra wiederherzustellen, versetzt dem Schattenhammer einen schweren Schlag und reinigt einen Teil der dunklen Verderbnis, die den zerstörten Mondbrunnen befällt.",al={"was geschieht wenn man aku'mai tötet","ende von aku'mai","nach dem töten des endbosses"}}},fx={["45e74127"]={q="Was ist die Tiefschwarze Grotte?",a="Die Tiefschwarze Grotte ist ein weitläufiger, teilweise untergetauchter unterirdischer Höhlenkomplex unter dem Zoramstrand entlang des nordwestlichen Eschentals. Einst ein uraltes Heiligtum der Nachtelfen, wurden ihre gefluteten Gänge und Marmorhallen von abscheulichen Mächten überrannt. Heute dient sie als korrumpierte unterirdische Festung, in der sich dunkle Kultisten, schlangenartige Naga und verdrehte Wasserbestien um einen Schrein versammeln, der den chaotischen Alten Göttern gewidmet ist.",al={"was ist die tiefschwarze grotte","was ist blackfathom","über die tiefschwarze grotte"}},["0e7de610"]={q="Warum steht die Tiefschwarze Grotte unter Wasser?",a="Vor zehntausend Jahren riss die katastrophale Große Zerschlagung das uralte Kalimdor auseinander und zertrümmerte die umliegende Küste. Der Tempelkomplex sank unter die Fluten des Verschleierten Meeres, als das Land nachgab. Im Laufe der Jahrtausende verschlang der Ozean den Großteil seiner unteren Hallen und Innenhöfe und verwandelte seine majestätischen Promenaden in ein geflutetes Netzwerk aus unterirdischen Höhlen und Gezeitengrotten.",al={"warum ist sie geflutet","warum ist die tiefschwarze grotte unter wasser","wie ist sie versunken"}},b8724226={q="Warum befinden sich Naga und Murlocs in denselben Ruinen?",a="Beide wurden von den dunklen Energien angezogen, die in den Ruinen erwachten. Die Naga stiegen aus dem Meer empor, um die uralte Macht des zerstörten Tempels zu ergründen, und schlossen einen finsteren Pakt mit dem Kult. Unterdessen folgte der Murlockrieger Gelihast dem Ruf der Alten Götter, bahnte sich seinen Weg hinein und erwarb sich durch rohe Brutalität den Respekt des Kults.",al={"warum naga und murlocs","murlocs in der tiefschwarzen grotte","naga in der tiefschwarzen grotte"}},cd1d34a5={q="Warum ich? Warum einen Fremden schicken anstatt einer Armee?",a="Eine Armee in die versunkenen, gefluteten Höhlen marschieren zu lassen, ist ein logistischer Albtraum, und Fraktionen wie die Argentumdämmerung operieren leise durch Späher, um den Kult nicht zu alarmieren. Ihr verdeckter Späher, Thaelrid, wurde in den Hallen hinterhältig angegriffen und tödlich verwundet. Da die Zeit knapp wird, verlassen sie sich auf fähige, diskrete Champions wie Euch, um Kelris niederzustrecken, bevor die Pläne des Kults Früchte tragen.",al={"warum abenteurer schicken","warum keine armee schicken","warum ich in der tiefschwarzen grotte"}},f5e67a9b={q="Wenn ich Kelris töte, was passiert dann?",a="Kelris' Tod säubert die Höhlen nicht sofort. Wenn Ihr ihn besiegt, hinterlässt er vier zeremonielle Altarkerzen in seinem Sanktum. Das Entzünden dieser Kerzen bricht die Siegel, die die dunklen Schutzzauber des Sanktuums zurückhalten, löst Wellen von Kultverteidigern aus und öffnet den massiven Steineingang, der direkt in Aku'mais inneres Versteck führt.",al={"nach kelris' tod","kelris töten, was passiert dann","was passiert, wenn kelris stirbt"}},f0f9473c={q="Wie bin ich in der Tiefschwarzen Grotte gelandet?",a="Ihr seid Gerüchten über uralte Dunkelheit zum nebligen Zoramstrand im nordwestlichen Eschental gefolgt. Verborgen zwischen den Ruinen der Küste führt ein treppenartiger Schacht in die Erde, der Euch zwingt, durch geflutete Tunnel zu tauchen, um diese ertrunkenen Hallen zu erreichen. Ob von den Nachtelfen von Darnassus entsandt, um vermisste Späher zu finden, vom Schamanen des Irdenen Rings geleitet, um zunehmende elementare Verderbnis zu untersuchen, oder dem Flüstern über Kultisten folgend, die sich unter der Brandung sammeln – Euer Weg führte direkt in das untergetauchte Heiligtum.",al={"wie bin ich hierher gekommen","wie komme ich hier herein","wie habe ich diesen ort gefunden"}},["55d79134"]={q="Wer ist Aku'mai?",a="Aku'mai ist eine monströse, uralte dreiköpfige Hydra und ein Diener eines Alten Gottes. Als die Verderbnis des Alten Gottes aus dem Erdinneren emporquoll und den heiligen Mondbrunnen des Tempels verunreinigte, erhob sich Aku'mai aus den Wassern, und er lauert nun in der tiefsten Höhle der Ruinen. Der Schattenhammer betet die Bestie an und opfert ihr Unschuldige für Macht.",al={"wer ist akumai","was ist akumai","hydraboss bfd"}},["10cbfa4e"]={q="Lebt Aku'mai da unten noch?",a="Ja. Aku'mai haust lebendig in seinem unterirdischen Versteck im Herzen der Ruinen. Die Kultisten des Schattenhammers bewachen die monströse Hydra und opfern ihr gefangene Unschuldige im Austausch gegen dunkle Macht.",al={"lebt akumai","schlaeft akumai","ist akumai noch da unten"}},cc477b61={q="Wer betet Aku'mai an?",a="Aku'mai wird vom fanatischen Schattenhammer-Kult angebetet, der innerhalb der Ruinen von Zwielichtfürst Kelris angeführt wird. Sie verehren die Hydra als Diener ihrer finsteren Meister und glauben, dass ihre Stärkung dazu beitragen wird, das Zeitalter zurückzubringen, in dem die Alten Götter die Welt beherrschten.",al={"wer betet akumai an","akumai-anbeter","kultisten die akumai anbeten"}},e60c1e85={q="Warum scheinen alle so besorgt über diesen Ort zu sein?",a="Wann immer die Alten Götter angerufen werden, droht ganz Azeroth ernste Gefahr. Außenstehende Fraktionen wie die Argentumdämmerung und der Irdene Ring erkennen, dass die Ansammlung von Kultisten, Naga und Satyren unter einem dunklen Banner ein katastrophales Chaos verheißt. Die Rituale, Opferungen und die Anbetung von Aku'mai durch den Kult verderben die umliegenden Gewässer und drohen, den Wahnsinn über das gesamte Eschental zu verbreiten.",al={"warum sorgen um bfd","warum ist blackfathom gefaehrlich","bedrohung durch blackfathom"}},["39220d00"]={q="Was soll ich in der Tiefschwarzen Grotte tun?",a="Ihr seid hier, um den uralten Tempel von den Übeln zu säubern, die in ihm schwelen. Der Schattenhammer-Kult unter Führung von Zwielichtfürst Kelris hat sich mit den örtlichen Naga und Satyren verbündet, um die urzeitliche Bestie Aku'mai anzubeten und zu nähren. Um ihre düsteren Rituale zu stoppen, müsst Ihr die Anführer der Kultisten niederstrecken, der Naga-Zauberei ein Ende setzen, die das Wasser vergiftet, und in das tiefste Heiligtum vordringen, um die monströse Hydra zu erschlagen, bevor der Diener der Alten Götter Chaos über Azeroth entfesseln kann.",al={"was mache ich hier","warum bin ich hier","was ist mein ziel hier","was ist meine mission hier"}}},fp="17,259,23.451.0,24.522.0,21.435.1,56.272.0,44.252.0,28.187.0,47.268.0,62.267.0,38.268.1"}
P.entries["zone:blastedlands"] = {n="Verwüstete Lande",s="In den Verwüsteten Landen wacht Burg Nethergarde über ein vom Dunklen Portal gezeichnetes Ödland. Roter Lehm und kahler Fels bedecken das einstige Black Morass, während Dämonen und Oger der Feste Schreckensfels die Gegend bedrohen.",h="In den Verwüsteten Landen wacht Burg Nethergarde über ein vom Dunklen Portal gezeichnetes Ödland.",kw={"black morass","verwüstete lande","das dunkle portal","drazial","schreckensfels","gromsblut","kum'isha","lord kazzak","lynnore","burg nethergarde","razelikh","die faulende narbe"},ang={["class:Mage"]="Als Magier erkennt Ihr in Burg Nethergardes strengem Einsatz arkaner Magie ihre Wacht gegen die Verderbnis durch Teufelsmagie und die nach Medivhs Fall verbliebenen Dimensionsrisse.",["class:Warlock"]="Als Hexenmeister findet Ihr mächtige Dämonen in der Faulenden Narbe. Zwischen den Felsen haust Daio der Verwelkte. Das Land bietet erfahrenen Hexenmeistern seltene Gelegenheiten, gefährliche Teufelswesen zu binden.",["faction:Alliance"]="Als Mitglied der Allianz findet Ihr in der Gegend nur in Burg Nethergarde einen befestigten Zufluchtsort. Sie schützt die südlichen Gebiete des Königreichs vor Gefahren, die Dämmerwald und Sturmwind bedrohen.",["faction:Horde"]="Als Mitglied der Horde findet Ihr hier keine Festung der Horde. Die Ruinen des Dunklen Portals sind ein düsteres Mahnmal für den Übergang der alten Horde und die Verwüstung durch dämonische Verderbnis.",["profession:Herbalism"]="Als Kräuterkundiger findet Ihr Gromsblut im trockenen roten Lehm der Verwüsteten Lande. Es ist einer der wenigen Orte, an denen es natürlich wächst."},sec={{t="Eine gezeichnete Einöde",b="Einst gehörten die Verwüsteten Lande zum Black Morass, einem ausgedehnten, dichten Sumpfgebiet. Während des Ersten Krieges rissen der Hexenmeister Gul'dan und der besessene Medivh Das Dunkle Portal auf und entfesselten die orcische Horde. Teufelsenergien strömten durch den Riss. Sie entzogen dem Land die Feuchtigkeit und backten es zu rissigem, rotem Lehm.\n\nAm Ende des Zweiten Krieges wurde Das Portal zerstört. Seine Schockwellen versengten den Boden erneut und färbten den einheimischen Stein karminrot."},{t="Nethergardes einsame Wacht",b="Burg Nethergarde wacht von den nördlichen Klippen aus über die einzige Straße ins Tal. Erzmagier Khadgar und der Kirin Tor gaben die steinerne Festung nach dem Zweiten Krieg in Auftrag. Ihre Magier und Soldaten haben geschworen, erneute Einfälle von Dämonen oder Orcs aufzuhalten.\n\nDer Dienst ist streng. Garnisonsmitglieder, die gegen die Regeln verstoßen, werden ins Verlies in Sturmwind verbannt. Die Oger der Feste Schreckensfels blieben nach dem Fall Draenors zurück und setzen die Verteidiger unter Druck. Unter teuflischer Führung überfallen sie die Straßen und greifen die Tore an."},{t="Die Überreste der Legion",b="Die Faulende Narbe durchzieht den südwestlichen Teil der Verwüsteten Lande: eine von Kratern übersäte Schlucht voller Dämonen. Nach der Niederlage der Legion am Hyjal scharte der Verdammniswachenkommandant Lord Kazzak umherstreifende Dämonen, Verdammniswachen und Teufelshunde unter seinem Banner. Sein Schreckenslord-Leutnant Razelikh der Schänder lenkt die Kultisten der Schatten geschworenen am Altar der Stürme und befehligt die örtlichen Oger der Feste Schreckensfels."},{t="Die Macht des Blutes",b="Gelehrte und Wanderer wagen sich weiterhin auf der Suche nach Entdeckungen in die Verwüsteten Lande. Gleich hinter dem nördlichen Pass experimentieren Blutmagier Drazial und Blutmagierin Lynnore mit Organen von Skorpidern, Basilisken und Ebern. Daraus brauen sie starke körperliche Stärkungsmittel.\n\nWeiter im Ödland sucht der Draenei-Eremit Kum'isha nach verstreuten Draenethystsplittern, Überresten aus Draenors zerschmetterter Vergangenheit. Reisende, die sie bergen, erhalten von ihm eine Belohnung."}},faq={{q="Warum ist der Boden rot und karg?",a="Die Verwüsteten Lande waren einst Teil des sumpfigen Black Morass. Die rohe dämonische Magie des Dunklen Portals raubte der Gegend Leben und Feuchtigkeit. Als Das Portal zerstört wurde, verwandelten seine sengende Hitze und chaotischen Energien den Lehm in harte, karminrote Erde.",al={"warum sind die verwüsteten lande rot","warum ist es hier tot","was geschah mit dem sumpf"}},{q="Was ist Das Dunkle Portal?",a="Das Dunkle Portal ist ein gewaltiges Tor zwischen Azeroth und Draenor, der zerschmetterten Heimatwelt der Orcs, die heute als Scherbenwelt bekannt ist. Es wurde zerstört, um die Verbindung zwischen den Welten zu kappen. Doch sein gewaltiger Steinrahmen steht noch immer unter der Wacht von Burg Nethergarde.",al={"wohin führt das dunkle portal","ist das portal offen","was ist das tor"}},{q="Wer kontrolliert Burg Nethergarde?",a="Burg Nethergarde ist eine Bastion der Allianz, die von Magiern des Kirin Tor und Sturmwind treuen Soldaten überwacht wird. Sie wurde nach dem Zweiten Krieg unter der Leitung von Erzmagier Khadgar erbaut. Von dort aus hält man Das Dunkle Portal streng im Auge und wehrt Angriffe naher Oger und Dämonen ab.",al={"wer leitet nethergarde","gehört nethergarde zur allianz","magier von nethergarde"}},{q="Was ist Die Faulende Narbe?",a="Die Faulende Narbe ist eine von Dämonen bevölkerte Schlucht im Süden der Verwüsteten Lande. Sie beherbergt die verbliebenen Streitkräfte der Brennenden Legion in den Östlichen Königreichen. An ihrer Spitze steht der mächtige Verdammniswächter Lord Kazzak, und zu ihnen gehören Verdammniswachen, Teufelswachen und Teufelshunde.",al={"elitegebiet faulende narbe","wer ist in der faulenden narbe","dämonenschlucht verwüstete lande"}},{q="Wer sind die Blutelfen beim Eingang?",a="Blutmagier Drazial und Blutmagierin Lynnore sind Forscher, die untersuchen, wie sich die verdorbene Tierwelt an die raue Teufelslandschaft angepasst hat. Sie tauschen starke Elixiere, die die körperlichen Eigenschaften Sterblicher stärken, gegen Eingeweide, Gehirne und Lungen von einheimischen Basilisken, Geiern, Skorpidern und Ebern.",al={"stärkungstränke der blutelfen","drazial und lynnore","eberlungen-quest"}},{q="Wer ist Kum'isha der Sammler?",a="Kum'isha ist ein Draenei-Mystiker, der im zentralen Ödland lebt. Er sammelt Draenethystsplitter und -kugeln aus Draenor und tauscht versiegelte Pakete mit seltener Ausrüstung und Waren gegen Fundstücke, die man ihm bringt.",al={"draenei in den verwüsteten landen","kum'isha","draenethyst-quest"}},{q="Wie erreicht man die Verwüsteten Lande zu Fuß?",a="Reist durch den Gebirgspass der Totenwinde nach Osten in die Sümpfe des Elends. Folgt der Hauptstraße nach Süden an der Hordensiedlung Steinard vorbei und nehmt dann den schmalen Gebirgspass in die Verwüsteten Lande.",al={"zu den verwüsteten landen gelangen","wie gelangt man dorthin","eingang zu den verwüsteten landen"}},{q="Warum leben Oger in der Wüste?",a="Die Oger der Feste Schreckensfels durchquerten während des Zweiten Krieges Das Dunkle Portal. Statt durch den Riss zurückzukehren, blieben sie, verschanzten sich in der Feste Schreckensfels und gerieten unter die Herrschaft des Schreckenslords Razelikh und des Kults der Schatten geschworenen.",al={"geschichte der oger von schreckensfels","warum sind die oger hier","feste schreckensfels"}}},fp="13,202,19.450.0,26.499.0,20.387.0,22.443.0,33.247.0,24.237.0,30.250.0,25.239.0,50.267.0,30.205.0,43.184.0,41.237.0"}
P.entries["zone:burningsteppes"] = {n="Brennende Steppe",s="Am Südfuß des Schwarzfels haben Feuer und Lava die Brennende Steppe versengt. Das Land birgt den wichtigsten Überlandweg zwischen Sturmwind und Khaz Modan, auf dem feindselige Klans und Drachen Reisende bedrohen.",h="Am Südfuß des Schwarzfels haben Feuer und Lava die Brennende Steppe versengt.",kw={"anduin lothar","schwarzfelsklan","der schwarzfels","schwarzfelsspitze","brennende steppe","schicksalshammer","flammenkamm","morgans wacht","ragnaros","thaurissan"},ang={["faction:Alliance"]="Als Reisender der Allianz betretet Ihr eine düstere, gefährliche Grenzregion, in der der Oberste Befehlshaber Anduin Lothar fiel. Marschall Maxwell in Morgans Wacht sucht tapfere Streiter gegen die Bedrohungen, die auf das Rotkammgebirge vorrücken.",["faction:Horde"]="Als Mitglied von Thralls Neuer Horde wisst Ihr, dass der Flammenkamm den gefährlichen, unbelehrbaren Schwarzfelsklan mit großer Sorge beobachtet. Seine Kriegstreiberei befleckt die Ehre der Orcs.",["profession:Mining"]="Als Bergbauer findet Ihr in diesem Vulkanland seltene Mineralien, darunter reichhaltige Thorium- und Dunkeleisenvorkommen. Die Steppe gehört zu den wenigen offenen Regionen Azeroths, in denen Dunkeleisen abgebaut werden kann.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Steine der Steppe vom Irrweg des Dunkeleisenklans während des Kriegs der Drei Hämmer zeugen. Seine Hauptstadt wurde zerschmettert und Ragnaros beschworen."},sec={{t="Ein katastrophaler Ursprung",b="Die Brennende Steppe war einst der nördliche Teil des Rotkammgebirges. Vor Jahrhunderten, während des Kriegs der Drei Hämmer, errichtete der verbannte Dunkeleisenklan hier Thaurissan als seine Hauptstadt. Als die Niederlage gegen die Klans der Bronzebärte und Wildhämmer drohte, versuchte Zauberer-Thane Thaurissan, Elementarkräfte zu beschwören.\n\nSein Zauber zerschmetterte die umliegenden Berge und brachte Ragnaros den Feuerfürsten nach Azeroth. Lavaströme taten sich auf, und der Schwarzfels erhob sich aus der Erde. Die Explosion hinterließ eine verkohlte, öde Steppe."},{t="Nachhall des Zweiten Krieges",b="Während des Zweiten Krieges wurde die Schwarzfelsspitze zum wichtigsten Machtzentrum der Alten Horde. Gegen Ende des Krieges marschierte die Große Allianz von Lordaeron in die Brennende Steppe und belagerte den Berg. An seinem Fuß streckte Kriegshäuptling Orgrim Schicksalshammer Lord Anduin Lothar nieder.\n\nLothars Tod spornte die alliierten Armeen an, die Orcs in die Flucht zu schlagen und den Krieg zu gewinnen. Asche und verrosteter Stahl kennzeichnen noch immer das Tal, in dem die Schlacht geschlagen wurde."},{t="Eine Brutstätte für Monster und Drachen",b="Schwarzfelsorcs sind noch immer in der Steppe und bewahren die Grausamkeit der Alten Horde trotz Thralls Neuer Horde im fernen Kalimdor. Von der Schwarzfelsfestung aus verbünden sie sich mit dem Schwarzen Drachenschwarm und Feuermägen-Ogern. Sie halten sich an keinen Waffenstillstand.\n\nDunkeleisenzwerge und Elementardiener spuken in den feurigen Ruinen. Schwarze Drachen und Wyrmbrut fallen über Reisende her, die zwischen Sturmwind und den nördlichen Königreichen unterwegs sind."}},faq={{q="Warum ist der Boden verkohlt und mit Lava bedeckt?",a="Vor Jahrhunderten versuchte Zauberer-Thane Thaurissan vom Dunkeleisenklan, einen Elementardiener zu beschwören, um seinen Klan vor der Niederlage im Krieg der Drei Hämmer zu bewahren. Sein Zauber durchbrach versehentlich die Elementarebene und beschwor Ragnaros den Feuerfürsten. Die Explosion riss die Erde auf, ließ den Schwarzfels emporsteigen und versengte den nördlichen Teil des Rotkammgebirges.",al={"warum brennt es hier","was geschah mit der brennenden steppe","warum ist der schwarzfels ein vulkan"}},{q="Gehören die Orcs hier zu Thralls Horde?",a="Nein. Die Schwarzfelsorcs der Brennenden Steppe weigern sich, sich Thralls Neuer Horde anzuschließen. Sie halten keinen Waffenstillstand mit der Allianz und pflegen die wilden, kriegstreiberischen Traditionen des Ersten und Zweiten Krieges. Sie dienen der Schwarzfelsspitze und dem Schwarzen Drachenschwarm.",al={"sind das thralls orcs","gehören schwarzfelsorcs zur horde","warum sind orcs hier feindselig"}},{q="Wo starb Anduin Lothar?",a="Gegen Ende des Zweiten Krieges erschlug Kriegshäuptling Orgrim Schicksalshammer Anduin Lothar am Fuß des Schwarzfels in der Brennenden Steppe. Lothars Tod trieb seinen Stellvertreter Turalyon und die Streitkräfte der Allianz zum Gegenangriff, der die Linien der Horde durchbrach.",al={"wo wurde lothar getötet","lothars todesort","duell zwischen orgrim schicksalshammer und lothar"}},{q="Wo findet die Allianz in der Steppe Schutz?",a="Soldaten und Reisende der Allianz suchen in Morgans Wacht Schutz, einem erhöht gelegenen Außenposten in den südöstlichen Ausläufern des Gebiets. Marschall Maxwell befehligt ihn, überwacht den nördlichen Pass und beobachtet die Truppenbewegungen des Feindes rund um den Berg.",al={"allianzstützpunkt brennende steppe","wo ist der flugpunkt der allianz","ort von morgans wacht"}},{q="Wo bereitet die Horde hier ihre Einsätze vor?",a="Abenteurer der Horde melden sich am Flammenkamm, einem erhöht gelegenen Lager auf dem nordöstlichen Kamm. Seine Gesandten beobachten den rivalisierenden Schwarzfelsklan und unterhalten Flugverbindungen zum Ödland, zu den Sümpfen des Elends, zur Sengenden Schlucht und zu den Flusslanden.",al={"hordenstützpunkt brennende steppe","flammenkamm","wo ist der ort der horde"}},{q="Was sind die Ruinen von Thaurissan?",a="Die Ruinen von Thaurissan sind die Überreste der prächtigen Stadt, die der Dunkeleisenklan nach seiner Verbannung aus Eisenschmiede errichtete. Als Thane Thaurissan Ragnaros beschwor, zerstörte die elementare Explosion seine Hauptstadt und band die Überlebenden an den Willen des Feuerfürsten.",al={"ruinen von thaurissan","was ist die zerstörte zwergenstadt","ruinen in der kartenmitte"}}},fp="15,216,20.517.0,24.428.0,29.389.0,46.338.0,42.250.0,28.268.0,51.237.0,43.237.0,33.248.0"}
P.entries["zone:darkshore"] = {n="Dunkelküste",s="Auberdine verbindet die Dunkelküste mit den Ländern der Nachtelfen und der größeren Allianz. Reisende erreichen diese kalte, neblige Küste im Nordwesten Kalimdors von Teldrassil oder den Östlichen Königreichen aus. Uralte Ruinen und eine beunruhigte Tierwelt prägen das Land, während Kultisten, Naga und eine schleichende Fäulnis es bedrohen.",h="Auberdine verbindet die Dunkelküste mit den Ländern der Nachtelfen und der größeren Allianz.",kw={"ameth'aran","auberdine","bashal'aran","bau der schwarzfelle","cliffspring falls","dunkelküste","die meistergleve","onu","turm von althalaxx"},ang={["class:Druid"]="Als Druide, der auf Rufe aus der Mondlichtung antwortet, erreicht Ihr die Front der Dunkelküste. Ihr untersucht verseuchte Wasserläufe und braut Reinigungsmittel für kranke Waldtiere.",["faction:Alliance"]="Für die Allianz ist Auberdine der wichtigste Handelsknotenpunkt im Norden Kalimdors. Der Hafen hält eine direkte Seeverbindung zwischen Sturmwind und Eisenschmiede sowie Darnassus, der Hauptstadt der Nachtelfen, aufrecht.",["faction:Horde"]="Für die Horde ist die Dunkelküste eine abgelegene Festung der Allianz unter starker Bewachung, nördlich der Lager der Horde im Eschental. Feindselige Schildwachen und gefährliche Kulte durchstreifen ihre tückische Küste.",["race:NightElf"]="Als junger Nachtelf, der Teldrassil verlässt, setzt Ihr Euren ersten Fuß auf das Festland Kalimdors. Uralte Ruinen und sich ausbreitende Verderbnis zeichnen die Wildnis."},sec={{t="Ein Land aus Nebel und Erinnerung",b="Die Dunkelküste liegt unter den westlichen Schatten des Hyjal und des Teufelswalds. Kiefernhainen folgen Nebel und kalte, felsige Küsten. Vor Jahrtausenden blühten hier die Kaldorei-Städte Ameth'Aran und Bashal'Aran. Die Große Zerschlagung zerstörte sie und ließ Säulen und Bögen halb versunken oder von Wurzeln überwuchert zurück. Geister der Hochgeborenen spuken in den Ruinen, während plündernde Murlocs und eindringende Naga zwischen ihnen umherstreifen."},{t="Der Hafen von Auberdine",b="Nach dem Dritten Krieg und der Pflanzung von Teldrassil machten die Nachtelfen Auberdine zu einem geschäftigen Hafen an dieser wilden Küste. Schiffe kommen aus Rut'theran, dem Hafen von Sturmwind und über Süderstade aus dem fernen Hafen von Menethil im Sumpfland. Auberdine verbindet die Länder der Nachtelfen mit dem Rest der Allianz. Schildwachen patrouillieren die Handelsstraße nach Süden ins Eschental, doch ihre kleine Garnison kann die tiefen Wildnisse dahinter nicht überwachen."},{t="Vergiftete Wasser und flüsternde Tiefen",b="Eine langsame, bösartige Fäulnis hat die Dunkelküste unter den östlichen Bergen erreicht. Verderbtes Abwasser aus dem Teufelswald fließt zu Quellen wie Cliffspring Falls, vergiftet das Wasser und treibt Bären, Hirsche und die Furbolgs im Bau der Schwarzfelle in gewaltsamen Wahnsinn.\n\nDie Kultisten des Dark Strand vollziehen am Turm von Althalaxx üble Rituale. Der Schattenhammer sammelt sich um das uralte und furchterregende Monument namens Die Meistergleve."}},faq={{q="Wie komme ich zur Dunkelküste?",a="Reisende der Allianz können von Rut'theran am Fuß von Teldrassil, dem Hafen von Sturmwind oder über Süderstade vom Hafen von Menethil im Sumpfland nach Auberdine segeln. Reisende der Horde müssen auf dem Weg nach Norden das Eschental zu Fuß durchqueren und vom Außenposten von Zoram'gar aus der Hauptstraße nach Nordosten über die Grenze folgen.",al={"zur dunkelküste gelangen","wie man auberdine erreicht","boot zur dunkelküste"}},{q="Was stimmt mit den Tieren und Furbolgs hier nicht?",a="Wasser aus den verseuchten Höhen des Teufelswalds, darunter der Klippenquell, trägt dämonische Verschmutzung in das Grundwasser der Dunkelküste. Das üble Wasser hat die einheimischen Furbolg-Stämme verwildern lassen und Hirsche sowie Raubtiere der Gegend krank und aggressiv gemacht.",al={"warum tiere krank sind","verderbnis der furbolgs","verderbnis an der dunkelküste"}},{q="Was geschah mit Ameth'Aran und Bashal'Aran?",a="Ameth'Aran und Bashal'Aran waren wohlhabende Kaldorei-Zwillingsstädte, die vor zehntausend Jahren während der Großen Zerschlagung zerstört wurden. Ihr Herrscher Athrikus Narassin behauptete, sein Volk vor der Katastrophe retten zu wollen, doch er band ihre Seelen in Edelsteine, um sie selbst als ewige Kraftquellen zu nutzen. Weinende Geister erfüllen die Ruinen.",al={"geschichte von ameth'aran","wissenswertes über bashal'aran","ruinen an der dunkelküste"}},{q="Was ist Die Meistergleve?",a="Im Süden der Dunkelküste ist Die Meistergleve ein riesiger versteinerter Schädel, der von einer gewaltigen Steinwaffe durchbohrt wird. Dieses uralte Relikt steht mit den ursprünglichen Alten Göttern und ihren Dienern in Verbindung. Gefährliche Kultisten des Schattenhammers werden davon angezogen.",al={"was ist die meistergleve","riesiger schädel an der dunkelküste","monster der meistergleve"}},{q="Wer ist der riesige Baum im Hain der Uralten?",a="Der riesige Baum im Hain der Uralten ist Onu, ein weiser und ehrwürdiger Uralter des Wissens. In seinem stillen Hain südlich von Auberdine erwägt er den beunruhigenden Vormarsch des Schattenhammers und hilft Reisenden, Störungen im Wald zu untersuchen.",al={"uralter des wissens an der dunkelküste","wer ist onu","baumwesen an der dunkelküste"}},{q="Wer lebt im Turm von Althalaxx?",a="Der Dark Strand, ein grausamer Kult, der dunkle Zauberei praktiziert und Dämonen beschwört, besetzt den Turm von Althalaxx. Seine Mitglieder überfallen arglose Reisende in den nördlichen Küstenwäldern.",al={"turm von althalaxx","kultisten im turm an der dunkelküste","althalaxx-kult"}}},fx={d345bcc9={q="Wer lebt hier derzeit?",a="Nachtelfen unterhalten die Siedlung Auberdine zusammen mit besuchenden Händlern der Allianz, darunter Zwerge und Menschen. Außerhalb der Stadt ist die Wildnis von feindseligen Naga, Troggs, verdorbenen Furbolgs und Überresten dunkler Kulte besetzt, die zwischen den uralten Steinen lauern.",al={"wer bewohnt die dunkelküste","bevölkerung der dunkelküste","wer lebt an der dunkelküste"}},["137b9ce8"]={q="Was ist Auberdine?",a="Auberdine ist eine ruhige Küstensiedlung und der wichtigste Hafen der Allianz im nördlichen Kalimdor. Mit seinen niedrigen hölzernen Elfenhallen, Erdwegen und einem markanten Hafenleuchtturm verbindet es Darnassus über das Wasser mit dem Festland und den Östlichen Königreichen.",al={"stadt auberdine","erzähl mir von auberdine","was ist die stadt an der dunkelküste"}},f41ff152={q="Wer verwaltet Auberdine?",a="Die zivilen Angelegenheiten von Auberdine werden vom Ältesten Thundris Windwirker geleitet, unterstützt vom Dorfrat von Auberdine. Die militärische Wache der Stadt wird von den Schildwachen übernommen, wobei Offiziere wie Schildwache Glynda Nal'Shea lokale Patrouillen und Verteidigung koordinieren.",al={"anführer von auberdine","wer hat in auberdine das sagen","dorfrat von auberdine"}},["5f65caea"]={q="Warum ist es an der Küste gebaut?",a="Nachdem die Nachtelfen nach dem Dritten Krieg zurückkehrten, wählten sie diesen Ort, um den Schiffsverkehr und die Versorgungslinien wiederzubeleben. Der Hafen bietet eine wichtige Fährverbindung zum Dorf Rut'theran auf Teldrassil und empfängt Fernhandelsschiffe, die vom Hafen von Menethil in den Östlichen Königreichen kommen.",al={"warum auberdine am strand bauen","zweck des hafens von auberdine","warum auberdine küste"}},["451a86e7"]={q="Wer hat hier das Sagen?",a="Die Nachtelfen beanspruchen die Dunkelküste als Teil ihres aufstrebenden Königreichs. Der Älteste Thundris Windwirker überwacht zivile Angelegenheiten von Auberdine aus, während die Schildwachen der Nachtelfen das militärische Kommando entlang der Küstenstraße und der regionalen Grenzen innehaben.",al={"wer regiert die dunkelküste","wer kontrolliert die dunkelküste","führung der dunkelküste"}},f5d3cc9f={q="Wer sind die Schildwachen?",a="Die Schildwachen sind das traditionelle stehende Heer der Kaldorei, das hauptsächlich aus Elite-Kriegerinnen der Nachtelfen besteht. Sie patrouillieren die Straßen, bewachen Siedlungen wie Auberdine und verteidigen das Elfenland vor eindringenden Monstern und Invasoren.",al={"armee der schildwachen","schildwachen der nachtelfen","was sind die schildwachen"}},["435217d7"]={q="Unterstehen sie Darnassus?",a="Ja. Die Verteidiger der Dunkelküste sind der Führung der Kaldorei verpflichtet, die in Darnassus auf Teldrassil residiert, obwohl die hohen Autoritäten der Hauptstadt die raue Grenzstadt Auberdine manchmal als einen abgelegenen Außenposten für Ausgestoßene und Außenseiter betrachten.",al={"dienen schildwachen darnassus","autorität von darnassus dunkelküste","untersteht auberdine darnassus"}},["709b4618"]={q="Warum gibt es so viele Schiffswracks am Strand?",a="Die Dunkelküste ist berüchtigt für brutales Wetter, starken Regen, dichten Meeresnebel und zerklüftete Untiefen. Böige Winde entfachen plötzliche Wellen, die Schiffe auf die Felsen treiben, wodurch die flachen Gewässer mit Wracks übersät sind, die die Passage nach Auberdine nicht erfolgreich bewältigten.",al={"schiffswracks an der dunkelküste","warum sind hier schiffe gestrandet","versunkene boote dunkelküste"}},["9d4c460f"]={q="Warum suchen die Hochgeborenen diese Ruinen heim?",a="Vor zehntausend Jahren waren die Hochgeborenen der magische Adel von Königin Azshara, die Zwillingsstädte wie Ameth'Aran und Bashal'Aran regierten. Als das Große Auseinanderbrechen ihr Imperium zerschmetterte, fing ihre Herrscherin ihre Seelen in Bindungsjuwelen ein und ließ ihre gequälten Geister für die Ewigkeit die Steinsäulen heimsuchen.",al={"warum sind hier geister der hochgeborenen","geister von ameth'aran","wer waren die hochgeborenen"}},c8232ccb={q="Was hat den Schwarzholzstamm verdorben?",a="Obwohl sie einst freundliche Nachbarn der Nachtelfen waren, wurden die Furbolgs des Schwarzholzstammes durch dunkle Verderbnis in einen unstillbaren Wahnsinn getrieben. Flüsse, die von den verseuchten Höhen des Teufelswaldes herabfließen, tragen vergiftetes Wasser durch die Dunkelküste und verzerren die Geister von Bestien und Furbolgs gleichermaßen.",al={"furbolgs vom schwarzholzstamm verrückt","warum sind furbolgs an der dunkelküste wahnsinnig","quelle der furbolg-verderbnis"}},a33e07d8={q="Wer ist der Kult der Schattenhammer und warum lagern sie hier?",a="Der Kult der Schattenhammer ist ein nihilistischer, apokalyptischer Kult, der sich den dunklen Entitäten verschrieben hat, die als die Alten Götter bekannt sind. Sie haben sich am The Master's Glaive im Süden der Dunkelküste versammelt und führen Rituale und Ausgrabungen rund um uralte unterirdische Überreste durch, die tief unter der Erde begraben liegen.",al={"kult des schattenhammers dunkelküste","kultisten an der dunkelküste","warum sind kultisten des schattenhammers hier"}},b665bd5a={q="Warum ist die Dunkelküste gefährlich?",a="Jenseits der unmittelbaren Grenzen von Auberdine ist die Küste voller Gefahren. Wilde Bestien und aufgebrachte Furbolgs streifen durch die Bäume, Naga und Murlocs befallen die Strände und zwielichtige Kulte wie der Dark Strand und der Kult der Schattenhammer lauern Reisenden aus versteckten Außenposten auf.",al={"ist die dunkelküste sicher","bedrohungen der dunkelküste","gefahren der dunkelküste"}},["9cbaedb5"]={q="Warum wird sie Dunkelküste genannt?",a="Die Küste erhielt ihren Namen von den dichten, schattigen Wäldern und dem düsteren, ungewöhnlichen Nebel, der die gesamte Küstenlinie bedeckt, das Tageslicht verdunkelt und die Strände in ewige Trübnis taucht.",al={"warum heißt es dunkelküste","namensursprung dunkelküste","warum wird es dunkelküste genannt"}},c5ede25e={q="Wie bin ich auf der Dunkelküste gelandet?",a="Ihr seid wahrscheinlich über Auberdine angekommen, den geschäftigen Küstenhafen und Handelsknotenpunkt, der den Norden Kalimdors mit der weiteren Welt verbindet. Falls Ihr von den Zweigen Teldrassils gereist seid, hat Euch eine Fähre über die nebelverhangenen Gewässer vom Dorf Rut'theran zu den Docks auf dem Festland gebracht. Reisende, die aus den Östlichen Königreichen kommen, unternehmen oft die lange Reise an Bord der großen Segelschiffe vom Hafen von Menethil. Alternativ folgen hartgesottene Wanderer, die über Land aus den tiefen Wäldern des Eschentals kommen, der bewachten Straße der Schildwachen nach Norden auf die felsige, nebelverhangene Küste.",al={"wie bin ich hierhergekommen","wie komme ich zur dunkelküste","wie bin ich hier angekommen"}},["7cfc9767"]={q="Was ist die Dunkelküste?",a="Die Dunkelküste ist ein langer, nebliger Streifen felsiger Küste entlang des nordwestlichen Kalimdor. Geschützt unter Bergen im Osten und dem Verschleierten Meer im Westen bietet sie schattige Wälder, regenverpeitschte Strände und zerfallende Elfenruinen. Sie dient den Nachtelfen als primäres Tor zwischen ihrer Inselheimat Teldrassil und dem Festland.",al={"erzähl mir von der dunkelküste","was für ein gebiet ist die dunkelküste","übersicht zur dunkelküste"}},["0d623756"]={q="Warum sieht sie so zerstört und düster aus?",a="Ein Großteil der Dunkelküste wurde vor zehntausend Jahren während der Großen Zerschlagung zerstört, was große Kaldorei-Städte in Trümmer legte. Heute verleihen ein allgegenwärtiger Meeresnebel, stürmische Winde und schleichende magische Verschmutzung, die von verseuchten Gebirgsflüssen herabfließt, der Küste ihre beständige, trauervolle Atmosphäre.",al={"warum ist die dunkelküste düster","warum ist die dunkelküste zerstört","dunkelküste zerstört"}},c840edc2={q="Was soll ich an der Dunkelküste tun?",a="Die Nachtelfen in Auberdine benötigen dringend Hilfe, um ein sich an der Küste ausbreitendes Unheil einzudämmen. Eine üble Verderbnis, die von den Höhen des Teufelswalds herabsickert, hat die Flüsse und das Grundwasser vergiftet und treibt die einheimische Tierwelt sowie die friedlichen Furbolgs der Schwarzfelle in gewalttätigen Wahnsinn. Jenseits der Wälder regen sich in uralten Hochgeborenen-Ruinen wie Ameth'Aran rastlose Geister, Naga und Murlocs dringen an den felsigen Stränden vor, und finstere Kultisten des Schattenhammers versammeln sich um das uralte Monument der Meistergleve. Der Dorfrat von Auberdine und die Schildwachen verlassen sich auf Reisende wie Euch, um das Gleichgewicht wiederherzustellen.",al={"warum bin ich hier","was soll ich an der dunkelkueste tun","was ist meine aufgabe hier"}}},fp="9,278,25.396.0,22.414.0,37.419.0,26.297.0,51.247.0,44.314.1,28.235.0,51.239.0,36.182.0"}
P.entries["zone:darkspearislands"] = {n="Darkspear-Inseln",s="Horde und Allianz kämpfen auf den Darkspear Islands vor der Küste Kalimdors. Die zeremoniellen Inseln sind den Trollen Vol'jins heilig, während die Allianz an der Küste Fuß fassen und den Stolz der Horde treffen will. Den Sieg erringt, wer die Stützpunkte hält, die Flagge der Darkspear Islands erobert und zuerst 2000 Ressourcen sammelt.",h="Horde und Allianz kämpfen auf den Darkspear Islands vor der Küste Kalimdors.",kw={"darkspear islands","dunkelspeer","schlachtfeld","zeremonieninseln","flagge der darkspear islands","die schiffbruchgrotte","verlassener turm","ressourcen","vol'jin","loa"},ang={["faction:Alliance"]="Für Soldaten der Allianz ist jeder eroberte Stützpunkt auf den Darkspear Islands ein Brückenkopf vor der Küste Kalimdors und ein Schlag gegen eines der stolzesten Völker der Horde.",["faction:Horde"]="Jeder Kämpfer der Horde an diesen Küsten verteidigt ein Versprechen. Die Dunkelspeer standen Thrall bei, als die Horde kaum etwas anderes hatte. Ihre heiligen Inseln werden nicht fallen, solange die Horde eine Klinge halten kann.",["race:Troll"]="Dies sind die Zeremonienplätze Eures Volkes. Jedes Banner der Allianz, das hier gehisst wird, beleidigt die Loa und Sen'jins Andenken. Jedes Banner, das Ihr niederreißt, ist ein erhörtes Gebet."},sec={{t="Heilige Inseln der Dunkelspeer",b="Die Dunkelspeer sind ein Inselvolk. Von größeren und grausameren Rivalen aus dem Schlingendorntal vertrieben, fanden sie auf den Inseln der südlichen Meere eine neue Heimat. Diese Inseln vor der Küste Kalimdors bewahren sie für ihre Riten und die Loa, die sie ehren.\n\nAuf Inseln wie diesen fand Thralls sturmgeschüttelte Flotte Sen'jins Volk, bedrängt von Kul Tiranern, Murlocs und einer Seehexe. Dort schworen die Trolle erstmals der Horde die Treue. Für einen Dunkelspeer bedeutet ein feindliches Banner über den Zeremonienplätzen Entweihung und Niederlage zugleich."},{t="Zwei Seiten, zwei Gründe",b="Für die Horde ist die Verteidigung der Inseln eine Ehrenschuld. Die Dunkelspeer standen Thrall bei, als die Horde kaum etwas anderes hatte. Deshalb kämpfen Orks, Tauren und Verlassene an ihrer Seite, um den heiligen Boden der Trolle zu bewahren. Für die Allianz sind diese Inseln ein Brückenkopf vor der Küste Kalimdors und eine Möglichkeit, die Horde dort zu treffen, wo ihr Stolz am tiefsten sitzt. Keine Seite spricht von Frieden. Auf jede Landung folgt eine Antwort, und um jedes gefallene Lager wird erneut gekämpft."},{t="Der Verlauf der Schlacht",b="Zahlen allein reichen nicht, um die Inseln zu halten. Die Kämpfe reichen vom Lager und den alten Ruinen bis zum Verlassenen Turm und zur Schiffbruchgrotte. Jede Seite häuft Ressourcen an, indem sie die Stützpunkte erobert und hält. Die Flagge der Darkspear Islands kann das Blatt wenden. Die erste Seite, die 2000 Ressourcen sammelt, gewinnt den Tag und treibt ihre Feinde zurück zu ihren Schiffen, bis zur nächsten Landung."}},faq={{q="Was ist das Schlachtfeld Darkspear Islands?",a="Die Darkspear Islands sind ein Schlachtfeld auf den zeremoniellen Inseln der Dunkelspeertrolle vor der Küste Kalimdors. Streitkräfte der Horde und der Allianz kämpfen darum, die Stützpunkte zu halten, die Flagge der Darkspear Islands zu erobern und zuerst 2000 Ressourcen zu sammeln.",al={"was sind die darkspear islands","schlachtfeld darkspear islands","pvp auf den darkspear islands"}},{q="Warum kämpft die Horde um die Darkspear Islands?",a="Die Inseln sind den Dunkelspeertrollen heilig, dem Volk Vol'jins. Sie schlossen sich der Horde an, nachdem Thralls Flotte sie bedrängt von Kul Tiranern, Murlocs und einer Seehexe vorfand. Würde die Allianz ihre Zeremonienplätze einnehmen, wären sie entweiht. Deshalb kämpft die Horde, um sie zu bewahren.",al={"warum verteidigt die horde die darkspear islands","interessen der horde auf den darkspear islands","warum kämpfen die trolle dort"}},{q="Warum kämpft die Allianz auf den Darkspear Islands?",a="Für die Allianz sind die Inseln ein Brückenkopf vor der Küste Kalimdors und eine Gelegenheit, eines der stolzesten Völker der Horde anzugreifen. Jeder eroberte Stützpunkt ist Boden, den die Horde zurückerobern muss.",al={"warum greift die allianz die darkspear islands an","interessen der allianz auf den darkspear islands","grund der allianz für darkspear"}},{q="Wie gewinnt man die Schlacht um die Darkspear Islands?",a="Jede Seite erobert und hält die Stützpunkte der Inseln, häuft so Ressourcen an und versucht, die Flagge der Darkspear Islands zu erobern. Die erste Seite, die 2000 Ressourcen sammelt, gewinnt.",al={"ziele auf den darkspear islands","wie gewinnt man auf den darkspear islands","flagge der darkspear islands"}},{q="Wo wird auf den Inseln gekämpft?",a="Die Kämpfe erstrecken sich über die Inseln, vom Lager und den alten Ruinen bis zum Verlassenen Turm und zur Schiffbruchgrotte. Der Kampf um jeden Ort endet selten mit einem einzigen Angriff.",al={"orte auf den darkspear islands","die schiffbruchgrotte","verlassener turm"}},{q="Wer sind die Dunkelspeertrolle?",a="Die Dunkelspeer sind ein Stamm von Dschungeltrollen, angeführt von Vol'jin. Aus dem Schlingendorntal vertrieben, fanden sie auf den Inseln der südlichen Meere eine neue Heimat, bis Thralls Flotte sie fand. Seither dienen sie der Horde treu, von Sen'jin in Durotar bis an jede Front ihrer Kriege.",al={"darkspear tribe","wer sind die dunkelspeer","trolle vol'jins"}}},fp="17,348,29.519.0,22.417.0,23.392.0,43.238.0,51.274.0,53.195.0,48.184.0,46.174.0,29.291.0"}
P.entries["zone:darnassus"] = {n="Darnassus",s="Hoch oben in den Ästen von Teldrassil liegt Darnassus, die Stadt der Nachtelfen. Tyrande Wisperwind und die Druiden leiten sie. Ihr Volk ist uralt, doch nun sterblich. Es muss lernen, ohne das ewige Leben auszukommen, und sucht neue Bande zur Allianz.",h="Hoch oben in den Ästen von Teldrassil liegt Darnassus, die Stadt der Nachtelfen.",kw={"die enklave des cenarius","darnassus","fandral","hauptstadt der nachtelfen","rut'theran","hirschhaupt","teldrassil","tempel des mondes","tyrande","wisperwind"},ang={["class:Druid"]="Die Enklave des Cenarius ist das Zentrum der Druidenlehre auf Teldrassil, wo Erzdruide Fandral Hirschhaupt streng und unbeugsam über die Ausbildung wacht.",["class:Priest"]="Der Tempel des Mondes ist das heilige Zentrum der Schwestern von Elune unter der Führung von Hohepriesterin Tyrande Wisperwind.",["faction:Alliance"]="Darnassus ist die westlichste Festung der Allianz und bietet auf Kalimdor Schutz für Flotte und Strategie.",["race:NightElf"]="Als Nachtelf habt Ihr in Darnassus das Herz und die Zuflucht Eures Volkes, während Ihr Euch den Prüfungen des sterblichen Lebens stellt."},sec={{t="Eine Krone hoch in den Ästen",b="Darnassus erstreckt sich über das obere Blätterdach des Weltbaums, vor der Küste im Norden Kalimdors. Seine hölzernen Hallen und gewundenen Pfade umschließen einen stillen See. Brücken verbinden die Terrassen der Händler und Handwerker sowie der Schildwachen und Druiden. Die Wildnis ist im Alltag der Stadt stets nah."},{t="Zuflucht eines sterblichen Volkes",b="Gemessen an der langen Geschichte der Kaldorei ist Darnassus jung. Im Dritten Krieg wurde Nordrassil geopfert, und die Nachtelfen lernten Alter und Krankheit kennen. Erzdruide Fandral Hirschhaupt und seine Anhänger pflanzten daraufhin Teldrassil in der Hoffnung, ihre verlorene Lebenskraft zurückzugewinnen. Zwischen seinen Ästen wuchs die Stadt heran, als Zuflucht und Denkmal ihres Überlebens. Doch schon regt sich Unheil zwischen den Wurzeln."},{t="Ein gespaltenes Heim",b="Zwei Mächte bestimmen über Darnassus. Vom Tempel des Mondes aus befehligt Hohepriesterin Tyrande Wisperwind die Schildwachen und leitet den Glauben ihres Volkes. Jenseits der Wasserwege führt Fandral die Druiden, denn Malfurion Sturmgrimm ist im Smaragdgrünen Traum verschollen. Ihren neuen Verbündeten in der Allianz zeigen die beiden Anführer Einigkeit. Doch zwischen Priesterinnen und Druiden schwelt weiterhin Zwietracht."}},faq={{q="Wie gelangt man vom Festland nach Darnassus?",a="Teldrassil liegt vor der Nordwestküste Kalimdors. Reisende erreichen Rut'theran am Fuß des Baumes per Schiff oder Flug. Ein leuchtendes magisches Portal an den Docks des Dorfes bringt sie hinauf nach Darnassus.",al={"wie kommt man nach darnassus","reise nach darnassus","eingang von darnassus"}},{q="Wer herrscht über Darnassus?",a="Hohepriesterin Tyrande Wisperwind herrscht vom Tempel des Mondes aus über Darnassus und die Kaldorei. Erzdruide Fandral Hirschhaupt führt die Druiden von der Enklave des Cenarius aus, während Malfurion Sturmgrimm im Smaragdgrünen Traum verschollen bleibt.",al={"anführer von darnassus","wer hat das sagen","herrscher von darnassus"}},{q="Warum wurde die Stadt erst vor Kurzem gegründet?",a="Darnassus wurde kurz nach dem Dritten Krieg gegründet. Die Nachtelfen opferten ihre Unsterblichkeit, um Archimonde am Hyjal zu besiegen. Fandral Hirschhaupt drängte sie, Teldrassil wachsen zu lassen, in der Hoffnung, ihren früheren Zustand wiederzuerlangen, während Malfurion Sturmgrimm im Smaragdgrünen Traum verschollen war. Zwischen den Ästen des Baumes errichteten sie Darnassus als neue Zuflucht.",al={"warum ist darnassus neu","wann wurde darnassus erbaut","geschichte von darnassus"}},{q="Wo ist Erzdruide Malfurion Sturmgrimm?",a="Malfurion Sturmgrimm wird im Smaragdgrünen Traum vermisst, wo sein Geist gefangen ist. Erzdruide Fandral Hirschhaupt führt während seiner Abwesenheit die Druiden von Teldrassil, während Tyrande Wisperwind nach einem Weg sucht, ihren geliebten Gefährten zu erwecken und zurückzuholen.",al={"wo ist malfurion","ist malfurion in darnassus","malfurions aufenthaltsort"}},{q="Wo befinden sich die Lehrer für Berufe und die Läden?",a="Auf den Terrassen von Darnassus befinden sich die Lehrer und Läden der Stadt. Auf der Terrasse der Handwerker gibt es Lehrer für Sammelberufe und Schneiderei sowie ein Gasthaus. Auf der Terrasse der Händler befinden sich Marktstände und das Auktionshaus. Lehrer für Schmiedekunst und Kampfberufe findet Ihr auf der Terrasse der Krieger. Die Bank steht auf der zentralen Insel der Tempelgärten.",al={"berufe in darnassus","auktionshaus in darnassus","bank in darnassus"}},{q="Warum schlossen sich die Nachtelfen der Allianz an?",a="Nach dem Dritten Krieg gerieten die Nachtelfen zunehmend unter Druck durch die Horde, besonders durch die Holzfäller der Orcs im Eschental. Darnassus knüpfte diplomatische Beziehungen und schloss sich der Großen Allianz an, um Verbündete gegen diese Übergriffe und andere wachsende Bedrohungen in ganz Kalimdor zu finden.",al={"warum sind die nachtelfen in der allianz","bande zwischen nachtelfen und allianz","allianz und darnassus"}}},fx={c2a87a41={q="Was ist Darnassus?",a="Darnassus ist die Hauptstadt der Nachtelfen, hoch oben in den Zweigen des großen Weltenbaums Teldrassil gelegen. Sie wurde kürzlich nach dem Dritten Krieg gegründet und dient als friedlicher Zufluchtsort. Ihre offenen Terrassen, Brücken und ruhigen Haine umgeben einen großen zentralen See und spiegeln die tiefe Ehrfurcht der Nachtelfen vor der Natur und Elune wider.",al={"was ist diese stadt","erzähl mir von darnassus","wissen über darnassus"}},a1b472ac={q="Wer hat Darnassus erbaut?",a="Die Stadt wurde von den Nachtelfen nach dem Dritten Krieg unter der Leitung des Erzdruiden Fandral Hirschhaupt und der Druiden, die Teldrassil pflanzten, gegründet. Sie wurde mit feinen Holzlogen, geformtem Stein und lebenden Zweigen erbaut, um das Überleben der Kaldorei nach ihrem Opfer am Hyjal zu ehren.",al={"wer erschuf darnassus","wer gründete darnassus"}},["9187c5ce"]={q="Warum liegt Darnassus in einem Baum?",a="Nachdem die Zerstörung von Nordrassil am Hyjal den Nachtelfen ihre Unsterblichkeit raubte, pflanzten Fandral Hirschhaupt und andere Druiden Teldrassil vor der Küste des nördlichen Kalimdors, in der Hoffnung, ihr ewiges Leben wiederherzustellen. Darnassus wurde direkt innerhalb seiner riesigen, hoch aufragenden Krone errichtet, um als abgelegener Zufluchtsort fernab der Gefahren des Festlands zu dienen.",al={"warum liegt es in einem baum","warum teldrassil"}},["03a6f12c"]={q="Wo ist Tyrande Wisperwind?",a="Die Hohepriesterin Tyrande Wisperwind residiert im The Temple of the Moon auf der Südseite von Darnassus. Von diesem mondbeschienenen Heiligtum aus beaufsichtigt sie die Schwesternschaft der Elune und regiert die Gesellschaft der Kaldorei.",al={"wo ist tyrande","tyrande finden"}},bbc7c157={q="Wer ist Fandral Hirschhaupt?",a="Fandral Hirschhaupt ist der amtierende Erzdruide, der den Zirkel des Cenarius in Darnassus leitet, während Malfurion Sturmgrimm vermisst wird. Er setzte sich für die Pflanzung von Teldrassil ein und vertritt aggressive, expansionistische Ansichten für die Kaldorei, die häufig mit denen der Hohepriesterin Tyrande Wisperwind kollidieren.",al={"erzdruide fandral hirschhaupt","wer ist fandral"}},["2b5108ff"]={q="Was ist der Tempel des Mondes?",a="Der Tempel des Mondes ist das große Zentrum der spirituellen Anbetung in Darnassus und der offizielle Sitz der Regierung der Kaldorei. Als Heimstatt der Schwesternschaft der Elune und der Hohepriesterin Tyrande Wisperwind wurde er nach dem Dritten Krieg aus Stein erbaut, der auf magische Weise vom Festland herbeigebracht wurde.",al={"tempel der elune darnassus","was ist der mondtempel"}},["4096dbf8"]={q="Wer ist Elune?",a="Elune ist die verehrte Mondgöttin der Nachtelfen, die mit Frieden, Heilung und dem Nachthimmel assoziiert wird. Die Kaldorei richten ihr spirituelles Leben nach ihrer Anbetung aus, geleitet von ihrer Hohepriesterin und der Schwesternschaft der Elune.",al={"göttin elune","was ist elune"}},e87e3fa7={q="Warum befindet sich ein Brunnen im Tempel des Mondes?",a="Im Zentrum des Tempels liegt ein heiliger Mondbrunnen unter der Statue von Haidene. Sein gesegnetes Wasser gilt als die Berührung Elunes selbst und wird von der Schwesternschaft der Elune zum Baden, zur Genesung und für heilige Riten genutzt.",al={"becken im tempel des mondes","brunnen der elune darnassus"}},["0e74b3a4"]={q="Was ist die Enklave des Cenarius?",a="Die Enklave des Cenarius ist ein üppiger Hain im Nordwesten von Darnassus, wo sich die Druiden der Stadt treffen und ausbilden. Gesäumt von uralten Bäumen, die mystische Runen tragen, beherbergt er das Heiligtum aus lebendem Holz von Erzdruide Fandral Hirschhaupt und dient als Versammlungsort für den Zirkel des Cenarius.",al={"enklave des cenarius darnassus","wo sind druiden in darnassus"}},e546b5d1={q="Warum ist Fandral Hirschhaupt der Erzdruide und nicht Malfurion?",a="Erzdruide Malfurion Sturmgrimm verschwand auf mysteriöse Weise nach dem Dritten Krieg in den Smaragdgrünen Traum. In seiner Abwesenheit trat Fandral Hirschhaupt vor, um das Kommando über die Druiden zu übernehmen und die Pflanzung von Teldrassil anzuführen.",al={"warum führt fandral","warum ist malfurion nicht erzdruide"}},c7c576ca={q="Ist Darnassus gefährlich?",a="Darnassus selbst ist ruhig und wird stark von Nachtelfen-Wächterinnen, turmhohen Uralten Beschützern und Uralten des Krieges bewacht. Die Stadt bleibt ein friedlicher Zufluchtsort für die Allianz, obwohl in der umliegenden Wildnis von Teldrassil Unruhen und Verderbnis schwelen.",al={"ist darnassus sicher","bedrohungen in darnassus"}},["6a190c74"]={q="Wie bin ich in Darnassus gelandet?",a="Wenn Ihr ein Nachtelf seid, begann Eure Reise wahrscheinlich im Laubschattental, von wo Ihr durch Dolanaar herabgestiegen seid, bevor Ihr der Waldstraße nach Westen über die Äste von Teldrassil zu den Toren der Hauptstadt gefolgt seid. Reisende von außerhalb kommen stattdessen weit unterhalb mit dem Schiff vom Festland an und legen in Rut'theran am Fuße des Weltenbaums an, bevor sie durch das leuchtende verzauberte Portal treten, das sie direkt hinauf in die Stadt befördert.",al={"wie bin ich hierher gekommen","wie kam ich in darnassus an","wie kam ich nach darnassus"}},["2586ce4f"]={q="Was soll ich in Darnassus tun?",a="Darnassus dient als politisches und spirituelles Herz der Kaldorei. Abenteurer kommen hierher, um Rat bei der Führung zu suchen – bei Hohepriesterin Tyrande Wisperwind im Tempel des Mondes oder Erzdruide Fandral Hirschhaupt in der Enklave des Cenarius –, während sie Waffenmeister, Klassenlehrer und Handwerker auf den verschiedenen Terrassen aufsuchen. Ob Ihr in die Wildnis geschickt werdet, um die Verderbnis zu reinigen, die Teldrassil befällt, oder Euch darauf vorbereitet, über die Ufer hinaus zum unruhigen Festland zu reisen, die Stadt bietet die Vorräte, Unterweisungen und Dekrete, die Ihr benötigt.",al={"was mache ich hier","warum bin ich in darnassus","was soll ich in darnassus tun"}}},fp="9,270,28.281.0,25.386.0,16.380.0,49.204.0,20.227.0,37.344.0,39.235.0,52.319.0,42.260.0"}
P.entries["zone:deadmines"] = {n="Todesminen",s="Tief unter dem staubigen Bauerndorf Mondbruch liegen die Todesminen, ein gewaltiger unterirdischer Komplex, der einst ein Drittel der Goldreserven Sturmwinds lieferte. Während des Ersten Krieges verlassen und lange Zeit als verflucht angesehen, wurden diese labyrinthischen Tunnel insgeheim von der Bruderschaft der Defias als ihr zentrales Aufmarschgebiet übernommen. Hier arbeiten Edwin van Cleef und seine zwangsverpflichteten Gobliningenieure fernab der Augen des Reiches an einer Waffe der Rache gegen das Königreich.",h="Tief unter dem staubigen Bauerndorf Mondbruch liegen die Todesminen, ein gewaltiger unterirdischer Komplex...",kw={"cookie","die todesminen","defias","edwin van cleef","ironcladbucht","juggernaught","mondbruch","handlanger pein","vancleef","westfall"},ang={["class:Paladin"]="Diese geschändeten Schächte sind eine Prüfung für Tapferkeit und Glauben und erinnern an die historischen Prüfungen von Sir Anduin Lothar sowie die verlorenen Bergleute, deren rastlose Tote noch immer durch die äußeren Stollen wandeln.",["faction:Alliance"]="Die Todesminen stellen die schwerste innere Bedrohung für das Königreich von Sturmwind dar; van Cleef zur Strecke zu bringen, ist der entscheidende Sieg, der den bedrängten Bauern von Westfall wieder Hoffnung schenkt.",["profession:Engineering"]="Die Goblin Gießerei und Sneeds mechanische Werkstatt bieten einen Einblick in modernste Dampfschredder, ferngesteuerte Golems und Spezialmunition.",["profession:Mining"]="Einst lieferten die felsigen Stollen ein Drittel des Reichtums der Hauptstadt und sind noch immer reich an Adern aus Kupfer, Zinn und wertvollem Silber."},sec={{t="Ein Erbe aus Gold und Ruin",b="Vor dem Ersten Krieg galten die Todesminen als das ergiebigste Goldförderzentrum in den Ländern der Menschen und finanzierten den Wohlstand von Sturmwind. Als die orkische Horde das Königreich überrannte und die Hauptstadt dem Erdboden gleichmachte, wurden die Minen hastig der Dunkelheit überlassen. In jenen turbulenten Jahren durchschritten legendäre Gestalten diese Tiefen: Sir Anduin Lothar wurde zwanzig Monate lang von unterirdischen Ogern gefangengehalten, während er den heiligen Foliant der Offenbarung barg, und Kriegshäuptling Schwarzfausts rebellische Tochter Griselda floh an der Seite des Ogers Turok in die unteren Gänge, bevor beide ihr Ende fanden. Man glaubte, die Tiefen seien verflucht und nur noch von schlurfenden Untoten sowie lauerndem unterirdischem Ungeziefer bevölkert, und so blieben sie jahrzehntelang unberührt."},{t="Das Sanktum der Bruderschaft",b="Als die Gilde der Steinmetze nach dem Wiederaufbau der Stadt ohne Bezahlung aus Sturmwind vertrieben wurde, formierte Edwin van Cleef die entrechteten Handwerker zur Bruderschaft der Defias. Auf der Suche nach einem sicheren Hauptquartier vor Gryan Starkmantels Volksmiliz errichteten die Diebe ihre zentrale Bastion in den verlassenen Stollen. Sie vertrieben die rechtmäßige Miners' League – wodurch Großknecht Distelklettes unglückselige Arbeiter dem Tod geweiht waren und als untote Ghule wiederauferstanden – und wandelten die Schächte in ein industrielles Kriegslager um. Bewacht von schwerfälligen Ogern, kampferprobten Banditen und mechanischen Konstrukten hallen die unteren Minen nun wieder von Spitzhacken, Feuern und illegalem Gewerbe wider."},{t="Das Geheimnis der Eisernen Bucht",b="Hinter der brütend heißen Goblin Gießerei und dem mit Bauholz übersäten Mast Raum liegt die Eiserne Bucht, eine riesige unterirdische Grotte, die unter den Dolchhügeln ausgehöhlt wurde. In diesem verborgenen Hafen hat van Cleef Goblingeschütz- und Schiffbauer damit beauftragt, ein kolossales eisengepanzertes Schlachtschiff zu errichten. Unter dem Befehl von Kapitän Grünhaut und dem Ersten Maat Handlanger Pein ist dieses Kriegsschiff dazu bestimmt, durch ein Unterwassertor aufs offene Meer hinauszusegeln, wo die Bruderschaft der Defias den Seehandel überfallen will, der Sturmwind seinen Reichtum sichert."}},faq={{q="Wo befindet sich der Eingang zu den Todesminen?",a="Der Eingang liegt verborgen in einer verfallenen Scheune im zerstörten Ort Mondbruch im südwestlichen Westfall. Verwinkelte Gänge führen durch einen äußeren Komplex voller Defiasgräber und untoter Bergleute, ehe Ihr das verschlossene Instanztor erreicht.",al={"todesminen eingang","weg zu den todesminen","wo sind die todesminen"}},{q="Warum nennen alle die Todesminen 'VC'?",a="Abenteurer bezeichnen den Dungeon häufig nach seinem Anführer Edwin van Cleef als 'VC'. Dieses Kürzel wird verwendet, um Verwechslungen der Todesminen mit Düsterbruch zu vermeiden, einem uralten Elfenkomplex in Feralas, der dieselben englischen Initialen 'DM' teilt.",al={"warum vc","vc bedeutung","warum heißt es vc"}},{q="Wer ist Edwin van Cleef?",a="Edwin van Cleef war der brillante Gildenmeister der Steinmetze, der den majestätischen Wiederaufbau von Sturmwind nach dem Ersten Krieg leitete. Als der Adelsrat sich weigerte, die Schulden zu begleichen, gründete van Cleef die Bruderschaft der Defias, um sich durch Aufruhr und offenes Banditentum Genugtuung zu verschaffen.",al={"vancleef geschichte","wer ist der endboss","defias anführer"}},{q="Was wird in der Eisernen Bucht gebaut?",a="Die Defias haben Goblbrowser engagiert, um ein massives gepanzertes Kriegsschiff zusammenzusetzen. Mit schwerem Geschütz und robustem Holz gerüstet, soll das Schlachtschiff das Seetor der Bucht durchqueren und den Handel überfallen, der die Hauptstadt versorgt.",al={"was bauen sie","todesminen schiff","schlachtschiff"}},{q="Was geschah mit den Arbeitern der Miners' League vor der Instanz?",a="Großknecht Distelklette und seine Mannschaft wurden entsandt, um die Minen rechtmäßig für das Königreich wiederzueröffnen. Als die Defias das Werk stürmten, schloss ein verheerender Tunneleinsturz die Bergleute in der Dunkelheit ein, wo sie verhungerten und schließlich als geistlose, rastlose Untote auferstanden.",al={"thistlenettle schicksal","warum gibt es untote bergleute","die suche nach andenken lore"}},{q="Welche Bedeutung hat der Sieg über Krümel den Murloc für das Defiasschiff?",a="Krümel dient als bizarrer Schiffskoch an Bord von van Cleefs Schlachtschiff. Während der Sieg über van Cleef der Rebellion den Kopf abschlägt, beseitigt der Tod von Krümel die verbliebene Besatzung in der Schiffskombüse und bricht die Präsenz der Mannschaft in der Eisernen Bucht endgültig, bevor Abenteurer durch den Küstenpfad entkommen.",al={"cookie der murloc","warum ist cookie ein boss","cookie todesminen"}},{q="Wohin führt der Ausgangstunnel beim Verlassen des Dungeons?",a="Folgt Ihr dem natürlichen Tunnel hinter dem Schlachtschiff hinaus, gelangt Ihr zu einem Ausgang an den Küstenklippen der Dolchhügel mit Blick auf das Meer und den Leuchtturm von Westfall.",al={"todesminen ausgang","wohin führt der ausgang"}}},fx={d03732b9={q="Was sind die Todesminen?",a="Die Todesminen sind ein weitläufiges Netzwerk aus labyrinthartigen Tunneln, die tief unter Westfall und dem nordwestlichen Schlingendorntal gegraben wurden. Vor dem Ersten Krieg waren sie das reichste Goldbergbaugebiet in Menschenlanden und sollen ein Drittel der gesamten Schatzreserven von Sturmwind gehalten haben. Sie wurden aufgegeben, als die Horde das Königreich überfiel und plünderte, wodurch die Schächte jahrelang verlassen blieben, bis Gesetzlose sie für sich beanspruchten.",al={"was sind die todesminen","geschichte der todesminen","erzähl mir von den todesminen"}},["990a0946"]={q="Warum werden sie Todesminen genannt?",a="Nachdem der Erste Krieg Verwüstung und Ruinen über Sturmwind gebracht hatte, verfielen die verlassenen Goldschächte in dunkle Unnutzbarkeit und galten weithin als verflucht. Zwischen den tödlichen Schrecken, die in ihren Tiefen lauerten, und der Stille eines erschöpften, verlassenen Steinreichs begannen Reisende, die verlassenen Gruben einfach als die Todesminen zu bezeichnen.",al={"warum heißen sie todesminen","warum todesminen genannt","ursprung des namens todesminen"}},["001f20c6"]={q="Wer hat diese Tunnel gegraben?",a="Generationen von menschlichen Arbeitern und Gildenmitgliedern förderten Vermögen an Gold aus diesen Hügeln, um die frühe Expansion von Sturmwind voranzutreiben. Kürzlich versuchte die Bergbaugesellschaft, die Gruben unter Großknecht Distelklette wieder zu eröffnen, nur damit die Defias-Bruderschaft und ihre zwangsverpflichteten Gräber das unterirdische Netzwerk beschlagnahmten und ihre eigenen weitläufigen Befestigungen hineinbauten.",al={"wer hat die todesminen gebaut","wer hat die todesminen gegraben","bergleute die die todesminen schufen"}},b6ffba12={q="Wer ist die Defias-Bruderschaft?",a="Die Defias-Bruderschaft ist ein grausamer Orden aus Abtrünnigen, Banditen und Gesetzlosen, der sich aus ehemaligen Steinmetzen, Dieben, Wegelagerern und Halsabschneidern zusammensetzt. Als eingeschworene Feinde des Königreichs haben sie die Kontrolle über Westfall übernommen und operieren aus dem Schatten heraus, um blutige Rache zu üben und den herrschenden Adel von Sturmwind zu stürzen.",al={"wer sind die defias","bruderschaft der defias","was sind defias"}},d563a934={q="Warum tragen sie rote Bandanas?",a="Die Defias tragen rote Seidenbandanas als trotziges Symbol für das Blut, das von der unterdrückten Arbeiterklasse von Sturmwind vergossen wurde. Es kennzeichnet ihre Treue zur Rebellion von Edwin van Cleef und erinnert jedes Mitglied an die Blutschuld, die der königliche Hof ihrer Meinung nach bei ihnen hat.",al={"warum rote bandanas","rote defiasmasken","bedeutung des roten bandanas"}},["29fe0b04"]={q="Wer hat die Defias-Bruderschaft gegründet?",a="Edwin van Cleef, der ehemalige Gildenmeister der Steinmetzgilde, gründete die Bruderschaft. Nachdem er Jahre damit verbracht hatte, die zerstörten Stadtmauern von Sturmwind wiederaufzubauen, richtete er seine umfassende Ausbildung in Heimlichkeit, List und Ingenieurskunst auf offenen Aufstand, als der Adel des Königreichs sich weigerte, seine Arbeiter zu bezahlen.",al={"wer gründete die defias","wer startete die bruderschaft","defias gründer"}},["90ba82c0"]={q="Warum verstecken sich die Defias in einer alten Mine?",a="Die Todesminen bieten eine massive, verteidigbare Festung, die unter den stillen Ruinen von Mondbruch verborgen liegt. Da Westfall weitgehend von der königlichen Armee aufgegeben wurde und die vergessenen unterirdischen Kammern der Tunnel direkt mit einer versteckten Meeresbucht verbunden sind, fand van Cleef den perfekten, abgeschiedenen Stützpunkt, um ungestört eine Armee und schwere Waffen anzuhäufen.",al={"warum versteck in todesminen","warum defias in der mine","warum in todesminen verstecken"}},["019c688c"]={q="Gibt es wirklich ein Schiff in der Mine?",a="Ja. Am tiefsten Punkt des Labyrinths liegt die Eiserne Bucht, ein kolossales, unterirdisches Becken. Dort liegt ein massives, eisenbeschlagenes Kriegsschiff vor Anker, das mit schweren Kanonen ausgestattet und von Goblin-Ingenieuren präpariert wurde, bereit, durch ein verstecktes Meerestor in den Ozean zu segeln, sobald es fertiggestellt ist.",al={"gibt es ein schiff in den todesminen","todesminen kriegsschiff","defias kriegsschiff"}},["763d2dd2"]={q="Wer hat hier unten das Sagen?",a="Edwin van Cleef befehligt die gesamte Operation von seiner Kabine an Bord des Kriegsschiffs tief in der Eisernen Bucht aus. Von diesem unterirdischen Stützpunkt aus leitet er die Bergbau-, Ingenieurs- und Überfalloperationen, die Westfall im Griff halten.",al={"wer führt die todesminen","wer leitet die todesminen","todesminen boss"}},["985d6768"]={q="Hat van Cleef Leutnants?",a="Er befehligt eine vielfältige Kabale aus vertrauenswürdigen Vollstreckern in den Schächten. Der brutale Oger Rhahk'Zor bewacht die oberen Tore, Sneed befehligt die Holzwerkstätten aus einem Eisernen Schredder heraus, der Goblin Gilnid leitet die Schmelzhütten der Gießerei und Kapitän Grünhaut zusammen mit dem rücksichtslosen Tauren-Ersten Offizier, Handlanger Pein, beaufsichtigen das Kriegsschiff.",al={"vancleefs offiziere","todesminen befehlshaber","defias leutnants"}},["27e06e7a"]={q="Für wen arbeiten die Goblins?",a="Die Goblins arbeiten direkt unter Edwin van Cleef als angeheuerte Spezialisten und Söldnerhandwerker. Sie betreiben die Gießerei, die Holzwerkstätten und die Werften und bringen die technische Meisterschaft und die industrielle Maschinerie mit, die nötig sind, um van Cleefs Kriegsmaschinen zu bauen – im Austausch für Gold, Einfluss und Ressourcen.",al={"wer hat die goblins angeheuert","sind goblins defias","goblin allianz defias"}},fb90d257={q="Warum hat man mich geschickt, um ihren Anführer zu töten?",a="Gryan Starkmantel und die bedrängte Volksmiliz verfügen nicht über die militärische Stärke, um die Todesminen selbst zu stürmen. Da Sturmwind die Augen verschließt und die Bedrohung ignoriert, verlässt sich die Miliz vollständig auf mutige, unabhängige Abenteurer wie Euch, um tief in den Berg einzudringen und dem Kopf der Schlange den Garaus zu machen.",al={"warum mich schicken um vancleef zu töten","gryan starkmantel anfrage","warum defias anführer töten"}},["22846885"]={q="Warum kann die Armee von Sturmwind das nicht erledigen?",a="Die stehenden Streitkräfte von Sturmwind sind über das gesamte Rotkammgebirge und ferne Grenzen verteilt und durch Schulden sowie bürokratische Apathie gelähmt. Das Haus der Adligen weigert sich, eine Expedition nach Westfall zu finanzieren, was die bäuerlichen Gemeinden der Provinz ungeschützt lässt und die freiwillige Volksmiliz zwingt, die Krise allein zu bewältigen.",al={"warum keine armee von sturmwind","warum räumt sturmwind die todesminen nicht","sturmwind bewacht westfall"}},["9fd39a6b"]={q="Schlossen sich die Bergleute den The Defias Brotherhood an?",a="Während die Arbeiter der Miners' League überfallen wurden und ums Leben kamen, schlossen sich viele rechtlose Arbeiter, Taschendiebe und verzweifelte Vagabunden bereitwillig der Sache der Bruderschaft an. Heute schuften nicht-elitäre Arbeiter und Tagebau-Bergleute unaufhörlich in den Schächten unter den wachsamen Peitschen der Aufseher und Vorarbeiter der The Defias Brotherhood.",al={"wurden bergleute zu the defias brotherhood","sind bergleute the defias brotherhood","bergleute arbeiten für the defias brotherhood"}},a6aef884={q="Warum helfen hier unten Goblins den The Defias Brotherhood?",a="Der Bau eines gepanzerten Schlachtschiffs und komplexer Erntewächter erfordert fortgeschrittene metallurgische und mechanische Fachkenntnisse, die einfachen Banditen fehlen. Edwin van Cleef heuerte Goblin-Ingenieure, Handwerker und Holzschnitzer an, die im Austausch für Reichtum und Profit gerne Gießereien und Werkstätten in den Kavernen errichteten.",al={"warum goblins in den todesminen","goblinpräsenz in den todesminen","warum sind goblins hier"}},b9fb938c={q="Was haben die Goblins davon, den The Defias Brotherhood zu helfen?",a="Für die Goblins ist es ein reines Geschäft. Sie erhalten einen riesigen Anteil des Goldes, das aus den Minen von Westfall geplündert wurde, uneingeschränkten Zugang zu hochwertigem Erz und Holz sowie völlige Freiheit, flüchtige Konstruktionsprototypen abseits der Zuständigkeit der Handelsprinzen zu testen.",al={"was bekommen die goblins","goblin profit todesminen","warum arbeiten goblins für the defias brotherhood"}},["4854becf"]={q="Wer ist Sneed?",a="Sneed ist ein gerissener Goblin-Aufseher, der den Holzfällereibetrieb der The Defias Brotherhood im Mast Room beaufsichtigt. Er befehligt das Fällen von Holz aus einem schweren, messerscharfen Holzfäller-Schredder heraus und verarbeitet riesige Bäume zu Masten und Balken für das Schlachtschiff.",al={"wer ist sneed","sneed todesminen","sneed boss"}},ba2c808f={q="Was ist diese Steinmetzgilde, von der jeder spricht?",a="Die Steinmetzgilde war die angesehene Vereinigung von Architekten, Steinmetzen und Handwerkern unter der Führung von Edwin van Cleef, die Sturmwind nach der Zerstörung im Ersten Krieg aus den Ruinen wiederaufbaute. Sie restaurierten die weißen Stadtmauern und Türme, nur um zum Fundament der Rebellion zu werden, als die Politik des Königreichs sie verriet.",al={"steinmetzgilde","was war die steinmetzgilde","wer waren die steinmetze"}},["30bf5c0b"]={q="Hat sich Sturmwind wirklich geweigert, die Steinmetze zu bezahlen?",a="Ja. Das Haus der Adligen von Sturmwind hatte durch die Ausweitung militärischer Kampagnen katastrophale Schulden angehäuft und weigerte sich, die volle Entschädigung für den Wiederaufbau der Stadt zu zahlen. Die Adligen, die im Geheimen von Lady Katrana Prestor manipuliert wurden, boten nur kärgliche Zahlungen an und lösten die Gilde abrupt auf, als Edwin van Cleef Wiedergutmachung forderte.",al={"hat sturmwind die steinmetze nicht bezahlt","warum wurden die steinmetze nicht bezahlt","bezahlung der steinmetze durch das haus der adligen"}},["8f04eff1"]={q="Sind die The Defias Brotherhood nur Banditen oder etwas Schlimmeres?",a="Sie sind weit mehr als gewöhnliche Diebe. Die The Defias Brotherhood ist ein organisiertes, tief verwurzeltes revolutionäres Syndikat, das über fortgeschrittene Goblin-Technik, Spionage und ausgebildete Magie verfügt, alles angetrieben von einem persönlichen und ideologischen Hass auf die herrschende Klasse von Sturmwind.",al={"sind die the defias brotherhood banditen","wie gefährlich sind die the defias brotherhood","bedrohungsstufe der the defias brotherhood"}},["2dd70853"]={q="Haben die The Defias Brotherhood einen tatsächlichen Plan?",a="Ihr Ziel ist nichts Geringeres, als Sturmwind in die Knie zu zwingen. Indem sie Westfall die Ressourcen entziehen und die Hauptstadt aushungern, während sie heimlich unter der Erde ein schweres eisernes Kriegsschiff bauen, beabsichtigen sie, direkt zu Burg Sturmwind zu segeln und das Königreich zur bedingungslosen Kapitulation zu bombardieren.",al={"meisterplan der the defias brotherhood","was ist das ziel der the defias brotherhood","was wollen die the defias brotherhood"}},["9ff64ec1"]={q="Könnten die The Defias Brotherhood Sturmwind selbst bedrohen?",a="Durchaus. Da König Varian vermisst wird, der Hof durch interne Intrigen gelähmt ist und die königliche Armee über ihre Grenzen hinaus beansprucht wird, könnte ein überraschender Marineangriff eines voll bewaffneten eisernen Schlachtschiffs die Verteidigungsanlagen des Hafens von Sturmwind zerschmettern und die Stadt von innen heraus schutzlos zurücklassen.",al={"können die the defias brotherhood sturmwind zerstören","könnten die the defias brotherhood sturmwind einnehmen","bedrohung von sturmwind durch the defias brotherhood"}},["9d82770e"]={q="Was passiert, nachdem Edwin van Cleef tot ist?",a="Die Übergabe des abgetrennten Kopfes von Edwin van Cleef an Gryan Starkmantel auf der Späherkuppe bestätigt den Tod des Drahtziehers und versetzt dem großen Feldzug der Bruderschaft einen schweren Schlag. Zudem deuten Dokumente, die man auf seiner Leiche findet, wie etwa ein nie abgeschickter Brief, auf tiefere Verschwörungen und Korruption hin, die im Herzen von Sturmwind schwären.",al={"nach dem tod von edwin van cleef","edwin van cleef ist tot was nun","folgen des todes von edwin van cleef"}},f607b8be={q="Beendet das Töten von Edwin van Cleef die The Defias Brotherhood?",a="Es zerschlägt ihre unmittelbaren Pläne, aber es beseitigt nicht die Rebellion. Tausende Taschendiebe, Briganten und Sympathisanten bleiben in ganz Westfall, dem Rotkammgebirge und den Stockaden verschanzt und hegen einen bitteren Hass auf die Krone, der ihren gründenden Anführer überdauert.",al={"endet die the defias brotherhood mit edwin van cleef","sind die the defias brotherhood besiegt","stoppt der tod von edwin van cleef die the defias brotherhood"}},c2558e80={q="Wird Westfall endlich sicher sein, nachdem Edwin van Cleef gefallen ist?",a="Nicht sofort. Schurkenhafte mechanische Erntewächter durchstreifen immer noch die zerstörten Felder, Gnollenrudel schleichen durch die Hügel und verstreute Zellen der The Defias Brotherhood plündern weiterhin Farmen. Die Volksmiliz steht vor einem langen, mühsamen Kampf, bevor jemals wirklich Frieden in die Ebenen zurückkehren wird.",al={"ist westfall jetzt sicher","wird sich westfall erholen","westfall nach den todesminen"}},d15c407d={q="Warum ist Westfall so ein Chaos?",a="Westfall war einst die fruchtbare Kornkammer des Königreichs, aber jahrelange Vernachlässigung, Dürreperioden und der Terror der The Defias Brotherhood haben es in den Ruin getrieben. Gesetzlose vertrieben die Siedler, ergriffen die Minen und ließen die einst üppigen Weiden brach liegen, wo sie nun von gefräßigen Aasfressern und schurkenhaften Erntegolems heimgesucht werden.",al={"warum ist westfall ruiniert","was ist mit westfall passiert","zustand von westfall"}},["8c3ab485"]={q="Wo sind all die Bauern aus Westfall hin?",a="Die meisten wurden gewaltsam von ihrem Land vertrieben, als die The Defias Brotherhood die Landschaft überrannte; sie flohen zu den Toren der Späherkuppe oder bettelten auf den Straßen von Sturmwind. Nur eine Handvoll sturer Siedler verbleibt auf ihren Familiengrundstücken und kämpft verzweifelt gegen Banditen und Gnolle, um eine Ernte zusammenzukratzen.",al={"wo sind die bauern","was ist mit den bauern von westfall passiert","vertriebene bauern aus westfall"}},["619c91ff"]={q="Warum schickt der König keine Hilfe nach Westfall?",a="König Varian Wrynn ist auf mysteriöse Weise verschwunden und hat seinen jungen Sohn Anduin sowie Hochlord Bolvar Fordragon zurückgelassen, um das Reich zu verwalten. Der königliche Hof, der von zerstrittenen Adligen manipuliert wird, behauptet, das Königreich habe nicht genügend Mittel und militärische Arbeitskräfte, um die Verteidigung von Westfall zu unterstützen, und überlässt die Provinz ihrem Schicksal.",al={"warum hilft der könig nicht in westfall","warum keine hilfe vom könig","könig varian hilfe für westfall"}},["21f940b9"]={q="Wie bin ich in den Todesminen gelandet?",a="Eure Jagd nach der The Defias Brotherhood führte Euch über die verwüsteten Ebenen von Westfall nach Mondbruch, einer verlassenen Stadt, die von Briganten überrannt wurde. Ein Verräter der The Defias Brotherhood half Euch dabei, ihr geheimes Hauptquartier ausfindig zu machen, das sich im baufälligen Mineneingang am Rande der Stadt verbirgt. Während Ihr Euch Euren Weg durch die alten Bergbautunnel und vorbei an Ausgrabungen der Untoten gebahnt habt, seid Ihr in die Tiefen vorgedrungen, wo die Bruderschaft ihr befestigtes Versteck errichtet hat.",al={"wie bin ich hierher gekommen","wie bin ich hier gelandet","wie komme ich hier rein"}},a22369d2={q="Was soll ich in den Todesminen tun?",a="Gryan Starkmantel und The People's Militia haben Euch geschickt, um das Übel an der Wurzel zu packen. Ihr seid hier, um Euch durch die Bergleute der Brotherhood, goblinische Bastler und Piraten-Mercenaries zu kämpfen, bis Ihr die Eiserne Bucht erreicht. Sobald Ihr dort seid, müsst Ihr ihr Kriegsschiff entern, Edwin van Cleef höchstpersönlich stellen und seinen Kopf fordern, um die Herrschaft der Defias über Westfall ein für alle Mal zu brechen.",al={"was mache ich hier","was ist mein ziel hier","warum bin ich hier"}},e11d0994={q="Hat noch jemand versucht, VanCleef zu töten?",a="Nicht mit Erfolg. Sturmwind hat kein Heer gegen ihn ausgesandt, und der Volksmiliz auf der Späherkuppe fehlt die Stärke, die Minen zu stürmen. Deshalb wendet sich Gryan Starkmantel an Abenteurer.",al={"wer hat versucht, vancleef zu töten","frühere angriffe auf die todesminen","hat jemand die todesminen angegriffen"}},["93f204fb"]={q="Wie übernahmen die Defias die Minen?",a="Nachdem VanCleef aus Sturmwind geflohen war, führte er seine Anhänger in die gesetzlosen Felder von Westfall. Sie überfielen die örtlichen Minenbetriebe, ließen wichtige Tunnel einstürzen, um königliche Arbeiter einzuschließen, und befestigten das weitläufige unterirdische Netz zu einer uneinnehmbaren Operationsbasis.",al={"wie übernahmen die defias die todesminen","wie fielen die todesminen","übernahme der mine durch die defias"}},["6779ccff"]={q="Gab es einen Aufstand in Sturmwind?",a="Als die Gilde ohne Bezahlung aufgelöst wurde, führte VanCleef wütende Aufstände durch die Straßen von Sturmwind an. Die Krone schlug hart zurück und trieb die aufständischen Handwerker ins Exil.",al={"aufstand der steinmetze in sturmwind","was geschah beim aufstand der steinmetze"}}},fp="13,318,25.642.0,26.653.0,27.461.1,47.206.0,42.189.0,22.291.0,37.246.0,65.243.0,63.283.0,57.175.0"}
P.entries["zone:deadwind"] = {n="Gebirgspass der Totenwinde",s="Ein übler Wind fegt durch den Gebirgspass der Totenwinde, wo die Straße zwischen dem Dämmerwald und den Sümpfen des Elends verläuft. Karazhan erhebt sich im Herzen des Passes; sein zerstörter Turm ist noch immer von Medivhs Tod gezeichnet. Oger und Geister treiben sich in der Schlucht herum, und kein Ort bietet Schutz.",h="Ein übler Wind fegt durch den Gebirgspass der Totenwinde, wo die Straße zwischen dem Dämmerwald und den...",kw={"dark riders","totmannsfurt","deadwind-oger","gebirgspass der totenwinde","karazhan","medivh","morgans plot","der letzte wächter","das laster"},ang={["class:Mage"]="Die Leylinien unter dem Gebirgspass der Totenwinde laufen in Karazhan zusammen. Magier betrachten diesen Knotenpunkt mit Schrecken, denn Medivh verzerrte den arkanen Strom, um Dimensionsbarrieren zu durchbrechen.",["class:Warlock"]="Rohe dämonische Energie haftet noch immer an den Felsen und steinernen Kellern. Medivhs Besessenheit und die nekromantische Geschichte des Passes hinterließen einen bleibenden Makel aus Teufelsmagie.",["faction:Alliance"]="Sturmwind betrachtet den Gebirgspass der Totenwinde als düstere Narbe an seinen Grenzen. Die Schrecken aus Karazhan beendeten den einstigen Glanz des Dämmerwalds und bedrohen noch immer Dunkelhain an der westlichen Straße.",["faction:Horde"]="Reisende, die von Steinard nach Westen ziehen, erwartet ein feindseliger Engpass. Rachsüchtige Geister von Menschen und massige Oger greifen jeden an, der die Schlucht betritt."},sec={{t="Eine Schlucht aus Knochen und heulendem Wind",b="Der Gebirgspass der Totenwinde liegt zwischen dem Dämmerwald und den Sümpfen des Elends. Seine Schluchten durchschneiden bleichen Stein und versteinertes Holz. Einst zählte man den Pass zum Rotkammgebirge, doch heute ist er eine ausgehöhlte Narbe. Ein übler Wind fegt durch die Schlucht, und plötzliche Blitze unter grauem Himmel machen Metallwaffen gefährlich.\n\nTotemartige Bildnisse hängen neben der Hauptstraße an abgestorbenen Ästen und warnen Reisende, weiterzugehen. Weder fruchtbarer Boden noch abbaubare Erzadern bieten einen Grund zu bleiben. Keine Stadt und kein Flugmeister können Hilfe leisten."},{t="Karazhans Vermächtnis",b="Karazhan beherrscht den Gebirgspass der Totenwinde und wurde über einer mächtigen Kreuzung von Leylinien erbaut. Der Turm war die Festung des Wächters Medivh, wo er plante, das Dunkle Portal zu öffnen und Sturmwind ins Verderben zu stürzen. Während des Ersten Krieges führten Lord Anduin Lothar und der junge Khadgar eine Expedition in den Turm, nachdem Medivhs Wahnsinn und Besessenheit ans Licht gekommen waren. Dort töteten sie ihn.\n\nSein Tod verbreitete Teufelsverderbnis über den Pass und den Dämmerwald. Karazhan ist eine unheilvolle Ruine geblieben, und seine instabile Magie sickert weiterhin ins Land."},{t="Deadwind-Oger und zerstörte Höfe",b="Südlich der Hauptstraße halten Deadwind-Oger das Gebiet um das Laster besetzt. In üble Lumpen gekleidet und mit gezacktem Eisen bewaffnet, überfallen sie jeden, der sich der südlichen Straße nähert. Berichten zufolge dienen sie einem verborgenen Meister in der Nähe.\n\nWeiter südlich liegen in Morgans Plot die skelettierten Überreste eines Weilers, der einst dem Turm diente. In den oberirdischen Ruinen und gewundenen Kellern hallt das Heulen von Phantomen und rastlosen Schemen wider, den Toten, die Karazhans entfesselte Zauberei zurückließ."},{t="Die Sichel und die Dark Riders",b="Verhüllte Dark Riders tauchen aus dem Gebirgspass der Totenwinde auf und kehren dann in seine Schatten zurück. Vor Kurzem terrorisierten sie den Dämmerwald und töteten unschuldige Siedler, während sie nach der Sichel von Elune suchten."}},faq={{q="Warum ist dieser Ort so tot und verwüstet?",a="Karazhans Magie und Medivhs dunkle Zauberei verwüsteten den Gebirgspass der Totenwinde. Als Medivh während des Ersten Krieges im Turm getötet wurde, brach Teufelsmagie durch die Schlucht. Sie ließ Bäume versteinern, entzog der Erde alles Leben und verdunkelte den Himmel.",al={"warum ist der gebirgspass der totenwinde tot","was geschah mit dem gebirgspass der totenwinde","warum sind die bäume hier tot"}},{q="Gibt es hier freundliche Städte, Gasthäuser oder Flugmeister?",a="Keine freundlichen Städte, Gasthäuser oder Flugmeister stehen in Gebirgspass der Totenwinde einer der beiden Fraktionen zur Verfügung. Reisende der Allianz sind auf Dunkelhain im Westen des Dämmerwalds angewiesen. Reisende der Horde brechen von Steinard im Osten, in den Sümpfen des Elends, auf.",al={"flugroute im gebirgspass der totenwinde","gibt es eine stadt im gebirgspass der totenwinde","gasthaus im gebirgspass der totenwinde"}},{q="Welche Bedeutung hat Karazhan für den Gebirgspass der Totenwinde?",a="Karazhan war der Turm des Wächters Medivh, in dem er daran arbeitete, das Dunkle Portal zu öffnen. Zwischen den verdorrten Bäumen, der instabilen Magie und den rastlosen Toten ist er noch immer ein unheilvolles Wahrzeichen des Gebirgspasses der Totenwinde.",al={"karazhan im gebirgspass der totenwinde","medivhs turm","geschichte von karazhan"}},{q="Wer sind die Dark Riders, und woher kommen sie?",a="Die Dark Riders sind verhüllte Gestalten, die aus dem Gebirgspass der Totenwinde ausreiten, um mächtige Relikte wie die Sichel von Elune zu jagen. Sie haben Schrecken über den nahe gelegenen Dämmerwald gebracht.",al={"dark riders in den totenwinden","reiter der sichel von elune"}},{q="Kann ich im Gebirgspass der Totenwinde Kräuter sammeln oder Erz abbauen?",a="Im Gebirgspass der Totenwinde gibt es keine nützlichen Vorkommen für Kräuter oder Erze. Aasvögel und feindselige Oger durchstreifen das karge Land.",al={"kräuter im gebirgspass der totenwinde","bergbau in den totenwinden","rohstoffe im gebirgspass der totenwinde"}},{q="Wer lebt heute im Gebirgspass der Totenwinde?",a="Deadwind-Oger rund um das Laster, Aasvögel und rastlose Geister bevölkern den Pass. Einige umherziehende menschliche Plünderer überleben dort, ohne Unterstützung der Allianz.",al={"bewohner des gebirgspasses der totenwinde","wer lebt in den totenwinden","gegner im gebirgspass der totenwinde"}}},fp="13,250,34.500.0,22.508.0,31.455.0,30.182.1,37.230.0,59.217.0,42.181.0,53.166.1,48.112.0,33.162.0"}
P.entries["zone:desolace"] = {n="Desolace",s="In ganz Desolace kämpfen Zentaurenstämme um die Ebenen, während Horde, Allianz und dämonische Kulte in das Ödland vordringen. Graue Erde, sturmverhangener Himmel, uralte Ruinen und gefallene Bestien prägen Kalimdors Westküste.",h="In ganz Desolace kämpfen Zentaurenstämme um die Ebenen, während Horde, Allianz und dämonische Kulte in das...",kw={"burning blade","zentauren","desolace","gelkis","magram","maraudon","die nijelspitze","schattenflucht","theradras","zaetar"},ang={["class:Druid"]="Druiden des Zirkels des Cenarius sehen Desolace als schreckliche Wunde in der Natur, wo Zaetar sein Ende fand und elementarer Verfall die Erde erstickt.",["class:Warlock"]="Desolaces trockene Ebenen und dämonische Orte wie Mannorocs Koven ziehen Hexenmeister an, die nach Geheimnissen der Teufelsrösser suchen. Diese wilden Pferde wurden durch verbotene Rituale des Schattenrats zu feuerspeienden Schrecken verdreht.",["faction:Alliance"]="Von der Nijelspitze aus beobachtet die Allianz die gefährlichen Zentaurenstämme, Siedlungen der Horde wie Schattenflucht und die dämonischen Kulte, die sich in Desolace ausbreiten.",["faction:Horde"]="Die Horde arbeitet daran, die Küste bei Schattenflucht zu sichern und die Kodoherden beim Geistwandlerposten zu schützen. Außerdem kämpft sie gegen die Burning Blade, um sie zu zerschlagen und zu beweisen, dass sich die moderne Horde vom dämonischen Einfluss befreit hat.",["race:Tauren"]="Für Tauren ist Desolace heiliger und tragischer Boden: die Wiege der Zentauren, deren Geißel Euer Volk beinahe ausrottete."},sec={{t="Ein verfluchtes, zerbrochenes Land",b="Sturmverhangener Himmel liegt über Desolace, wo graue Erde aufgerissen ist und Tümpel gelb geworden sind. Der Legende nach entzog Prinzessin Theradras, ein Erdelementar, dem Land seine Lebenskraft, um ihre Gestalt wiederherzustellen. Zaetar, Sohn von Cenarius, kam, um sie zu bezwingen, wurde jedoch stattdessen ihr Gefährte. Aus ihrer Verbindung gingen die ersten Zentauren hervor. Beschämt und wutentbrannt töteten die neugeborenen Zentauren ihren Vater und breiteten sich über die Ebenen aus. Sie hinterließen das vernarbte Ödland, das Reisende heute sehen."},{t="Hufe im Krieg",b="Tausende Hufe donnern durch Desolace, während vier Zentaurenstämme gegen Fremde und gegeneinander kämpfen. Die Kolkar durchstreifen die östlichen Klippen, während die Magram primitive Jurten um brackige Dolinen errichtet haben. Weiter südlich leben die Gelkis jenseits von Seilbrücken in tiefen Schluchten. Die fanatischen Maraudine bewachen den Zugang zu Maraudon. Reisende, die das Ödland durchqueren, geraten oft in diese alte Blutrache. Sicheres Geleit kann bedeuten, einen Stamm zu bekämpfen, um mit einem anderen eine vorsichtige Unterredung zu führen."},{t="Kulte und düstere Küsten",b="Jenseits der Zentaurengebiete sammeln sich Gefahren an Desolaces Grenzen. Die Burning Blade operiert von der Festung Donneraxt und der Schattenklamm aus und beschwört Dämonen und Satyrn, deren Teufelsfeuer die Region bedroht.\n\nNaga schleichen sich an die sturmgepeitschten Strände von Ethel Rethor, während Dunkelspeertrolle von den Stelzen Schattenfluchts aus Fische harpunieren. Hoch oben in den nördlichen Felsen hält die Allianz von der Nijelspitze aus Wache. Sie fürchtet die Ausbreitung der Horde und den dämonischen Makel, der sich von Mannorocs Koven ausbreitet."}},faq={{q="Warum ist Desolace ein totes Ödland?",a="Der Legende nach war Desolace einst fruchtbar, bis Prinzessin Theradras ihm seine Lebenskraft entzog, um ihre Gestalt wiederherzustellen. Dann wurden die Zentauren geboren und breiteten sich gewaltsam aus. Sie zerstörten die verbliebene Pflanzenwelt und hinterließen grauen Staub und Asche.",al={"warum ist desolace tot","desolace ursprung hintergrundgeschichte"}},{q="Woher stammen die Zentauren?",a="Die Zentauren gingen aus Zaetar, Sohn von Cenarius, und Prinzessin Theradras, einem Erdelementar, hervor. Die ersten Khane waren von ihrem Aussehen abgestoßen und wutentbrannt. Kurz nach ihrer Geburt töteten sie ihren Vater und breiteten sich über die Ebenen aus.",al={"ursprung der zentauren","wer erschuf die zentauren","zaetar theradras"}},{q="Kann ich mich hier mit den Zentaurenstämmen verbünden?",a="Ja. Ihr könnt Euch bei den Gelkis oder den Magram Ansehen verdienen, indem Ihr Angehörige des rivalisierenden Stammes erschlagt. Mit genug Ansehen erhaltet Ihr Zugang zum Dorf des Stammes und Frieden in seinem Gebiet, während der gegnerische Stamm Euch dauerhaft feindlich gesinnt ist.",al={"ansehen bei den zentauren","gelkis oder magram","wie man sich mit zentauren anfreundet"}},{q="Was ist Maraudon?",a="Maraudon ist die heilige Begräbnisstätte der Ahnen der Zentauren, verborgen in den gewundenen westlichen Klippen von Desolace. Dort befinden sich Zaetars Grab und die unterirdische Höhle von Prinzessin Theradras, in der sie elementare Verderbnis durch die Höhlen leitet.",al={"wo liegt maraudon","maraudon dungeon","was liegt unter desolace"}},{q="Wer ist der Wanderer, der mit einem Bären durch Desolace zieht?",a="Der Wanderer ist Rexxar, Champion der Horde, der mit seinem treuen Bären Misha reist. Der Halboger patrouilliert auf den staubigen Straßen von Desolace und dem Steinkrallengebirge, beobachtet die Wildnis und hilft jenen, die wichtige Angelegenheiten der Horde verfolgen.",al={"rexxar desolace","bestienmeister in desolace","wer ist der ork mit einem bären"}},{q="Warum kämpfen Allianz und Horde hier gegen die Burning Blade?",a="Die Burning Blade hat Festungen wie die Festung Donneraxt eingenommen, um Dämonen zu beschwören und Teufelsrösser zu binden. Ihre Dämonen und Satyrn drohen die Region zu verseuchen, daher müssen Horde und Allianz sie bekämpfen.",al={"burning blade desolace","kultisten der festung donneraxt","warum sind dämonen hier"}}},fp="8,209,24.445.0,14.468.0,25.490.0,38.221.0,32.220.0,40.243.0,17.238.0,49.233.0,63.210.0"}
P.entries["zone:dunmorogh"] = {n="Dun Morogh",s="Dun Morogh ist ein hoch gelegenes Schneegebiet und die Heimat der Zwerge in den Bergen. Auch die Gnome finden hier Zuflucht, denn sie haben ihre Heimat verloren. Doch der Schnee ist nicht sicher. Troggs und Frostmähnentrolle streifen darin umher, ebenso die Lepergnome.",h="Dun Morogh ist ein hoch gelegenes Schneegebiet und die Heimat der Zwerge in den Bergen.",kw={"ambossar","bräuhall","das coldridgetal","die tiefenbahn","dun morogh","frostmähnen","gnomeregan","gol'bolar","eisenschmiede","kharanos","magni bronzebart","troggs"},ang={["profession:Cooking"]="Als Koch findet Ihr deftige Speisen in Kharanos und Bräuhall, wo Jäger und Gastwirte Wildschweinfleisch, Bärenrippchen und Zwergenbier gegen die Bergkälte nutzen.",["profession:Mining"]="Als Bergbauer findet Ihr in Dun Morogh reiche oberirdische Kupfervorkommen, besonders rund um den Steinbruch Gol'Bolar und entlang der verschneiten Felswände.",["race:Dwarf"]="Als Zwerg stammt Ihr aus dieser angestammten Heimat. Von den Herdfeuern Ambossars bis zum flammenden Herzen der Großen Schmiede verteidigt Ihr diese Gipfel im Dienst von König Magni gegen Trolle und Troggs.",["race:Gnome"]="Als Gnom liegt Eure verlorene Heimat Gnomeregan verstrahlt im westlichen Tal. Ihr schlagt Eure Basis in Dun Morogh neben Euren Vetterzwergen auf und kämpft gegen Troggs und abtrünnige Lepergnome."},sec={{t="Eine Bergfestung",b="Die Berge erheben sich zwischen der Sengenden Schlucht im Süden und dem Sumpfland im Norden. Ihr Schmelzwasser speist die Flüsse von Khaz Modan, und Kupfer und Eisen durchziehen das Gestein in Adern. Zwergische Gebirgsjäger bewachen die schmalen Straßen an den Nord- und Südtoren. Unter dem höchsten Berg liegt Eisenschmiede, der Sitz von König Magni Bronzebart."},{t="Eine geteilte Zuflucht",b="Vor Jahrhunderten trieben die Zwerge die einheimischen Frostmane-Eistrolle hinauf in die Felsen. So schufen sie Platz für sich und ihre gnomischen Verbündeten. Die beiden Völker gediehen in benachbarten Berghallen, bis zum Dritten Krieg. Dann fiel Gnomeregan.\n\nTroggs drangen in die Stadt der Gnome ein, und radioaktives Gas verwüstete sie. Ihre eigenen Verteidiger wurden zu Lepergnomen verdreht. Hochtüftler Gelbin Mekkadrill führte die Überlebenden ins Exil, und nun leben sie als Gäste in Eisenschmiede. Doch die Lepergnome und die Troggs dringen ins Frosthauchtal vor."},{t="Unruhe in den Schneewehen",b="Die Frostmähnen sind dreister geworden und unterhalten bewaffnete Lager vom Schimmergrat bis zum Coldridgetal. Troggs haben sich aus alten Spalten in den Steinbruch Gol'Bolar gegraben, und die Minen sind in Gefahr. Wendigos und Wildschweine streifen durch die Schneewehen, und die Dunkeleisenzwerge schicken ihre Spione. Giftiger Niederschlag breitet sich von den Ruinen Gnomeregans aus. Die Gebirgsjäger kämpfen darum, von Kharanos bis zu den Grenztoren die Ordnung aufrechtzuerhalten."}},faq={{q="Welche Völker beginnen in Dun Morogh?",a="Zwerge und Gnome beginnen ihre Reise im Coldridgetal, im Südwesten von Dun Morogh. Als Zwerg stammt Ihr aus dieser angestammten Heimat. Von den Herdfeuern Ambossars bis zum flammenden Herzen der Großen Schmiede verteidigt Ihr diese Gipfel im Dienst von König Magni Bronzebart gegen Trolle und Troggs.",al={"startvolk in dun morogh","wer beginnt hier","startgebiet der zwerge","startgebiet der gnome"}},{q="Was geschah mit Gnomeregan?",a="Während des Dritten Krieges schwärmten Troggs von unten nach Gnomeregan. Hochtüftler Gelbin Mekkadrill ließ radioaktives Gas in die unteren Ebenen strömen, um sie zu vertreiben, doch der Plan scheiterte. Tausende starben, viele Gnome wurden zu wahnsinnigen Lepergnomen, und die gesunden Überlebenden flohen nach Eisenschmiede.",al={"warum ist gnomeregan zerstört","was geschah mit den gnomen","warum gibt es hier lepergnome"}},{q="Wie verlasst Ihr Dun Morogh zu Fuß?",a="Hohe Bergrücken umgeben Dun Morogh. Um Loch Modan zu Fuß zu erreichen, folgt Ihr den Straßen zum Nordtorpass oder Südtorpass in den nordöstlichen Bergen. Von Eisenschmiede bringt die Tiefenbahn Reisende direkt nach Sturmwind.",al={"dun morogh verlassen","von dun morogh nach loch modan"}},{q="Wo befindet sich der Flugmeister in Dun Morogh?",a="Der einzige funktionierende Flugmeister der Allianz in dieser Zone befindet sich in der Großen Schmiede von Eisenschmiede. Die Flugrouten verbinden Reisende mit Orten in Khaz Modan, Sturmwind und den nördlichen Außenposten der Allianz.",al={"flugmeister in dun morogh","flugroute in dun morogh","wohin fliegen ab dun morogh"}},{q="Wer sind die Frostmähnentrolle?",a="Die Frostmähnen sind Eistrolle, die Dun Morogh beherrschten, lange bevor die Zwerge aus Uldaman hervorkamen. Die Zwerge besiegten sie und trieben sie vor Generationen in die Felsen, doch sie bleiben erbitterte Feinde Eisenschmiedes und überfallen von Rückzugsorten wie der Höhle der Frostmähnen aus Bauernhöfe und Straßen.",al={"warum gibt es trolle in dun morogh","trolle in dun morogh","stamm der frostmähnen"}},{q="Was ist Kharanos?",a="Kharanos ist die wichtigste Zwergensiedlung im Zentrum von Dun Morogh. Dort gibt es die Brauerei Donnerbräu, Ausbilder und Vorräte. Gebirgsjäger und junge Abenteurer nutzen den Ort als Basis im Kampf gegen die Trolle und die wilde Tierwelt der Gegend.",al={"ort in dun morogh","zentrum von kharanos","was ist der hauptort"}}},fx={ee70a2d7={q="Was ist Dun Morogh?",a="Dun Morogh ist eine hochgelegene, verschneite Gebirgsregion im westlichen Khaz Modan. Von allen Seiten von aufragenden Gipfeln umgeben, bildet sie das angestammte Kernland der Zwerge von Eisenschmiede und die Zuflucht der Gnome. Das Reich ist bekannt für seine beißende Kälte, dichte Kiefernwälder, gefrorene Seen und seinen großen Mineralreichtum. Es beherbergt die prächtige Bergzitadelle von Eisenschmiede an seinen nördlichen Graten sowie die belagerte Technostadt Gnomeregan, die versteckt in den westlichen Hügeln liegt.",al={"was ist das für ein ort","wo sind wir","dun morogh zone"}},["8c7c9511"]={q="Was ist in der Vergangenheit von Dun Morogh geschehen?",a="Dun Morogh wurde ursprünglich von den Eistrollen der Frostmähnen gehalten. Die Zwerge und Gnome besiedelten später diese verschneiten Gipfel und schmiedeten eine dauerhafte Verwandtschaft. Sie bauten Eisenschmiede und Gnomeregan, während sie die Frostmähnen zurück in die entlegenen Felsen drängten. Während des Zweiten Krieges hielten zwergische und gnomische Verteidiger ihre Bergfestungen erfolgreich gegen die orcische Horde. Heute stehen die friedlichen Ländereien nach dem Fall von Gnomeregan und den zunehmenden Einfällen von Troggs vor Unruhen.",al={"geschichte von dun morogh","was ist hier passiert"}},["4399d516"]={q="Wer lebt in Dun Morogh und wer herrscht dort?",a="Dun Morogh wird hauptsächlich von König Magni Bronzebart von seinem Thron in der Bergfestung Eisenschmiede aus regiert. Die Zwerge von Eisenschmiede unterhalten Berggarnisonen, Außenposten und Wachtürme in den Pässen. Dun Morogh ist auch die Heimat der Gnome, deren Anführer, Hochtüftler Gelbin Mekkadrill, und die überlebende Bevölkerung nach dem tragischen Verlust von Gnomeregan derzeit bei ihren zwergischen Verbündeten Zuflucht suchen. Jenseits der Siedlungen bestreiten Frostmähnen-Trolle und primitive Troggs die zwergische Autorität in den wilden Felsen und Steinbrüchen.",al={"wer regiert dun morogh","wer kontrolliert dun morogh","wer lebt hier"}},["1f8f2322"]={q="Ist Dun Morogh gefährlich?",a="Während die Hauptstraßen und Städte von zwergischen Gebirgswächtern bewacht werden, stellt die Wildnis eine ernsthafte Gefahr dar. Wilde Tiere wie Grizzlybären, Bergeber, hungernde Wölfe und grausame Wendigos durchstreifen die Schneefelder. Feindselige Frostmähnen-Trolle unternehmen Überfälle von Bergrücken wie dem Schimmergrat und der Höhle der Frostmähnen aus. Unterdessen haben unterirdische Troggs den Steinbruch Gol'Bolar und die Eisklamm überrannt, und radioaktive, verseuchte Gnome schleichen durch die kontaminierten Außenbezirke von Gnomeregan.",al={"ist dun morogh sicher","bedrohungen in dun morogh","gefahren in dun morogh"}},["6bfc0e90"]={q="Warum will jeder, dass ich im Steinbruch Gol'Bolar Troggs töte?",a="Der Steinbruch Gol'Bolar im südöstlichen Dun Morogh ist ein lebenswichtiges zwergisches Ausgrabungs- und Bergbaulager. Beim Graben nach Stein und kostbarem Erz brachen die Bergleute in unterirdische Tunnel ein und legten Horden von wilden Troggs frei. Die Kreaturen schwärmten in die offene Grube und das Bergwerk, drängten die Arbeiter zurück und legten den Betrieb lahm. Die Gebirgswächter und Aufseher sind auf fähige Rekruten angewiesen, um die eingedrungenen Troggs auszulöschen, damit das Königreich seinen Steinbruch zurückgewinnen kann.",al={"troggs in gol'bolar","warum troggs im steinbruch töten","problem im steinbruch gol'bolar"}},bf67ca5d={q="Wohin soll ich mich nach Dun Morogh begeben?",a="Sobald Ihr Eure Aufgaben in Dun Morogh abgeschlossen und ausreichend Erfahrung gesammelt habt, führt Eure Reise auf natürliche Weise nach Osten in Richtung Loch Modan. Ihr könnt zu Fuß entweder durch die Tunnel des Nordtorpasses oder des Südtorpasses gehen oder einen Greifenritt vom Flugmeisterplatz tief in Eisenschmiede direkt zum Dorf Thelsamar am See nehmen.",al={"wohin nach dun morogh","nächste zone nach dun morogh","nach dun morogh"}},["44145090"]={q="Wie bin ich in Dun Morogh gelandet?",a="Wenn Ihr ein Zwerg oder Gnom seid, der seine Reise beginnt, habt Ihr in den geschützten Trainingsgeländen vom Coldridgetal begonnen, bevor Ihr Euch durch den Pass in das eigentliche Dun Morogh gewagt habt. Zwerge stammen aus diesen rauen Gipfeln, während gnomische Flüchtlinge nach dem Fall von Gnomeregan hierher flohen, um bei ihren zwergischen Verbündeten Zuflucht zu suchen. Reisende aus anderen Königreichen kommen normalerweise durch die großen Tore von Eisenschmiede über Die Tiefenbahn aus Sturmwind oder durch eine Wanderung nach Westen durch die Gebirgspässe von Loch Modan an.",al={"wie bin ich hierher gekommen","wie komme ich nach dun morogh","warum bin ich hierher gekommen"}},["8cf74af4"]={q="Was soll ich in Dun Morogh tun?",a="Das verschneite Reich von Eisenschmiede braucht jeden fähigen Verteidiger. Feindselige Frostmähnen-Trolle bedrohen zwergische Siedlungen von den hohen Bergrücken aus, wilde Troggs haben den Steinbruch Gol'Bolar überrannt und mutierte, verseuchte Gnome schleichen durch die kontaminierten Ruinen von Gnomeregan im Westen. Siedlungen vor Ort wie Kharanos und Bräuhall brauchen dringend Rekruten, um wilde Tiere zurückzudrängen und die Wege zu säubern. Leiht ihnen Eure Stärke, um die Region zu sichern, Eure Fähigkeiten zu schärfen und Euch als würdig zu erweisen, dem allgemeinen Ruf der Allianz zu folgen.",al={"was soll ich hier tun","mein ziel in dun morogh","was mache ich hier"}}},fp="10,226,21.341.0,16.532.0,21.397.0,31.294.0,28.274.0,36.235.0,41.202.0,29.271.0,17.212.0"}
P.entries["zone:durotar"] = {n="Durotar",s="Durotar ist ein Land aus roten Schluchten, in dem junge Orcs und Dunkelspeertrolle sich für The New Horde beweisen. Kriegshäuptling Thrall gründete diese trockene Heimat nach dem Dritten Krieg und benannte sie nach seinem Vater Durotan. Der Südstrom und Das große Meer grenzen das Land ein. Klingenhügel und die Kriegerstadt Orgrimmar erheben sich aus seinem Fels. Doch Stacheleberstämme halten sich hier weiterhin, ebenso gestrandete Allianztruppen.",h="Durotar ist ein Land aus roten Schluchten, in dem junge Orcs und Dunkelspeertrolle sich für The New Horde...",kw={"durotan","durotar","die echoinseln","orgrimmar","klingenhügel","sen'jin","die knochenhöhle","der südstrom","thrall","burg tiragarde","das tal der prüfungen","zalazane"},ang={["class:Shaman"]="Als junger Schamane findet Ihr das trockene Land voller roher Elementargeister. Ihr besucht heilige Orte wie den Geisterfelsen und den Schrein der schlafenden Flamme, um Euch auf Erde und Feuer einzustimmen.",["class:Warlock"]="Thrall lässt dunkle Magie streng verfolgen und zwingt die Zirkel des Shadow Council, sich an Orten wie der Knochenhöhle und tief unter der Stadt in den gewundenen Höhlen des Flammenschlunds zu verstecken.",["faction:Alliance"]="Durotar ist das schlagende Herz der Streitmacht der Horde. Jeder Reisende der Allianz, der durch die sonnenverbrannten Schluchten zieht, wird von aggressiven Patrouillen und einheimischen Bestien gleichermaßen sofort gejagt.",["race:Orc"]="Durotar ist das neue gelobte Land Eures Volkes, errungen durch Schweiß und Blut nach Jahren dämonischer Trägheit und Internierung. Euch im Tal der Prüfungen zu beweisen, ist der erste Übergangsritus für jeden neuen Champion der Horde.",["race:Troll"]="Nachdem sie der Seehexe im Großen Meer entkommen waren, fanden die Dunkelspeer an Thralls Seite Zuflucht in Durotar. Doch der Verräter Zalazane riss die Echoinseln von innen an sich. Die Inseln zurückzuerobern und Sen'jin zu verteidigen, ist eine persönliche Sache."},sec={{t="Eine harte neue Heimat",b="Thrall wählte diese raue Grenzregion mit Absicht. Hier sollten sich die Orcs durch Arbeit und Entschlossenheit einen ehrlichen Lebensunterhalt verdienen, nicht durch Eroberung. Der rissige rote Boden und die hoch aufragenden Felstürme erinnern sie an Draenor vor dessen Untergang. Wasser ist knapp, und nur wenig Land lässt sich bewirtschaften, doch die Horde hat sich mit der kargen Erhabenheit angefreundet. Durotar beweist, dass die Orcs ihr eigenes Schicksal geschmiedet haben."},{t="Feinde an der Grenze",b="Die Horde hält Durotar, doch um das Land zu sichern, muss sie weiterkämpfen. Die Razormane-Stacheleber wurden bei der Gründung der Nation vertrieben und überfallen von den westlichen Klippen aus die Höfe. Im Süden halten die Überreste der Flotte von Großadmiral Daelin Prachtmeer noch immer Burg Tiragarde und weigern sich aufzugeben. Schlimmer noch: Der Dämonenkult der Burning Blade lauert in verborgenen Schluchten und tiefen Meereshöhlen. Er verführt junge Orcs dazu, zur Teufelsmacht zurückzukehren."},{t="Die Prüfungen der Dunkelspeer",b="An der Südküste liegt Sen'jin, wo sich die verbannten Dunkelspeertrolle unter Meister Gadrin versammeln. Ihre Heimat lag auf den nahegelegenen Echoinseln. Doch der Hexendoktor Zalazane verfiel dem Wahnsinn und versklavte mit dunklem Voodoo sein eigenes Volk. Die Dunkelspeer können die Inseln nicht allein zurückerobern. Sie zählen auf neue Krieger aus dem Tal der Prüfungen, die Zalazanes Griff brechen sollen."}},faq={{q="Warum ließ Thrall die Horde in einer so kargen Wüste siedeln?",a="Thrall wählte dieses unwirtliche Gebiet ganz bewusst. Nachdem er die Orcs über Das große Meer nach Kalimdor geführt hatte, ließ er sie sich hier niederlassen. Die rote Erde und die zerklüfteten Tafelberge erinnerten die Orcs an ihre Heimatwelt Draenor, während die harten Bedingungen als Sühne und als Schule der Disziplin dienten. Sie machten sich die natürlichen Verteidigungen des Landes zunutze. Thrall glaubte, sein Volk müsse sich das Überleben durch ehrliche Mühsal verdienen, statt fruchtbares Land zu erobern. So sollte es nicht wieder in blutdürstige Selbstzufriedenheit verfallen. Westlich des Südstroms lag das Brachland, im Norden die zerstörte Wildnis von Azshara.",al={"warum hier siedeln","warum durotar","warum ist durotar karg"}},{q="Nach wem wurde Durotar benannt?",a="Das Land wurde zu Ehren von Durotan benannt, Thralls verstorbenem Vater und früherem Häuptling des Frostwolfklans. Durotan hatte sich gegen die dämonische Verderbnis der Orcclans gestellt und wurde auf Befehl des Hexenmeisters Gul'dan ermordet.",al={"nach wem ist durotar benannt","durotan","herkunft des namens durotar"}},{q="Warum sind Menschen in Burg Tiragarde?",a="Die Soldaten in Burg Tiragarde sind überlebende Kul-Tiraner unter Leutnant Benedict, die von der Invasionsflotte des Großadmirals Daelin Prachtmeer zurückblieben. Sie halten die verfallende Garnison. Selbst nachdem Prachtmeer getötet worden war, weigerten sich diese Truppen aufzugeben oder abzuziehen. Sie halten einen befestigten feindlichen Außenposten direkt an Durotars Südküste.",al={"warum menschen in durotar","menschen in burg tiragarde","truppen von prachtmeer in durotar"}},{q="Worum geht es bei dem Konflikt auf den Echoinseln?",a="Die Dunkelspeertrolle errichteten ihre Heimat auf Kalimdor ursprünglich auf den Echoinseln. Doch ein mächtiger Hexendoktor namens Zalazane verfiel dem Wahnsinn und wandte seine dunkle Magie gegen seine Brüder und Schwestern. Er versklavte ihren Geist. Dadurch verloren die Dunkelspeer ihre Heimat. Die Überlebenden flohen aufs Festland und gründeten Sen'jin, von wo aus sie Angriffe starten, um Zalazanes Griff zu brechen.",al={"was geschah mit den echoinseln","warum sen'jin","zalazanes geschichte"}},{q="Was treibt die Burning Blade in Durotar?",a="Die Burning Blade ist ein subversiver Dämonenkult, der dem Shadow Council und der Brennenden Legion dient. Agenten lauern an abgelegenen Orten wie der Knochenhöhle und im Koven der Brennenden Klinge. Sie versuchen, Thralls Führung zu untergraben und leicht beeinflussbare Orcs zurück in den Dämonendienst zu locken.",al={"burning blade in durotar","kultisten in der knochenhöhle","dämonen in durotar"}},{q="Wie ist Durotar mit anderen Regionen verbunden?",a="Eine Brücke über den Südstrom führt nach Westen ins Brachland, während nördlich die zerstörte Wildnis von Azshara liegt. Außerhalb von Orgrimmar ermöglicht ein Zeppelinmast direkte Flüge über den Kontinent nach Tirisfal und zum Basislager Grom'gol im Schlingendorntal.",al={"wie durotar verlassen","reisen in durotar","ausgänge aus durotar"}}},fx={["9c6f22ef"]={q="Was ist Sen'jin?",a="Sen'jin ist eine küstennahe Fischersiedlung am südlichen Ufer von Durotar, die als vorläufige Heimat der Dunkelspeere dient. Das von Häuptling Vol'jin gegründete Dorf beherbergt Alchemisten, Jäger und Schamanen, die daran arbeiten, die Küste des Festlands zu sichern und das Dorf vor Wassermonstern und verräterischen Verwandten aus dem Wasser zu schützen.",al={"sen'jin dorf","was ist sen'jin","sen'jin"}},["115273b6"]={q="Wer war Sen'jin?",a="Sen'jin war der ehrwürdige Schattenjäger und Häuptling der Dunkelspeere auf ihren angestammten Inseln im Großen Meer. Während des Dritten Krieges sah er Thralls Ankunft und die Befreiung seines Volkes voraus, opferte jedoch sein Leben, um den Stamm vor rasenden Murlocs und Meereshexen zu verteidigen, bevor sie fliehen konnten.",al={"wer ist sen'jin","sen'jin lore"}},["6c467bea"]={q="Warum leben Trolle in Durotar?",a="Der Stamm der Dunkelspeere verdankt sein Überleben Thrall, der sie rettete, als ihre ursprüngliche Heimatinsel unter den Angriffen aus dem Wasser zu versinken begann. Sie schworen der Horde die Treue, begleiteten die Orcs nach Kalimdor und erhielten die vor der Küste liegenden Echoinseln als Siedlungsgebiet, wobei sie enge kulturelle und militärische Bindungen mit Orgrimmar pflegen.",al={"warum sind hier trolle","darkspear in durotar"}},["84e0b3bb"]={q="Wohin führt die Reise nach Klingenhügel?",a="Sobald Ihr Eure Stärke in der Umgebung von Klingenhügel bewiesen habt, werdet Ihr beordert, entweder nach Norden in die großen Tore von Orgrimmar zu ziehen, um die höhere militärische Führung zu treffen, oder westwärts über den Südstrom in die weite Ausdehnung des Brachlands, wo größere Schlachten gegen Stacheleber, Zentauren und Eindringlinge der Allianz auf Euch warten.",al={"nach klingenhügel","wohin nach klingenhügel","nächstes gebiet nach klingenhügel"}},["25a880c0"]={q="Wie bin ich in Durotar gelandet?",a="Wenn Ihr ein Orc seid, ist dieses raue, rote Land die neue souveräne Heimat Eures Volkes, die von Kriegshäuptling Thrall nach dem Exodus aus den Östlichen Königreichen erschaffen wurde. Ihr seid hier erwachsen geworden und wurdet in das abgelegene Tal der Prüfungen geschickt, um Eure Stärke unter der Wüstensonne zu testen, bevor Ihr Euch Euren Platz in der Horde verdientet. Wenn Ihr ein Dunkelspeertroll seid, floh Euer Volk an der Seite von Thrall über das Große Meer und besiedelte die Küste, nachdem es von dem verräterischen Hexendoktor Zalazane von den nahe gelegenen Echoinseln vertrieben worden war.",al={"wie bin ich hierher gekommen","warum bin ich in durotar","wie kam ich hier an"}},d894869f={q="Was soll ich in Durotar tun?",a="Ihr seid hier, um Euch als würdig für die Horde zu erweisen und das Überleben einer jungen Nation zu sichern. Durotar bleibt ein raues Grenzland, das von allen Seiten bedrängt wird: Klingenhauer-Stacheleber überfallen Siedlungen, menschliche Überreste von Kul Tiras halten hartnäckig an Burg Tiragarde fest, und der heimtückische Kult der Burning Blade schmiedet Pläne in schattigen Schluchten. Indem Ihr Außenposten wie Klingenhügel und Sen'jin unterstützt, helft Ihr dabei, die Felsen zu zähmen, gefährdete Siedlungen zu schützen und Euch Euren Platz unter den Champions zu verdienen, die durch die großen Straßen des nahe gelegenen Orgrimmar wandeln.",al={"was soll ich in durotar tun","was ist meine aufgabe hier","was mache ich hier"}},["04dde4a2"]={q="Was ist Durotar?",a="Durotar ist das felsige, sonnenverbrannte Reich an der Ostküste von Kalimdor, das als stolze Heimat der Horde dient. Gegründet von Kriegshäuptling Thrall nach dem Dritten Krieg, spiegeln seine rote Erde, die zerklüfteten Canyons und das raue Klima bewusst Draenor wider, die angestammte Welt der Orcs. Begrenzt durch Der Südstrom im Westen und Das große Meer im Süden und Osten, beherbergt Durotar die Hauptstadt Orgrimmar und bietet sowohl Orcs als auch Dunkelspeeren eine Heimat.",al={"über durotar","informationen zu durotar","wo liegt durotar"}},cb6442fd={q="Was ist in Durotar passiert?",a="Ursprünglich ein Weideland, das lose von Stacheleberstämmen gehalten wurde, wurde Durotar zum Ziel von Thralls Exodus über Das große Meer. Nachdem verbündete Streitkräfte einheimische Bestienstämme zurückgedrängt und über die Brennende Legion am Hyjal triumphiert hatten, etablierte Thrall Durotar offiziell als souveräne orcische Nation. Kurz nach ihrer Gründung fiel die Flotte von Daelin Prachtmeer an der Ostküste ein, doch die Horde schlug die Armada zurück und trieb die menschlichen Überreste in die Burg Tiragarde.",al={"geschichte von durotar","vergangenheit von durotar"}},b3a1e6d0={q="Wer lebt in Durotar?",a="Durotar wird als Stammesherrschaft von Kriegshäuptling Thrall vom Sitz in Orgrimmar aus regiert. Orcs machen die große Mehrheit der Bevölkerung aus, begleitet von den im Exil lebenden Dunkelspeeren in der Nähe von Sen'jin. Tauren-Verbündete und besuchende Abgesandte der Verlassenen durchqueren häufig die Region, während feindselige Taschen von Stachelebern, Zentauren, Harpyien und Kul Tiras-Marines die Grenzen in den äußeren Felsen streitig machen.",al={"wer leitet durotar","bevölkerung von durotar","einwohner von durotar"}},b78335a1={q="Ist Durotar gefährlich?",a="Ja. Jenseits der befestigten Straßen und Tore von Siedlungen wie Klingenhügel und Orgrimmar bleibt Durotar weitgehend ungezähmt. Giftige Skorpide, räuberische Raptoren und Krokilisken durchstreifen die Wildnis. Schlimmer noch, verschanzte Feinde belästigen ständig die Reisenden der Horde: Razormane-Stacheleber greifen aus den nördlichen Canyons an, Kolkar-Zentauren plündern Wasserlöcher, Marines der Menschen besetzen die Schipperküste und heimliche Hexenmeister der Burning Blade lauern im nahegelegenen Schatten.",al={"ist durotar sicher","bedrohungen in durotar","gefahren von durotar"}},["923cfd3c"]={q="Was ist Klingenhügel und warum ist er hier?",a="Klingenhügel ist das wichtigste befestigte Wegekreuz im zentralen Durotar. Direkt an der Verbindungsstelle gelegen, die Sen'jin im Süden, Das Brachland jenseits vom Südstrom im Westen und Orgrimmar im Norden verbindet, verankert er die Logistik und Verteidigung der Horde. Stark dominiert von seinen militärischen Kasernen und Wachtürmen, koordiniert die Siedlung Grenzpatrouillen und dient als primärer Außenposten, der Reisende vor den an der Küste lebenden Marines und Plünderern schützt.",al={"klingenhügel","über klingenhügel","warum klingenhügel"}},["1bf45605"]={q="Wer hat Klingenhügel erbaut?",a="Klingenhügel wurde von Thralls Horde kurz nach ihrer Ankunft in Kalimdor erbaut. Ursprünglich nur ein kahler Hügel an der Grenze – bekannt dafür, dass Rexxar dort einen Hinterhalt von Streitkräften von Kul Tiras abfing, der für Thrall bestimmt war – wurde der Ort mit einer robusten Kaserne und Bauten befestigt, um die Verteidigung der Horde zwischen dem Meer, den Canyons und der nördlichen Hauptstadt zu verankern.",al={"wer hat klingenhügel erbaut","ursprung von klingenhügel"}},["6b0364de"]={q="Gehört Klingenhügel zu Orgrimmar?",a="Er ist nicht Teil der Stadt selbst, aber er untersteht direkt der Verwaltung und militärischen Autorität von Orgrimmar. Klingenhügel fungiert als äußere Garnisonsstadt und Bereitstellungsort im zentralen Durotar, der ankommende Reisende filtert, Rekruten ausbildet und die südlichen Zugänge zu den hoch aufragenden nördlichen Toren der Hauptstadt sichert.",al={"gehört klingenhügel zu orgrimmar","klingenhügel und orgrimmar"}},["406d1dd3"]={q="Hat jemand vor der Horde in Durotar gelebt?",a="Die Stacheleber beanspruchten das Land lange bevor die Horde ankam. Borstige Stämme, insbesondere die Razormane, besetzten die Felsen und Flussufer dessen, was als Teil vom Brachland galt. Entscheidende Kampagnen unter der Führung von Thrall drängten sie in entlegene Canyons und nach Westen über Der Südstrom, obwohl sie immer noch erbittert kämpfen, um ihr angestammtes Territorium zurückzuerobern.",al={"wer lebte zuerst hier","ureinwohner von durotar"}},f5af283b={q="Wer hat das Sagen in der Umgebung von Klingenhügel?",a="Die lokale Verteidigung und militärische Operationen in Klingenhügel unterliegen erfahrenen Veteranen wie Gar'Thok, während orcische Offiziere wie Orgnil Narbenseele die Spionageabwehr und interne Untersuchungen leiten. Gemeinsam verwalten sie die Stadtverteidigung, organisieren Jagdausflüge und beauftragen vielversprechende Rekruten mit der Verteidigung des zentralen Durotar.",al={"anführer von klingenhügel","wer leitet klingenhügel"}},["87682b7e"]={q="Wer sind diese Seeleute von Kul Tiras und warum sind sie an unserer Küste?",a="Es sind Überreste der großen Armada, die vom verstorbenen Großadmiral Daelin Prachtmeer von Kul Tiras befehligt wurde. Prachtmeer weigerte sich, Frieden mit den Orcs zu akzeptieren, und errichtete die Burg Tiragarde entlang der Ostküste als Stützpunkt, um Krieg zu führen. Selbst nachdem der Admiral bei Theramore getötet wurde, verschanzten sich seine überlebenden Offiziere in den Ruinen und setzten ihren unnachgiebigen Kreuzzug gegen die Horde fort.",al={"seeleute von kul tiras","warum sind menschen in durotar","seeleute in burg tiragarde"}},["52bc9e7d"]={q="Wer ist Lieutenant Benedict?",a="Lieutenant Benedict ist der überlebende Offizier von Kul Tiras, der die feindselige Garnison in der Burg Tiragarde befehligt. Nach dem Tod von Admiral Prachtmeer sammelte Benedict die verbleibenden Soldaten und Marines gemäß geltenden Befehlen und unterhielt eine befestigte menschliche Bastion in Durotar, die regelmäßig orcische Siedlungen und Karawanen schikaniert.",al={"lieutenant benedict","benedict und burg tiragarde","wer ist benedict"}}},fp="7,395,16.374.0,23.415.0,27.369.0,56.632.0,28.226.0,51.345.0,39.378.0,43.280.1,39.261.0"}
P.entries["zone:duskwood"] = {n="Dämmerwald",s="Im Dämmerwald verbirgt ewige Düsternis unter einem Fluch die sonnige Vergangenheit des Waldes. Sturmwind hat seine menschlichen Bewohner aufgegeben, die sich in Dunkelhain unter dem Schutz von The Nachtwache ans Überleben klammern. Ghule, riesige giftige Spinnen, plündernde Oger und wilde, geheimnisvolle Worgen streifen durch die Haine und heimgesuchten Grabhügel.",h="Im Dämmerwald verbirgt ewige Düsternis unter einem Fluch die sonnige Vergangenheit des Waldes.",kw={"althea schwarzhaupt","grand hamlet","dunkelhain","dämmerwald","ello schwarzhaupt","bibbers","morbent fel","the night watch","rabenflucht","sichel von elune","sven yorgen","zwielichtshain","worgen"},ang={["class:Druid"]="Als Druide könnt Ihr die tiefe Verbindung des uralten Großen Baums zum Smaragdgrünen Traum erforschen und die schlummernde Magie der Welt untersuchen.",["class:Paladin"]="Als Paladin erwartet Euch in Rabenfluchts entweihten Grabhügeln eine dringende Prüfung, denn Morbent Fels finstere Nekromantie verlangt nach dem Licht.",["faction:Alliance"]="Als Gebiet der Allianz erhält der Dämmerwald keine offizielle Truppenunterstützung aus Sturmwind. Nur The Nachtwache und heldenhafte Abenteurer stehen zwischen seiner Bevölkerung und der Vernichtung.",["profession:Herbalism"]="Als Kräuterkundler könnt Ihr seltene Pflanzen wie Grabmoos und Königsblut in den heimgesuchten Grabhügeln und auf verfluchtem Boden finden. Sie locken Sammler an, die den ruhelosen Untoten auf den Friedhöfen trotzen wollen."},sec={{t="Von Sonnenschein zu Schatten",b="Einst versorgte der Dämmerwald das Königreich Sturmwind mit fruchtbarem Ackerland und wohlhabenden Siedlungen wie Grand Hamlet und Rabenflucht. Sein Niedergang begann, als Wächter Medivh während des Ersten Krieges in Karazhan fiel. Wellen verderbter Teufelsmagie verwandelten das Waldland in einen knorrigen, schattigen Morast.\n\nSpinnen wurden zu schrecklichen Raubtieren, und fliehende Wölfe strömten nach Norden in den Wald von Elwynn. Aus Grand Hamlet wurde Dunkelhain, wo die Stadtbewohner größtenteils sich selbst überlassen blieben, nachdem die königliche Garnison abgezogen war, um die Hauptstadt zu verteidigen."},{t="Die Sichel und die Wolfsmenschen",b="Die Nachtelfenpriesterin Velinde Sternensang brachte die Sichel von Elune in den Dämmerwald. Nachdem sie in Rolands Verdammnis, einer stillgelegten Mine, verschwunden war, grub der schürfende Arbeiter Bibbers das Relikt schließlich aus. Der sorglose Umgang mit der Waffe entfesselte Worgen, gefräßige zweibeinige Wolfsbestien aus einer anderen Welt. In ewigen Nebel und Blutrausch gehüllt, rissen diese Raubtiere durch die westlichen Haine. Sie verschlimmerten das Elend einer Region, die bereits von untoten Flüchen geplagt wurde."},{t="Ein bedrängtes Grenzland",b="Kommandantin Althea Schwarzhaupt und ihre freiwillige Miliz, The Nachtwache, halten Dunkelhain am Leben. Lord Ello Schwarzhaupt versucht, die verfallende Siedlung zu regieren. Jenseits des von Laternen erhellten Stadtgebiets lauert überall Gefahr. Die ruhelosen Toten, die der Nekromant Morbent Fel erweckt hat, regen sich auf dem gewaltigen Friedhof von Rabenflucht. Vul'Gol-Oger kamen aus dem Gebirgspass der Totenwinde, um den Süden zu beanspruchen, während Dunkle Reiter die Kreuzwege auf der unerbittlichen Suche nach der verlorenen Sichel durchstreifen."},{t="Der Zwielichtshain",b="Nahe dem Zentrum des Dämmerwalds liegt ein tiefer, uralter Krater, den die Verderbnis der Umgebung verschont hat: der Zwielichtshain. Ein uralter Großer Baum dort birgt ein ruhendes Portal in den Smaragdgrünen Traum. Sanfte, ätherische Dämmerung taucht dieses überirdische Heiligtum im sterbenden Land in mildes Licht. Schlafende druidische Energien wachen darüber."}},faq={{q="Warum heißt er Dämmerwald?",a="Der Dämmerwald war einst eine lebendige, sonnige Provinz von Sturmwind. Als Wächter Medivh während des Ersten Krieges im nahe gelegenen Karazhan erschlagen wurde, ergossen sich unberechenbare Teufelsenergien über den Wald, verdunkelten das Sonnenlicht und verdrehten die Pflanzenwelt. Die Dunkelheit gab dem Land seinen Namen.",al={"warum ist der dämmerwald dunkel","geschichte von grand hamlet","was geschah mit grand hamlet"}},{q="Woher kamen die Worgen?",a="Die Nachtelfe Velinde Sternensang brachte die mystische Sichel von Elune in die Region und verschwand nahe Rolands Verdammnis. Jahre später störte ein verängstigter Arbeiter namens Bibbers die Sichel in der Mine. Unwissentlich öffnete er Risse, die wilde Wolfsmenschen in den Wald riefen.",al={"warum gibt es worgen","ursprung der worgen im dämmerwald","sichel von elune und worgen"}},{q="Warum gibt es so viele Untote in Rabenflucht?",a="Auf dem Friedhof von Rabenflucht ruhen unzählige Seelen, die Hunger, Bestien und Kriegen zum Opfer fielen. Der niederträchtige Nekromant Morbent Fel schlug sein Lager auf dem Verlassenen Gut auf und belebte die Gräber mit dunkler Zauberei zu Ghulen, Skeletten und Abscheulichkeiten.",al={"untote in rabenflucht","warum geister im dämmerwald","morbent fel und untote"}},{q="Warum schickt Sturmwind keine Soldaten, um Dunkelhain zu helfen?",a="Da König Varian Wrynn vermisst wird und die Ressourcen knapp sind, zog die Regentschaft von Sturmwind ihr Militär zurück, um Elwynn und den Thron zu schützen. Dunkelhain ist auf sich allein gestellt und wird ausschließlich von der freiwilligen Miliz The Nachtwache verteidigt.",al={"warum keine sturmwinder wachen","sturmwind gab dunkelhain auf","wo ist die armee"}},{q="Wer sind die Dunklen Reiter, die durch die Wälder streifen?",a="Die Dunklen Reiter sind geheimnisvolle, vermummte Reiter aus dem Gebirgspass der Totenwinde nahe Karazhan. Angelockt von der Freisetzung der Sichel von Elune drangen sie in den Dämmerwald ein und ermordeten rücksichtslos Sven Yorgens Familie, während sie nach dem Artefakt suchten.",al={"dunkle reiter im gebirgspass der totenwinde","reiter auf yorgens hof","wer sind die dunklen reiter"}},{q="Was ist der gewaltige Baum im Zentrum des Kraters?",a="Der Krater ist der Zwielichtshain, in dem ein uralter Großer Baum steht. Der Baum enthält ein ruhendes Portal in den Smaragdgrünen Traum. Im Hain herrscht eine friedliche, mystische Dämmerung, die sich von der verfluchten Dunkelheit des Waldes unterscheidet.",al={"baum im zwielichtshain","grünes portal im dämmerwald","kraterbaum"}}},fx={["9267ad89"]={q="Ist die Dunkelheit im Dämmerwald magisch oder natürlich?",a="Sie ist vollkommen magisch. Der ständig bewölkte Himmel und der erstickende Nebel stammen von dunklen Flüchen, die durch Medivhs Tod im nahe gelegenen Gebirgspass der Totenwinde entfesselt wurden, in Verbindung mit uralten Artefakten wie der Sichel von Elune, die die natürliche Ordnung des Waldes stören.",al={"ist der nebel im dämmerwald magie","magischer fluch dämmerwald","warum keine sonne im dämmerwald"}},aa573e0c={q="Wer hat in Dunkelhain das Sagen?",a="Dunkelhain wird von Lord Ello Schwarzhaupt, dem Bürgermeister, zusammen mit dem Rat von Dunkelhain regiert. Die Stadt verlässt sich stark auf ihre eigenen Bürger, um Ordnung zu halten und im Rathaus für Gerechtigkeit zu sorgen.",al={"anführer von dunkelhain","wer regiert dunkelhain","rat von dunkelhain"}},["63356d06"]={q="Wer ist Lord Ello Schwarzhaupt?",a="Lord Ello Schwarzhaupt ist das Oberhaupt des angesehenen Adelsgeschlechts Schwarzhaupt, dessen Wurzeln in Grand Hamlet bis vor den Ersten Krieg zurückreichen. Als Bürgermeister kämpft er hartnäckig darum, den Betrieb von Dunkelhain aufrechtzuerhalten, obwohl er vom königlichen Hof in Sturmwind von militärischer Unterstützung abgeschnitten ist.",al={"wer ist ello schwarzhaupt","lord schwarzhaupt","bürgermeister von dunkelhain"}},a73a6b59={q="Ist Dunkelhain noch treu gegenüber Sturmwind?",a="Ja, Dunkelhain bleibt technisch der Allianz und König Anduin gegenüber treu, aber die Bevölkerung hegt tiefe Bitterkeit. Sie fühlen sich vom Adel der Hauptstadt völlig im Stich gelassen und sind gezwungen, sich an jeder Grenze selbst gegen Monster zu verteidigen.",al={"ist dunkelhain allianz","dunkelhain sturmwind loyalität","untersteht dunkelhain sturmwind"}},ec7f551f={q="Was ist The Nachtwache und warum brauchen sie meine Hilfe?",a="The Nachtwache ist eine lokale Freiwilligenmiliz, die von den Bürgern Dunkelhains gegründet und ausgebildet wurde, um die Hauptstraßen zu patrouillieren und das Dorf zu verteidigen. Da die Armee von Sturmwind abgezogen wurde, sind sie im Kampf gegen Ghule, Skelette, Worgen und Bestien viel zu dünn besetzt, was sie dazu zwingt, reisende Abenteurer anzuheuern, um die Bedrohungen zu dezimieren.",al={"was ist the night watch","night watch miliz","warum der night watch helfen"}},be442b70={q="Wer ist Kommandantin Althea Schwarzhaupt?",a="Kommandantin Althea Schwarzhaupt ist die Tochter von Lord Ello und die entschlossene Anführerin von The Nachtwache. Sie koordiniert die Verteidigung von Dunkelhain und rekrutiert direkt Helden, um gegen die Untoten und andere Monstrositäten zurückzuschlagen, die aus den Wäldern kriechen.",al={"kommandantin althea","wer ist althea schwarzhaupt","night watch kommandantin"}},c10a928d={q="Woher kommen all diese Skelette und Ghule?",a="Die Toten erheben sich vor allem vom Friedhof von Rabenflucht und dem Friedhof \"Stille Gärten\". Der Nekromant Morbent Fel, der sich in seinem Haus auf dem Forlorn Rowe versteckt, praktiziert aktiv dunkle Künste, um Leichen zu erheben und die Ruhestätten der Region in wandelnde Legionen zu verwandeln.",al={"warum untote im dämmerwald","skelette dämmerwald quelle","woher kommen ghule"}},f53dcf97={q="Was ist in Raven Hill passiert? Warum ist es verlassen?",a="Raven Hill war einst eine stattliche Stadt, eine Schwesterstadt von Grand Hamlet. Als dunkle Flüche und monströse Kreaturen die umliegende Landschaft überrannten, flohen die Lebenden oder wurden niedergemetzelt. Heute hat sein weitläufiger Friedhof das Gebiet verschlungen, und nur wenige verängstigte Ausgestoßene wie Bibbers wagen es, sich seinen Ruinen zu nähern.",al={"raven hill geschichte","warum ist raven hill verlassen","was geschah in raven hill"}},["64d771df"]={q="Warum ist jeder in Dunkelhain so grimmig und verängstigt?",a="Die Dorfbewohner leben in ständiger Angst. Sie werden von allen Seiten von unnatürlichen Raubtieren, Worgen und ruhelosen Toten belagert, ohne offizielle Verstärkung aus Sturmwind. Jede Reise außerhalb des fackelbeleuchteten Zentrums der Stadt birgt das Risiko eines Hinterhalts durch Schrecken, die in der Dunkelheit lauern.",al={"dunkelhain leute angst","warum hat dunkelhain angst","dunkelhain paranoja"}},["2e45eefe"]={q="Ist der Dämmerwald gefährlich?",a="Extrem gefährlich. Die Straßen werden von wilden Worgen, riesigen giftigen Spinnen, umherstreifenden Ghulen, aggressiven Ogern und Defias-Banditen durchstreift. Schon ein leichtes Abweichen vom Pfad in den Wald kann Euch mit tödlichen untoten Champions oder unsichtbaren Schrecken konfrontieren.",al={"ist der dämmerwald gefährlich","wie gefährlich ist der dämmerwald","bedrohungsstufe dämmerwald"}},["4f653c45"]={q="Wie bin ich im Dämmerwald gelandet?",a="Ihr seid wahrscheinlich von den sonnigen Obstgärten von Elwynn kommend über den Nazferiti-Fluss nach Süden gezogen oder seid der Straße südöstlich von den trockenen Ebenen von Westfall gefolgt. Alternativ erreichen Reisende das Gebiet oft über die südliche Brücke von Rotkammgebirge, nachdem sie den Leuten von Seenhain geholfen haben. Sobald Ihr unter das dichte Blätterdach getreten seid, verschwand das Tageslicht hinter einem undurchdringlichen Grau. Das Königreich Sturmwind beansprucht diese Provinz zwar noch auf dem Papier, aber seine Soldaten haben die Grenze längst aufgegeben und lassen jeden, der die Grenzen überschreitet, diese schattenhaften Straßen allein beschreiten.",al={"wie kam ich zum dämmerwald","wie bin ich hierher gekommen","woher kam ich im dämmerwald"}},["39e18767"]={q="Was soll ich im Dämmerwald tun?",a="Dunkelhain führt einen verzweifelten Kampf um das eigene Überleben, und da Sturmwind sich weigert, Verstärkung zu schicken, suchen die Bürger bei jedem fähigen Reisenden Hilfe. Die örtliche Miliz, The Nachtwache, braucht Eure Klinge, um die Ghule, Skelette und albtraumhaften Worgen zurückzuschlagen, die in die Stadt und auf die Straßen eindringen. Erkundigt Euch bei Kommandantin Althea Schwarzhaupt und Bürgermeister Lord Ello Schwarzhaupt in Dunkelhain oder reist nach Westen, um die Schrecken des Friedhofs rund um Raven Hill zu untersuchen. Ob Ihr nun überwucherte Spinnen beseitigt oder die dunkle Geschichte erforscht, die verlassene Gehöfte heimsucht, dieses Land wird Euren Mut bis an die absoluten Grenzen testen.",al={"was tue ich im dämmerwald","warum bin ich hier dämmerwald","was ist mein ziel hier"}},["31aef3fe"]={q="Was ist der Dämmerwald? Warum ist es hier immer dunkel?",a="Der Dämmerwald ist eine düstere, dicht bewaldete Region südlich von Wald von Elwynn. Einst war er eine fruchtbare Provinz des Königreichs Sturmwind. Das Land verfiel in eine unnatürliche, ewige Dämmerung, als Medivh in Karazhan erschlagen wurde, was Wellen dunkler magischer Energie entfesselte, die die Pflanzenwelt verdorrten ließen, dichten schwarzen Nebel heraufbeschworen und zahllose Monstrositäten anlockten, die unter den Ästen wandeln.",al={"warum ist der daemmerwald dunkel","was geschah mit dem daemmerwald","daemmerwald-lore"}},a3ed01d1={q="War der Dämmerwald schon immer so?",a="Nein. Vor dem Ersten Krieg war er eine sonnenbeschienene Region mit blühenden Siedlungen wie Grand Hamlet und Raven Hill. Überfälle der Alten Horde und der magische Kataklysmus, der von Medivhs Fall ausging, verwandelten das sonnige Waldland in das schattenhafte Reich der Albträume, das Ihr heute seht.",al={"war der daemmerwald immer dunkel","geschichte von brightwood","vergangenheit des daemmerwalds"}}},fp="8,307,23.516.0,27.456.1,24.445.0,18.302.0,26.262.0,31.267.1,43.223.0,53.223.0,43.221.1,46.207.0"}
P.entries["zone:dustwallow"] = {n="Düstermarschen",s="Mitten in Kalimdor liegen die Düstermarschen zwischen dem Brachland und dem großen Meer. Unterirdische Quellen speisen ihre tückischen Moore, in denen gefährliche Raubtiere, geheime Scharmützel zwischen den Fraktionen und der Schwarze Drachenschwarm lauern. Im Osten ist Die Insel Theramore eine Festung der Allianz; im Nordwesten halten die mit der Horde verbündeten Stonemaul-Oger Brackenwall.",h="Mitten in Kalimdor liegen die Düstermarschen zwischen dem Brachland und dem großen Meer.",kw={"alcaz","brackenwall","düstermarschen","jaina","sumpf","onyxia","der morast","stonemaul","tabetha","theramore","der drachensumpf"},ang={["class:Mage"]="Als Magier könnt Ihr durch die Moore zu Tabetha's Farm im Morast reisen. Die Einsiedlerin bietet einzigartiges Wissen über arkane Leitungen und uralte Kraftquellen.",["faction:Alliance"]="Die Insel Theramore ist das Herz der Präsenz der Allianz auf Kalimdor. Wenn Ihr über den Hafen von Menethil ankommt, bewacht Ihr die Dammwege und entwirrt ein Netz aus Deserteuren und verschwundenen Gesandten.",["faction:Horde"]="Gesandte der Horde kommen, um die bedrängten Stonemaul-Oger in Brackenwall zu unterstützen. Ihr helft, Drachenangriffe aus dem Drachensumpf abzuwehren, und behaltet die Bewegungen der Menschen an der Küste im Auge."},sec={{t="Eine versunkene Landschaft",b="Vor der Großen Teilung war Düstermarschen eine hoch gelegene Grasebene, auf der Herden umherzogen. Die Katastrophe zerschmetterte das Tal und ließ den Grundwasserspiegel steigen. So ertrank das Land in endlosen stehenden Tümpeln, moosigen Untiefen und erstickendem Schlamm.\n\nUnterirdische Quellen halten den Sumpf feucht und unter dichtem Nebel überflutet. Krokilisken, Raptoren und Spinnen lauern in den Mooren. Zerfallende Dammwege durchqueren sie, doch zerklüftete Untiefen und wandernde Moore machen jeden Schritt abseits der Wege gefährlich."},{t="Alter Hass und brüchige Waffenruhen",b="Die Düstermarschen blieben weitgehend wild, bis Lady Jaina Prachtmeer nach dem Dritten Krieg menschliche Flüchtlinge über das Meer führte und an der Ostküste die Zitadelle auf der Insel Theramore gründete. Bald kämpften Kul Tiraner unter Großadmiral Daelin Prachtmeer in blutigen Schlachten im Feuchtgebiet gegen Thralls junge Horde. Der Admiral wurde besiegt, und Theramore und Orgrimmar halten nun offiziell Waffenstillstand.\n\nDie Spannungen schwelen weiter. Theramore leidet unter Desertionen und Sabotage, während Spione in den Mooren lautlose, tödliche Konflikte austragen."},{t="Der Schatten des Drachensumpfs",b="Im Süden der Düstermarschen erhebt sich felsiges Gelände zum Drachendüster und Drachensumpf. Die Stonemaul-Oger siedelten sich dort zuerst unter Rexxar, ihrem halbogrischen Champion, an, bis der Schwarze Drachenschwarm sie gewaltsam aus Stonemaul Village vertrieb. Die vertriebenen Oger flohen unter Oberanführer Mok'Morokk nach Norden nach Brackenwall und schworen Rache.\n\nOnyxia, Tochter von Deathwing, lauert zwischen den zerklüfteten Felsen. Sie lenkt ihre Brut und spinnt finstere Machenschaften weit über den Sumpf hinaus."}},faq={{q="Was ist die wichtigste Siedlung der Allianz hier?",a="Die wichtigste Siedlung der Allianz ist Die Insel Theramore, ein befestigter Stadtstaat auf einer felsigen Insel vor der Ostküste. Lady Jaina Prachtmeer gründete sie nach dem Dritten Krieg. Ein schmaler Dammweg verbindet sie mit Kalimdor, und wichtige Schifffahrtsrouten führen zum Hafen von Menethil in den Östlichen Königreichen.",al={"stützpunkt der allianz düstermarschen","wo liegt theramore","menschenstadt düstermarschen"}},{q="Wo finden Abenteurer der Horde im Sumpf Zuflucht?",a="Reisende der Horde finden Zuflucht in Brackenwall im Nordwesten des Sumpfes. Die Stonemaul-Oger gründeten die Siedlung, schlossen sich unter Rexxar der Horde an und öffneten ihre Tore für verbündete Orcs und Tauren.",al={"stützpunkt der horde düstermarschen","wo liegt brackenwall","oger­siedlung"}},{q="Warum gibt es so viele schwarze Drachen im Süden des Sumpfes?",a="Schwarze Drachen sammeln sich im Süden des Sumpfes, weil Der Drachensumpf und Das Drachendüster zu Onyxias Herrschaftsgebiet und Brutstätten gehören. Ihre schwarzen Drachkin vertrieben die Stonemaul-Oger und legten Nester für Welplinge und Drakoniden in den Felsvorsprüngen und tiefen Höhlen an.",al={"drachen im drachensumpf","warum schwarze drachen hier","das drachendüster"}},{q="Was geschah mit der ursprünglichen Heimat der Stonemaul-Oger?",a="Die Stonemaul-Oger lebten einst friedlich in Stonemaul Village im Süden des Sumpfes. Der Schwarze Drachenschwarm griff an, erschlug viele von ihnen und zwang die Überlebenden, nach Nordwesten nach Brackenwall zu fliehen.",al={"die stonemaul ruinen","was geschah mit stonemaul village","alte ogersiedlung"}},{q="Wer lebt in dem einsamen Häuschen draußen im Morast?",a="Tabetha besitzt das Häuschen und lebt zurückgezogen in den Tiefen des Sumpfes als exzentrische, mächtige Einsiedlerin und Magierin. Arkanisten suchen bei ihr Rat oder Hilfe, um unberechenbare magische Relikte zu reinigen.",al={"tabetha's farm","tabetha düstermarschen","wer ist die hexe im sumpf"}},{q="Was ist die Insel Alcaz, und wer kontrolliert sie?",a="Strashaz-Naga kontrollieren die Insel Alcaz, eine streng bewachte Insel vor der Nordostküste des Sumpfes. Gefährliche Eliteverteidiger patrouillieren dort, und im umliegenden Wasser lauern Hydras.",al={"insel alcaz","insel vor der küste der düstermarschen","was gibt es auf alcaz"}}},fp="16,349,19.464.0,29.524.0,25.469.2,42.276.0,53.203.0,58.250.2,52.204.0,52.188.0,41.171.2"}
P.entries["zone:easternplaguelands"] = {n="Östliche Pestländer",s="Die Fäule der Geißel verdunkelt die Östlichen Pestländer. Stratholme bleibt eine Festung der Untoten, während der Scharlachrote Kreuzzug den Osten befestigt. Die Kapelle des Hoffnungsvollen Lichts bietet allen, die zurückschlagen, neutralen Schutz.",h="Die Fäule der Geißel verdunkelt die Östlichen Pestländer.",kw={"argentumdämmerung","darrowshire","östliche pestländer","kelthuzad","kapelle des hoffnungsvollen lichts","nathanos","der pestwald","rivendare","scharlachroter kreuzzug","geißel","stratholme","tyrs hand"},ang={["class:Paladin"]="Der Fall Lordaerons lastet schwer auf der Silbernen Hand. In Stratholme wandte sich Arthas der Dunkelheit zu, und an der Kapelle des Hoffnungsvollen Lichts fand ein tapferer letzter Widerstand statt.",["faction:Alliance"]="Für die Allianz betretet Ihr die Pestländer auf einer feierlichen Pilgerreise, um die verwüsteten Überreste Eurer einstigen Verbündeten im Norden zurückzuerobern und zu ehren.",["profession:Herbalism"]="In dieser verseuchten Region könnt Ihr seltene, instabile Kräuter sammeln, darunter Arthas' Tränen, Pestblüte und Schwarzer Lotus.",["profession:Mining"]="Adern aus Echtsilber, Mithril und reichhaltigem Thorium ziehen sich durch die verdorbenen Hänge und gefährlichen, von der Geißel verseuchten Täler.",["race:Undead"]="Als Untoter kennt Ihr die Östlichen Pestländer als Geburtsstätte der Geißel und als Frontlinie, an der die Verlassenen ihre einstigen Herren und die Scharlachroten Fanatiker bekämpfen."},sec={{t="Ein Land in Trümmern",b="Einst Eastweald genannt, waren die Östlichen Pestländer Lordaerons fruchtbares Kernland. Stratholme war das Zentrum der Region, nahe wohlhabender Städte wie Darrowshire und Corins Kreuzung. Während des Dritten Krieges ließ Prinz Arthas Stratholme säubern, nachdem er erfahren hatte, dass das Getreide mit der Seuche der Untoten versetzt worden war.\n\nNach dem Fall Lordaerons breitete sich die Magie der Geißel ungehindert aus. Der Boden wurde braun und verfault. Gewöhnliche Pflanzen wuchsen zu gewaltigen Pilzen heran, und orangefarbener Dunst legte sich über die Täler."},{t="Krieg an drei Fronten",b="Stratholme ist der südliche Machtstützpunkt der Geißel in Lordaeron. Baron Rivendare befehligt die Stadt unter der Führung des Lichs Kel'Thuzad. Im Südosten hat der fanatische Scharlachrote Kreuzzug Tyrs Hand befestigt und greift Stratholmes scharlachrote Festungen an.\n\nDer Hass des Kreuzzugs richtet sich neben den Untoten auch gegen jeden lebenden Reisenden, der seine Grenzen überschreitet. Weiter nördlich führen die Waldtrolle der Mossflayer von Zul'Mashar inmitten des größeren Konflikts isolierte, verzweifelte Feldzüge."},{t="Bollwerke der Lebenden",b="Achtet auf Euren Schritt in den Östlichen Pestländern. Die neutrale Argentumdämmerung unterhält die Kapelle des Hoffnungsvollen Lichts im äußersten Osten, wo Champions der Allianz und der Horde Schutz, Vorräte und Flugrouten finden. Jenseits der Kapelle markieren zerstörte Wachtürme Lordaerons verlorene Verteidigungsanlagen: Crown Guard, Eastwall, Northpass und Der Pestwald."}},faq={{q="Warum sehen Himmel und Bäume so krank aus?",a="Die Seuche der Untoten des Kults der Verdammten hat überall im Land ihre Spuren hinterlassen. Nach dem Dritten Krieg verseuchte seine nekromantische Magie die Erde, veränderte die örtliche Tierwelt und erfüllte die Luft mit unnatürlichem orangefarbenem Smog. Wälder verdrehten sich zu Pilzhainen wie dem Pestwald.",al={"warum ist der himmel orange","warum riesige pilze","verderbnis der östlichen pestländer"}},{q="Wo finde ich hier einen sicheren Zufluchtsort oder eine Flugroute?",a="Die Kapelle des Hoffnungsvollen Lichts am östlichen Rand des Gebiets ist der wichtigste Zufluchtsort. Die Argentumdämmerung unterhält sie und bietet Flugrouten zur Unterstadt, Eisenschmiede, zum Zugwindlager und ins Hinterland für Reisende der Allianz und der Horde.",al={"sicheres gebiet in den pestländern","flugroute östliche pestländer","freundliche stadt östliche pestländer"}},{q="Wer kontrolliert die Stadt Stratholme?",a="In Stratholme tobt ein Krieg. Baron Rivendare beherrscht den Großteil der brennenden Ruinen für Kel'Thuzad, während der Scharlachrote Kreuzzug im westlichen Bezirk eine aggressive Garnison hält. Dort führt er eine blutige Belagerung gegen die Untoten.",al={"wer führt stratholme","geschichte der bosse von stratholme","was gibt es in stratholme"}},{q="Warum ist der Scharlachrote Kreuzzug feindselig gegenüber fremden Abenteurern?",a="Der Fanatismus und die Paranoia des Scharlachroten Kreuzzugs nahmen nach dem Fall Lordaerons und der Spaltung der Silbernen Hand zu. Seine Mitglieder glauben, Fremde trügen die Seuche in sich oder paktierten mit den Untoten. Deshalb greifen sie jene an, die sich Festungen wie Tyrs Hand nähern.",al={"warum greift mich der scharlachrote kreuzzug an","tyrs hand feindselig","scharlachroter kreuzzug rot"}},{q="Was geschah mit der Stadt Darrowshire?",a="Während des Dritten Krieges griffen Streitkräfte der Geißel unter dem Todesritter Marduk dem Schwarzen und dem Ghul Horgus dem Schlächter Darrowshire an. Paladin Davil Crokford und Hauptmann Joseph Redpath kämpften tapfer, doch Nekromantie korrumpierte Redpaths Seele und ließ ihn sein eigenes Volk abschlachten. Darrowshire liegt nun in verwunschenen Ruinen.",al={"geschichte von darrowshire","untergang von darrowshire","wer zerstörte darrowshire"}}},fp="19,201,14.487.0,21.470.0,22.315.0,46.266.0,50.219.0,36.218.0,58.241.0,41.318.0"}
P.entries["zone:elwynn"] = {n="Wald von Elwynn",s="Der Wald von Elwynn ist fruchtbares, grünes Land, und Sturmwind lebt von seinem Holz und Gold, seinen Fischen und seinem Getreide. Eigentlich sollte es ein friedlicher Ort sein. Doch Ungeziefer, umherstreifende Tiere und Wegelagerer durchstreifen die Wälder. Deshalb schickt die Abtei von Nordhain ihre Rekruten aus, um sich um sie zu kümmern.",h="Der Wald von Elwynn ist fruchtbares, grünes Land, und Sturmwind lebt von seinem Holz und Gold, seinen Fischen...",kw={"defias","osttal","elwynn","wald von elwynn","tiefenschacht","goldhain","hogger","jaspis","nazferiti","nordhain","abtei von nordhain","vancleef"},ang={["class:Rogue"]="Als Schurke findet Ihr Elwynn vom Schatten der Bruderschaft der Defias durchzogen, mit Diebstählen, Schmuggelware und geheimen Signalen der Rebellen.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, das wichtigste Menschenkönigreich der Allianz zu beschützen. Sturmwind ist auf Elwynns Holz, Erz und Getreidelieferungen angewiesen.",["profession:Mining"]="Als Bergarbeiter findet Ihr Kupferadern in der Echokammmine, der Tiefenschachtmine und der Jaspismine. Kobolde befallen diese Minen, doch sie bleiben ein wichtiges frühes Bewährungsfeld.",["race:Human"]="Als Mensch beginnt Ihr im angestammten Herzen des Königreichs. Ihr werdet in der Abtei von Nordhain ausgebildet, bevor Ihr aufbrecht, um Eure Heimat vor Banditen, wilden Tieren und politischem Zerfall zu verteidigen."},sec={{t="Die Kornkammer des Königreichs",b="Der Wald erstreckt sich von den Toren Sturmwinds nach Süden bis zum Nazferiti River. Hier regnet es häufig, und die Felder danken es mit reicher Ernte. Dahinter wachsen dichte Laubwälder, deren Holz in die Hauptstadt gebracht wird. Karren rollen aus Goldhain und dem Holzfällerlager des Osttals herbei, beladen mit Getreide und Vieh, Bauholz und rohem Kupfer. In Elwynn werden auch Pferde gezüchtet, und Ritter und Reisende im ganzen Königreich freuen sich über ein kräftiges Evendale-Pferd."},{t="Ein brüchiger Frieden",b="Doch dies sind unruhige Zeiten. Die Armee von Sturmwind ist weit entfernt im Einsatz, deshalb müssen die Marschälle und Deputys mit unerprobten Rekruten auskommen. Kobolde haben die Tiefenschachtmine und die Jaspismine überrannt. Gnolle der Flussspatpfoten durchstreifen die südwestlichen Grenzen, und Murlocs haben die Ufer des Steinhügelsees und des Kristallsees besetzt.\n\nSelbst die Wölfe sind neu hier. Sie flohen vor der Verderbnis jenseits des Flusses im Dämmerwald und kamen nach Elwynn herüber."},{t="Die Gefahr der roten Halstücher",b="Die Bruderschaft der Defias hat sich als organisierte Bande von Gesetzlosen in Elwynn ausgebreitet. Ihre Mitglieder stammen aus Edwin van Cleefs Steinmetzgilde, nach erbitterten Streitigkeiten mit dem Haus der Adligen um die Bezahlung.\n\nSie haben die Weinberge von Nordhain, Brackbrunns Kürbisbeet, Jerods Anlegestelle und den Obsthain am Spiegelsee eingenommen. Gerüchten zufolge leiten ihre Agenten Gnolle und Kobolde in der Nähe an, um das Reich zu destabilisieren. Die Wachen Rolf und Malakai untersuchten Murlocs nahe dem Steinhügelsee; beide wurden getötet und an seinen Ufern zurückgelassen."}},faq={{q="Warum patrouilliert die Wache von Sturmwind kaum im Wald?",a="Die Streitkräfte Sturmwinds sind überlastet. Das Königreich entsandte große Truppenverbände nach Süden ins Schlingendorntal, häufte Schulden an und entzog der Region Arbeitskräfte. Die Weststromgarnison und Goldhain verlassen sich nun auf kleine Trupps und freiwillige Rekruten, um Banditen, Gnollen und Murlocs entgegenzutreten.",al={"wo sind die wachen","warum ist die armee von sturmwind nicht da","warum ist elwynn ungeschützt"}},{q="Warum gibt es Kobolde in allen Minen?",a="Es gibt nur wenige Wachen, und Kobolde sind auf der Suche nach Gold und Mineralien in die Tiefenschachtmine, die Jaspismine und die Echokammmine geschwärmt. Sie vertrieben die menschlichen Goldsucher und Bergleute und verteidigen ihre Ansprüche nun mit Kerzen, groben Spitzhacken und geplünderten Werkzeugen.",al={"warum sind kobolde in den minen","kobolde in elwynn","tiefenschachtmine verseucht"}},{q="Wer sind die Banditen mit den roten Masken?",a="Die Banditen mit den roten Masken gehören zur Bruderschaft der Defias, Gesetzlosen, die Höfe und Minen in Elwynn und Westfall besetzt haben. Die Volksmiliz auf der Späherkuppe in Westfall versucht noch immer herauszufinden, wer sie anführt und warum.",al={"rote masken","banditen mit roten halstüchern","wer sind die defias in elwynn"}},{q="Wohin führt die Straße nach Süden?",a="Die Straße nach Süden überquert den Nazferiti River und führt in den Dämmerwald. Einst war dieses Gebiet friedlich, doch nun ist es in unnatürliche Dunkelheit gehüllt und von Untoten, monströsen Spinnen und gefräßigen Tieren verseucht.",al={"was liegt jenseits des flusses","wohin führt die brücke im dämmerwald","brücke über den nazferiti river"}},{q="Worum geht der Streit zwischen den Maclures und den Steinfelds?",a="Die Steinfelds und die Maclures sind benachbarte Bauernfamilien im Süden Elwynns, die einen erbitterten, langjährigen Groll gegeneinander hegen. Ihre jüngeren Angehörigen, Maybell Maclure und Tommy Joe Steinfeld, haben sich heimlich ineinander verliebt und verschärfen damit die Rivalität.",al={"maclure gegen steinfeld","rivalität zwischen bauernfamilien in elwynn","streit zwischen steinfeld und maclure"}},{q="Was ist der Turm von Azora?",a="Der Turm von Azora ist ein arkaner Turm neben der Straße zwischen Goldhain und dem Holzfällerlager des Osttals. Dort leben zurückgezogen Magier, darunter Theocritus, der die Leylinien der Region erforscht und magische Studien betreibt, die nicht direkt der Aufsicht des Zaubererturms von Sturmwind unterstehen.",al={"turm an der straße zum osttal","magierturm in elwynn","wer lebt im turm von azora"}}},fx={f92572cc={q="Was soll ich im Wald von Elwynn tun?",a="Da die Armee von Sturmwind im ganzen Reich dünn gesät ist, ist die Verteidigung von Elwynn auf lokale Deputys und fähige Rekruten wie Euch gefallen. Marschall Dughan in Goldhain benötigt Hilfe dabei, die Kobolde aus den Goldminen zu vertreiben, die Flusspfotengnolle an der westlichen Grenze abzuwehren und die bösartigen Murlocs um die Seen zu bekämpfen. Gleichzeitig haben rotmaskierte Defias-Banditen lokale Bauernhöfe und Obstgärten überrannt, während sich streitende Landbesitzer wie die Maclures und die Steinfelds in Streitigkeiten verstricken, die geschlichtet werden müssen. Sobald Ihr geholfen habt, hier die Ordnung wiederherzustellen, führt der Weg nach Westen nach Westfall oder nach Osten in Richtung Rotkammgebirge.",al={"was soll ich in elwynn tun","was mache ich hier","was ist meine mission im wald von elwynn","warum bin ich hier"}},["23586590"]={q="Was ist der Wald von Elwynn?",a="Der Wald von Elwynn ist das grüne Herzland des Königreichs Sturmwind. Eingebettet unter den Ausläufern der Brennende Steppe versorgen diese uralten Wälder mit ihren stattlichen Laubbäumen, sanften Hügeln und reißenden Flüssen das Königreich mit Holz, Fisch, Ernteerträgen und Erz. Sein majestätisches Blätterdach schützt kleine Bauernhöfe, gewundene Landstraßen und Städte wie Goldhain, während die Hauptstadt Sturmwind vom nordwestlichen Kamm aus über das Reich wacht.",al={"was ist elwynn","wo bin ich","lore wald von elwynn"}},["4e6f8475"]={q="Was ist in der Vergangenheit im Wald von Elwynn geschehen?",a="Vor Jahrhunderten von menschlichen Migranten der Arathi-Blutlinie gegründet, blühte der Wald von Elwynn zu einem florierenden Reich auf. Während des Ersten Krieges jedoch fegte die Horde durch den Wald, brannte seine Lichtungen nieder und kesselte Sturmwind ein, bevor Goldhain und die Hauptstadt dem Erdboden gleichgemacht wurden. Nach dem Zweiten Krieg half Oberkommandierender Turalyon bei der Überwachung der Rückführung der Bevölkerung und der Wald wurde neu aufgebaut, wobei nur verstreute, verrottende Katapulte als Erinnerung an die Invasion zurückblieben.",al={"geschichte des walds von elwynn","vergangenheit wald von elwynn","erster krieg elwynn"}},["2f8050d9"]={q="Ist der Wald von Elwynn gefährlich?",a="Obwohl der Wald von Elwynn idyllisch erscheint, verbirgt seine friedliche Fassade wachsende Unruhen. Kobolde haben die entscheidenden Goldminen des Reiches überrannt, während feindselige Flusspfotengnolle von der westlichen Grenze aus überfallen. Bösartige Murlocs haben Lager um den Kristallsee und den Steinhügelsee errichtet und überfallen Wachen und Reisende gleichermaßen. Schlimmer noch: die Bruderschaft der Defias mit ihren roten Masken agiert aus dem Schatten, besetzt Obstgärten und Gehöfte, während die Streitkräfte Sturmwinds darum kämpfen, die Kontrolle zu behalten.",al={"ist elwynn sicher","bedrohungen wald von elwynn","bedrohungen in elwynn"}},["41d1722e"]={q="Gehört dies zu Sturmwind?",a="Ja, der Wald von Elwynn ist das Kerngebiet des Königreichs Sturmwind. Der Wald grenzt direkt an die Tore der Hauptstadt und versorgt deren Märkte mit Holz aus dem Holzfällerlager des Osttals, Ernteerträgen von ländlichen Bauernhöfen und Erz aus regionalen Minen. Die Wache von Sturmwind unterhält Außenposten im gesamten Wald, einschließlich der Weststromgarnison und des Nordhaintals, obwohl die königlichen Ressourcen derzeit im gesamten Reich knapp sind.",al={"gehört elwynn zu sturmwind","territorium königreich sturmwind","zugehörigkeit elwynn"}},["36c6d40e"]={q="Warum ist es hier im Vergleich zu überall sonst so friedlich?",a="Der Wald von Elwynn liegt im geschützten Zentrum des Königreichs, direkt unter den schützenden Mauern von Sturmwind. Im Gegensatz zum Dämmerwald im Süden, der einem schleichenden magischen Fluch anheimfiel, oder Westfall im Westen, das Dürre und Banditentum überlassen wurde, erlebte der Wald von Elwynn nach dem Zweiten Krieg umfangreiche Wiederaufbaumaßnahmen. Seine unmittelbare Nähe zum Thron schirmt ihn vor den schlimmsten Schrecken ab, die in den Nachbarländern lauern.",al={"warum ist elwynn friedlich","elwynn vs dämmerwald","warum ist elwynn nicht zerstört"}},["7bf05012"]={q="Was ist Goldhain?",a="Goldhain ist das zentrale Kreuzungsdorf des Waldes von Elwynn, das südlich von Nordhain und südöstlich von Sturmwind liegt. Vor Jahrhunderten gegründet, dient es als wichtiger Knotenpunkt, der Handelsstraßen nach Westfall, dem Rotkammgebirge und dem Dämmerwald verbindet. Es beherbergt geschäftige Handwerker, lokale Ausbilder und das berühmte Gasthaus \"Zur Höhle des Löwen\", das Reisenden auf ihrem Weg durch das Herz des Königreichs Gastfreundschaft bietet.",al={"goldhain","erzähl mir von goldhain","lore goldhain"}},["2eb13bb0"]={q="Wer ist Marschall Dughan und warum schickt mich jeder zu ihm?",a="Marschall Dughan ist der Stadtkommandant und oberste Gesetzeshüter für Goldhain und den umliegenden Wald. In der Stadt stationiert, überwacht er die lokale Sicherheit, koordiniert regionale Patrouillen und versucht, Reisende und Versorgungswege zu schützen. Da das Militär von Sturmwind andernorts überlastet ist, verlässt sich Dughan stark auf fähige Abenteurer, um Bedrohungen zu untersuchen und die Ordnung im gesamten Wald von Elwynn wiederherzustellen.",al={"marschall dughan","wer ist dughan","dughan goldhain"}},["68a6801b"]={q="Ist Marschall Dughan Sturmwind unterstellt?",a="Ja, Marschall Dughan ist ein Offizier der Wache von Sturmwind und direkt dem Oberkommando des Königreichs in Sturmwind unterstellt. Er setzt die Gesetze der Krone durch und versucht, die königliche Autorität im gesamten zentralen Wald aufrechtzuerhalten, muss jedoch ständig Truppen und Vorräte von der Hauptstadt anfordern, die selten eintreffen.",al={"dughan sturmwind","wem untersteht dughan","ist dughan wache von sturmwind"}},["6c2b38d9"]={q="Warum habe ich in der Abtei von Nordhain begonnen?",a="Das Nordhaintal ist ein geschützter, befestigter Zufluchtsort, der dazu dient, vielversprechende neue Rekruten für das Königreich Sturmwind auszubilden und einzuberufen. Geschützt hinter Steinmauern und natürlichen Klippen beherbergt das Tal die Abtei von Nordhain, wo angehende Krieger, Priester, Paladine und andere Aspiranten ihr Handwerk verfeinern und lokale Kommandanten unterstützen, bevor sie in die weite Welt hinausziehen.",al={"warum nordhain","start in nordhain","beginn in nordhain"}},f22f39d1={q="Was ist die Abtei von Nordhain?",a="Die Abtei von Nordhain ist der historische Sitz des Heiligen Ordens der Kleriker von Nordhain, ein Orden vom das Heilige Licht, der Sturmwind während seiner dunkelsten Ären unterstützte. Bestehend aus der Haupthalle, der Hall of Arms und dem Bibliotheksflügel, bot sie einst dem Wächter Medivh während seines Komas Schutz und bewahrte heilige Folianten wie das The Tome of Divinity auf. Nach dem Zweiten Krieg wiederaufgebaut, bildet sie heute Rekruten und Champions vom das Licht aus.",al={"lore abtei von nordhain","was ist nordhain","die abtei in nordhain"}},c283ebda={q="Wer ist Marschall McBride?",a="Marschall McBride ist der für das Nordhaintal zuständige Gesetzeshüter und Militärkommandant. Von der Abtei von Nordhain aus überwacht er die lokale Verteidigung, beobachtet Bedrohungen durch die von Ungeziefer befallene Echokammmine und die eindringenden Defias-Banditen und rekrutiert fähige neue Bürger für den Dienst zur Verteidigung des Reiches.",al={"marschall mcbride","mcbride nordhain","wer ist mcbride"}},["16daccd8"]={q="Was ist die The Fargodeep Mine?",a="The Fargodeep Mine ist eine verlassene Gold- und Kupfermine südlich von Goldhain. Einst eine wichtige Quelle für Einnahmen und Metall für die Schatzkammer Sturmwinds, versank die Mine im Chaos, als ein Koboldstamm in ihre Tunnel eindrang. Jetzt überrannt, bleibt sie ein umkämpftes Risiko direkt in der Nähe lokaler Bauernhöfe, was Marschall Dughan dazu veranlasst, Abenteurer in ihre Tiefen zu schicken, um die Lage zu erkunden und den Befall zu beseitigen.",al={"tiefenschachtmine","fargodeep","lore fargodeep"}},e239f261={q="Wer sind die Flusspfotengnolle und warum greifen sie uns an?",a="Das Flusspfotenrudel ist ein wilder Clan hyänenartiger Gnolle, der sich entlang der westlichen Grenze des Waldes von Elwynn in der Nähe der Weststromgarnison verschanzt hat. Aggressiv und räuberisch, haben sie lange Zeit die menschliche Expansion bestritten und Farmen sowie unvorsichtige Reisende überfallen. Sie haben Lager entlang des Waldrands und des Steinhügelsee errichtet und drängen aggressiv in menschliches Land vor.",al={"flusspfotengnolle","warum greifen flusspfoten an","flusspfotenrudel"}},da4445a3={q="Arbeiten die Flusspfotengnolle für jemanden?",a="Während Gnolle normalerweise aus roher Wildheit und Gier handeln, deuten Gerüchte im ganzen Wald darauf hin, dass sie möglicherweise mit der Bruderschaft der Defias im Bunde stehen. Seltsame Verbindungen und Kopfgelder, einschließlich Geschäfte mit zwielichtigen Sammlern in der Nähe der Kammwacht, deuten darauf hin, dass die Banditen die Gnolle bewaffnen oder mit ihnen kooperieren könnten, um die Westgrenze des Waldes von Elwynn zu destabilisieren.",al={"wer führt die flusspfoten","sind gnolle bei den defias","verbindung flusspfoten defias"}},["29c0080a"]={q="Warum ist jeder so besorgt wegen der Murlocs am Fluss?",a="Murlocs sind in großer Zahl in die Wasserwege des Waldes von Elwynn eingedrungen und befallen den Kristallsee und den Steinhügelsee. Diese primitiven amphibischen Kreaturen sind erbittert territorial und überfallen lokale Fischer, Reisende und Stadtpatrouillen. Wache Thomas befürchtet, dass sie, wenn ihre expandierenden Siedlungen am Ufer nicht kontrolliert werden, lokale Straßen überrennen und ihre Scharmützel direkt bis nach Goldhain tragen werden.",al={"murloc-bedrohung elwynn","warum sorge wegen murlocs","murloc-problem"}},["0c4f3fe8"]={q="Was ist im Holzfällerlager des Osttals los?",a="Das Holzfällerlager des Osttals ist das Herz der geschäftigen Holzindustrie des Waldes von Elwynn, eingebettet in den östlichen Wäldern entlang der Grenze zum Rotkammgebirge. Die Holzfäller fällen die riesigen Laubbäume des Waldes, um Bauholz für Konstruktionen, Wagen und Befestigungen im gesamten Reich von Sturmwind bereitzustellen, obwohl feindselige Wölfe und Bären die Arbeitstrupps häufig bedrohen.",al={"holzfällerlager des osttals","holzfäller osttal","was ist osttal"}},["9effb187"]={q="Wo führt das alles nach dem Wald von Elwynn hin?",a="Sobald Ihr Marschall Dughan fertig unterstützt habt, zweigen die Straßen von Goldhain in Richtung härterer Grenzgebiete ab. Die westliche Brücke über den Fluss Nazferiti führt in den Staub und Wind von Westfall, wo die Defias das Sagen haben. Im Osten liegt das erhöhte Grenzland des Rotkammgebirges, während die Überquerung der südlichen Brücken Euch in die verfluchte, geisterhafte Düsternis des Dämmerwaldes führt.",al={"wohin nach elwynn","nächstes gebiet nach elwynn","nach dem wald von elwynn"}},cd54a445={q="Wie ist Westfall?",a="Westfall ist ein trockenes, windgepeitschtes Agrargebiet südwestlich des Waldes von Elwynn. Einst die Kornkammer des Königreichs, liegen seine sanften Weiden nun brach und trocken, befallen von abtrünnigen mechanischen Erntewächtern, gefräßigen Aasvögeln und Banditen. Die Bruderschaft der Defias hat fast die vollständige Kontrolle über die Region, und nur eine verzweifelte lokale Miliz auf der Späherkuppe leistet ihnen Widerstand.",al={"was ist westfall","über westfall","übersicht westfall"}},["4080ef4d"]={q="Wie bin ich im Wald von Elwynn gelandet?",a="Wenn Ihr ein Mensch seid, ist der Wald von Elwynn das Herzland Eures Volkes. Wahrscheinlich habt Ihr Eure ersten Schritte im geschützten Tal der Abtei von Nordhain gemacht und seid dem Ruf des Reiches gefolgt, um Eure Fähigkeiten zu trainieren und die lokalen Behörden zu unterstützen. Sobald Ihr die anfänglichen Probleme im Tal gelöst hattet, wies Euch Marschall McBride den Weg nach Süden entlang der Straße nach Goldhain. Reisende anderer Völker reisen normalerweise von der Tiefenbahn nach Sturmwind und treten durch die großen Stadttore direkt hinaus in den Wald.",al={"wie kam ich hierher","warum bin ich im wald von elwynn","wie kam ich nach elwynn","wie bin ich hier gelandet"}},f8d7f725={q="Was geschah mit Rolf und Malakai?",a="Die Wachen Rolf und Malakai waren Späher aus Sturmwind, die ausgesandt wurden, um zunehmende Aktivitäten der Murlocs nahe den östlichen Wasserläufen und dem Steinhügelsee zu untersuchen. Sie haben sich nicht zurückgemeldet, und Wache Thomas bittet Reisende darum, Nachforschungen anzustellen.",al={"rolf und malakai","verlorene wachen elwynn","was geschah mit den wachen hartford und stone"}}},fp="13,250,28.459.0,18.438.0,22.513.1,54.269.0,43.248.0,38.217.0,31.190.0,54.246.0,27.282.0"}
P.entries["zone:felwood"] = {n="Teufelswald",s="Der Teufelswald steht zwischen Eschental und Hyjal weiter im Griff der Verderbnis. Einst war er ein Paradies, das die Nachtelfen pflegten, doch während des Dritten Krieges vergiftete dämonische Magie das Land. Satyrn, entstellte Bestien und Urtume durchstreifen seine Tiefen, während Außenposten des Zirkels des Cenarius, der Allianz und der Horde an seiner Reinigung arbeiten.",h="Der Teufelswald steht zwischen Eschental und Hyjal weiter im Griff der Verderbnis.",kw={"fluchschlund","blutgift","deadwood","das smaragdrefugium","teufelswald","jaedenar","liedblume","nachtlaublichtung","tichondrius","holzschlund"},ang={["class:Druid"]="Für den Zirkel des Cenarius ist der Teufelswald eine tiefe Tragödie. Als Druide widmet Ihr Euer Leben der Reinigung seiner verseuchten Pflanzen und der Besänftigung wahnsinniger Naturgeister.",["class:Warlock"]="Als Hexenmeister findet Ihr in den dunklen Tunneln des Teufelswalds und den verbliebenen dämonischen Mächten einen Brennpunkt Eurer Jagd auf rivalisierende Kultisten des Schattenrats.",["profession:Herbalism"]="Als Kräuterkundiger könnt Ihr seltene, unberechenbare Pflanzen aus der teufelsverseuchten Erde des Teufelswalds sammeln. Nur wenige Orte in Azeroth bieten Gromsblut und Arthas' Tränen.",["race:NightElf"]="Als Kaldorei wisst Ihr, dass die Entweihung dieser uralten Wälder unermessliche Trauer und Scham hervorruft. Euer Volk hat es versäumt, sie vor dem Einfluss der Legion zu schützen."},sec={{t="Ein entweihtes Paradies",b="Vor dem Dritten Krieg flossen klare Bäche unter singenden Vögeln, und uralte Beschützer bewachten die friedlichen Haine. Dann beendeten der Schreckenslord Tichondrius und die Brennende Legion diesen Frieden. Vor ihrem Angriff auf Hyjal vergifteten sie mit dem Schädel von Gul'dan den Norden Kalimdors. Seine Zauberkraft schwärzte den Waldboden und verwandelte ihn in Morast.\n\nSpäter erschlug Illidan Sturmgrimm Tichondrius und nahm die Essenz des Artefakts in sich auf. Doch die Teufelsverderbnis blieb. Treants und Urtume verfaulten von innen, Flüsse kochten vor Galle und die Bestien des Waldes verfielen dem kannibalischen Wahnsinn."},{t="Der Kampf um die Reinigung",b="Die Heilung des Teufelswalds geht nur langsam voran. An seiner Südgrenze bekämpft der Zirkel des Cenarius vom Smaragdrefugium aus die Seuche. Seine Druiden kümmern sich um vergiftete Liedblumen und Nachtdrachenknollen und geben Wanderern Cenarische Leuchtfeuer und reinigende Salben.\n\nDie Nachtelfen halten im Norden die Nachtlaublichtung, während die Horde den Blutgiftposten unterhält. Beide Stützpunkte liegen inmitten einer tödlichen Wildnis, in der sich die Natur gegen sterbliches Fleisch gewandt hat."},{t="Der Schatten in Jaedenar",b="Kultisten nähren weiterhin die Teufelsverderbnis des Waldes. Im unterirdischen Labyrinth von Jaedenar und der Schattenfeste vollziehen Überreste des Schattenrats unter der Führung von Lord Fluchschlund finstere Rituale. Sie sind mit trügerischen Satyrn verbündet, die uralte Mondbrunnen entweihen.\n\nDie Hexenmeister nutzen die Qualen des Waldes und beschwören dämonische Verstärkung. Der Teufelswald kann nicht erlöst werden, solange der Rat hier verwurzelt ist."}},faq={{q="Warum ist der Teufelswald verderbt?",a="Während des Dritten Krieges verderbte der Schreckenslord Tichondrius den Wald mit dem dämonischen Schädel von Gul'dan. Die Legion wollte die Verteidigung der Nachtelfen vor ihrem Marsch auf Hyjal schwächen. Wildtiere, Wasser und Urtume wurden verseucht.",al={"wie wurde der teufelswald verderbt","was geschah mit dem teufelswald","warum sind die bäume tot"}},{q="Können die verderbten Pflanzen im Wald gereinigt werden?",a="Ja. Druiden des Zirkels des Cenarius geben Euch Salben, die aus gesammelter Teufelsverderbnis und Mineralrückständen gebraut werden. Tragt sie auf Liedblumen, Peitschenknollen und Nachtdrachen auf, um ihre Verderbnis zu bannen und heilende Früchte und Segnungen zu erhalten.",al={"pflanzen reinigen","cenarische pflanzensalbe","verderbte liedblume"}},{q="Wer kontrolliert Jaedenar?",a="Der geheime Schattenrat, eine Sekte aus sterblichen Hexenmeistern und Dämonenanbetern, kontrolliert Jaedenar. Von den unterirdischen Höhlen der Schattenfeste aus überwacht der Schreckenslord Lord Fluchschlund ihre Rituale und befehligt die Satyrn der Region.",al={"was ist jaedenar","wer ist in der schattenfeste","jaedenar boss"}},{q="Sind die Furbolgs im Teufelswald feindselig?",a="Die meisten sind feindselig. Die Deadwood-Stämme sind der dämonischen Verderbnis und dem teuflischen Wahnsinn vollständig verfallen. Die Holzschlund-Furbolgs kontrollieren das nördliche Tunnelsystem und sind unverdorben, misstrauen Fremden jedoch, bis diese sich als freundlich erweisen.",al={"furbolgs im teufelswald","holzschlund-furbolgs","lager der totenwaldfelle"}},{q="Wie gelangt man durch den Teufelswald zur Mondlichtung oder nach Winterquell?",a="Die Straße nach Norden führt in die Holzschlundfeste, einen befestigten Höhlenkomplex. Die unverdorbenen Holzschlund-Furbolgs kontrollieren die Tunnel vom Teufelswald zur Mondlichtung und nach Winterquell. Ihr müsst ihr Vertrauen gewinnen oder Euch hindurchkämpfen.",al={"holzschlund-tunnel","weg nach winterquell","pass zur mondlichtung"}},{q="Warum greifen die verderbten Urtume Nachtelfen an?",a="Dämonische Magie verdrehte und vergiftete die einst edlen Urtume und Treants. Ewige Qualen haben ihren Verstand zerrüttet, und sie grollen den Nachtelfen, weil diese sie ihrer Ansicht nach der Brennenden Legion überlassen haben.",al={"wahnsinnige treants","verderbte urtume","warum sind urtume feindselig"}}},fp="7,298,19.587.0,21.430.0,22.403.1,25.236.0,51.234.0,22.236.0,36.219.0,60.221.0,49.200.0"}
P.entries["zone:feralas"] = {n="Feralas",s="In Feralas erstreckt sich Regenwald zwischen Desolace, Tausend Nadeln und dem verhüllten Meer. Gebirgswälle schützen eine uralte Wildnis voller überwucherter Kaldorei-Ruinen und urzeitlicher Bestien. Überreste der Hochgeborenen, Gordunni-Oger und rivalisierende Außenposten der Allianz und der Horde ringen um das Gebiet.",h="In Feralas erstreckt sich Regenwald zwischen Desolace, Tausend Nadeln und dem verhüllten Meer.",kw={"camp mojache","düsterbruch","traum-geäst","eldre'thalas","mondfeder","feralas","gordunni","shandris","thalanaar"},ang={["class:Druid"]="Als Druide wisst Ihr, dass das Traum-Geäst Feralas mit dem Smaragdgrünen Traum verbindet. Dieser Ort ist heilig, und Ihr müsst ihn vor Verderbnis und Schändern bewahren.",["faction:Alliance"]="Als Agent der Allianz arbeitet Ihr von der Mondfederfeste aus unter Shandris Mondfeder. Ihr beobachtet die Küste nach Naga und bewacht das Erbe der Elfen.",["faction:Horde"]="In Camp Mojache helft Ihr, die Grenze der Horde gegen Vorstöße der Gordunni, abtrünnige Grimtotem und Woodpaw-Wildhunde zu halten.",["profession:Herbalism"]="Als Kräuterkundiger findet Ihr unter dem feuchten, schattigen Blätterdach Pflanzen aus gemäßigten und tropischen Regionen, darunter Sonnengras, Lila Lotus und Khadgars Schnurrbart.",["race:NightElf"]="Als Nachtelf spürt Ihr in Feralas das Gewicht der uralten Kaldorei-Zivilisation. Oger, die heilige Ruinen wie Eldre'Thalas entweihen, erfüllen Euch mit Trauer und Zorn."},sec={{t="Ein Wald, den die Ödlande verschonten",b="Ihr betretet einen Regenwald, der noch immer grün ist, während Desolace und Tausend Nadeln nahebei trocken daliegen. Gebirgszüge halten die Ödlande fern und schützen uraltes Wachstum unter warmer, nebliger Luft und hoch aufragenden Wasserfällen. Vor der Großen Spaltung sah ein Großteil Kalimdors so aus. Im Laufe der Zeitalter verschlang der Dschungel die Monumente der Kaldorei, die einst hier herrschten, und verbarg vergessene Tempel und Pavillons unter Moos und Farnen."},{t="Die Ruinen von Eldre'Thalas",b="Im Herzen von Feralas liegt Eldre'Thalas in Trümmern und trägt heute den Namen Düsterbruch. Die Kaldorei errichteten die Stadt auf dem Höhepunkt ihres Imperiums, doch die Gordunni-Oger haben ihre weitläufigen steinernen Höfe entweiht. Der Klan breitet sich im Tal aus, plündert heilige Stätten, besudelt unberührte Haine und zwingt die Tierwelt, ihr Gebiet zu verteidigen. Gerüchten zufolge befinden sich Überreste der Hochgeborenen und seit zehntausend Jahren eingeschlossene Mächte in Düsterbruchs versiegelten Kammern."},{t="Der Kampf um Stützpunkte",b="Expeditionen der Allianz und der Horde sind in den Dschungel vorgedrungen, wo jede Überquerung Gefahr birgt. In der Mondfederfeste auf der Insel Sardor führt Generalin Shandris Mondfeder die Schildwachen gegen die Oger und die vordringenden Naga. Weiter östlich dient Camp Mojache der Horde als Stützpunkt gegen aggressive Woodpaw-Wildhunde, feindselige Grimtotem-Tauren und unerbittliche Oger. Keine Fraktion kontrolliert das wilde Landesinnere von Feralas."}},faq={{q="Was ist Düsterbruch?",a="Düsterbruch ist der Name, den Eldre'Thalas heute trägt, eine große Elfenstadt, die die Große Spaltung überstand. Im Laufe der Zeitalter verfiel sie und fiel dem brutalen Klan Gordunni zum Opfer. Oger und verräterische Geister ringen um ihre Flügel, in denen uralte Geheimnisse der Hochgeborenen verborgen sind.",al={"eldre'thalas","ogerstadt","zentrum der uralten ruinen"}},{q="Wie erreichen Reisende der Allianz sicher die Mondfederfeste?",a="Von Desolace aus können Reisende der Allianz durch die Zwillingskolosse nach Süden ziehen, doch die dortigen Bestien sind gefährlich. Oder sie können bei Sar'therisstrand ins Meer gehen und entlang der Vergessenen Küste nach Süden zur Insel Sardor schwimmen, um die gefährliche Straße und Camp Mojache zu umgehen.",al={"zur mondfederfeste gelangen","zugang der allianz nach feralas","wie kommt die allianz nach feralas"}},{q="Warum bekämpft die Horde die Gordunni-Oger so erbittert?",a="Die Gordunni-Oger dringen aus Düsterbruch vor, überfallen Versorgungskonvois und greifen Reisende im ganzen Dschungel an. Ihre Kriegerscharen bedrohen Camp Mojache, weshalb Anführer der Horde wie Belgrom Rockmaul zu schnellen, aggressiven Schlägen gegen die Außenposten des Klans aufrufen.",al={"warum gordunni töten","ogerkrieg der horde","camp mojache oger"}},{q="Was ist das Traum-Geäst?",a="Das Traum-Geäst ist einer der vier Großen Bäume Azeroths. Sein mystisches Naturportal verbindet die physische Welt mit dem Smaragdgrünen Traum. Der grüne Drachenschwarm und uralte Wächter behüten ihn, ebenso wie seine Gegenstücke im Eschental, im Dämmerwald und im Hinterland.",al={"portal der grünen drachen","großer baum in feralas","baum des smaragdgrünen traums"}},{q="Warum sind Grimtotem-Tauren in Feralas?",a="Eine abtrünnige Sekte der Grimtotem-Tauren unterhält ein Lager in der Wildnis, außerhalb der Autorität Donnerfels'. Sie sind sowohl der Allianz als auch der Horde feindlich gesinnt, haben einheimische Feendrachen gefangen und sind Ziele von Spähern der Horde.",al={"grimtotem in feralas","truppenlager der grimmtotem","feindselige tauren"}},{q="Gibt es Silithiden in Feralas?",a="Ja. Südlich der Hauptstraße wimmelt es in der unterirdischen Brutstätte Die Gewundene Tiefe von Silithiden. Ihr Auftauchen im Regenwald zeigt, dass sich der Schwarmgeist weit über die Wüsten im Süden Kalimdors hinaus ausbreitet.",al={"die gewundene tiefe","käfer in feralas","silithiden-brutstätte"}}},fp="7,281,32.415.0,25.429.0,26.398.0,18.249.0,62.265.0,61.250.0,24.261.0,44.222.0,30.218.0"}
P.entries["zone:gnomeregan"] = {n="Gnomeregan",s="In Dun Morogh liegt Gnomeregan in Ruinen und unter Quarantäne, seit die Gnome sich verzweifelt gegen Troggs verteidigten. Einst ihre unterirdische Hauptstadt und ihr größtes technologisches Wunder, birgt es nun verstrahlte Hallen, mutierte Troggs, wahnsinnige Lepragnome und abtrünnige mechanische Wächter. Die Überlebenden leben als Flüchtlinge im nahegelegenen Eisenschmiede.",h="In Dun Morogh liegt Gnomeregan in Ruinen und unter Quarantäne, seit die Gnome sich verzweifelt gegen Troggs...",kw={"dun morogh","gnomeregan","grubbis","lepragnom","mekkadrill","strahlung","thermaplugg","tinkers' court","trogg","verflüssigte ablagerung"},ang={["faction:Alliance"]="Als Mitglied der Allianz steht Ihr einem Volk bei, das im Zweiten Krieg an der Seite der Allianz kämpfte. Gnomeregan von Thermaplugg zu befreien, ist entscheidend, um die Stärke der Gnome innerhalb der Fraktion wiederherzustellen.",["profession:Engineering"]="Als Ingenieur findet Ihr in den Ruinen Gnomeregans fortschrittliche Meisterwerke, Baupläne und experimentelle Apparate. Seine Konstruktionspläne sind inmitten tödlichen mechanischen Chaos von unschätzbarem Wert.",["race:Dwarf"]="Als Zwerg verbindet Euch eine Verwandtschaft mit den Gnomen, die bis zu den Vorfahren zurückreicht, die beim Bau der Fundamente Gnomeregans halfen. Ausgrabungen der Zwerge in Uldaman setzten auch unwissentlich die Trogg-Horden frei, die die Stadt verwüsteten.",["race:Gnome"]="Als Gnom birgt Gnomeregan die größte Tragödie Eures Volkes und eine Schande, die bis heute währt. Seine Hallen zu betreten, ist eine erschütternde Pilgerreise, um achtzig Prozent Eures gefallenen Volkes zu rächen und den Verräter Thermaplugg zu entthronen."},sec={{t="Ein Wunder aus Eisen und Dampf",b="Unter Dun Morogh vereinte Gnomeregan gnomische Erfindungsgabe, wetteiferndes Handwerk und Politik unter einem Dach. Mit Hilfe der benachbarten Zwerge von Eisenschmiede errichteten seine Bewohner einen gewaltigen mechanischen Komplex, angetrieben von mahlenden Motoren und surrenden Zahnrädern.\n\nSein ausgeklügeltes Belüftungsnetz erforderte fünfzehn Techniker, die rund um die Uhr arbeiteten, damit frische Luft zirkulierte. Am Tinkers' Court debattierten und wetteiferten Gnome, während ihre Hauptstadt zu einem Wunder der Industrie heranwuchs. Während des Zweiten Krieges sandten sie der Allianz von Lordaeron Belagerungsmaschinen, Flugmaschinen und Waffen."},{t="Die Trogg-Invasion und die Vergiftung",b="Während des Dritten Krieges, als die Geißel Lordaeron verheerte, weckten Ausgrabungen der Zwerge am uralten Titanengewölbe Uldaman primitive Troggs unter Dun Morogh. Die Kreaturen gruben sich in die unteren Fundamente von Gnomeregan, und Hochtüftler Gelbin Mekkadrill führte die Verteidigung.\n\nAls die Verteidigungsanlagen der Stadt zu versagen begannen, folgte Mekkadrill dem Rat seines obersten Beraters, Robogenieur Thermaplugg. Er befahl, die Tanks mit radioaktivem Abfall in die unteren Ebenen abzulassen, um die Eindringlinge auszurotten. Das giftige Gas breitete sich unkontrolliert aus. Fast achtzig Prozent der gnomischen Bevölkerung starben innerhalb weniger Tage."},{t="Der Verrat des wahnsinnigen Robogenieurs",b="Robogenieur Thermaplugg hatte heimlich Hochtüftler Mekkadrills Amt begehrt. Gerüchten zufolge wusste er schon vor ihrem Beginn von der Trogg-Invasion und half, die Katastrophe in Gang zu setzen. Niemand bestätigte diese Gerüchte, doch Mekkadrill hält sie für möglich. Was auch immer Thermaplugg beabsichtigte, die Ereignisse entglitten seiner Kontrolle.\n\nDie Strahlung tötete die Troggs nicht, sondern trieb sie in einen gewalttätigen Blutrausch, während Thermaplugg in den verseuchten unteren Ebenen gefangen war. Die Strahlenkrankheit verwandelte ihn in einen wahnsinnigen Lepragnom. Von seinem Thron am Tinkers' Court aus krönte er sich zum Techno-Oberlord von Gnomeregan und befehligt geistlose lepröse Überlebende und unberechenbare Maschinen."},{t="Ein brüchiger Sieg",b="Von Tüftlerstadt in Eisenschmiede aus koordiniert Hochtüftler Mekkadrill den Versuch, Gnomeregan zurückzuerobern. Er schickt Abenteurer der Allianz in dessen giftige Tiefen, um Thermapluggs Herrschaft zu brechen. Wird der Robogenieur im Herzen des Tinkers' Court erschlagen, endet seine Befehlsgewalt über die abtrünnigen Verteidigungsanlagen und die leprösen Kohorten.\n\nEndlich können die Gnome seinen monumentalen Verrat rächen. Doch eine dauerhafte Rückeroberung bleibt schwer fassbar. Verstrahlter Schlamm, mutierte Bestien und Troggs verstopfen weiterhin die tieferen Tunnel. Mekkadrill stellt Gyrodrillmatic Excavationators zusammen und schmiedet umfassendere militärische Pläne, um die angestammte Heimat seines Volkes zurückzugewinnen."}},faq={{q="Warum ist Gnomeregan verstrahlt?",a="Troggs drangen von unten ein, und Hochtüftler Gelbin Mekkadrill versuchte, sie zu vernichten, indem er auf Rat von Robogenieur Thermaplugg Gnomeregans Tanks mit radioaktivem Abfall öffnen ließ. Der Plan sollte nur die unteren Sektoren fluten, doch tödliche Strahlung sickerte durch die ganze Stadt. Sie tötete achtzig Prozent der gnomischen Bevölkerung und mutierte die Überlebenden.",al={"was geschah mit gnomeregan","warum ist gnomeregan grün","strahlung in gnomeregan"}},{q="Woher kamen all die Troggs?",a="Die Troggs waren uralte Kreaturen, die durch archäologische Ausgrabungen der Zwerge aus ihrem tiefen unterirdischen Schlummer gerissen wurden. Sie hatten in Uldaman, einem Titanenkomplex, gegraben. Angelockt von der Hitze und den Vibrationen der schweren Maschinen Gnomeregans, gruben sie weitläufige Tunnel in die unteren Ebenen und technischen Bezirke der Stadt.",al={"warum gibt es troggs in gnomeregan","ursprung der troggs","trogg-invasion"}},{q="Warum baten die Gnome die Allianz nicht um Hilfe gegen die Troggs?",a="Die Trogg-Invasion traf während des Dritten Krieges ein, als die Geißel das Königreich Lordaeron zu Fall brachte. Die Gnome kämpften mit ihrer eigenen Technik und ihren eigenen Soldaten. Kein Bericht erklärt, warum Hochtüftler Mekkadrill nie Hilfe von außen anforderte. Stattdessen ließ er die Tanks mit radioaktivem Abfall der Stadt ablassen.",al={"warum half die allianz gnomeregan nicht","hat die allianz die gnome im stich gelassen"}},{q="Was sind Lepragnome?",a="Lepragnome sind Überlebende des Ablassens radioaktiver Abfälle in Gnomeregan, die durch lang anhaltende Strahlenbelastung schwer körperlich und geistig entstellt wurden. Ihre Haut wurde krankhaft blassgrün, ihre Körper wurden von Blasen und Krankheiten gezeichnet, und ihr Verstand verfiel unter der Kontrolle von Robogenieur Thermaplugg in rasende, mörderische Raserei.",al={"warum sind die gnome grün und wahnsinnig","verstrahlte gnome","geschichte der lepragnome"}},{q="Wer ist Robogenieur Thermaplugg?",a="Robogenieur Thermaplugg war Hochtüftler Mekkadrills vertrauter oberster Berater, obwohl er heimlich das Amt des Hochtüftlers begehrte. Auf sein Drängen hin wurde die Stadt mit Strahlung geflutet, und Mekkadrill nennt ihn den Verräter des gnomischen Volkes. Gemeinsam mit der Stadt verstrahlt, herrscht Thermaplugg als wahnsinniger Lepragnom-Tyrann vom Tinkers' Court aus.",al={"thermaplugg","wer ist der endboss","robogenieur thermaplugg"}},{q="Was ändert sich, wenn Robogenieur Thermaplugg besiegt wird?",a="Mit Thermapluggs Niederlage fällt die Führung weg, die die Lepragnome und die abtrünnigen Verteidigungsanlagen lenkt. Tödliche Strahlung und dichte Trogg-Nester verstopfen weiterhin die unteren Gänge. Mekkadrill muss daher tiefere Ausgrabungen vorbereiten, bevor die Stadt vollständig zurückerobert werden kann.",al={"erobern wir gnomeregan zurück","was geschieht, wenn thermaplugg stirbt","ist gnomeregan gerettet"}},{q="Warum sind Dunkeleisenzwerge in Gnomeregan?",a="Der Dunkeleisenklan sandte Gesandte nach Gnomeregan, darunter den Botschafter der Dunkeleisenzwerge. Die Dunkeleisenzwerge wollen Eisenschmiede und die Allianz sabotieren. Sie streben ein Bündnis mit Thermaplugg an und hoffen, gnomische Technik und zu Waffen umgebaute Maschinen für ihre eigenen Kriegszüge einzusetzen.",al={"botschafter der dunkeleisenzwerge","warum sind dunkeleisenzwerge in gnomeregan","zwerge in gnomeregan"}},{q="Wo leben die überlebenden Gnome jetzt?",a="Nach der radioaktiven Katastrophe flohen die nicht verderbten überlebenden Gnome durch die Berge nach Eisenschmiede. Ihre Vettern, die Zwerge, gewährten ihnen Zuflucht in Tüftlerstadt, einer technischen Enklave in der Bergfestung. Dort regiert Gelbin Mekkadrill sein verbanntes Volk und plant dessen Heimkehr.",al={"wo leben die gnome","heimatstadt der gnome","flüchtlinge in eisenschmiede"}}},fx={["072b7788"]={q="Was ist Gnomeregan?",a="Gnomeregan ist die uralte unterirdische Hauptstadt der Gnome, tief in die schneebedeckten Hügel des westlichen Dun Morogh gegraben. Sie wurde vor Jahrhunderten mit der Hilfe der Zwerge aus Eisenschmiede erbaut und stand als monumentaler Triumph der Ingenieurskunst, der Maschinerie und der Innovation. Heute jedoch liegen ihre glänzenden Metallhallen vergiftet da, überrannt von mutierten Troggs und wahnsinnigen Leprognomen nach einer katastrophalen Katastrophe.",al={"was ist gnomeregan","gnomeregan hintergrundgeschichte","über gnomeregan"}},["18622943"]={q="War Gnomeregan die Hauptstadt der Gnome?",a="Ja. Gnomeregan diente über Generationen hinweg als Herz der gnomischen Gesellschaft und Regierung. Es war das Zentrum des gnomischen Einfallsreichtums, beherbergte ihre Akademien, Werkstätten und den Tinkers' Court, in dem ihr gewählter Hoftüftler regierte. Alle großen Erfindungen und wissenschaftlichen Bestrebungen des Volkes der Gnome entsprangen diesen unterirdischen Hallen.",al={"war dies die hauptstadt der gnome","ist gnomeregan die hauptstadt","gnome hauptstadt"}},c31b3f81={q="Leben die Gnome noch in Gnomeregan?",a="Gnomeregan beherbergt nicht mehr das gnomische Volk. Achtzig Prozent der Bevölkerung starben, als giftige Strahlung die Stadt flutete, und viele, die zurückblieben, mutierten zu wahnsinnigen Leprognomen. Die meisten unversehrten Überlebenden flohen in die Tüftlerstadt in Eisenschmiede, obwohl einige wenige Ingenieure und Rückgewinnungsarbeiter in den Ruinen verblieben sind.",al={"leben hier gnome","sind noch gnome in gnomeregan","wer lebt jetzt in gnomeregan"}},["6e97b706"]={q="Haben die Gnome die Troggs ausgegraben?",a="Nein. Die Troggs wurden tief unter der Erde geweckt, als zwergische Forscher das Titanengewölbe von Uldaman ausgruben. Einmal aus ihrem Schlummer geweckt, gruben sich die Troggs durch die Berge in Richtung Eisenschmiede, wurden aber von den lauten Vibrationen und den mahlenden Maschinen von Gnomeregan weggelockt.",al={"haben gnome troggs ausgegraben","wie wurden troggs geweckt","haben gnome troggs verursacht"}},["1dd76133"]={q="Wer hat jetzt das Sagen bei den Gnomen?",a="Hoftüftler Gelbin Mekkadrill bleibt das gewählte Oberhaupt der Gnome. Trotz der Tragödie von Gnomeregan halten ihn seine Leute in Ehren und erkennen sein Genie und seine Hingabe an. Er führt derzeit die im Exil lebenden Gnome von der Tüftlerstadt in Eisenschmiede aus und konzentriert sich ganz auf die Rückeroberung ihrer Heimat.",al={"wer führt die gnome","gnome anführer","hoftüftler der gnome"}},["955293ce"]={q="Warum will die Allianz, dass ich nach Gnomeregan gehe?",a="Hoftüftler Mekkadrill und die Allianz brauchen mutige Abenteurer, um das Herz der zerstörten Stadt anzugreifen. Sie brauchen Euch, um den Trogg-Befall zu verringern, verlorene technologische Schaltpläne und Daten zu bergen, Thermapluggs automatisierte Verteidigungsanlagen zu stören und letztlich den Verräter Thermaplugg selbst hinzurichten.",al={"warum schickt man mich nach gnomeregan","gnomeregan allianz quest warum","warum nach gnomeregan gehen"}},["1f8ae1d4"]={q="Was erhoffen sich die Gnome von der Rückeroberung Gnomeregans?",a="Neben der Sicherung der Gerechtigkeit gegen Thermaplugg müssen die Gnome verzweifelt wichtige Baupläne, Energiequellen und Maschinen bergen, die zurückgelassen wurden. Langfristig würde die Rückeroberung ihrer Stadt es dem Gnomenvolk ermöglichen, ihr Exil in Eisenschmiede zu beenden, ihre fortschrittliche Zivilisation wiederaufzubauen und ihren Status als industrielle Macht für die Allianz wiederherzustellen.",al={"was wollen gnome von gnomeregan","gnome ziele gnomeregan","warum gnomeregan zurückerobern"}},cb78eee3={q="Können Leprognome geheilt werden?",a="Gnomische Wissenschaftler wie Ozzie Wechselvolt und Razzle Flinkspross untersuchen aktiv die giftigen Rückstände in der Hoffnung, ein Rekombobulationsheilmittel zu erfinden. Vorerst jedoch bleibt das Leiden unumkehrbar, und die meisten Leprognome degenerieren in den giftigen Dämpfen geistig und körperlich weiter.",al={"können leprognome geheilt werden","gibt es ein heilmittel für leprognome","leprognome heilen"}},["84ebb566"]={q="Waren Leprognome vorher normale Gnome?",a="Ja. Sie waren gewöhnliche Bürger, Erfinder und Arbeiter, die während der Notentlüftung in den unterirdischen Tunneln gefangen waren. Das giftige radioaktive Gas verformte ihre Körper, ließ ihre Haut kränklich grün werden und zerstörte ihren Verstand, sodass sie tollwütig wurden und nur noch Thermaplugg die Treue hielten.",al={"waren leprognome normal","wie wurden leprognome gemacht","ursprung der leprognome"}},c40f7a95={q="Wissen Leprognome, was sie tun?",a="Nein. Die Strahlung hat sie völlig wahnsinnig gemacht. In ihrem Delirium halluzinieren Leprognome oft, dass alle Außenstehenden, die die Stadt betreten – selbst Völker der Allianz – Trogg-Eindringlinge seien. Mit der Zeit zersetzt die anhaltende Exposition ihren Verstand noch weiter zu sabbernden Elenden.",al={"haben leprognome einen verstand","sind leprognome wahnsinnig","können leprognome denken"}},["322b05cb"]={q="Warum brauchen die Gnome externe Abenteurer statt ihrer eigenen Armee?",a="Fast achtzig Prozent der gnomischen Bevölkerung wurden bei der Katastrophe ausgelöscht, was ihr Militär dezimiert hat. Die wenigen überlebenden gnomischen Soldaten sind damit beschäftigt, die Sicherheit aufrechtzuerhalten und Kriegsmaschinen für die Allianz in Eisenschmiede zu entwickeln, was Mekkadrill dazu zwingt, abgehärtete Mercenaries und Helden anzuheuern, um die giftigen Ruinen zu säubern.",al={"warum braucht man externe abenteurer","warum keine gnome armee nutzen","warum fragt man mich wegen gnomeregan"}},["300e368c"]={q="Wie bin ich in Gnomeregan gelandet?",a="Ihr seid in Gnomeregan angekommen, indem Ihr durch die schneebedeckten Ausläufer von Dun Morogh gereist seid, am Bräuhall vorbei nach Westen zu den massiven mechanischen Eingangstoren der Stadt und durch deren Dienstaufzüge hinabgestiegen seid. Alternativ können Abenteurer der Horde eine direkte Teleportationsbake nehmen, die in Beutebucht von Goblin-Ingenieuren installiert wurde, die ein aktives, lukratives Interesse an jeder Technologie haben, die aus den Ruinen geborgen werden kann.",al={"wie bin ich hierher gekommen","wie kommt man in gnomeregan rein","gnomeregan eingang"}},bfca8253={q="Hätten die Gnome Gnomeregan retten können?",a="Niemand kann das mit Gewissheit sagen. Die Invasion der Troggs schlug zu, während der Dritte Krieg tobte, und die Gnome bekämpften sie auf sich allein gestellt, bis das verzweifelte Entlüften der radioaktiven Tanks der Stadt das Schicksal Gnomeregans besiegelte.",al={"hätten sie die stadt retten können","konnte gnomeregan gerettet werden","musste gnomeregan fallen"}},["46a0252f"]={q="Wer hat die Strahlung in Gnomeregan ausgelöst?",a="Hochtüftler Gelbin Mekkadrill befahl auf Anraten seines obersten Beraters, des Mechatüftlers Thermadraht, die Notentlüftung der radioaktiven Tanks der Stadt. Der Plan sollte nur die unteren Ebenen fluten, um die eindringenden Troggs auszurotten, doch die Strahlung tötete fast achtzig Prozent der Gnome. Thermadraht, der heimlich das Amt des Hochtüftlers begehrt hatte, wird nun als Verräter gebrandmarkt; Gerüchte, wonach er bereits im Vorfeld von der Trogg-Invasion wusste, wurden nie bestätigt.",al={"wer hat gnomeregan verstrahlt","wer hat das gas freigesetzt","wer hat die strahlung ausgeloest"}},["21748788"]={q="Gibt es noch einen Gnomenkönig?",a="Die Gnome haben keine traditionelle Monarchie; sie sind eine Leistungsgesellschaft, die von einem gewählten Hochtüftler angeführt wird. Zwar scherzt Mekkadrill gelegentlich darüber, sich selbst 'König der Gnome' zu nennen, doch der Einzige, der innerhalb von Gnomeregan Anspruch auf einen königlichen Titel erhebt, ist der verrückte Verräter Mechatüftler Thermadraht, der sich selbst zum Techno-Oberlord krönte.",al={"gibt es einen gnomkoenig","haben gnome einen koenig","gnomen-koenigtum"}},["0653d7e6"]={q="Was sind all diese Gnomenmaschinen, die mich bekämpfen?",a="Die mechanischen Konstrukte, Lochkarten-Wachposten und Meuteverprügler, denen Ihr begegnet, waren ursprünglich zivile Verteidigungs- und Nutzautomaten, die gebaut wurden, um die Stadt zu beschützen und die Ordnung aufrechtzuerhalten. Mechatüftler Thermadraht riss ihre Hauptkontrollsysteme an sich und programmierte sie um, damit sie jeden Eindringling angreifen, der sein Reich betritt.",al={"angreifende gnomenmaschinen","warum sind roboter in gnomeregan feindselig","wer kontrolliert die maschinen von gnomeregan"}},["8cb52331"]={q="Was soll ich in Gnomeregan tun?",a="Ihr seid hier, um einen Schlag gegen den verrückten Verräter Mechatüftler Thermadraht zu führen, der die Kontrolle über die Stadt an sich riss, nachdem er Hochtüftler Gelbin Mekkadrill dazu verleitet hatte, ihre unteren Ebenen mit giftiger Strahlung zu fluten. Im Auftrag der im Exil in Eisenschmiede lebenden Gnome – oder auf der Suche nach Bergungsgut und technologischen Geheimnissen – müsst Ihr Euch durch Horden verstrahlter Troggs, durchgedrehter Verteidigungsautomaten und wahnsinniger Lepragnome vorkämpfen, um Tinkers' Court zu erreichen und Thermadrahts Herrschaft ein Ende zu setzen.",al={"warum bin ich hier","was ist meine mission hier","was tun in gnomeregan"}}},fp="10,331,26.559.0,36.587.0,27.653.1,17.596.1,29.340.0,35.286.0,67.301.0,22.308.0,29.337.0,53.258.1,48.273.0,42.304.0"}
P.entries["zone:hallofthanes"] = {n="Die Halle der Thanen",s="Verteidiger der Allianz suchen nun einen Weg in die Halle der Thanen, tief unter Eisenschmiede. Ihre alten Gewölbe bergen Zwergenrelikte, und die Gefahr hat diese Tiefen erreicht.",h="Verteidiger der Allianz suchen nun einen Weg in die Halle der Thanen, tief unter Eisenschmiede.",kw={"freischaltung","dungeon","durgen dirgehammer","faldrim ambossar","die halle der thanen","eisenschmiede","magmatus","plunder","underground map"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, die Stabilität Eisenschmiedes zu schützen, indem Ihr tiefe Höhlen säubert und den High Seat sichert.",["race:Dwarf"]="Als Zwerg dringt Ihr in das uralte Felsgestein Dun Moroghs ein und vertreibt Entweiher aus heiligen Hallen, die legendäre Clannamen tragen.",["race:Gnome"]="Als Gnom, der an der Seite enger Verbündeter in Eisenschmiede lebt, habt Ihr allen Grund, dabei zu helfen, mechanische Konstrukte wie Plunder davon abzuhalten, Euer gemeinsames Zuhause zu bedrohen."},sec={{t="Geheimnisse unter dem Berg",b="In der Großen Schmiede von Eisenschmiede erklingen die Hämmer, doch vergessene Hallen reichen tief unter den Stein. Die Halle der Thanen liegt in diesen uralten Tiefen und ist mit Zwergenblutlinien und Relikten der Steinarbeitskunst verbunden. Nun müssen Champions der Allianz ihre schattigen Gewölbe betreten und die Tiefen schützen."},{t="Den Weg aufdecken",b="Der Weg in die Halle der Thanen ist vor den gewöhnlichen Reisenden Eisenschmiedes verborgen. Ihre Gänge wurden versiegelt oder versteckt. Um einen Durchgang zu finden, müsst Ihr eine Underground Map bergen und mithilfe vergessener Karten durch die tieferen Tunnel bis zum Eingang navigieren."},{t="Die Bedrohung durch Dirgehammer",b="Durgen Dirgehammer befehligt das innere Heiligtum der Halle der Thanen. Plunder, ein verzauberter Wächter, und der feurige Hüne Magmatus bedrohen ihre Hallen. Faldrim Ambossar entstammt einer uralten Zwergenlinie. Durgen zu besiegen beendet die Unruhen unter der Stadt und schützt die heiligen Hallen vor Unterwanderung."}},faq={{q="Wo befindet sich die Halle der Thanen?",a="Die Halle der Thanen liegt unter Eisenschmiede, in den tieferen, abgesperrten Gängen des Berges, fern der Hauptstraßen der Stadt.",al={"standort der halle der thanen","wo liegt die halle der thanen","standort des dungeons in eisenschmiede"}},{q="Wie erhalte ich Zugang zur Halle der Thanen?",a="Earthseer Farsen hält im Steinbruch Gol'Bolar in Dun Morogh Wache und leitet den Weg ein. Bergt die Underground Map und folgt dann Old Eisenschmiede Incursion in die Halle der Thanen.",al={"zugang zur halle der thanen","freischaltung der halle der thanen","quest nach der underground map"}},{q="Welche Bosse befinden sich in der Halle der Thanen?",a="Vier große Bedrohungen erwarten Euch im Inneren: Faldrim Ambossar, Magmatus, der verzauberte Golem Plunder und Durgen Dirgehammer.",al={"bossliste","wer sind die bosse","bosse der halle der thanen"}},{q="Für welchen Stufenbereich wird dieser Dungeon empfohlen?",a="Die Halle der Thanen ist für Abenteurer der Allianz zwischen Stufe 13 und 18 ausgelegt und bietet eine frühe Herausforderung tief unter Eisenschmiede.",al={"welche stufe hat die halle der thanen","stufenbereich der halle der thanen"}},{q="Können Spieler der Horde die Halle der Thanen betreten?",a="Nein. Die Halle der Thanen ist für die Allianz bestimmt und liegt unter ihrer Hauptstadt Eisenschmiede.",al={"kann die horde die halle der thanen betreten","ist die halle der thanen nur für die allianz"}},{q="Was bewirkt es, Durgen Dirgehammer zu besiegen?",a="Wenn Ihr Durgen Dirgehammer besiegt, brecht Ihr die Macht abtrünniger Zwergenkräfte und ihrer beschworenen Konstrukte unter Eisenschmiede. Die Ahnengruften unter der Großen Schmiede sind wieder sicher.",al={"warum dirgehammer töten","geschichte des endbosses","hintergrundgeschichte von durgen dirgehammer"}}},fx={["89d0670c"]={q="Was ist die Halle der Thanen?",a="Die Halle der Thanen ist ein Instanz-Dungeon tief unter der Zwergenhauptstadt Eisenschmiede. Während Eisenschmiede normalerweise als prächtige Heimat des Bronzebart-Clans belebt ist, birgt diese unterirdische Domäne schwelende interne Bedrohungen und feindliche Begegnungen, die erfahrene Verteidiger der Allianz erfordern, um unter den Berg vorzudringen und die Ordnung wiederherzustellen.",al={"hintergrundgeschichte halle der thanen","was ist dieser dungeon","halle der thanen dungeon"}},["20f1c0f0"]={q="Wie bin ich in die Halle der Thanen gelangt?",a="Ihr seid der Spur einer alten unterirdischen Karte gefolgt, die tief im zwergischen Gebiet entdeckt wurde. Nachdem Ihr ihre Geheimnisse entschlüsselt und Zugang von innerhalb von Eisenschmiede erhalten habt, führte Euch Eure Suche in diese vergessenen Steinhallen, die direkt unter den Berg gehauen wurden.",al={"wie bin ich hierher gelangt","wie bin ich hier gelandet","wie habe ich die halle der thanen gefunden"}},b863ae36={q="Was soll ich in der Halle der Thanen tun?",a="Ihr seid hier, um tief in diese uralten Gewölbe vorzudringen, die feindlichen Streitkräfte zu überwinden, die sie besetzt halten, und die Bedrohungen zu zerschlagen, die in der Dunkelheit lauern. Eure Expedition gipfelt in der Konfrontation mit gefährlichen Abtrünnigen und Wächtern, darunter Faldrim Ambossar, Plunder, Magmatus und Durgen Totenhammer.",al={"was mache ich hier","warum bin ich hier","was ist mein ziel hier"}}},fp="14,155,28.269.0,19.248.0,25.304.1,36.128.0,43.167.0,42.113.0,49.121.0,43.85.0,47.176.1"}
P.entries["zone:hillsbrad"] = {n="Vorgebirge des Hügellands",s="Im Vorgebirge des Hügellands trennen grüne Felder noch immer zwei verfeindete Mächte. Die Menschen von Süderstade und die Verlassenen in Tarrens Mühle kämpfen auf den Weiden und machen die Region zum Schlachtfeld der Allianz und der Horde.",h="Im Vorgebirge des Hügellands trennen grüne Felder noch immer zwei verfeindete Mächte.",kw={"azurelode","dun garok","burg durnholde","hillsbrad","die felder von hillsbrad","fegefeuerinsel","süderstade","syndikat","tarrens mühle"},ang={["class:Rogue"]="Das Rabenholdtanwesen liegt verborgen in den Bergen über dem Vorgebirge. Es ist der geheime Treffpunkt und Ausbildungsort der angesehensten Diebes- und Assass nengilde Azeroths.",["race:Dwarf"]="Die Soldaten von Dun Garok zeigen die Entschlossenheit Eisenschmiedes, seine menschlichen Verbündeten zu verteidigen und die Bedrohung durch die Untoten nördlich des Sumpflands einzudämmen.",["race:Human"]="Süderstade ist eine der letzten Zufluchten Eures Volkes in Lordaeron. Seine Weiden erinnern an das große Königreich, das durch Verrat und Untod verloren ging.",["race:Orc"]="Die zerstörten Wehrmauern von Burg Durnholde markieren den Ort, an dem Kriegshäuptling Thrall seine Ketten sprengte und den Geist der Horde neu entfachte.",["race:Undead"]="Tarrens Mühle sichert die Südgrenze des Reichs der Verlassenen. Apotheker Lydon arbeitet dort daran, The New Plague zu entwickeln und die Zukunft Eures Volkes zu sichern."},sec={{t="Ein Garten neben den Ruinen",b="Das Vorgebirge des Hügellands besitzt noch immer grüne Felder, während die Seuche weite Teile des nördlichen Lordaerons verzehrt. Weiden, Kiefernhaine und bewirtschaftete Höfe erinnern an das Königreich vor dem Dritten Krieg. Bewaffnete Patrouillen, abtrünnige Söldner und aasfressende Bestien durchqueren die Felder und Straßen. Einst Lordaerons Kornkammer, ist Hillsbrad heute eines seiner umkämpftesten Grenzgebiete."},{t="Der Krieg zwischen Süderstade und Tarrens Mühle",b="Süderstade liegt an der Südküste und wird von menschlichen Flüchtlingen und Soldaten gehalten, die der Allianz treu sind. Nördlich davon war Tarrens Mühle einst ein stilles menschliches Bauerndorf. Die Geißel zerstörte es, und die Verlassenen befestigten es als ihre südlichste Garnison. Das offene Land dazwischen ist zu einem erbarmungslosen Schlachtfeld geworden, auf dem Champions der Allianz und der Horde um die Kontrolle über Hillsbrad kämpfen."},{t="Alte Wunden und verborgene Gefahren",b="Die Gewalt in Hillsbrad reicht bis zum Zweiten Krieg zurück. An seiner Küste und in seinen Hügeln kam es zu den ersten großen Zusammenstößen zwischen der Großen Allianz und der Alten Horde. Später befand sich in Burg Durnholde das Internierungslager, in dem Thrall aufwuchs, bevor er die Rebellion der Orcs anführte. Nun gehört die zerstörte Burg dem Syndikat, vertriebenen menschlichen Adligen, die zu Banditen wurden.\n\nKüstenmurlocs, feindselige Gnolle und die schattenhaften Toten auf der Fegefeuerinsel lassen keinen Winkel der Hügel sicher erscheinen."}},faq={{q="Warum ist Hillsbrad nicht wie der Rest von Lordaeron von der Seuche verheert?",a="Die Geißel zog hauptsächlich durch zentrale Korridore zur Hauptstadt und den nördlichen Königreichen und ließ Hillsbrad weitgehend außerhalb der Seuchenkessel, die den Norden verwüsteten. Sein Boden ist fruchtbar und die Vegetation gesund geblieben. Damit ist es der unversehrteste Überrest des alten Lordaerons.",al={"warum ist hillsbrad grün","wurde hillsbrad von der seuche heimgesucht","warum gibt es in hillsbrad keine seuche"}},{q="Wer kontrolliert Hillsbrad derzeit?",a="Keine der beiden Fraktionen kontrolliert ganz Hillsbrad. Die Allianz hält Süderstade und nahegelegene Höfe wie Die Felder von Hillsbrad, während die Verlassenen Tarrens Mühle im Norden halten. Zwerge besetzen Dun Garok im Osten, und das kriminelle Syndikat hält die Ruinen von Burg Durnholde.",al={"wem gehört hillsbrad","fraktionskontrolle in hillsbrad","gehört hillsbrad zur allianz oder horde"}},{q="Was ist Burg Durnholde?",a="Burg Durnholde diente einst nach dem Zweiten Krieg als Hauptquartier des Internierungslagersystems der Allianz. Aedelas Blackmoore verwaltete die Burg und zog Thrall dort als Gladiatorensklaven auf. Thrall entkam, sammelte die Orcs um sich und verwüstete Burg Durnholde. Nach dem Fall Lordaerons besetzte das Syndikat die Ruinen.",al={"geschichte von burg durnholde","was geschah in burg durnholde","wer kontrolliert burg durnholde"}},{q="Warum kämpfen die Verlassenen und die Menschen hier so erbittert?",a="Tarrens Mühle markiert die Südgrenze von Sylvanas Windläufers Herrschaftsgebiet, während Süderstade der wichtigste Aufmarschort und Hafen der Allianz in Lordaeron ist. Die Verlassenen sehen Süderstade als Bedrohung ihrer Südflanke. Die Menschen betrachten die Untoten als Usurpatoren, die aus ihrer Heimat vertrieben werden müssen.",al={"grund für den krieg um süderstade","geschichte des konflikts zwischen süderstade und tarrens mühle","grund für den konflikt in hillsbrad"}},{q="Was ist die Fegefeuerinsel?",a="Die Fegefeuerinsel ist eine zerklüftete, abgelegene Insel vor Hillsbrads Südküste. Mächtige untote Ghule, Skelette und rachsüchtige Geister bevölkern sie. Dadurch ist sie ein gefährlicher Zufluchtsort vor der Küste für dunkle Magie und ruhelose Tote.",al={"geschichte der fegefeuerinsel","insel vor süderstade","warum sind untote auf der fegefeuerinsel"}},{q="Wer sind die Banditen in den Lagern und Türmen?",a="Die Banditen gehören zum Syndikat, einem Netzwerk ehemaliger Adliger und Fußsoldaten aus dem gefallenen Menschenkönigreich Alterac. Nach dem Verrat ihres Königreichs im Zweiten Krieg wurden sie verstoßen. Nun wollen sie ihr Land mit Erpressung, Diebstahl und Mord zurückerobern.",al={"banditen in hillsbrad","wer ist das syndikat","syndikat in hillsbrad"}}},fx={["5a0996a2"]={q="Was ist das Vorgebirge des Hügellands?",a="Das Vorgebirge des Hügellands ist ein hügeliges, gemäßigtes Küstengebiet am südlichen Rand des gefallenen Lordaeron, begrenzt durch den Silberwald im Westen, das schneebedeckte Alteracgebirge im Norden und den Thoradinswall, der im Osten zum Arathihochland führt. Anders als die verheerten Lande im Norden ist das Vorgebirge des Hügellands üppig und ländlich geblieben, mit grünen Wiesen, ertragreichen Farmen und Klippen am Meer. Unter dieser idyllischen Fassade dient es als gewaltsames Grenzgebiet, das zwischen den überlebenden Menschen der Allianz und den vordringenden Verlassenen umkämpft ist.",al={"was ist hillsbrad","übersicht vorgebirge des hügellands","erzähle mir von hillsbrad"}},["88d7d468"]={q="Was ist im Vorgebirge des Hügellands geschehen?",a="Das Vorgebirge des Hügellands war lange Zeit eines der blutigsten Schlachtfelder in Lordaeron. Während des Zweiten Krieges kam es hier zu den allerersten Zusammenstößen zwischen der Allianz und der alten Horde, einschließlich heftiger Scharmützel mit Waldtrollen und Überfällen auf die Küste, durch die Städte wie Hillsbrad und Süderstade kurzzeitig in Ruinen lagen. Später konzentrierten sich die Internierungslager für Orcs auf diesen Ort bei Burg Durnholde, bis Thralls Aufstand die Festung dem Erdboden gleichmachte. Als der Dritte Krieg ausbrach, stahl Thrall Schiffe aus Süderstade, um Kalimdor zu erreichen, und die Geißel überrannte später den Norden, was die Verlassenen schließlich dazu veranlasste, Tarrens Mühle zu erobern.",al={"geschichte von hillsbrad","geschichte der battle of hillsbrad","vergangenheit von hillsbrad"}},["10678baf"]={q="Ist das Vorgebirge des Hügellands gefährlich?",a="Äußerst gefährlich. Neben einheimischen Raubtieren wie Berglöwen, Schnappschildkröten und umherstreifenden Spinnen ist das Vorgebirge des Hügellands eine aktive Kriegszone. Die menschlichen Wachen von Süderstade und die Todespirscher der Untoten von Tarrens Mühle jagen einander auf den Straßen. Zusätzlich operieren Schergen des Syndikats aus verstreuten Türmen und den Ruinen von Burg Durnholde, feindselige Daggerspine-Naga und Torn Fin-Murlocs befallen die Küste, Gnolle der Schlammschnauze durchstreifen die Wälder und Zwergenschützen besetzen in großer Zahl Dun Garok.",al={"wie gefährlich ist hillsbrad","ist hillsbrad sicher","gefahren in hillsbrad"}},dea356d1={q="Was ist Tarrens Mühle und warum ist die Horde hier?",a="Tarrens Mühle ist eine heruntergekommene Siedlung im nördlichen Vorgebirge, die als südlichste Festung der Verlassenen in Lordaeron dient. Einst ein friedliches Bauerndorf der Menschen, fiel es während der Invasion der Geißel und wurde später von Sylvanas Windläufers Streitkräften besetzt. Von hier aus projiziert die Horde ihre Macht nach Süden, beherbergt Apotheker, die an bösartigen Gebräuen arbeiten, und stationiert Truppen, um wiederholte Angriffe auf Süderstade und die nahe gelegenen menschlichen Ackerländer durchzuführen.",al={"was ist tarrens mühle","warum horde in tarrens mühle","horde basis tarrens mühle"}},b39e7470={q="War Tarrens Mühle vorher eine Stadt der Menschen?",a="Ja. Vor dem Dritten Krieg war Tarrens Mühle eine blühende Stadt unter dem Königreich Lordaeron. Im Zweiten Krieg entsandte König Terenas Truppen hierher, um gefangene Hochelfentruppen zu befreien, die in der Nähe von der Horde festgehalten wurden – ein Akt, der dazu beitrug, das Bündnis von Quel'Thalas mit der Menschheit zu festigen. Selbst nachdem das Königreich gefallen war, hielt sich ein Kontingent von Menschen kurzzeitig an die Stadt, bevor die Geißel und die anschließende Besetzung durch die Verlassenen sie beanspruchten.",al={"lebten menschen in tarrens mühle","war tarrens mühle menschlich","vergangenheit von tarrens mühle"}},c8808bc1={q="Wer hat in Tarrens Mühle das Sagen?",a="Hochexekutorin Darthalia befehligt die Militärgarnison der Verlassenen in Tarrens Mühle. Sie leitet die Kriegsanstrengungen im gesamten Vorgebirge und ordnet chirurgische Schläge gegen menschliche Farmer, die Stadt Süderstade und rivalisierende Fraktionen in der gesamten Region an. An ihrer Seite überwachen Forscher der Königlichen Apothekervereinigung wie Apotheker Lydon die lokalen Operationen und chemischen Experimente.",al={"wer leitet tarrens mühle","anführer von tarrens mühle","kommandant von tarrens mühle"}},["9809687d"]={q="Worum geht es bei der Battle of Hillsbrad eigentlich?",a="Der andauernde Kampf ist ein territorialer und existenzieller Zusammenstoß um das südliche Lordaeron. Die Menschen von Süderstade und den Feldern von Hillsbrad kämpfen darum, die letzten Überreste ihrer unverdorbenen Heimat zu verteidigen und einen lebenswichtigen Stützpunkt an der Küste zu halten. Umgekehrt versuchen die Verlassenen, die Grenzen ihres jungen Königreichs von der Unterstadt aus nach außen zu erweitern, die landwirtschaftlichen Versorgungswege der Menschen systematisch zu zerstören und die Allianz zu vertreiben, damit diese keine Gegeninvasion starten kann.",al={"warum kämpfen sie im vorgebirge des hügellands","zweck der battle of hillsbrad","grund für den krieg im hügelland"}},["3a05e673"]={q="Was ist Süderstade?",a="Süderstade ist eine geschäftige Hafenstadt der Allianz an der südlichen Küste. Ursprünglich ein bescheidenes Fischerdorf, diente es während des Ersten Krieges als Landungspunkt für Flüchtlinge aus Sturmwind, bevor es im Zweiten Krieg zu einem stark verteidigten Militärhafen ausgebaut wurde. Heute fungiert es unter der Führung von Magistrat Henry Maleb und Marshal Redpath als wichtigste Zuflucht für menschliche Überlebende, Seeleute und Abenteurer der Allianz im nördlichen Lordaeron.",al={"was ist süderstade","übersicht süderstade","allianz süderstade"}},["54a7e72a"]={q="Waren in Burg Durnholde Orcs gefangen?",a="Ja. Nach dem Sieg der Allianz im Zweiten Krieg diente Burg Durnholde als Hauptquartier für das gesamte Netzwerk der Internierungslager im Süden, unter dem Kommando von Generalleutnant Aedelas Blackmoore. Gefangene Orcs wurden hier von Wachen der Allianz inhaftiert und befriedet. Am bemerkenswertesten ist, dass Blackmoore den verwaisten Säugling Thrall innerhalb ihrer Arenamauern aufzog, der schließlich ausbrach, seine Brüder mobilisierte und die Festung mit Hilfe der Erdgeister dem Erdboden gleichmachte.",al={"war burg durnholde ein internierungslager","orc gefangene in burg durnholde","internierung in burg durnholde"}},ee5f5dea={q="Wer hält jetzt Burg Durnholde?",a="Die zertrümmerten Steinhöfe und ausgebrannten Unterkünfte von Burg Durnholde werden jetzt vom Syndikat besetzt. Diese verbannten Adligen, in Ungnade gefallenen Gefolgsleute und Banditen aus dem gefallenen Königreich Alterac haben die Ruinen befestigt und nutzen sie als Ausgangsbasis, um Versorgungswege, Karawanen und Reisende im östlichen Hillsbrad zu überfallen.",al={"wer ist in burg durnholde","banditen in burg durnholde","wer kontrolliert burg durnholde"}},["7f2bc51a"]={q="Was ist Dun Garok und warum sind dort Zwerge?",a="Dun Garok ist eine robuste Zwergenfestung, die in die felsigen südöstlichen Klippen des Hügellands eingebettet ist und vom Sturmspitz-Clan sowie den Bergsteigern der Eisenschmiede unter Hauptmann Eisenhügel besetzt wird. Diese standhaften Truppen trafen ein, um die Positionen der Allianz zu verstärken, nahe gelegene Bergbauressourcen wie den Azurschacht zu sichern und zu verhindern, dass die Streitkräfte der Verlassenen nach Osten durch das Gebirge in Richtung Thoradinswall vorstoßen.",al={"was ist dun garok","warum gibt es zwerge im hügelland","zwerge in dun garok"}},b8990472={q="Was sind das für Murlocs und naga-artige Wesen an der Küste?",a="Die Uferlinie wird vom Murlocstamm der Torn Fin und den schlangenartigen Naga, bekannt als die Daggerspine, überrannt. Die Torn Fin lauern im seichten Wasser, greifen Fischer an und konkurrieren mit Bergleuten entlang der Küste. In der Zwischenzeit sind die Daggerspine-Naga an Land gekrochen, um Küstenenklaven zu errichten, und greifen jeden bösartig an, der in der Nähe der Brandung reist oder die Küste plündert.",al={"murlocs an der küste von hillsbrad","naga im hügelland","küstenmonster hillsbrad"}},["235a8e20"]={q="Wie bin ich im Vorgebirge des Hügellands gelandet?",a="Euer Weg hierher hängt von Eurer Zugehörigkeit ab. Wenn Ihr mit der Horde marschiert, seid Ihr wahrscheinlich vom Grabmal im Silberwald nach Süden gereist und seid der langen, kurvenreichen Straße entlang der südlichen Grenze Lordaerons nach Osten gefolgt, bis Ihr Tarrens Mühle erreicht habt. Wenn Ihr für die Allianz kämpft, seid Ihr weit von den Zwergenhallen der Eisenschmiede gereist, durch Loch Modan und die durchnässten Sümpfe des Sumpflands nach Norden marschiert, habt das Arathihochland durchquert und seid durch die uralte Bresche des Thoradinswalls gezogen, um den Hafen von Süderstade zu erreichen. Alternativ trotzen wagemutige Seeleute und Schwimmer manchmal der Meerespassage direkt nördlich vom Hafen von Menethil.",al={"wie bin ich ins vorgebirge des hügellands gekommen","wie bin ich hierher gekommen","warum bin ich im vorgebirge des hügellands","wie erreiche ich hillsbrad"}},f17f6b77={q="Was soll ich im Vorgebirge des Hügellands tun?",a="Ihr steht an einer der instabilsten Frontlinien in Azeroth. Für die Allianz konzentriert sich Eure Pflicht auf Süderstade und die Felder von Hillsbrad: die Verteidigung menschlicher Farmer gegen die Aggression der Untoten, die Jagd auf die Schurkenbanditen des Syndikats und das Eindämmen der wilden Kreaturen, die die Küsten befallen. Für die Horde verlangen Hochexekutorin Darthalia und die Königliche Apothekervereinigung in Tarrens Mühle die systematische Zerschlagung des menschlichen Widerstands, das Ernten von Zutaten für eine A New Plague, und das Zurückdrängen der Sturmspitz-Zwerge und Soldaten der Allianz. Auf den Feldern zwischen den beiden Städten erfordert das Überleben ständige Wachsamkeit gegenüber feindlichen Champions.",al={"was mache ich hier","was soll ich im hügelland tun","was ist mein ziel im hügelland","warum bin ich hier"}}},fp="19,211,25.349.0,37.387.0,28.450.0,56.278.0,33.271.0,23.306.0,54.295.0,23.214.0,51.260.0"}
P.entries["zone:hinterlands"] = {n="Hinterland",s="Das Hinterland trägt noch immer die alten Gebietsansprüche der Amani, während Wildhammerzwerge den Nistgipfel halten. Waldtrolle beherrschen ihre verfallenen Tempel, und die Revantusk haben an der Ostküste ein Dorf gegründet.",h="Das Hinterland trägt noch immer die alten Gebietsansprüche der Amani, während Wildhammerzwerge den Nistgipfel...",kw={"nistgipfel","greif","hinterland","jintha'alor","quel'danil","revantusk","seradane","vilebranch","wildhammer","witherbark"},ang={["class:Druid"]="Seradanes uralter Baum ist eng mit dem Smaragdgrünen Traum verbunden. Achtet auf die schleichende Fäulnis des Alptraums.",["faction:Alliance"]="Die Wildhammerzwerge schätzen ihre wilde Unabhängigkeit. Helft ihren Außenposten und den Hochelfen von Quel'Danil, im Kampf gegen die gemeinsamen Trollbedrohungen Vertrauen aufzubauen.",["faction:Horde"]="Das Dorf Revantusk verschafft der Horde einen östlichen Brückenkopf im nördlichen Lordaeron. Um ihn zu halten, müsst Ihr die wilden Vilebranch zurückschlagen.",["race:Dwarf"]="Als Wildhammer oder zu Besuch weilender Bronzebart erlebt Ihr auf dem Nistgipfel das Zwergenleben unter offenem Himmel. Schamanische Macht und legendäre Greifen prägen das Leben dort.",["race:Troll"]="Im Hinterland lebt der alte Ruhm der Amani weiter, während Blutlinien um Tempelstufen kämpfen. Die Revantusk zeigen, dass Waldtrolle in The New Horde noch immer ihren Platz haben."},sec={{t="Ein Land voller Ansprüche",b="Die Amani-Waldtrolle herrschten über das Hinterland, lange bevor Menschen oder Zwerge ins nördliche Lordaeron kamen. Ihre Niederlage in den uralten Trollkriegen zerschlug das Imperium in einzelne Stämme. Jahrhunderte später vertrieb der Krieg der drei Hämmer die Wildhammerzwerge aus Grim Batol.\n\nSie wanderten nach Norden und siedelten sich auf dem Nistgipfel über der Erde an. Dort zähmten sie einheimische Greifen und bewahrten ihre schamanischen Traditionen, während sie in den Höhen eine große Festung errichteten. Die Waldtrolle betrachteten sie als Eindringlinge auf dem Land ihrer Ahnen. Scharmützel und Überfälle halten die Fehde seitdem am Leben."},{t="Stämme des Waldes",b="Drei Waldtrollstämme bewohnen die dichten Wälder und verfallenen Tempel. Die stärksten sind die brutalen Vilebranch, die die terrassierte Tempelstadt Jintha'Alor und den hoch aufragenden Altar von Zul halten. Weiter südlich klammern sich die schwächeren Witherbark an Shadra'Alor und Hiri'Watha.\n\nDie nomadischen Revantusk wurden lange von ihren Vettern verachtet und hatten keine wahre Heimat. Nach dem Dritten Krieg schlossen sie einen Vertrag mit Thralls New Horde. Mit Hilfe von Orcs und Verlassenen gründeten sie an den östlichen Meeresklippen das Dorf Revantusk und beanspruchten eine eigene Küstenfestung."},{t="Der schlummernde Riss",b="Seradane, der große Baum im nördlichen Hinterland, birgt ein Portal zum Smaragdgrünen Traum. Grüne Drachen und Kreaturen der Natur bewachen den Hain. Nun sickert der Smaragdgrüne Alptraum über die Schwelle des Portals und verwandelt einst wohlwollende Drachen und Drachkin in wütende Wächter."}},faq={{q="Wie komme ich ins Hinterland?",a="Reisende beider Fraktionen betreten das Hinterland vom Vorgebirge des Hügellands aus. Sie ziehen nordöstlich durch einen Gebirgspass hinter Burg Durnholde. Reisende der Allianz folgen der Straße zum Nistgipfel, während Reisende der Horde östlich durch die Wildnis zum Dorf Revantusk an der Küste ziehen.",al={"zugang zum hinterland","wie man ins hinterland kommt","ins hinterland reisen"}},{q="Wer herrscht über den Nistgipfel?",a="Falstad Wildhammer, Herr des Nistgipfels, führt dort den Wildhammerklan an. Than Kurdran Wildhammer führte den Klan während des Zweiten Kriegs.",al={"anführer der wildhammer","wer führt die wildhammer an","herrscher des nistgipfels"}},{q="Warum sind die Revantusk-Trolle mit der Horde verbündet?",a="Die nomadischen Revantusk suchten Schutz und wollten das Umherziehen beenden. Die feindseligen Vilebranch und Witherbark wiesen Gesandte der Horde ab. The New Horde gab den Revantusk Mittel und Soldaten, um das Dorf Revantusk an der Küste zu errichten, und gewann so ihre Treue im Kampf gegen die Rivalen vor Ort.",al={"revantusk und horde","warum trolle der horde im hinterland beitreten","geschichte des dorfes revantusk"}},{q="Was ist Jintha'Alor?",a="Jintha'Alor ist eine uralte Festung, die sich in vielen Terrassen in die südlichen Klippen schneidet. Sie ist die wichtigste Festung der skrupellosen Vilebranch und beherbergt Opferaltäre und Elitesoldaten. Ihre Hexendoktoren vollziehen Blutrituale für ihre dunklen Loa.",al={"geschichte von jintha'alor","trollstadt im hinterland","stadt der vilebranch"}},{q="Was ist der Große Baum bei Seradane?",a="Seradane, einer der Großen Bäume Azeroths, birgt ein Portal zum Smaragdgrünen Traum. Grüne Drachen und Wildkin bewachen den Hain.",al={"portal bei seradane","großer baum im hinterland","grüne drachen im hinterland"}},{q="Was ist Die Quel'Danil-Hütte?",a="Die Quel'Danil-Hütte ist ein Waldrefugium der Hochelfen von Highvale. Die Geißel verschonte sie bei ihrem direkten Angriff auf Quel'Thalas. Ihre Waldläufer und Gelehrten arbeiten mit den nahegelegenen Wildhammerzwergen zusammen und tauschen Informationen über feindselige Waldtrolle aus.",al={"hochelfenhütte im hinterland","quel'danil","elfen im hinterland"}}},fp="15,193,25.569.0,20.545.0,19.283.1,32.283.0,21.133.0,51.270.0,20.236.0,35.127.0,25.237.0"}
P.entries["zone:hyjal"] = {n="Hyjal",s="Auf Hyjal krönt Nordrassil noch immer den heiligen Berg über dem zweiten Brunnen der Ewigkeit. In der letzten Schlacht des Dritten Krieges hielten Nachtelfen, Menschen und Orcs die Hänge gegen die Brennende Legion, bis Archimonde an den Wurzeln des Weltbaums fiel. Die Schlacht zeichnete den Berg mit Narben, und der verwundete Baum steht noch immer über dem Brunnen.",h="Auf Hyjal krönt Nordrassil noch immer den heiligen Berg über dem zweiten Brunnen der Ewigkeit.",kw={"archimonde","grabhügelbaue","schlacht um hyjal","druids of the claw","hyjal","hyjal summit","nordrassil","brunnen der ewigkeit","weltbaum"},ang={["class:Druid"]="Als Druide ist Hyjal Euch heilig. Euer Orden schlief dort jahrhundertelang in den Grabhügelbauen, und sein Weltbaum verband Euch einst mit dem Smaragdgrünen Traum.",["faction:Alliance"]="Jaina Prachtmeers Überlebende aus Lordaeron hielten die erste Linie an Hyjals Hängen. Sie verschafften den Nachtelfen die nötige Zeit.",["faction:Horde"]="Thralls Horde kämpfte an diesen Hängen an der Seite von Menschen und Nachtelfen, um die Brennende Legion aufzuhalten.",["race:NightElf"]="Als Nachtelf kennt Ihr Hyjal als heiligsten Ort Eures Volkes. Hier gaben die Kaldorei ihre Unsterblichkeit auf, damit der Weltbaum Archimonde vernichten konnte."},sec={{t="Der heilige Berg",b="Vor zehntausend Jahren, nach der Großen Zerschlagung, goss Illidan Stormrage gestohlene Wasser aus dem ersten Brunnen der Ewigkeit in einen See auf Hyjal. Dort erschuf er einen zweiten Brunnen. Die Drachenaspekte ließen den Weltbaum Nordrassil über seinen Wassern wachsen, um ihn zu bewachen. Ihre Segen verliehen den Nachtelfen Unsterblichkeit und banden sie eng an den Smaragdgrünen Traum. Jahrtausendelang wachten die Kaldorei über den Berg, während ihre Druiden in den Grabhügelbauen darunter schliefen."},{t="Die Schlacht um Hyjal",b="Während des Dritten Krieges führte Archimonde die Geißel und die Brennende Legion Hyjal hinauf, um den Brunnen zu leeren und den Weltbaum zu zerstören. Jaina Prachtmeers Menschen und Thralls Horde legten alten Hass beiseite, um an der Seite von Tyrande Wisperwind und Malfurion Sturmgrimm zu kämpfen.\n\nSie hielten die Hänge, während Malfurion eine Falle vorbereitete. Als Archimonde Nordrassil erreichte, ließ Malfurion das Horn des Cenarius ertönen. Tausende Irrwische schwärmten über den Dämon her, und die gespeicherte Kraft des Baumes zerriss ihn. Die Nachtelfen verloren ihre Unsterblichkeit, und Nordrassil wurde versengt."},{t="Die Grabhügelbaue und der Gipfel",b="Unter Hyjal liegen die Grabhügelbaue, wo die Druids of the Claw Tausende von Jahren in Bärengestalt schliefen. Malfurion weckte sie mit dem Horn des Cenarius, damit sie gegen die Legion kämpften. Heute zählen die Grabhügelbaue und Hyjal Summit hoch oben auf dem Berg zu Kalimdors gefährlichsten Orten. Nur große Kriegstrupps erfahrener Helden können sich ihnen stellen."}},faq={{q="Wo liegt Hyjal?",a="Hyjal erhebt sich im Norden Kalimdors, umgeben von Eschental, Teufelswald und Winterquell. Auf seinem Gipfel stehen der Weltbaum Nordrassil und der zweite Brunnen der Ewigkeit.",al={"wo liegt hyjal","hyjal ort","wie gelangt man nach hyjal"}},{q="Was geschah in der Schlacht um Hyjal?",a="Am Ende des Dritten Krieges führte Archimonde die Brennende Legion und die Geißel Hyjal hinauf, um den Weltbaum zu zerstören. Menschen, Orcs und Nachtelfen hielten gemeinsam die Hänge, bis Malfurion Sturmgrimm an Nordrassil das Horn des Cenarius erschallen ließ. Daraufhin vernichteten Tausende Irrwische und die eigene Kraft des Baumes den Dämonenfürsten.",al={"schlacht um hyjal","wie starb archimonde","wer tötete archimonde"}},{q="Warum verloren die Nachtelfen hier ihre Unsterblichkeit?",a="Nordrassils Segen bewahrten die Nachtelfen vor dem Altern. Als die Macht des Baumes Archimonde vernichtete, verbrannten diese Segen, und die Kaldorei wurden sterblich.",al={"unsterblichkeit der nachtelfen","warum sind nachtelfen sterblich"}},{q="Was sind die Grabhügelbaue?",a="Die Grabhügelbaue sind ein uraltes Höhlensystem unter Hyjal, in dem die Druids of the Claw Tausende von Jahren im Smaragdgrünen Traum schliefen. Malfurion Sturmgrimm weckte sie, damit sie gegen die Brennende Legion kämpften. Ihre Tiefen zählen heute zu Kalimdors gefährlichsten Orten.",al={"grabhügelbaue","druids of the claw","grabhügelbaue von hyjal"}},{q="Was ist Hyjal Summit?",a="Hyjal Summit ist das hoch gelegene Gebiet auf Hyjal und zählt zu Kalimdors gefährlichsten Orten. Nur die stärksten Kriegstrupps wagen sich dorthin.",al={"hyjal summit","gipfel von hyjal"}}},fp="11,334,19.465.0,25.540.0,31.343.0,21.164.0,43.319.0,52.157.0,26.264.0,21.130.0"}
P.entries["zone:ironforge"] = {n="Eisenschmiede",s="Eisenschmiede liegt tief im Herzen eines Berges im Schnee von Dun Morogh. Sie ist die uralte Hauptstadt der Bronzebartzwerge und eine der stärksten Bastionen der Allianz. In ihrem Zentrum lodert Die Große Schmiede. Hier herrscht König Magni Bronzebart, und seine Hallen bieten nun auch den Gnomen Zuflucht, die Gnomeregan verloren haben.",h="Eisenschmiede liegt tief im Herzen eines Berges im Schnee von Dun Morogh.",kw={"bronzebart","die tiefenbahn","dun morogh","die große schmiede","high seat","eisenschmiede","khaz modan","magni bronzebart","tüftlerstadt"},ang={["faction:Alliance"]="Eisenschmiede ist durch Die Tiefenbahn mit Sturmwind verbunden. Sie bildet den nördlichen Anker der Allianz und zählt zu ihren zuverlässigsten Militärfestungen.",["profession:Blacksmithing"]="Die Große Schmiede gilt in ganz Azeroth als führendes Zentrum der Metallverarbeitung. Dort steht der Große Amboss, an dem Meisterschmiede und König Magni selbst Metall zu Legenden formen.",["race:Dwarf"]="Eisenschmiede ist die angestammte Heimat Eurer Sippe. Ihre Hallen ehren die Widerstandskraft Eures Volkes, seine Meisterschaft im Umgang mit Stein und die heilige Abstammungslinie, die bis zu den Titanen zurückreicht.",["race:Gnome"]="Seit der Katastrophe, die Gnomeregan verschlang, dient Tüftlerstadt Euch als vorübergehende Heimat und Command Center, während Hochtüftler Mekkadrill die Befreiung Eurer Stadt plant."},sec={{t="Eine Stadt aus Stein und Feuer",b="Vor fünfundzwanzig Jahrhunderten erwachten die ersten Zwerge in Uldaman. Sie zogen nach Westen in die zerklüfteten Gipfel von Dun Morogh und gruben sich in den höchsten Berg. Dort errichteten sie einen Schrein für ihren Schöpfer, den Titanen Khaz'goroth, und daneben Die Große Schmiede. Seitdem ist die Stadt in Ringen um diesen feurigen Herd nach außen gewachsen.\n\nKeine Stadt an der Oberfläche ist wie sie. Eisenschmiede liegt vollständig unter Stein und wird von tosenden Feuerstellen und Flüssen aus geschmolzenem Gestein gewärmt. Ihre befestigten Tore und tiefen Hallen haben Jahrhunderten des Krieges standgehalten."},{t="Der Krieg der drei Hämmer",b="Seit Generationen teilten sich drei Zwergenclans den Berg. Die Bronzebärte lebten neben den Wildhämmern und den Dunkeleisenzwergen. Als Hochkönig Modimus Ambossar starb, entbrannte ein erbitterter Bürgerkrieg um die Herrschaft über Eisenschmiede. Die Bronzebärte siegten und vertrieben ihre Rivalen.\n\nDann führte Zauberfürst Thaurissan die Dunkeleisenzwerge aus Rache zurück. Seine Belagerung reichte bis ins Herz Eisenschmiedes, ehe die Bronzebärte sie zurückschlugen. Im Süden beschwor Thaurissan dann durch ein Missgeschick Ragnaros den Feuerfürsten herauf. Das Erscheinen des Feuerfürsten zerschmetterte das Rotkammgebirge und besiegelte das Schicksal von Thaurissans eigenem Heer. Seitdem herrschen die Bronzebärte unangefochten über Eisenschmiede."},{t="Treue zur Allianz",b="Im Zweiten Krieg überrannte der Bleeding Hollow-Clan große Teile von Khaz Modan. Doch Eisenschmiede hielt hinter seinen versiegelten Toren stand, bis die Allianz von Lordaeron die Belagerung durchbrach. Aus Ehrenschuld schwor König Magni Bronzebart Eisenschmiede für immer der Allianz zu. Er hielt zu ihr, selbst als Gilneas und Quel'Thalas sich abwandten."},{t="Eine Zuflucht für Verbannte",b="Im Dritten Krieg trauerte Magni um seinen Bruder Muradin, der in Nordend verschollen war. Als Gnomeregan fiel, öffnete der König Tausenden von Gnomenflüchtlingen seine Tore. Unter Hochtüftler Gelbin Mekkadrill gruben sie die Tüftlerstadt in die steinerne Stadt. Nun verläuft auch Die Tiefenbahn unter der Erde direkt nach Sturmwind. So ist Eisenschmiede zu einem Knotenpunkt zwergischen Stahls und gnomischer Erfindung geworden."}},faq={{q="Wer herrscht über Eisenschmiede?",a="König Magni Bronzebart herrscht vom High Seat aus über Eisenschmiede und das Königreich Khaz Modan. Als geschickter Krieger und meisterhafter Schmied hat er sein Volk durch den Zweiten und den Dritten Krieg geführt und ist der Allianz tief ergeben. Eisenschmiede bleibt eine der standhaftesten Bastionen der Allianz.",al={"könig von eisenschmiede","herrscher von eisenschmiede","wer ist der zwergenkönig"}},{q="Warum leben so viele Gnome in Eisenschmiede?",a="Als die nahe gelegene gnomische Hauptstadt Gnomeregan durch einen plötzlichen Troggangriff und einen verheerenden Strahlenunfall fiel, flohen die überlebenden Gnome nach Dun Morogh. König Magni nahm sie in Eisenschmiede auf und überließ ihnen ein ganzes Stadtviertel, das heute Tüftlerstadt heißt.",al={"gnome in eisenschmiede","warum sind gnome hier","gnome in der tüftlerstadt"}},{q="Was ist Die Große Schmiede?",a="Die Große Schmiede ist das feurige industrielle Herz der Stadt. Unterirdische Wasserfälle aus geschmolzenem Magma speisen sie. Sie umgibt den Großen Amboss, an dem zwergische Waffenschmiede legendäre Waffen und Rüstungen fertigen.",al={"die große schmiede","amboss von eisenschmiede","zentrum von eisenschmiede"}},{q="Wie reist man zwischen Eisenschmiede und Sturmwind?",a="Die Tiefenbahn verbindet Eisenschmiede direkt mit Sturmwind. Diese außergewöhnliche unterirdische Eisenbahn wurde von gnomischer Ingenieurskunst erschaffen und führt geradewegs durch das Felsgestein der Östlichen Königreiche.",al={"eisenschmiede nach sturmwind","die tiefenbahn","zug nach sturmwind"}},{q="Ist Eisenschmiede jemals einer feindlichen Armee zum Opfer gefallen?",a="Eisenschmiede ist niemals an einen äußeren Feind gefallen. Kilrogg Totauge und sein Bleeding Hollow-Clan belagerten die Stadt während des Zweiten Krieges monatelang. Die Dunkeleisenzwerge drangen im Krieg der drei Hämmer in die Stadt ein, doch Tore und Verteidiger hielten stand.",al={"wurde eisenschmiede erobert","fiel eisenschmiede","belagerung von eisenschmiede"}},{q="Wohin zogen die anderen Zwergenclans?",a="Nach dem Krieg der drei Hämmer zog der besiegte Wildhammer-Clan nach Norden ins Sumpfland und ins Hinterland. Der feindselige Dunkeleisen-Clan ließ sich in Rotkammgebirge und Schwarzfels nieder und geriet unter die Herrschaft des Feuerfürsten.",al={"wo sind die wildhämmer","wo sind die dunkeleisenzwerge","die drei zwergenclans"}}},fx={["0779b12a"]={q="Was ist die Eisenschmiede?",a="Die Eisenschmiede ist die angestammte Hauptstadt der Zwerge und eine der ältesten Siedlungen auf Azeroth. Tief unter dem Stein des Berges Eisenschmiede im verschneiten Dun Morogh ausgehauen, steht sie als Herz des Zwergenkönigreichs Khaz Modan und als Grundpfeiler der Allianz. Es ist eine befestigte unterirdische Metropole, die in konzentrischen Ringen aus höhlenartigen Kammern, dröhnenden Schmieden und lebhaften Steinhallen angeordnet ist, in denen es von Handwerkern, Entdeckern und Soldaten wimmelt.",al={"übersicht stadt eisenschmiede","was für ein ort ist die eisenschmiede","über die eisenschmiede"}},["9f789b9e"]={q="Wer hat die Eisenschmiede im Berg erbaut?",a="Vor Tausenden von Jahren tauchten frühe Zwergenahnen aus den Titanenruinen von Uldaman auf und reisten nach Westen nach Dun Morogh. Sie entdeckten den höchsten Berg der Region, meißelten ihr Heim tief in das Grundgestein, errichteten einen Altar für den Titanen Khaz'goroth und entzündeten die Große Schmiede, um die herum die unterirdische Stadt wuchs.",al={"wer hat die eisenschmiede erbaut","wie wurde die eisenschmiede erschaffen","wer meißelte die eisenschmiede"}},["1ca57bea"]={q="Warum fließt Lava durch die Mitte der Eisenschmiede?",a="Die Stadt wurde absichtlich um natürliche unterirdische Ströme und Wasserfälle aus geschmolzenem Gestein herum gebaut. Die Zwergenmetallarbeiter nutzten diese unerschöpfliche geothermische Hitze, um die Große Schmiede anzutreiben und Gießereien, Schmelzöfen und Schmieden zu befeuern, die es den Rüstungs- und Waffenschmieden der Eisenschmiede ermöglichen, weltberühmte Waffen und Rüstungen herzustellen, ohne die Feuer jemals ausgehen zu lassen.",al={"warum gibt es lava in der eisenschmiede","lava in der großen schmiede","warum magma in der eisenschmiede"}},af5eaa17={q="Was ist im Laufe der Geschichte in der Eisenschmiede geschehen?",a="Lange nach ihrer Gründung brach ein Bürgerkrieg aus, als Großkönig Modimus Ambossar starb. Der Bronzebart-Clan vertrieb die rivalisierenden Wildhammer- und Dunkeleisenzwerge und verteidigte die Stadt anschließend gegen eine brutale Invasion der Dunkeleisenzwerge. Jahrhunderte später, während des Zweiten Krieges, belagerte die orcische Horde die Eisenschmiede, aber die Bergfestung hielt stand, bis die Allianz eintraf, um die Belagerung zu brechen. Heute bleibt sie eine ungebrochene Bastion.",al={"geschichte der eisenschmiede","geschichte von eisenschmiede","was ist in der geschichte der eisenschmiede passiert"}},["879099cb"]={q="Wer lebt in der Eisenschmiede?",a="Die Eisenschmiede ist vor allem die Heimat der Bronzebart-Zwerge, die Khaz Modan regieren. Der katastrophale Fall von Gnomeregan brachte jedoch eine große Bevölkerung von gnomischen Flüchtlingen in die Stadt, die ihren eigenen Distrikt in der Tüftlerstadt unter Großtüftler Gelbin Mekkadrill gründeten. Menschliche Botschafter, reisende Händler und Abenteurer der Allianz aller Art durchwandern regelmäßig ihre steinernen Straßen.",al={"wer lebt in der eisenschmiede","bevölkerung der eisenschmiede","völker in der eisenschmiede"}},["30458af2"]={q="Ist Eisenschmiede gefährlich?",a="Hinter ihren massiven, versiegelten Toren gilt Eisenschmiede als eine der sichersten und geschütztesten Bastionen der Welt. Wachen patrouillieren in jedem Ring und die Bergwände haben bisher jede belagernde Armee zurückgeschlagen. Unvorsichtige Besucher können jedoch in die sengend heißen Schlackegruben um Die Große Schmiede fallen, und zwielichtige Verschwörer lauern bekanntlich in den abgelegenen Ecken.",al={"ist eisenschmiede sicher","bedrohungen in eisenschmiede","ist es hier sicher"}},["44f103f9"]={q="Warum heißt die Stadt Eisenschmiede?",a="Die Stadt erhielt ihren Namen von Die Große Schmiede, dem kolossalen Herz der Industrie und des Handwerks, das zwergische Siedler erbauten, als sie erstmals in den Berggipfel vordrangen. Sowohl die umliegende Höhlenstadt als auch der Berg selbst wurden zu Ehren dieser gewaltigen, ewigen Gießerei benannt.",al={"herkunft des namens eisenschmiede","warum eisenschmiede","woher hat eisenschmiede seinen namen"}},["8722c25e"]={q="Wer hat in Eisenschmiede das Sagen?",a="König Magni Bronzebart, Thane von Eisenschmiede und Häuptling des Bronzebart-Clans, regiert das Königreich vom High Seat aus. Als erfahrener Kommandant des Zweiten und Dritten Krieges leitet Magni die Zwergennation und stimmt sich eng mit den Anführern der Allianz ab, um Khaz Modan und die umliegenden Regionen zu sichern.",al={"anführer von eisenschmiede","wer führt eisenschmiede an","wer hat das sagen"}},f1f3f31b={q="Ist König Magni ein guter König?",a="Magni wird von seinem Volk weithin als standhafter, mutiger und fähiger Monarch verehrt, der sein Königreich während der Belagerung durch die Horde und dem Ansturm der Geißel beschützt hat. Obwohl er persönlich mit dem Schmerz über seinen vermissten Bruder Muradin und Spannungen mit seiner Tochter Moira zu kämpfen hat, ist er ein engagierter Herrscher, der sich seinem Volk und seinen Verbündeten zutiefst verpflichtet fühlt.",al={"ist magni bronzebart ein guter könig","wie wird könig magni angesehen","ist magni beliebt"}},["48b1fbac"]={q="Ist König Magni Sturmwind unterstellt?",a="Nein. Eisenschmiede ist ein vollkommen souveränes Königreich. König Magni behandelt Sturmwind als gleichberechtigten und geschätzten Partner innerhalb der Allianz, verbunden durch uralte Ehre und gegenseitige Verteidigungspakte. Die Zwerge halfen nach dem Zweiten Krieg beim Wiederaufbau von Sturmwind, und Die Tiefenbahn verbindet ihre Hauptstädte, doch Magni ist nur seinem Thron im Berg verantwortlich.",al={"ist magni sturmwind unterstellt","untersteht eisenschmiede sturmwind","beziehung zwischen eisenschmiede und sturmwind"}},df9a6ce3={q="Warum gibt es ein Gnomviertel in Eisenschmiede?",a="Als die unterirdische Gnom-Hauptstadt Gnomeregan einer plötzlichen Trogg-Invasion und giftiger Verstrahlung zum Opfer fiel, führte Hochtüftler Gelbin Mekkadrill die Überlebenden nach Eisenschmiede. König Magni bot seinen langjährigen Nachbarn bedingungslose Zuflucht und stellte einen Bezirk bereit, der zur Tüftlerstadt wurde, um ihren Hof im Exil unterzubringen.",al={"warum leben gnome in eisenschmiede","warum gibt es tüftlerstadt hier","geschichte der gnome in eisenschmiede"}},cda22453={q="Planen die Gnome, Gnomeregan zurückzuerobern?",a="Ja. Tüftlerstadt dient Hochtüftler Mekkadrill und seinen Ingenieuren als Stützpunkt, während sie Pläne schmieden, erfinden und Maschinen bauen, um ihre verstrahlte Heimat zurückzuerobern. Gnomische Kommandos und Freiwillige der Allianz starten routinemäßig Angriffe in die Korridore der Stadt, um Troggs zu beseitigen und verräterische Bedrohungen auszuschalten.",al={"werden gnome gnomeregan zurückerobern","erobern gnome gnomeregan zurück","pläne zur rückeroberung von gnomeregan"}},c12e1e98={q="Wie bin ich in Eisenschmiede gelandet?",a="Wenn Ihr ein Zwerg oder ein Gnom seid, seid Ihr wahrscheinlich die großen Steinwälle von Dun Morogh hinaufmarschiert, nachdem Ihr Euch in Das Coldridgetal und Kharanos bewiesen habt, entsandt, um Euch bei der Führung der Stadt vorzustellen. Wenn Ihr von weiter her kommt, seid Ihr wahrscheinlich über Die Tiefenbahn direkt aus dem Herzen von Sturmwind angereist oder auf dem Rücken eines Greifen direkt in Die Große Schmiede geflogen, um zu handeln, zu studieren oder dem Ruf zu den Waffen von König Magni zu folgen.",al={"wie bin ich hierher gekommen","wie komme ich nach eisenschmiede","wie erreichte ich eisenschmiede"}},fb631935={q="Was soll ich in Eisenschmiede tun?",a="Eisenschmiede dient als pulsierendes Herz des Handels, der Ausbildung und der militärischen Planung für die Allianz in Khaz Modan. Hier könnt Ihr Euren Beruf an den lodernden Feuern von Die Große Schmiede meistern, eine fortgeschrittene Ausbildung für Eure Klasse suchen oder die Forscherliga in der Hall of Explorers konsultieren. Hochtüftler Mekkadrill koordiniert den Widerstand der Gnome von Tüftlerstadt aus, während König Magni Bronzebart die Verteidigung des Reiches gegen aufkommende Bedrohungen in den gesamten Östlichen Königreichen überwacht.",al={"was soll ich in eisenschmiede tun","warum bin ich hier","was ist mein ziel hier"}},f6bc736b={q="Was geschah mit Gnomeregan?",a="Bösartige unterirdische Primitive namens Troggs brachen aus tiefen Klüften nach Gnomeregan hervor. Verzweifelt darauf bedacht, die Eindringlinge auszumerzen, leiteten die Gnome radioaktiven Müll in die unteren Ebenen ab. Die Strahlung schaffte es nicht, die Troggs auszulöschen, sondern verstrahlte stattdessen die Stadt, machte viele Bürger krank und zwang die Überlebenden zur Flucht.",al={"was geschah in gnomeregan","fall von gnomeregan","warum fiel gnomeregan"}}},fp="9,312,24.539.0,28.652.0,21.321.0,18.389.0,20.300.0,42.268.0,24.194.0,50.210.0,43.250.0,35.236.0"}
P.entries["zone:lochmodan"] = {n="Loch Modan",s="Der große See von Loch Modan liegt oberhalb des Sumpflands und wird vom Steinwerkdamm zurückgehalten. Rund um Thelsamar bedrohen Troggs die südlichen Täler, Kobolde arbeiten in den Minen und Oger halten das nordöstliche Hochland.",h="Der große See von Loch Modan liegt oberhalb des Sumpflands und wird vom Steinwerkdamm zurückgehalten.",kw={"die weitschreiter-lodge","eisenband","festung mo'grosh","splitterstein","der steinwerkdamm","der loch","thelsamar","troggs","tal der könige"},ang={["class:Hunter"]="In der Weitschreiter-Lodge auf den südöstlichen Höhenzügen versammeln sich Fährtenleser, um Bären, Krokilisken und Bergbussarde zu jagen.",["faction:Alliance"]="Loch Modan bewacht die Route zwischen Dun Morogh und den nördlichen Wegen zum Sumpfland und trägt so zur Verteidigung des Gebiets von Eisenschmiede bei.",["profession:Mining"]="In den Hügeln, Steinbrüchen und von Troggs verseuchten Höhlen von Loch Modan liegen leicht zugängliche Kupfer-, Zinn- und Silberadern.",["race:Dwarf"]="Als Zwerg seht Ihr in Loch Modan unvergleichliche Steinmetzkunst und die gefährliche alte Geschichte, die Euer Volk unter dem Stein immer wieder freilegt."},sec={{t="Ein Juwel im Hochland",b="Der See von Loch Modan füllt ein grünes Tal östlich von Dun Morogh. Kiefern und Birken wachsen bis zu schroffen Gipfeln hinauf, und der Steinwerkdamm überspannt den nördlichen Rand. Die Zwergenstadt Thelsamar zieht Gebirgsjäger, Jäger und Bergleute an. Kupfer und Zinn durchziehen die umliegenden Hügel."},{t="Ausgegrabene Schrecken und Invasionen",b="Zerbrochene Katapulte und Ballisten auf dem Seegrund erinnern an den Zweiten Krieg. Damals besetzte die orkische Horde Loch Modan, bis die Zwerge sie vertrieben. In jüngerer Zeit öffneten Ausgrabungen der Zwerge unterirdische Kammern und setzten wilde Troggs frei. Ihre von Häuptlingen angeführten Stämme überrannten die südlichen Schluchten des Splittersteintals und des Tals der Könige. Die Gebirgsjäger von Eisenschmiede kämpfen, um die Handelswege zu verteidigen."},{t="Machenschaften im Schatten",b="Troggs und die Oger der Festung Mo'grosh bedrohen das Tal. Untersuchungen örtlicher Sabotage weisen auf die verräterischen Dunkeleisenzwerge hin, die durch die brennenden Pässe im Süden kamen. Dunkeleiseninfiltratoren haben es auf die Sprengpulvervorräte der Zwerge abgesehen und hegen Pläne gegen den Steinwerkdamm."}},faq={{q="Was hält den See davon ab, das Sumpfland zu überfluten?",a="Der Steinwerkdamm hält den gesamten Loch zurück. Zwergische Ingenieure warten ihn sorgfältig, denn ein Bruch würde die tiefer gelegenen Sümpfe des Sumpflands im Norden überschwemmen.",al={"was ist der damm","zweck des steinwerkdamms","warum hat loch modan einen damm"}},{q="Woher kamen all die Troggs?",a="Zwergische Entdecker und Bergleute brachen tief in den Bergen in unterirdische Kammern ein. Wilde Troggs strömten heraus, schwärmten an die Oberfläche und errichteten Lager in den Tälern.",al={"warum gibt es hier troggs","trogg-invasion in loch modan","ursprung der troggs"}},{q="Was ist die wichtigste Siedlung der Allianz in dieser Zone?",a="Thelsamar auf den westlichen Felsvorsprüngen ist die wichtigste Stadt der Allianz und ein Knotenpunkt für Reisende. Der Gasthof Zum Starkbier-Lager, die Händler und die Greifenmeister verbinden Reisende mit Eisenschmiede und weiter entfernten Orten.",al={"stadt in loch modan","knotenpunkt in loch modan","thelsamar"}},{q="Wer herrscht über die Festung Mo'grosh?",a="Massige Oger halten die Festung Mo'grosh in den nordöstlichen Bergen. Sie stiegen ins Tal hinab und errichteten einen befestigten Außenposten, der Jäger und Reisende in der Nähe terrorisiert.",al={"oger-lager in loch modan","oger im nordosten von loch modan","mogrosh"}},{q="Was geschah mit Eisenbands Ausgrabungsstätte?",a="Troggs, die aus unterirdischen Kammern hervorströmten, überrannten die archäologische Ausgrabungsstätte von Ausgrabungsleiter Eisenband. Das Team gab seine Arbeit auf und kämpfte darum, seine verbliebenen Vorräte zu sichern.",al={"eisenbands ausgrabung","warum wurde eisenbands stätte aufgegeben","problem mit ausgrabungsleiter eisenband"}},{q="Kann man von Loch Modan ins Ödland oder in die Sengende Schlucht reisen?",a="Ja. Fußwege führen durch die Berge nach Süden ins trockene Ödland. Der Steinwerkpass durch das Tal der Könige führt nach Südwesten zu den vulkanischen Felsen der Sengenden Schlucht.",al={"loch modan ins ödland","südlicher ausgang von loch modan","weg ins ödland"}}},fx={["0550e806"]={q="Wonach graben sie bei Ironband's Excavation?",a="Das Team von Ausgrabungsleiter Eisenband wurde entsandt, um antike Titanenartefakte auszugraben und vergessenes Zwergenerbe zu entdecken. Leider stießen sie bei ihren Grabungen auf von Troggs verseuchte Höhlen, was zu einem Überfall führte, der die Bergleute vertrieb und Eisenband dazu brachte, seine Aufmerksamkeit auf die antiken Ruinen von Uldaman zu richten.",al={"ziel der ausgrabung bei ironband","wonach graben sie bei ironband","ironband's excavation"}},c3dabc80={q="Was ist Dun Algaz und warum ist es gefährlich?",a="Dun Algaz ist der befestigte Gebirgspass, der Loch Modan mit dem Sumpfland im Norden verbindet. Er ist gefährlich, weil feindliche Streitkräfte, darunter Dragonmaw-Orcs und einheimische Briganten, den Pass ständig belagern und bekämpfen, was ein Durchqueren ohne Zwergenpatrouillen riskant macht.",al={"pass dun algaz","warum ist dun algaz gefährlich","pass zum sumpfland"}},["2a064472"]={q="Was befindet sich auf der anderen Seite von Dun Algaz?",a="Durch die gewundenen Tunnel von Dun Algaz gelangt man in das Sumpfland, einen riesigen, nebligen Sumpf, der sich bis zum Hafen von Menethil und den nördlichen Landen erstreckt.",al={"wohin führt dun algaz","was liegt nördlich von dun algaz","jenseits von dun algaz"}},["52ebefe5"]={q="Wie bin ich in Loch Modan gelandet?",a="Wenn Ihr ein Zwerg oder Gnom seid, hat Euch Euer Weg wahrscheinlich aus den verschneiten Felsklippen von Dun Morogh nach Osten geführt, durch die bewachten Tunnel des Nordtorpasses oder Südtorpasses. Reisende von weiter her, einschließlich Menschen und Nachtelfen, die aus Sturmwind über die Tiefenbahn nach Eisenschmiede kommen, nutzen dieselbe Bergstraße hinunter in dieses gemäßigte Tal oder fliegen direkt zur Siedlung Thelsamar.",al={"wie bin ich hierhergekommen","wie habe ich loch modan erreicht","reise nach loch modan"}},["13e88a97"]={q="Was soll ich in Loch Modan tun?",a="Die Verteidiger von Loch Modan sind unterbesetzt und brauchen dringend Eure Hilfe. Feindliche Troggs, die durch die Bergbauoperationen der Zwerge ausgegraben wurden, bedrohen die Siedlungen, während grausame Mo'grosh-Oger den Nordosten beherrschen. In Thelsamar und dem Tal der Könige suchen Hauptmann Rugelfuß und lokale Gebirgsjäger nach Rekruten, um die Trogg-Einfälle zurückzuschlagen, die belagerte archäologische Ausgrabung von Ausgrabungsleiter Eisenband zu unterstützen und den lebenswichtigen Steinwerkdamm vor drohender Sabotage zu schützen.",al={"warum bin ich hier","was soll ich in loch modan tun","was ist meine mission hier"}},["2ab9b343"]={q="Was ist Loch Modan?",a="Loch Modan ist ein gemäßigtes Tal im östlichen Khaz Modan, das östlich von Dun Morogh und südlich vom Sumpfland liegt. Umgeben von schroffen Bergen und lichten Kiefernwäldern ist sein prägendes Merkmal das gewaltige Süßwasser-Loch, das von Der Steinwerkdamm zurückgehalten wird. Es dient als integraler Bestandteil des zwergischen Königreichs Eisenschmiede.",al={"gebiet loch modan","über loch modan","was ist das für ein ort"}},["4c6debd3"]={q="Was ist in Loch Modan passiert?",a="Während des Zweiten Krieges stürmte die Horde in Loch Modan und befestigte Positionen im gesamten Tal gegen die Allianz. Die Verteidiger von Eisenschmiede kämpften einen brutalen Feldzug, um ihr Land zu befreien. Während die Zwerge die Region zurückeroberten, bleiben zerstörte Katapulte und Ballisten, die auf dem Seegrund und auf Inseln ruhen, als Überbleibsel dieses Krieges zurück.",al={"geschichte von loch modan","vergangene schlachten in loch modan","zweiter krieg loch modan"}},["11acca40"]={q="Ist Loch Modan gefährlich?",a="Hinter seiner ruhigen alpinen Erscheinung steht Loch Modan vor zahlreichen Krisen. Bösartige Troggs, die durch kürzliche Grabungen freigelegt wurden, überrennen die Hügel und Minen, Mo'grosh-Oger besetzen den Nordosten, Kobolde plagen die Straßen und Infiltratoren des Dunkeleisenclans sabotieren aktiv die Zwergenpositionen rund um Der Steinwerkdamm.",al={"gefahren in loch modan","ist loch modan sicher","bedrohungen in loch modan"}},["85c52931"]={q="Wer lebt hier?",a="Das Tal ist die Heimat von Zwergen aus Eisenschmiede und Gnomen, konzentriert um die Siedlung Thelsamar, sowie Jägern und Fährtenlesern in Die Weitschreiter-Lodge. Aggressive Troggs, Kobolde, Saboteure des Dunkeleisenclans und die Mo'grosh-Oger bestreiten jedoch heftig die Kontrolle der Zwerge über die Wildnis.",al={"wer lebt in loch modan","bewohner von loch modan","wer wohnt hier"}},["0925f1bd"]={q="Gehört dies zum Zwergenkönigreich?",a="Ja. Loch Modan ist eine wesentliche östliche Provinz des Königreichs Eisenschmiede, die unter der Autorität von König Magni Bronzebart regiert und von den Bergsteigern von Eisenschmiede verteidigt wird.",al={"ist loch modan teil von eisenschmiede","regiert eisenschmiede loch modan","zwergenkönigreich loch modan"}},["90a2b33d"]={q="War der See schon immer so groß?",a="Nein. Das Loch war einst viel kleiner. Als der Meisterarchitekt Franclorn Forgewright Der Steinwerkdamm entwarf und errichtete, staute das massive Bauwerk den Abfluss aus den Bergen von Khaz Modan und verdoppelte damit mehr als die ursprüngliche Größe des Gewässers.",al={"wie groß war loch modan","ursprüngliche größe des lochs","hat der damm den see vergrößert"}},ef90b12a={q="Wer hat hier das Sagen?",a="Die Region untersteht direkt König Magni Bronzebart in Eisenschmiede. Vor Ort wird die zivile Verwaltung in Thelsamar von Magistrat Bluntnose beaufsichtigt, militärische Garnisonen folgen Offizieren wie Hauptmann Rugelfuß, und die Verteidigung des lebenswichtigen Der Steinwerkdamm fällt unter Chefingenieur Hinderweir VII.",al={"wer führt loch modan an","führung von loch modan","wer regiert dieses land"}},["0cf9ab54"]={q="Was ist Thelsamar?",a="Thelsamar ist die wichtigste Zwergensiedlung in Loch Modan, die entlang der westlichen Klippen liegt. Sie beherbergt den Gasthof Zum Starkbier-Lager, Handwerker, Greifenmeister und die örtliche Verwaltung und dient als Stützpunkt zwischen Eisenschmiede, dem Sumpfland und den östlichen Grenzgebieten.",al={"dorf thelsamar","stadt thelsamar","über thelsamar"}},["9c1680d8"]={q="Was sind Troggs und woher kommen sie?",a="Troggs sind wilde, unterirdische Humanoide, die versehentlich durch archäologische und bergbauliche Ausgrabungen der Zwerge unter den Gipfeln von Khaz Modan freigesetzt wurden. Sobald sie erwacht waren, schwärmten sie in die Täler hinauf, bauten primitive Lager und griffen Reisende an.",al={"woher kommen troggs","was ist ein trogg","ursprung der troggs"}},["15b5e85c"]={q="Was machen die Dunkeleisenzwerge am Damm?",a="Saboteure des Dunkeleisenclans sind mit Sprengstoff in Der Steinwerkdamm eingedrungen und versuchen, das Kronjuwel von Eisenschmiede zu untergraben. Ihre Pläne drohen, den Damm zu zerstören und die Region zu verwüsten, was Chefingenieur Hinderweir VII dazu zwingt, Hilfe anzuheuern, um sie auszurotten.",al={"dunkeleisenzwerge am damm","warum sind dunkeleisenzwerge am steinwerkdamm","bedrohung durch dunkeleisenzwerge in loch modan"}}},fp="10,205,16.273.0,31.409.0,20.301.1,52.164.0,35.171.0,52.170.0,30.171.0,44.163.0,64.175.0"}
P.entries["zone:moonglade"] = {n="Mondlichtung",s="In der Mondlichtung versammeln sich Druiden des Zirkels des Cenarius unter einer endlosen Dämmerung. Das Tal im Norden Kalimdors ist Zuflucht für nachtelfische und taurische Druiden, während Reisende zu Fuß die Holzschlundfeste durchqueren müssen, um es zu erreichen.",h="In der Mondlichtung versammeln sich Druiden des Zirkels des Cenarius unter einer endlosen Dämmerung.",kw={"zirkel des cenarius","dendrite sternenschauer","smaragdgrüner traum","see von elune'ara","mondlichtung","nachthafen","remulos","sturmgrimms grabhügel"},ang={["class:Druid"]="Als Druide ist die Mondlichtung Euer heiliges Zuhause und Zufluchtsort. Eure spirituelle Bindung ermöglicht es Euch, Euch von überall in Azeroth hierher zu teleportieren, Meister wie Dendrite Sternenschauer zu befragen, mit großen Geistern Zwiesprache zu halten und Formen wie die Aquatic Form zu meistern.",["race:NightElf"]="Als Nachtelf war die Mondlichtung zehntausend Jahre lang das spirituelle Herzland Eures Volkes und die Ruhestätte Eurer schlafenden Erzdrui­den. Elunes anhaltender Segen beschützte sie.",["race:Tauren"]="Als Tauren erneuert Euer Platz im Zirkel des Cenarius ein uraltes Band zu Cenarius. Hamuul Runetotem setzte sich für Eure Aufnahme ein, die die Mondlichtung ehrt, obwohl sich die Nachtelfen lange abgeschottet hielten."},sec={{t="Heilige Dämmerung",b="Die Mondlichtung liegt zwischen den Bergen nördlich des Teufelswalds und Winterquells. Unter Elunes Mondschein hält die Dämmerung über dem See von Elune'ara an, im Herzen eines Tals, das seit den Anfängen der kaldoreiischen Zivilisation heilig ist. Die Brennende Legion ließ die Lichtung bei ihren uralten Invasionen und im jüngsten Dritten Krieg unberührt, aufgehalten von Cenarius und seinen Nachkommen. Hüter Remulos wacht nun über die Mondlichtung und bewahrt das Gleichgewicht der Natur in einem Zufluchtsort, an dem Fraktionskonflikte keinen Platz haben."},{t="Sitz des Zirkels",b="Malfurion Sturmgrimm gründete den Zirkel des Cenarius vor Jahrtausenden, und die Mondlichtung ist bis heute sein Hauptsitz. In Nachthafen am See lernen Druiden uralte Traditionen kennen. Nach dem Dritten Krieg nahm der Zirkel Tauren in seine Reihen auf und folgte den Lehren des Erzdrui­den Hamuul Runetotem. Hier treten die Loyalitäten zur Allianz und zur Horde in den Hintergrund. Bewaffnete Wächter wahren den Frieden, und Mitglieder, die zu Gewalt greifen, werden rasch zur Rechenschaft gezogen."},{t="Die Grabhügel und der Traum",b="Südlich des Sees von Elune'ara liegen die Sturmgrimms Grabhügel. Tausende von Jahren schliefen elfische Druiden in diesen unterirdischen Höhlen, während ihre Geister den Smaragdgrünen Traum durchstreiften. Ihre Körper ruhten unter ständiger Bewachung. Während des Dritten Krieges blies Tyrande Wisperwind hier das Horn des Cenarius und erweckte Malfurion.\n\nDie Grabhügel sind weiterhin mit dem Traum verbunden. Doch nun steigen seltsame Wellen aus ihren tiefen Tunneln auf, und dunkle Flüsterstimmen beunruhigen das smaragdgrüne Reich."}},faq={{q="Wie erreichen Reisende, die keine Druiden sind, die Mondlichtung?",a="Zu Fuß durchquert Ihr die Holzschlundfeste, ein Tunnelnetz, das den oberen Teufelswald, Winterquell und die Mondlichtung verbindet, sofern Euch bei saisonalen Ereignissen keine Ritualmagie dorthin bringt. Die Holzschlund-Furbolgs bewachen den Durchgang streng, und Fremde müssen ihren guten Willen beweisen, um sicher hindurchzukommen.",al={"wie gelangt man zur mondlichtung","zur mondlichtung gelangen","eingang zur mondlichtung"}},{q="Warum können Horde und Allianz hier friedlich nebeneinander wandeln?",a="Der Zirkel des Cenarius regiert die Mondlichtung und dient der Natur statt der Politik. Die Wächter der Mondlichtung in ganz Nachthafen greifen jeden an, der Gewalt gegen jemanden beginnt, der beim Zirkel in gutem Ansehen steht.",al={"warum ist die mondlichtung neutral","pvp in der mondlichtung","können horde und allianz hier kämpfen"}},{q="Welchen Zweck erfüllt Nachthafen?",a="Nachthafen ist die Hauptsiedlung der Mondlichtung, in der der Zirkel des Cenarius lebt und wirkt. Ausbilder, Pfleger und Heiligtümer bieten kaldoreiischen und taurischen Druiden Orte, um sich über den Zustand der wilden Länder Azeroths auszutauschen.",al={"zweck von nachthafen","was ist nachthafen","ort in der mondlichtung"}},{q="Wer führt die Mondlichtung, wenn Malfurion Sturmgrimm abwesend ist?",a="Hüter Remulos wacht vom Schrein von Remulos über die Mondlichtung, solange Malfurion Sturmgrimm abwesend ist. Zusammen mit erfahrenen Mitgliedern des Zirkels wie Dendrite Sternenschauer pflegt er die heiligen Lande und leitet die Bemühungen, die Welt zu heilen.",al={"anführer der mondlichtung","wer führt den zirkel des cenarius","wer ist remulos"}},{q="Was ruht unter den Sturmgrimms Grabhügeln?",a="Die Sturmgrimms Grabhügel sind tiefe Kammern, in denen Druiden eine lange Zwiesprache mit dem Smaragdgrünen Traum hielten. Ihre tiefen Flügel bewahren weiterhin mächtige Verbindungen zum Traum, doch jüngste Störungen lassen darauf schließen, dass beunruhigende Albträume darin erwachen.",al={"lore der grabhügel","zweck der sturmgrimms grabhügel","wo schlafen die druide"}},{q="Warum haben Druiden besondere Flugrouten von Nachthafen aus?",a="Silva Fil'naveth, die Hippogryphenmeisterin, und Bunthen Plainswind, der Wind Rider-Hüter, bieten Druiden direkte Flüge von Nachthafen nach Rut'theran und Donnerfels an. Diese Routen helfen dem Orden, zwischen seinem heiligen Hain und den Heimatlanden seiner Völker zu reisen.",al={"flugmeister von nachthafen","druiden-flugmeister in der mondlichtung","kostenlose flüge in der mondlichtung"}}},fp="9,207,15.457.0,18.412.0,29.447.1,43.274.0,57.197.0,34.215.0,53.223.0,45.241.0,58.258.0"}
P.entries["zone:mulgore"] = {n="Mulgore",s="Unter dem Steinkrallengebirge liegt Mulgore, die grüne, geschützte Heimat der Tauren. Zwischen hohen Hochebenen breiten sich Grasland und Die wogenden Ebenen aus, umringt von hohen Bergwänden. Mulgore ist das Herz der vereinten Stämme, die von Donnerfels aus über das Land wachen.",h="Unter dem Steinkrallengebirge liegt Mulgore, die grüne, geschützte Heimat der Tauren.",kw={"bael'dun","baine bluthuf","dorf der bluthufe","cairne bluthuf","camp narache","erdenmutter","kodo","mulgore","die hochwolkenebene","teufelsfelsen","donnerfels","venture company"},ang={["class:Druid"]="Mulgores wogende Ebenen und unberührte Haine zählen zu den reinsten Naturschutzgebieten Kalimdors. Hier studieren Taurendruiden das Gleichgewicht und die Gaben der Natur.",["class:Hunter"]="Auf Mulgores Ebenen gedeiht die Große Jagd. Pumas, Wölfe und wilde Kodos stellen Euer Geschick und Eure Geduld als Fährtenleser auf die Probe.",["faction:Horde"]="Mulgore ist das Herz der Spiritualität und Landwirtschaft der Horde im Zentrum Kalimdors. Ein Blutschwur gegenseitiger Verteidigung verbindet das Land mit Thralls Volk.",["race:Tauren"]="Dieses Tal ist Eure angestammte Heimat, durch Opfer und Einigkeit zurückerobert. Im Dienst der Erdenmutter müsst Ihr seine Quellen bewahren und seine heiligen Stätten reinigen."},sec={{t="Ein Land zurückerobert",b="Über Generationen lebten die Tauren als Nomaden und wurden von Zentauren-Kriegsbanden über die Ebenen gejagt. Ihr Schicksal wendete sich, als Oberhäuptling Cairne Bluthuf Thrall und dessen Orcs traf. Sie teilten Ideale von Ehre, Schamanismus und Stärke, und so schlossen sich die Tauren der jungen Horde an. Mit der Hilfe der Orcs brach Cairne die Vorherrschaft der Zentauren und führte sein Volk nach Mulgore. Hier errichteten sie zum ersten Mal seit Jahrhunderten dauerhafte Heimstätten und krönten die nördlichen Mesas mit ihrer Hauptstadt."},{t="Die Prüfungen der Erdenmutter",b="Um in Mulgore erwachsen zu werden, müssen junge Tauren dem Ruf der Großen Jagd folgen und die Erdenmutter ehren. Ihre Ausbildung beginnt in Camp Narache unter Häuptling Falkenwind. Von dort steigen sie hinab ins Dorf der Bluthufe und nehmen die Rites of the Earthmother auf sich. Sie lernen, mit den Geistern der Ahnen zu sprechen und einheimische Kräuter zu sammeln. Außerdem lernen sie, die Herden von Kodos und Schreiteern zu achten, die ihr Volk ernähren."},{t="Bedrohungen ringsum",b="Trotz seiner Ruhe ist Mulgore von allen Seiten bedroht. Vertriebene Stacheleber haben sich in der Dornrankenklamm verschanzt und die heiligen Grabstätten der Teufelsfelsen geschändet. In den Bergen fallen Windfurienharpyien über das Wild her, und Bleichmähnen-Gnolle schlagen aus verborgenen Höhlen zu.\n\nAuch Fremde sind gekommen, um aus dem Land Gewinn zu schlagen. Die Goblins der Venture Company verschmutzen die heiligen Quellen und brechen im Osten Stein. Zwergenforscher aus Bael Modan haben die Grabungsstätte von Bael'dun eröffnet. Dort graben sie trotz des Protests der Tauren nach uralten Titanenrelikten."}},faq={{q="Warum haben sich die Tauren dauerhaft in Mulgore niedergelassen?",a="Die Tauren ließen sich dauerhaft in Mulgore nieder, nachdem sie sich mit Thralls Horde verbündet hatten. Zentaurenmarodeure hatten das Nomadenvolk lange durch Kalimdor gejagt. Doch Cairne Bluthuf gewann die Kraft, sie zu vertreiben und das angestammte Tal zurückzuerobern. Die Tauren errichteten dauerhafte Siedlungen, darunter das Dorf der Bluthufe und Donnerfels. So erhielten alle Stämme eine gemeinsame Heimat, in der sie in Frieden gedeihen konnten.",al={"warum leben tauren hier","geschichte der taurenheimat","warum donnerfels besiedeln"}},{q="Wie verlasst Ihr Mulgore zu Fuß?",a="Ihr könnt Mulgore zu Fuß durch den einzigen Pass in der südöstlichen Bergwand verlassen. Folgt der Hauptstraße nach Osten, vorbei am Dorf der Bluthufe und Morin Wolkenpirschers Außenposten, durch den Gebirgskorridor und hinein in die trockenen Ebenen des Brachlands.",al={"ausgang aus mulgore","wie kommt man von mulgore ins brachland","straße aus mulgore"}},{q="Wer ist die Venture Company und warum ist sie hier?",a="Die Venture Company ist ein von Goblins geführtes Handelskartell, das nach den Naturschätzen Kalimdors strebt. In Mulgore baut sie in den östlichen Bergen Erz ab und hat die wichtigen Wasserbrunnen Donnerhorn, Wildmähne und Winterhuf besetzt. Damit entweiht sie das Land und bedroht die Wasserversorgung der Region.",al={"venture company in mulgore","warum sind goblins hier","mine der venture company"}},{q="Warum graben Zwerge im Gebiet der Tauren?",a="Zwerge der Expedition Bael Modan graben in der Grabungsstätte von Bael'dun in Mulgores westlichen Ausläufern. Die Forscherliga schickte sie, um Relikte ihrer Titanenschöpfer auszugraben. Sie graben ohne Erlaubnis auf Taurenland, obwohl die Tauren protestieren, dass ihre Arbeit die Erdenmutter verletzt.",al={"grabungsstätte von baeldun","warum sind zwerge in mulgore","bael dun"}},{q="Was sind die Rites of the Earthmother?",a="Die Rites of the Earthmother sind heilige Prüfungen, denen sich junge Tauren beim Eintritt ins Erwachsenenalter unterziehen. Dabei beweisen sie ihre Hingabe an das Land und die Traditionen ihrer Ahnen. Die Prüfungen verlangen Jagdgeschick, Fährtenlesen, die Zwiesprache mit Visionen und Wissen um das Gleichgewicht der Natur. Sie finden im Dorf der Bluthufe und auf den Goldenen Ebenen statt.",al={"rites of the earthmother","prüfung zum erwachsenwerden der tauren","rite of the earthmother"}},{q="Wer herrscht über Mulgore?",a="Oberhäuptling Cairne Bluthuf herrscht von Donnerfels auf den nördlichen Mesas aus über alle Lande der Tauren. Sein Sohn Baine Bluthuf regiert das Dorf der Bluthufe und kümmert sich unter Cairnes weiser Führung um die täglichen Belange der unteren Ebenen.",al={"führer von mulgore","wer ist der häuptling von mulgore","cairne bluthuf anführer"}}},fx={["145a41be"]={q="Was ist Mulgore?",a="Mulgore ist die grüne, geschützte angestammte Heimat der Tauren, eingebettet in einen Ring aus schützenden Bergen im zentralen Kalimdor. Seine sanften goldenen Graslandschaften und hoch aufragenden, windgepeitschten Plateaus bieten erstklassige Jagdgründe und einen friedlichen Zufluchtsort, der zu Fuß nur durch einen einzigen Gebirgspass im Osten zugänglich ist, der in das Brachland führt.",al={"was ist das für ein gebiet","erzähle mir von mulgore","überblick mulgore"}},bf98c20a={q="Ist Mulgore gefährlich?",a="Obwohl Mulgore weitaus friedlicher ist als das Brachland, steht es vor wachsenden Problemen. Aggressive Borstennacken-Stacheleber dringen in heilige Gebiete ein, Bleichmähnen-Gnolle lauern in südlichen Höhlen und Windfurien-Harpyien nisten entlang der Bergrücken. Darüber hinaus beutet die Venture Company unberührte Wasserquellen und Berghänge aus, während Zwergenausgräber im Westen angestammtes Land entweihen.",al={"ist mulgore sicher","bedrohungen in mulgore","gefahr hier"}},["148e56bf"]={q="Wer sind die Tauren und wie sind sie in Mulgore gelandet?",a="Die Tauren, oder Shu'halo, sind ein altes, nomadisches Volk, das der Erdenmutter ergeben ist. Über Generationen hinweg wanderten sie durch das Brachland, unaufhörlich gejagt und bis an den Rand der Ausrottung getrieben von marodierenden Zentaurenstämmen. Nachdem sie während des Dritten Krieges ein Band der Ehre mit Thrall und den neu angekommenen Orcs geschmiedet hatten, führte Häuptling Cairne Bluthuf sein vereintes Volk zurück in ihr angestammtes Tal von Mulgore, um ein dauerhaftes Zuhause zu beanspruchen.",al={"woher kamen die tauren","geschichte der tauren in mulgore","wie kamen die tauren hierher"}},["24d564cd"]={q="Was ist das Dorf der Bluthufe?",a="Das Dorf der Bluthufe ist eine bedeutende Siedlung am klaren Wasser des Stonebullsees im zentralen Mulgore. Benannt zu Ehren von Cairnes Stamm und regiert von seinem Sohn Baine, dient sie als primärer Handels-, Handwerks- und Sammelpunkt, wo sich junge Jäger und Krieger nach ihrer Reise von der Hochwolkenebene versammeln.",al={"lore zu bloodhoof","was ist bloodhoof","dorf in mulgore"}},dbff83eb={q="Was ist Donnerfels?",a="Donnerfels ist die prächtige Hauptstadt der Taurennation, die hoch oben auf einer Reihe von windgepeitschten, verteidigbaren Plateaus über dem nördlichen Mulgore errichtet wurde. Gegründet von Cairne Bluthuf nach dem Dritten Krieg, bieten ihre erhöhten Plateaus und Seilbrücken Tauren aller Stämme Schutz und eine sichere Bastion gegen Zentauren-Invasoren.",al={"lore zu donnerfels","tauren-hauptstadt","stadt auf den plateaus"}},["69b40be7"]={q="Was machen die Bleichmähnen-Gnolle in Mulgore?",a="Der Bleichmähnenstamm der Gnolle hat sich Höhlen um den Bleichmähnenfels gegraben und Lager entlang der südlichen Berge von Mulgore verstreut. Während die Philosophie der Tauren das Teilen der Gaben der Erdenmutter schätzt, belästigen diese aggressiven Gnolle Reisende, überfallen nahe gelegene Jagdgründe und greifen jeden Krieger an, der in die Nähe ihres Territoriums kommt.",al={"bleichmähnen-gnolle in mulgore","warum sind gnolle hier","bleichmähnenfels"}},["7f5f34f0"]={q="Wie bin ich in Mulgore gelandet?",a="Wenn Ihr ein Taure seid, seid Ihr hier unter den nomadischen Stämmen aufgewachsen, die kürzlich unter Häuptling Cairne Bluthuf vereint wurden. Nach dem Dritten Krieg siedelte sich Euer Volk auf diesen grünen angestammten Ebenen an, um den Zentauren zu entkommen und eine dauerhafte Heimat aufzubauen, beginnend mit Eurem Training auf dem südlichen Plateau der Hochwolkenebene. Reisende anderer Völker kommen durch den einsamen, befestigten Gebirgspass vom östlichen Brachland oder per Wyvernflug direkt zur ausgedehnten Plateaustadt Donnerfels.",al={"wie bin ich hierhergekommen","warum bin ich in mulgore","wie bin ich nach mulgore gekommen"}},a8ac99e7={q="Was soll ich in Mulgore tun?",a="Junge Tauren müssen die Rites of the Earthmother bestehen, um ihren Wert zu beweisen, angestammte Traditionen zu ehren und die Wege des Landes zu lernen. Über Eure Riten hinaus steht Mulgore vor drohenden Gefahren, die seinen Frieden bedrohen: Aggressive Borstennacken-Stacheleber schwärmen durch die östlichen Schluchten, Bleichmähnen-Gnolle lauern in den Hügeln und die von Goblins geführte Venture Company entweiht heilige Wasserquellen und reißt für Erz in die Berge. Ob Ihr nun dem Ruf von Häuptling Falkenwind folgt oder Baine Bluthuf im Dorf der Bluthufe unterstützt, Eure Pflicht ist es, die Stämme zu schützen und die neue Heimat zu verteidigen.",al={"was mache ich hier","was sollte ich hier tun","was ist mein ziel in mulgore"}},dd86ecd9={q="Wer ist Cairne Bluthuf?",a="Cairne Bluthuf ist der ehrwürdige High Chieftain der vereinten Taurenstämme, Anführer der Bloodhoof und Herrscher über Donnerfels. Als unvergleichlicher Krieger und weiser Ältester verbündete Cairne sein Volk mit Thralls Horde und führte es durch gefährliche Kriege gegen die Zentauren, um auf den Tafelbergen eine dauerhafte Zuflucht zu gründen.",al={"cairne bluthuf hintergrundgeschichte","wer ist der high chieftain","tauren anführer"}},["96a44cf3"]={q="Ist Baine sein Sohn?",a="Ja, Baine Bluthuf ist Cairnes Sohn. Baine ist für seinen Mut im Kampf und seine diplomatische Zurückhaltung bekannt und führt als Häuptling das Dorf der Bluthufe im Herzen Mulg ores, während sein Vater ihn darauf vorbereitet, eines Tages das Amt des Oberhäuptlings zu übernehmen.",al={"ist baine cairnes sohn","baine bluthuf verwandtschaft","baine bluthuf"}}},fp="7,276,16.464.0,29.422.0,19.560.0,49.395.0,33.247.0,50.273.0,44.275.0,38.319.0,18.219.0"}
P.entries["zone:orgrimmar"] = {n="Orgrimmar",s="Aus den roten Schluchten im Norden Durotars erhebt sich Orgrimmar, die Festung der Orcs. Die Stadt ist das Herz von The New Horde. Trolle, Tauren und Verbündete der Verlassenen haben Schutz hinter ihren Mauern gefunden.",h="Aus den roten Schluchten im Norden Durotars erhebt sich Orgrimmar, die Festung der Orcs.",kw={"die kluft der schatten","the drag","durotar","grommash hold","orgrim schicksalshammer","orgrimmar","der flammenschlund","thrall","tal der geister","tal der stärke","tal der weisheit","kriegshäuptling"},ang={["class:Shaman"]="Als Schamane folgt Ihr Thralls Wiederbelebung des Schamanismus im Herzen der Horde-Führung. Im friedvollen Tal der Weisheit studieren die Schamanen die Elemente und stehen mit den Geistern der Ahnen in Verbindung.",["class:Warlock"]="Als Hexenmeister findet Ihr in der Kluft der Schatten einen unsicheren Zufluchtsort. Thrall behält Euch im Auge, während Ihr abgeschieden von öffentlicher Verurteilung Eure dunklen Künste verfeinert.",["faction:Horde"]="Als Champion der Horde findet Ihr Waffenmeister, Klassenmentoren und Handelsplätze in ihrem militärischen und kulturellen Zentrum. Auch Kriegshäuptling Thrall empfängt hier Besucher.",["race:Orc"]="Als Orc seht Ihr in Orgrimmar die hart erkämpfte Freiheit von dämonischer Trägheit und Internierung. Zugleich ist die Stadt die stolze Ahnenfestung Eures Volkes auf dem Boden Durotars.",["race:Troll"]="Als Dunkelspeertroll habt Ihr nach dem Verlust der Darkspear Isles an der Seite der Orcs dauerhafte Zuflucht gefunden. Das Tal der Geister ist Eure sichere spirituelle Heimat."},sec={{t="Ein aus Stein gehauenes Zuhause",b="Die Orcs kamen hierher, um eine Heimat zu finden. Nach dem Dritten Krieg führte Kriegshäuptling Thrall sie an die trockenen Küsten Kalimdors. Dort sollten sie endlich frei sein von dämonischer Verderbnis und menschlichen Ketten. Er nannte das Land nach seinem Vater Durotar. Die Stadt benannte er nach Orgrim Schicksalshammer, seinem gefallenen Mentor.\n\nDie Festung wurde mit Blut und Schweiß errichtet. Tauren standen an der Seite der Orcs, ebenso Dunkelspeertrolle und Gobliningenieure. Auch der Champion Rexxar kämpfte an ihrer Seite. Gemeinsam schlugen sie Zentauren, Harpyien und die wilden Donnerechsen der Schluchten zurück."},{t="Täler der Horde",b="Zerklüftete Berge umringen die Stadt. Sie halten sowohl fremde Feinde als auch Durotars schneidende Winde fern. Im Inneren öffnet sich der Fels zu Höhlen, und jedes Tal erfüllt eine eigene Aufgabe im Leben der Horde.\n\nIm Tal der Stärke steht das Torhaus. Von dort führt eine Straße tiefer hinein zum Markt von The Drag. Taurendruiden und Schamanen versammeln sich an den Teichen im Tal der Weisheit. Im Tal der Geister leben die Schattenjäger und Hexendoktoren der Dunkelspeere zwischen ihren Stelzenpavillons."},{t="Schatten im roten Fels",b="Unter dem Tal der Ehre und den Höhen von Grommash Hold regt sich ein anderes Leben unter Orgrimmar. Hexenmeister und Schurken üben in der Höhle namens Kluft der Schatten. Thrall behält sie genau im Auge und duldet ihre Künste nur widerwillig. Noch tiefer windet sich Der Flammenschlund durch vulkanische Tunnel unter dem Schluchtboden. Finsterer Kultisten und unterirdische Bestien wüten dort und bedrohen die Festung aus ihren eigenen Fundamenten heraus."}},faq={{q="Wer herrscht über Orgrimmar?",a="Kriegshäuptling Thrall herrscht von Grommash Hold aus über Orgrimmar. An seiner Seite führen Dunkelspeerhäuptling Vol'jin und der erfahrene Kommandant Varok Saurfang The New Horde. Dabei hat Thrall Ehre, Überleben und das schamanistische Erbe im Sinn.",al={"anführer von orgrimmar","wer herrscht über orgrimmar","aktueller kriegshäuptling"}},{q="Warum heißt die Stadt Orgrimmar?",a="Thrall benannte Orgrimmar nach Orgrim Schicksalshammer, dem legendären früheren Kriegshäuptling. Orgrim brach den Einfluss des Shadow Council auf die Old Horde und übergab Thrall vor seinem Tod im Kampf seine Kriegsrüstung und den Doomhammer.",al={"ursprung des namens orgrimmar","nach wem ist orgrimmar benannt"}},{q="Wer lebt außer Orcs in Orgrimmar?",a="Orgrimmar ist die Heimat des Dunkelspeerstamms, dessen Mitglieder im Tal der Geister leben. In der Stadt sind außerdem Taurenbotschafter im Tal der Weisheit willkommen. Auch eine Gruppe von Abgesandten der Verlassenen ist in der Stadt vertreten, nachdem sie sich vor Kurzem der Horde angeschlossen haben.",al={"völker in orgrimmar","wer lebt hier","trolle in orgrimmar"}},{q="Was ist die Kluft der Schatten?",a="Die Kluft der Schatten ist ein düsterer Felsspalt unter den Schluchtenhängen, abseits von The Drag. Die Schurken- und Hexenmeistergilden der Stadt haben dort ihr Zuhause. So bleiben illegaler Handel und gefährliche dämonische Beschwörungen vor den Wohnvierteln verborgen.",al={"die kluft der schatten","unterirdisches orgrimmar","hexenmeisterviertel von orgrimmar"}},{q="Welche Gefahren gibt es in der Stadt?",a="Der Flammenschlund liegt direkt unter der Kluft der Schatten. In seinen vulkanischen Spalten wimmelt es von Troggs, sengenden Elementaren und verräterischen Hexenmeistern, die Thralls Herrschaft aus der Tiefe untergraben wollen.",al={"gefahren in orgrimmar","bedrohung durch den flammenschlund","kultisten in orgrimmar"}},{q="Wie reist man von Orgrimmar auf andere Kontinente?",a="Von Türmen außerhalb des Haupttors Orgrimmars starten von Goblins konstruierte Zeppeline. Sie fliegen regelmäßig über Das große Meer nach Tirisfal, nahe der Unterstadt, und südwärts zum Basislager Grom'gol im Schlingendorntal.",al={"zeppelinflüge von orgrimmar","von orgrimmar nach tirisfal reisen","reisen von orgrimmar"}}},fx={["34960c6e"]={q="Was ist Orgrimmar?",a="Orgrimmar ist die Kriegerhauptstadt der Orcs und der primäre Sitz der The New Horde. Gehauenen in die hoch aufragenden roten Felsschluchten des nördlichen Durotar, steht sie als befestigtes Refugium, das von Kriegshäuptling Thrall nach dem Dritten Krieg erbaut wurde. Sie dient als Herz von Handel, militärischer Stärke und Kultur für Orcs, Dunkelspeere, Tauren und ihre Verbündeten, die Verlassenen.",al={"was ist das für eine stadt","überblick orgrimmar","über orgrimmar"}},["8dcd1cbd"]={q="Warum ist Orgrimmar hier draußen in der Wüste?",a="Thrall führte sein Volk bewusst in die rauen, sonnenverbrannten Lande von Durotar, um sich durch Arbeit und Beharrlichkeit eine Heimat zu schaffen. Der rote Boden und die schroffen Felsen erinnerten die Orcs an ihre angestammte Heimat Draenor, während sie natürliche Verteidigungstäler und Schluchten boten, um ihre hart erkämpfte Unabhängigkeit zu schützen.",al={"warum bauen in durotar","warum steht die stadt in einer wüste","warum hier siedeln"}},["2df9c1bd"]={q="Wo ist Thrall?",a="Thrall hält Hof innerhalb von Grommash Hold, hoch oben im Tal der Weisheit gelegen. Vor seiner kalten Steinfestung steht ein alter Baumstamm, der den zertrümmerten Schädel und die Rüstung von Mannoroth zeigt – ein klares Denkmal zu Ehren von Grom Höllschreis Opfer und der Befreiung der Horde von dämonischer Verderbnis.",al={"wo findet man thrall","aufenthaltsort von thrall","wo ist der kriegshäuptling"}},["6bde2c20"]={q="Wer ist Nazgrel?",a="Nazgrel ist ein erfahrener Orc-Krieger und vertrauenswürdiger Leutnant, der Thrall direkt innerhalb von Grommash Hold dient. Er ist dem Kriegshäuptling fest ergeben und hilft, die Verteidigung und die militärische Einsatzbereitschaft der Stadt an der Seite des Oberkommandos der Horde zu beaufsichtigen.",al={"wer ist dieser krieger bei thrall","rolle von nazgrel","thrall-berater nazgrel"}},["19245cb0"]={q="Ist Orgrimmar gefährlich?",a="Während die hoch aufragenden Tore und erfahrenen Grunzer der Stadt Eindringlinge fernhalten, lauern im Inneren immer noch Gefahren. Hinterhältige Kultisten und Schurken-Zirkel treiben ihr Unwesen in den schattigen Abgründen unter den Klippen, wilde Razorwinds fegen durch die Täler und beschädigen unachtsame Konstruktionen, und der unterirdische Der Flammenschlund strotzt nur so vor Troggs und dunkler elementarer Verderbnis direkt unter den Straßen.",al={"ist es hier sicher","orgrimmar gefahr","gefahren in orgrimmar"}},f5c45f78={q="Was ist in Orgrimmar passiert?",a="Nach dem Dritter Krieg führte Thrall die Orcs nach Kalimdor, um der dämonischen Verderbnis zu entkommen, die ihr Volk zerrüttet hatte. Mit Hilfe der Tauren, Trolle und Rexxar meißelten sie diese Festung aus den Canyons von Durotar, während sie einheimische Stacheleber, Zentauren und Harpyien bekämpften, und verwandelten so ein karges Grenzland in die dauerhafte Zitadelle der The New Horde.",al={"orgrimmar geschichte","vergangenheit von orgrimmar","wie wurde orgrimmar gegründet"}},f55ec44b={q="Wie bin ich in Orgrimmar gelandet?",a="Wenn Ihr ein Orc oder ein Dunkelspeer-Troll seid, seid Ihr dem Ruf Eurer Ältesten gefolgt. Nachdem Ihr Euch in den Prüfungen von Durotar bewiesen habt, wiesen Euch Eure Ausbilder den Weg nach Norden entlang der roten Lehmstraßen, damit Ihr die großen befestigten Tore der Hauptstadt passieren konntet. Wenn Ihr von weit her gekommen seid – als Tauren aus den Ebenen von Mulgore oder als Verlassene-Reisender, der das große Meer mit einem Zeppelin von Tirisfal aus überquert hat –, dann seid Ihr im Herzen der The New Horde angekommen, dem Ruf von Kriegshäuptling Thrall folgend, um ihre verstreuten Völker unter einem Banner zu vereinen.",al={"wie kam ich hierher","wie bin ich hier angekommen","warum kam ich nach orgrimmar"}},["07461c2e"]={q="Was soll ich in Orgrimmar tun?",a="Ihr seid hier, um Euer Handwerk zu verfeinern, Euch bei Euren Anführern zu melden und die wachsende Horde zu unterstützen. Sucht die Klassenlehrer und Berufslehrer in den Tälern der Stadt auf, handelt an den Auktionshäusern oder stellt Euch Kriegshäuptling Thrall in Grommash Hold vor. Das junge Reich ist von Bedrohungen umgeben – von Zentauren-Kriegstrupps und Stacheleber-Plünderern, die über die Grenzen eindringen, bis hin zu niederträchtigen Kultisten, die sich in den unterirdischen Tiefen von Der Flammenschlund verstecken. Beweist Euren Wert bei der Verteidigung Eurer Verbündeten.",al={"was soll ich hier tun","warum bin ich hier","was ist meine aufgabe in orgrimmar"}},["2f0bb5cb"]={q="Wer hat Orgrimmar erbaut?",a="Kriegshäuptling Thrall und seine Orcs gründeten die Festung kurz nach der Schlacht am Hyjal und stellten sie in bemerkenswert kurzer Zeit fertig. Dabei halfen ihnen die gerissenen Dunkelspeertrolle, die edlen Tauren aus Mulgore, Goblinarbeiter und Ingenieure sowie Rexxar, der umherwandernde Halb-Oger und Bestienmeister.",al={"wer hat orgrimmar erbaut","wie wurde orgrimmar erbaut","bau von orgrimmar"}}},fp="9,189,26.559.0,20.491.0,23.432.1,20.206.0,32.211.0,36.267.0,28.236.0,35.193.0,53.213.0"}
P.entries["zone:ragefire"] = {n="Der Flammenschlund",s="Unter Orgrimmar bedrohen Troggs und ein Dämonenkult die junge Horde. Die Searing Blade schmiedet Pläne in Vulkankavernen unter der Kluft der Schatten, während darüber die Hauptstadt liegt.",h="Unter Orgrimmar bedrohen Troggs und ein Dämonenkult die junge Horde.",kw={"bazzalan","schlund","die kluft der schatten","jergosh","neeru fireblade","orgrimmar","flammenschlund","searing blade","taragaman"},ang={["class:Warlock"]="Als Hexenmeister könnt Ihr die dunkle Magie der Searing Blade in den Ritualen und Dämonenfolianten von Jergosh dem Herbeirufer und Bazzalan aus nächster Nähe erleben.",["faction:Horde"]="Für die Horde bietet die Säuberung des Schlunds unter Orgrimmar jungen Champions eine Kraftprobe und die Gelegenheit, die Hauptstadt zu schützen.",["race:Tauren"]="Als Tauren wisst Ihr, dass Maur Grimmtotems Tod durch die Ragefiretroggs die Jagd auf die Bestien zu einer Frage der Ehre und Vergeltung für Donnerfels macht."},sec={{t="Gefahr aus der Tiefe",b="Ragefiretroggs brechen tief unter Orgrimmar hervor und dringen in gewundene Vulkangänge und Lavagruben ein. Während orcische Baumeister oben ihre neue Heimat errichten, werden die Troggs immer aggressiver. Magatha Grimmtotem schickt Maur Grimmtotem als Gesandten von Donnerfels, doch die Troggs schalten ihn ab. Sie weichen nur der Gewalt."},{t="Die Searing Blade",b="Die Searing Blade, ein Dämonenkult, ist eine größere Gefahr als die Troggs. Ihre Fanatiker sind dem Schattenrat treu ergeben und schmieden in Kavernen neben Magmaströmen Pläne zum Untergang der jungen Horde. Jergosh der Herbeirufer, ein listiger Hexenmeister, führt den Kult gemeinsam mit Bazzalan, einem Satyr, und Taragaman der Hungerleider, einer grausamen Teufelswache. Taragaman wacht über einen Altar im Lavasee."},{t="Das Spiel des Kriegshäuptlings",b="Neeru Feuerklinge scheint Hexenmeister neben dem Eingang des Schlunds in der Kluft der Schatten auszubilden. Heimlich führt er dort die Burning Blade an. Er schickt Abenteurer der Horde als Loyalitätsprüfungen in die Tiefe und hofft, schwache Kultisten auszusortieren und Thralls Unterstützer zu töten.\n\nThrall weiß von Neerus Täuschung. Der Kriegshäuptling nutzt diese Vorstöße, um gefährliche Kultführer wie Jergosh und Bazzalan auszuschalten. Neeru lässt er an Ort und Stelle, damit er die weitreichenderen Pläne des Schattenrats überwacht."}},faq={{q="Wo befindet sich der Eingang zum Flammenschlund?",a="Der Eingang liegt in Orgrimmar, im unterirdischen Stadtteil Kluft der Schatten. Er befindet sich nahe Neeru Fireblades Zelt, des Hexenmeisterlehrers.",al={"lage des flammenschlunds","wo liegt der flammenschlund?","eingang zum flammenschlund"}},{q="Warum gibt es Troggs unter Orgrimmar?",a="Ragefiretroggs gruben sich aus unterirdischen Hohlräumen unter Durotar nach oben. Diplomatie konnte ihr plötzliches Auftauchen unter der Hauptstadt nicht eindämmen. Dort stellen sie eine große Gefahr dar.",al={"herkunft der ragefiretroggs","warum gibt es hier troggs?","troggs in orgrimmar"}},{q="Wer führt die Kultisten im Schlund an?",a="Jergosh der Herbeirufer, ein Hexenmeister, und Bazzalan, ein Satyr, führen die Searing Blade an. Taragaman der Hungerleider, eine herbeigerufene Teufelswache, unterstützt sie.",al={"bosse im flammenschlund","anführer der searing blade","wer herrscht im flammenschlund?"}},{q="Was bewirkt der Tod von Bazzalan und Jergosh für die Geschichte?",a="Der Tod von Bazzalan und Jergosh zerschlägt die aktive Führung der Searing Blade unter Orgrimmar. Ihr Tod zeigt die Widerstandskraft der Horde und ermöglicht Thrall, eine Dämonen anbetende Zelle unter seinem Thron zu vereiteln.",al={"bedeutung der bazzalan-lore","warum bazzalan töten?","ausgang von hidden enemies"}},{q="Können Abenteurer der Allianz den Flammenschlund betreten?",a="Jeder Abenteurer kann durch das Portal hineingehen. Ein Abenteurer der Allianz muss hochstufigen Wachen der Horde und feindseligen Verteidigern in ganz Orgrimmar ausweichen, um die Kluft der Schatten zu erreichen.",al={"kann die allianz den flammenschlund besuchen?","allianz im flammenschlund"}},{q="Warum lässt Thrall Neeru Feuerklinge nicht einfach hinrichten?",a="Thrall duldet jene, die in der Kluft der Schatten dunkle Magie praktizieren. Er behält sie in seiner Nähe und unter seiner Aufsicht, statt sie aus seinem Blickfeld zu vertreiben.",al={"thrall und neeru fireblade","warum lässt man neeru leben?"}}},fx={f4fa764c={q="Was ist Der Flammenschlund?",a="Der Flammenschlund ist ein unterirdisches Netzwerk aus feurigen vulkanischen Kavernen, das direkt unter der Orc-Hauptstadt Orgrimmar verläuft. Während es sich direkt unter den belebten Straßen darüber befindet, beherbergen seine geschmolzenen Tiefen bösartige Troggs und eine versteckte Kabale von Searing Blade-Kultisten, die gegen die Horde intrigieren.",al={"was ist der flammenschlund","über den flammenschlund","rfc hintergrundgeschichte"}},["947efccf"]={q="Warum gibt es eine Höhle unter Orgrimmar?",a="Die Kavernen bildeten sich auf natürliche Weise als vulkanisches Netzwerk innerhalb der felsigen Erde unter Durotar. Als die Orcs diesen verteidigungsfähigen Canyon wählten, um Orgrimmar zu errichten, lag der feurige Schlund bereits unter der Erde, ausgehöhlt von uralten unterirdischen Magmaströmen.",al={"warum eine höhle unter orgrimmar","wie entstand der flammenschlund","höhlen unter orgrimmar"}},["9252a3ac"]={q="Haben die Orcs sie ausgegraben?",a="Nein. Die Orcs haben Der Flammenschlund nicht ausgehoben. Es war bereits ein natürliches Labyrinth aus geschmolzenem Gestein und Lavaschloten, lange bevor Thrall sein Volk dazu führte, sich in Durotar niederzulassen und die Mauern von Orgrimmar darüber zu errichten.",al={"haben orcs rfc gegraben","hat die horde den flammenschlund gegraben"}},b0dedca2={q="Warum hat Thrall mich hierher geschickt?",a="Thrall entdeckte Gerüchte über Kultistenaktivitäten, die direkt unter seiner Stadt schwärten. Anstatt einen offenen militärischen Überfall zu starten, der die Verräter alarmieren würde, entsandte er vielversprechende Abenteurer in die Tiefen, um die Bedrohung zu untersuchen und die schattenhaften Anführer der Searing Blade zu eliminieren.",al={"warum schickte thrall mich in den rfc","grund für thralls rfc quest","warum bin ich im flammenschlund"}},["0d5305cc"]={q="Wer ist Thrall?",a="Thrall ist der Kriegshäuptling der Horde und Gründer der Nation Durotar. Geboren als Go'el, Sohn des Häuptlings Durotan vom Frostwolfklan, entkam er der menschlichen Knechtschaft und den Gladiatorenarenen, um die zersplitterten Orc-Klane zu vereinen, ihr vergessenes schamanisches Erbe wiederzubeleben und eine neue, ehrenhafte Horde zu schmieden.",al={"wer ist kriegshäuptling thrall","thrall hintergrundgeschichte","wer ist thrall"}},["09eb01d5"]={q="Wie wurde er Kriegshäuptling?",a="Thrall kämpfte an der Seite von Orgrim Schicksalshammer, um nach dem Zweiter Krieg inhaftierte Orcs aus den Internierungslagern der Allianz zu befreien. Als Schicksalshammer im Kampf fiel, vermachte er seine legendäre schwarze Rüstung und seinen Kriegshammer an Thrall und ernannte ihn zum neuen Kriegshäuptling, der ihr Volk nach Kalimdor führen sollte.",al={"wie thrall kriegshäuptling wurde","ursprung von thralls führung","wie bekam thrall schicksalshammer"}},c23e3fbc={q="Ist Thrall ein Schamane?",a="Ja. Geleitet von den Geistern und dem alten Eremiten Drek'Thar vom Frostwolfklan, wurde Thrall der erste neue Orc-Schamane seit einer Generation, der die korrumpierende dämonische Teufelsmagie, die einst seine Rasse versklavt hatte, zugunsten der Harmonie mit den Elementen ablehnte.",al={"ist thrall schamane","thralls klasse","kann thrall zaubern"}},["833fd6a3"]={q="Was sind die Hidden Enemies, von denen Thrall spricht?",a="Die Hidden Enemies sind dämonische Kultisten und Sympathisanten, die heimlich in Durotar leben und planen, Thralls junge Gesellschaft zu stürzen. Sie operieren aus dem Schatten und versteckten Tunneln heraus, dienen dunklen Mächten aus der Vergangenheit der Orcs und untergraben aktiv den Frieden der Horde von innen heraus.",al={"hidden enemies thrall","wer sind die hidden enemies","was sind die hidden enemies"}},["606e7173"]={q="Warum gibt es Dämonen unter Orgrimmar?",a="Die Kultisten der Searing Blade brachten Dämonen wie Taragaman der Hungerleider in die Tiefen, um ihre dunklen Rituale zu verankern. Sie lauern unter Die Kluft und nutzen dämonische Macht, um unvorsichtige Bürger anzulocken und Initianden zu prüfen, die der Brennende Legion dienen wollen.",al={"dämonen im flammenschlund","warum dämonen unter orgrimmar","taragaman im rfc"}},["0ca922e2"]={q="Was ist der Schattenrat?",a="Der Schattenrat war eine geheime Kabale von Hexenmeistern, die ursprünglich auf Draenor von Gul'dan gegründet wurde, um die Orc-Klane zu manipulieren und sie an die Brennende Legion zu binden. Obwohl sie während des Erster Krieg und Zweiter Krieg zerschlagen wurde, arbeiten verbliebene Sekten wie die Burning Blade weiterhin auf die Ziele ihrer dämonischen Meister hin.",al={"schattenrat hintergrundgeschichte","was ist der schattenrat","geschichte des schattenrats"}},be4be4e7={q="Was sind die Ragefire-Troggs?",a="Die Ragefire-Troggs sind ein gewalttätiger, unterirdischer Klan von primitiven Troggs, die die oberen Bereiche des Schlunds befallen. Barbarenhaft und aggressiv brechen sie aus unterirdischen Spalten in die Kavernen ein und greifen sofort jeden an, der ihr Territorium betritt.",al={"ragefire-troggs","was sind die troggs im rfc","rfc troggs"}},["608f7b0a"]={q="Warum ich, ich bin doch noch kein Held?",a="Thrall kann seine Elite-Kor'kron-Wachen nicht einsetzen, ohne die Verschwörer zu alarmieren und sie tiefer in den Untergrund zu treiben. Indem er eifrige neue Abenteurer einsetzt, unternimmt er einen leisen, abstreitbaren Schlag, der die unmittelbaren Leutnants des Kults eliminiert, während er seine eigenen Gegenuntersuchungen diskret hält.",al={"warum schickte man mich in den rfc","warum abenteurer für ragefire","warum ich ragefire"}},cbc9ae06={q="Was passiert, nachdem ich den Hexenmeister und den Satyr getötet habe?",a="Sobald Jergosh der Herbeirufer und Bazzalan gefallen sind, sind ihre Pläne im Schlund gelähmt. Ihr meldet Euren Triumph an Thrall zurück, der die Existenz eines größeren Netzwerks des Verrats bestätigt, das über die Kavernen hinaus in die Welt an der Oberfläche reicht.",al={"nach dem töten von bazzalan und jergosh","jergosh getötet nächster schritt","was tun nach rfc"}},e02585d8={q="Führt das zurück zu Thrall?",a="Ja. Thrall erwartet, dass Ihr Euch direkt in seinem Thronsaal im Tal der Weisheit meldet. Die Tötung der Feldkommandanten des Kults beweist Eure Loyalität und informiert den Kriegshäuptling über das wahre Ausmaß der Subversion, die direkt unter seinen Füßen braut.",al={"führt rfc zurück zu thrall","rückkehr zu thrall nach rfc","bericht an thrall"}},["02870934"]={q="Wie bin ich in Der Flammenschlund gelandet?",a="Ihr seid durch die schattigen Tunnel unter Orgrimmar in Die Kluft hinabgestiegen, wo sich die Ausgestoßenen der Stadt und dunklere Praktizierende versammeln. Neben dem Zelt des Hexenmeisters Neeru Feuerklinge liegt die tiefste Schwelle der Kluft: ein rauchender Torbogen, der direkt in das vulkanische Unterinnere von Durotar führt. Ob von Kriegshäuptling Thrall hierher geschickt, um versteckte Verräter aufzuspüren, von Tauren-Gesandten aus Donnerfels entsandt oder von dunklen Flüsterern hierher gelenkt, die Eure Standhaftigkeit prüften – Ihr seid durch dieses Tor in die unterirdischen Magmatunnel gegangen.",al={"wie kam ich hierher","wie kam ich zum flammenschlund","warum bin ich in diesen kavernen"}},["9382a7ef"]={q="Was soll ich in Der Flammenschlund tun?",a="Ihr seid hier, um eine schwärende Fäulnis zu beseitigen, die das Herz der Horde bedroht. In diesen vulkanischen Kavernen haben sich wilde Troggs aus den Tiefen nach oben gekrallt, lehnen Frieden gewaltsam ab und schlachten Gesandte ab. Schlimmer noch, die Searing Blade – ein verdeckter Splitter des dämonischen Schattenrats – plant Orgrimmars Ruin aus der Dunkelheit. Eure Pflicht ist es, Euch durch die Troggs zu schneiden, den bulligen Teufelswache Taragaman der Hungerleider zu konfrontieren und die sterblichen Kommandeure des Kults, Jergosh der Herbeirufer und den Satyr Bazzalan, zu eliminieren und ihr unterirdisches Netzwerk zu zertrümmern, bevor es die Stadt darüber überrennt.",al={"was mache ich hier","was ist mein ziel in ragefire","warum wurde ich hierher geschickt"}}},fp="14,165,18.299.0,17.349.0,19.465.1,40.152.0,31.176.0,40.138.0,64.199.1,46.186.0,50.149.1"}
P.entries["zone:razorfenkraul"] = {n="Kral der Klingenhauer",s="Im äußersten Süden des Brachlands verteidigen Borstennacken das heilige Dornengestrüpp des Kral der Klingenhauer. Sie verehren das Dickicht als Ruhestätte ihres Ahnen Agamaggan, während Charlga Klingenflankes Herrschaft die Region bedroht.",h="Im äußersten Süden des Brachlands verteidigen Borstennacken das heilige Dornengestrüpp des Kral der...",kw={"agamaggan","brachland","charlga","halmgar","kral","borstennacken","ramtusk","razorfen","klingenflanke","geißel"},ang={["class:Shaman"]="Als Schamane erkennt Ihr, wie die Geomantie der Borstennacken Erde und Elemente rund um Agamaggans Blut verdreht und Urkräfte für wilde Zwecke einsetzt.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, Versorgungskarren und junge Siedlungen im südlichen Brachland zu schützen, indem Ihr die Aggression des Kral der Klingenhauer eindämmt.",["race:Tauren"]="Als Tauren wisst Ihr, dass die Borstennacken seit Langem um die Grenzen Mulgors streiten. Ihre dunklen Bündnisse und die Schändung der Erde machen den Kral der Klingenhauer zu einer Frage des Stammesverteidigung.",["race:Undead"]="Als Untoter interessiert Ihr Euch vielleicht für seltsame Reagenzien, Fledermausguano und Berichte über Vorstöße der Geißel zwischen den Dornenranken."},sec={{t="Blut des Ebergottes",b="Vor zehntausend Jahren kämpfte Agamaggan im Krieg der Ahnen gegen die Brennende Legion. Der kolossale wilde Gott fiel, doch sein Opfer bewahrte das Leben auf Azeroth. Legenden erzählen, dass überall dort, wo sein Blut in die Erde drang, dornenbedeckte Ranken emporwuchsen und dichte Wehrwälle in den südlichen Ebenen bildeten. Die Borstennacken verehren Agamaggan als ihren göttlichen Ahnen und beanspruchen das Dickicht als heiligen Boden. Die größten unter ihnen wurden zum Razorfen."},{t="Die Ambitionen der Greisin",b="Charlga Klingenflanke herrscht mit despotischer Gewalt über den Kral der Klingenhauer. Unter der Ältestengreisin haben die schamanistischen Borstennacken ihre üblichen Scharmützel beigelegt und greifen nun gemeinsam rivalisierende Stämme, regionale Handelswege und junge Siedlungen der Horde an. Gerüchte und Späherberichte sprechen von untoten Unholden, die nahe dem Dornengestrüpp umherstreifen. Charlga verhandelt möglicherweise mit Abgesandten der Geißel und hofft, ihren Stamm mit verbotener Nekromantie zu stärken."}},faq={{q="Was ist der Kral der Klingenhauer?",a="Der Kral der Klingenhauer ist ein weitläufiges Gewirr aus dornigen Ranken im südlichen Brachland. Die Borstennacken betrachten ihn als ihr spirituelles Zentrum und ihre Heimat der Ahnen.",al={"was ist rfk","kral der klingenhauer erklärt","überblick zum kral der klingenhauer"}},{q="Wie entstanden die riesigen Dornen?",a="Die gewaltigen Dornengestrüppe wuchsen vor zehntausend Jahren während des Krieges der Ahnen aus der Erde, dort, wo das Blut des gefallenen Eberhalbgotts Agamaggan vergossen wurde.",al={"warum gibt es riesige dornen","woher stammt das dornengestrüpp","agamaggans dornen"}},{q="Wer herrscht über den Kral der Klingenhauer?",a="Charlga Klingenflanke, eine erbarmungslose Greisin und Schamanin der Borstennacken, herrscht über den Kral der Klingenhauer. Sie befehligt den Stamm der Razorfen und führt Angriffe auf benachbarte Dörfer und Reisende.",al={"wer ist der boss von rfk","charlga klingenflanke","greisin des krals"}},{q="Warum sorgt sich die Horde um den Kral der Klingenhauer?",a="Angriffe der Borstennacken bedrohen junge Siedlungen der Horde im Brachland, und Späher haben Untote nahe dem Dickicht gesehen. Ihre Anwesenheit weckt die Befürchtung, dass Charlga mit der Geißel zusammenarbeitet.",al={"warum interessiert sich die horde dafür","interesse der horde an rfk","bedrohung im brachland"}},{q="Warum interessieren sich Truppen der Allianz für den Kral?",a="Charlgas Stamm bedroht Außenposten nahe Feralas und Tausend Nadeln. Befehlshaber und Späher der Allianz in Thalanaar wollen sie besiegen, um die Grenze zu sichern.",al={"allianzquests für rfk","warum geht die allianz hierher","thalanaar quest"}},{q="Was bedeutet die Niederlage von Earthcaller Halmgar für die Geschichte?",a="Earthcaller Halmgar ist ein seltener und einflussreicher Geomant tief im Dickicht. Seine Niederlage schwächt die Erdformungspriester der Borstennacken, stört Charlga Klingenflankes Verteidigung und mindert ihre Macht, Agamaggans heiliges Dornengestrüpp zu formen.",al={"was passiert nach earthcaller halmgars tod","hintergrund zu earthcaller halmgar","halmgar besiegt"}}},fx={["59c8bcc4"]={q="Wer hat all diese Dornen im Kral der Klingenhauer erschaffen?",a="Niemand hat sie von Hand erschaffen. Vor zehntausend Jahren, während des Krieges der Ahnen, fiel der kolossale Eberhalbgott Agamaggan im Kampf gegen die Brennende Legion. Wo sein göttliches Blut in den Boden sickerte, brachen massive, undurchdringliche, dornenbewachsene Gebüsche aus der Erde hervor und bildeten das labyrinthartige Dickicht, das Ihr heute seht.",al={"wer hat die dornen erschaffen","wer baute die dornen","ursprung der dornen im kral der klingenhauer"}},["4843f165"]={q="Was sind Stacheleber?",a="Stacheleber sind primitive, aggressive, eberähnliche Humanoide, die in Kalimdor beheimatet sind. Sie haben muskulöse, gebeugte Rücken, die mit scharfen, defensiven Stacheln übersät sind. Es wird angenommen, dass sie die sterblichen Nachkommen des Halbgottes Agamaggan sind; sie verehren seine Ruhestätten und verteidigen ihre dornigen Gebiete erbittert gegen alle Außenstehenden.",al={"was sind stacheleber","wer sind die stacheleber","stacheleber hintergrundgeschichte"}},ea4583b3={q="Warum leben die Stacheleber in einem riesigen Dornenlabyrinth?",a="Das Dornenlabyrinth ist direkt aus dem Blut ihres gefallenen Gottes Agamaggan hervorgegangen. Für die Stacheleber ist der Kral der Klingenhauer heiliger Boden und seine tatsächliche Ruhestätte. Das Gestrüpp bietet ihnen sowohl heilige Verehrung als auch natürliche, nahezu undurchdringliche Festungen gegen ihre regionalen Feinde.",al={"warum in dornen leben","warum leben stacheleber hier","stacheleber dornenlabyrinth"}},b1fd1d2b={q="Ist Charlga Klingenflanke die Anführerin aller Stacheleber?",a="Nicht aller Stacheleber, aber sie beherrscht den mächtigen Stamm der Klingenhauer, der sich im Kral verschanzt hat. Als gerissene Matrone und Geomantin vertrieb sie die dortigen Tauren aus dem südlichen Brachland und übt weitreichende Autorität aus, obwohl rivalisierende Stacheleberstämme, die über ganz Kalimdor verstreut sind, sich selbst regieren.",al={"charlga klingenflanke anführerin","wer führt alle stacheleber an","hat charlga das sagen über alle"}},["8ed48c28"]={q="Wer ist Agathelos der Tobende?",a="Agathelos ist ein massiver, wilder Eber, der im Kral der Klingenhauer haust. Stacheleber verehren Eber als lebende Symbole ihres Gottes Agamaggan und betrachten besonders große und beharrliche Bestien wie Agathelos als direkte Segnungen und heilige Manifestationen der ursprünglichen Macht des Großen Ebers.",al={"wer ist agathelos","hintergrundgeschichte von agathelos der tobende","agathelos rieseneber"}},["4f663063"]={q="Spioniert die Horde auch im Kral der Klingenhauer herum?",a="Ja. Die Plünderer von Charlga Klingenflanke verüben ständig brutale Angriffe auf Siedlungen der Horde im gesamten Brachland und haben die Tauren aus ihren angestammten südlichen Gebieten vertrieben. Sowohl die Orcs als auch die Tauren entsenden aktiv Krieger, um die Macht der Matrone zu brechen und die Bedrohung durch die Stacheleber zu beenden.",al={"ist die horde hier","präsenz der horde im kral der klingenhauer","horde im kral der klingenhauer"}},["5328604f"]={q="Wer ist Agamaggan?",a="Agamaggan, der Große Eber, war ein Uralter Wächter und einer der ersten und mächtigsten Wilden Götter, die Azeroth durchstreiften. Die Stacheleber verehren ihn als ihren Schöpfer, huldigen seinem Andenken und beziehen spirituelle sowie geomantische Kraft aus seinem Blut und den riesigen Dornenclustern, die aus seinem Opfer hervorgegangen sind.",al={"wer ist agamaggan","agamaggan der große eber","agamaggan hintergrundgeschichte"}},bc4e6730={q="Starb Agamaggan im Krieg der Ahnen?",a="Ja. Vor zehntausend Jahren folgte Agamaggan dem Ruf von Cenarius, Azeroth vor der Brennende Legion zu verteidigen. Er wütete über den Kontinent und zermalmte Tausende von Dämonen, bevor er schließlich im Kampf gegen eine überwältigende dämonische Armee fiel und sein Leben opferte, damit Malfurion Sturmgrimm den Brunnen der Ewigkeit erreichen konnte.",al={"wie starb agamaggan","agamaggan krieg der ahnen","ist agamaggan gestorben"}},e47b7687={q="Verehren die Stacheleber Agamaggan immer noch?",a="Das tun sie, mit fanatischer Hingabe. Schamanen und Geomanten der Stacheleber beten zu Agamaggan um Stärke im Kampf, verehren riesige Eber als seinen Segen und horten Blutedelsteine, die aus seinem versteinerten Blut geformt wurden. Sie glauben, dass seine physischen Überreste sie und ihre heilige Heimat beschützen.",al={"verehren die stacheleber noch immer agamaggan","stacheleber religion","verehrung von agamaggan"}},["7583b13a"]={q="Wer sind die Typen vom Totenschädel?",a="Der Totenschädel ist eine militante Fraktion der Stacheleber, die auf dem Schlachtfeld von Oberanführer Rammhauer angeführt wird und an der Seite des Stammes der Klingenhauer operiert. Rammhauer leitet ihre disziplinierten, kampferprobten Truppen an, um das Dornenlabyrinth fest im Griff zu halten und bösartige Kriege gegen ihre Nachbarn zu führen.",al={"stamm des totenschädels","wer sind die vom totenschädel","totenschädel-stacheleber"}},["4bc36485"]={q="Werden die Stacheleber hier Siedlungen im Brachland angreifen?",a="Das tun sie bereits. Unter dem Kommando der Matrone Charlga Klingenflanke schwärmen aggressive Plünderer ständig aus den Dornen in die umliegenden Ländereien aus. Sie haben Reisende in der Nähe des großen Aufzugs belästigt, rivalisierende Stämme überfallen und Siedlungen sowie Karawanen der Horde an den Rand eines offenen Krieges gedrängt.",al={"werden stacheleber das brachland angreifen","brachland unter angriff durch stacheleber","stacheleber-überfälle im brachland"}},ed4c33ec={q="Was ist der Unterschied zwischen dem Kral und den Hügeln?",a="Beide sind massive Dornennetzwerke, die durch den Fall von Agamaggan entstanden sind, aber sie erfüllen unterschiedliche Rollen. Kral der Klingenhauer ist das angestammte Herz, wo Charlga Klingenflanke lebende Stacheleberplünderer versammelt. Hügel der Klingenhauer, weiter südöstlich in der Nähe des riesigen skelettierten Mauls des Halbgottes gelegen, ist unter den dunkleren Einfluss der Geißel gefallen.",al={"unterschied zwischen kral und hügeln","kral der klingenhauer gegen hügel der klingenhauer","kral oder hügel"}},["974f5634"]={q="Ist die Geißel im Kral der Klingenhauer involviert?",a="Ja. Beunruhigende Berichte und abgefangene Schreiben enthüllen, dass Charlga Klingenflanke begonnen hat, mit Agenten der Geißel zu verhandeln. Späher haben Untote in der Nähe des Kral der Klingenhauer gesichtet, was die ernste Sorge aufkommen lässt, dass die Schergen des Lichkönigs versuchen, durch diese ahnungslosen Stämme einen Fuß auf Kalimdor zu fassen.",al={"geißel im kral der klingenhauer","gibt es untote im kral der klingenhauer","präsenz der geißel im kral"}},a384c7af={q="Wer ist Amnennar?",a="Amnennar der Kältebringer ist ein mächtiger Agent der Geißel, der sich in den benachbarten Hügel der Klingenhauer niedergelassen hat. Er arbeitet hinter den Kulissen, manipuliert die Führung der Stacheleber und befehligt die Streitkräfte des Totenschädels, um das südliche Gestrüpp in eine Festung der Untoten zu verwandeln.",al={"wer ist amnennar","amnennar der kältebringer","amnennar hintergrundgeschichte"}},af015f4e={q="Wie bin ich im Kral der Klingenhauer gelandet?",a="Ihr seid in die südlichsten Ausläufer des Brachlandes gereist, in die Nähe der hoch aufragenden Klippen mit Blick auf Tausend Nadeln. Während Ihr Euch durch das umkämpfte Buschland vorkämpftet, fandet Ihr das riesige Dickicht aus blutgenährtem Gestrüpp, das aus dem Kadaver des uralten Eber-Gottes Agamaggan entsprang. Direkt in diese massiven, versteinerten Dornenranken gehauen liegt der westliche Eingang zum Kral, wo Verteidiger der Stacheleber den Zugang gegen jeden bewachen, der es wagt, in ihr heiliges Territorium einzudringen.",al={"wie bin ich hierher gekommen","wie erreicht man den kral der klingenhauer","wo ist der kral der klingenhauer"}},["141f6ea5"]={q="Was soll ich im Kral der Klingenhauer tun?",a="Ihr seid hier, um die feindselige Macht des Stammes der Klingenhauer zu brechen und ihre aggressive Expansion über das Brachland aufzuhalten. Unter der Führung ihrer Matrone Charlga Klingenflanke haben diese fanatischen Stacheleber ihre gewaltsamen Übergriffe auf benachbarte Siedlungen und Karawanen verstärkt. Euer Ziel ist es, Euch durch die verschlungenen Dornengänge zu kämpfen, die Führung des Totenschädels zu zerschmettern und Charlga zur Strecke zu bringen, bevor ihre dunkle Geomantie und ihre mutmaßlichen Geschäfte mit finsteren Mächten der Untoten einen umfassenden Krieg entfachen.",al={"was ist meine mission hier","warum bin ich im kral der klingenhauer","was mache ich hier"}}},fp="14,218,21.427.0,20.423.1,23.142.0,34.156.0,25.170.0,48.182.0,48.157.0,59.248.0"}
P.entries["zone:redridge"] = {n="Rotkammgebirge",s="Das Rotkammgebirge wird nun von Schattenfellgnollen und Schwarzfelsorcs der Dunklen Horde angegriffen. Reißende Flüsse durchziehen die bewaldeten Hänge rund um den Immerruhsee, während Seenhain mit umherziehenden Söldnern die Stellung hält und Sturmwinds Truppen mit Unruhen in der Heimat ringen.",h="Das Rotkammgebirge wird nun von Schattenfellgnollen und Schwarzfelsorcs der Dunklen Horde angegriffen.",kw={"schwarzfelsorcs","der immerruhsee","seenhain","magistrat solomon","marschall marris","rotkammgebirge","renders tal","schattenfell","steinwacht","burg steinwacht","verner gutmark"},ang={["faction:Alliance"]="Als Soldat der Allianz könnt Ihr in Seenhain Eure Fähigkeiten schärfen. Der Ort ist ein Außenposten an der Front und muss sich organisierten Orcs und Gnollen stellen.",["faction:Horde"]="Die im Rotkammgebirge verschanzen Schwarzfelsorcs gehören zur feindseligen Dunklen Horde. Sie sind Feinde von Thralls Horde ebenso wie der Menschen in Seenhain.",["profession:Herbalism"]="An den gemäßigten Berghängen gedeihen Wilddornrose, Beulengras, Maguskönigskraut und Flitzdistel.",["profession:Mining"]="In den felsigen Klüften und Tälern rund um den Immerruhsee findet Ihr Kupfer, Zinn und seltene Silberadern, besonders nahe den Rethbanhöhlen."},sec={{t="Eine belagerte Bastion",b="Das Rotkammgebirge gehörte einst zu den friedlichsten Regionen des Königreichs. Seine Wälder lieferten Sturmwind Bauholz, während seine Gewässer und Felder das Königreich mit Fisch und Feldfrüchten versorgten. Nun ist Seenhain gegen wiederholte Angriffe befestigt. Burg Steinwacht, einst eine stolze Festung des Königreichs, ist an abtrünnige Schwarzfelsorcs gefallen. Ihre Stellung sperrt Straßen und bedroht die östlichen Täler."},{t="Das geteilte Gebirge",b="Diese Gipfel sind Teil des Rückgrats, das sich über den Subkontinent Azeroth erstreckt. Vor Jahrhunderten reichte das Gebirge viel weiter nach Norden. Dann beschwor der Dunkeleisenklan versehentlich den Feuerlord Ragnaros herauf, und die Erde riss auf. So entstand der feurige Krater des Schwarzfels. Die Katastrophe trennte die nördlichen Gipfel ab, aus denen die ascheverhangene Brennende Steppe wurde. Nur die südlichen Täler des Rotkammgebirges blieben üppig und grün, den Angriffen von den Hängen oberhalb ausgesetzt."},{t="Vom Königreich vernachlässigt",b="Magistrat Solomon und Marschall Marris flehen um Verstärkung, doch Sturmwinds Regentschaftsrat überlässt Seenhain sich selbst. Bitten an Späherkuppe und Dunkelhain bringen keine Hilfe; beide Siedlungen sind durch eigene Krisen geschwächt. Da keine Verstärkung in Sicht ist, heuern die örtlichen Magistrate jeden fähigen Söldner an, der bereit ist, den Uferpfad zu wagen, die Gnolllager zu säubern und die Gefahr jenseits des Immerruhsees zurückzudrängen."},{t="Die verborgenen Bündnisse",b="Morganth, ein abtrünniger Hexenmeister, verbündete sich zunächst mit den Schwarzfelsorcs, um Burg Steinwacht einzunehmen. Später verriet er sie und unterwarf die Schattenfellgnolle vom Turm von Ilgalar aus seinem Willen. Bei den Ermittlungen zu den Schwarzfelsorcs gefundene Berichte enthüllen zudem ein Bündnis zwischen den Orcs und dem Schwarzen Drachenschwarm."}},faq={{q="Warum schickt Sturmwind keine Soldaten, um Seenhain zu helfen?",a="Nach dem Fall von Burg Steinwacht sind die verbliebenen königlichen Soldaten in Seenhain zahlenmäßig deutlich unterlegen. Magistrat Solomon hat um Truppen, Waffen, Nahrung und Vorräte gebeten, doch Sturmwinds Streitkräfte sind stark beansprucht, und auch die Siedlungen in der Nähe haben eigene Probleme. Die Garnison ist auf Abenteurer angewiesen, die helfen, die Region zu halten.",al={"warum keine sturmwinder wachen","warum ist das rotkammgebirge verlassen","wo ist sturmwinds armee"}},{q="Wer kontrolliert Burg Steinwacht?",a="Schwarzfelsorcs der Dunklen Horde kontrollieren Burg Steinwacht. Von der Bergfestung aus bedrohen sie die östlichen Täler und Reisende auf dem Uferpfad. Ihre Verbindungen zu anderen Gefahren der Gegend kommen bei den Ermittlungen ans Licht.",al={"wer ist in burg steinwacht","feinde in burg steinwacht","was geschah mit burg steinwacht"}},{q="Welche Gefahren lauern im Immerruhsee?",a="Feindselige Murlocstämme bevölkern den Immerruhsee und überfallen nahegelegene Anlegestellen und Ruinen. Räuberische Schwimmhäuter jagen ebenfalls unter der Oberfläche und schüren Gerüchte über Wassermonster in der Tiefe.",al={"monster im immerruhsee","gefahren im see des rotkammgebirges","murlocs im immerruhsee"}},{q="Gibt es Außenposten der Horde im Rotkammgebirge?",a="Im Rotkammgebirge gibt es keine Siedlungen, Händler oder Flugrouten der Horde. Reisende der Horde durchqueren die Gegend meist auf dem Weg von der Brennenden Steppe im Norden zu den Sümpfen des Elends im Südosten. Dabei nutzen sie Straßen unter Kontrolle der Allianz und durchqueren feindselige Wildnis.",al={"hordenstädte im rotkammgebirge","ist das rotkammgebirge horde oder allianz","flugroute der horde im rotkammgebirge"}},{q="Was sind die Drei Ecken?",a="Die Drei Ecken sind eine Kreuzung im Südwesten des Rotkammgebirges. Dort trifft der Uferpfad auf die östliche Grenze des Waldes von Elwynn und die Straße nach Dämmerwald. So entsteht ein wichtiger Durchgang, den umherziehende Gnolle und wilde Tiere oft zum Ziel haben.",al={"drei ecken","kreuzung der drei ecken","kreuzung im rotkammgebirge"}},{q="Warum ist der nördliche Weg zur Brennenden Steppe so gefährlich?",a="Der Pfad nach Norden führt hinter Render’s Camp direkt hinauf in die Brennende Steppe, ein ödes vulkanisches Ödland. Dort herrschen mächtige Schwarzfelsorcs, Feuerelementare und Drachkin. Die Gefahr nimmt dort plötzlich zu, weshalb der nördliche Gebirgspass zu den tödlichsten Aufstiegen im Süden Azeroths gehört.",al={"nördliche straße des rotkammgebirges","grenze zwischen rotkammgebirge und brennender steppe","nördlicher pass im rotkammgebirge"}}},fx={d1ce2561={q="Was soll ich im Rotkammgebirge tun?",a="Seenhain ist in einer verzweifelten Lage und wurde von der Krone so gut wie aufgegeben. Ihr seid hier, um auf die Bitten von Magistrat Solomon und Marschall Marris um Verteidigung zu antworten. Die Stadt ist schwer bedrängt von marodierenden Schattenhautgnollen entlang der Straßen und wilden Schwarzfelsorcs, die Burg Steinwacht eingenommen haben. Da die königliche Garnison zahlenmäßig unterlegen ist und The Everstill Bridge zerstört wurde, müsst Ihr die Gnolle zurückschlagen, die Vorhut der Orcs zurückdrängen und verhindern, dass dieser friedliche Zufluchtsort am See völlig zusammenbricht.",al={"was mache ich hier","warum bin ich hier","was ist mein ziel im rotkammgebirge","was ist meine mission hier"}},bf444872={q="Ist das Rotkammgebirge gefährlich?",a="Trotz seines idyllischen Aussehens ist das Rotkammgebirge außerordentlich gefährlich. Die Orcs des Schwarzfels kontrollieren die östlichen Schluchten und die Burg, Shadowhide-Gnolle plündern die Wälder und Murlocs tummeln sich an den Ufern des Sees. Sogar die nördliche Straße grenzt an die sengenden Gipfel der Brennenden Steppe, wo monströse Bedrohungen, die weit über eine durchschnittliche Patrouille hinausgehen, direkt hinter den Talpässen lauern.",al={"ist das rotkammgebirge sicher","gefahrenstufe rotkammgebirge","wie gefährlich ist das rotkammgebirge"}},["1cc45818"]={q="Warum ist jeder in Seenhain so besorgt?",a="Seenhain befindet sich im aktiven Belagerungszustand. Die Orcs des Schwarzfels haben Burg Steinwacht direkt auf der anderen Seite des Sees eingenommen, Shadowhide-Gnolle bedrängen die Stadt von den Hügeln aus und Murlocs befallen die Wasserwege. Da die Brücke zerstört ist und keine Verstärkung aus Sturmwind eintrifft, befürchten die Stadtbewohner, dass ein umfassender Angriff sie jeden Moment auslöschen könnte.",al={"warum hat seenhain angst","bedrohung in seenhain","warum besorgnis in seenhain"}},["851f5e81"]={q="Steht Seenhain kurz vor dem Fall?",a="Ohne Eingreifen von außen ist die Lage von Seenhain düster. Die örtliche Stadtwache ist den Orc-Plünderern, Gnollrudeln und Seeungeheuern zahlenmäßig weit unterlegen. Ihre Festung in Steinwacht wurde leicht überrannt und die Verteidiger von Seenhain wurden an das westliche Ufer des Sees zurückgedrängt, wo sie mit Mühe einen Verteidigungswall entlang der zerstörten Brücke halten.",al={"wird seenhain fallen","ist seenhain dem untergang geweiht","kann seenhain überleben"}},["7ced12b0"]={q="Hat Sturmwind Hilfe nach Seenhain geschickt?",a="Seenhain hat Sturmwind, Westfall und Dunkelhain um Hilfe gebeten, doch die benachbarten Siedlungen sind mit ihren eigenen Krisen beschäftigt. General Marcus Jonathan wurde ebenfalls um Verstärkung gebeten. Die königlichen Soldaten, die Seenhain noch verteidigen, haben nach dem Fall von Burg Steinwacht weiterhin einen Mangel an Truppen und Vorräten.",al={"hat sturmwind seenhain geholfen","sturmwind hilfe für seenhain","hat sturmwind truppen ins rotkammgebirge geschickt"}},["3a3ab87f"]={q="Wer hat hier das Sagen?",a="Seenhain wird von Magistrat Solomon regiert, der zivile Angelegenheiten und städtische Belange vom Rathaus von Seenhain aus beaufsichtigt. Militärische und Verteidigungsoperationen unterstehen Marschall Marris, der die örtliche Wache leitet und Verteidigungsbemühungen nahe der Brücke koordiniert.",al={"wer führt das rotkammgebirge","wer regiert seenhain","anführer des rotkammgebirges"}},["1dd15680"]={q="Wer ist Magistrat Solomon?",a="Magistrat Solomon ist das gewählte Oberhaupt von Seenhain und oberster Richter des Gerichts von Seenhain. Gealtert und erschöpft trägt er die Last, die Stadt mit Nahrung zu versorgen, organisiert zu halten und politisch mit dem Königreich verbunden zu lassen, während er verzweifelt auswärtige und regionale Anführer um militärische Entlastung bittet.",al={"magistrat solomon","wer ist solomon","solomon rotkammgebirge"}},["0e63cf14"]={q="Untersteht Marschall Marris Magistrat Solomon?",a="Ja. Solomon repräsentiert die zivile Autorität und das Gericht des Königreichs in Seenhain, während Marschall Marris das dort stationierte Kontingent der Sturmwindgarde befehligt. Die beiden arbeiten eng zusammen, wobei Solomon die diplomatische und städtische Überlebenssicherung verwaltet, während Marris taktische Scharmützel und Truppeneinsätze handhabt.",al={"untersteht marris solomon","rang von marschall marris und solomon","wer steht im rang über wem in seenhain"}},["7b7fd7c0"]={q="Wer sind die Orcs des Schwarzfels und warum sind sie im Rotkammgebirge?",a="Der Clan des Schwarzfels ist ein rücksichtsloser Überrest der Alten Horde, der im Norden vom Schwarzfels aus operiert. Im Gegensatz zu Thralls Horde in Kalimdor lehnen diese Abtrünnigen jeden Frieden mit der Allianz ab. Sie sind von der Brennenden Steppe in das Rotkammgebirge herabgestiegen, um die Region zu erobern, und nutzen Burg Steinwacht als Stützpunkt, um Seenhain zu zerschlagen.",al={"orcs des schwarzfels im rotkammgebirge","warum sind orcs im rotkammgebirge","wer ist der clan des schwarzfels im rotkammgebirge"}},["114fb915"]={q="Woher kommen die Orcs des Schwarzfels?",a="Sie marschierten aus südlicher Richtung über die gezackten nördlichen Gebirgspässe direkt von der Brennenden Steppe und der Schwarzfelsspitze, ihrer alten Festung aus dem Zweiter Krieg, hierher. Sie errichteten Außenposten wie Render's Camp, bevor sie Burg Steinwacht überwältigten.",al={"woher kommen die orcs im rotkammgebirge","herkunft der orcs des schwarzfels","woher kommen die orcs"}},["9f02e3ae"]={q="Sind die Orcs des Schwarzfels dieselben Orcs aus den Kriegen?",a="Ja. Sie sind abgehärtete Veteranen und direkte Nachkommen des Clans des Schwarzfels aus dem Erster Krieg und Zweiter Krieg, die sich weigerten, sich zu ergeben oder Thralls neuem schamanistischen Pfad zu folgen. Sie behalten ihre ursprünglichen blutrünstigen Praktiken und ihre dunkle Magie bei und halten fest an ihrer ursprünglichen Mission, die menschlichen Königreiche auszulöschen.",al={"stammen die orcs des schwarzfels aus dem ersten krieg","orcs des schwarzfels aus dem zweiten krieg","sind das dieselben orcs aus den alten kriegen"}},["09fb7c4a"]={q="Was sind die Gnolle des Rotkammgebirges? Warum greifen sie an?",a="Die örtlichen Shadowhide-Gnolle sind wilde, hyänenartige Humanoide, die die Hügel und Täler des Rotkammgebirges bewohnen. Obwohl sie von Natur aus territorial und räuberisch sind, wird ihre derzeitige koordinierte Gewalt von dunklen Einflüssen angetrieben, die ihre verstreuten Rudel zu einer organisierten Armee vereint haben, die darauf aus ist, menschliche Siedlungen abzuschlachten.",al={"gnolle im rotkammgebirge","warum greifen gnolle das rotkammgebirge an","shadowhide-gnolle"}},ba7471d2={q="Arbeiten die Gnolle mit den Orcs zusammen?",a="Die Shadowhide-Gnolle dienen dem abtrünnigen Hexenmeister Morganth im Turm von Ilgalar. Ihre Beziehung zu den Orcs des Schwarzfels kann durch Berichte untersucht werden, die in der Region geborgen wurden.",al={"sind gnolle und orcs verbündet","arbeiten gnolle für den schwarzfels","arbeiten orcs und gnolle zusammen"}},["74e139ea"]={q="Wer ist Yowler?",a="Yowler ist der Anführer der Gnolle des Rotkammgebirges. Er haust in den Hügeln oberhalb von Seenhain und versammelt das Rudel gegen die Stadt. Verner Gutmark bittet Abenteurer, ihn zu besiegen und seine Pfote zurückzubringen.",al={"wer ist yowler","yowler gnollanführer","yowler rotkammgebirge"}},b25dfaa0={q="Warum ist die The Everstill Bridge kaputt und warum ist das wichtig?",a="Die The Everstill Bridge ist schwer beschädigt. Sie ist von enormer Bedeutung, da sie den schmalen Hals des Immerruhsees überspannt und als wichtigste Verkehrsverbindung von Seenhain zum östlichen Ufer und nach Steinwacht dient. Ihre Zerstörung behindert den Handel und die Verteidigung der Stadt und erschwert jeden Gegenangriff auf feindliche Lager.",al={"the everstill bridge zerstört","warum ist die brücke in seenhain zerstört","zerstörte brücke im rotkammgebirge"}},b35f81a4={q="Warum hat Sturmwind die The Everstill Bridge nicht repariert?",a="Sturmwind hat keine Gelder, Vorräte oder Steinmetze zur Unterstützung geschickt. Die Verantwortung liegt vollständig bei den Arbeitern vor Ort unter der Leitung von Großknecht Oslow, deren Reparaturarbeiten ständig durch Murloc-Überfälle und den Verlust von Vorräten unterbrochen und sabotiert werden.",al={"warum wurde die brücke nicht repariert","sturmwind brückenreparatur seenhain","wer repariert die brücke"}},["834d2ea2"]={q="Warum gibt es schwarze Drachenwelpen im Rotkammgebirge?",a="Schwarze Drachenwelpen sind durch die Pässe aus der Brennenden Steppe herabgeströmt und befallen den Uferpfad und die südlichen Schluchten. Sie schleichen durch die felsigen Bergrücken, kundschaften das Gebiet aus und lauern Passanten auf, was als düstere Warnung dient, dass die Brut von Deathwing in der Nähe aktiv ist.",al={"drachenwelpen im rotkammgebirge","schwarze drachen im rotkammgebirge","warum drachenwelpen im rotkammgebirge"}},ce7dd1a7={q="Arbeiten die Drachen mit den Orcs zusammen?",a="Die wachsende Präsenz des Schwarzfels und Sichtungen von schwarzen Drachenwelpen beunruhigen Seenhain. Magistrat Solomon bittet Reisende, seine Sorgen an Hochlord Bolvar Fordragon weiterzuleiten. Weitere Untersuchungen offenbaren die Art der Bedrohung.",al={"sind schwarze drachen mit dem schwarzfels verbündet","bündnis von orcs und drachen","arbeiten orcs des schwarzfels mit drachen"}},["7d7bd3f8"]={q="Warum kämpft hier ein Abenteurer statt der Wachen?",a="Die Wachen von Seenhain sind vollständig mit der Verteidigung des Stadtperimeters beschäftigt, sodass niemand für Offensivangriffe übrig bleibt. Da angeforderte Verstärkungen weiterhin nicht verfügbar sind, haben Magistrat Solomon und Marschall Marris keine andere Wahl, als reisende Abenteurer anzuheuern, um die Orcs zurückzudrängen, die Gnolle auszudünnen und den Uferpfad zu sichern.",al={"warum tue ich das im rotkammgebirge","warum abenteurer im rotkammgebirge","wo sind die wachen im rotkammgebirge"}},["839c7682"]={q="Wo ist die Armee von Sturmwind?",a="Die Streitkräfte von Sturmwind sind überdehnt. Königliche Soldaten verbleiben in Seenhain nach ihrer Niederlage bei Burg Steinwacht, aber die wiederholten Bitten der Stadt nach frischen Truppen und Vorräten haben nicht die Verstärkungen gebracht, die ihre Verteidiger benötigen.",al={"wo sind die soldaten von sturmwind","warum keine armee aus sturmwind","standort der armee von sturmwind"}},de572e98={q="Wie bin ich im Rotkammgebirge gelandet?",a="Ihr seid wahrscheinlich den Straßen von Wald von Elwynn aus nach Osten durch die Kreuzung Drei Ecken gefolgt oder über den Fluss aus den dunklen Wäldern von Dämmerwald im Südwesten gekommen. Als junger Champion, der die menschlichen Lande unterstützt, führen Eure Reisen natürlich hierher, sobald die abgelegenen Probleme rund um Sturmwind nach stärkeren Händen verlangen. Die Hilferufe von Seenhain erreichen die benachbarten Gebiete und ziehen reisende Abenteurer den Uferpfad hinauf in diese umkämpften Höhen.",al={"wie bin ich hierher gekommen","wie habe ich das rotkammgebirge erreicht","warum bin ich ins rotkammgebirge gekommen"}},["85c0e73f"]={q="Was ist das Rotkammgebirge?",a="Das Rotkammgebirge ist eine höhergelegene, malerische Region östlich des Wald von Elwynn und südlich der Brennende Steppe. Bekannt für seine reißenden Flüsse, hoch aufragenden Ulmen und den schimmernden Der Immerruhsee, galt es lange Zeit als eine der friedlicheren Ländereien im südlichen Azeroth. Heute wird seine stille Schönheit durch eindringende Schwarzfels-Orcs, gewalttätige Gnolle und feindselige Murlocs im See erschüttert.",al={"was ist das rotkammgebirge","zone rotkammgebirge","erzähl mir vom rotkammgebirge"}},["5d244582"]={q="Ist das Rotkammgebirge Teil des Königreichs Sturmwind?",a="Ja, das Rotkammgebirge steht unter dem Schutz und der Herrschaft des Königreichs Sturmwind, obwohl seine lokalen Anführer seit dem Zweiter Krieg die täglichen Angelegenheiten weitgehend unabhängig regiert haben. Der Magistrat Solomon aus Seenhain bittet den Thron von Sturmwind immer noch formell um Verteidigung und verlässt sich auf den Handel und die gegenseitige Loyalität der Allianz, selbst wenn königliche Truppen nirgendwo in Sicht sind.",al={"gehört das rotkammgebirge zu sturmwind","ist das rotkammgebirge allianz","ist seenhain teil von sturmwind"}},["8563150d"]={q="Warum gibt es einen See inmitten des Rotkammgebirges?",a="Der Immerruhsee sammelt auf natürliche Weise das Abflusswasser der umliegenden Gebirgszüge. Sein klares, ruhiges Wasser versorgte Seenhain einst mit reichlich Fisch und sauberem Wasser, obwohl es in letzter Zeit von bösartigen Murloc-Stämmen überrannt und von lauernden Dreschern unter der Oberfläche heimgesucht wurde.",al={"warum der immerruhsee","ursprung des sees im rotkammgebirge","was ist der see im rotkammgebirge"}},["8de34bfa"]={q="Was ist im Rotkammgebirge passiert?",a="Das Rotkammgebirge war einst eine friedliche Wiege menschlicher Gehöfte bis zum Erster Krieg, als Kriegshäuptling Schwarzfaust und die Hexenmeister des Schattenrats die Ritter von Sir Anduin Lothar besiegten und die Menschen ins Exil trieben. Nach dem Zweiter Krieg von der Allianz zurückerobert und wiederaufgebaut, wurde die Region kürzlich erneut belagert, nachdem Schwarzfels-Orcs aus den Bergen herabstiegen und Burg Steinwacht einnahmen.",al={"geschichte des rotkammgebirges","was passierte im rotkammgebirge","rotkammgebirge erster krieg"}}},fp="18,271,21.379.0,17.452.0,22.430.0,22.309.1,52.324.0,29.235.0,37.186.0,41.258.0,26.229.0,60.279.0"}
P.entries["zone:riverglades"] = {n="Flusslande",s="In den Flusslanden kämpfen menschliche Loyalisten und Horde-Außenposten noch immer um ein Tal östlich des Ödlands und der Brennenden Steppe. Einst beanspruchte Sturmwind die Region, doch die Alte Horde überrannte sie im Ersten Krieg. Das Rotkammgebirge liegt im Südwesten, die Sümpfe des Elends im Süden und Tanaris jenseits des Meeres.",h="In den Flusslanden kämpfen menschliche Loyalisten und Horde-Außenposten noch immer um ein Tal östlich des...",kw={"schwarzfelspass","bruderschaft des pferds","demar brant","burg farholde","feste krol'dok","hafen von powderfuse","rotkammpass","flusslande","rog'mar","sonnengrund"},ang={["faction:Alliance"]="Als Soldat der Allianz findet Ihr in den Flusslanden alte Wunden, die wieder aufgerissen werden. Überreste der Bruderschaft des Pferds setzen ihren stillen Kreuzzug fort, um Land zurückzuerobern, das Sturmwind während des Ersten Krieges aufgab.",["faction:Horde"]="Für die Horde sichern Außenposten wie Rog'mar einen Küstenstützpunkt und halten den Druck auf die alten menschlichen Festungen östlich des Rotkammgebirges aufrecht.",["race:Human"]="Als Mensch begegnet Ihr in Sonnengrund einem tragischen Kapitel Eurer Herkunft. Der Ort erinnert daran, welchen hohen Preis Euer Königreich im Ersten Krieg an seiner Ostgrenze zahlte."},sec={{t="Ein vergessenes Grenzland",b="Vor dem Ersten Krieg gehörten die Flusslande zum Königreich Sturmwind. Dann fegte die Alte Horde hindurch. Orcs plünderten Sonnengrund, verschonten aber den Magierturm, um menschliche Zauberei zu studieren. Die überlebenden Bewohner versklavten sie. Sturmwind-Soldaten versuchten, die Gefangenen zu befreien und den Ort wieder aufzubauen. Doch das Königreich erklärte das Tal für verloren und sandte seine Streitkräfte zur Verteidigung der Kernlande. Jahrelang erhielt die Krone die Flusslande kaum offiziell unterstützt."},{t="Der Kampf um Farholde",b="Sturmwinds Anführer ließen die Flusslande zurück, doch ihre menschlichen Verteidiger gaben ihre Heimat nie ganz auf. Ritterkommandant Demar Brant führt die verbliebenen Loyalisten der legendären Bruderschaft des Pferds an. Sie halten Burg Farholde gegen die Wildnis und feindliche Eindringlinge. In der Nähe unterhält die moderne Horde eine starke Präsenz an Außenposten wie Rog'mar und Bolder'ok. Der alte Kampf um die Lichtungen geht weiter."},{t="Landschaft und Wege",b="Die Flusslande erstrecken sich entlang der Küste des Verbotenen Meeres, zwischen Bergen und gewundenen Wasserläufen. Nach Westen gelangt Ihr durch den Schwarzfelspass zur Brennenden Steppe. Nach Südwesten führt der Weg durch den Rotkammpass zum Rotkammgebirge. Im Süden liegen die Sümpfe des Elends. Im Nordwesten führen Pfade am Zwielichtschleier vorbei ins Ödland. Vom Hafen von Powderfuse aus könnt Ihr ein Boot über das Meer zum Dampfdruckpier in Tanaris nehmen."}},faq={{q="Was sind die Flusslande?",a="Die Flusslande liegen östlich des Ödlands und der Brennenden Steppe, an der Küste des Verbotenen Meeres. Einst beanspruchte Sturmwind die Region. Heute hält die Allianz Burg Farholde, während die Horde Rog'mar besetzt.",al={"überblick über die flusslande","was ist dieses gebiet","über die flusslande"}},{q="Was geschah mit Sonnengrund?",a="Die Alte Horde überfiel und zerstörte Sonnengrund während des Ersten Krieges. Orcs versklavten die überlebenden Dorfbewohner, ließen aber einen örtlichen Magierturm stehen, um menschliche Magie zu studieren. Sturmwind-Soldaten versuchten, die Gefangenen zu befreien und den Ort wieder aufzubauen. Doch schließlich gab das Königreich das Gebiet auf, um seine Westgrenzen zu verteidigen.",al={"geschichte von sonnengrund","untergang von sonnengrund","was geschah mit dem ort"}},{q="Wer kontrolliert Burg Farholde?",a="Loyalisten der Allianz halten Burg Farholde unter dem Kommando von Ritterkommandant Demar Brant von der Bruderschaft des Pferds. Seine Streitkräfte kämpfen seit Jahren darum, die Flusslande zurückzuerobern, nachdem Sturmwind das Gebiet für verloren erklärt hatte.",al={"wer führt farholde an","allianz in den flusslanden","bruderschaft des pferds"}},{q="Wie gelangt Ihr von den Flusslanden nach Tanaris?",a="Vom Hafen von Powderfuse an der Ostküste der Flusslande fährt regelmäßig ein Küstenboot zum Dampfdruckpier in Tanaris. Es überquert direkt das Meer.",al={"boot nach tanaris","boot vom hafen von powderfuse","wie gelangt man nach tanaris"}},{q="Welche Pässe führen in andere Gebiete?",a="Nach Südwesten gelangt Ihr durch den Rotkammpass zum Rotkammgebirge. Oder Ihr zieht nach Süden zu den Sümpfen des Elends. Westwärts führt der Schwarzfelspass an den Borstenhügeln vorbei zur Brennenden Steppe. Pfade nördlich des Zwielichtschleiers führen direkt ins Ödland.",al={"wie gelangt man nach rotkammgebirge","pässe aus den flusslanden","ausgänge aus den flusslanden"}},{q="Was ist die Feste Krol'dok?",a="Die Feste Krol'dok ist ein befestigter Gewölbekomplex in den Flusslanden und ein bedeutender Sitz feindlicher Macht im umkämpften Gebiet.",al={"feste krol'dok","gewölbe in den flusslanden","welches gewölbe gibt es hier"}}},fp="11,291,22.431.0,25.415.0,20.414.0,24.187.0,28.295.0,27.212.0,46.146.0,34.266.0,28.127.0"}
P.entries["zone:ruinsoflordaeron"] = {n="Ruinen von Lordaeron",s="Über der Unterstadt bergen die Ruinen von Lordaeron noch immer Schrecken aus der gefallenen Hauptstadt. Prinz Arthas und die Geißel brachten das Menschenreich während des Dritten Krieges zu Fall. Nun durchstreifen Allianz und Horde die Oberfläche, um Relikte der Vergangenheit zurückzuerobern oder ihre Bedrohungen zu beseitigen.",h="Über der Unterstadt bergen die Ruinen von Lordaeron noch immer Schrecken aus der gefallenen Hauptstadt.",kw={"bjork","lordaeron captain","new plague","rath'mael","ruinen von lordaeron","the abandoned","the baron","tirisfal","unterstadt","viktor the vile","witherfang"},ang={["class:Paladin"]="Als Paladin durchschreitet Ihr die entweihten Hallen von Lordaeron, der Wiege der Ritter der Silbernen Hand, um Schrecken zu bannen und ruhelose Captains im Dienste des Lichts zur Ruhe zu betten.",["faction:Alliance"]="Als Abenteurer der Allianz könnt Ihr an der Schwelle zur Hauptstadt der Verlassenen zuschlagen und zugleich den Geistern Eurer abgeschlachteten Brüder aus dem Norden Gerechtigkeit und Frieden bringen.",["race:Human"]="Als Mensch seht Ihr die zerstörte Hauptstadt vielleicht als geheiligten Boden, der durch Verrat geraubt wurde, und sucht nach verlorenen Erbstücken und einer Möglichkeit, gefallene Angehörige zu ehren.",["race:Undead"]="Für die Verlassenen sind die Ruinen darüber ihre frühere Heimat und ihr ewiger Friedhof. Sie zu säubern sichert ihre Haustür und versorgt die Apotheker mit Bestandteilen für die Entwicklung der New Plague."},sec={{t="Der Hof eines gefallenen Reiches",b="Capital City hielt einst die Krone der Östlichen Königreiche. König Terenas Menethil II. saß auf ihrem Thron, und die menschliche Zivilisation hatte dort ihren Mittelpunkt. Als Prinz Arthas aus Northrend zurückkehrte, tötete er seinen Vater im Thronsaal und hetzte die Untoten auf das Volk los.\n\nDie Verlassenen leben nun in den Katakomben darunter, in der Unterstadt. Über ihnen ist die Oberfläche eine verlassene Dämmerzone. Zerbrochene Torbögen und von Unkraut überwuchertes Pflaster bieten wilden Bestien wie Witherfang und geistesgestörten Überbleibseln der Vergangenheit Zuflucht."},{t="Qual und Seuche",b="Die ruhelosen Toten sind nicht die einzige Gefahr auf dem verwüsteten Gelände. Apotheker und finstere Gestalten wie Viktor the Vile erproben im Schatten neue Seuchen, während verdrehte Experimente wie The Abandoned frei umherstreifen.\n\nZornige Geister wie Rath'mael und verfluchte Gefolgsleute wie The Baron spuken durch die eingestürzten Hallen, gefangen in endloser Qual. Sie greifen jeden lebenden oder untoten Eindringling an, der ihren Weg kreuzt."},{t="Geister der königlichen Garde",b="Geisterhafte Verteidiger verweilen in den oberen Ruinen, darunter ein geisterhafter Lordaeron Captain. Noch immer an ihre zerbrochenen Eide gebunden, sehen diese Erscheinungen jeden, der sich dem Thron nähert, als Eindringling. Den Captain und seine Soldaten zur Ruhe zu betten, beendet eine bittere Wacht, die seit dem Fall der Hauptstadt andauert."}},faq={{q="Wo liegt der Dungeon Ruinen von Lordaeron?",a="Der Dungeon Ruinen von Lordaeron erstreckt sich über die Oberfläche von Capital City in Tirisfal, direkt über dem Eingangsnetz, das hinab zur Hauptstadt der Verlassenen, der Unterstadt, führt.",al={"lage der ruinen von lordaeron","wo liegt der dungeon lordaeron","eingang zum dungeon unterstadt"}},{q="Warum interessieren sich Horde und Allianz für diesen Ort?",a="Die Allianz wagt sich nach Lordaeron, um verlorene Familienerbstücke zu bergen, königliche Wappen zu sammeln und gefallenen Vorfahren Frieden zu bringen. Die Horde, insbesondere die Verlassenen, will den Umkreis der Unterstadt sichern und Forschungsproben für die neue Seuche der Königlichen Apothekervereinigung beschaffen.",al={"warum zu den ruinen von lordaeron","allianzquests in lordaeron","hordenquests in lordaeron"}},{q="Wer ist Viktor the Vile?",a="Viktor the Vile ist eine finstere Gestalt, die die Gesetzlosigkeit in den Ruinen für ihre üblen Experimente ausnutzt. Seine Arbeit trägt zur Verderbnis und zu den verdrehten Abscheulichkeiten bei, die die obere Hauptstadt verseuchen.",al={"lore zu viktor the vile","wer ist viktor the vile"}},{q="Was ist „The Abandoned“, dem man in den Ruinen begegnet?",a="The Abandoned ist ein groteskes untotes Ungeheuer, das in den Ruinen zurückgelassen wurde. Wie viele zusammengeflickte Schrecken, die während oder nach der Eroberung durch die Geißel erschaffen wurden, wandert es ziellos durch die verfallenen Gemächer und greift alles an, was ihm begegnet.",al={"boss the abandoned","wer ist the abandoned"}},{q="Was bedeutet es für die Geschichte, den Lordaeron Captain zu besiegen?",a="Der Sieg über den geisterhaften Lordaeron Captain befreit einen hochrangigen königlichen Verteidiger von einer ewigen, zermürbenden Pflicht. Seit dem ersten Massaker der Geißel an die Ehre gebunden, hat der Captain jahrelang ein zerstörtes Königreich bewacht, und diese Wacht dauert seit dem Fall der Hauptstadt an. Den Captain zur Ruhe zu betten, beendet einen qualvollen Kreislauf geisterhafter Knechtschaft und ermöglicht es, das blutbefleckte Abzeichen zurückzuerobern.",al={"lordaeron captain besiegen","bedeutung des lordaeron captain","was passiert, wenn der captain stirbt"}},{q="Sind die Ruinen von Lordaeron von der Unterstadt getrennt?",a="Ja. Die Verlassenen leben in den Höhlen der Unterstadt darunter, während die Ruinen an der Oberfläche eine aktive Kampfzone bleiben. Dort lauern ruhelose Geister, wilde Raubtiere und experimentelle Bedrohungen, die die Verlassenen noch nicht vollständig beseitigt haben.",al={"liegt die unterstadt in diesem dungeon","ruinen oder unterstadt"}}},fx={["1b77984b"]={q="Was ist dieser Ort, die Ruinen von Lordaeron?",a="Ihr steht in den zertrümmerten Überresten der Hauptstadt, einst das Juwel der menschlichen Zivilisation und das Herz des Königreichs Lordaeron. Während des Dritten Krieges verriet Prinz Arthas sein Königreich, schlachtete seinen Vater König Terenas im Thronsaal darüber ab und entfesselte die untote Geißel auf ihren Straßen. Heute liegen ihre zerbrochenen Bögen und versengten Türme über der unterirdischen Unterstadt und dienen als bitteres Denkmal für das gefallene Königreich.",al={"was sind die ruinen von lordaeron","hintergrundgeschichte ruinen von lordaeron","was war das für ein ort"}},eb89374f={q="Wer lebte hier, bevor es zerstört wurde?",a="Diese Stadt war die Heimat des größten nördlichen Königreichs der Menschheit, regiert von der Menethil-Dynastie. Adlige, Priester des Heiligen Lichts, Soldaten und Hunderttausende einfacher Leute gingen einst über diese gepflasterten Straßen. Tragischerweise haben viele dieser ehemaligen Bürger ihre Heimat nie wirklich verlassen; von der Pest dahingerafft, bilden ihre wiederbelebten Leichen sowohl die gedankenlose Geißel, die die Pestländer heimsucht, als auch die befreiten Verlassenen, die nun in den Höhlen darunter wohnen.",al={"wer lebte hier früher","ursprüngliche bewohner von lordaeron","wer war zuerst hier"}},["6e6195fd"]={q="Warum ist hier alles kaputt und verbrannt?",a="Als Prinz Arthas mit Frostgram zurückkehrte, erschlug er König Terenas und überließ die Stadt der Geißel. Untote Schrecken wüteten durch die Alleen, brannten Gebäude nieder und metzelten jeden nieder, der versuchte, Widerstand zu leisten. Später, während des Bürgerkriegs unter den Untoten, kämpften Sylvanas Windläufer und ihre Verlassenen gegen Schreckenslords und verbliebene Legionen der Geißel durch genau diese Innenhöfe und rissen nieder, was von der großartigen Architektur der Stadt übrig geblieben war.",al={"warum ist lordaeron zerstört","wie wurde lordaeron verbrannt","warum ist es in ruinen"}},dd470a5c={q="Wer hat Lordaeron zerstört?",a="Das Königreich wurde von innen heraus durch seinen eigenen Kronprinzen, Arthas Menethil, unter dem korrumpierenden Flüstern des Lichkönigs zertrümmert. Ausgesandt, um den Kult der Verdammten und ihre Pest der Untoten aufzuhalten, wurde Arthas rücksichtslos, nahm die verfluchte Runenklinge Frostgram im gefrorenen Norden an und ergab seine Seele. Als Todesritter zurückkehrend, schlug er seinen Vater nieder und lieferte die Stadt den Klauen der Geißel aus.",al={"wer hat lordaeron zerstört","wer brachte lordaeron zu fall","zerstörer von lordaeron"}},f5a9164f={q="Wo ist Arthas jetzt?",a="Arthas verließ den zerstörten Kontinent Lordaeron vor Jahren und segelte zurück über Das große Meer nach Nordend, als der Lichkönig vom Dämonenjäger Illidan Sturmgrimm bedroht wurde. Er kämpfte sich die eisige Spitze des Frostthrons hinauf und ist aus dem Blickfeld der Allgemeinheit in den gefrorenen Einöden verschwunden, wobei er ein Königreich hinterließ, das in rivalisierende Fraktionen von Untoten und Überlebenden zersplittert ist.",al={"wohin ist arthas gegangen","wo ist prinz arthas","arthas standort"}},["2fe0baef"]={q="Ist jemand aus der Stadt entkommen?",a="Ein paar Glückliche entkamen dem Gemetzel. Vor dem endgültigen Zusammenbruch achtete die Zauberin Jaina Prachtmeer auf die Warnungen eines mysteriösen Propheten und führte Tausende menschlicher Flüchtlinge über das Meer nach Kalimdor, wo sie den Hafen von Theramore gründeten. Andere flohen nach Süden in Richtung des Königreichs Sturmwind oder griffen zu den heiligen Waffen, um zurückzukämpfen, wobei sie den fanatischen Scharlachroten Kreuzzug und die wachsame Argentumdämmerung bildeten.",al={"haben bürger von lordaeron überlebt","hat jemand den fall von lordaeron überlebt","überlebende von lordaeron"}},["9cf7434f"]={q="Warum gibt es eine Stadt der Untoten unter den Ruinen?",a="Als die Macht des Lichkönigs schwand, brach Sylvanas Windläufer dessen mentale Kontrolle über eine Vielzahl von Untoten. Sie nannten sich die Verlassenen und stürzten die dämonischen Schreckenslords, die die Hauptstadt hielten. Die Ruinen darüber waren zu exponiert für feindliche Augen und ständige Angriffe des Scharlachroten Kreuzzugs, also entschied Sylvanas, die riesigen unterirdischen Krypten und Kanalisationen in eine schwer befestigte Festung zu verwandeln.",al={"warum existiert die unterstadt","warum ist die unterstadt unter lordaeron","untote stadt unter ruinen"}},["55ddf3da"]={q="Wer hat die Unterstadt gebaut?",a="Das Fundament begann unter der Hauptstadt als königliche Verliese, Kanalisationen und tiefe Krypten, die von den Menschen von Lordaeron erbaut wurden. Während des Dritten Krieges begannen Arthas und die Geißel, diese unterirdischen Korridore zu einem ausgeklügelten Netzwerk zu erweitern, das ein Zentrum der Macht der Geißel werden sollte. Nachdem sie dem Schreckenslord Varimathras die Kontrolle entrissen hatten, vollendeten Sylvanas und die Verlassenen den Ausbau der Unterstadt als ihre ständige Hauptstadt.",al={"wer erschuf die unterstadt","konstruktion der unterstadt","wer hat die unterstadt ausgegraben"}},c0ee4f6f={q="War die Unterstadt schon immer da unten?",a="Nicht in ihrem modernen, weitläufigen Zustand. Zu Zeiten von König Terenas bestand das Untergeschoss lediglich aus Schlossverliesen, Aquädukten, Abwasserkanälen und Familiengräbern. Erst nach dem Fall des Königreichs höhlten Abscheulichkeiten der Geißel und Arbeiter der Verlassenen die massiven Ringe und Viertel aus, die Ihr heute seht, und verwandelten Versorgungstunnel in eine weitläufige unterirdische Bastion der Toten.",al={"war die unterstadt schon immer da","existierte die unterstadt vorher","alte unterstadt"}},dc41e367={q="Wer hat hier das Sagen?",a="Fürstin Sylvanas Windläufer, die Banshee-Königin, befehligt diese Ruinen und die Unterstadt darunter. Einst die Waldläufergeneralin von Silbermond, wurde sie von Arthas erschlagen, als rachsüchtige Banshee wiedererweckt und holte sich schließlich ihre physische Leiche zurück. Durch reine Willenskraft und List befreite sie ihre untoten Brüder und Schwestern und schmiedete die Verlassenen, die sie mit rücksichtsloser Entschlossenheit von ihrem Thron im Royal Quarter aus führt.",al={"wer regiert die ruinen von lordaeron","anführer der unterstadt","wer kontrolliert diesen ort"}},["3d3094f9"]={q="Ist Sylvanas eine Königin oder etwas anderes?",a="Ihr Volk verehrt sie als Banshee-Königin und Fürstin der Verlassenen, aber sie ist kein erblicher Adel von Lordaeron. Der Titel spiegelt die tragische Natur ihres Todes durch die Hand von Prinz Arthas wider, der ihre Seele aus ihrem Körper riss, damit sie als wimmernde Banshee dienen konnte. Obwohl der Titel an Monarchie erinnert, entspringt ihre Autorität der Befreiung, dem Überleben und dem absoluten militärischen Kommando.",al={"ist sylvanas eine königin","titel banshee-königin","was ist sylvanas titel"}},ac534dbb={q="Antwortet Sylvanas Thrall gegenüber?",a="Auf dem Papier erkennt Sylvanas Kriegshäuptling Thrall als den obersten Befehlshaber der Horde an, und sie stimmte ihrer Zweckallianz zu. In der Realität behält die Banshee-Königin die vollständige Autonomie über die Verlassenen und ihre nördlichen Gebiete. Thralls Wort wird respektiert, und Gesandte der Verlassenen laufen in Orgrimmar umher, aber Fürstin Sylvanas antwortet in erster Linie ihrem eigenen Überleben und den Ambitionen ihres Volkes.",al={"beziehung sylvanas thrall","gehorcht sylvanas thrall","steht sylvanas unter thrall"}},["6b51523d"]={q="Was ist in diesem Thronsaal dort oben die Treppe hinauf passiert?",a="Der Thronsaal war der Ort des katastrophalen Verrats, der das Königreich beendete. Prinz Arthas, frisch zurückgekehrt aus Nordend, marschierte an willkommen heißenden Bürgern und läutenden Glocken vorbei in diese Kammer. Als sein Vater, König Terenas, sich vom Thron erhob, um ihn zu begrüßen, zog Arthas Frostgram, verkündete, dass er seinem Vater nachfolgen würde, und stieß die verfluchte Runenklinge durch das Herz des alten Königs.",al={"was passierte im thronsaal","geschichte thronsaal von lordaeron","thronsaal historisch"}},["6e83c082"]={q="Ist das die Stelle, an der Terenas getötet wurde?",a="Ja. Wenn Ihr direkt vor das zerbrochene Podest tretet, steht Ihr auf genau den Pflastersteinen, auf denen König Terenas Menethil II. seinen letzten Atemzug tat. Ein schwacher, dunkler Fleck ist auf dem Steinboden immer noch sichtbar, von dem es heißt, er sei das Blut des alten Königs, das in das Mauerwerk sickerte, als sein Sohn ihn niederschlug. Selbst jetzt hallen spektrales Flüstern und Glocken leise in der Kammer nach.",al={"wo wurde terenas getötet","ist das terenas blut","ort an dem könig terenas starb"}},ea8d978d={q="Was ist mit Terenas' Krone passiert?",a="Terenas' goldene Krone fiel zu Boden, als Arthas ihn im Thronsaal ermordete. Ihr Fall markiert das Ende seiner Herrschaft und die Katastrophe, die Lordaeron ereilte.",al={"warum liegt die krone auf dem boden","könig terenas krone ruinen","terenas krone blut"}},bb044bc8={q="Sind die Verlassenen tatsächlich Teil der Horde?",a="Ja, obwohl es größtenteils ein Pakt zum gegenseitigen Überleben ist. Umgeben vom Scharlachroten Kreuzzug, feindseligen Menschen und der verbleibenden Geißel sandten die Verlassenen Botschafter über das Meer, um Verbündete zu suchen. Die Horde, die einen Stützpunkt in den Östlichen Königreichen benötigte, um der Allianz entgegenzuwirken, stimmte zu, ihnen den Eintritt zu gewähren, was den Verlassenen dringend benötigte militärische Unterstützung und internationales Ansehen verschaffte.",al={"verlassene horde allianz","sind untote in der horde","warum sind die verlassenen bei der horde"}},["50000697"]={q="Warum hat Thrall Untote in die Horde aufgenommen?",a="Thrall wurde hauptsächlich durch die Fürsprache von Erzruide Hamuul Runetotem und den Tauren überzeugt, die glaubten, die Verlassenen seien tragische Opfer, die eines Tages Erlösung oder ein Heilmittel für ihr Leiden finden könnten. Darüber hinaus erkannte Thrall die strategische Notwendigkeit eines etablierten Stützpunkts in den Östlichen Königreichen, um zu verhindern, dass die Allianz den nördlichen Kontinent unangefochten dominiert.",al={"warum erlaubte thrall die untoten","thrall verlassene grund","warum nahm die horde die verlassenen auf"}},["9af0f393"]={q="Vertrauen ihnen die Orcs und Tauren?",a="Nicht vollständig. Während die Tauren sie mit tiefem Mitleid betrachten und hoffen, ihr Leiden zu heilen, hegen viele Orcs tiefe Bedenken gegenüber dunkler Magie, Nekromantie und der finsteren Natur der Unterstadt. Thrall behält Sylvanas' Handlungen genau im Auge, und stationierte Botschafter sind misstrauisch gegenüber dem, was in den Laboren der Royal Apothecary Society gebraut wird.",al={"vertrauen orcs den verlassenen","tauren verlassene vertrauen","vertraut die horde untoten"}},["849f698a"]={q="Ist es sicher für mich, hier zu stehen?",a="Das hängt ganz von Eurer Loyalität ab. Wenn Ihr für die Horde kämpft, erkennen die Verlassenen und ihre Abscheulichkeiten Euch als Verbündeten an, obwohl die Schatten darüber zwielichtige Kreaturen und verweilende Geister bergen. Wenn Ihr unter dem Banner der Allianz marschiert, befindet Ihr Euch tief im Feindesland; Wachen der Verlassenen und Schreckenswachen werden Euch auf Sicht niederschlagen.",al={"sind die ruinen von lordaeron sicher","bin ich hier sicher","gefahr in lordaeron stehen"}},aac358a1={q="Werden mich die Wachen angreifen?",a="Todeswachen der Verlassenen und königliche Monstrositäten, die rund um die Ruinen stationiert sind, werden Reisende der Horde ignorieren oder beschützen, doch sie sind gegenüber Champions der Allianz brutal feindselig. Zudem lauern in den isolierten Korridoren und Dungeon-Flügeln der Ruinen oben feindselige Abtrünnige und Monster, die jeden angreifen, der ihren Weg kreuzt, ungeachtet der Loyalität.",al={"greifen unterstadt-wachen an","sind ruinen-wachen feindselig","greifen mich wachen an"}},e9ec8c01={q="Gibt es immer noch Geißel in der Nähe?",a="Ja. Während Sylvanas den Großteil der Geißel aus der Hauptstadt vertrieben hat, ist die Geißel gleich hinter den Grenzen in den Westlichen Pestländern noch stark verschanzt. Selbst in den dunkleren Nischen und vergessenen Untergeschossen dieser Ruinen halten sich noch geistlose Untote und Überbleibsel der Geißel auf, die nur darauf warten, jedes lebende Fleisch zu zerfetzen, das sich zu weit vorwagt.",al={"geißel in ruinen von lordaeron","ist die geißel in der nähe der unterstadt","gibt es dort geißel"}},["0a975308"]={q="Was ist das für eine Seuche, von der alle reden?",a="Sie sprechen von der Seuche des Untodes, einem schrecklichen biomagischen Ansteckungsherd, der vom Lichkönig und seinen Nekromanten entwickelt wurde. Durch den Kult der Verdammten über infiziertes Getreide in ganz Lordaeron verteilt, tötete sie jeden, der es innerhalb weniger Stunden verzehrte, und belebte ihre Leichen sofort als gehorsame, verrottende Knechte der Geißel wieder.",al={"was ist die seuche des untodes","welche seuche ist gemeint","lordaeron-seuche"}},["290f94a8"]={q="Wer hat die ursprüngliche Seuche erschaffen?",a="Die ursprüngliche Seuche wurde von den Schreckenslords der Brennenden Legion entwickelt und vom Lichkönig, Ner'zhul, perfektioniert, während er auf dem Frostthron in Nordend gefangen war. Um sie in Lordaeron freizusetzen, rekrutierte er den abtrünnigen Dalaran-Erzmagier Kel'Thuzad, der den Kult der Verdammten gründete und die Getreidevorräte vergiftete.",al={"wer erschuf die seuche des untodes","schöpfer der ursprünglichen seuche","wer machte die seuche"}},["89f62638"]={q="Stellt Sylvanas eine neue her?",a="Ja. Lady Sylvanas hat die Königliche Apothekergesellschaft damit beauftragt, eine 'neue Seuche' zu brauen. Ihr Ziel ist es, eine Biowaffe zu erschaffen, die stark genug ist, um sowohl die Geißel als auch die Lebenden gleichermaßen auszulöschen, um so das Überleben der Verlassenen und die Rache an Arthas zu sichern. Ihre geheimen Tests finden genau jetzt im Apothekarium unter uns statt.",al={"erschafft sylvanas eine seuche","neue seuche der verlassenen","neue seuche unterstadt"}},dcb566d2={q="Wer ist der Lichkönig und was will er?",a="Der Lichkönig ist der oberste Herrscher der Geißel, erschaffen aus dem gequälten Geist des Orc-Schamanen Ner'zhul, der auf dem Frostthron in Eis eingeschlossen war. Sein Ziel war es, Azeroth für die Brennende Legion weichzuklopfen, aber er hegte seine eigenen schrecklichen Ambitionen: alles sterbliche Leben auszurotten und es durch ein ewiges, vereintes Imperium des Untodes unter seinem absoluten mentalen Befehl zu ersetzen.",al={"wer ist der lichkönig","was will der lichkönig","motive des lichkönigs"}},["3a9893a7"]={q="Wo ist der Lichkönig jetzt?",a="Er regiert vom Frostthron auf dem Eiskronengletscher auf dem fernen, gefrorenen Kontinent Nordend aus. Nach Illidans Angriff, der sein eisiges Gefängnis zum Bersten brachte, rief der Lichkönig Arthas nach Nordend zurück, um ihre Geister zu verschmelzen und seine Macht zu bewahren, weit weg vom zerstörten Königreich Lordaeron.",al={"wo ist der lichkönig","standort des lichkönigs","wo ist der frostthron"}},["0138c577"]={q="Kontrolliert er immer noch die Verlassenen?",a="Nein. Als der Frostthron durch Illidans Zauberei gespalten wurde, begann der telepathische Griff des Lichkönigs zu brechen. Sylvanas und viele andere Untote erlangten ihren freien Willen zurück und lösten sich aus seinem kollektiven Geist. Obwohl er versucht, sie zurückzugewinnen, widerstehen die Verlassenen nun gewaltsam seinem Flüstern und kämpfen erbittert, um ihre Autonomie zu wahren.",al={"kontrolliert der lichkönig die verlassenen","kann der lichkönig die verlassenen befehligen","freier wille der verlassenen"}},["6a523c60"]={q="Wer ist der Scharlachrote Kreuzzug und warum hassen sie Untote?",a="Der Scharlachrote Kreuzzug ist ein Orden religiöser, menschlicher Fanatiker, der aus den zerschlagenen Überresten der Ritter der Silbernen Hand und den Rittern von Lordaeron gebildet wurde. Traumatisiert von der Seuche, die ihre Heimat zerstörte, sind sie von Paranoia zerfressen. In ihren Augen sind alle Untoten ausnahmslos Abscheulichkeiten, und jeder Lebende, der mit ihnen verkehrt, gilt als befleckt und ist zur Hinrichtung markiert.",al={"wer ist der scharlachrote kreuzzug","warum hasst der scharlachrote kreuzzug untote","scharlachroter kreuzzug lore"}},b59db3a3={q="Sind sie dieselben wie die Argentumdämmerung?",a="Nein, sie sind bittere Rivalen mit gemeinsamen Wurzeln. Beide gingen aus der Asche der Ritter der Silbernen Hand hervor, doch als der Scharlachrote Kreuzzug blinder Fanatik und Fremdenfeindlichkeit verfiel, spalteten sich gemäßigte Paladine ab, um die Argentumdämmerung zu gründen. Die Dämmerung heißt alle Völker willkommen und konzentriert sich darauf, das Land gegen die Geißel zu verteidigen, statt wahllos zu säubern.",al={"scharlachroter kreuzzug gegen argentumdämmerung","sind scharlachrote und argentumdämmerung gleich","unterschied zwischen scharlachroten und argentum"}},ca88b6f6={q="Greifen sie auch lebende Spieler an?",a="Ja. Der Scharlachrote Kreuzzug glaubt, dass jeder, der nicht ihr purpurrotes Wappen trägt, insgeheim die Seuche in sich trägt oder mit den Untoten kollaboriert. Ob Ihr ein Orc, ein Taure, ein Nachtelf oder ein menschlicher Soldat aus Sturmwind seid, ihre Fanatiker werden Euch als Träger der Verderbnis brandmarken und auf Sicht angreifen.",al={"greift der scharlachrote kreuzzug die allianz an","greifen scharlachrote lebende an","scharlachroter kreuzzug feindselig gegenüber lebenden"}},["861c7602"]={q="Was macht die Königliche Apothekergesellschaft da unten?",a="Diese finstere Gilde aus Apothekern und ehemaligen Magiern der Verlassenen operiert vom Apothekarium in der Unterstadt aus und arbeitet unermüdlich unter Lady Sylvanas' Dekret. Ihr Hauptauftrag ist die Entwicklung einer katastrophalen 'neuen Seuche', die sowohl die Geißel als auch die lebenden Völker auslöschen kann, wobei sie rücksichtslose Experimente durchführen, um die Vorherrschaft der Verlassenen zu sichern.",al={"was macht die königliche apothekergesellschaft","zweck der königlichen apothekergesellschaft","apotheker unterstadt"}},["3c47ce18"]={q="Experimentieren sie an Menschen?",a="Ja. Tief im Apothekarium sind gefangene Kreuzfahrer des Scharlachroten Kreuzzugs, Ghule der Geißel und verschiedene Bestien in Eisenkäfigen eingesperrt. Die Apotheker unterziehen diese Gefangenen schmerzhaften chemischen Cocktails und bösartigen Seuchenstämmen, um auszuwerten, wie schnell Fleisch verrottet und wie die Ansteckung sowohl lebende als auch nekrotische Physiologie beeinflusst.",al={"experimentiert apotheker an menschen","experimente der königlichen apothekergesellschaft","foltern unterstadt-apotheker menschen"}},f7d23701={q="Ist Arthas noch am Leben, und könnte ich jemals gegen ihn kämpfen?",a="Arthas ist nicht im sterblichen Sinne tot, sondern vollständig zu einem Todesritter-Champion der Geißel korrumpiert. Er ist weit über das Meer in Nordend, außerhalb der Reichweite von jedem in Lordaeron. Euer Kampf findet genau jetzt gegen die Bedrohungen statt, die hier verweilen: die lokalen Kommandeure der Geißel, der Scharlachrote Kreuzzug und die abtrünnigen Bestien, die diese Ruinen befallen.",al={"kann ich gegen arthas kämpfen","ist arthas am leben","werden wir arthas gegenüberstehen"}},["9fc2648e"]={q="Ist er jetzt der Lichkönig?",a="Flüstereien aus dem Norden behaupten, dass Arthas die Turmspitze von Eiskrone bestieg, um den Lichkönig aus Illidans Belagerung zu befreien, das Eis zerschlug, um den Helm der Herrschaft aufzusetzen und seine Seele mit Ner'zhul zu verschmelzen. Für die Welt im Allgemeinen bleibt der genaue Zustand Nordends in eisiges Geheimnis gehüllt, aber seine dunkle Präsenz lastet über allen Untoten.",al={"ist arthas der lichkönig","wurde arthas zum lichkönig","identität von arthas als lichkönig"}},["89a21402"]={q="Wie bin ich in den Ruinen von Lordaeron gelandet?",a="Ihr seid durch die zerbröckelnden äußeren Tore der gefallenen Hauptstadt in Tirisfal gegangen, direkt über den Aufzügen, die in die Unterstadt hinabführen. Ob Ihr einem militärischen Ruf gefolgt seid, Gerüchten über ungezügelte Schrecken nachgegangen seid, die an der Leiche des Königreichs kleben, oder feindliches Gebiet durchquert habt, um heilige Überbleibsel der Vergangenheit zurückzuerobern – Eure Reise führte Euch in die versiegelten, umkämpften Innenhöfe, wo die Schatten der Geißel und die Geister der alten Menschheit noch immer verweilen.",al={"wie kam ich hierher","wie landete ich hier","warum bin ich in den ruinen von lordaeron","wie bin ich hier angekommen"}},bb4abd7f={q="Was soll ich in den Ruinen von Lordaeron tun?",a="Ihr seid hier, um die Schrecken zu säubern, die in den Ruinen an der Oberfläche über der Hauptstadt der Verlassenen eitern. Für die Horde bedeutet das, abtrünnige Bestien der Geißel zu jagen, verlorene Insignien zurückzuholen und tödliche Gebräue für die Königliche Apothekergesellschaft zu testen. Für die Allianz ist es ein verdeckter Schlag, um angestammten Boden zu reinigen, heilige Erbstücke wie das Crest of Lordaeron zurückzuholen und wandernden, gequälten Geistern Trost zu spenden, die noch keinen Frieden gefunden haben.",al={"was mache ich hier","was ist meine mission hier","was soll ich in den ruinen tun","was ist mein ziel hier"}}},fp="18,278,27.503.0,22.413.0,25.302.1,48.174.0,61.277.0,23.179.0,49.228.0,61.384.1,54.227.0"}
P.entries["zone:scarlet"] = {n="Das Scharlachrote Kloster",s="In den nordöstlichen Hügeln von Tirisfal bietet Das Scharlachrote Kloster dem Scharlachroten Kreuzzug hinter befestigten Mauern Schutz. Einst war es ein friedliches Heiligtum und ein Zentrum der Gelehrsamkeit für die Kirche des Heiligen Lichts. Heute beherbergen seine vier Flügel Eiferer, die trainieren, Gefangene foltern und Krieg gegen Außenstehende führen.",h="In den nordöstlichen Hügeln von Tirisfal bietet Das Scharlachrote Kloster dem Scharlachroten Kreuzzug hinter...",kw={"waffenkammer","kathedrale","doan","friedhof","herod","library","mograine","scharlachroter kreuzzug","das scharlachrote kloster","tirisfal","whitemane"},ang={["class:Mage"]="Der Flügel Library birgt seltene historische und theologische Werke. Arkanist Doan, der bedeutendste Arkanist des Kreuzzugs, bewacht sie.",["class:Paladin"]="Das Scharlachrote Kloster war einst ein heiliges Zentrum der Priesterschaft von Lordaeron und ein Ort der Gelehrsamkeit. Sein Fall an den scharlachroten Fanatismus zeigt, wie Hingabe in Wahnsinn umschlagen kann.",["class:Priest"]="Das Scharlachrote Kloster begann als Sitz der Kirche des Heiligen Lichts. Seine prächtigen Kapellen zeigen heilige Macht, die von Sterblichen eingesetzt wird, die von Hass und Rache verdorben sind.",["race:Undead"]="An der Grenze von Tirisfal bedroht Das Scharlachrote Kloster die Verlassenen. Seine Spione reichen bis nach Todesend, und in seinen Verliesen werden gefangene Untote gefoltert."},sec={{t="Ein gefallener Zufluchtsort",b="Vor dem Dritten Krieg war Das Scharlachrote Kloster ein stolzer Sitz der Priesterschaft von Lordaeron, die sich der Gelehrsamkeit und Erleuchtung verschrieben hatte. Dann verwüstete die Geißel das Land. Die überlebenden Kreuzfahrer säuberten die Hallen von Untoten und Spinnen und machten aus den Archiven und Innenhöfen eine befestigte Garnison.\n\nTrauer und Furcht verhärteten sich zu Misstrauen. Der Scharlachrote Kreuzzug begann, jeden Außenstehenden als Träger der Seuche zu sehen, ob lebendig oder untot, Mensch oder andersartig. In ihren Augen müssen solche Feinde mit Feuer geläutert werden."},{t="Die vier Flügel",b="Hinter dem Grand Vestibule liegen vier Flügel. Auf dem Friedhof erheben sich gefallene Kreuzfahrer als untote Scheusale, während Folterer Gefangenen Geständnisse abpressen. Die Library birgt theologische und historische Werke, bewacht vom abtrünnigen Magier Arkanist Doan und seinen Hunden.\n\nIn der Waffenkammer bilden Waffenmeister wie Herod Rekruten zu disziplinierten Kriegern aus. Tief in der Festung liegt die Kathedrale, das Herz des Kreuzzugs. Von dort lenken seine Anführer ihren Feldzug durch den verheerten Norden."},{t="Der Fall des Hochinquisitors",b="Scharlachroter Kommandant Mograine befehligt das innere Heiligtum der Kathedrale an der Seite der wahren Herrin des Klosters, Hochinquisitor Whitemane. Whitemane kanalisiert das Heilige Licht und kann gefallene Champions wiedererwecken. Für ihre Anhänger lässt diese Macht die Garnison unbesiegbar erscheinen.\n\nWhitemanes Niederlage trifft die Führung des Kreuzzugs in Tirisfal. Sie zerstört den Anschein göttlicher Autorität, der den Eifer des Klosters nährt. Die Anführer des Kreuzzugs sind sterblich, und ihr Feldzug gegen die Verlassenen und die benachbarten Lande wird stark geschwächt."}},faq={{q="Warum ist der Scharlachrote Kreuzzug lebenden Abenteurern der Allianz feindlich gesinnt?",a="Der Scharlachrote Kreuzzug ist dem Wahnsinn und der Paranoia verfallen. Seine Mitglieder sehen jeden ohne ein karmesinrotes Wappenrock als möglichen Träger der Seuche der Geißel. Sie unterscheiden nicht zwischen Freund und Feind und glauben, jeder Außenstehende sei verdorben und müsse geläutert werden, bevor er die Verderbnis verbreitet.",al={"warum greifen scharlachrote menschen an","scharlachroter kreuzzug feindlich gegenüber allianz","warum sind sie wahnsinnig"}},{q="Was geschieht, wenn Ihr Hochinquisitor Whitemane besiegt?",a="Hochinquisitor Whitemanes Niederlage versetzt der Führung des Scharlachroten Kreuzzugs im Westen einen schweren Schlag. Als geistliche Führerin des Klosters erweckt sie die Gefallenen wieder und hält Kommandant Mograine an ihrer Seite im Kampf. Ihr Tod bringt die Garnison aus dem Gleichgewicht und schwächt ihre Bedrohung für die umliegende Region.",al={"was bedeutet whitemanes tod","lore zu whitemanes niederlage","ende der kathedrale"}},{q="Was ist der Scarlet Key und wo findet Ihr ihn?",a="Arkanist Doan bewahrt den Scarlet Key in seiner Geldkassette tief im Flügel Library hinter seinem Studierzimmer auf. Der Schlüssel öffnet die äußeren Tore der Flügel Waffenkammer und Kathedrale.",al={"wo ist der scarlet key","waffenkammer und kathedrale öffnen","klosterschlüssel"}},{q="Warum ist Arkanist Doan im Scharlachroten Kloster?",a="Arkanist Doan ist ein mächtiger menschlicher Magier, der dem Scharlachroten Kreuzzug dient. Er glaubt, dass arkane Magie nötig ist, um die Geißel aus Lordaeron zu tilgen. In seinem Studierzimmer bewacht er die Library des Klosters und den Scarlet Key.",al={"wer ist arkanist doan","doan lore","magier in der library"}},{q="Wer war Alexandros Mograine und wie hängt er mit diesem Ort zusammen?",a="Alexandros Mograine, der berühmte Aschenbringer, war ein legendärer Paladin der Silbernen Hand und einer der Gründer des Scharlachroten Kreuzzugs. Er gründete ihn gemeinsam mit Hochgeneral Abbendis und Großinquisitor Isillien. Sein Sohn Renault befehligt nun gemeinsam mit Hochinquisitor Whitemane die Kathedrale.",al={"mograine klostergeschichte","aschenbringer kloster","renault mograines vater"}},{q="Was unterscheidet den Flügel Friedhof so sehr vom Rest des Klosters?",a="Der Friedhof offenbart den Fanatismus des Klosters in einem noch düstereren Licht. Befrager Vishas leitet dort die Folterkammern. In vernachlässigten Krypten ernten oder manipulieren gefallene Zauberwirker wie Blutmagier Thalnos die ruhelosen Toten.",al={"warum sind die untoten auf dem friedhof","thalnos lore","befrager vishas"}}},fx={["0c05301c"]={q="Wer ist der Scharlachrote Kreuzzug?",a="Der Scharlachrote Kreuzzug ist ein fanatischer militärischer Orden aus menschlichen heiligen Kriegern und Priestern, der aus den Überresten der Ritter der Silbernen Hand gebildet wurde. Verzehrt von Trauer und Hass nach der Geißelung von Lordaeron, haben sie sich ganz der Ausrottung der Untoten verschrieben und setzen ihre Mission mit extremer Rücksichtslosigkeit und Paranoia durch.",al={"wer ist der scharlachrote kreuzzug","was ist der scharlachrote kreuzzug","lore scharlachroter kreuzzug"}},b0ef06b1={q="Sind die Mitglieder des Scharlachroten Kreuzzugs Menschen?",a="Ja, ihre Ränge bestehen ausschließlich aus Menschen aus dem gefallenen Reich Lordaeron. Sie hegen eine heftige Intoleranz gegenüber allen nicht-menschlichen Völkern, ungeachtet von Bündnissen oder früheren Bindungen, und erachten Außenstehende als unwürdig oder von Natur aus durch die Seuche befleckt.",al={"nur menschen im kreuzzug","volk des kreuzzugs","ist der scharlachrote kreuzzug menschlich"}},["1402011d"]={q="Warum greife ich eine Kirche voller Paladine an?",a="Obwohl sie die Insignien heiliger Orden tragen und das Licht führen, sind die Kommandanten des Klosters in gewalttätigen Extremismus verfallen. Ob Ihr dem Ruf von Raleigh the Devout folgt, um die korrupte Führung des Ordens zu säubern, oder im Namen von Varimathras in der Unterstadt zuschlagt, um einen aggressiven Nachbarn vor seiner Haustür zu neutralisieren, Ihr seid dort, um ihre militärische Macht zu brechen.",al={"warum scharlachrotes kloster angreifen","warum paladine dort töten","grund für kampf im kloster"}},["18e8d4ac"]={q="Ist der Scharlachrote Kreuzzug tatsächlich böse?",a="Sie begannen mit einer edlen Sache – Lordaeron von der Geißel der Untoten zu befreien. Doch Trauma und Paranoia haben ihren Zweck völlig verzerrt. Sie foltern nun unschuldige Reisende, brandmarken jeden Außenstehenden als verseucht und schlachten jeden ab, der nicht ihren Wappenrock trägt, wodurch sie im Streben nach Läuterung jeden moralischen Verstand verlieren.",al={"ist scharlachroter kreuzzug böse","sind das die bösen","sind kreuzzügler böse"}},fe2faadd={q="Unterstützt die Allianz den Scharlachroten Kreuzzug?",a="Nicht offiziell. Während manche in Sturmwind Sympathien für die überlebenden heiligen Krieger von Lordaeron hegen mögen, hat die unterschiedslose Feindseligkeit des Kreuzzugs formelle Bindungen zerrissen. Abenteurer und Persönlichkeiten der Allianz wie Raleigh the Devout betrachten ihre derzeitigen Kommandanten als wahnsinnige Eiferer, deren Gräueltaten die Ehre des Lichts beschmutzen.",al={"unterstützt die allianz den kreuzzug","gehört kreuzzug zur allianz","allianz bindungen zum kreuzzug"}},ae07147f={q="Befindet sich die Anführerin des Klosters in der Kathedrale?",a="Ja. Sowohl der Scharlachrote Kommandant Mograine als auch Hoher Inquisitor Whitemane residieren in der Kapelle der Kreuzzügler tief im Flügel der Kathedrale, bewacht von einer inneren Garde eifriger Verteidiger.",al={"wo ist whitemane","ist whitemane in der kathedrale","ort des kathedralenbosses"}},["11700a05"]={q="Warum hasst der Scharlachrote Kreuzzug die Verlassenen so sehr?",a="Für den Kreuzzug sind alle Untoten Abscheulichkeiten, die aus der Seuche hervorgegangen sind, welche ihre Familien und ihre Heimat auslöschte. Sie machen keinen Unterschied zwischen den willenlosen Schergen der Geißel und den freien Verlassenen, die die Hauptstadt besetzt halten; beide werden als verrottende Usurpatoren angesehen, die in heiligem Feuer vollständig gereinigt werden müssen.",al={"kreuzzug gegen verlassene","warum hasst kreuzzug untote","fehde zwischen kreuzzug und verlassenen"}},["38169c8a"]={q="Waren die Scharlachroten Kreuzzügler und die Verlassenen einst dasselbe Volk?",a="Ja. Die meisten Kreuzzügler und Verlassenen waren Bürger, Soldaten oder Priester des Königreichs Lordaeron vor dem Dritten Krieg. Als die Seuche durch das Land fegte, wurden diejenigen, die starben und wieder auferstanden, zu Untoten, während die traumatisierten Lebenden flohen oder sich zusammenschlossen, wodurch ehemalige Nachbarn und Verwandte zu erbitterten, geschworenen Feinden wurden.",al={"kannten sich kreuzzügler und verlassene","waren beide bürger von lordaeron","überreste von lordaeron"}},["80c0e472"]={q="Woher kam der Scharlachrote Kreuzzug?",a="Der Kreuzzug entstand aus den überlebenden Rittern der Silbernen Hand und Soldaten Lordaerons, die von Hochlord Alexandros Mograine und General Abbendis angeführt wurden. Überwältigt vom Verlust ihres Königreichs, spalteten sich die überlebenden Anführer: Diejenigen, die unerbittlichen, kompromisslosen Fanatismus befürworteten, bildeten den Scharlachroten Kreuzzug, während Gemäßigte sich abspalteten, um die Argentumdämmerung zu gründen.",al={"ursprung des scharlachroten kreuzzugs","wie wurde kreuzzug gegründet","wer gründete kreuzzug"}},c4a70323={q="Was war die Silberne Hand?",a="Die Ritter der Silbernen Hand waren der legendäre heilige Orden der Paladine, der während des Zweiten Kriegs von Erzbischof Alonsus Faol und Uther der Lichtbringer gegründet wurde. Sie dienten als vorderste Vorkämpfer der Allianz und Lordaerons, bis Prinz Arthas ihre Reihen während der Invasion der Geißel zerschlug.",al={"was war die silberne hand","ritter der silbernen hand","paladine der silbernen hand"}},d5472427={q="Warum tötet der Scharlachrote Kreuzzug auch lebende Menschen?",a="Tiefe Paranoia hat den Bezug des Kreuzzugs zur Realität untergraben. Sie glauben, dass jeder Außenstehende ein heimlicher Träger der Untotenseuche sein könnte. Jeder, der nicht ihre Uniform trägt und sich ihrer starren Autorität unterwirft, wird als korrumpiert gebrandmarkt und zu Folter oder Tod verurteilt.",al={"warum lebende menschen töten","kreuzzug tötet menschen","warum töten sie ihresgleichen"}},b6568619={q="Ist der Scharlachrote Kreuzzug eine Bedrohung für Sturmwind?",a="Nicht direkt im Sinne einer geografischen Eroberung, da ihre Bemühungen in den nördlichen Ruinen von Lordaeron verankert sind. Ihr Wahnsinn und ihre Bereitschaft, jeden Reisenden zu ermorden, machen sie jedoch zu einer aktiven Gefahr für Bürger, Botschafter und Abenteurer der Allianz, die sich in die Nähe ihrer Gebiete wagen.",al={"ist kreuzzug eine bedrohung für die allianz","kreuzzug gegen sturmwind","bedrohung durch den kreuzzug"}},["6889160e"]={q="Warum will jeder, dass ich in Das Scharlachrote Kloster gehe?",a="Beide Fraktionen haben wichtige Interessen in Tirisfal. Die Verlassenen können eine schwer bewaffnete Festung voller Eiferer direkt vor ihrer Hauptstadt nicht dulden, während Vertreter der Allianz versuchen, heilige Texte zu bergen, gefährliche Abtrünnige zu unterdrücken und der wahnsinnig gewordenen Führung Gerechtigkeit widerfahren zu lassen.",al={"warum werde ich ins kloster geschickt","wer will das kloster tot","grund für kloster quests"}},["0c6b4a7d"]={q="Wofür ist Scarlet Monastery Library da?",a="Die Library, die das Athenaeum und die Gallery of Treasures umfasst, beherbergt alte Schriften aus Lordaeron, historische Aufzeichnungen und arkanes Wissen. Sie dient sowohl als intellektuelles Archiv als auch als abgeschiedenes Forschungsheiligtum, dem Arkanist Doan vorsteht.",al={"zweck des bibliotheksflügels","was machen sie in der bibliothek","athenaeum des scharlachroten klosters"}},["29dc31ee"]={q="Wofür werden die Flügel der Waffenkammer und der Kathedrale genutzt?",a="Die Waffenkammer dient als militärisches Herz des Kreuzzugs und beherbergt Trainingsgelände, Kasernen und Waffenlager, die von Herod dem Scharlachroten Champion beaufsichtigt werden. Die Kathedrale steht als höchstes geistiges Heiligtum und Befehlsstand, wo Mograine Elitetruppen drillt und Whitemane Predigten hält und die Präsenz des Kreuzzugs in Tirisfal koordiniert.",al={"wozu waffenkammer und kathedrale","zweck waffenkammer","zweck kathedrale"}},f04a1b7f={q="Wie bin ich im Scharlachroten Kloster gelandet?",a="Ihr seid in die weit nordöstlichen Hügel von Tirisfal gereist und durch das neblige Land zum befestigten Sitz des Scharlachroten Kreuzzugs vorgedrungen. Ob Ihr im Auftrag der Horde aus der Unterstadt heraufgekrochen seid, um eine Bedrohung durch Eiferer vor ihrer Haustür zu beseitigen, oder vom Vorgebirge des Hügellands nach Norden marschiert seid, um dem Ruf enttäuschter Kreuzzügler zu folgen, die die fanatische Führung des Klosters stürzen wollten, der Weg führte Euch unweigerlich vor diesen schwer bewachten Komplex.",al={"wie bin ich hierhergekommen","weg zum scharlachroten kloster","warum bin ich hier"}},be779d1d={q="Was soll ich im Scharlachroten Kloster tun?",a="Ihr seid hier, um die vier Flügel des Kreuzzugs zu durchbrechen und ihren Halt über die Region zu brechen. Je nachdem, wer Euch geschickt hat, jagt Ihr vielleicht gefallene Anführer wie den Scharlachroten Kommandanten Mograine und Hoher Inquisitor Whitemane, entdeckt verlorene Bände und Wissen in der Bibliothek, sammelt Herzen des Eifers für die Apothekervereinigung oder bergt heilige Artefakte und erschlagt korrupte Anführer, die jeden außerhalb ihrer Ränge als verseuchte Untote brandmarken.",al={"was mache ich hier","warum bin ich hier","meine mission hier"}},["3ffc247b"]={q="Was ist das Scharlachrote Kloster?",a="Das Scharlachrote Kloster liegt in den nordöstlichen Tirisfal und ist ein befestigtes Heiligtum sowie die wichtigste Bastion des Scharlachroten Kreuzzugs in der Region. Einst ein friedlicher Kathedralenkomplex, der dem Heiligen Licht und klerikalem Lernen gewidmet war, wurde die Festung in ein schwer bewaffnetes Hauptquartier, Trainingsgelände und ideologisches Bollwerk für den fanatischen Feldzug des Kreuzzugs gegen das Untodtum umgewandelt.",al={"was ist das scharlachrote kloster","scharlachrotes kloster lore","über das scharlachrote kloster"}},fd7417a7={q="War das Scharlachrote Kloster schon immer ihres?",a="Nein. Vor dem Fall von Lordaeron war es einfach als das Alte Kloster bekannt. Ursprünglich vom adligen Haus Godwyn gefördert, diente es als Erzbischofssitz und Priesterseminar unter Erzbischof Alonsus Faol. Nach der Verwüstung des Dritten Krieges befreiten überlebende Paladine seine Hallen von den verweilenden Geißel-Infestationen und benannten es in Scharlachrotes Kloster um.",al={"war das scharlachrote kloster immer kreuzzug","geschichte des scharlachroten klosters","wem gehörte das scharlachrote kloster früher"}},e7b85043={q="Wer hat das Scharlachrote Kloster erbaut?",a="Das Alte Kloster wurde als Zufluchtsort der Kirche des Heiligen Lichts unter der Schirmherrschaft des adligen Hauses Godwyn errichtet. Seine Bibliotheken und Archive wurden über Generationen von Archivaren wie Blake Godwyn kuratiert und standen bis zum Zusammenbruch des Königreichs als stolzes Zentrum des Priestertums und der Paladinausbildung in Lordaeron.",al={"wer baute das kloster","ursprünge des klosters"}},fbd0569e={q="Wer hat das Kommando über das Scharlachrote Kloster?",a="Die militärische Garnison der Festung untersteht Scharlach-Kommandant Renault Mograine, der eine ergebene Streitmacht von Kriegern befehligt. Die wahre geistliche und doktrinäre Herrscherin des Komplexes ist jedoch Hochinquisitorin Weißsträhne, eine mächtige Priesterin, die imstande ist, die Gefallenen wiederzuerwecken, damit sie in ihrem Namen kämpfen.",al={"wer fuehrt das scharlachrote kloster an","wer leitet das kloster","anfuehrer des scharlachroten klosters"}}},fp="17,291,18.495.0,14.492.0,31.517.1,66.284.0,55.301.1,46.170.0,46.213.0,57.280.1,74.218.0"}
P.entries["zone:searinggorge"] = {n="Sengende Schlucht",s="In der Sengenden Schlucht schürft der Dunkeleisenzwergen-Klan in einem Land, das einst mit dem grünen Rotkammgebirge verbunden war. Ragnaros der Feuerfürst versengte es, als er vor über zwei Jahrhunderten beschworen wurde. Nun überwacht die Thoriumbruderschaft die Sklavenminen des Klans im Kessel.",h="In der Sengenden Schlucht schürft der Dunkeleisenzwergen-Klan in einem Land, das einst mit dem grünen...",kw={"der schwarzfels","kessel","dunkeleisenzwergen-klan","ragnaros","sengende schlucht","die schlackengrube","steinwerkpass","thoriumbruderschaft","thoriumspitze"},ang={["class:Rogue"]="Als Schurke könnt Ihr mit Eurer geschulten Fingerfertigkeit das Tor des Steinwerkpasses zwischen Loch Modan und der Schlucht öffnen.",["faction:Alliance"]="Als Reisender der Allianz findet Ihr den Steinwerkpass versperrt, damit die Dunkeleisenzwerge von den friedlichen Zwergensiedlungen in Loch Modan getrennt bleiben. Die Allianz entsendet tapfere Abenteurer zu Angriffen in die Schlucht.",["faction:Horde"]="Als Reisender der Horde könnt Ihr Kargath als Stützpunkt nutzen. Die Horde hat eine Überlandroute in die Schlucht geschlagen, um Informationen über den Schwarzfels zu sammeln und die Unternehmungen der Dunkeleisenzwerge in Khaz Modan zu stören.",["profession:Mining"]="Als Bergbauer könnt Ihr in der vulkanischen Ödnis und den tiefen Ausgrabungen der Schlackengrube nach reichen Adern aus Mithril, Echtsilber und begehrtem Dunkeleisenerz suchen.",["race:Dwarf"]="Als Zwerg aus Eisenschmiede seht Ihr in der Sengenden Schlucht eine bittere Erinnerung an den Krieg der drei Hämmer und den verhängnisvollen Leichtsinn des Dunkeleisenzwergen-Klans. Dessen Ausgrabungen bedrohen nun die südlichen Zugänge nach Khaz Modan."},sec={{t="Eine versengte Ödnis",b="Vor dem Krieg der drei Hämmer war die Sengende Schlucht ein grüner, hügeliger Teil der Rotkammgebirgskette. Dieses Land ging vor über zweihundertdreißig Jahren verloren. Zauberer-Thane Thaurissan beschwor Ragnaros aus den Tiefen unter der Welt herauf, in der Hoffnung, eine Niederlage in einen Sieg zu verwandeln. Der Feuerfürst riss die Erde entzwei, türmte den Schwarzfels auf und legte die große Dunkeleisenstadt Thaurissan in rauchende Trümmer. Asche, Schwefel und Vulkanglas bedeckten das nördliche Tal."},{t="Der Kessel und die Schlackengrube",b="Nach dem Fall ihrer alten Hauptstadt bemächtigten sich die Dunkeleisenzwerge der Schlucht, um die Rohstoffe für ihre Kriegsmaschinerie zu gewinnen. Im Herzen des Tals gräbt sich der Kessel als gewaltiger Tagebau tief in den Fels. In seinen unteren Bereichen bildet die Schlackengrube einen brutalen unterirdischen Minenkomplex.\n\nAufseher der Dunkeleisenzwerge und schwerfällige Kriegsgolems zwingen gefangene Feinde zur Sklavenarbeit. Sie fördern Eisen, Mithril und seltenes Dunkeleisenerz aus glühendem Gestein. Aufsteigende Lava und umherstreifende Bestien bedrohen die Minenarbeiter auf Schritt und Tritt."},{t="Thoriumbruderschaft und umkämpfte Pfade",b="Die Thoriumspitze thront auf den nördlichen Klippen über der Ausgrabung. Die Thoriumbruderschaft hält diesen befestigten Außenposten, seit sie sich von ihren Verwandten im Schwarzfels losgesagt hat. Ihre Meisterhandwerker bieten Reisenden neutrale Zuflucht, wenn sie die Unternehmungen der Dunkeleisenzwerge untergraben oder seltene Schmelzkomponenten beschaffen.\n\nDer Zugang zur Schlucht bleibt streng kontrolliert. Die Allianz versperrt den Steinwerkpass nach Loch Modan mit schweren Eisentoren, während Expeditionen der Horde aus dem nahen Kargath einen schmalen Pfad durch das östliche Ödland geschlagen haben, um das Gebiet auszukundschaften."}},faq={{q="Warum ist die Sengende Schlucht verbrannt und mit Asche bedeckt?",a="Vor über zweihundertdreißig Jahren versuchte der Dunkeleisen-Zauberer-Thane Thaurissan während des Kriegs der drei Hämmer, eine übernatürliche Macht zu beschwören, um einer Niederlage zu entgehen. Stattdessen rief er Ragnaros den Feuerfürsten herbei. Der Ausbruch zerschmetterte den südlichen Teil des Rotkammgebirges, türmte den Schwarzfels auf und verbrannte die umliegenden Täler zu Sengender Schlucht und Brennender Steppe.",al={"warum ist es verbrannt","geschichte der sengenden schlucht","wie entstand die sengende schlucht"}},{q="Welche Zwerge leben an der Thoriumspitze?",a="Die Zwerge an der Thoriumspitze gehören zur Thoriumbruderschaft, einer unabhängigen Fraktion von Dunkeleisenzwergen, die sich von ihren Verwandten im Reich unter dem Schwarzfels losgesagt haben. Von ihrem Lager auf der Thoriumspitze aus arbeiten sie als Meisterschmiede und Kunsthandwerker. Sie tauschen Wissen und Handwerksgeheimnisse mit Reisenden, die ihnen gegen die Dunkeleisenstreitkräfte weiter unten helfen.",al={"zwerge an der thoriumspitze","wer ist die thoriumbruderschaft","geschichte der thoriumbruderschaft"}},{q="Was geschieht im Kessel?",a="Der Dunkeleisenzwergen-Klan kontrolliert den Kessel, einen gewaltigen Tagebau, in dem sich die unterirdische Schlackengrube befindet. Aufseher und Kriegsgolems zwingen gefangene Gefangene zur Sklavenarbeit und lassen sie wertvolle Erze abbauen, darunter Dunkeleisenerz, für die großen Schmieden im Schwarzfels.",al={"was ist der kessel","geschichte der schlackengrube","was bauen die dunkeleisenzwerge ab"}},{q="Wie gelangt Ihr von Loch Modan in die Sengende Schlucht?",a="Der Steinwerkpass von Loch Modan ist durch ein schweres, verschlossenes Tor versperrt, das von Gebirgsjägern aus Eisenschmiede bewacht wird. Ihr könnt den Schlüssel zur sengenden Schlucht durch einen offiziellen Auftrag für Kurator Thorius erhalten, einen erfahrenen Schurken bitten, das Schloss zu knacken, oder das Tor umgehen, indem Ihr den offenen Pfad südlich von Kargath im Ödland nehmt.",al={"tor des steinwerkpasses","wie öffnet man das tor zur sengenden schlucht","schlüssel zur sengenden schlucht"}},{q="Warum interessiert sich die Horde für die Sengende Schlucht?",a="Die Horde nutzt das nahe Kargath im Ödland als Stützpunkt. Ihre Befehlshaber haben einen Gebirgspass in die Schlucht geschlagen, um die Truppenbewegungen der Dunkeleisenzwerge auszukundschaften und Wege zum strategisch wichtigen Schwarzfels zu sichern.",al={"warum ist die horde hier","verbindung zwischen kargath und der schlucht","horde presence"}},{q="Gibt es in der Sengenden Schlucht Eingänge zu Dungeons oder Schlachtzügen?",a="In der Sengenden Schlucht gibt es keine direkten Instanzportale, doch ihr südlicher Eingang führt in den Schwarzfels. Im Berg liegen die Schwarzfelstiefen, die Schwarzfelsspitze und die tiefen Gänge zum Geschmolzenen Kern.",al={"instanzen in der sengenden schlucht","dungeons in der sengenden schlucht","wo ist der geschmolzene kern"}}},fp="13,249,20.456.0,29.498.0,39.549.0,51.376.0,44.359.0,33.260.0,50.303.0,45.225.0,62.207.0"}
P.entries["zone:shadowfang"] = {n="Burg Shadowfang",s="Im südlichen Silberwald bietet Burg Shadowfang Erzmagier Arugal und den von ihm beschworenen Worgen Schutz. Das alte Anwesen der Silberleins ist von wilden Bestien überrannt, und die ermordeten Verteidiger spuken dort. Das nahe Lohenscheit bleibt an einen schrecklichen Fluch gebunden.",h="Im südlichen Silberwald bietet Burg Shadowfang Erzmagier Arugal und den von ihm beschworenen Worgen Schutz.",kw={"arugal","fenrus","lohenscheit","sfk","shadowfang","silberlein","silberwald","grüntal","worgen"},ang={["class:Mage"]="Als Magier mahnt Euch die Tragödie von Burg Shadowfang, was geschehen kann, wenn ein Zauberer der Kirin Tor Wesen von jenseits dieser Welt beschwört und sich damit über jede sterbliche Kontrolle hinwegsetzt.",["class:Paladin"]="Als Paladin könnt Ihr in Kommandant Grüntals ruhelosem Geist eine traurige Erinnerung an gefallene Paladin-Verteidiger sehen, deren heilige Schwüre durch den Tod verdreht wurden.",["class:Warlock"]="Als Hexenmeister könnt Ihr Euch von den dunklen Energien der Burg, den Leerwandlern und den dämonischen Zaubern angezogen fühlen, ebenso wie von der Suche nach uralten Relikten wie der Kugel von Soran'ruk.",["faction:Horde"]="Die Verlassenen sehen in Arugals vorrückenden Rudeln eine unmittelbare Gefahr für ihr junges Gebiet im Silberwald. Todespirscher und die Königliche Apothekervereinigung machen die Burg zu einem vorrangigen Ziel."},sec={{t="Der Fall der Dynastie Silberlein",b="Burg Shadowfang gehörte einst der Familie Silberlein, und der fromme Kommandant Grüntal sollte sie verteidigen. Während des Dritten Krieges fegte die Geißel durch Lordaeron, und Dalarans Zauberer fielen in Scharen. Um die Toten aufzuhalten, widersetzte sich Erzmagier Arugal verzweifelt der Führung der Kirin Tor und nutzte die Forschungen des Magiers Ur.\n\nEr beschwor Worgen von jenseits dieser Welt, um das Blatt zu wenden. Die Bestien fielen über die Untoten her, entzogen sich dann jeder sterblichen Kontrolle und stürmten den südlichen Silberwald. Baron Silberlein und sein Hofstaat wurden niedergemetzelt und dazu verdammt, neben den Monstern, die ihre Heimat überrannten, durch die steinernen Hallen zu spuken."},{t="Arugals Kinder",b="Schuld und Wahnsinn trieben Arugal hinter die blutbefleckten Zinnen. Er nannte die gefräßigen Wolfsmenschen seine geliebten Kinder und gab der Burg den Namen Burg Shadowfang. Wolfsrudel und Schattenhunde gedeihen in ihren steinernen Lagern unter Züchtern wie Wolfsmeister Nandos. Arugals gewaltige Wolfsbestie, Fenrus der Verschlinger, wacht über sie.\n\nDer Fluch reichte über die Mauern hinaus. Das nahe Lohenscheit bleibt in einem schrecklichen Kreislauf gefangen: Tagsüber gehen die Bewohner als Menschen umher, nachts jagen sie als gefräßige Worgen unter dem Mond. Sie sind an den verrückten Erzmagier auf den Höhen gebunden."},{t="Der Schlag der Verlassenen",b="Fürstin Sylvanas Windläufer sah in Arugal eine ernste Bedrohung für ihre Herrschaft im Silberwald. Sie entsandte die Königliche Apothekervereinigung und Elite-Todespirscher, um den Ursprung des Worgenfluchs zu finden. Infiltrationstrupps erlitten in den Kerkern brutale Verluste. Schließlich drangen Helden der Horde, die dem Ruf aus dem Grabmal folgten, in den höchsten Turm ein und streckten Arugal nieder.\n\nMit Arugals Tod verlor das Rudel seinen Herrn. Der Geist, der die Ausbreitung der Bestien in der Wildnis lenkte, war gebrochen. Sein Kopf wurde zum Beweis für Lordaerons Vergeltung."}},faq={{q="Was geschieht, wenn Erzmagier Arugal besiegt wird?",a="Arugals Tod beseitigt die Macht, die die Worgenrudel im südlichen Silberwald kontrolliert. Auf Befehl von Fürstin Sylvanas Windläufer bringen Abenteurer der Horde seinen abgetrennten Kopf zu Dalar Morgenweber im Grabmal. Wilde Bestien und geisterhafte Überreste in der Burg und den umliegenden Wäldern bleiben eine Gefahr für Reisende.",al={"folgen von arugals tod","lore zu arugals tod","was geschieht nach arugals tod"}},{q="Warum beschwor Arugal die Worgen?",a="Während des Dritten Krieges erlitten Dalarans Armeen verheerende Niederlagen gegen die Geißel. Gefallene Zauberer erhoben sich als untote Soldaten für den Lichkönig. Auf der Suche nach einer Waffe, die das Blatt wenden konnte, nutzte Arugal die Forschungen des Magiers Ur, um Worgen von jenseits dieser Welt zu beschwören. Er glaubte, ihre Wildheit könne die Geißel aufhalten.",al={"warum wurden worgen beschworen","arugals motivation","dalaran beschwört worgen"}},{q="Wer war Baron Silberlein?",a="Baron Silberlein war der menschliche Adlige, der vor dem Dritten Krieg die Burg beherrschte und über das nahe Lohenscheit wachte. Als Arugals beschworene Bestien außer Kontrolle gerieten, stürmten sie die Festung und töteten den Baron, seine Familie und seine Wachen. Silberleins rachsüchtiger Geist spukt noch immer in den großen Speisesälen und ist dazu verdammt, neben den Monstern zu wandeln, die ihn erschlugen.",al={"lore zu baron silberlein","ursprünglicher herr von burg shadowfang"}},{q="Warum sind die Bewohner von Lohenscheit tagsüber freundlich?",a="Arugals dunkle Magie ließ die Bewohner des nahen Lohenscheit tagsüber als Menschen zurück, klaren Verstandes und friedlich gegenüber Reisenden der Allianz. Bei Sonnenuntergang setzt der Fluch ein und verwandelt die gesamte Bevölkerung in wilde Worgen, die dem verrückten Erzmagier in der Burg treu ergeben sind.",al={"menschen aus lohenscheit","fluch von lohenscheit","warum verwandelt sich lohenscheit in worgen"}},{q="Wer ist Kommandant Grüntal?",a="Kommandant Grüntal war ein Paladin und der Offizier, der für die Verteidigung von Burg Silberlein verantwortlich war. Als die Worgen die Festung überrannten, kämpfte er bis zum Tod. Sein ruheloser Geist patrouilliert noch immer durch die oberen Gänge und hält selbst im Untod an seiner Pflicht als Soldat fest.",al={"lore zu grüntal","geisterhafter paladinboss"}},{q="Was ist Das Buch von Ur?",a="Das Buch von Ur enthält die Forschungen Urs, eines Erzmagiers aus Dalaran, der Wesen von jenseits dieser Welt untersuchte, darunter die Worgen. Arugal nutzte die Schriften für seine verhängnisvollen Beschwörungen. Die Königliche Apothekervereinigung in der Unterstadt sucht das Buch, um die wolfartigen Kreaturen und ihre seltsame Magie zu verstehen.",al={"quest um das buch von ur","lore zu ur"}}},fx={["4bfedcc6"]={q="Was ist Burg Shadowfang?",a="Burg Shadowfang ist eine heimgesuchte Burg, die auf den hohen Klippen des südlichen Silberwalds thront und auf Lohenscheit hinabblickt. Ursprünglich als Silberleins Burg bekannt, diente sie einst als Festung der Allianz, die die Grenzen nahe Gilneas bewachte. Heute steht sie korrumpiert und in dunkle Nebel gehüllt als Festung für Erzmagier Arugal und seine wilden Worgen-Nachkommen.",al={"was ist burg shadowfang","erzähle mir von shadowfang","lore burg shadowfang"}},["1d3b32c5"]={q="Wer hat Burg Shadowfang erbaut?",a="Die Festung war der Sitz von Baron Silberlein, einem Adligen, dessen Familie lange vor dem Dritten Krieg die Herrschaft über die umliegenden Ländereien und Lohenscheit innehatte. Unter seiner Herrschaft stand sie als stolze Bastion der Menschen, bewacht von Kommandant Grüntal und vereidigten Soldaten des Reiches.",al={"wer baute burg shadowfang","ursprung von shadowfang","wer schuf shadowfang"}},["7c8f83a0"]={q="War der Silberwald ein Gebiet von Lordaeron?",a="Ja. Der Silberwald bildete den rauen westlichen Rand des Königreichs Lordaeron und grenzte im Süden an Gilneas. Seine Anwesen und Siedlungen waren an die Allianz gebunden, bevor die Seuche das Königreich zerschlug.",al={"war dies lordaeron","geschichte von silberwald und lordaeron","gehörte der silberwald zu lordaeron"}},["91da6ffd"]={q="Warum ist der Silberwald heute so verlassen?",a="Zwischen der Invasion der Geißel, dem Schließen des großen Walls durch Gilneas und Arugals tobendem Worgenfluch wurde die lebende Bevölkerung abgeschlachtet, verflucht oder floh ins Ausland. Die wenigen, die geblieben sind, klammern sich verzweifelt an umkämpfte Weiler wie Lohenscheit.",al={"warum ist der silberwald leer","verlassener silberwald","warum ist der silberwald eine ruine"}},["2ee73ad9"]={q="Warum hat Arugal überhaupt Worgen in den Silberwald gebracht?",a="Als die untote Geißel nach Süden marschierte, starben die Zauberer von Dalaran in Scharen, nur um im Dienst des Lichkönigs wieder aufzuerstehen. Arugal glaubte, dass durch extra-dimensionale Beschwörungen herbeigerufene Verbündete die Untoten dort überwältigen könnten, wo konventionelle sterbliche Armeen gescheitert waren.",al={"warum worgen in den silberwald bringen","grund für arugals worgenbeschwörung","warum hier worgen beschwören"}},["671a79f5"]={q="Wen wollte Arugal aufhalten?",a="Er beschwor sie speziell, um die untoten Armeen der Geißel zu vernichten, die anschwollen, indem sie jeden Soldaten und Zauberer, der in der Schlacht fiel, abschlachteten und wiedererweckten.",al={"gegen wen kämpfte arugal","arugals feind","gegen wen beschwor arugal worgen"}},eeb57b84={q="Hat Arugals Plan gegen die Geißel funktioniert?",a="Taktisch ja – die Worgen zerfleischten die Untoten mühelos. Aber strategisch war es eine Katastrophe. Die wilden Wolfsmenschen ließen sich nicht kontrollieren, wandten sich gegen menschliche Soldaten und Zauberer gleichermaßen und verbreiteten einen tödlichen Fluch in der gesamten Region.",al={"besiegten worgen die geißel","funktionierte die beschwörung","worgenerfolg gegen geißel"}},["2bfe7e75"]={q="Sind die Worgen in der Burg dieselben, die Lohenscheit überrannt haben?",a="Ja. Arugals Rudel, einschließlich der Rudel von Shadowfang und Moonrage, haben denselben verfluchten Ursprung. Die Bestien, die durch die Hallen der Burg streifen, sind Arugals eigene Brut und eng mit dem Fluch verbunden, der die Dorfbewohner unterhalb plagt.",al={"stammen shadowfang worgen aus lohenscheit","lohenscheit worgen shadowfang","dasselbe worgenrudel"}},b78b86f3={q="Was ist mit den Dorfbewohnern von Lohenscheit passiert?",a="Die Dorfbewohner überlebten den Dritten Krieg nur, um von Arugals dunkler Magie gefangen genommen zu werden. Obwohl sie bei Tageslicht wie normale Menschen erscheinen, verwandelt der Sonnenuntergang sie in wilde, blutrünstige Worgen, die dem wahnsinnigen Erzmagier treu ergeben sind.",al={"was passierte mit den leuten aus lohenscheit","schicksal von lohenscheit","stadtbewohner von lohenscheit"}},["39fbc1b5"]={q="Sind die Dorfbewohner von Lohenscheit auch verflucht?",a="Ja. Sie sind Opfer des lykanthropischen Worgenfluchs. Bei Tag bewahren sie ihren Verstand und handeln friedlich mit Wanderern der Allianz; bei Nacht raubt ihnen der Fluch ihre Menschlichkeit und macht sie zu reißenden Bestien.",al={"ist lohenscheit verflucht","fluch von lohenscheit","sind dorfbewohner infiziert"}},d6e89a88={q="Wer sind die Geister in Burg Shadowfang?",a="Es sind die ruhelosen Geister von Baron Silberlein, Kommandant Grüntal und der ehemaligen Dienerschaft der Burg. Sie wurden während des überraschenden Worgenangriffs erschlagen und ihre Seelen sind durch Qual und Gram an die zerstörten Steine gebunden.",al={"geister in shadowfang","wer sind die geister in burg shadowfang","gespenster in shadowfang"}},["0a399272"]={q="Sind die Geister die alten Diener der Burg?",a="Ja. Von geisterhaften Köchen und schattenhaften Begleitern bis hin zu ehemaligen Wachen sind die spektralen Verteidiger, die durch die Hallen wandern, die abgeschlachteten Bediensteten, die Baron Silberlein einst zu Lebzeiten dienten.",al={"sind geister ehemalige diener","geister der burghofdiener","silberleins diener"}},["3f532512"]={q="Warum können die Geister nicht ruhen?",a="Das pure Entsetzen ihres Massakers in Verbindung mit der schweren Schattenmagie, die die Burg durchdringt, verhindert ihre Erlösung. In ihrer ewigen Qual schlagen sie mit unheiliger Wut gegen jeden lebenden Eindringling, der ihre Gräber stört.",al={"warum sind geister ruhelos","warum spuken geister in shadowfang","ruhelose geister shadowfang"}},["59c03d52"]={q="Arbeitet Arugal für die Geißel?",a="Nein. Arugal verachtet die Geißel; er beschwor die Worgen gerade deshalb, um sie zu vernichten. Obwohl er wahnsinnig geworden ist, gilt seine Loyalität seinen 'Kindern' und nicht dem Lichkönig.",al={"ist arugal geißel","arbeitet arugal für die geißel","dient arugal der geißel"}},["99eb22e3"]={q="Kontrolliert der Lichkönig Arugal?",a="Nein. Arugals Wahnsinn ist völlig selbstverschuldet und entspringt Schuldgefühlen und Magie, nicht dem telepathischen Griff des Frostthrons. Er agiert unabhängig als Herr seines eigenen dunklen Reiches.",al={"kontrolliert der lichkönig arugal","lichkönig arugal","arugal gedankenkontrolle"}},["501c4a9b"]={q="Endet der Fluch, nachdem Arugal tot ist?",a="Nein. Arugals Tod enthauptet zwar die Führung von Burg Shadowfang, aber der Worgenfluch hat bereits das Blut der Sterblichen im gesamten Wald infiziert. Das Leiden besteht noch lange fort, nachdem der Erzmagier gefallen ist.",al={"endet der worgenfluch","verschwindet der worgenfluch","ist lohenscheit geheilt"}},["6cb01af1"]={q="Werden die Verlassenen Burg Shadowfang einnehmen?",a="Momentan begnügen sich die Verlassenen damit, die Bedrohung für ihre südliche Grenze zu beseitigen und das Buch von Ur wiederzuerlangen. Die Ruine bleibt eine düstere, heimgesuchte Hülle, die über die Wälder blickt, statt ein befestigter Außenposten zu werden.",al={"werden verlassene shadowfang einnehmen","erobern verlassene shadowfang","wer kontrolliert shadowfang danach"}},["3f22b397"]={q="Wie bin ich in Burg Shadowfang gelandet?",a="Ihr seid der Spur des Schreckens durch den Silberwald bis zu den Klippen oberhalb von Lohenscheit gefolgt. Wenn Ihr der Horde dient, wurdet Ihr wahrscheinlich vom Grabmal oder der Unterstadt nach Süden geschickt, um die Worgenplage zu untersuchen, die die Region erstickt. Wenn Ihr für die Allianz kämpft, haben Euch Gerüchte über die verfluchten Wälder, verlorene heilige Relikte oder den gefallenen Kirin Tor tief in das feindliche Gebiet der Verlassenen geführt. Ihr seid die windigen Klippen hinter den Toren von Lohenscheit hinaufgestiegen, seid an reißenden Wolfsbestien vorbeigedrungen und durch das uralte Tor der Burg gebrochen, um das Versteck des wahnsinnigen Erzmagiers zu betreten.",al={"wie kam ich hierher","wie erreiche ich burg shadowfang","wie fand ich diesen ort"}},["31a8c552"]={q="Was soll ich in Burg Shadowfang tun?",a="Euer oberstes Ziel ist es, Euch durch die heimgesuchten Hallen zu kämpfen und Erzmagier Arugal niederzustrecken, um seine verdrehte Herrschaft über den Silberwald zu beenden. Unterwegs müsst Ihr die Worgen niedermetzeln, die durch die Höfe streifen, und die ruhelosen Geister von Baron Silberlein und seiner erschlagenen Dienerschaft zur Ruhe betten. Wenn Ihr im Namen der Verlassenen handelt, habt Ihr die Aufgabe, das Buch von Ur zu bergen und das Schicksal der vermissten Todespirscher zu entdecken, die hineingeschickt wurden. Helden, Paladine und Hexenmeister der Allianz suchen nach verlorenen Artefakten der Macht, heiligen Waffen und Vergeltung für die dunkle Magie, die das Land vergiftet.",al={"was mache ich hier","warum bin ich hier","was ist mein ziel in burg shadowfang"}},efb02893={q="Warum ist Burg Shadowfang voller Worgen?",a="Als die heraufbeschworenen Worgen sich aus der Kontrolle der Kirin Tor befreiten, wüteten sie durch den Wald und belagerten die Burg. Sie metzelten Baron Silberlein und seinen gesamten Haushalt nieder. Vom Schuldgefühl über das, was er entfesselt hatte, in den Wahnsinn getrieben, adoptierte Erzmagier Arugal die Bestien als seine eigenen 'Kinder', beanspruchte die Ruine für sich und benannte sie in Burg Shadowfang um.",al={"warum sind hier worgen","burg shadowfang worgen grund","warum worgen drinnen"}},["7d419eb0"]={q="Warum interessiert sich die Horde für diese Burg?",a="Die Worgen, die aus der Burg streifen, sind eine unkontrollierte Plage, die den Griff der Verlassenen über den Silberwald bedroht. Von ihrer Basis im Grabmal aus erkannten die Anführer der Verlassenen, dass die umliegenden Lande niemals sicher sein werden, solange Arugal seine wolfsartigen Schrecken von den Burgzinnen aus befehligt.",al={"warum interessiert sich die horde für burg shadowfang","interesse der horde an burg shadowfang","warum nach burg shadowfang"}},d6cbfc07={q="Wer hat Euch hierher geschickt?",a="Kommandeure der Verlassenen im Grabmal ordneten den Angriff an, um Arugal zu eliminieren und das Schicksal ihrer vermissten Späher aufzudecken. Währenddessen entsandte die Königliche Apothekervereinigung in der Unterstadt Agenten, um Urs magische Forschungen aus der Library des Erzmagiers zu bergen.",al={"wer schickte mich nach burg shadowfang","questgeber für burg shadowfang","wer will arugal tot sehen"}},a794fece={q="Ist dies jetzt Land der Verlassenen?",a="Die Verlassenen beanspruchen den nördlichen Silberwald, doch ihr Griff nach dem Süden ist heiß umkämpft. Burg Shadowfang bleibt fest unter Arugals Herrschaft, während verbliebene Geißel, wilde Bestien und überlebende menschliche Siedlungen der Dunklen Fürstin die Herrschaft über die Region streitig machen.",al={"ist silberwald land der verlassenen","gehört dies sylvanas","gebiet der verlassenen burg shadowfang"}},b918d1de={q="Wer hat in Burg Shadowfang das Sagen?",a="Die Burg untersteht vollständig Erzmagier Arugal. Wahnsinnig geworden durch den Dritten Krieg, herrscht er über die oberen Türme, flankiert von seinen monströsen Worgen und seinem gewaltigen Schoßworg, Fenrus, und befehligt die Burg durch dunkle Hexerei.",al={"wer herrscht in burg shadowfang","wer hat drinnen das sagen","meister von burg shadowfang"}},ecad974c={q="Ist Arugal der Boss der Burg?",a="Ja. Arugal ist der Meister von Burg Shadowfang. Er orchestriert den Worgenbefall im gesamten Silberwald und thront an der Spitze des Burgturms als dessen höchste Autorität.",al={"ist arugal der boss","endboss burg shadowfang","meister arugal"}},["3b086809"]={q="Hatte jemand vor ihm das Sagen?",a="Baron Silberlein herrschte über die Burg, als sie noch ein Stützpunkt der Allianz war. Er und seine Familie regierten die Burg, bis Arugals Worgen während des Dritten Krieges die Mauern durchbrachen und jeden darin niedermetzelten.",al={"wer herrschte vor arugal","früherer meister von burg shadowfang","früherer herr der burg"}},["7f02160f"]={q="Woher kommen die Worgen?",a="Es handelt sich um gefräßige, extra-dimensionale Wesen, die aus einer anderen Ebene gerissen wurden. Verzweifelt versucht, die Geißel während des Dritten Krieges aufzuhalten, wandte Arugal sich der verbotenen Forschung des Magiers Ur aus Dalaran zu und beschwor diese jenseitigen Bestien nach Azeroth.",al={"woher kamen die worgen","ursprung der worgen","quelle der worgen"}},["4fa8e666"]={q="Hat Arugal die Worgen alleine beschworen?",a="Arugal führte die Beschwörung gegen den ausdrücklichen Rat seiner Gefährten in Dalarans Kirin Tor durch. Sich stark auf die Schriften im Buch von Ur verlassend, zwang er die Entitäten über die Ebenengrenzen hinweg.",al={"handelte arugal allein","wer half beim beschwören der worgen","beschwörung arugal"}},a6a018be={q="Können die Worgen kontrolliert werden?",a="Kaum, und nur durch dunkle Magie. Obwohl beschworen, um als Verbündete gegen die Untoten zu dienen, wandten sie sich sofort gegen ihre Beschwörer. Arugal schafft es nur, einige von ihnen zu lenken, weil sein gebrochener Verstand sie als Familie betrachtet und er Verzauberungen nutzt, um zerbrechlichen Gehorsam zu erzwingen.",al={"können worgen kontrolliert werden","kontrolle der worgen","sind worgen zahm"}},["24ed31c3"]={q="Was ist mit den The Todespirscher Adamant und Vincent passiert?",a="Die The Todespirscher Adamant und Vincent schlichen auf Befehl aus dem Grabmal in Burg Shadowfang, um Arugals Stärke auszukundschaften. Sie wurden von den Verteidigern der Burg gefangen genommen; Vincent wurde eingekerkert und im Innenhof hingerichtet, während Adamant in den Kerkern gefangen auf Rettung wartet.",al={"adamant und vincent","was ist mit den the deathstalkers passiert","späher der verlassenen burg shadowfang"}},cc7bdeae={q="Warum wurden die The Todespirscher in die Burg Shadowfang geschickt?",a="Das Kommando der Verlassenen benötigte präzise Informationen über den tierischen Befall, der ihre südliche Front bedrohte. Adamant und Vincent erhielten den Auftrag, die Burg zu infiltrieren, Arugals wahre Truppenstärke zu bestimmen und den Weg für einen entscheidenden Schlag zu ebnen.",al={"warum the deathstalkers schicken","auskundschaften von burg shadowfang","mission der the deathstalkers"}},["4cfa60a4"]={q="Leben die The Todespirscher noch?",a="Vincent ist tot, er wurde nach seiner Gefangennahme erschlagen. Adamant jedoch bleibt tief in den unteren Haltezellen der Burg eingekerkert, lebendig genug, um jedem Horde-Abenteurer zu helfen, der zu ihm durchdringt.",al={"leben vincent und adamant noch","überlebten die the deathstalkers","schicksal der the deathstalkers"}},c6ee2849={q="Was sind The Todespirscher?",a="Die The Todespirscher sind die elitären verdeckten Assassinen und Schurken der Verlassenen. Spezialisiert auf Verstohlenheit, Spionage und plötzlichen Tod, agieren sie als die stillen Dolche der Unterstadt an den Grenzen von Lordaeron.",al={"was ist ein the deathstalker","wer sind die the deathstalkers","the deathstalkers der verlassenen"}},["40c5e48b"]={q="Wem unterstehen die The Todespirscher?",a="Sie unterstehen einer strikten Befehlskette, die von Offizieren und Kommandeuren der Verlassenen geleitet wird, welche in den Gebieten stationiert sind, und dienen letztlich dem Willen des herrschenden Rats der Unterstadt.",al={"führung der the deathstalkers","wer befehligt die the deathstalkers","wer führt die the deathstalkers"}},["63a10ab0"]={q="Arbeiten die The Todespirscher direkt für Sylvanas?",a="Ja. Jeder The Deathstalker ist der Banshee-Königin, Fürstin Sylvanas Windläufer, verschworen. Sie bilden ihr persönliches Geheimdienstnetzwerk und spüren Bedrohungen für ihre untoten Anhänger mit freiem Willen in ganz Lordaeron auf.",al={"dienen the deathstalkers sylvanas","sylvanas the deathstalkers","the deathstalkers banshee-königin"}},f68cd02f={q="Warum schickt mich jeder in die Burg Shadowfang?",a="Weil die anfängliche Aufklärung der Verlassenen mit der Gefangennahme ihrer elitären The Todespirscher völlig zusammengebrochen ist. Arugals Versteck ist zu tückisch für normale Infanterie, es erfordert bewährte Abenteurer, die sich sowohl durch Bestien als auch durch rachsüchtige Geister kämpfen können.",al={"warum schickt man mich nach burg shadowfang","warum mache ich das","warum held in burg shadowfang"}},ebbfbfb0={q="Bin ich der Einzige, der das tun kann?",a="Die Ressourcen der Verlassenen im Silberwald sind extrem knapp, da sie gegen Faulhufgnolle, Geißel-Versprengte und Patrouillen aus Dalaran kämpfen müssen. Da ihre eigenen Vorauskommandos kompromittiert sind, sind Ihr und Eure Verbündeten die einzige Streitmacht, die in der Lage ist, die Burg zu stürmen.",al={"bin ich der einzige","niemand sonst zur säuberung von burg shadowfang","einzige wahl"}},["0f7e4add"]={q="Haben andere vor mir versucht, die Burg zu stürmen?",a="Ja. Neben den gescheiterten The Deathstalker-Spähern betraten Kirin Tor-Ermittler wie Zauberer Ashcrombe die Burg, um Arugal zu beurteilen, nur um gefangen genommen oder in ihren verfluchten Hallen eingesperrt zu werden.",al={"haben andere burg shadowfang versucht","frühere versuche burg shadowfang","wer hat es vorher versucht"}},["13386e7c"]={q="Was ist mit dem Silberwald passiert?",a="Der Silberwald war einst ein grünes Reich mit hoch aufragenden, silbern borkigen Kiefern, das von der Allianz bewacht wurde. Als die Geißel während des Dritten Krieges über Lordaeron hinwegfegte, ließ die Plage die Wälder verwelken, Ernten wurden verbrannt und die Bevölkerung massakriert oder hinter den Greymane-Wall getrieben.",al={"geschichte silberwald","was geschah mit silberwald","warum ist der silberwald so"}}},fp="15,249,31.608.0,17.575.0,19.531.1,46.300.1,33.314.0,26.353.0,59.258.0,28.263.0,23.300.0"}
P.entries["zone:shendralas"] = {n="Shen'dralas",s="Zentauren, Ausgestoßene und Stacheleber kämpfen um Shen'dralas, südöstlich von Desolace. Zwischen Feralas und Mulgore erheben sich uralte Ruinen inmitten schroffer Felsen.",h="Zentauren, Ausgestoßene und Stacheleber kämpfen um Shen'dralas, südöstlich von Desolace.",kw={"rückzugsort der borstennacken","desolace","evenshade overlook","feralas","lake dumont","front der magram","mulgore","zuflucht der ausgestoßenen","shen'dralas","tal der knochen"},ang={["faction:Alliance"]="Als Reisende der Allianz durchquert Ihr eine abgelegene, umkämpfte Wildnis mit alternativen Routen zwischen Feralas und dem zentralen Kalimdor. Auf der Reise ist große Wachsamkeit geboten.",["faction:Horde"]="Als Mitglied der Horde findet Ihr Shen'dralas gleich hinter den südlichen Ausläufern Mulgore. Wenn Ihr die Magram und die Stacheleber dort in Schach haltet, schützt Ihr die Grenzen der Horde.",["race:NightElf"]="Als Nachtelf erinnert Shen'dralas' Name an die alte Überlieferung der Hochgeborenen von Eldre'Thalas. Wächterinnen, die im südlichen Kalimdor vor leichtfertigem Umgang mit arkaner Magie auf der Hut sind, beobachten das Gebiet mit Interesse.",["race:Tauren"]="Als Tauren grenzt Shen'dralas an Mulgore und Desolace. Die Angriffe der Stacheleber und Zentauren entlang seiner Höhen bedrohen nahegelegene, angestammte Jagdgründe."},sec={{t="Ein Grenzland in Aufruhr",b="Shen'dralas liegt in den Höhen südöstlich von Desolace, zwischen Mulgore und Feralas. Seine zerklüfteten Pässe und verborgenen Enklaven bieten Gruppen Schutz, die fern der großen Hauptstädte der Fraktionen ums Überleben kämpfen. Am Evenshade Overlook halten manche von abgelegenen Höhen aus Wache. In der Zuflucht der Ausgestoßenen suchen andere Schutz, wo sie in Vergessenheit geraten können."},{t="Zentauren, Stacheleber und uralte Ruinen",b="Uralte Ruinen erinnern an das Erbe der Hochgeborenen, das hinter Shen'dralas' Namen steht, doch das Land ist alles andere als friedlich. Fehden der Zentauren greifen auf die Front der Magram über und halten altes Blutvergießen entlang der Grenzen am Leben. Stacheleber der Borstennacken halten befestigtes Gebiet am Rückzugsort der Borstennacken. Reisende treffen in den Schluchten auf umkämpftes Gebiet."},{t="Das Tal der Knochen",b="Das Tal der Knochen führt nach Nordwesten in Richtung Desolace und bietet den wichtigsten Überlandweg nach Shen'dralas. Sonne und Wind haben den Durchgang gebleicht. Seine Knochen erinnern an die gewaltsamen Kämpfe, die noch immer durch diese Felsen ziehen."}},faq={{q="Wo liegt Shen'dralas?",a="Shen'dralas liegt südöstlich von Desolace, zwischen Feralas und Mulgore. Reisende zu Fuß gelangen gewöhnlich von Desolace aus durch das Tal der Knochen hinein.",al={"wo liegt shen'dralas","shen'dralas lage","wie kommt man nach shen'dralas"}},{q="Wird Shen'dralas von der Allianz oder der Horde kontrolliert?",a="Weder die Allianz noch die Horde beherrscht Shen'dralas. Umherziehende Zentauren, feindselige Stacheleber, Ausgestoßene und abgelegene Lager machen es zu einem umkämpften Grenzland.",al={"ist shen'dralas von der horde kontrolliert","ist shen'dralas von der allianz kontrolliert","wem gehört shen'dralas"}},{q="Welche wichtigen Siedlungen oder Wahrzeichen gibt es hier?",a="Die wichtigsten Wahrzeichen sind das Tal der Knochen, der Rückzugsort der Borstennacken, der Evenshade Overlook, die Front der Magram, die Zuflucht der Ausgestoßenen und Shen'dralas' zentrale Weite.",al={"teilgebiete von shen'dralas","wahrzeichen in shen'dralas","sehenswürdigkeiten in shen'dralas"}},{q="Warum gibt es hier Zentauren?",a="Die Gebietskriege der Zentauren reichen von den Ebenen Desolaces entlang der Front der Magram bis nach Shen'dralas. Dort gerät der Klan mit örtlichen Verteidigern und rivalisierenden Fraktionen aneinander.",al={"zentauren in shen'dralas","front der magram","warum sind die magram hier"}},{q="Was ist der Rückzugsort der Borstennacken?",a="Der Rückzugsort der Borstennacken ist ein befestigter Außenposten, den Stacheleber der Borstennacken halten. Sie haben sich an den Rändern der Zone einen erbittert umkämpften Stützpunkt gesichert.",al={"rückzugsort der borstennacken","stacheleber in shen'dralas"}},{q="Welche Verbindung besteht zwischen dieser Zone und Lake Dumont?",a="Es ist keine Verbindung bekannt. Shen'dralas hat eigene Wahrzeichen, etwa das Tal der Knochen und die Zuflucht der Ausgestoßenen.",al={"lake dumont","geschichte der karte von shen'dralas"}}},fp="11,141,23.322.0,36.313.0,19.222.0,29.144.0,55.152.0,45.155.0,27.159.0,28.132.0,57.114.0"}
P.entries["zone:silithus"] = {n="Silithus",s="Silithus liegt unter sich ausbreitenden Silithidenschwärmen, die der Zirkel des Cenarius im Auge behält. Die Wüste birgt die uralten Ruinen von Ahn'Qiraj, die vor tausend Jahren hinter dem Skarabäuswall versiegelt wurden. Druiden halten die Schwärme und die Kultisten des Hammer des Zwielichts in Schach.",h="Silithus liegt unter sich ausbreitenden Silithidenschwärmen, die der Zirkel des Cenarius im Auge behält.",kw={"ahn'qiraj","burg cenarius","bau des ashischwarms","bau des regalschwarms","bau des zoraschwarms","die skarabäushöhe","der skarabäuswall","silithiden","silithus","hammer des zwielichts"},ang={["class:Druid"]="Als Druide werdet Ihr nach Silithus gerufen, wo der Zirkel des Cenarius seine südlichen Operationen in Kalimdor unterhält. Helft dabei, die Verderbnis des Landes einzudämmen, und stellt Euch den unnatürlichen Brutstätten, die das Gleichgewicht der Natur bedrohen.",["profession:Herbalism"]="Trotz der rauen Wüste von Silithus gedeihen seltene Pflanzen: Bergsilberweisling, Traumblatt, Sonnengras und der begehrte Schwarze Lotus.",["profession:Mining"]="In den trockenen Felsen und Insektentunneln von Silithus lagern einige der reichsten Thoriumvorkommen der Welt. Seltene, von Schlamm bedeckte Adern verbergen sich tief in den Bauten der Silithiden.",["race:NightElf"]="Als Nachtelf wandelt Ihr auf dem düsteren Boden, auf dem Eure Vorfahren im Krieg der Sandstürme bluteten. Tausende opferten ihr Leben, um die Tore von Ahn'Qiraj zu versiegeln."},sec={{t="Die Wüstengrenze",b="Ihr betretet Silithus vom Krater von Un'Goro aus durch einen breiten, felsigen Pass in dessen nordwestlicher Ecke. Der Dschungel weicht Dünen, zerklüftetem Gestein und hoch aufragenden Bauten. Wasser ist knapp, und der Wind trägt das Summen von Insektenflügeln über den Sand. Nahe der Mitte der Wüste bietet die Burg Cenarius Reisenden, Forschern und Kriegern Schutz. Der Zirkel des Cenarius unterhält diesen Außenposten als einzigen Zufluchtsort in der feindseligen Einöde."},{t="Echos des Wandelsands",b="Vor tausend Jahren kämpften Nachtelfen und die großen Drachenschwärme verzweifelt, um die Qiraji im Krieg der Sandstürme zurückzudrängen. Die Qiraji waren ein insektenartiges Imperium, das aus der uralten Aqiri-Zivilisation hervorging.\n\nAls sich der Sieg als unerreichbar erwies, sperrten die Verteidiger die Schwärme mit dem Skarabäuswall und der verzauberten Skarabäushöhe in ihrer Festung ein. Die Tore hielten stand, doch Silithiden gruben sich durch Tunnel darunter hindurch und bildeten in der ganzen Wüste gewaltige Kolonien, darunter den Bau des Ashischwarms, den Bau des Zoraschwarms und den Bau des Regalschwarms."},{t="Ein Sturm zieht auf",b="Der Hammer des Zwielichts hat mehrere Außenposten in Silithus befestigt. Seine Kultisten beschwören elementare Schrecken und verehren die dunkle Macht unter Ahn'Qiraj. Beobachter des Zirkels des Cenarius verfolgen die Ausbreitung der Silithidenkolonien und halten Wache gegen die uralte Bedrohung hinter dem Skarabäuswall."}},faq={{q="Wie komme ich zu Fuß nach Silithus?",a="Reist durch den Krater von Un'Goro bis in seine nordwestliche Ecke. Nahe einer Biegung des gewundenen Flusses führt eine ansteigende Schotterstraße zwischen zwei markanten Felssäulen hindurch und durch die Kraterwand nach Silithus.",al={"eingang nach silithus","wie kommt man nach silithus","weg durch silithus"}},{q="Was ist der Skarabäuswall?",a="Der Skarabäuswall ist eine gewaltige verzauberte Barriere im Süden von Silithus. Vor tausend Jahren errichteten Nachtelfen und die Drachenschwärme ihn während des Krieges der Sandstürme, um das Qiraji-Imperium in Ahn'Qiraj einzuschließen.",al={"tor von ahn'qiraj","der skarabäuswall","die große mauer in silithus"}},{q="Wer leitet die Burg Cenarius?",a="Der Zirkel des Cenarius hat die Burg Cenarius gegründet und leitet sie. Seine Druiden und verbündeten Wächter beobachten die Silithidenschwärme, untersuchen uralte Ruinen und heißen neutrale Reisende von Allianz und Horde willkommen.",al={"wer ist in der burg cenarius","fraktion der burg cenarius","burg cenarius freundlich"}},{q="Was sind die riesigen Insektenhügel in der ganzen Region?",a="Die gewaltigen Hügel sind die großen unterirdischen Bauten der Silithiden: der Bau des Ashischwarms, der Bau des Zoraschwarms und der Bau des Regalschwarms. Jeder birgt ein weitläufiges Tunnelsystem und eigene insektenartige Kasten, die dem Willen der Mächte hinter Ahn'Qiraj dienen.",al={"bauten in silithus","insektenbauten silithus","bau des ashischwarms bau des zoraschwarms"}},{q="Was treibt der Hammer des Zwielichts hier?",a="Der Hammer des Zwielichts unterhält mehrere befestigte Lager in Silithus, darunter das Basislager der Twilight und den Twilight-Posten. Seine Kultisten vollziehen finstere Riten, um Elementare zu beschwören, und verehren die uralten, bösartigen Wesen, die hinter dem Skarabäuswall begraben liegen.",al={"kultisten des hammer des zwielichts in silithus","twilight-außenposten silithus","warum ist der hammer des zwielichts in silithus"}}},fp="8,245,19.408.0,28.509.0,18.272.0,33.207.0,24.219.0,23.205.0,49.212.0,41.243.0"}
P.entries["zone:silverpine"] = {n="Silberwald",s="Patrouillen der Verlassenen halten den Silberwald, wo rivalisierende Mächte die Wälder an Lordaerons Westküste bedrohen. Die Seuche der Geißel hat den Wald gezeichnet, und Worgen, verseuchte Gnolle sowie feindselige menschliche Enklaven gefährden Reisende.",h="Patrouillen der Verlassenen halten den Silberwald, wo rivalisierende Mächte die Wälder an Lordaerons...",kw={"mühlenbern","arugal","insel fenris","der greymane-wall","lohenscheit","rot hide","das grabmal","shadowfang","silberwald"},ang={["class:Mage"]="Mühlenbern und der Abstieg des Erzmagiers Arugal in den wolfsartigen Wahnsinn machen den Silberwald zu einer düsteren Warnung vor Magie des Kirin Tor, die katastrophal fehlgeht.",["faction:Alliance"]="Entdecker der Allianz finden einen feindseligen Wald vor. Mühlenbern beherbergt nur eine schwache Garnison aus Dalaran, und die Bewohner von Lohenscheit sind verflucht.",["race:Undead"]="Der Silberwald ist die Frontlinie der Verlassenen südlich von Tirisfal. Die Königliche Apothekervereinigung testet hier neue Mixturen, während die Deathguard gegen verbliebene Agenten der Geißel kämpft."},sec={{t="Eine verwunschene Grenze",b="Der Silberwald erstreckt sich zwischen Tirisfal und dem versiegelten Greymane-Wall. Einst ein üppiges Wunder Lordaerons, ist er seit dem Dritten Krieg dahingewelkt. Geisterhafte Nebel ziehen zwischen sterbenden Kiefern mit silberner Rinde hindurch, während verfallene Gehöfte verlassen in der Wildnis liegen.\n\nIm Norden grenzt Tirisfal an den Wald, und im Osten erstreckt sich der Lordameresee entlang seiner Küste. Im Süden schirmt der Greymane-Wall Gilneas vom Chaos jenseits davon ab. Die Verlassenen halten ihren zentralen Außenposten beim Grabmal und kämpfen darum, die Wälder gegen Feinde von allen Seiten zu sichern."},{t="Rivalisierende Enklaven und die Geißel",b="Der Anspruch der Verlassenen auf den Silberwald wird von lebenden und untoten Mächten angefochten. Auf der Insel Fenris im Osten führt Thule Rabenklaue Überreste der Geißel an und befehligt seuchenverwirrte Rot Hide-Gnolle, die den nördlichen Ackerbaugebieten zusetzen. Im Süden halten menschliche Magier aus Dalaran Mühlenbern, eine befestigte Siedlung, in der sie mystische Forschungen betreiben und sich der Expansion der Verlassenen widersetzen.\n\nBeim Grabmal führen die Königliche Apothekervereinigung und Hochexekutor Hadrec einen brutalen Feldzug gegen diese Bedrohungen. Sie testen auch neue, hoch ansteckende Seuchen."},{t="Die Worgen und Shadowfang",b="Burg Shadowfang ragt über den südwestlichen Wäldern des Silberwalds auf und wird vom wahnsinnigen Dalaran-Erzmagier Arugal gehalten. Einst war sie der Sitz von Baron Silberlein. Während des Dritten Krieges beschwor Arugal Wolfsbestien aus einer anderen Dimension, um die Geißel zurückzuschlagen. Die Bestien wandten sich gegen ihre Beschwörer und verbreiteten einen lykanthropischen Fluch in den südlichen Wäldern.\n\nBei Tageslicht wirken die menschlichen Dorfbewohner von Lohenscheit gewöhnlich und gehen ihren Pflichten nach. Unter dem Nachthimmel verwandeln sie sich in wilde Worgen."}},faq={{q="Was ist der Greymane-Wall an der Südgrenze?",a="Der Greymane-Wall ist eine gewaltige Steinbarriere, die König Genn Greymane errichten ließ, um Gilneas vom übrigen Lordaeron abzuschotten. Als die Geißel während des Dritten Krieges den Kontinent verwüstete, verschloss Gilneas seine Tore und verweigerte Hilfe von außen. Die Gebiete nördlich der Mauer, darunter der südliche Silberwald, mussten allein zurechtkommen.",al={"warum gibt es eine riesige mauer","geschichte des greymane-walls","tor nach gilneas"}},{q="Warum greifen die Dorfbewohner von Lohenscheit nachts an?",a="Der Worgenfluch des Erzmagiers Arugal befällt die Bewohner von Lohenscheit. Tagsüber behalten sie ihre menschliche Gestalt und gehen ihrem Alltag nach; der Allianz gegenüber bleiben sie freundlich. Mit dem Aufgang des Mondes verwandelt der Fluch sie in wilde, blutdürstige Worgen, die jeden in ihrer Nähe angreifen.",al={"geheimnis von lohenscheit","worgen in lohenscheit","warum sind die menschen in lohenscheit nachts feindselig"}},{q="Wer ist Thule Rabenklaue?",a="Thule Rabenklaue ist ein mächtiger Nekromant im Dienst der Geißel. Von Burg Fenris auf der Insel Fenris im Lordameresee aus befehligt er Legionen von Untoten und beeinflusst die verseuchten Rot Hide-Gnolle im östlichen Silberwald. Sie bedrohen die Ostflanke der Verlassenen.",al={"wer führt die insel fenris","geschichte von thule ravenclaw","geißel auf der insel fenris"}},{q="Warum besetzt Dalaran Mühlenbern?",a="Magier aus Dalaran halten Mühlenbern unter der Führung von Erzmagier Ataeric. Von dem Dorf aus überwachen die menschlichen Magier die Bewegungen der Verlassenen, erforschen die magischen Leiden des Waldes und versuchen, den nahegelegenen Worgenausbruch einzudämmen, der sich von Burg Shadowfang ausbreitet.",al={"magier in mühlenbern","warum ist die allianz in mühlenbern","dalaran im silberwald"}},{q="Was ist das Grabmal?",a="Das Grabmal ist der wichtigste militärische Außenposten und Verkehrsknotenpunkt der Verlassenen im Silberwald. Unter Hochexekutor Hadrec dient es als Basis für Deathguard-Patrouillen, Deathstalker-Späher und die Königliche Apothekervereinigung, während sie darum kämpfen, den Wald zu sichern.",al={"hordenstadt im silberwald","wo ist der flugpunkt","geschichte des grabmals"}},{q="Können Allianzspieler im Silberwald Quests erledigen?",a="Im Silberwald gibt es keine Sammelplätze der Allianz und keine befreundeten Städte; die örtlichen Aufgaben sind allein für die Horde bestimmt. Abenteurer der Allianz kommen gewöhnlich auf dem Weg von Süderstade hierher, um Burg Shadowfang zu erkunden oder feindliche Streitkräfte der Verlassenen zu bekämpfen.",al={"ist der silberwald nur für die horde","allianzquests im silberwald","kann die allianz in den silberwald"}}},fx={["21fc6836"]={q="Was ist der Silberwald?",a="Der Silberwald ist ein riesiges, uraltes Waldgebiet entlang der rauen Westküste von Lordaeron, direkt südlich von Tirisfal und im Osten begrenzt durch den Lordameresee. Einst ein üppiger und grüner Wald, geschützt von der Allianz, ist er heute in geisterhafte Nebel, krankhaft blasse Kiefern und eine unheimliche Stille gehüllt, die nur durch entferntes Heulen unterbrochen wird. Die Verlassenen halten den Norden vom Grabmal aus, aber ihr Anspruch wird ständig von den Überresten der Geißel, wilden Rotkamm-Gnollen, Zauberern aus Dalaran und den verfluchten Worgen von Burg Shadowfang bestritten.",al={"was ist der silberwald","erzähl mir vom silberwald","silberwald lore"}},["01503e92"]={q="Was ist im Silberwald passiert?",a="Der Silberwald ähnelte einst der unberührten Wildnis des Hinterlands, aber der Dritte Krieg ruinierte ihn. Als die Geißel des Lichkönigs nach Süden zog, brannten untote Armeen Gehöfte nieder, schlachteten die ländliche Bevölkerung ab und verseuchten das Land mit der Seuche des Untods. König Genn Greymane schloss Gilneas hinter seiner massiven Mauer ab und gab nördliche Gebiete wie Lohenscheit und Mühlenbern auf. Um die Geißel abzuwehren, entfesselte Erzmagier Arugal wilde Worgen, doch der Fluch breitete sich außer Kontrolle aus. Mit dem Zusammenbruch von Lordaeron wurden die verseuchten Wälder zu einem umkämpften Schlachtfeld.",al={"silberwald geschichte","was passierte im silberwald","untergang des silberwalds"}},b9edb2aa={q="Wer lebte hier vor den Verlassenen?",a="Vor dem Dritten Krieg wurde der Silberwald von menschlichen Bauern, Bergleuten und Soldaten aus Lordaeron und Gilneas bewohnt. Südliche Siedlungen wie Lohenscheit und Mühlenbern blieben draußen, als sich Gilneas hinter dem Greymane-Wall verschanzte. Die Insel Fenris beherbergte eine geschäftige Militärgarnison von Lordaeron in Burg Fenris. Die meisten dieser ehemaligen Bewohner kamen während der Invasion der Geißel ums Leben, flohen nach Süden hinter den versiegelten Wall oder erlagen dem Untod und dem Worgenfluch.",al={"wer lebte früher im silberwald","ehemalige bewohner des silberwalds","frühere einwohner des silberwalds"}},["5b2addb4"]={q="Warum sieht der Wald so tot aus?",a="Der Wald trägt die tiefen, bleibenden Narben des Dritten Krieges. Silberwald markiert das südlichste Ausmaß, in dem die Seuche der Untoten der Geißel die Flora sichtbar verdarb, die Lebenskraft aus dem Boden zog und die uralten Kiefern mit ihrer silbernen Rinde bleich, kränklich und ihre verdorbenen Nadeln abwerfend zurückließ. Da Lordaeron zerstört und Gilneas abgeriegelt wurde, blieben keine Pfleger zurück, um die verwüsteten Haine zu heilen oder die verbrannten Äcker zu bestellen, wodurch kalte Nebel und Fäulnis über die Wälder zogen.",al={"warum stirbt der silberwald","warum sieht der silberwald tot aus","verdorrte bäume silberwald"}},["67376895"]={q="Ist der Silberwald gefährlich?",a="Äußerst gefährlich. Wilde Raubtiere wie verseuchte Bären, riesige Spinnen und grausame Worgs schleichen unter den Bäumen. Die seuchenbefallenen Rotkammgnolle schlachten Reisende entlang der Straßen brutal ab, während menschliche Magier aus Dalaran Mühlenbern gegen das Eindringen der Horde befestigen. Im Süden terrorisieren die wilden Mondzorn-Worgen unter dem Einfluss von Erzmagier Arugal die Täler. Außerhalb des befestigten Zufluchtsorts Das Grabmal erfordert das Überleben ständige Wachsamkeit.",al={"wie gefährlich ist der silberwald","bedrohungen im silberwald","ist es hier sicher"}},["6dcc337b"]={q="Warum hat die Horde mich in den Silberwald geschickt?",a="Ihr wurdet von Tirisfal aus nach Süden geschickt, um die Grenze der Verlassenen zu verstärken. Die Unterstadt betrachtet den Silberwald als entscheidend für die Sicherung ihrer Südgrenze, doch ihr Halt ist zerbrechlich und überdehnt. Hochexekutor Hadrec und die Todeswache benötigen fähige Recken, um eindringende Nekromanten der Geißel zurückzuschlagen, feindselige Gnolle zu eliminieren, Dalarans verdeckte Manöver zu überwachen und die blutrünstigen Worgen einzudämmen, die zu überrennen drohen.",al={"warum bin ich im silberwald","horde ankunft silberwald","warum hierher geschickt"}},ab9ff98b={q="Ist dies noch Land der Verlassenen?",a="Die Verlassenen beanspruchen den Silberwald als souveränes Territorium der Unterstadt, doch ihre Kontrolle ist stark umstritten. Während sie im nördlichen Silberwald und im befestigten Zufluchtsort Das Grabmal festen Besitzstand wahren, haben sie keine unbestrittene Herrschaft über den gesamten Wald. Feindselige Rotkammgnolle beherrschen die östlichen Gewässer, Dalaran-Zauberer besetzen Mühlenbern und Arugals wilde Worgen dominieren die südwestlichen Regionen.",al={"gehört silberwald den verlassenen","wer kontrolliert den silberwald","territorium der verlassenen silberwald"}},["858ebaa5"]={q="Wer hat Das Grabmal erbaut?",a="Vor dem Dritten Krieg war Das Grabmal einfach ein großer, ruhiger menschlicher Friedhof mit einer Krypta am Straßenrand, die von den Bewohnern Lordaerons errichtet wurde, um ihre Toten entlang der westlichen Hauptstraße beizusetzen. Nach dem Fall von Lordaeron beschlagnahmten die überlebenden Verlassenen das Bestattungsgelände und bauten die Krypta zu einem befestigten Militäraußenposten, einer Karawanenstation und einem logistischen Hauptquartier für ihre südlichen Operationen um.",al={"wer hat das grabmal gebaut","ursprung das grabmal","geschichte das grabmal"}},f51f7d3d={q="Warum haben die Verlassenen ihre Basis im Grabmal?",a="Das Grabmal liegt verteidigungstechnisch günstig in den westlichen Hügeln und bietet den Verlassenen einen natürlichen Aussichtspunkt über die Küste und die Hauptstraße. Positioniert zwischen der Geißel im Osten, Dalaran im Südosten und wilden Worgen im Süden, dient es als einziger sicherer Außenposten, von dem aus Patrouillen der Todeswache und Forscher der Königlichen Apothekervereinigung die Verteidigung koordinieren und die Route nach Tirisfal schützen können.",al={"warum sind verlassene im das grabmal","basis der verlassenen das grabmal warum","bedeutung von das grabmal"}},["0581536d"]={q="Wer ist Hochexekutor Hadrec?",a="Hochexekutor Hadrec ist der militärische Kommandant der Operationen der Verlassenen im Silberwald und im Grabmal stationiert. Streng und pragmatisch leitet er die Todeswache und die Späher der Todespirscher bei der Befriedung der Wildnis an, deckt versteckte Bedrohungen auf und koordiniert Angriffe gegen feindselige Kräfte wie Thule Rabenklaue und die Rotkammgnolle.",al={"hadrec","wer ist hadrec","hochexekutor hadrec silberwald"}},ff53d58c={q="Wem ist Hochexekutor Hadrec unterstellt?",a="Hadrec ist direkt Fürstin Sylvanas Windläufer, der Banshekönigin der Verlassenen, und ihrem Oberkommando in der Unterstadt unterstellt. Als hochrangiger Offizier der Todeswache besteht sein Mandat darin, die Grenzen ihres neugeborenen Königreichs zu sichern und jede Macht zu eliminieren, die die Souveränität der Verlassenen gefährden könnte.",al={"wer ist hadrecs chef","hadrecs vorgesetzter","wem berichtet hadrec"}},["6c73f41e"]={q="Wer sind die Rotkammgnolle und warum sind sie hier?",a="Die Rotkammgnolle sind ein bösartiger Gnollklan, der den Silberwald bewohnt, hauptsächlich von Insel Fenris aus operiert und die Ufer des Lordameresee durchstreift. Im Gegensatz zu gewöhnlichen Gnollen sind sie von der Seuche der Untoten befallen, haben fleckiges graues Fell und trübe, gelbe Augen. Sie führen einen brutalen Guerillakrieg gegen die Verlassenen, plündern Schlachtfelder und greifen jeden, der sich ihren Lagern nähert, heftig an.",al={"rotkammgnolle","warum sind gnolle im silberwald","rotkammgnoll silberwald"}},ad054bc9={q="Wer kontrolliert die Rotkammgnolle?",a="Die Rotkammgnolle stehen unter dem Bann von Thule Rabenklaue, einem verräterischen Nekromanten, der sich der Geißel angeschlossen hat. Von seiner Festung auf Insel Fenris aus nutzt Thule dunkle Magie, um diese verdorbenen Bestien zu manipulieren und sie zu ausgehobenen Schlachtfeldern zu schicken, um frische Leichen für seine wachsenden Legionen von Untoten zu ernten.",al={"wer befehligt die rotkammgnolle","meister der rotkammgnolle","wer führt die rotkammgnolle"}},["97f89d60"]={q="Was sind Das Todesfeld?",a="Das Todesfeld ist eine verdorbene landwirtschaftliche Fläche im zentralen Silberwald, entlang der Straße, die zum Lordameresee führt. Einst ein friedliches Gehöft, wurde es während des Dritten Krieges zu einem Massenmordplatz, als die Geißel Lordaeron überrannte. Heute ist es ein offener Friedhof, übersät mit flachen Gräbern und aufgewühlter Erde.",al={"das todesfeld silberwald","das todesfeld","was ist das todesfeld"}},d487a8f2={q="Warum graben die Gnolle in Das Todesfeld?",a="Die Rotkammgnolle graben Das Todesfeld um, um die während des Dritten Krieges dort begrabenen menschlichen Leichen auszugraben. Auf Befehl von Thule Rabenklaue graben sie Körper und konservierte Überreste aus, um den Nekromanten mit Rohmaterial für den Bau von Konstrukten der Geißel und zur Verstärkung seiner untoten Armee auf Insel Fenris zu versorgen.",al={"warum graben die rotkammgnolle","gnolle das todesfeld warum","gnoll gräbt nach leichen"}},["3bca491d"]={q="Was befindet sich auf Insel Fenris?",a="Insel Fenris ist eine große Insel, die im Lordameresee vor der Ostküste des Silberwaldes liegt. Sie wird von Burg Fenris dominiert, einer ehemaligen Militärfestung von Lordaeron, die in einen dunklen Verfall geraten ist. Heute dient die Insel als schwer befestigte Zuflucht, die von Rotkammgnollen und den untoten Schergen von Thule Rabenklaue wimmelt.",al={"insel fenris","was ist auf insel fenris","burg fenris"}},bd044bca={q="Warum will Hadrec, dass Insel Fenris angegriffen wird?",a="Hadrec erkennt Insel Fenris als das schlagende Herz der Bedrohung durch die Geißel im östlichen Silberwald. Thule Rabenklaue in Burg Fenris verschanzt zu lassen, gibt der Geißel einen unangreifbaren Aufmarschpunkt, um untote Gnolle zu erheben, Versorgungskarawanen zu überfallen und den östlichen Zugang nach Tirisfal zu bedrohen. Der Angriff auf die Insel ist entscheidend, um Thules Macht zu brechen und den See zu sichern.",al={"warum insel fenris angreifen","hadrec insel fenris motiv","angriff auf insel fenris grund"}},["574e415e"]={q="Arbeiten die Dalaran-Zauberer in Mühlenbern mit der Allianz zusammen?",a="Ja. Während Dalaran sich stark auf den Wiederaufbau seiner zerstörten Stadt konzentriert, bleiben die in Mühlenbern stationierten Streitkräfte der Kirin Tor der Allianz gegenüber offen freundlich gesinnt und der Horde gegenüber erbittert feindselig. Dalaran schickt häufig Unterstützung an die überlebenden menschlichen Enklaven im Silberwald, widersetzt sich der Expansion der Verlassenen und arbeitet eng mit den südlichen Überresten zusammen.",al={"mühlenbern dalaran allianz","ist dalaran hier bei der allianz","kirin tor allianz silberwald"}},fd7851b2={q="Wer ist Arugal und was ist 'Arugals Torheit'?",a="Erzmagier Arugal war ein Zauberer aus Dalaran, der in seiner Verzweiflung, sich während des Dritten Krieges gegen die Geißel zu verteidigen, zu verbotener Magie griff und monströse Wolfbestien, bekannt als Worgen, beschwor. Die wilden Bestien wandten sich jedoch gegen die Zauberer der Kirin Tor und unschuldige Einheimische gleichermaßen und verbreiteten einen gefräßigen Lykanthropie-Fluch im südlichen Silberwald. Getrieben vom Wahnsinn durch Schuldgefühle und Entsetzen über das, was er entfesselt hatte, zog sich Arugal in Burg Shadowfang zurück und nahm die Worgen als seine 'Kinder' an.",al={"arugal","arugals torheit","wer war arugal","erzmagier arugal lore"}},f38b73fd={q="Woher kamen die Worgen?",a="Die Worgen sind außerweltliche Wolfbestien, die von Erzmagier Arugal durch Dimensionen gezogen wurden. Auf der Suche nach einer Waffe, um Dalaran während des Dritten Krieges gegen die Geißel zu stärken, beschwor Arugal diese Kreaturen in den Silberwald, wo sie sich schnell gegen ihre Beschwörer wandten und einen transformierenden Fluch verbreiteten.",al={"woher kamen die worgen","worgen ursprung silberwald","wie kamen worgen hierher"}},fc903f13={q="Ist Arugal noch am Leben?",a="Ja, Erzmagier Arugal ist sehr wohl am Leben. Umhüllt von Wahnsinn residiert er hoch oben in den Türmen von Burg Shadowfang und überblickt Lohenscheit. Von seiner Festung aus lenkt er sein Rudel Shadowfang-Worgen und bewacht seine verdrehte lupine Domäne vor jedem, der mutig genug ist, seine Tore zu durchbrechen.",al={"ist arugal am leben","wo ist arugal jetzt","arugal status"}},["5dc043c6"]={q="Was ist Lohenscheit?",a="Lohenscheit ist eine menschliche Siedlung im südwestlichen Silberwald, direkt unter den imposanten Klippen von Burg Shadowfang. Sie blieb draußen, als Gilneas vor dem Dritten Krieg den Greymane-Wall versiegelte. Die überlebenden Bewohner kämpfen darum, tagsüber einen Anschein von normalem Leben aufrechtzuerhalten, obwohl eine uralte Dunkelheit sie verzehrt, sobald die Sonne untergeht.",al={"lohenscheit lore","was ist lohenscheit","stadt lohenscheit"}},["20eec241"]={q="Wo führt das alles nach dem Silberwald hin?",a="Sobald Ihr den Silberwald stabilisiert habt, indem Ihr Thule Rabenklaue konfrontiert und Arugal in Burg Shadowfang beseitigt, führt Eure Reise normalerweise nach Osten über die Berge in das Vorgebirge des Hügellands, um die Verlassenen bei Tarrens Mühle zu unterstützen. Alternativ nehmen viele Reisende der Horde einen Zeppelin nach Kalimdor, um durch die weiten Ebenen im Brachland zu kampieren.",al={"wohin nach dem silberwald","nächstes gebiet nach silberwald","silberwald nächster schritt"}},da147569={q="Wie bin ich im Silberwald gelandet?",a="Ihr seid wahrscheinlich der Straße nach Süden aus Tirisfal gefolgt und habt den Gebirgspass südwestlich der Ruinen von Unterstadt durchquert. Charaktere der Verlassenen sichern ihre nördliche Heimat in Tirisfal und stoßen dann ganz natürlich nach Süden in den Silberwald vor, um das junge Reich zu erweitern. Alternativ kommen Reisende der Horde von anderen Kontinenten per Zeppelin vor der Unterstadt an, bevor sie die Küste hinunterwandern, während seltene Abenteurer aus dem Süden möglicherweise das Vorgebirge des Hügellands durchqueren, um diese verseuchten Wälder zu erreichen.",al={"wie bin ich hierher gekommen","wie erreiche ich den silberwald","weg zum silberwald"}},["97a9302a"]={q="Was soll ich im Silberwald tun?",a="Ihr seid hier, um den Verlassenen dabei zu helfen, ihre südliche Grenze gegen wachsende Gefahren zu sichern. Meldet Euch bei Hochexekutor Hadrec und den Todespirschern am Grabmal. Ihr müsst die krankheitsbefallenen Rotpelzgnolle aufhalten, die aus den Todesfeldern und von der Insel Fenris plündern, die Nekromanten der Geißel wie Thule Rabenklaue ausrotten und die Zauberer von Dalaran im Auge behalten, die sich in Mühlenbern verschanzt haben. Weiter südlich werdet Ihr außerdem die gefräßigen Wolfsbestien untersuchen, die Lohenscheit terrorisieren, sowie den Schatten, der von Burg Shadowfang ausgeht.",al={"was ist meine mission hier","warum wurde ich in den silberwald geschickt","was tun wir im silberwald"}}},fp="17,230,18.551.0,30.531.1,25.482.1,49.319.0,57.270.1,23.261.1,35.243.0,22.247.0,48.232.0"}
P.entries["zone:stockade"] = {n="Das Verlies",s="Eine gewaltsame Rebellion hat Das Verlies unter den Kanälen von Sturmwind nahe dem Magierviertel erfasst. Das Verlies wurde als Hochsicherheitsgefängnis für Halsabschneider, politische Aufrührer und gefangene Staatsfeinde erbaut, doch nun herrscht dort Anarchie unter gefährlichen Gefangenen. Aufseher Thelwasser wurde zum Eingang zurückgedrängt und sucht Hilfe, bevor der Aufstand die Hauptstadt erreicht.",h="Eine gewaltsame Rebellion hat Das Verlies unter den Kanälen von Sturmwind nahe dem Magierviertel erfasst.",kw={"bazil thredd","bruegal eisenfaust","canals","defias","dextren ward","hamhock","kam tiefenzorn","aufstand","verlies","sturmwind","targorr","aufseher thelwasser"},ang={["class:Mage"]="Das Gefängnis liegt am Kanalufer des Magierviertels, wo körperliche Schläger anfällig für Verlangsamungszauber sind. Der Oger-Magier Hamhock kann Kettenblitz entfesseln.",["class:Rogue"]="Das verwinkelte Netz aus verschlossenen Eisenzellen und Verbindungen zu den Defias bietet einzigartige Möglichkeiten, Schlösserknacken zu üben und Einblicke in Bazil Thredds Unterwelt-Syndikat zu gewinnen.",["faction:Alliance"]="Die Rebellion bedroht Sturmwinds innere Sicherheit und das Herz der Hauptstadt. Sie niederzuschlagen schützt diese Sicherheit und erfüllt geheime Kopfgelder aus dem Rotkammgebirge, dem Dämmerwald und der Eisenschmiede.",["race:Dwarf"]="Kam Tiefenzorn in Sturmwinds Zellen zu wissen, ist eine Beleidigung für Dun Modr. Das Königreich Eisenschmiede fordert seinen Kopf, um die im Sumpfland verlorenen Zwergenleben zu rächen."},sec={{t="Ein Gefängnis unter Belagerung",b="Unter den Kanälen von Sturmwind ist Das Verlies zum Kriegsgebiet geworden. Als die reguläre Armee an ferne Fronten zog, mussten die unterbesetzten Gefängniswachen auf unerfahrene Jugendliche zurückgreifen, darunter vierzehnjährige Rekruten. Sie konnten die Ordnung nicht aufrechterhalten. Die Insassen begannen eine blutige, koordinierte Rebellion, zerrissen ihre Wolldecken zu Gangschals und metzelten die verbliebenen Wachen nieder. Aufseher Thelwasser kann den Eingang kaum halten, während die Sträflinge Zellen, Flure und Haftblöcke kontrollieren."},{t="Adlige und Assassinen",b="Der Aufstand legte Sturmwinds politische Machenschaften offen. Die Gebiete außerhalb der Stadt waren zunehmend frustriert über das Haus der Nobles, das Hinrichtungen aussetzte, um die Gefangenen als politisches Druckmittel einzusetzen. Wache Berton aus dem Rotkammgebirge wollte den gefangenen Orc Targorr der Schreckliche wegen seiner Gräueltaten hinrichten lassen, doch die Adligen setzten sein Urteil aus.\n\nRatsherr Mühlenstein aus Dunkelhain musste mitansehen, wie der Grabräuber Dextren Ward dem Galgen entging, obwohl er für den Nekromanten Morbent Fel Gräber geschändet hatte. Auch die Zwerge von Dun Modr forderten den Tod des Dunkeleisensaboteurs Kam Tiefenzorn. Als im Verlies das Chaos ausbrach, heuerten die örtlichen Behörden im Stillen Abenteurer an, um die Hinrichtungen auszuführen, welche die Gerichte der Hauptstadt nicht vollstrecken wollten."},{t="Der Drahtzieher und die Aufrührer",b="Bazil Thredd, ein gerissener Verbrecher mit Verbindungen zur Bruderschaft der Defias, organisierte den Aufstand aus seiner Zelle. Bruegal Eisenfaust gehört zu den Aufrührern und ist ein gefährlicher zwergischer Schläger. Er ist einer von mehreren hartgesottenen Sträflingen, denen Abenteurer begegnen könnten, während sie Thelwasser helfen, das Gefängnis zurückzuerobern."}},faq={{q="Warum ist im Verlies eine offene Rebellion ausgebrochen?",a="Die Bruderschaft der Defias organisierte einen Aufstand im ganzen Gefängnis, während es stark unterbesetzt war. Da die Armee von Sturmwind an ferne Fronten entsandt worden war, bewachten jugendliche Freiwillige hartgesottene Mörder. Die Sträflinge überfielen das Personal, bemächtigten sich der Waffen und drängten Aufseher Thelwasser aus den Zellenblöcken.",al={"warum der aufstand","was geschah im verlies","ursache des aufstands im verlies"}},{q="Wer führt den Aufstand im Gefängnis an?",a="Bazil Thredd, ein einflussreicher Defias-Verbrecher im östlichen Zellenblock, plante den Aufstand. Zu den weiteren gefährlichen Gefangenen zählen Bruegal Eisenfaust, Hamhock und Kam Tiefenzorn.",al={"bosse im verlies","wer führt den aufstand an","wer kontrolliert das verlies"}},{q="Warum leben Gefangene wie Targorr und Dextren Ward noch?",a="Beide waren zum Tode verurteilt, doch korrupte Politiker im Haus der Nobles ließen ihre Hinrichtungen bürokratisch aufschieben, um die Gefangenen als politisches Druckmittel einzusetzen. Diese Einmischung empörte Verbündete in Seenhain und Dunkelhain, die Abenteurer schickten, um sie während des Chaos zu töten.",al={"warum wurde targorr nicht hingerichtet","dextren ward vor gericht","korruption im haus der nobles"}},{q="Was bedeutet es für das Gefängnis, Bruegal Eisenfaust zu besiegen?",a="Bruegal Eisenfaust ist ein gefährlicher zwergischer Schläger unter den Aufrührern. Ihn zu besiegen beseitigt eine Bedrohung, während Abenteurer den Aufstand niederschlagen.",al={"bruegal eisenfaust hintergrund","bruegal töten","wer ist bruegal"}},{q="Warum sind Dunkeleisenzwerge und Orcs in einem Menschgefängnis?",a="Das Verlies ist ein Hochsicherheitsgefängnis für besonders wichtige Kriegsgefangene. Targorr der Schreckliche führte Angriffe der Schwarzfelsorcs im Rotkammgebirge an, während Kam Tiefenzorn das Sumpfland für den Dunkeleisenklan sabotierte. Beide wurden gefangen genommen und in die Hauptstadt gebracht.",al={"warum sind dunkeleisenzwerge hier","kam tiefenzorn hintergrund","targorr im verlies"}},{q="Können Spieler der Horde das Verlies betreten?",a="Ja, aber der Zutritt ist äußerst gefährlich. Das Verliesportal befindet sich in Sturmwind nahe den Kanälen des Magierviertels. Infiltratoren der Horde müssen sich an den Stadtwachen und den Verteidigern der Hauptstadt vorbeischleichen, um es zu erreichen.",al={"können hordespieler ins verlies","horde im gefängnis von sturmwind"}}},fx={["07af5e0b"]={q="Was ist das Verlies?",a="Das Verlies ist Sturmwinds Hochsicherheitsgefängnis, das unter dem Kanalviertel der Hauptstadt errichtet wurde. Es dient als Verwahrungsort für Kleinkriminelle, Halsabschneider, politische Aufständische und hochkarätige Feinde des Königreichs, die auf ihr Urteil warten.",al={"was ist das verlies","gefängnis das verlies","sturmwind gefängnis"}},["2fc364a6"]={q="Ist das Verlies nur für die Defias?",a="Nein. Während die Bruderschaft der Defias den Kern des Aufstands bildet, beherbergen die Zellen auch Kleinkriminelle, Grabräuber wie Dextren Ward, gefangene Schwarzfels-Orcs wie Targorr der Schreckliche und sogar Dunkeleisensabotöre wie Kam Tiefenzorn.",al={"ist das verlies nur für defias","wer ist im verlies","sind alle gefangenen defias"}},["0d433487"]={q="Warum sind hier so viele Defias eingesperrt?",a="Sturmwinds Behörden haben Agenten der Bruderschaft in ganz Westfall, dem Wald von Elwynn und in der Stadt selbst gefasst. Anstatt sie sofort hinzurichten, hat die Krone sie in das Verlies verfrachtet und damit ein gefährliches Netzwerk von Aufständischen direkt unter den Dielen der Stadt konzentriert.",al={"warum so viele defias hier","warum defias im verlies","gefangene der bruderschaft der defias"}},e96a18b2={q="Wer leitet dieses Gefängnis?",a="Aufseher Thelwasser leitet die Einrichtung. Als der Aufstand ausbrach, wurden seine Wachen überwältigt und aus den Zellentrakten vertrieben. Thelwasser konnte gerade noch den Eingangsbereich halten, was ihn dazu zwang, verzweifelt nach fähigen Abenteurern zu suchen, um die Korridore zurückzuerobern.",al={"wer leitet das verlies","aufseher des verlieses","aufseher thelwasser"}},["06cbacdc"]={q="Warum können Aufseher Thelwassers Wachen den Aufstand nicht bewältigen?",a="Die Gefängniswache war bereits extrem dünn besetzt, sodass man sogar Freiwillige im Alter von nur vierzehn Jahren einsetzte, um gefährliche Sträflinge zu bewachen. Als die Defias sich zusammenschlossen und angriffen, wurde das Personal völlig unvorbereitet erwischt, niedergemetzelt oder zur Flucht in die Eingangshalle gezwungen.",al={"warum können wachen aufstand nicht stoppen","wo sind die gefängniswachen","wachen im verlies"}},["7c158547"]={q="Warum schickt Sturmwind mich hinein und nicht die Armee?",a="Ein Großteil von Sturmwinds Militär ist an weit entfernten Fronten im Einsatz, und die korrupte Bürokratie im Haus der Adligen lähmt schnelles kommunales Handeln. Zudem sind Stadtbeamte verzweifelt bemüht, den Aufstand geheim zu halten, um eine offene Panik in den Straßen zu vermeiden.",al={"warum abenteurer schicken","warum nicht die armee ins verlies","wo ist die armee von sturmwind"}},a2006c52={q="Wissen die Wachen draußen, was im Inneren vor sich geht?",a="Die Wachen halten die Aufständischen an der Schwelle des Kerkers auf, und Aufseher Thelwasser sucht Hilfe, um die Ordnung im Inneren wiederherzustellen. Die Stadtbeamten halten den Vorfall geheim, um die normalen Bürger nicht zu beunruhigen.",al={"wissen wachen draußen bescheid","weiß sturmwind vom aufstand","geheimnis des verlieses"}},b1798127={q="Was ist der Unterschied zwischen den Gefangenen, Sträflingen und Aufständischen hier drin?",a="Die Insassen reichen von gewöhnlichen Gaunern und Taschendieben, die von den Straßen aufgelesen wurden, bis hin zu verurteilten Schwerverbrechern und kompromisslosen Defias-Aufständischen. Während gewöhnliche Sträflinge die Gelegenheit nutzten, zu randalieren und zu plündern, erhalten die Aufständischen aktiv Befehle von Bazil Thredd, um das Gefängnis zu übernehmen.",al={"sträflinge aufständische gefangene","gegnerarten im verlies","wer sind die insassen"}},["378bbf14"]={q="Wie kamen die Insassen an Waffen und wie haben sie sich organisiert?",a="Der Aufstand wurde akribisch vom Defias-Anführer Bazil Thredd geplant. Unter seiner Regie zerrissen die Gefangenen ihre Wolldecken zu roten Bandenschals, überfielen die unterbesetzten Wachen, stahlen deren Waffen und Schlüssel und befreiten methodisch die Zellen in jedem Flügel.",al={"wie kamen gefangene an waffen","wie haben sich defias organisiert","wer hat die gefangenen bewaffnet"}},["855deb71"]={q="Warum baut man ein Gefängnis direkt unter die Stadt?",a="Der Gefängniskomplex liegt unter den Kanälen von Sturmwind. Die ursprüngliche Platzierung wird nicht erklärt.",al={"warum gefängnis unter sturmwind","standort des verlieses warum","gefängnis unter den kanälen"}},caa2e4bf={q="Wie bin ich im Verlies gelandet?",a="Ihr seid durch die schweren Eisentüren von den nördlichen Kanälen in Sturmwind eingetreten. Unter den Straßen brach ein massiver Aufstand aus, und die verbliebenen Wachen von Aufseher Thelwasser wurden bis zur Schwelle zurückgedrängt, wodurch die Sträflinge die Kontrolle übernahmen. In der Verzweiflung, das Chaos vor den Bürgern oben geheim zu halten, heuerte der Aufseher fähige Abenteurer an, um direkt in die Zellentrakte zu marschieren und die Einrichtung mit Gewalt zurückzuerobern.",al={"wie bin ich hierher gekommen","warum bin ich hier","wie habe ich das verlies betreten"}},["45edc40e"]={q="Was soll ich im Verlies tun?",a="Eure Hauptmission ist es, den Aufstand niederzuschlagen und seinem Anführer, dem Drahtzieher der Defias Bazil Thredd, ein Ende zu setzen. Verbündete im ganzen Königreich haben diesen Moment des Chaos jedoch genutzt, um überfällige Schulden zu begleichen: Dunkelhain sucht Vergeltung für den Grabräuber Dextren Ward, Seenhain will den rücksichtslosen Orc Targorr der Schreckliche tot sehen, und Eisenschmiede fordert den Kopf des Saboteurs Kam Tiefenzorn.",al={"was ist meine mission hier","was tue ich hier","warum bin ich hier"}}},fp="12,345,20.476.0,20.680.1,30.277.1,38.302.0,35.174.0,60.285.0,60.151.0,61.253.0,37.213.0"}
P.entries["zone:stonetalon"] = {n="Steinkrallengebirge",s="Im Steinkrallengebirge treffen heilige Höhen auf Rauch, gefällte Wälder und verwüstete Erde. Nachtelfen und Tauren verehren das Gebirge, während an seinen Grenzen Spannungen schwelen.",h="Im Steinkrallengebirge treffen heilige Höhen auf Rauch, gefällte Wälder und verwüstete Erde.",kw={"das verbrannte tal","gerenzo wrenchwhistle","malaka'jin","steinkrallengebirge","der steinkrallengipfel","sonnenfels","talondeep pass","scherwind"},ang={["class:Druid"]="Die Entweihung der Scherwindklippe und die versengte Verderbnis des Verbrannten Tals rufen Druiden herbei, die erzürnte Naturgeister besänftigen und heilige Rastplätze schützen sollen.",["class:Shaman"]="Goblinbohrer greifen die Berggeister an, deren Schreie bis nach Orgrimmar dringen. Schamanen folgen dem Ruf, um tobende Felselementare zu bändigen und das Gleichgewicht auf den Gipfeln wiederherzustellen.",["faction:Alliance"]="Vom Steinkrallengipfel und aus versteckten Lagern rund um die Scherwindklippe verteidigt die Allianz uralte Kaldorei-Grabhügel gegen Goblinmaschinen und Rivalen, die ihr Gebiet beanspruchen.",["faction:Horde"]="Reisende der Horde verlassen sich auf Sonnenfels und Malaka'jin, den südlichen Trollaußenposten, um die Verschmutzung durch die Venture Company einzudämmen und Grimtotem-Gesetzlose aufzuspüren."},sec={{t="Die Bösen Winde und die Gipfel",b="Das Steinkrallengebirge erhebt sich im zentralen Kalimdor unter den Bösen Winden. Feuchtigkeit von den westlichen Meeren bringt plötzliche Wolkenbrüche, die die Sandsteinpfade glitschig machen. Heftige Böen fegen durch die tiefer gelegenen Täler, blenden Reisende mit Sand und reißen Unachtsame manchmal von den Klippen.\n\nAuf den höheren Graten wachsen immergrüne Wälder rund um den Steinkrallengipfel. Nachtelfen pflegen dort die Grabhügel ihrer Ahnen und die Haine. Außerdem bewachen sie heilige Rastplätze von Wyvern und Hippogryphen entlang des Mirkfallonsees."},{t="Industrie und Eindringlinge",b="Die Venture Company hat die Stille des Gebirges mit Holzfällercamps und Tagebauen in der Scherwindklippe gebrochen. Mit Unterstützung des wahnsinnigen Lepragnoms Gerenzo Pfeifzang haben die Goblins uralte Wälder gefällt und den Himmel mit Ofenrauch gefüllt. Ihr Industrieschlamm verschmutzt das abfließende Bergwasser.\n\nÖrtliche Schamanen aus Orgrimmar erhörten die Schreie der Berggeister. Auch kleine Lager der Allianz in der Nähe leisten den Entweihten Widerstand und versuchen, die verbliebenen Hochländer zu schützen."},{t="Narben der Vergangenheit",b="Im Süden liegt das Verbrannte Tal, einst eine blühende Wildnis und heute eine aschebedeckte Ödnis. Schurken-Feuerelementare, schwarze Drachenbrut und Harpyien bevölkern seine Ruinen. Während des Dritten Krieges schlossen Horde und Allianz unter der Führung des geheimnisvollen Orakels einen brüchigen Waffenstillstand auf diesen Gipfeln.\n\nSeitdem haben sich die Beziehungen verschlechtert. Abtrünnige Grimtotem-Tauren halten besetzte Lager, während Dunkelspeertrolle in Malaka'jin mit Streitkräften der Allianz zusammenstoßen, die aus dem Brachland und Eschental vordringen."}},faq={{q="Wie komme ich ins Steinkrallengebirge?",a="Die meisten Reisenden erreichen das Steinkrallengebirge über den Talondeep Pass, einen Gebirgspfad aus dem Südwesten Eschentals. Hohe Pfade führen nach Süden in Desolace, während Wege nach Osten ins nördliche Brachland hinabführen.",al={"eingang zum steinkrallengebirge","weg ins steinkrallengebirge","straße im steinkrallengebirge"}},{q="Warum ist das Verbrannte Tal verbrannt und verwüstet?",a="Das Verbrannte Tal war einst ein üppiges Refugium, doch eine katastrophale Verwüstung verzehrte es in Flammen. Heute ist es eine aschebedeckte Ruine voller aggressiver Feuerelementare, Schurkendrachen und tödlicher Harpyien.",al={"feuer im verbrannten tal","was geschah mit dem verbrannten tal","warum brannte das verbrannte tal"}},{q="Was macht die Venture Company in der Scherwindklippe?",a="Die Venture Company fällt Holz und gräbt tief in der Scherwindklippe nach wertvollen Mineralien. Ihre Aktivitäten haben den Felskesselsee mit Motorenschmiere verschmutzt, die Täler kahl geschlagen und die örtlichen Geister und Bewohner erzürnt.",al={"venture company im steinkrallengebirge","goblins an der scherwindklippe","warum fällen goblins bäume"}},{q="Wo befinden sich die wichtigsten Flugmeister?",a="Helden der Allianz nutzen den Flugmeister beim hoch gelegenen Heiligtum am Steinkrallengipfel im Norden. Reisende der Horde verlassen sich auf das zentrale Bergdorf Sonnenfels.",al={"flugroute im steinkrallengebirge","wo ist der flugpunkt im steinkrallengebirge","flugpunkt im steinkrallengebirge"}},{q="Was geschah während des Dritten Krieges am Steinkrallengipfel?",a="Während des Dritten Krieges folgten Thrall und Jaina Prachtmeer Visionen des Propheten Medivh durch die Höhlen des Steinkrallengipfels, um das Orakel zu suchen. Dort schlossen sie am Hyjal ein vorübergehendes Bündnis gegen die Brennende Legion.",al={"geschichte des steinkrallengipfels","das orakel im steinkrallengebirge","dritter krieg im steinkrallengebirge"}},{q="Wer sind die Grimtotem im Steinkrallengebirge?",a="Die Grimtotem sind ein abtrünniger Taurenstamm, der fremden Einfluss bekämpft. Im Steinkrallengebirge besetzen sie einen Außenposten nahe der Grenze zum Brachland, terrorisieren Reisende und nehmen Gefangene.",al={"posten der grimmtotem","grimtotem im steinkrallengebirge"}}},fx={["4946a833"]={q="Was ist das Steinkrallengebirge?",a="Das Steinkrallengebirge ist eine raue, vom Wind geformte Gebirgskette im Zentrum von Kalimdor, gelegen westlich des Brachlands, südlich des Eschentals und nördlich von Desolace. Bekannt für extreme Winde, tiefe Schluchten und steile Sandsteingipfel, die während des Großen Bruchs entstanden, bildet die Region ein historisches Grenzland, in dem Nachtelfen und Tauren seit Generationen koexistieren. Die hohen, heiligen Gipfel sind immer noch üppig mit Nadelbäumen bewachsen, während die tiefer gelegenen Täler trocken, felsig und durch die Industrie schwer gezeichnet sind.",al={"gebiet steinkrallengebirge","was ist steinkrallengebirge","über das steinkrallengebirge"}},["4e995438"]={q="Ist das Steinkrallengebirge gefährlich?",a="Ja, Reisende sind sowohl natürlichen Gefahren als auch erbitterten Feinden ausgesetzt. Heftige Stürme und plötzlicher Regen können die hohen Sandsteinklippen so glatt machen, dass Menschen in den Tod stürzen. Jenseits des Wetters wimmelt es in den Bergen von aggressiven Blutwutharpien, räuberischen Wyvern, Spinnen, Kobolden und aufgebrachten Elementaren. Zudem machen die rücksichtslosen Maschinen und bewaffneten Vollstrecker der Venture Company umkämpfte Täler wie die Scherwindklippe außergewöhnlich gefährlich.",al={"gefahr im steinkrallengebirge","ist das steinkrallengebirge sicher","gefahren des steinkrallengebirges"}},["9d849e11"]={q="Wer lebt im Steinkrallengebirge?",a="Die Region beherbergt eher verstreute Fraktionen als eine einzelne herrschende Macht. Die Nachtelfen halten den Steinkrallengipfel und bewachen heilige Stätten auf den Höhen, während die Horde Siedlungen am Sonnenfels und das Trodorf Malaka'jin unterhält. Einheimische Blutwutharpien nisten in den Klippen, feindselige Grimtotemtauren besetzen nahegelegene Posten und die Venture Company der Goblins besetzt abgeholzte Landstriche um die Scherwindklippe.",al={"wer lebt im steinkrallengebirge","fraktionen im steinkrallengebirge","bewohner des steinkrallengebirges"}},a4f73e64={q="Warum betreibt die Venture Company Holzwirtschaft in der Scherwindklippe?",a="Die Venture Company ist ein rücksichtsloser Handelskonzern, der durch unbegrenzten Ressourcenabbau Profit sucht. In der Scherwindklippe roden sie mithilfe schwerer Maschinen wie dem Super Reaper 6000 alte Wälder und sprengen die Erde nach wertvollem Erz auf. Ihre Missachtung der Natur erfüllt die Luft mit Ruß und vergiftet lokale Gewässer mit Schlamm und Öl, was ihnen den wütenden Widerstand sowohl der örtlichen Druiden als auch der Horde einbringt.",al={"abholzung durch venture company","warum fällen goblins bäume","holzfällerei venture company steinkrallengebirge"}},["66935983"]={q="Wer leitet die Venture Company in der Scherwindklippe?",a="Die örtlichen Abholzungs- und Minenarbeiten in der Scherwindklippe werden von einem aussätzigen Gnom namens Gerenzo Pfeifzang geleitet. Gerenzo überwacht die Rodungen von einer Plattform hoch über dem Felskesselsee aus und setzt sein technisches Fachwissen ein, um die Zerstörung zu maximieren. Seine schurkischen Operationen haben sogar den Zorn rivalisierender Goblintüftler der Tüftlergewerkschaft auf sich gezogen, die versuchen, ihn auszuschalten.",al={"wer leitet die scherwindklippe","gerenzo wrenchwhistle","anführer der venture company im steinkrallengebirge"}},ff0da62d={q="Wer sind die Blutwutharpien?",a="Die Blutwutharpien sind ein bösartiger Stamm von Vogelmenschen, die im Steinkrallengebirge heimisch sind. Historisch gesehen war dieses Gebirge ihr angestammtes Kernland, bevor sie sich in das Brachland und darüber hinaus ausbreiteten. Sie verteidigen ihr Territorium aggressiv gegen Eindringlinge, fangen lokale Bestien und geraten gewaltsam mit sowohl Taurenpilgern als auch eindringenden Goblinmaschinen an Orten wie dem verbrannten Tal aneinander.",al={"blutwutharpien","harpien im steinkrallengebirge","wer sind die harpien hier"}},["66599fe7"]={q="Was ist der Sonnenfels?",a="Der Sonnenfels ist eine friedliche Siedlung der Horde, eingebettet in ein abgelegenes Bergtal südlich des Mirkfallonsees. Er dient als primäre Basis für Tauren und Orcs in der Region und beherbergt Schamanen und Druiden, die sich der Wiederherstellung des Landes von der Verschmutzung durch die Venture Company und der Bekämpfung der Bedrohungen widmen, die in die heiligen Berge eindringen.",al={"hintergrund zum sonnenfels","was ist der sonnenfels","tauren am sonnenfels"}},["5a5a6e9c"]={q="Warum haben sich die Tauren am Sonnenfels niedergelassen?",a="Seit Generationen verehren die Tauren dieses Tal als einen Ort mit einer tiefen Verbindung zur Geisterwelt. Alte Legenden besagen, dass der Sonnengott An'she den Gipfel küsste, auf dem sich die Zuflucht befindet. Die Tauren unternahmen hier lange Zeit heilige Pilgerreisen, um mit Geistern in Kontakt zu treten und große rituelle Freudenfeuer zu entzünden, um die schattigen Berge zu erhellen.",al={"warum siedelten tauren am sonnenfels","geschichte des sonnenfelses","an'she sonnenfels"}},["51d42c77"]={q="Was ist die Scherwindklippe?",a="Die Scherwindklippe war einst ein üppiger Urwald, wurde aber durch industrielle Ausbeutung verwüstet. Die Venture Company rodete das Tal zu einer kargen Ausdehnung aus Baumstümpfen, Erde und rauchenden Maschinen. Zwischen der Entwaldung durch die Venture Company, dem fauligen Abfluss im Felskesselsee und Kobolden, die die örtliche Mine befallen, steht sie als ruiniertes Denkmal ungezügelter Gier.",al={"über die scherwindklippe","gebiet scherwindklippe","hintergrund zur scherwindklippe"}},d850bc0a={q="Was befindet sich in der Scherwindmine?",a="Die Scherwindmine, die sich in den südöstlichen Klippen der Scherwindklippe befindet, ist von aggressiven Scherwindkobolden überrannt. Die Kobolde, die von den regulären Bergleuten vertrieben wurden oder von ihnen verlassen wurden, graben nun wütend nach Adern von Rauchigen Eisenerzbarren und greifen jeden heftig an, der versucht, in ihre unterirdischen Grabungen einzudringen.",al={"kobolde der scherwindmine","was gibt es in der scherwindmine","rauchiges eisenerz scherwindmine"}},d3863c46={q="Was ist der Krallenbau auf dem Steinkrallengipfel?",a="Der Krallenbau ist ein alter Nachtelfen-Barrow-Bau, der in die Höhen des Steinkrallengipfels gehauen wurde. Er wird von Cenariondruiden unterhalten, die mit den Geistern der Natur und dem Smaragdgrünen Traum kommunizieren. Tief im Inneren haben Druiden traditionell in heiliger Kontemplation geschlafen, bewacht von Dryaden, Hütern und den magischen Schutzzaubern des Gipfels.",al={"krallenbau","der bau am steinkrallengipfel","barrow-bau steinkrallengebirge"}},a547ffd6={q="Verbindet das Eschental das Steinkrallengebirge?",a="Ja. Der raue Steinkrallenpfad verbindet das südwestliche Eschental direkt mit dem nordöstlichen Steinkrallengebirge durch einen höhlenartigen Gebirgspass. Reisende und Abenteurer gelangen häufig zwischen den unberührten, umkämpften Wäldern des Eschentals und den kargen Höhen des Steinkrallengebirges, während sie Bedrohungen durch die Venture Company oder die anhaltenden Fraktionskonflikte verfolgen.",al={"wie verbindet das eschental das steinkrallengebirge","steinkrallenpfad eschental","eschental grenze steinkrallengebirge"}},a5c2784c={q="Wie bin ich im Steinkrallengebirge gelandet?",a="Die meisten Reisenden erreichen diese zerklüfteten Höhen über den Steinkrallenpfad, einen alten Gebirgstunnel, der in das südwestliche Eschental gehauen wurde. Andere Wanderer klettern die rauen Pfade hinauf, die westlich aus dem Brachland führen, und steigen die windgepeitschten Pässe hinauf in die felsigen Klippen. Ob von Nachtelfenkommandanten in Astranaar nach Süden geschickt oder westwärts über die verbrannte Grenze vom Wegekreuz aus entsandt, die hohen Schluchten und heulenden Ill Winds begrüßen jeden, der die beschwerliche Reise in das Gebirge unternimmt.",al={"wie bin ich hierher gekommen","wie komme ich ins steinkrallengebirge","ankunft im steinkrallengebirge"}},["4abc7ef6"]={q="Was soll ich im Steinkrallengebirge tun?",a="Ihr seid hier, um den wachsenden Bedrohungen entgegenzutreten, die diese heiligen Höhen entweihen. An der Scherwindklippe reißen die rücksichtslosen Goblins der Venture Company alte Wälder nieder und verschmutzen die Flüsse mit Maschinen, was den Zorn beider Fraktionen auf sich zieht. Unterdessen stiftet der Grimtotemstamm Unruhe entlang der östlichen Grenze, während bösartige Harpien und wütende Feuerelementare das versengte Becken des verbrannten Tals befallen. Ihr müsst Eure Verbündeten dabei unterstützen, diese Umweltverschmutzer und Monster zurückzudrängen, um das Land zu schützen.",al={"was soll ich hier tun","warum bin ich hier","was ist meine mission im steinkrallengebirge"}}},fp="20,167,27.462.0,22.461.0,17.474.0,41.202.0,42.194.0,52.224.0,42.161.0,54.229.0,36.181.0"}
P.entries["zone:stormwind"] = {n="Sturmwind",s="Das weiß ummauerte Sturmwind ist der größte Zufluchtsort der Menschen und das Herz der Allianz. Doch sein König ist verschollen. Die Krone ruht nun auf dem Haupt eines zehnjährigen Jungen.",h="Das weiß ummauerte Sturmwind ist der größte Zufluchtsort der Menschen und das Herz der Allianz.",kw={"anduin","bolvar","kathedrale","tiefenbahn","prestor","steinmetze","sturmwind","vancleef","wrynn"},ang={["class:Paladin"]="Als Paladin findet Ihr die Kathedrale des Lichts, das wichtigste Heiligtum Eures Glaubens im Süden. Dort werden Ritter der Silbernen Hand ausgebildet und die Gerechtigkeit hochgehalten.",["class:Rogue"]="Als Schurke findet Ihr das Hauptquartier von SI:7 unter den steinernen Straßen der Altstadt. Von dort aus leitet die Organisation das wichtigste Geheimdienst- und Spionagenetzwerk der Allianz.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr in Sturmwind auf Seemacht, spirituellen Halt und wichtige diplomatische Führung zählen. Es ist die bevölkerungsreichste Metropole der Großen Allianz.",["race:Dwarf"]="Als Zwerg könnt Ihr mit der Tiefenbahn zu Euren Verwandten im Zwergendistrikt reisen. Sie pflegen enge Handels- und Militärbeziehungen zum Menschenreich.",["race:Human"]="Als Mensch ist Sturmwind der letzte große Sitz souveräner Macht Eures Volkes, nachdem Lordaeron, Alterac und Dalaran im Norden gefallen sind."},sec={{t="Aus der Asche auferstanden",b="Sturmwind ist alt. Vor mehr als tausend Jahren gründeten die Nachfahren der Arathi die Stadt. Viele Generationen lang blühte sie als Reich, das niemandes Hilfe brauchte. Dann kam die Horde durch das Dunkle Portal. Der südliche Kontinent wurde verwüstet, und im Ersten Krieg wurde die Stadt dem Erdboden gleichgemacht.\n\nDie Überlebenden folgten Sir Anduin Lothar nach Norden, über das große Meer nach Lordaeron. Als die Horde im Zweiten Krieg besiegt wurde, bezahlten König Terenas Menethil II und die Allianz für den Wiederaufbau Sturmwinds. Die Steinmetzgilde errichtete die Stadt mit glänzendem weißen Stein neu, mit Kanälen, die durch ihre Viertel fließen."},{t="Ein gespaltener Hof",b="Doch der weiße Stein verbirgt ein zerrüttetes Haus. Das Haus der Edlen stritt mit der Steinmetzgilde über die Löhne, und der Streit stürzte das Königreich in lähmende Schulden. Die Arbeiter der Gilde erhoben sich zum Aufstand. Sie wurden ausgerechnet aus der Stadt vertrieben, die sie erbaut hatten.\n\nDann verschwand König Varian Wrynn auf dem Weg zu einem Gipfeltreffen. Damit sich keine Panik ausbreitete, ging die Krone an seinen Sohn, Prinz Anduin Wrynn. Er ist zehn Jahre alt. Hochlord Bolvar Fordragon regiert nun als Regent und Befehlshaber des Heeres. An seiner Seite steht die königliche Beraterin Lady Katrana Prestor."},{t="Herz der Großen Allianz",b="Seit Lordaeron von der Geißel überrannt wurde, richten die Menschen ihren Blick mehr als auf jede andere Stadt auf Sturmwind. Die Gläubigen versammeln sich in der Kathedrale des Lichts. Und im Tal der Helden ehren hohe Statuen die Söhne Lothars. Sie zogen durch das Dunkle Portal und wurden nie wieder gesehen."},{t="Wohin die Steinmetze gingen",b="Die Steinmetze versammelten sich unter ihrem Gildenmeister Edwin van Cleef erneut in Westfall. Dort wurden sie zur Bruderschaft der Defias, rot maskierten Banditen, die nun das Ackerland des Königreichs strangulieren. Die Erbauer von Sturmwinds weißen Mauern haben geschworen, das Haus der Edlen für jeden Stein bezahlen zu lassen."},{t="Ein Freund am Hof",b="Die Bruderschaft der Defias fand Hilfe in Burg Sturmwind. Lord Gregor Lescovar vom Haus der Edlen verhandelte heimlich mit der Bruderschaft und gab ihr die Pläne des Königreichs weiter. Dabei saß er unter den Lords, die die Steinmetze betrogen hatten."},{t="Schatten in der Burg",b="Lady Katrana Prestor hat heimlich die Entscheidungen des Hauses der Edlen gelenkt. Sie schürte dessen Konflikt mit den Steinmetzen und ignorierte Bitten um militärische Hilfe aus Siedlungen wie Westfall und dem Rotkammgebirge. Außerdem flüsterte sie Hochlord Bolvar Gift ins Ohr und hielt Sturmwinds Legionen untätig und gespalten, während Unruhen jenseits der Stadtmauern den Thron bedrohen."}},faq={{q="Wer regiert gerade über Sturmwind?",a="Der zehnjährige Prinz Anduin Wrynn trägt Sturmwinds Krone, während Hochlord Bolvar Fordragon als Regent regiert und das Heer befehligt. Bolvar verlässt sich auf den Rat der königlichen Beraterin Lady Katrana Prestor, während König Varian Wrynn weiterhin vermisst wird.",al={"aktueller könig","wer ist der könig","wer führt sturmwind","könig von sturmwind"}},{q="Was ist König Varian Wrynn zugestoßen?",a="König Varian verschwand unter verdächtigen Umständen, als er zu einem diplomatischen Gipfeltreffen in Theramore segelte. Sein Verschwinden wurde geheim gehalten, um die Stabilität zu wahren, doch Gerüchte verbreiteten sich in den Straßen und auf dem Land.",al={"wo ist varian","vermisster könig","varian verschwunden","varian wrynn vermisst"}},{q="Warum wurde die Stadt wiederaufgebaut, und von wem?",a="Die Orcische Horde brannte die ursprüngliche Stadt im Ersten Krieg nieder. Nach dem Zweiten Krieg finanzierte die Allianz von Lordaeron den Wiederaufbau, und der Meisterhandwerker Edwin van Cleef führte die Steinmetzgilde an, um die Hauptstadt aus weißem Stein neu zu errichten.",al={"wer hat sturmwind wiederaufgebaut","steinmetzgilde","neues sturmwind","wiederaufbau der stadt"}},{q="Warum rebellierten die Steinmetze gegen die Krone?",a="Das Haus der Edlen machte hohe Schulden, als es Sturmwinds Heer ausbaute, weigerte sich dann aber, der Steinmetzgilde die versprochenen Löhne zu zahlen. Als Edwin van Cleef die Bezahlung forderte, lösten die Edlen die Gilde auf. Die Arbeiter randalierten und wurden aus der Stadt vertrieben.",al={"ursprung der defias","warum sind die defias wütend","aufstand der steinmetze"}},{q="Wen stellen die riesigen Statuen im Tal der Helden dar?",a="Das Tal der Helden ehrt die Söhne Lothars: General Turalyon, Waldläuferhauptmann Alleria Windläufer, Erzmagier Khadgar, Kurdran Wildhammer und Danath Trollbann. Die Statuen erinnern an jene Helden, die durch das Dunkle Portal nach Draenor gingen, um den Riss zu versiegeln und Azeroth zu beschützen.",al={"statuen am stadteingang","statuen im tal der helden","statuen der söhne lothars"}},{q="Wie ist Sturmwind mit Eisenschmiede verbunden?",a="Die Tiefenbahn, eine unterirdische Eisenbahn, verbindet Sturmwind mit Eisenschmiede. Hochschrauber Gelbin Mekkadrill ließ sie auf Wunsch von König Magni Bronzebart erbauen, damit die Hauptstädte rasch Handel treiben und sich im Krieg gegenseitig Verstärkung schicken können.",al={"die tiefenbahn","zug nach eisenschmiede","wie kommt man nach eisenschmiede"}},{q="Warum schickt Sturmwind keine Truppen, um Westfall und dem Rotkammgebirge zu helfen?",a="Der königliche Hof erklärt unter dem Einfluss von Lady Katrana Prestor, Sturmwind könne keine Truppen von seinen Mauern und den nahen Grenzen abziehen. Die Finanzen des Königreichs sind angespannt, und politische Machtkämpfe haben das Haus der Edlen gelähmt. So sind die Städte der Region auf ihre örtlichen Milizen angewiesen.",al={"sturmwinds fehlendes heer","warum keine hilfe für westfall","verstärkung verweigert"}}},fx={["9beefbfb"]={q="Was ist Sturmwind?",a="Sturmwind ist die Hauptstadt des Menschenkönigreichs Sturmwind und die größte Bastion der Menschheit, die in Azeroth noch steht. Erbaut nördlich des Waldes von Elwynn entlang der Küste, dient sie als pulsierendes Herz, primärer Hafen und kulturelles Zentrum der Großen Allianz. Wiederaufgebaut aus der Asche des Ersten Krieges, bieten ihre befestigten Steinmauern Handwerkern, Gelehrten, Soldaten und Flüchtlingen Schutz, die die Stadt als Symbol menschlicher Ausdauer betrachten.",al={"über sturmwind","hauptstadt sturmwind","was ist sturmwind"}},edb1c1aa={q="Was ist in der Vergangenheit mit Sturmwind passiert?",a="Ursprünglich vor über tausend Jahren von Nachkommen der Arathor-Blutlinie gegründet, florierte das Königreich jahrhundertelang durch Konflikte mit Gnollen und Dschungeltrollen. Während des Ersten Krieges belagerte jedoch die Orcische Horde die Hauptstadt. Nach der tragischen Ermordung von König Llane Wrynn wurde die Stadt durchbrochen, geplündert und bis auf die Grundmauern niedergebrannt. Sir Anduin Lothar führte die überlebenden Flüchtlinge nach Norden über das Meer nach Lordaeron und kehrte erst nach dem Zweiten Krieg zurück, um ihre Heimat zurückzuerobern und wiederaufzubauen.",al={"geschichte von sturmwind","zerstörung von sturmwind","sturmwind erster krieg"}},d0a4b7c8={q="Ist Sturmwind gefährlich?",a="Hinter ihren kolossalen Toren und der wachsamen Stadtwache ist Sturmwind eines der am stärksten befestigten Refugien der Welt. Dennoch lauern unsichtbare Gefahren im Inneren. Das nahe gelegene Gefängnis war Schauplatz gewaltsamer Aufstände, Kultisten und Diebe schleichen durch die schattigen Canals, und politische Unruhen, geschürt von der Bruderschaft der Defias, lassen das Haus der Adligen nervös werden. Während offener Krieg selten die Mauern durchbricht, flüstern Korruption, Verrat und verborgene Verschwörungen durch die Burg und die Gassen gleichermaßen.",al={"ist sturmwind sicher","gefahr in sturmwind","bedrohungen für sturmwind"}},["163d181d"]={q="Wer ist die Bruderschaft der Defias?",a="Die Bruderschaft der Defias ist eine rücksichtslose Gilde von Gesetzlosen, Briganten, Dieben und Piraten, die die Stabilität des Königreichs offen bedrohen. Sie sind an ihren charakteristischen roten Bandanas zu erkennen, die das Blut symbolisieren sollen, das für ihre Sache vergossen wurde. Obwohl sie stark von Westfall, dem Rotkammgebirge und den Todesminen aus operieren, reicht ihr Einfluss direkt bis nach Sturmwind, wo ihre Spione und Sympathisanten die Autorität der Krone untergraben und Zwietracht unter der Arbeiterklasse säen.",al={"bruderschaft der defias","wer ist die defias","defias-bande"}},b1d432aa={q="Was ist die Kathedrale des Lichts?",a="Die Kathedrale des Lichts, die über dem Kathedralenplatz thront, ist das herausragende geistige Zentrum für die Menschheit und die Große Allianz. Nach dem Zweiten Krieg unter Erzbischof Alonsus Faol und dem damaligen Bischof Benedictus wiederaufgebaut, dient sie als Sitz der Kirche des Heiligen Lichts und als Hauptquartier des Ordens der Silbernen Hand. Paladine und Priester reisen aus allen Teilen der Reiche an, um zu trainieren, Weisheit zu suchen und in ihren großen, friedlichen Hallen zu meditieren.",al={"kathedrale des lichts","kathedrale von sturmwind","kirche des lichts sturmwind"}},["3414b788"]={q="Wie bin ich in Sturmwind gelandet?",a="Wenn Ihr Eure Reise in Nordhain begonnen und Euch durch den Wald von Elwynn gearbeitet habt, führte Euch die Hauptstraße direkt durch das Tal der Helden und in die befestigten Tore der Hauptstadt. Wenn Ihr aus Dun Morogh oder Eisenschmiede stammt, seid Ihr wahrscheinlich mit der Tiefenbahn gefahren, dem Wunderwerk gnomischer Ingenieurskunst, das die Zwergenfestung direkt mit dem Zwergendistrikt unter den Bergen verbindet. Reisende aus anderen Teilen von Azeroth erreichen die Tore von Sturmwind nach langen Märschen durch die südlichen Königreiche, auf der Suche nach dem letzten großen Bollwerk der Menschheit.",al={"wie bin ich hierhergekommen","wie komme ich nach sturmwind","wie gelange ich nach sturmwind"}},["68c43aeb"]={q="Was soll ich in Sturmwind tun?",a="Sturmwind ist das schlagende Herz der Allianz und ein Zufluchtsort, um sich auszuruhen, zu trainieren und sich zu versorgen. Unter den glänzend weißen Stadtmauern ist das Königreich jedoch tief gespalten. König Varian Wrynn ist unter mysteriösen Umständen verschwunden, was den jungen König Anduin und Hochlord Bolvar Fordragon in der Festung mit politischer Lähmung kämpfen lässt. Währenddessen rufen die umliegenden Grenzgebiete in Westfall und dem Rotkammgebirge nach Hilfe gegen grassierendes Banditentum, und die The Defias Brotherhood schmiedet Pläne aus den Schatten heraus. Ihr seid hier, um Euer Handwerk zu verfeinern, Euren Fraktionsführern Bericht zu erstatten und einem bedrängten Reich Euer Schwert zu leihen.",al={"warum bin ich hier","was soll ich hier tun","was ist meine aufgabe in sturmwind"}}},fp="14,142,19.590.0,15.532.0,27.258.0,21.287.1,17.236.1,19.351.2,30.238.0,35.216.0,38.251.1,48.261.1,50.272.0,40.223.0,65.267.0"}
P.entries["zone:stranglethorn"] = {n="Schlingendorntal",s="Trolle, Goblins, Piraten und Soldaten ringen um das Schlingendorntal. Südlich des Dämmerwalds ist das alte Kernland der Gurubashi zu einem Labyrinth aus Ruinen, wilden Tieren und rivalisierenden Lagern geworden.",h="Trolle, Goblins, Piraten und Soldaten ringen um das Schlingendorntal.",kw={"blutsegel","beutebucht","grom'gol","gurubashi","kurzen","nesingwary","revilgaz","schlingendorntal","venture company","zul'gurub"},ang={["class:Hunter"]="Als Jäger könnt Ihr den berühmten Großwildjäger Hemet Nesingwary am nördlichen Flussufer treffen. Er fordert Scharfschützen auf, die gefährlichsten Raptoren, Panther und Krokilisken des Dschungels aufzuspüren.",["faction:Alliance"]="Als Allianzangehörige erbt Ihr Sturmwinds kostspielige Bemühungen, den Dschungel zu erobern und zu befrieden. Nun verteidigen bedrängte Meuterer im Rebellenlager die Interessen des Königreichs.",["faction:Horde"]="Als Hordeangehörige könnt Ihr Euch auf das Basislager Grom'gol als strategische Festung auf dem südlichen Kontinent verlassen, das Zeppeline aus Durotar und der Unterstadt versorgen.",["profession:Herbalism"]="Als Kräuterkundige könnt Ihr an den Flussufern und Küsten des feuchten Blätterdachs nach Wildstahlblume, Fadeleaf, Golddorn und Lila Lotus suchen.",["race:Troll"]="Als Troll liegt Eure angestammte Heimat in der Wiege der Dschungeltrolle, dem Schlingendorntal. Auf die Verehrung Hakkars des Seelenschinders durch das Gurubashi-Imperium folgte ein Bürgerkrieg, der Stämme wie die Dunkelspeer über die Meere trieb."},sec={{t="Ruinen eines Imperiums",b="Zul'Gurub herrschte einst als Hauptstadt des Gurubashi-Imperiums über das Tal. Diese Herrschaft endete, als radikale Priester Hakkar den Seelenschinder beschworen und ein Bürgerkrieg die Region zerriss. Die Zandalari schlugen den Aufstand des Blutgottes nieder, doch das Imperium erholte sich nie davon. Nun kämpfen Nachfolgefraktionen im ganzen Dschungel. Die Bloodscalp halten den Nordwesten, während die Schädelspalter den Osten besetzen. Beide Stämme metzeln Außenstehende nieder, während sie ihre angestammte Heimat zurückfordern."},{t="Piraten und Profitjäger",b="Beutebucht prägt die Südspitze des Tals mit Handel und Seeverkehr. Das Steamwheedle Cartel gründete den Hafen, und die Blackwater Raiders führen ihn unter Baron Revilgaz. Blutsegelbukaniere, die entlang der Küste ankern, bedrohen den Hafen ständig. Weiter im Landesinneren holzt die Venture Company Bäume ab und baut in den Hügeln seltene singende Kristalle ab."},{t="Umkämpfte Wildnis",b="Rivalisierende Mächte treffen im gefährlichen Grenzland des Tals aufeinander. Die Horde hält das Basislager Grom'gol an der Westküste, und Goblin-Zeppeline verbinden es mit Durotar und Tirisfal. Allianz-Loyalisten im Rebellenlager suchen den abtrünnigen Colonel Kurzen. Im dichten Dschungel führt der berühmte Jäger Hemet Nesingwary Großwildexpeditionen an. Wanderer, die sich von seinen Jagden anziehen lassen, begegnen lauernden Panthern, riesigen Affen und feindlichen Soldaten."},{t="Der Wahnsinn im Dschungel",b="Colonel Kurzen führte eine Expedition aus Sturmwind in den nördlichen Dschungel, verfiel dann dem Wahnsinn und errichtete eine tyrannische Söldnerfestung. Das Gedankenauge, geführt von Mai'Zoth, einem Ogerzauberer vom nahe gelegenen Ogerhügel der Mosh'Ogg, verfing Kurzens Geist in Zauberei. Die Expedition verfiel dem Wahnsinn, und Kurzens ehemalige Männer spalteten sich ab und gründeten das Rebellenlager."}},faq={{q="Wer kontrolliert das Schlingendorntal?",a="Keine einzelne Macht kontrolliert das Schlingendorntal. Trolle der Bloodscalp und Schädelspalter, Kurzens Truppenlager, die Venture Company sowie militärische Stützpunkte der Horde und der Allianz halten rivalisierende Gebiete. Beutebucht ist die größte Siedlung und wird von Baron Revilgaz und den Blackwater Raiders regiert.",al={"wem gehört das schlingendorntal","wer herrscht über das schlingendorntal","fraktionen im schlingendorntal"}},{q="Was ist Beutebucht?",a="Beutebucht ist eine Hafenstadt auf den südlichen Klippen des Kap des Schlingendorntals. Einst war sie die menschliche Siedlung Schwarzmeerbucht, wurde von Trollen erobert und später vom Steamwheedle Cartel gesichert. Baron Revilgaz und Flottenmeister Seehorn führen sie als neutralen Handelshafen, der Reisende über das große Meer mit Ratschet verbindet.",al={"was ist beutebucht","hafen von beutebucht","wer führt beutebucht"}},{q="Warum wurde Colonel Kurzen abtrünnig?",a="Colonel Kurzen wurde abtrünnig, nachdem Mai'Zoth, ein Ogerzauberer, der das Gedankenauge führte, seinen Geist verstrickt hatte. Kurzen hatte eine Expedition aus Sturmwind in den Dschungel geführt, wurde jedoch unberechenbar und despotisch. Lieutenant Doren und loyale Soldaten spalteten sich ab, gründeten das Rebellenlager und stellten sich ihm entgegen.",al={"warum ist kurzen böse","was geschah mit kurzen","kurzens hintergrundgeschichte"}},{q="Was ist Zul'Gurub?",a="Zul'Gurub ist die zerstörte Hauptstadt des Gurubashi-Imperiums im Nordosten des Schlingendorntals. Vor fünfzehn Jahrhunderten beschworen radikale Priester dort Hakkar den Seelenschinder und lösten damit den Bürgerkrieg aus, der das Imperium beendete. Ranken und Ruinen bedecken die verlassene Stadt, doch dunkle Rituale bedrohen noch immer ihre Hallen.",al={"was ist zul'gurub","geschichte von zul'gurub","hauptstadt der gurubashi"}},{q="Was war der Stein der Gezeiten?",a="Der Stein der Gezeiten ist ein legendäres Relikt aus der alten Geschichte der Gurubashi, das ein Trollkrieger an der Küste fand. Er verlieh seinem Träger die Kontrolle über Wasser und Elementarbeschwörungen wie ein mächtiger Magier und brachte ihm so den Namen Tidebearer ein. Sein Fluch zog jeden Träger langsam aus der körperlichen Welt, bis er ins Meer ging und verschwand.",al={"stein der gezeiten","legende des tidebearers","gurubashi-wasserstein"}},{q="Wie reise ich ins Schlingendorntal?",a="Ihr könnt von Dämmerwald aus nach Süden über die Flussgrenze ins nördliche Schlingendorntal laufen. Zeppeline der Horde verbinden das Basislager Grom'gol mit Durotar und Tirisfal. Von Kalimdor aus nehmt Ihr das Handelsschiff, das zwischen Ratschet im Brachland und Beutebucht verkehrt.",al={"wie kommt man ins schlingendorntal","reise ins schlingendorntal","reise zum schlingendorntal"}}},fp="18,166,18.455.0,22.346.0,22.414.0,25.340.1,32.270.0,18.322.0,32.268.1,18.294.0,32.328.0,38.256.0"}
P.entries["zone:swampofsorrows"] = {n="Sümpfe des Elends",s="Grüne Drachenbrut bewacht den versunkenen Tempel von Atal'Hakkar unter dem Tränenteich. Zwischen dem Gebirgspass der Totenwinde und den Verwüsteten Landen liegt dieses salzverkrustete Moor mit gefährlichen Wildtieren und der Garnison der Horde in Steinard. Die Allianz hat hier keinen sicheren Zufluchtsort.",h="Grüne Drachenbrut bewacht den versunkenen Tempel von Atal'Hakkar unter dem Tränenteich.",kw={"schwarzer morast","zerschlagene","der sichere hafen","verirrte","tränenteich","sorgendunkel","steinard","versunkener tempel","sümpfe des elends","der tempel von atal'hakkar"},ang={["faction:Alliance"]="Ohne einen Außenposten, hinter dem Ihr Euch sammeln könnt, steht Euch eine einsame und feindselige Reise durch den Sumpf bevor. Bereitet Euch sorgfältig in Dunkelhain oder Burg Nethergarde vor, bevor Ihr aufbrecht.",["faction:Horde"]="Steinard ist Euer wichtiger vorgeschobener Stützpunkt auf dem südlichen Kontinent. Wyvernrouten verbinden die Siedlung direkt mit Kargath, Flammenkamm, Basislager Grom'gol, Beutebucht und Rog'mar in den Flusslanden.",["profession:Blacksmithing"]="An den Gebirgskämmen am nördlichen und südlichen Rand des Sumpfs könnt Ihr Eisen, Gold, Mithril und Echtsilber sammeln.",["profession:Herbalism"]="Das Moor ist eine der wenigen ergiebigen Quellen für Blindkraut in Azeroth. Außerdem findet Ihr dort reichlich Lebenswurz, Fadeblatt und Würgetang.",["race:Troll"]="Die versunkenen Ruinen von Atal'Hakkar erinnern an die dunkle Blutmagie, die das Gurubashi-Reich spaltete und den Zorn der Drachenaspekte auf sich zog."},sec={{t="Eine versunkene Geschichte",b="Die Sümpfe des Elends waren einst die nördliche Hälfte des gewaltigen Schwarzen Morasts. Nach dem Zerfall des Gurubashi-Reiches flohen fanatische Atal'ai-Trolle in das Moor und errichteten den Tempel von Atal'Hakkar. Sie wollten Hakkar den Seelenschinder beschwören, ihren blutdürstigen Loa. Der Aspekt Ysera spürte die Gefahr und versenkte die verfluchte Pyramide unter dem Tränenteich. Wächter des grünen Drachenschwarms unter Eranikus wurden zu ihrer Bewachung abgestellt.\n\nSpäter versengte der Kataklysmus des Dunklen Portals den südlichen Morast zu den Verwüsteten Landen. Das nördliche Moor erhielt seinen klagenden Namen."},{t="Außenposten und gebrochene Verbannte",b="Steinard ist der wichtigste Stützpunkt sesshafter Bewohner im Sumpf. Während des Ersten Krieges neben Rockard und Kyross gegründet, die heute beide in Ruinen liegen, wurde es unter Thrall wiederaufgebaut und zum südlichsten Aufmarschgebiet der Horde in den Östlichen Königreichen.\n\nJenseits seiner Palisaden durchqueren seltsame Wanderer das Moor. Auf Azeroth gestrandete Draenei wurden von Heimweh und Wahnsinn befallen und zu wilden Verirrten. Im Sicheren Hafen ist eine kleine Gemeinschaft klar denkender Zerschlagener Verbannter geblieben. Sie ist vorsichtig, aber bereit, friedlich mit Reisenden zu handeln."},{t="Das versinkende Moor",b="Raubtiere machen jede Durchquerung der Sümpfe des Elends gefährlich. Tiefe Moore verbergen hervorschnellende Krokilisken, giftige Spinnen, umherstreifende Sumpfjaguare und mit Sumpfschutt bedeckte Moorbestien. Bösartige Murlocs kriechen durch Küstenhöhlen und entlang des Nebelschilfstrands.\n\nSalzhaltige Gezeiten dringen landeinwärts und überziehen verrottete Baumstämme mit Salzkrusten. Weiter östlich bewacht aggressive Elite-Drachenbrut im Sorgendunkel die Zugänge zum Versunkenen Tempel. Sie greift jeden an, der sich ihrer Wacht nähert."}},faq={{q="Wie erreiche ich die Sümpfe des Elends?",a="Die übliche Landroute führt von Dunkelhain im Dämmerwald nach Osten, durch den Spukenden Gebirgspass der Totenwinde und hinab in den Sumpf. Aus dem Süden folgt Ihr der Hauptstraße von den Verwüsteten Landen nach Norden.",al={"wie komme ich zu den sümpfen des elends","straße durch die sümpfe des elends","nach steinard gelangen"}},{q="Warum liegt der Tempel von Atal'Hakkar unter Wasser?",a="Vor Jahrhunderten versuchte die Priesterschaft der Atal'ai, Hakkar den Seelenschinder nach Azeroth zu beschwören. Ysera, Aspekt des grünen Drachenschwarms, entdeckte ihre dämonischen Blutrituale und versenkte den Tempel im Moor, um eine Katastrophe abzuwenden. Grüne Drachenbrut bewacht seine versunkenen Hallen.",al={"warum ist der versunkene tempel versunken","wer versenkte den tempel","geschichte des versunkenen tempels"}},{q="Was ist Steinard?",a="Steinard war eine der ersten Siedlungen der orcischen Horde, nachdem sie während des Ersten Krieges das Dunkle Portal durchquert hatte. Kämpfe verwüsteten den Außenposten, doch Thrall ließ ihn vor Kurzem zurückerobern und wiederaufbauen, um die Logistik der Horde nahe den Verwüsteten Landen zu sichern.",al={"geschichte von steinard","orcischer stützpunkt im sumpf","wer gründete steinard"}},{q="Gibt es hier Siedlungen der Allianz?",a="In den Sümpfen des Elends gibt es keine Siedlungen, Wachen oder Flugrouten der Allianz. Wenn Ihr durch das Moor reist, nutzt Dunkelhain im Westen oder Burg Nethergarde im Süden als Stützpunkt.",al={"allianzstützpunkt in den sümpfen des elends","flugroute der allianz im sumpf","wo ist das lager der allianz"}},{q="Wer sind die seltsamen mutierten Humanoiden im Sumpf?",a="Diese seltsamen Humanoiden sind Draenei, die nach dem Einsturz des Dunklen Portals auf Azeroth gestrandet sind. Von ihrer Heimat abgeschnitten, verfielen die meisten der Verzweiflung und dem Wahnsinn und wurden zu feindseligen Verirrten. Eine kleine Gruppe geistig gesunder Zerschlagener Verbannter fand im Nordwesten Zuflucht im Sicheren Hafen und entschied sich für neutrales Überleben statt sinnloser Wut.",al={"wer sind die verirrten","was ist der sichere hafen","draenei im sumpf"}},{q="Was ist Sorgendunkel?",a="Sorgendunkel ist das dichte Sumpfgebiet östlich des Tränenteichs. Elite-Drachenbrut und Jungtiere des grünen Drachenschwarms patrouillieren dort und halten Sterbliche mit Gewalt fern, um die Geheimnisse des Versunkenen Tempels zu schützen.",al={"drachengebiet in den sümpfen des elends","drachen im sorgendunkel","grüne drachenbrut im sumpf"}}},fp="16,249,17.556.0,26.487.0,16.475.0,36.188.0,44.259.0,16.248.0,40.179.0,51.307.0,19.185.0"}
P.entries["zone:tanaris"] = {n="Tanaris",s="In Tanaris handeln Goblins unter sengender Sonne, während sich Gefahren im Sand regen. Gadgetzan heißt Allianz und Horde willkommen, während Sandfury-Trolle, Silithiden und uralte Mächte die Dünen jenseits der Stadt beherrschen.",h="In Tanaris handeln Goblins unter sengender Sonne, während sich Gefahren im Sand regen.",kw={"die höhlen der zeit","wüste","freibeuter","gadgetzan","nozdormu","sandfury","silithiden","steamwheedle","tanaris","uldum","zul'farrak"},ang={["faction:Alliance"]="Als Reisender der Allianz findet Ihr zwischen den Düstermarschen und Feralas keine größeren Stützpunkte der Allianz. Das neutrale Gadgetzan bietet Euch einen wichtigen Ausgangspunkt für Reisen durch das südliche Kalimdor.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr Gadgetzan als Handelszentrum nutzen, das die Routen vom Freiwindposten und Camp Mojache mit den von Silithiden befallenen Ödlanden im äußersten Süden verbindet.",["profession:Herbalism"]="Die trockene Hitze Tanaris' lässt Feuerblüte auf den wandernden Dünen gedeihen. Schattige Ruinen und feuchte Oasen bergen wertvollen Lila Lotus.",["profession:Mining"]="In den trockenen Klippen und Felsvorsprüngen Tanaris' finden sich Adern von Mithril, Truesilver, Iron und Gold. Vereinzelte Vorkommen von Small Thorium liegen tiefer in der Wüste.",["race:Troll"]="Als Troll zeigen Euch die Sandfury-Trolle von Zul'Farrak uralte Vettern, die in der Abgeschiedenheit der Wüste eine brutale Kultur erschufen."},sec={{t="Ein Meer aus Dünen",b="Tanaris liegt unter sengender Sonne, und Sand bedeckt einen Großteil des Landes. Innerhalb der Mauern von Zul'Farrak bewachen die Sandfury-Trolle ihr abgeschiedenes Zuhause. Hyänen, Basilisken und Skorpide durchstreifen den Wüstenboden. Tunnel ziehen sich unter der heißen Erde entlang."},{t="Goblin-Geschäfte",b="Nahe der Inselheimat der Goblins, Kezan, ist Tanaris zu einem Handelsplatz des Dampfdruckkartells geworden. Von der ummauerten Stadt Gadgetzan bis zu den Docks des Dampfdruckpiers heißen die Goblins Münzen von Allianz und Horde gleichermaßen willkommen. Schläger sorgen für Frieden, doch die Südmeerfreibeuter setzen Schiffen und Ausgrabungsstätten entlang der Küste weiterhin zu."},{t="Uralte Geheimnisse und neue Gefahren",b="Tanaris birgt Mächte, die älter sind als die Reiche der Sterblichen. Im Osten gehören die Höhlen der Zeit Nozdormu und dem bronzenen Drachenschwarm. Ihre Drachen nutzen manchmal die thermischen Aufwinde der Wüste.\n\nWeiter südlich markieren gewaltige Steintore den Titankomplex Uldum. Silithidenschwärme graben sich von Nestern wie der Klaffenden Schlucht und dem Giftigen Unterschlupf aus nach außen."}},faq={{q="Wie reise ich nach Tanaris?",a="Durchquert Tausend Nadeln zu Fuß, um die Schimmernde Ebene zu erreichen. Am südlichen Ende der Salzwüste führt ein Gebirgspass hinab nach Tanaris, und Gadgetzans Mauern sind sofort zu sehen. Schiffe fahren auch vom Hafen von Powderfuse in den Flusslanden zum Dampfdruckpier an der Ostküste.",al={"wie kommt man nach tanaris","reise nach tanaris","eingang nach tanaris"}},{q="Warum ist Gadgetzan beiden Fraktionen gegenüber neutral?",a="Das Dampfdruckkartell herrscht über Gadgetzan und ist dem Profit verpflichtet. Um den Handel zu schützen und Geschäfte anzuziehen, setzen die Goblins Neutralität durch. Ihre Schläger greifen jeden an, der innerhalb der Stadtmauern einen Fraktionskampf beginnt.",al={"warum ist gadgetzan neutral","können horde und allianz nach gadgetzan","neutralität der goblins in gadgetzan"}},{q="Was ist Zul'Farrak?",a="Zul'Farrak ist die ummauerte Wüstenhauptstadt der Sandfury-Trolle. Abgeschieden in der Wüste wurde der Stamm Außenstehenden gegenüber feindselig und bewacht seine heiligen Becken und geheimnisvollen Schreine.",al={"was ist zul'farrak","wer lebt in zul'farrak","stadt der sandtrolle"}},{q="Was sind die Insektenwesen, die überall in der Wüste nisten?",a="Die insektenartigen Bestien sind Silithiden, monströse Gräber, die gewaltige Bauten wie die Klaffende Schlucht und den Giftigen Unterschlupf errichten. Ihr Auftauchen in Tanaris beunruhigt den Leitenden Feldmesser Rutenwünschels und erinnert ihn an die uralten Schrecken des Kriegs der Sandverschiebung.",al={"was sind die käfer in tanaris","insektennester in tanaris","silithiden in tanaris"}},{q="Was liegt hinter den gewaltigen Steintoren im Süden?",a="Die gewaltigen Tore im Tal der Behüter markieren den Eingang zu Uldum, einer Forschungseinrichtung der uralten Titanen. Kolossale steinerne Wächter bewachen den versiegelten Eingang, während Gelehrte und Goblins aus der Ferne zusehen.",al={"riesige tore im südlichen tanaris","tore der ruinen von uldum","titantor in tanaris"}},{q="Wer lebt in den Höhlen der Zeit?",a="Die Höhlen der Zeit sind die angestammte Heimat des bronzenen Drachenschwarms und seines Aspekts Nozdormu. Aus verborgenen, gewundenen Tiefen beobachten die zeitlosen Drachen den Lauf der Geschichte. Manchmal patrouillieren sie am Himmel über den südlichen Dünen.",al={"lore der höhlen der zeit","was ist in den höhlen der zeit","drachen in tanaris"}}},fp="7,203,14.233.0,17.333.0,35.335.0,27.288.0,42.224.0,19.175.0,56.255.0,52.219.0,38.232.0"}
P.entries["zone:teldrassil"] = {n="Teldrassil",s="Vor Kalimdors Nordwestküste erhebt sich Teldrassil, der Weltbaum, in dessen Krone Darnassus liegt. Die Druiden zogen ihn nach dem Dritten Krieg heran. Doch sein Wachstum ist beeinträchtigt.",h="Vor Kalimdors Nordwestküste erhebt sich Teldrassil, der Weltbaum, in dessen Krone Darnassus liegt.",kw={"rat der urahnen","crown of the earth","darnassus","dolanaar","fandral hirschhaupt","rut'theran","laubschattental","teldrassil","weltbaum"},ang={["class:Druid"]="Während Malfurion im Smaragdgrünen Traum gefangen ist, führt Erzdruide Fandral Hirschhaupt hier den Zirkel des Cenarius. Viele Druiden befürchten, dass Teldrassil überstürzt herangezogen wurde.",["faction:Alliance"]="Teldrassil ist die nördlichste Hochburg der Allianz in Kalimdor und ermöglicht den Schiffsverkehr und Handel zwischen Darnassus und den Königreichen auf dem Festland.",["profession:Herbalism"]="Teldrassil hat keine Mineralien oder Erze, doch auf seinem Blätterdach wachsen Friedensblumen, Silberblatt und Erdwurzel im Überfluss.",["race:NightElf"]="Als Nachtelf seht Ihr in Teldrassil den Neuanfang Eures Volkes nach der Verwüstung des Hyjal. Ohne den Segen der Aspekte muss der Baum dringend verteidigt werden."},sec={{t="Ein Blätterdach über dem Meer",b="Weit erstrecken sich Teldrassils Äste, tief unter ihnen liegt das verhüllte Meer. Auf seinen Zweigen finden sich Hügel, uralte Lichtungen und neblige Seen. Morgentau speist seine Flüsse. Am westlichen Rand liegt Darnassus, die Stadt der Kaldorei.\n\nWeit unten, am Fuß des Stammes, liegt Rut'theran. Es ist der Hafen der Insel. Ein Portal voller Magie verbindet den Ort mit der Krone."},{t="Die Weigerung der Aspekte",b="Im Dritten Krieg wurde Nordrassil geopfert. Shan'do Malfurion Sturmgrimm begab sich in den Smaragdgrünen Traum. In seiner Abwesenheit trat Erzdruide Fandral Hirschhaupt vor den Rat der Urahnen. Er bewegte sie dazu, an seiner Stelle einen weiteren Baum heranzuziehen. Denn er hoffte, den Kaldorei das unsterbliche Leben zurückzugeben, das sie verloren hatten.\n\nDoch Nozdormu und die Drachenaspekte hielten dies für ein Werk des Hochmuts. Sie verweigerten ihren Segen. So wuchs Teldrassil ohne Schutz. Mit ihm wuchsen Fehler, die nicht der Natur entsprangen."},{t="Ein schleichendes Leiden",b="Unter Teldrassils Wildtieren hat sich Gewalt ausgebreitet. Friedliche Furbolgstämme sind dem Wahnsinn verfallen, verzerrte Grells vermehren sich in den Grabhügeln, und Satyrn vollziehen dunkle Riten an Orten wie dem Teufelsfels. An den Gestaden der Dunkelküste stranden Meeresriesen, Drescher und Schildkröten, um den verderbten Gewässern rings um den Baum zu entkommen. Naturforscher und Schildwachen suchen auf den Ästen nach dem Schatten, der ihre neue Heimat langsam erdrosselt."}},faq={{q="Warum wurde Teldrassil herangezogen?",a="Nachdem Nordrassil am Ende des Dritten Krieges verwüstet worden war, verloren die Nachtelfen ihre Unsterblichkeit. Erzdruide Fandral Hirschhaupt drängte den Rat der Urahnen und die Druiden des Zirkels des Cenarius, einen neuen Weltbaum im Meer zu pflanzen. Er hoffte, so wiederherzustellen, was sein Volk verloren hatte.",al={"warum herangezogen","wer erschuf teldrassil","ursprung teldrassils"}},{q="Warum stellte Teldrassil die Unsterblichkeit der Nachtelfen nicht wieder her?",a="Nozdormu, der Zeitlose, segnete Nordrassil und verlieh den Nachtelfen die Unsterblichkeit. Als Teldrassil herangezogen wurde, hielt er ihr Verlangen für anmaßend und verweigerte dem neuen Baum seinen Segen.",al={"unsterblichkeit","warum nicht unsterblich","nozdormus segen"}},{q="Wie verlasst Ihr Teldrassil?",a="Geht durch Darnassus zum rosafarbenen Portal in den Tempelgärten. Es bringt Euch hinunter nach Rut'theran am Fuß des Stammes. Von dort nehmt Ihr ein Schiff über das Meer nach Auberdine auf dem Festland der Dunkelküste oder nutzt eine der verfügbaren Hippogryphenrouten.",al={"wie hinausgelangen","den baum verlassen","teldrassil schiff"}},{q="Warum gibt es in Teldrassil keine Erzadern?",a="Teldrassil wächst aus den lebenden Ästen und dem Holz eines gewaltigen Weltbaums, nicht aus kontinentalem Gestein. Ohne steinige Erdkruste im Untergrund gibt es in diesem Gebiet keine Metalladern oder Erzvorkommen, dafür wachsen Kräuter im Überfluss.",al={"wo gibt es kupfer","kein erz","bergbau in teldrassil"}},{q="Warum werden die Furbolgs und Tiere wahnsinnig?",a="Eine finstere Präsenz sickert in Teldrassils ungesegnete Wurzeln ein, und eine Krankheit hat das örtliche Wasser und die Pflanzenwelt verdorben. Sie treibt die friedlichen Holzlinge und den Furbolgstamm der Gnarlpine zur Aggression, während Überreste der Satyrn die Verderbnis gezielt nähren.",al={"verdorbene furbolgs","gnarlpine wahnsinnig","was ist die verderbnis"}},{q="Was ist Laubschattental?",a="Laubschattental ist ein geschütztes Tal auf Teldrassils östlichen Ästen, umgeben vom großen Baum Aldrassil. Junge Nachtelfen beginnen ihre Ausbildung in diesem friedlichen Zufluchtsort, bevor sie in die weite Welt hinausziehen.",al={"laubschattental","startgebiet","gebiet aldrassil"}}},fx={["11a6d5e5"]={q="Was ist Teldrassil?",a="Teldrassil ist ein riesiger Weltenbaum, der auf einer Insel vor der nordwestlichen Küste von Kalimdor gewachsen ist. Sein gigantischer Stamm ragt aus dem Nebelmeer empor und breitet sich in Äste aus, die so gewaltig sind, dass sie ein ganzes bewaldetes Reich mit Seen, Flüssen und der Hauptstadt Darnassus auf ihrem Blätterdach tragen.",al={"was ist das für ein ort","über teldrassil","erzähl mir von teldrassil"}},["313cd5a2"]={q="Was ist auf Teldrassil passiert?",a="Nach dem Dritten Krieg und dem Schaden, der am Nordrassil des Hyjal entstanden war, verschwand der Druide Malfurion Sturmgrimm. In seiner Abwesenheit überzeugte Erzdruide Fandral Hirschhaupt den Zirkel der Ältesten, einen neuen Weltenbaum zu züchten, um das Verlorene zu ersetzen. Obwohl er erfolgreich gewachsen ist, hat seitdem eine schleichende Verderbnis begonnen, seine Äste zu befallen.",al={"geschichte von teldrassil","wie entstand teldrassil","ereignisse auf teldrassil"}},c5e34e84={q="Wer lebt auf Teldrassil oder verwaltet es?",a="Teldrassil ist der angestammte Zufluchtsort und die heutige Heimat der Nachtelfen. Spirituell und zivil leiten die Hohepriesterin Tyrande Wisperwind und Erzdruide Fandral Hirschhaupt ihr Volk von der Hauptstadt Darnassus aus, unterstützt von der Schwesternschaft der Elune, den cenarischen Druiden und den Wächterinnen, die die Waldsiedlungen schützen.",al={"wer führt teldrassil an","anführer von teldrassil","wer lebt hier"}},b86e706e={q="Ist Teldrassil gefährlich?",a="Obwohl Teldrassil von Wächterinnen geschützt wird, wird es zunehmend gefährlicher. Ein dunkles Leiden hat die einheimischen Bestien und lokalen Furbolgs in den Wahnsinn getrieben, während bösartige Satyrn, blutrünstige Harpyien und umherstreifende Holzschlinger die Siedlungen jenseits der patrouillierten Straßen bedrohen.",al={"ist es hier sicher","bedrohungen auf teldrassil","gefahren auf teldrassil"}},["2863bed2"]={q="Warum heißt es Teldrassil?",a="In der darnassischen Sprache der Nachtelfen lässt sich Teldrassil direkt mit 'Krone der Erde' übersetzen. Es wurde zu Ehren seiner Rolle als monumentaler Weltenbaum benannt, der dazu bestimmt ist, ihre Zivilisation zu behüten und zu beschützen.",al={"was bedeutet teldrassil","bedeutung des namens teldrassil"}},["514d23b0"]={q="Wer ist Fandral Hirschhaupt?",a="Fandral Hirschhaupt ist der Erzdruide, der nach Malfurion Sturmgrimms Verschwinden in den Smaragdgrünen Traum die Führung der nachtelfischen Druiden übernahm. Leidenschaftlich, stur und aggressiv, setzte sich Fandral für die Pflanzung von Teldrassil ein und gerät häufig mit der Hohepriesterin Tyrande Wisperwind über die Politik aneinander.",al={"wer ist der erzdruide","fandral hirschhaupt geschichte","hirschhaupt"}},["52c333ac"]={q="Wer ist Tyrande Wisperwind?",a="Tyrande Wisperwind ist die Hohepriesterin der Göttin Elune und das oberste Oberhaupt des nachtelfischen Volkes. Nachdem sie ihr Volk zehntausend Jahre lang durch die lange Mahnwache und den Dritten Krieg geführt hat, leitet sie nun vom The Temple of the Moon in Darnassus aus die Geschicke.",al={"wer ist tyrande","hohepriesterin tyrande","wer führt die nachtelfen an"}},["29b1e9e4"]={q="Wie bin ich auf Teldrassil gelandet?",a="Wenn Ihr ein Nachtelf seid, ist dieser kolossale Weltenbaum die neue Heimat Eures Volkes. Nachdem Ihr Nordrassil und Eure uralte Unsterblichkeit auf dem Hyjal geopfert habt, um die Brennende Legion zu besiegen, siedelten die Kaldorei vor der Nordwestküste von Kalimdor um. Erzdruide Fandral Hirschhaupt und der Zirkel der Ältesten ließen Teldrassil im Nebelmeer wachsen, um Eurer Rasse einen neuen Zufluchtsort zu geben, und Ihr begann Eure Reise in seinen grünen Ästen im Laubschattental. Wenn Ihr von außerhalb hierher gereist seid, seid Ihr wahrscheinlich von der Dunkelküste zum Hafen von Rut'theran am Fuße des Baumes gesegelt und dann durch das leuchtende Portal geschritten, das Reisende direkt in die Krone befördert.",al={"wie gelange ich nach teldrassil","wie bin ich hierhergekommen","warum fange ich hier an"}},["8381279f"]={q="Was soll ich auf Teldrassil tun?",a="Ihr seid dazu berufen, den jungen Weltenbaum zu beschützen und das dunkle Leiden aufzudecken, das seine Äste beunruhigt. Trotz seiner üppigen Wälder greift eine finstere Verderbnis um sich: Holzschlinger werden aggressiv, friedliche Furbolgs des Gnarlpine-Stammes verfallen dem Wahnsinn und abscheuliche Satyrn lauern in schattigen Dickichten wie dem Teufelsfels. Angefangen im Laubschattental und bei der Hilfe für Siedlungen wie Dolanaar müsst Ihr den Wächterinnen und Druiden helfen, das Gleichgewicht wiederherzustellen. Ihr werdet die heiligen Mondbrunnen auffüllen, verdorbenes Ungeziefer ausrotten und die Geschichte Eures Volkes lernen, bevor Ihr Euch in die Hauptstadt Darnassus und über das Meer zum Festland von Kalimdor begebt.",al={"was soll ich auf teldrassil tun","warum bin ich hier","was ist meine mission hier"}}},fp="10,168,21.379.0,26.466.0,17.410.1,25.260.0,52.182.0,28.253.0,44.210.0,52.248.0,19.205.0"}
P.entries["zone:thousandneedles"] = {n="Tausend Nadeln",s="Im Süden Kalimdors erstrecken sich die Tausend Nadeln über einen trockenen Canyon mit Sandsteinsäulen. Tauren halten die Tafelberge, während Gnome und Goblins Raketenwagen über die Schimmernde Ebene jagen.",h="Im Süden Kalimdors erstrecken sich die Tausend Nadeln über einen trockenen Canyon mit Sandsteinsäulen.",kw={"klippenbehüter langhorn","düsterwolkengipfel","fizzel kupferbolz","freiwindposten","der große aufzug","grimmtotem","kravel kohlebart","illusionenrennbahn","pozzik","die schimmernde ebene","tausend nadeln"},ang={["faction:Horde"]="Der Große Aufzug verbindet das Brachland mit Eurer Festung am Freiwindposten und markiert eine strategische Südgrenze gegen Zentaurenklans und aufständische Tauren.",["profession:Engineering"]="Die Salzpfannen locken Tüftler an, die auf der Illusionenrennbahn Raketentreibstoff, Fahrzeugteile und Hochgeschwindigkeitsantriebe erforschen wollen.",["race:Gnome"]="An der Illusionenrennbahn in der Schimmernden Ebene könnt Ihr die Präzision und Eleganz gnomischer Ingenieurskunst neben den windschiefen Goblinkonstruktionen zeigen.",["race:Tauren"]="Als Tauren könnt Ihr sehen, wie hoch Euer Volk kletterte, um dem Gemetzel der Zentauren zu entkommen. Der Freiwindposten dient auch als Sammelpunkt für Angriffe auf die verräterischen Grimmtotem am Düsterwolkengipfel."},sec={{t="Ein Wald aus Stein",b="Vor der Großen Zerschlagung speisten Binnengewässer einen üppigen Flusscanyon, der zum Meer führte. Die Katastrophe zerriss das alte Kalimdor, hob das Flussbett über den Grundwasserspiegel und änderte den Lauf des Flusses. Trockener Fels und Sandsteinspitzen blieben zurück. Dutzende schlanke, zylindrische Säulen ragen wie ein versteinerter Wald aus dem Canyonboden empor.\n\nTauren errichteten Dörfer auf den Säulen und verbanden die Gipfel durch waghalsige Seilbrücken. Sie suchten Schutz vor feindseligen Zentaurenplünderern, die den schattenverhangenen Grund unter ihnen durchstreiften."},{t="Gefahren auf den Tafelbergen",b="Das Leben auf den nadelartigen Spitzen ist alles andere als friedlich. Am Freiwindposten stellen sich Tauren, die der Horde die Treue halten, räuberischen Windnattern und Wyvern vom Steilhang sowie verräterischen Verwandten des kriegerischen Grimmtotemklans entgegen, der sich auf dem Düsterwolkengipfel verschanzt hat. Klippenbehüter Langhorn leitet die Verteidigung des Plateaus. Er sucht mutige Kämpfer, die gegen Grimmtotem-Aufwiegler vorgehen und die zerbrechlichen Brücken zwischen den Gipfeln sichern.\n\nIm Norden bringen gewaltige mechanische Winden am Großen Aufzug Reisende aus dem südlichen Brachland hinab. Die Durchquerung des Canyonbodens bleibt ein tödliches Wagnis."},{t="Die Illusionenrennbahn",b="Im Südosten öffnen sich die Canyonwände zur Schimmernden Ebene, einer gewaltigen, ausgetrockneten Salzpfanne unter dem Meeresspiegel. In dieser rauen, blendenden Weite wahren Gnome und Goblins rund um die Illusionenrennbahn eine brüchige Neutralität. Die rivalisierenden Ingenieure Pozzik und Fizzel Kupferbolz lassen experimentelle Raketenwagen über das harte Salz rasen. Jeder will beweisen, dass sein Volk technologisch überlegen ist.\n\nDer Boxenstopp lockt Schurken, Schwindler wie Kravel Kohlebart und Jäger an, die den zähen Skorpionen, Schildkröten und Basilisken nachstellen, welche das glühend heiße Becken durchstreifen."}},faq={{q="Wie kamen die Tausend Nadeln zu ihrem Namen?",a="Die Tausend Nadeln verdanken ihren Namen den Dutzenden gewaltigen, zylindrischen Sandsteinsäulen, die aus dem Canyonboden ragen. Reißende Flüsse formten sie vor der Großen Zerschlagung. Heute gleichen sie einem Wald aus riesigen Nadeln.",al={"warum heißt es tausend nadeln","ursprung der nadelsäulen","geschichte der felsspitzen"}},{q="Wie gelangt man vom Brachland hinab in die Tausend Nadeln?",a="Reisende nehmen den Großen Aufzug, einen gewaltigen Doppelaufzug, der von Horde-Wachen an der Südgrenze des Brachlands betrieben wird. Ein Sturz von der Kante ist tödlich, wartet also auf die Plattform. Reisende der Allianz können auch von Westen aus durch Thalanaar in Feralas wandern.",al={"wie gelangt man zu den tausend nadeln","eingang zum großen aufzug","aufzug zu den tausend nadeln"}},{q="Warum leben die Tauren auf den Tafelbergen?",a="Zentaurenkriegsrudel trieben die nomadischen Tauren einst beinahe bis zur Auslöschung. Außenposten wie der Freiwindposten auf unzugänglichen Felssäulen schützten sie vor den Sturmangriffen der Zentauren. Hölzerne Hängebrücken verbanden die Tafelberge und ermöglichten den Tauren, hoch über den Raubtieren und Plünderern unter ihnen zu reisen.",al={"warum stehen tauren auf säulen","geschichte des freiwindpostens","tauren auf höher gelegenem gelände"}},{q="Was ist die Illusionenrennbahn?",a="Die Illusionenrennbahn ist ein Erprobungsgelände für Ingenieure auf der Salzpfanne der Schimmernden Ebene. Gnomische und goblinische Tüftler lassen experimentelle Raketenwagen über das flache Salz rasen, um ihren Streit darüber auszutragen, welches Volk die beste Maschinerie baut.",al={"salzpfannenrennstrecke","gnomen-goblin-rennen","raketenwagen-rennstrecke"}},{q="Wie präsent ist der Grimmtotemklan im Canyon?",a="Der Grimmtotemklan besetzt den Düsterwolkengipfel, eine befestigte Ansammlung von Felsspitzen direkt gegenüber dem Freiwindposten. Anders als die anderen Taurenstämme, die der Horde die Treue schworen, greifen die Grimmtotem ihre Verwandten an und schmieden Pläne, um die Tafelberge zu beherrschen.",al={"grimmtotem in den tausend nadeln","tauren am düsterwolkengipfel","böse tauren in den tausend nadeln"}},{q="Was ist die Schimmernde Ebene?",a="Die Schimmernde Ebene ist ein riesiger, ausgetrockneter Seeboden östlich der Tafelberge des Canyons. Ihre Salzkruste entstand, als das uralte Binnenmeer nach der Zerschlagung verdunstete. Glühende Hitze, blendend weißes Salz und gefährliche Raubtiere machen sie zu einer unwirtlichen Wüste, die vor allem für Hochgeschwindigkeitstests genutzt wird.",al={"salzpfanne","weiße wüste der tausend nadeln","östliche wüste"}}},fx={["0eee4587"]={q="Warum fahren Goblins und Gnome in der Wüste mit Raketenautos?",a="Der flache, offene Salzuntergrund der schimmernden Ebene bietet das perfekte Testgelände für den Test von Hochgeschwindigkeitsmotoren. Gnome und Goblins gründeten die Illusionenrennbahn, um den langjährigen Streit darüber, welche Rasse die bessere Technik besitzt, endgültig beizulegen.",al={"warum rennwagen","goblin gnom rennen","raketenauto rivalität"}},e421f132={q="Was hat es mit dem Düsterwolkengipfel und diesen geheimen Notizen auf sich?",a="Der Düsterwolkengipfel ist die schwer bewachte Festung des Stammes der Grimtotem auf den Tafelbergen östlich des großen Aufzugs. Dort gefundene geheime Korrespondenz enthüllt geheime Kontakte zwischen den Anführern der Grimtotem, wie Arnak Grimtotem, und einer unbekannten dunklen Macht, was auf verräterische Ambitionen weit jenseits einfacher Stammesfehden hindeutet.",al={"düsterwolkengipfel notizen","grimtotem notizen","düsterwolkengipfel geheimnis"}},["7b560411"]={q="Was planen die Grimtotem?",a="Die Grimtotem lehnen die Führung von Cairne Bluthuf und die kulturellen Veränderungen, die der Beitritt zur Horde mit sich brachte, grundlegend ab. Sie trachten danach, Cairne zu stürzen, die Autorität der Horde zu untergraben und verbünden sich sogar mit finsteren Mächten und beschwören Wesen der Vergeltung, um ihre Vorherrschaft durchzusetzen.",al={"grimtotem plan","was wollen grimtotem","grimtotem verschwörung"}},["853c4dd1"]={q="Was ist der Steilhang und warum wollen wir Wyverneier?",a="Der Steilhang ist der angestammte Nistplatz wilder Wyverns in Tausend Nadeln. Tauren aus dem Freiwindposten klettern zu diesen hohen Felsvorsprüngen hinauf, um befruchtete Wyverneier zu sammeln, damit diese sorgfältig aufgezogen und als treue Flugreittiere für die Horde ausgebildet werden können.",al={"steilhang wyverns","warum wyverneier sammeln","steilhang eier"}},dc3189d8={q="Wie bin ich in Tausend Nadeln gelandet?",a="Die meisten Reisenden kommen von Norden, indem sie durch das Brachland an Camp Taurajo vorbeireiten, bis sie schließlich den steilen Abhang erreichen, wo der massive, von Tauren konstruierte Der große Aufzug einen direkt auf den Boden des Canyons hinablässt. Alternativ können Abenteurer, die durch die dichten Wälder von Feralas nach Osten wandern, die westliche Schlucht zu Fuß betreten, während wagemutige Entdecker, die den Gefahren der Düstermarschen trotzen oder nach Theramore segeln, durch die umkämpften Lücken schlüpfen. Ein langer Marsch über Land nach Norden von den Wüsten von Tanaris bringt einen ebenfalls direkt in die weitläufige Salzfläche der schimmernden Ebene.",al={"wie kam ich hierher","wie erreiche ich tausend nadeln","nach tausend nadeln kommen"}},["16801326"]={q="Was soll ich in Tausend Nadeln tun?",a="Ihre Anwesenheit hier hängt von Ihren Loyalitäten und Ambitionen ab. Champions der Horde haben die Aufgabe, den Freiwindposten zu unterstützen: die Galak-Zentaurenhorden, die den Schluchtenboden durchstreifen, zurückzudrängen, Harpyienhorste zu überwachen, Wyverneier vom Steilhang zu sammeln und den verräterischen Grimtotem-Stamm zu bekämpfen, der sich auf dem Düsterwolkengipfel verschanzt hat. Für unabhängige Wanderer und Reisende der Allianz dient die dramatische Weite als gefährliche Überlandkreuzung zwischen dem zentralen und südlichen Kalimdor, die zur schimmernden Ebene führt, wo Goblin- und Gnom-Waghälse gutes Gold für Teile, Treibstoff und Hilfe bei ihrer ewigen Raketenauto-Rivalität zahlen.",al={"warum bin ich hier","was ist mein zweck hier","was mache ich in tausend nadeln"}},d1fb42e2={q="Was sind die Tausend Nadeln?",a="Tausend Nadeln ist ein riesiger, arider Canyon, der das zentrale und südliche Kalimdor teilt. Sein Canyonboden ist übersät mit hoch aufragenden Sandsteinfelsen, die sich wie ein versteinerter Wald in den Himmel strecken und oben durch zarte Seil- und Holzbrücken verbunden sind. Im Osten geht der Canyon in die schimmernde Ebene über, eine blendend weiße Salzpfanne.",al={"was ist das für ein ort","über tausend nadeln","erzähl mir von tausend nadeln"}},["98fcff4e"]={q="Warum ist hier alles aus Canyons und Säulen?",a="Vor langer Zeit, vor dem Großen Zerwürfnis, war diese Region ein grüner Fluss-Canyon, der von reißenden Wassern geformt wurde, die von Feralas nach Osten in ein Binnenmeer flossen. Als die Welt zerbrach, stieß das Kataklysmus das Flussbett in die Höhe und veränderte den Lauf des Flusses. Ohne Wasser trocknete das Land aus und hinterließ hoch aufragende Sandsteinsäulen und ein vertrocknetes Salzbett.",al={"warum gibt es felsnadeln","wie entstanden die nadeln","warum sandsteinsäulen"}},["05d5c74f"]={q="Sind die Tausend Nadeln gefährlich?",a="Es ist ziemlich gefährlich. Barbarische Galak-Zentauren patrouillieren in Raubzügen auf dem Canyonboden, während räuberische Geier, Skorpide und abtrünnige Harpyien die Klippen heimsuchen. Selbst die Seilbrücken zwischen den hohen Felsnadeln bergen Gefahren, da Raubvögel häufig auf unachtsame Reisende herabstürzen oder die Spannweiten beschädigen.",al={"wie gefährlich sind die tausend nadeln","gefahren hier","ist es sicher"}},["1b8e8bea"]={q="Warum hat die Horde mich in die Tausend Nadeln geschickt?",a="Die Horde unterhält hier eine wichtige Präsenz, um den lokalen Tauren-Stämmen zu helfen, die unter unerbittlichen Angriffen stehen. Der Freiwindposten ist ein wichtiges Bollwerk, das das Brachland mit den südlichen Wüsten verbindet, und die Horde braucht mutige Helden, um marodierende Zentauren zurückzudrängen und interne Bedrohungen zu unterdrücken.",al={"horde mission tausend nadeln","warum bin ich hier horde","was will die horde hier"}},a7c3b539={q="Ist das Land der Tauren?",a="Ja. Die kargen Canyons und hohen Mesas der Tausend Nadeln sind seit unzähligen Generationen traditionell das angestammte Gebiet mehrerer Tauren-Stämme, obwohl bösartige Zentaurenclans sie an den Rand des Überlebens drängten, bevor die Horde eintraf.",al={"gehören die tausend nadeln den tauren","gebiet der tauren","ist das land der shu'halo"}},fef8bf7c={q="Was ist der Freiwindposten?",a="Der Freiwindposten ist der primäre Außenposten der Horde in den Tausend Nadeln. Er wurde auf einer massiven Mesa hoch über dem Talboden errichtet und verfügt über hölzerne Aufzüge, einen Flugturm und ein Netzwerk von Hängebrücken, die zu benachbarten Felsnadeln führen.",al={"freiwindposten","was ist freiwindposten"}},["6ac472b0"]={q="Wer sind die Galak-Zentauren und warum greifen sie uns an?",a="Der Stamm der Galak sind die lokalen Zentauren, die den Canyonboden für sich beanspruchen. Wie alle Zentauren sind sie extrem territorial, nomadisch und gewalttätig. Sie jagen jeden Reisenden, der durch die Schluchten zieht, und versuchen, die Siedlungen der Tauren vollständig auszulöschen.",al={"galak-zentauren","warum greifen zentauren an","stamm der galak"}},["9f0b1de8"]={q="Warum hassen sie die Tauren?",a="Die Feindschaft zwischen Tauren und Zentauren ist uralt und unerbittlich. Über Generationen hinweg jagten umherziehende Zentauren auf den Ebenen von Kalimdor Tauren zum Zeitvertreib und führten brutale, grundlose Kriege, die die friedlichen Stämme ständig auf der Flucht hielten.",al={"warum hassen zentauren tauren","zentauren tauren fehde","zentauren groll"}}},fp="16,179,17.529.0,18.553.0,18.535.0,38.222.0,59.251.0,43.279.0,27.248.0,45.235.0,30.284.0"}
P.entries["zone:thunderbluff"] = {n="Donnerfels",s="Hoch über den Graslanden von Mulgore erhebt sich Donnerfels auf windgepeitschten roten Felsplateaus. Die Stadt ist die Hauptstadt der Tauren und das Herz ihres Geistes, ihrer Kultur und ihres Handels. Schwankende Hängebrücken und hölzerne Aufzüge verbinden die Höhen. Fern der marodierenden Zentauren ist sie ein friedlicher Ort für Reisende aus ganz Kalimdor.",h="Hoch über den Graslanden von Mulgore erhebt sich Donnerfels auf windgepeitschten roten Felsplateaus.",kw={"cairne bluthuf","die anhöhe der ältesten","aufzüge","hamuul runetotem","die anhöhe der jäger","magatha grimmtotem","mulgore","die teiche der visionen","die anhöhe der geister","donnerfels"},ang={["class:Druid"]="Auf der Anhöhe der Ältesten leitet Erzdruide Hamuul Runetotem das bedeutendste Heiligtum der Horde für Naturmagie. Er ist der erste Taurendruide seit Jahrtausenden, der in dieser Kunst unterrichtet wurde.",["class:Shaman"]="Auf der Anhöhe der Geister bieten die Teiche der Visionen einen stillen Ort, um die Elementargeister und die Geister Eurer Tauren-Vorfahren zu ehren und zu hören.",["faction:Horde"]="Donnerfels bringt eine ländliche Atmosphäre in den südlichen Teil von The New Horde in Kalimdor und ist viel friedlicher als Orgrimmars rauhe Wehrmauern.",["race:Tauren"]="Donnerfels steht für die hart erkämpfte Einigkeit und den Neubeginn Eures Volkes nach Generationen des Umherziehens und der Angriffe der Zentauren unter Oberhäuptling Cairne Bluthuf."},sec={{t="Eine dauerhafte Zuflucht",b="Unzählige Generationen lang durchstreiften die Tauren Kalimdor und kämpften ums Überleben gegen die Zentauren. Diese Zeit endete im Dritten Krieg, als sich Oberhäuptling Cairne Bluthuf mit Kriegshäuptling Thrall verbündete. Gemeinsam brachen Orcs und Tauren die Angriffe der Zentauren und gewannen die Weidegründe von Mulgore. Dann führte Cairne die verbündeten Stämme hinauf auf diese steinernen Bastionen und gründete Donnerfels. Es war das erste dauerhafte Zuhause, das die vereinten Stämme seit Jahrhunderten gekannt hatten."},{t="Eine Stadt in den Wolken",b="Auf den zentralen Felsplateaus liegen die Märkte, die Bank und das Gasthaus sowie ein hoch aufragender Horst für die Windreiter. Drei weitere Plateaus erstrecken sich über dem Abgrund, jedes mit seiner eigenen Aufgabe. Späher und Fährtenleser leben auf der Anhöhe der Jäger. Die Hüter der Überlieferungen leben auf der Anhöhe der Ältesten, zusammen mit dem Zirkel des Cenarius unter Erzdruide Hamuul Runetotem.\n\nDie Anhöhe der Geister ist den Geistern vorbehalten. Dort leben Schamanen und Priester. Tief unter ihnen liegen die Höhlen, die als die Teiche der Visionen bekannt sind."},{t="Ein brüchiger Zusammenhalt",b="Cairne Bluthuf genießt den Respekt fast aller Stämme, doch unter den erst kürzlich sesshaft gewordenen Tauren herrscht nicht überall Einigkeit. Der Stamm der Grimmtotem, angeführt von der Ältesten Magatha Grimmtotem, lebt auf der Anhöhe der Ältesten. Magatha stellt Cairnes versöhnliche Art und seine Treue zu den fremden Völkern der Horde infrage. Unter Cairnes wachsamen Augen herrscht Frieden, doch an den Ratsfeuern über den Ebenen bestehen weiterhin Spannungen."}},faq={{q="Wer herrscht über Donnerfels?",a="Oberhäuptling Cairne Bluthuf herrscht über Donnerfels und führt die vereinten Taurenstämme an. Seine Weisheit, Geduld und Stärke werden verehrt. Er gründete die Stadt, nachdem er sich mit Thralls Horde verbündet und die Zentauren aus Mulgore vertrieben hatte. So vereinte er die nomadischen Stämme unter The New Horde.",al={"anführer von donnerfels","wer hat das sagen","häuptling von donnerfels","cairne"}},{q="Wie gelangt Ihr nach Donnerfels hinauf?",a="Wenn Ihr zu Fuß oder auf einem Kodo ankommt, nehmt einen der großen hölzernen Plattformaufzüge an der Südwest- oder Nordostseite des zentralen Plateaus. Ihr könnt auch mit einem Wind Rider über Kalimdor fliegen.",al={"aufzug in donnerfels","wie kommt man hinein","eingang von donnerfels","hinaufkommen"}},{q="Warum errichteten die Tauren ihre Stadt auf hohen Felsplateaus statt am Boden?",a="Jahrhundertelang setzten Zentaurenstämme den Tauren während ihres nomadischen Lebens zu. Die steilen Klippen der Felsplateaus schützen ihre Heimat, Schmieden und verehrten Ältesten vor Angriffen vom Boden aus und geben den Tauren einen Ort, an dem sie in Frieden siedeln können.",al={"warum felsplateaus","warum leben sie auf klippen","klippen von donnerfels","höhenlage der tauren"}},{q="Was sind die verschiedenen Anhöhen der Stadt?",a="Das zentrale Plateau hat eine untere, mittlere und obere Ebene, umgeben von drei äußeren Plateaus. Auf der Anhöhe der Jäger befinden sich Krieger, Jäger und Fährtenleserhütten. Druiden, Weise und der Stamm der Grimmtotem leben auf der Anhöhe der Ältesten. Auf der Anhöhe der Geister gibt es Schreine der Erdenmutter und Ausbilder für Schamanen, Priester und Magier. Darunter liegen die Teiche der Visionen, die Schamanen und Priestern, die der spirituellen Zwiesprache geweiht sind, Schutz bieten.",al={"gebiete von donnerfels","was sind die anhöhen","bezirke von donnerfels"}},{q="Was sind die Teiche der Visionen?",a="Die Teiche der Visionen sind heilige Höhlen unter der Anhöhe der Geister. Tauren-Seher, Geistwandler und Praktizierende der arkanen Künste versammeln sich an diesen stillen, nebelverhangenen Wassern, um mit den Elementen Zwiesprache zu halten und Vorzeichen über die Zukunft ihres Volkes zu deuten.",al={"die teiche der visionen","höhle auf der anhöhe der geister","höhle in donnerfels"}},{q="Wer ist Magatha Grimmtotem?",a="Magatha Grimmtotem ist die Matriarchin und Älteste des Grimmtotemstamms. Sie lebt auf der Anhöhe der Ältesten und nimmt an Cairnes Rat teil, misstraut jedoch Außenstehenden und stellt die offene Haltung des Bloodhoof tribe gegenüber der Horde infrage.",al={"magatha","älteste","wer ist anführer der grimmtotem"}}},fx={["6fa5b073"]={q="Was ist Donnerfels?",a="Donnerfels ist die Hauptstadt der Tauren, hoch oben auf den windgepeitschten Tafelbergen im nördlichen Mulgore gelegen. Sie wurde von Oberhäuptling Cairne Bluthuf gegründet, nachdem er die Zentauren mit Thralls Horde zurückgedrängt hatte, und bietet einen sicheren, dauerhaften Zufluchtsort für ein Volk, das über Generationen als umherziehende Nomaden lebte.",al={"was ist diese stadt","erzähl mir von donnerfels","donnerfels stadt"}},fc90632b={q="Ist Cairne Bluthuf ein König?",a="Nein. Cairne Bluthuf trägt den Titel eines Oberhäuptlings der vereinten Taurenstämme. Die Gesellschaft der Tauren krönt keine Monarchen; Cairne regiert durch den tiefen Respekt, die Weisheit und die Stärke, die er über Jahrzehnte bewiesen hat, und nicht durch ein erbliches, königliches Gottesgnadentum.",al={"cairne bluthuf könig","ist cairne ein könig","tauren könig"}},["047fa056"]={q="Steht Cairne Bluthuf unter Thralls Befehl?",a="Thrall ist der Kriegshäuptling der Horde, aber seine Bindung zu Cairne gründet auf gegenseitiger Ehre und Bündnis und nicht auf strikter Unterwerfung. Cairne verpflichtete sein Volk der Horde aus Dankbarkeit und einer gemeinsamen Vision und steht Thrall als einer seiner vertrauenswürdigsten Berater und als Gleichgestellter zur Seite.",al={"steht cairne unter thralls befehl","ist thrall cairnes boss","cairne und thrall"}},["85c1a10f"]={q="Warum sind die Tauren der Horde beigetreten?",a="Zentaurenplünderer hatten die nomadischen Tauren im Brachland an den Rand der Ausrottung getrieben. Als Kriegshäuptling Thrall und die Orcs in Kalimdor landeten, halfen sie Cairnes Volk, die Belagerung der Zentauren zu brechen und Mulgore zu sichern, wodurch ein unzerbrechliches Band zwischen ihren Kulturen geschmiedet wurde.",al={"warum der horde beitreten","tauren horde allianz","wie traten die tauren bei"}},["3180b5ca"]={q="Was hat es mit dem Stamm der Grimtotem auf sich?",a="Die Grimtotem sind ein wilder und aggressiver Clan unter der Führung der Elder Crone Magatha. Im Gegensatz zum friedlichen Stamm der Bluthuf hegen sie tiefes Misstrauen gegenüber Außenstehenden und stellen offen Cairnes friedliche Führung in Frage, da sie glauben, die Tauren sollten Kalimdor erobern und die anderen Rassen vertreiben.",al={"grimtotem stamm","wer sind die grimtotem","grimtotem tauren"}},ca8246e8={q="Sind die Grimtotem Feinde von Cairne?",a="Offiziell bleiben sie Teil der vereinten Taurennation, und Magatha wohnt sogar auf Die Anhöhe der Ältesten. Unter der Oberfläche jedoch brodelt eine bittere politische Rivalität, da Magatha ständig Ränkespiele betreibt und glaubt, dass sie allein die rechtmäßige Vision hat, die Tauren zu regieren.",al={"sind grimtotem böse","grimtotem gegen cairne","magatha gegen cairne"}},["54829977"]={q="Ist Donnerfels gefährlich?",a="Innerhalb der Stadt sorgen die tapferen Wachen für Ordnung und Sicherheit vor den Bestien und Stachelebern, die auf den Ebenen darunter schleichen. Die größte unmittelbare Gefahr für Besucher ist der steile Abgrund – ein unvorsichtiger Schritt von den Rändern der Tafelberge oder den Holzbrücken aus endet tödlich.",al={"ist donnerfels sicher","bedrohungen in donnerfels","gefahr hier"}},["7db56847"]={q="Wie bin ich in Donnerfels gelandet?",a="Wenn Ihr ein junger Taure seid, begann Eure Reise im Süden auf dem geschützten Grasland der Hochwolkenebene und führte durch das Dorf der Bluthufe, bevor Ihr hierher kamt. Der Weg führt zum Fuß dieser gewaltigen Tafelberge, wo große hölzerne Seilaufzüge Reisende hunderte Fuß in den Himmel hieven. Alternativ reisen Besucher aus fernen Ländern über Kalimdor oft mit einem Wind Rider zum zentralen Wind Rider Roost auf den Felsen.",al={"wie kam ich hierher","wie kam ich nach donnerfels","wie erreiche ich donnerfels"}},["347b5cac"]={q="Was soll ich in Donnerfels tun?",a="Donnerfels ist das spirituelle und kulturelle Herz der vereinten Taurenstämme. Hier könnt Ihr fortgeschrittene Ausbildung von den Ältestenschamanen, Druiden, Jägern und Kriegern suchen, die sich auf den Anhöhen versammelt haben. Oberhäuptling Cairne Bluthuf und die Stammesältesten verlassen sich ebenfalls auf fähige Champions, um Mulgore vor anhaltenden Bedrohungen zu schützen – einschließlich marodierender Zentauren, der vordringenden Venture Company, Harpyien und rebellischen Stachelebern –, bevor sie Euch nach Osten in die größeren Prüfungen der Horde senden.",al={"was sollte ich in donnerfels tun","warum bin ich hier","was ist mein zweck hier"}}},fp="13,326,17.466.0,20.453.0,12.391.1,24.277.0,35.194.0,61.212.0,41.395.0,29.239.0,25.233.0"}
P.entries["zone:tirisfal"] = {n="Tirisfal",s="Tirisfal im Norden Lordaerons ist die Heimat von Fürstin Sylvanas Windläufer und ihren Verlassenen. Unter verdorbenen Himmeln umgeben gefallene Anwesen und ruhende Krypten ihre gewaltige Hauptstadt unter der Erde, die Unterstadt. Die hirnlose Geißel schnürt sie ein, ebenso wie die Eiferer des Scharlachroten Kreuzzugs. Hier kämpfen die Toten mit freiem Willen ums Überleben.",h="Tirisfal im Norden Lordaerons ist die Heimat von Fürstin Sylvanas Windläufer und ihren Verlassenen.",kw={"agamand","balnir","brill","todesend","verlassene","lichtungen","lordaeron","scharlachroter kreuzzug","sylvanas","tirisfal","unterstadt"},ang={["class:Priest"]="Heilige historische Stätten wie Faols Ruheplatz – das Grab von Erzbischof Alonsus Faol, dem Gründer der Silver Hand – liegen hier. Der Tod hat sie entstellt, und Eiferer und Schattenpriester streiten um sie.",["faction:Alliance"]="Für die überlebenden Völker der Allianz ist Tirisfal ein tragisches Denkmal für den Fall Lordaerons, voller entweihter Gräber einstiger Brüder und Schwestern im Glauben.",["faction:Horde"]="Tirisfal ist die lebenswichtige Bastion der Horde in den nördlichen Östlichen Königreichen. Es festigt die diplomatischen Bande zu den Verlassenen und wehrt menschliche Extremisten und die Geißel ab.",["race:Undead"]="Dies ist Euer angestammtes Heimatland gleich zweimal: das Königreich, das Ihr im Leben erbaut habt, und das unsichere Schutzgebiet, das Ihr im Untod unter Fürstin Sylvanas verteidigen müsst."},sec={{t="Ein Land im Zwielicht",b="Einst war Tirisfal die fruchtbare Wiege der Menschheit, bevor die Seuche des Lichkönigs seine Bewohner dahinraffte. Nun bricht die Sonne nur selten durch die Düsternis, über sterbenden Wäldern und kalten Küstenhügeln. Alte Gehöfte wie Agamands Mühlen stehen noch, doch die meisten ihrer Herren liegen in Massengräbern oder wandeln als ruhelose Tote. Dennoch hält sich in Städten wie Brill eine dunkle Widerstandskraft. Und in Todesend lernen die frisch erwachten Verlassenen, ihr zweites Leben zu ertragen."},{t="Ein Krieg an zwei Fronten",b="Fürstin Sylvanas herrscht nun unter den Ruinen von Lordaeron über die Region, doch ihr Volk ist von allen Seiten bedrängt. Diener der Geißel befallen noch immer Senken, Felder und bröckelnde Krypten und sind vollständig an den Frostthron in Nordend gebunden. Im Osten hält der Scharlachrote Kreuzzug das nördliche Tirisfal, von seiner Festung im Scharlachroten Kloster aus. Ihre Patrouillen haben geschworen, alle untoten Kreaturen zu vernichten, und führen einen ständigen Guerillakrieg gegen Kundschafter und Reisende der Verlassenen."},{t="Echos der uralten Vergangenheit",b="Die Geschichte der Lichtungen reicht weiter zurück als jede menschliche Krone. Vor langer Zeit wollten Hochelfen im Exil sich in diesen Wäldern niederlassen. Doch schattenhafte Mächte tief unter der Erde begannen, sie in den Wahnsinn zu treiben, und sie zogen weiter nach Norden. Jahrhunderte später erwählte der geheime Rat von Tirisfal diese schattigen Haine. Hier stärkte er seine einsamen Wächter, die Azeroth vor den Dämonen beschützten."}},faq={{q="Warum sind der Himmel grün und das Land verfault?",a="Während des Dritten Krieges entfesselten Prinz Arthas und die Geißel die Seuche der Untoten über dem Königreich Lordaeron. Die magische Verderbnis vergiftete nicht nur die Bevölkerung, sondern auch den Boden, die Bäume und das Wasser und ließ die Lichtungen in ewigem, unheimlichem und krankhaftem Verfall zurück.",al={"warum ist tirisfal verseucht","was geschah mit tirisfal","warum stirbt tirisfal"}},{q="Was unterscheidet hier die Verlassenen von der Geißel?",a="Die Verlassenen sind Untote, die sich nach der Schlacht am Hyjal aus der telepathischen Beherrschung des Lichkönigs befreiten und sich aus eigenem Willen Fürstin Sylvanas Windläufer anschlossen. Die Geißel, die auf den Gehöften und in den Ruinen umherstreift, bleibt eine hirnlose Sklavenschaft, gebunden an die Befehle des Lichkönigs.",al={"verlassene gegen geißel","warum greifen zombies untote an","sind alle untoten böse"}},{q="Wer sind die rot gepanzerten Soldaten, die Reisende angreifen?",a="Sie gehören zum Scharlachroten Kreuzzug, einem kompromisslosen abgespaltenen Orden aus früheren Paladinen der Silver Hand und Überlebenden. In der Überzeugung, alle Untoten seien unverbesserliche Abscheulichkeiten, die mit Schwert und Feuer gereinigt werden müssten, töten sie mit fanatischem Hass sowohl hirnlose Sklaven als auch die Verlassenen mit freiem Willen.",al={"scharlachroter kreuzzug","rote menschen","menschen im kloster"}},{q="Woher stammt der Name Tirisfal?",a="Der Name ist älter als jedes menschliche Königreich, und sein wahrer Ursprung ist in Vergessenheit geraten. Bekannt ist er vor allem durch den Rat von Tirisfal, den geheimen Orden der Magier, der die Wächter stärkte, damit sie Azeroth vor Dämonen beschützten.",al={"bedeutung von tirisfal","ursprung von tirisfal"}},{q="Wo beginnt die Reise der frisch erwachten Verlassenen?",a="Frisch erwachte Verlassene erheben sich aus den Krypten des Schattengrabes in Todesend, einer abgeschiedenen Ortschaft im Südwesten Tirisfals. Dort beurteilen Verwalter und Vollstrecker, ob die Auferstandenen bei Verstand und treu genug sind, um der Dunklen Fürstin zu dienen.",al={"startgebiet der untoten","wo liegt todesend","startgebiet der verlassenen"}},{q="Wie verlassen Reisende Tirisfal, um andere Kontinente zu erreichen?",a="Auf dem Hügel südlich von Brill, direkt außerhalb der Ruinen von Lordaeron, steht ein großer, von Goblins betriebener Zeppelin-Turm. Diese Luftschiffe bieten regelmäßige Direktverbindungen über das Meer nach Orgrimmar in Kalimdor und zum Basislager Grom'gol im Schlingendorntal.",al={"zeppeline in tirisfal","wie kommt man nach orgrimmar","wie kommt man ins schlingendorntal"}}},fx={["6c272224"]={q="Was ist Tirisfal?",a="Tirisfal ist das Kernland der Verlassenen an der Nordküste von Lordaeron. Einst das friedliche, fruchtbare Herz eines stolzen Menschenkönigreichs, wurde es während des Dritter Krieg von der Pest des Untodes der Geißel verwüstet. Heute bedecken verseuchte Wälder und ein ewiges grünes Zwielicht die Hügel, eingerahmt von den Ruinen von Lordaeron und umgeben von feindseligen Eiferern, wilden Bestien und verbliebenen Untoten.",al={"was ist tirisfal","erzähl mir von tirisfal","tirisfal gebietsüberlieferung"}},["342b65f9"]={q="War dies schon immer das Land der Untoten?",a="Nein. Über tausende von Jahren war Tirisfal die Wiege der menschlichen Zivilisation und das blühende Herz des Königreichs von Lordaeron. Friedliche Gehöfte, wohlhabende Mühlen und kleine Weiler florierten unter König Terenas Menethil. Diese Ära endete gewaltsam während des Dritter Krieg, als Prinz Arthas und der Kult der Verdammten mit der Pest durch das Land fegten und die Bewohner in untote Sklaven verwandelten, bevor Sylvanas Windläufer sie befreite.",al={"war tirisfal immer untot","wer lebte hier vorher","tirisfal vor der pest"}},["4790468d"]={q="Wer lebt oder herrscht in Tirisfal?",a="Die Verlassenen beanspruchen Tirisfal unter der Herrschaft von Königin Sylvanas Windläufer aus der Unterstadt. Ihr Griff ist jedoch ständig umkämpft. Der fanatische Scharlachroter Kreuzzug befehligt Befestigungen und sein großes Kloster im Nordosten, während geistlose Geißel-Kreaturen verlassene Farmen durchstreifen. An der östlichen Grenze beim Bollwerk koordinieren die Verlassenen ihre Aktionen mit der Argentumdämmerung, um die Schrecken der Westliche Pestländer einzudämmen.",al={"wer regiert tirisfal","wer kontrolliert tirisfal","tirisfal fraktionen"}},["97ffdb73"]={q="Ist Tirisfal gefährlich?",a="Extrem gefährlich. Außerhalb der Mauern der Außenposten der Verlassenen begegnet Ihr geistlosen Resten der Geißel, wilden Gnollen, riesigen Arachniden und bösartiger Tierwelt, die von der Pest verseucht wurde. Noch schlimmer sind die Eiferer des Scharlachroter Kreuzzug, die jeden Untoten auf Sicht hinrichten. Im fernen Osten liegen die Westliche Pestländer, wo Monster, die weitaus tödlicher sind als alles in Tirisfal, die Unvorsichtigen zerfleischen werden.",al={"wie gefährlich ist tirisfal","tirisfal bedrohungen","ist es hier sicher"}},["30e6283a"]={q="Wer hat in Brill das Sagen?",a="Magistrat Sevren beaufsichtigt die zivile Verwaltung von Brill und leitet den Wiederaufbau und das tägliche Überleben der Stadt. Die militärische Autorität und die taktischen Operationen, insbesondere der Feldzug gegen den nahegelegenen Scharlachroter Kreuzzug, werden von Exekutor Zygand befehligt.",al={"brill anführer","wer führt brill","das sagen in brill"}},["3fc3649e"]={q="Wem untersteht Magistrat Sevren?",a="Sevren dient der Dunklen Fürstin, Königin Sylvanas Windläufer. Als Magistrat von Brill vertritt er die zivile Autorität der Krone der Verlassenen in der Region und arbeitet dabei direkt mit den königlichen Exekutoren und der Royal Apothecary Society mit Sitz in der Unterstadt zusammen.",al={"vorgesetzter von sevren","wem untersteht sevren","führungskette in brill"}},["381a9b46"]={q="Wo befindet sich die Bansheekönigin?",a="Fürstin Sylvanas Windläufer residiert im Royal Quarter der Unterstadt, tief unter den Ruinen von Capital City, direkt südlich von Brill. Von ihrem Thronsaal aus leitet sie die Verlassenen in ihrem Krieg gegen die Geißel und den The Scarlet Crusade.",al={"wo ist sylvanas","sylvanas finden","standort der bansheekönigin"}},e7993821={q="Was ist Brill?",a="Brill ist die wichtigste Siedlung der Verlassenen im zentralen Tirisfal, gelegen an der Kreuzung nördlich von Capital City. Einst eine lebende Siedlung unter der Barov-Herrschaft, wurde sie nach dem Dritten Krieg wiederaufgebaut, um neu erweckten Untoten einen Ort der Ruhe, des Handels und der Organisation zu bieten, bevor sie in die Welt hinausziehen.",al={"über brill","was für eine stadt ist brill","hintergrundgeschichte von brill"}},["529e09c8"]={q="Lebten hier früher einmal lebende Menschen?",a="Ja. Brill war einst eine ruhige menschliche Gemeinde innerhalb des Königreichs Lordaeron. Es wurde zum Ausgangspunkt früher Experimente mit der Seuche, die von Kel'Thuzad orchestriert wurden, was zu Massenopfern und riesigen Massengräbern führte, noch bevor Prinz Arthas jemals eintraf, um Nachforschungen anzustellen.",al={"lebten menschen in brill","lebendige geschichte von brill","wer lebte in brill"}},["7b7ff5e2"]={q="Was ist die Taverne Zur Galgenschlinge?",a="Die Taverne Zur Galgenschlinge ist der zentrale Treffpunkt und das Gasthaus von Brill. Sie bietet Schutz, üble Getränke und eine Atempause vor den düsteren Wäldern außerhalb. In ihren dunkleren Ecken halten die Verlassenen gefangene Feinde – wie etwa die Eiferer des The Scarlet Crusade – für finstere Versuche der Apotheker gefangen.",al={"taverne zur galgenschlinge","gasthaus von brill","was ist die taverne zur galgenschlinge"}},["0d8014ee"]={q="Was hat es mit Agamands Mühlen auf sich?",a="Agamands Mühlen war einst das wohlhabendste und produktivste landwirtschaftliche Anwesen in Tirisfal, berühmt für Mehl und Getreide. Als die Seuche zuschlug, wurde der gesamte Komplex überrannt und ein Gemetzel folgte. Heute steht es als eine verrottende, von Windmühlen gesäumte Ruine da, die von den untoten Dienern der Geißel heimgesucht wird.",al={"hintergrundgeschichte von agamands mühlen","was geschah mit agamands mühlen","agamands mühlen"}},["001d4abe"]={q="Wer waren die Agamands?",a="Die Agamands waren eine adelige, wohlhabende menschliche Dynastie, die die weitläufigen Mühlen entwickelte und Grundbesitz in ganz Tirisfal hielt, einschließlich Brill. Während des Dritten Krieges konnte ihr Reichtum sie nicht retten; die Familie fiel der Geißel zum Opfer und ihre reanimierten Patriarchen suchen weiterhin das Anwesen heim.",al={"familie agamand","wer lebte in agamands mühlen","die agamands"}},eeb96a2c={q="Warum sind sie uns gegenüber feindselig, wenn sie auch Untote sind?",a="Die Untoten, die Agamands Mühlen heimsuchen, haben ihren freien Willen nie wiedererlangt. Im Gegensatz zu den Verlassenen, die sich von der mentalen Kontrolle des Lichkönigs befreit haben, bleiben diese Kreaturen als gedankenlose Sklaven der Geißel gefangen, gezwungen, jeden Lebenden oder abtrünnigen Toten zu vernichten, der ihr Gebiet betritt.",al={"warum greifen die agamands uns an","warum sind die untoten der agamands feindselig","warum gegen andere untote kämpfen"}},a357af07={q="Wohin führt das alles nach Tirisfal?",a="Die meisten Verlassenen reisen durch den Gebirgspass nach Süden in den Silberwald, um bei der Sicherung der südlichen Grenze zu helfen und gegen Agenten von Dalaran und Rot Hide-Gnolle zu kämpfen. Alternativ bieten Zeppeline südlich von Brill eine Passage nach Orgrimmar oder zum Basislager Grom'gol auf der anderen Seite des Meeres.",al={"wohin nach tirisfal","nächstes gebiet nach tirisfal","nach tirisfal"}},["50336b90"]={q="Was ist die Unterstadt?",a="Die Unterstadt ist die weitläufige unterirdische Hauptstadt der Verlassenen, erbaut innerhalb der alten Abwasserkanäle, Krypten und Katakomben unter den zerstörten Ruinen von Lordaeron. Sie dient als Festung von Königin Sylvanas und als Command Center für die Operationen der Verlassenen in ganz Azeroth.",al={"was ist die unterstadt","hintergrundgeschichte der unterstadt","über die unterstadt"}},ddddba9f={q="Ist die Grenze zum Silberwald als Nächstes dran?",a="Ja. Wenn Ihr der Straße nach Süden aus Tirisfal folgt, gelangt Ihr direkt in den Silberwald. Dies ist die natürliche Fortsetzung Eures Dienstes für die Verlassenen, wo Ihr Euch der wachsenden Bedrohung entlang der südlichen Grenzen von Lordaeron stellt.",al={"als nächstes in den silberwald","gehe ich als nächstes in den silberwald","grenze zum silberwald"}},["789ead4d"]={q="Wie bin ich in Tirisfal gelandet?",a="Wenn Ihr ein neu erweckter Verlassener seid, seid Ihr während des Falls von Lordaeron an die Geißel gestorben und hier begraben worden. Da der Griff des Lichkönigs gebrochen ist, kehrte Euer freier Wille zurück und Ihr habt Euch aus dem Grab im abgelegenen Tal von Todesend herausgekämpft. Wenn Ihr zu den anderen Völkern der Horde gehört, seid Ihr wahrscheinlich über die Zeppeltürme zwischen Brill und der Unterstadt angekommen, die dieses verseuchte Reich direkt mit Orgrimmar und dem Basislager Grom'gol verbinden.",al={"wie bin ich hierher gekommen","wie bin ich nach tirisfal gekommen","wie bin ich angekommen"}},["89135166"]={q="Was soll ich in Tirisfal tun?",a="Euer Ziel ist es, den Verlassenen dabei zu helfen, ihren brüchigen Halt über die verseuchten Herzlande von Lordaeron zu sichern. Von den Krypten von Todesend in Richtung Brill müsst Ihr die gedankenlose Geißel ausmerzen, die verlassene Bauernhöfe heimsucht, die fanatischen Eiferer des The Scarlet Crusade ausschalten, die aus dem Norden vordringen, und die verseuchten Bestien ausdünnen, die durch die verrottenden Wälder streifen. Dies beweist Euren Wert für Fürstin Sylvanas und bereitet Euch darauf vor, ihrem wachsenden Königreich unter den Ruinen von Capital City zu dienen.",al={"was soll ich hier tun","warum bin ich in tirisfal","was ist mein ziel hier"}}},fp="15,338,18.442.0,19.456.0,26.372.0,42.269.0,65.287.0,53.289.0,39.222.0,53.244.0,53.247.0"}
P.entries["zone:undercity"] = {n="Unterstadt",s="Unter den zerschlagenen Ruinen der Hauptstadt Lordaerons liegt Unterstadt, die dunkle Festung der Verlassenen. Fürstin Sylvanas Windläufer entriss sie der Geißel und machte sie zu einem Zufluchtsort, den kein Feind durchdringen kann. Heute ist sie der Sitz der Macht der Verlassenen. Und sie ist die große Bastion der Horde im Norden der Östlichen Königreiche.",h="Unter den zerschlagenen Ruinen der Hauptstadt Lordaerons liegt Unterstadt, die dunkle Festung der Verlassenen.",kw={"das apothekarium","arthas","verlassene","lordaeron","geißel","sylvanas","terenas","tirisfal","unterstadt","varimathras"},ang={["faction:Horde"]="Als wichtigster Stützpunkt der Horde in den Östlichen Königreichen sichert Unterstadt Zeppelinstrecken direkt nach Durotar und zum Basislager Grom'gol.",["race:Human"]="Unter dem Boden Eures gefallenen Stammesreiches liegt eine düstere Verkehrung der königlichen Krypten Lordaerons, bevölkert von den wandelnden Leichen Eurer einstigen Brüder.",["race:Orc"]="Tief in eben diesen Kerkern war einst der legendäre Kriegshäuptling Orgrim Schicksalshammer von der Allianz von Lordaeron eingekerkert, bevor ihm seine geschichtsträchtige Flucht gelang.",["race:Undead"]="Unterstadt ist Euer eigenes Herrschaftsgebiet und Eure Heimat, von Euch selbst ausgehoben, nachdem Ihr Euch aus dem eisernen Griff des Lichkönigs befreit habt."},sec={{t="Von königlichen Krypten zur Geißelfestung",b="Lange vor der Seuche nannte man die Katakomben und Abwasserkanäle unter dem Palast bereits Unterstadt. Dort lagen Adlige begraben, neben den ärmsten Menschen des Reiches. Auch die tiefsten Kerker des Königreichs befanden sich dort. Selbst Orgrim Schicksalshammer, der ehemalige Kriegshäuptling, wurde dort gefangen gehalten, bevor er entkam.\n\nIm Dritten Krieg ermordete Arthas Menethil König Terenas und verwüstete die Hauptstadt. Dann ließ der Prinz seine untoten Diener graben. Sie erweiterten die alten Gänge zu einem befestigten Herrschaftssitz der Geißel. Doch die Geißel erlebte die Vollendung ihrer dunklen Hauptstadt nie."},{t="Der Aufstieg der Verlassenen",b="Als die Macht des Lichkönigs schwand, befreite sich Fürstin Sylvanas Windläufer von seinem Willen und nahm Tausende Untote mit sich. Sie überfiel Arthas aus dem Hinterhalt, und er floh nach Nordend zurück. Es folgte ein erbitterter Bürgerkrieg gegen die Überreste der Geißel, die Schreckenslords und den menschlichen Widerstand. Daraus ging Sylvanas mit den halbfertigen Katakomben hervor. Sie nannte ihr Volk die Verlassenen und beaufsichtigte jahrelange Arbeiten an der weitläufigen Stadt."},{t="Die Architektur der Verdammten",b="Die Stadt erstreckt sich in Ringen um das Handwerksviertel, und gewaltige Aufzüge verbinden sie mit den Palastruinen darüber. Ringsum liegen die anderen Viertel, darunter das giftige Apothekarium. Dort braut die Königliche Apothekervereinigung hochwirksame Seuchen, neben Kanälen voller grünen Schleims. Noch tiefer hält die Bansheekönigin im Königsviertel Hof, gemeinsam mit ihrem Schreckenslord-Kommandanten Varimathras. Legionen turmhoher Monstrositäten halten Wache."}},faq={{q="Was war Unterstadt, bevor die Untoten sie übernahmen?",a="Unter dem Palast von Lordaeron lagen die uralten Krypten der menschlichen Könige, dazu der Kerkerkomplex und das weitläufige Abwassernetz der Stadt. Dort waren Kriegsgefangene wie Orgrim Schicksalshammer untergebracht, ebenso mittellose Bürger, die in den unterirdischen Schatten lebten. Die Kerker unter dem Palast nannte man bereits Unterstadt. Nachdem Prinz Arthas die Hauptstadt geplündert hatte, begann er, diese Katakomben in eine Festung der Geißel zu verwandeln, bevor Sylvanas sie einnahm.",al={"ursprünge unterstadts","was war unterstadt ursprünglich","geschichte der kanalisation lordaerons"}},{q="Warum wurde die Stadt unterirdisch statt an der Oberfläche gebaut?",a="Die oberirdische Stadt Lordaeron wurde im Dritten Krieg völlig zerstört. Dadurch ließ sie sich nur schwer gegen den Scharlachroten Kreuzzug, die Streitkräfte der Geißel und überlebende Mitglieder der Allianz verteidigen. Die unterirdischen Tunnel boten natürlichen Schutz, Engpässe und Verborgenheit. So konnten die Verlassenen den ursprünglichen Bau der Geißel vollenden und unbemerkt gedeihen.",al={"warum unterirdisch leben","warum lordaeron nicht wiederaufbauen","warum unterstadt unter den ruinen liegt"}},{q="Wer herrscht über Unterstadt?",a="Die Stadt wird von Fürstin Sylvanas Windläufer beherrscht, der Bansheekönigin und Königin der Verlassenen. Sie regiert vom Königsviertel aus, bewacht von königlichen Wachen der Verlassenen und ihrem unterworfenen Schreckenslord-Leutnant Varimathras. Sylvanas befreite sich nach der Schlacht um Hyjal vom Willen des Lichkönigs. Die Stadt hat außerdem ein Kriegsviertel, ein Schurkenviertel und ein Magieviertel.",al={"wer ist der anführer von unterstadt","herrscher von unterstadt","wer regiert unterstadt"}},{q="Was ist das Denkmal für König Terenas in den Ruinen darüber?",a="Über den Hauptaufzügen der Stadt steht ein steinernes Denkmal für den ermordeten König Terenas Menethil II. Sein Leichnam liegt nicht darin, denn er wurde verbrannt und seine Asche während der Wiedererweckung von Kel'Thuzad verstreut. Überlebende Menschen der Allianz meißelten das Denkmal mutig inmitten der Ruinen, damit die Erinnerung an Lordaerons letzten wahren König fortbesteht.",al={"grab von könig terenas","grab im thronsaal von lordaeron","wer baute das grabmal über unterstadt"}},{q="Was sind die seltsamen Geräusche im Thronsaal von Lordaeron?",a="Im zerstörten Thronsaal über den Aufzügen von Unterstadt hallen die Echos der Vergangenheit noch immer nach. Besucher, die in der Mitte stehen, können leise geisterhafte Klänge hören: die Jubelglocken und Rosenblätter bei Arthas' Rückkehr, die warnenden Worte des Propheten Medivh und das letzte Gespräch zwischen König Terenas und seinem vatermörderischen Sohn.",al={"geistergeräusche im thronsaal","flüstern im thronsaal","stimmen im thronsaal von lordaeron"}},{q="Warum lassen die Verlassenen andere Mitglieder der Horde hierher?",a="Die Verlassenen schlossen sich aus Überlebensgründen mit der Horde des Kriegshäuptlings Thrall zusammen, denn sie sind von feindseligen Scharlachroten Fanatikern und Legionen der Geißel umzingelt. Die giftigen Dämpfe und alchemistischen Flüsse sind für die lebenden Völker der Horde erstickend, doch Abgesandte und Reisende dürfen die Stadt betreten, um diplomatische und militärische Verbindungen zu stärken.",al={"warum sind orcs in unterstadt","horde in unterstadt","warum gehört unterstadt zur horde"}}},fx={a590d153={q="Was ist die Unterstadt?",a="Die Unterstadt ist die unterirdische Hauptstadt der Verlassenen, die direkt unter den zerstörten Ruinen der Hauptstadt in Tirisfal erbaut wurde. Sie wurde aus alten königlichen Krypten, Abwasserkanälen und Katakomben herausgehauen und von Prinz Arthas als Festung der Geißel ausgebaut, bevor Fürstin Sylvanas Windläufer und ihre abtrünnigen Untoten sie während des Bürgerkriegs einnahmen. Heute dient sie als befestigter Zufluchtsort für Untote mit freiem Willen, durchzogen von giftigem Schlamm und wachsam bewacht gegen alle lebenden Eindringlinge.",al={"was ist die unterstadt","erzähl mir von der unterstadt","unterstadt hintergrundgeschichte"}},c51b16b2={q="Was geschah mit dem alten König von Lordaeron?",a="König Terenas Menethil II. wurde im Thronsaal direkt über dieser Stadt von seinem eigenen Sohn, Prinz Arthas, ermordet. Nachdem er aus Nordend zurückgekehrt war, verdorben durch die Runenklinge Frostgram, erschlug Arthas seinen Vater und ließ die Geißel über das Königreich hereinbrechen. Terenas' Asche wurde später vom Todesritter gestohlen, um Kel'Thuzad wiederzubeleben, wobei nur der Gedenkstein und die getrocknete Blutspur zurückblieben, die Ihr noch immer in der Nähe des zerstörten Throns sehen könnt.",al={"schicksal von könig terenas","was geschah mit könig terenas","wer tötete könig terenas"}},c11144c7={q="Wer war Arthas?",a="Arthas Menethil war der Kronprinz von Lordaeron und ein berühmter Paladin der Silbernen Hand. In seinem verzweifelten Versuch, die Plage des Untodes, die seine Heimat überrollte, aufzuhalten, wurde sein Kreuzzug rücksichtslos und fanatisch. In Nordend bemächtigte er sich der verfluchten Runenklinge Frostgram, die seine Seele verschlang und ihn zum schrecklichen Champion des Lichkönigs machte. Er kehrte nur nach Hause zurück, um seinen Vater abzuschlachten, Lordaeron dem Erdboden gleichzumachen und schließlich nach Norden zurückzukehren, um mit dem Frostthron zu verschmelzen.",al={"wer ist arthas","prinz arthas hintergrund","arthas menethil"}},["7f6bbd49"]={q="Wer ist Sylvanas Windläufer?",a="Fürstin Sylvanas Windläufer war einst die tapfere Waldläufergeneral von Silbermond, die Quel'Thalas während des Dritten Krieges gegen die Geißel verteidigte. Als sie fiel, riss Arthas ihre Seele aus ihrem Körper und verwandelte sie in eine Banshee, um sie zu quälen. Als der Griff des Lichkönigs schwächer wurde, brach sie frei, nahm ihre körperliche Form zurück und scharte andere unabhängige Untote um sich, die Verlassenen. Jetzt regiert sie als ihre Bansheekönigin vom Königsviertel aus.",al={"wer ist die bansheekönigin","sylvanas hintergrund","wer ist sylvanas"}},["2a8de90f"]={q="Warum wird Sylvanas die Dunkle Fürstin genannt?",a="Die Verlassenen ehren Sylvanas als die Dunkle Fürstin, weil sie sie aus der sinnlosen Knechtschaft des Lichkönigs befreit und ihnen Zuflucht gewährt hat, als der Rest von Azeroth nach ihrer totalen Ausrottung strebte. Der Beiname wird neben ihrem Titel als Bansheekönigin verehrt und spiegelt sowohl ihre schattenhafte Meisterschaft über den Tod als auch die wilde, unnachgiebige Hingabe ihrer untoten Untertanen wider.",al={"warum dunkle fürstin","titel dunkle fürstin sylvanas","bedeutung dunkle fürstin"}},["84f18f47"]={q="Warum sind die Verlassenen Teil der Horde?",a="Umgeben von feindseligen Scharlachroten Kreuzzüglern, der unerbittlichen Geißel und rachsüchtigen Überresten der Allianz, konnten die Verlassenen in Lordaeron nicht allein überleben. Fürstin Sylvanas nahm über das Meer Kontakt mit Kriegshäuptling Thrall auf und schmiedete ein pragmatisches Zweckbündnis. Die Horde gewann einen entscheidenden militärischen Stützpunkt in den Östlichen Königreichen, während die Verlassenen wesentliche Verstärkungen und politische Legitimität in ihrem Überlebenskampf sicherten.",al={"warum sind die verlassenen bei der horde","untote treten der horde bei","verlassene horde allianz"}},["71200045"]={q="Was ist die Geißel und sind sie noch in der Nähe?",a="Die Geißel ist die riesige, gefräßige Armee aus sinnlosen Untoten, die von der Brennenden Legion erschaffen wurde und vom Lichkönig aus Nordend regiert wird. Obwohl die Verlassenen die Unterstadt und Tirisfal ihrem Griff entrissen haben, bleibt die Geißel eine unmittelbare, tödliche Gefahr. Ihre Legionen unter dem Kommando von Kel'Thuzad ersticken noch immer die nahegelegenen Pestländer und befallen verlassene Gehöfte und Krypten in Tirisfal.",al={"ist die geißel in der nähe","was ist die geißel","geißel in lordaeron"}},["501548ab"]={q="Wo ist der Lichkönig jetzt?",a="Der Lichkönig residiert auf dem Frostthron in den fernen, eisigen Einöden von Nordend. Nach dem Bürgerkrieg in den Pestländern floh Prinz Arthas aus Lordaeron, um seinen schwächer werdenden Meister zu beschützen. Er bestieg den Gletscher und verschmolz ihre Essenzen zu einer einzigen schrecklichen Entität. Von dieser arktischen Bastion aus wacht sein eisiger Blick noch immer über Azeroth.",al={"wo ist der lichkönig","standort des lichkönigs","wo ist arthas jetzt"}},["4cc7f971"]={q="Wer ist der Scharlachrote Kreuzzug?",a="Der Scharlachrote Kreuzzug ist ein fanatischer Orden menschlicher Eiferer, der aus den Ruinen der Verteidigung von Lordaeron hervorgegangen ist. Geblendet von ihrem rechtschaffenen Hass auf die Untoten, unterscheiden sie nicht zwischen der sinnlosen Geißel und den Verlassenen mit freiem Willen. Sie betrachten jeden, der vom Untod gezeichnet ist – sowie jeden lebenden Außenseiter, der sie toleriert – als abscheuliche Kreaturen, die nur auf den Scheiterhaufen gehören. Ihre Hauptbastion in Tirisfal ist das Scharlachrote Kloster.",al={"wer ist der scharlachrote kreuzzug","scharlachrote kreuzzügler","scharlachroter kreuzzug hintergrund"}},["271820ed"]={q="Ist die Unterstadt gefährlich?",a="Sie ist außerordentlich gefährlich, besonders für Lebende. Kanäle mit rohen alchemistischen Abfällen und giftigem Schlamm durchziehen die Straßen der Stadt und füllen die höhlenartigen Hallen mit giftigen Dämpfen, die das Atmen für Besucher aus Fleisch und Blut gefährlich machen. Unter den gepflasterten Vierteln liegen verseuchte Abwasserkanäle, und noch tiefer finden geheime Experimente statt, bei denen täglich dunkle Alchemie und rücksichtslose Attentate geplant werden.",al={"ist die unterstadt sicher","gefahr in der unterstadt","gefahren in der unterstadt"}},["2539a3c3"]={q="Wie bin ich in der Unterstadt gelandet?",a="Als ein Verlassener führte Euer Weg Euch natürlich hierher, nachdem Ihr in Todesend aus dem Tod erwacht seid und Eure Loyalität in Tirisfal bewiesen habt, indem Ihr den Straßen vorbei an Brill gefolgt seid, um unter die zerstörten Ruinen der Hauptstadt hinabzusteigen. Wenn Ihr aus Kalimdor oder fernen Ländern stammt, seid Ihr wahrscheinlich an Bord eines Zeppelins der Horde angekommen, der an den Türmen direkt außerhalb der Hauptstadt anlegt, oder Ihr seid durch die verheerte Landschaft gewandert. Die Unterstadt ist der wichtigste Stützpunkt der Horde im nördlichen Lordaeron und bietet Schutz und Bestimmung unter den alten Palastkatakomben.",al={"wie bin ich hierher gekommen","wie erreiche ich die unterstadt","wie kommt man in die unterstadt"}},b63c4cf2={q="Was soll ich in der Unterstadt tun?",a="Ihr seid hier, um die Verlassenen zu unterstützen und die Stärke der Horde gegen die Gefahren zu versammeln, die Lordaeron umgeben. Innerhalb der konzentrischen Viertel der Stadt könnt Ihr Klassenlehrer aufsuchen, Vorräte erwerben und die dunklen Forscher der Royal Apothecary Society konsultieren. Jenseits Eures Handwerks ist es Eure Pflicht, Aufträge für Fürstin Sylvanas Windläufer und ihre Leutnants anzunehmen. Die Verlassenen führen einen Krieg an mehreren Fronten: die Überreste der sinnlosen Geißel säubern, den fanatischen Scharlachroten Kreuzzug zurückschlagen und sicheren Boden für die Untoten mit freiem Willen sichern, damit sie überdauern können.",al={"was mache ich hier","was soll ich in der unterstadt tun","warum bin ich hier"}}},fp="9,318,36.556.0,20.416.0,26.421.0,54.450.0,60.340.0,24.362.0,51.333.0,57.328.0,51.322.0"}
P.entries["zone:ungoro"] = {n="Krater von Un'Goro",s="Der Krater von Un'Goro lockt Reisende in ein üppiges Becken zwischen den Wüsten von Tanaris und Silithus. Unter einem zentralen Vulkan streifen Dinosaurier zwischen lebenden Elementaren und uralten Titanenrelikten umher. Über das Becken verstreut liegen farbige Machtkristalle, deren Ursprung ein Rätsel bleibt.",h="Der Krater von Un'Goro lockt Reisende in ein üppiges Becken zwischen den Wüsten von Tanaris und Silithus.",kw={"teufelssaurier","feuersäulengrat","götterländer","lakkari","marschalls zuflucht","machtkristalle","torwa pfadfinder","ungoro","krater von ungoro"},ang={["class:Druid"]="Als Druide könnt Ihr mit dem Zirkel des Cenarius Un'Goros abgeschiedenes Ökosystem erforschen und seine reiche Erde ernten, um Morgenkorn anzubauen. Der Zirkel will die reine, ungezähmte Lebenskraft verstehen, die die Caldera erhält.",["faction:Alliance"]="Als Naturforscher der Allianz könnt Ihr Euch in Marschalls Zuflucht mit Williden Marschall und J.D. Collie zusammentun. Naturforscher der Allianz wetteifern darum, die Titanenpylonen zu entschlüsseln und dabei die Forscher aus Darnassus zu schützen, die Bodenproben sammeln.",["faction:Horde"]="Als Abenteurer der Horde könnt Ihr durch Tanaris kommen, um Euch mit legendären Teufelssauriern zu messen. Ihr könnt auch den Kräuterkundigen aus Donnerfels helfen, aus Un'Goros urzeitlicher Erde Morgenkorn zu ziehen.",["profession:Herbalism"]="Dank der reichlichen Feuchtigkeit des Beckens gedeihen dort neben Feuerblüten an den Vulkanhängen auch Blindkraut, Traumblatt und Goldener Sansam. Nur an wenigen Orten in Kalimdor wachsen alle vier zusammen.",["profession:Mining"]="Mithrilvorkommen und reichhaltige Thoriumadern liegen dicht gedrängt an den Kraterwänden und den Felsklippen des Feuersäulengrats. Un'Goro ist ein herausragendes Ziel für hochwertige Erze."},sec={{t="Die Götterländer",b="Uralte Aufzeichnungen der Nachtelfen über den Krieg der Sandstürme berichten, dass die Qiraji am Rand des Kraters von Un'Goro zurückgeschlagen wurden. In ihrer Sprache nannten sie diesen Ort die „Götterländer“. Gelehrte vermuten, dass die Titanen die Caldera während der Formung Kalimdors als Testgelände oder Wohnstätte nutzten. An den Graten ragen steinerne Pylonen auf, die vor Energie summen. Blaue, rote, grüne und gelbe Kristalle treten aus der Urerde hervor."},{t="Ein wildes Ökosystem",b="Un'Goro hat keine Städte, Dörfer oder einheimischen humanoiden Gesellschaften. Hier gedeiht das Leben in einem wilden, urzeitlichen Zustand. Teufelssaurier durchstreifen die Ebenen der Terrorflucht, Blutblüten schlagen in den Marschen um sich, und Schleime kriechen über die Teergruben von Lakkari. Im Herzen des Kraters liegt der Feuersäulengrat, ein aktiver Vulkan voller feindseliger Feuerelementare, angeführt von Feuerläufer. Entdecker und Kürschner suchen nach seinen natürlichen Schätzen, darunter Teufelssaurierhäute, sofern sie die Nahrungskette überleben."},{t="Marschalls Zuflucht",b="Marschalls Zuflucht, ein erhöhtes Lager in den nördlichen Klippen, ist fast die gesamte besiedelte Präsenz in Un'Goro. Williden Marschall führte Wissenschaftler, Naturforscher und Glückssucher hierher, um die Schätze des Beckens zu katalogisieren.\n\nMonströse Wildtiere setzten der Expedition zu und trieben ihre Mitglieder auf höher gelegenes Gelände. Die Zuflucht bleibt ein umkämpfter Stützpunkt für Reisende, die die geheimnisvollen Machtkristalle erforschen, vulkanische Aktivität kartieren und beobachten, wie Silithidenschwärme über die südlichen Grate vordringen."}},faq={{q="Wie gelangt man in den Krater von Un'Goro?",a="Natürliche Rampen führen die Kraterwände hinab. Eine kommt aus dem Südwesten von Tanaris nahe dem Disteltal, eine weitere aus dem Nordosten von Silithus. Ohne magische Hilfe ist ein Sprung von den Klippen tödlich. Marschalls Zuflucht im Norden bietet Flugverbindungen nach Gadgetzan und zur Burg Cenarius.",al={"wie gelangt man nach ungoro","eingang nach ungoro","wie erreicht man den krater von ungoro"}},{q="Wozu dienen die farbigen Machtkristalle?",a="Rote, blaue, grüne und gelbe Machtkristalle liegen verstreut auf dem Dschungelboden. Die Gnom-Forscherin J.D. Collie in Marschalls Zuflucht kann Entdeckern erklären, wie sie an den nördlichen, östlichen und westlichen Pylonen verwendet werden. Kombiniert bestimmte Farben an den richtigen Pylonen, um schlummernde Titanenenergien zu nutzen und schützende oder heilende Talismane herzustellen.",al={"ungoro-kristalle","rote blaue grüne gelbe kristalle in ungoro","machtpylonen"}},{q="Warum ist Un'Goro üppig bewachsen, obwohl es von Wüsten umgeben ist?",a="Gelehrte glauben, die Titanen, die die Welt formten, hätten Un'Goros unnatürliche Üppigkeit geschaffen. Titanische Leitungen, die Wärme des Feuersäulengrats und uralte Leyenergie nähren sein abgeschiedenes, schnell wachsendes Ökosystem. Es trotzt den trockenen Bedingungen des benachbarten Tanaris und Silithus.",al={"warum ist ungoro ein dschungel","ungoro und die wüste","wie gibt es in ungoro pflanzen"}},{q="Warum nannten die Qiraji diesen Ort die „Götterländer“?",a="Übersetzte Tafeln über den Krieg der Sandstürme berichten, dass die Insektenschwärme an Un'Goros Grenze haltmachten. In ihrer Sprache nannten sie den Ort die „Götterländer“. Der Geologe Larksbane, der den Bericht übersetzte, bringt den Namen mit Theorien in Verbindung, nach denen die Titanen einst im Krater lebten, und fragt sich, ob Aman'Thul selbst über ihn wachte.",al={"bedeutung der götterländer","qiraji in ungoro","warum konnten die silithiden ungoro nicht einnehmen"}},{q="Wozu wird Un'Goro-Erde verwendet?",a="Über das Kraterbecken verteilt liegt reiche, kraftvolle Erde. Kombiniert geerntete Erde in einem Immergrünbeutel mit Tharlendris-Samen, um Morgenkorn anzubauen, ein mystisches Kraut, das bei Forschern in Donnerfels, Darnassus und dem Zirkel des Cenarius heiß begehrt ist.",al={"bodenprobe aus ungoro","wozu dient ungoro-erde","morgenkorn und erde"}},{q="Gibt es hier humanoide Siedlungen oder Dungeons?",a="Im Krater von Un'Goro liegt Die Terrasse des Formers, für jene um Stufe achtundfünfzig bis sechzig, aber es gibt keine einheimischen humanoiden Gesellschaften. Marschalls Zuflucht, ein kleiner Expeditionsaußenposten am nördlichen Rand, ist die einzige dauerhafte Siedlung. Abgesehen von vereinzelten Einsiedlerjägern oder verirrten Entdeckern ist die Caldera völlig wild.",al={"dungeons in ungoro","wer lebt in ungoro","humanoide in ungoro"}}},fp="14,269,13.410.0,18.462.0,16.490.0,35.282.0,45.336.0,56.270.0,51.330.0,30.235.0,52.287.0"}
P.entries["zone:wailing"] = {n="Die Höhlen des Wehklagens",s="Unter der Blühenden Oase im Brachland pfeift eingeschlossener Dampf durch Die Höhlen des Wehklagens. Quellen und Spalten sollten einst Kalimdors sonnengebleichte Savanne wiederbeleben. Heute bergen die Höhlen vergiftete Wasser, verdrehte Tiere und gefallene Jünger, gefangen in einem unnatürlichen Albtraum.",h="Unter der Blühenden Oase im Brachland pfeift eingeschlossener Dampf durch Die Höhlen des Wehklagens.",kw={"deviate","druiden des giftzahns","smaragdgrüner alptraum","lady anakondra","lord kobrahn","lord pythas","lord serpentis","die blühende oase","mutanus","naralex","verdan"},ang={["class:Druid"]="Für Druiden der Tradition des Zirkels des Cenarius wie auch für Tauren-Druiden sind die Höhlen eine tragische Warnung vor den Gefahren im Smaragdgrünen Traum. Ihre gefallenen Brüder, die Druiden des Giftzahns, zu läutern, ist eine ernste Pflicht.",["race:NightElf"]="Naralex wurde unter den Nachtelfen-Druiden verehrt. Seine Verderbnis durch den Smaragdgrünen Alptraum ist eine schmerzliche Katastrophe für sein Volk jenseits des Meeres.",["race:Tauren"]="Die verdrehten Wasser bedrohen die empfindlichen Oasen, die das Leben im ganzen Brachland erhalten. Die Quellen zu reinigen, ist für die Stämme von Mulgore und dem Wegekreuz lebenswichtig."},sec={{t="Eine edle Vision wird vergiftet",b="Der Nachtelfen-Druide Naralex entdeckte ein gewaltiges unterirdisches Wassersystem und wollte das Brachland wiederherstellen. Durch einen Kanal in den Smaragdgrünen Traum wollte er reines, urtümliches Leben durch die Quellen leiten und die ausgedörrte Savanne in ein blühendes Paradies verwandeln.\n\nTief in den Höhlen trat Naralex in Zwiesprache mit dem Traum, verankert durch seine treuen Akolythen. Doch sein schlafender Geist berührte den Smaragdgrünen Alptraum. Die Verderbnis ergriff ihn, und sein Kanal wurde zu einem Ventil, das Gift und Wahnsinn in die Wasser ergoss."},{t="Die Druiden des Giftzahns",b="Als sich die dunkle Energie des Alptraums von Naralex' hilfloser Gestalt ausbreitete, verfielen die Gedanken seiner Schüler dem Wahnsinn. Sie entsagten der friedvollen Weisheit des Zirkels des Cenarius und wurden zu den fanatischen Druiden des Giftzahns.\n\nIhre Anführer, Lady Anakondra, Lord Kobrahn, Lord Pythas und Lord Serpentis, nehmen reptilienartige Gestalten an. Sie nehmen die giftige Mutation der Höhlen an, statt sie zu bekämpfen, und schirmen ihren schlafenden Meister vor Einmischung von außen ab. Sie glauben, dieses verdrehte Wachstum sei die wahre Entwicklung der Natur."},{t="Der Alptraum wird Fleisch",b="Den Griff der Druiden des Giftzahns zu brechen, rettet Naralex nicht. Am Dreamer's Rock beginnen seine verbliebenen, unverdorbenen Jünger ein Ritual, um ihn sanft aus seiner Trance zu wecken. Sein schlafender Geist windet sich, und sein tiefster Schrecken bricht als Mutanus der Verschlinger hervor, ein monströser, entstellter Murloc. Mutanus ist das Fleisch gewordene Abbild von Naralex' schlimmsten Alpträumen.\n\nNur wenn Mutanus erschlagen wird, lässt sich der Kanal zum Alptraum kappen. Naralex kann erwachen, die Gestalt eines Vogels annehmen und aus den verdorbenen Höhlen fliegen."}},faq={{q="Warum heißen sie Die Höhlen des Wehklagens?",a="Die Höhlen des Wehklagens verdanken ihren Namen den klagenden Rufen, die durch ihre Tunnel hallen. Eingeschlossener unterirdischer Dampf und Windstöße unter hohem Druck zwängen sich durch enge Kalksteinspalten und erzeugen das unheimliche Pfeifen.",al={"warum heißen sie höhlen des wehklagens","ursprung des namens","warum klagen sie"}},{q="Was ließ die Tiere dort zu „Deviates“ werden?",a="Als Naralex dem Einfluss des Smaragdgrünen Alptraums verfiel, strömten verdorbene Traumenergien in die unterirdischen Quellen. Das verunreinigte Wasser verwandelte die dort lebenden Raptoren, Krokilisken und Schlangen in unnatürliche Deviates.",al={"deviate verderbnis","warum mutieren raptoren","ursprung der deviate tiere"}},{q="Wer sind die Druiden des Giftzahns?",a="Die Druiden des Giftzahns waren einst Naralex' ergebene Akolythen, Nachtelfen und Tauren. Der Alptraum verdarb sie zusammen mit ihm, zerschmetterte ihren Geist und ließ sie Schlangen und Gift verehren. Sie nahmen Titel wie Kobrahn, Pythas und Anakondra an.",al={"giftzahndruiden","geschichte der druide des giftzahns","wer ist lord serpentis"}},{q="Warum ist der Endgegner ein riesiger Murloc namens Mutanus?",a="Mutanus erscheint während des Versuchs, Naralex zu erwecken. Das Ritual offenbart Mutanus' Wesen und seine Verbindung zum schlafenden Druiden.",al={"warum ist mutanus ein murloc","was ist mutanus","geschichte des endgegners"}},{q="Was geschieht, nachdem Mutanus besiegt wurde?",a="Der Versuch der Jünger, Naralex zu erwecken, geht nach der Konfrontation weiter. Am Ende offenbart das Ritual das Schicksal des Druiden.",al={"naralex erwecken","naralex ende","was geschieht mit naralex"}},{q="Wer lebt in der Höhle über dem Eingang?",a="Getreue des Zirkels des Cenarius, darunter Nalpak und Ebru, leben in der schädelartigen Felshöhle über dem Eingang. Sie suchen tapfere Reisende, die Deviatbälge sammeln und die Verderbnis reinigen, bevor sie das Brachland verschlingt.",al={"höhle über dem eingang","npcs in schlangen-schädelhöhle","wer sind nalpak und ebru"}}},fx={["38e519c2"]={q="Warum macht sich jeder solche Sorgen um diesen Ort?",a="Die unterirdischen Quellen in den Höhlen speisen die primären Oasen, die das Leben im ariden Brachland erhalten. Sollte der Makel des Smaragdgrünen Traums ungehindert in diese Wasserwege sickern, könnten sich die verdrehten Mutationen und der Wahnsinn, die die Flora und Fauna der Höhlen korrumpieren, über die gesamte Region ausbreiten und das Land in einen Albtraum bei Tageslicht verwandeln.",al={"warum sorgen um die höhlen des wehklagens","die höhlen des wehklagens bedrohung für das brachland","wie schlimm sind die höhlen des wehklagens"}},["81917ac6"]={q="Wie bin ich in den Höhlen des Wehklagens gelandet?",a="Ihr seid vom Wegekreuz nach Süden in Die blühende Oase gereist, den Berichten über bizarre Bestien und korrumpiertes Wasser folgend, das durch das Brachland sickerte. Hinter dem üppigen Blattwerk und den Lagern der Kolkar-Zentauren liegt eine gewaltige, schädelförmige Höhle, die in den Fels gehauen wurde. Angelockt durch Hilferufe aus Donnerfels, durch Goblins aus Ratschet, die nach seltsamen Essenzen suchten, oder durch Jünger, die im Auge des Schädels oben kampierten, seid Ihr an den gewundenen Spalten und dem Zischen unterirdischer Geysire vorbei in die stöhnenden Tiefen hinabgestiegen.",al={"wie bin ich hierher gekommen","wie erreiche ich die höhlen des wehklagens","woher bin ich hierher gekommen"}},["28a012f3"]={q="Was soll ich in den Höhlen des Wehklagens tun?",a="Ihr seid hier, um die Korruption zu tilgen, die diese unterirdische Quelle befallen hat. Der Nachtelf-Druide Naralex fiel in einen albtraumhaften Schlaf, als er versuchte, das Brachland wiederzubeleben, was die Kreaturen darin verdrehte und seine Jünger in die giftigen Druiden des Giftzahns verwandelte. Ihr müsst die vier Giftzahnfürsten – Lady Anakondra, Lord Kobrahn, Lord Pythas und Lord Serpentis – zur Strecke bringen, um ihren Griff zu brechen, und dann den verbliebenen Jüngern helfen, Naralex zu wecken, bevor sein fiebriger Albtraum die Oase vollständig verschlingt.",al={"was ist mein ziel hier","warum bin ich in den höhlen des wehklagens","was mache ich hier unten"}},["3386ab3f"]={q="Was sind Die Höhlen des Wehklagens?",a="Die Höhlen des Wehklagens sind ein weitläufiges unterirdisches Höhlensystem, das unter dem trockenen Brachland, nahe der blühenden Oase, verläuft. Seine natürlichen unterirdischen Quellen leiten Wasser kilometerweit unter der Erde und speisen die seltenen Oasen an der Oberfläche, die über die Region verstreut sind. Entdeckt von dem Nachtelf-Druiden Naralex, sollten sie das Herz eines großen Projekts zur natürlichen Regeneration werden. Stattdessen wurden sie zu einem Epizentrum gefährlicher Verderbnis, nachdem eine tragische Katastrophe die Druiden darin ergriffen hatte.",al={"was sind die höhlen des wehklagens","übersicht der höhlen des wehklagens","über die höhlen des wehklagens"}},e070a543={q="Wer lebt dort unten?",a="Die Höhlen wimmeln von unnatürlicher Tierwelt und abtrünnigen Druiden. Naralex' korrumpierte Anhänger, die Leaders of the Fang, haben die Tunnel zusammen mit mutierten Schlangen, Schlämmen, Raptoren und Krokilisken als ihr Gebiet beansprucht. Außerhalb des Instanzeingangs lauern wilde Bestien, Schlämme und sogar Ausgestoßene in den feuchten Gängen, während die korrumpierten Druiden die inneren Kammern bewachen und ihren schlafenden Meister beschützen.",al={"wer ist in den höhlen des wehklagens","kreaturen in den höhlen des wehklagens","bewohner der höhlen des wehklagens"}},["49d47201"]={q="Warum hat mich die Horde hierher geschickt?",a="Die seltsamen Mutationen der einheimischen Bestien und die faulen Energien, die aus der blühenden Oase sprudeln, bedrohen das gesamte Brachland. Die Horde und die Cenarion-Druiden von Donnerfels können es nicht dulden, dass eine unkontrollierte dunkle Macht das Land und die Wasserwege direkt vor der Haustür des Wegekreuzes vergiftet. Ihr wurdet ausgesandt, um Nachforschungen anzustellen, den abtrünnigen Leaders of the Fang ein Ende zu bereiten und dabei zu helfen, die wachsende Gefahr zu unterdrücken.",al={"warum bin ich in den höhlen des wehklagens","mission der horde in den höhlen des wehklagens","warum hat man mich in die höhlen des wehklagens geschickt"}},d445bb78={q="Ist das Teil eines größeren Problems im Brachland?",a="Ja. Die unterirdischen Kanäle unter diesen Höhlen speisen die Oasen an der Oberfläche im gesamten Brachland. Die Verderbnis des Alptraums, die das Wasser in den Höhlen korrumpiert, hat begonnen, in die umliegende Landschaft überzulaufen, was dazu führt, dass wilde Kreaturen wie Raptoren und Krokilisken mutieren und die blühende Oase in eine Brutstätte für seltsames Deviatleben verwandelt.",al={"problem mit den oasen im brachland","deviatverderbnis im brachland","beeinflussen die höhlen des wehklagens das brachland"}},["038fd1cf"]={q="Breiten sich die Deviatwesen außerhalb der Höhlen aus?",a="Das tun sie bereits. Die unterirdischen Quellen fließen direkt in oberirdische Oasen wie die blühende Oase und bringen unnatürliches Wachstum und mutierte Kreaturen in die offene Savanne. Seltsame Kreaturen wie Deviatfisch können aus den Gewässern außerhalb gefischt werden, und aggressive mutierte Raubtiere belästigen zunehmend Reisende zwischen den Oasen und dem Wegekreuz.",al={"breiten sich die deviatwesen aus","deviatbestien im brachland","deviatfisch außerhalb"}},["8502642f"]={q="Wer hat hier das Sagen?",a="Während Naralex tief in den Höhlen in seinem korrumpierten Schlummer gefangen liegt, gehört die tägliche Herrschaft über die Höhlen den Druiden des Giftzahns. Sie werden von Lord Serpentis angeführt, einst Naralex' bester Schüler, der seine verdrehten Brüder versammelte, um das Land in ihr eigenes verzerrtes Paradies zu verwandeln, zusammen mit anderen fang lords wie Cobrahn, Pythas und Lady Anakondra.",al={"wer führt die höhlen des wehklagens","anführer der höhlen des wehklagens","boss der höhlen des wehklagens"}},["32be29c8"]={q="Was ist der Smaragdgrüne Traum und wie hängt er mit dieser Höhle zusammen?",a="Der Smaragdgrüne Traum ist ein riesiges Geisterreich, das Azeroth unberührt und wild darstellt, von dem grünen Drachenschwarm behütet und für Druiden zugänglich. Naralex glaubte, er könne die reinen, wiederherstellenden Energien des Traums in die unterirdischen Aquifere der Höhlen des Wehklagens leiten, um üppiges Pflanzenleben im Brachland wiederherzustellen. Als er ihn jedoch anzapfte, wurde er vom Smaragdgrünen Alptraum gefangen genommen, was eine verdrehte Version der Natur in die physischen Höhlen projizierte.",al={"verbindung zum smaragdgrünen traum","höhlen des wehklagens smaragdgrüner traum","naralex smaragdgrüner traum"}}},fp="15,278,31.501.0,22.495.0,24.481.1,37.218.0,50.226.0,31.267.0,51.127.1,39.123.1,52.229.0"}
P.entries["zone:warsonggulch"] = {n="Kriegshymnenschlucht",s="An der Grenze zwischen Eschental und Brachland kämpfen Horde und Allianz ohne Unterlass in der Kriegshymnenschlucht. Orcs des Kriegshymnenklans schlagen Holz für die Horde, während die Nachtelfen der Feste Silverwing ihren heiligen Wald verteidigen. Kämpfer vieler Völker überfallen die gegnerische Festung, um deren Banner zu erbeuten.",h="An der Grenze zwischen Eschental und Brachland kämpfen Horde und Allianz ohne Unterlass in der...",kw={"kriegshymnenschlucht","schlachtfeld","vorhut des kriegshymnenklans","schildwachen der silberschwingen","feste silverwing","kriegshymnenmühle","flagge","bauholz","eschental","grom hellscream"},ang={["faction:Alliance"]="Soldaten der Allianz kämpfen an der Seite ihrer Nachtelfenverbündeten, während die Äxte des Kriegshymnenklans Bäume in deren heiligem Wald fällen.",["faction:Horde"]="Jeder Stamm aus der Kriegshymnenmühle hilft, irgendwo in Kalimdor eine Mauer der Horde zu errichten. Haltet die Schlucht, und die Horde kann weiterbauen.",["race:NightElf"]="Diese Wälder kennen die Schritte der Kaldorei seit zehntausend Jahren. Jeder aus der Schlucht vertriebene Orc bedeutet ein zurückgewonnenes Stück Eschental.",["race:Orc"]="Der Kriegshymnenklan ist Grom Hellscreams eigener Klan. In der Schlucht machen seine Krieger ihrem Namen noch immer Ehre, mit der Axt in der Hand gegen die Schildwachen."},sec={{t="Holz und Blut",b="Die Horde baut ihre Heimat in Kalimdor aus Holz, das zu großen Teilen im Eschental geschlagen wird. Der Kriegshymnenklan, Grom Hellscreams Krieger, fällt hier Bäume, seit die Horde erstmals an Land ging. Seine Kriegshymnenmühle am Ende der Schlucht liefert Holz für die Lager und Mauern der Horde. Die Nachtelfen sehen in jedem gefällten Baum eine Wunde in einem Wald, den sie seit zehntausend Jahren behüten. Sie erinnern sich auch daran, dass Groms Krieger Cenarius in diesen Wäldern erschlugen."},{t="Vorhut und Schildwachen",b="Die Kämpfer der Horde bilden die Vorhut des Kriegshymnenklans, die vom Mor'shan-Stützpunkt am nördlichen Rand des Brachlands versorgt wird. Dort hält Kelm Hargunth sie bewaffnet und verpflegt. Die Schildwachen der Silberschwingen aus der Feste Silverwing stellen sich ihnen entgegen.\n\nDiese Nachtelfenkrieger haben geschworen, jeden Eindringling aus dem Eschental zu vertreiben, und Illiyana Mondflamm versorgt sie im Hain der Silberschwingen. Auch Verbündete strömen in die Schlucht: Zwerge und Menschen an die Seite der Schildwachen, Tauren, Trolle und Verlassene an die Seite der Vorhut."},{t="Der Kampf um die Banner",b="Die Kriegshymnenmühle steht an einem Ende der Schlucht, die Feste Silverwing am anderen. Jede Festung beherbergt das Banner ihrer Seite. Kämpfer überfallen die feindliche Festung, ergreifen deren Flagge und eilen zurück, während Verteidiger sie jagen. Jedes heimgebrachte Banner trifft den Stolz des Feindes. Die Seite, die die meisten erbeutet, gewinnt den Tag."}},faq={{q="Was ist die Kriegshymnenschlucht?",a="Die Kriegshymnenschlucht liegt in einem bewaldeten Tal zwischen dem Eschental und dem Brachland. Dort kämpfen die Vorhut des Kriegshymnenklans der Horde und die Schildwachen der Silberschwingen der Nachtelfen um den Holzeinschlag der Horde und versuchen, die gegnerische Flagge zu erbeuten.",al={"was ist die kriegshymnenschlucht","kriegshymnenschlucht schlachtfeld","wsg"}},{q="Warum kämpft die Horde in der Kriegshymnenschlucht?",a="Die Horde braucht das Holz des Eschentals, um ihre Heimat in Kalimdor aufzubauen und zu halten. Die Kriegshymnenmühle an der Schlucht ist eine ihrer wichtigsten Holzquellen, und die Vorhut verteidigt sie, damit die Lager und Mauern der Horde entstehen können.",al={"was für die horde in der kriegshymnenschlucht auf dem spiel steht","warum fällen die orcs bäume im eschental","beweggrund der vorhut des kriegshymnenklans"}},{q="Warum kämpfen die Nachtelfen in der Kriegshymnenschlucht?",a="Die Nachtelfen behüten das heilige Eschental seit zehntausend Jahren, und der Kriegshymnenklan erschlug dort einst den Halbgott Cenarius. Die Schildwachen der Silberschwingen kämpfen mit dem Rest der Allianz an ihrer Seite, um den Holzeinschlag zu stoppen und die Orcs aus ihren Wäldern zu vertreiben.",al={"was für die allianz in der kriegshymnenschlucht auf dem spiel steht","warum kämpfen die schildwachen","beweggrund der schildwachen der silberschwingen"}},{q="Wer ist die Vorhut des Kriegshymnenklans?",a="Die Vorhut des Kriegshymnenklans besteht aus den Kämpfern der Horde in der Kriegshymnenschlucht und stammt aus dem einst von Grom Hellscream geführten Kriegshymnenklan. Sie erhält Nachschub am Mor'shan-Stützpunkt im nördlichen Brachland, wo Kelm Hargunth sie ausrüstet.",al={"vorhut des kriegshymnenklans","kämpfer des kriegshymnenklans","kelm hargunth"}},{q="Wer sind die Schildwachen der Silberschwingen?",a="Die Schildwachen der Silberschwingen sind Nachtelfenkrieger der Feste Silverwing, die geschworen haben, die Horde aus dem Eschental zu vertreiben. Im Hain der Silberschwingen versorgt Illiyana Mondflamm die Champions der Allianz, die in der Schlucht an ihrer Seite kämpfen.",al={"schildwachen der silberschwingen","feste silverwing","illiyana mondflamm"}},{q="Wie wird die Schlacht in der Kriegshymnenschlucht gewonnen?",a="Jede Seite bewahrt ihre Flagge in ihrer eigenen Festung auf. Kämpfer überfallen die feindliche Festung, ergreifen deren Flagge und tragen sie heim, während sie ihr eigenes Banner verteidigen. Die Seite, die die meisten Flaggen heimbringt, gewinnt.",al={"ziele in der kriegshymnenschlucht","flagge erobern kriegshymnenschlucht","wie gewinnt man die kriegshymnenschlucht"}}},fp="13,291,16.424.0,23.488.0,28.315.0,22.226.0,42.201.0,46.259.0,30.223.0,33.216.0,39.193.0"}
P.entries["zone:westernplaguelands"] = {n="Westliche Pestländer",s="Giftiger Nebel und Untotenlegionen ersticken die Westlichen Pestländer, wo Fraktionen um Boden kämpfen. Einst die Kornkammer des nördlichen Lordaeron, fielen ihre Höfe und Städte Kel'Thuzads Kesseln zum Opfer, doch im Boden hält sich noch Leben. Die Argentumdämmerung, die Allianz, die Verlassenen und der Scharlachrote Kreuzzug führen verzweifelte Feldzüge auf den verseuchten Feldern.",h="Giftiger Nebel und Untotenlegionen ersticken die Westlichen Pestländer, wo Fraktionen um Boden kämpfen.",kw={"andorhal","das bollwerk","darrowehr","pestkessel","zugwindlager","herdweiler","burg mardenholde","scholomance","uthers grabmal","westliche pestländer"},ang={["class:Paladin"]="Als Paladin steht Euch auf den entweihten Feldern Lordaerons eine ernste Prüfung bevor. Ihr könnt zu Uthers Grabmal pilgern und gegen die Schrecken von Scholomance sowie die verdorbenen Eiferer Herdweilers kämpfen.",["faction:Alliance"]="Das Zugwindlager ist der vorgeschobene Stützpunkt der Allianz. Kommandant Ashlam Valorfist leitet von dort Feldzüge, um die Pestkessel zu sabotieren und Lordaerons gefallene Städte zu rächen.",["faction:Horde"]="Das Bollwerk markiert die Grenze der Souveränität der Verlassenen. Von dort stößt die Horde nach Osten vor, um Kommandanten der Geißel auszuschalten und die Scharlachroten Eiferer an ihrer verwundbaren Flanke herauszufordern.",["profession:Herbalism"]="Als Kräuterkundiger könnt Ihr seltene und gefährliche Pflanzen wie Pestblüte und Arthas' Tränen zwischen verseuchten Kiefernwäldern finden, wo die anhaltende Verderbnis ihr Wachstum ermöglicht."},sec={{t="Lordaerons Kornkammer",b="Vor dem Dritten Krieg erstreckten sich Höfe östlich von Tirisfal bis zum Darrowmeresee. Herdweiler verwaltete den Norden von Burg Mardenholde aus, während Andorhal Getreide für das ganze Königreich lagerte und verschiffte. Deshalb machte Kel'Thuzad die Region zu seinem Hauptziel. In Andorhal mischte der Kult der Verdammten die Seuche des Untods unter die Getreidelieferungen und verwandelte Lordaerons Nahrungsvorräte in seinen Untergang."},{t="Ein belagertes Land",b="Die Geißel errichtete vier gewaltige Pestkessel, um den Boden zu vergiften. Sie stehen auf dem Teufelssteinfeld, auf Dalsons Tränenfeld, beim Trostlosen Feld und auf Gahrrons Trauerfeld. Monströse Kessellords bewachen die Bottiche und füllen die Luft mit giftigem Nebel. Bäume winden sich mit geschwollenen Wucherungen, und verseuchte Wildtiere toben durchs Dickicht. Unter Darrowehr im Darrowmeresee bildet Dunkelmeister Gandling in Scholomance Nekromanten aus und verstärkt so die Bedrohung durch Untote."},{t="Geteilte Fraktionen",b="Die Geißel hält einen Großteil der Region, doch andere Fraktionen behaupten ihre Stützpunkte. Im Norden kontrolliert der Scharlachrote Kreuzzug Herdweiler und läutert alles, was er für verseucht hält. Streitkräfte der Allianz sammeln sich im Süden im Zugwindlager, während die Verlassenen ihre Grenzen vom Bollwerk aus verteidigen. Die neutrale Argentumdämmerung lenkt den Kampf gegen die Kessel, unterstützt Streiter beider Fraktionen und bewacht Uthers Grabmal, den letzten wahrhaft geweihten Boden der Region."}},faq={{q="Warum traf die Seuche diese Gegend so schwer?",a="Andorhal verschiffte Getreide durch das nördliche Lordaeron und wurde dadurch zum Ziel Kel'Thuzads. Dort mischte der Kult der Verdammten die Seuche des Untods unter die Getreidelieferungen und errichtete dann auf vier großen Höfen Pestkessel, um den Untod über die Nahrungsvorräte des Königreichs zu verbreiten.",al={"warum sind die westlichen pestländer verseucht","was geschah mit andorhal","warum stehen hier pestkessel"}},{q="Wer kontrolliert Herdweiler im Norden?",a="Der Scharlachrote Kreuzzug kontrolliert Herdweiler und Burg Mardenholde. Die einstige Verwaltungszentrale der Region für Lordaeron wird nun von Eiferern gehalten, die Außenstehende an ihren Grenzen hinrichten und allen misstrauen, die nicht zum Kreuzzug gehören.",al={"fraktion in herdweiler","wer lebt in burg mardenholde","ist herdweiler freundlich"}},{q="Wo finden Spieler der Allianz und der Horde sichere Außenposten?",a="Die Allianz sammelt sich im Zugwindlager nahe der Südgrenze zum Alteracgebirge. Dort gibt es einen Flugmeister und Verbündete der Argentumdämmerung. Die Horde operiert vom Bollwerk an der Westgrenze aus, das von Tirisfal aus erreichbar ist.",al={"wo sind die flugrouten","hordenlager in den westlichen pestländern","allianzlager in den westlichen pestländern"}},{q="Wozu dienen die Pestkessel auf den Feldern?",a="Der Kult der Verdammten errichtete Pestkessel auf dem Teufelssteinfeld, auf Dalsons Tränenfeld, beim Trostlosen Feld und auf Gahrrons Trauerfeld. Sie pumpen Pestdämpfe in Luft und Boden. Agenten der Argentumdämmerung werben Abenteurer an, die Kessellords zu töten und die giftigen Gebräue mit Gegenmitteln zu bekämpfen.",al={"was sind die pestkessel","zweck der pestkessel","pestkessel auf dem teufelssteinfeld"}},{q="Was ist Scholomance und wo liegt es?",a="Scholomance ist eine unterirdische Akademie der Nekromantie, die von der Geißel und dem Kult der Verdammten betrieben wird. Sie liegt unter den Ruinen von Darrowehr, einer Festungsinsel im Südosten des Darrowmeresees.",al={"standort von scholomance","wo liegt scholomance","verlies darrowehr"}},{q="Ist ein Teil der Westlichen Pestländer unverdorben?",a="Uthers Grabmal auf dem Trauerhügel nahe dem Südrand der Region ist heilig und unberührt von der Verderbnis. Es ist ein geweihtes Denkmal für Hochgeneral Uther den Lichtbringer und den untergegangenen Orden der Silbernen Hand.",al={"heiliger boden in den westlichen pestländern","ist uthers grabmal unversehrt","ist uthers grabmal sicher"}}},fp="19,342,28.378.0,18.438.0,16.443.0,41.268.0,37.227.0,56.233.0,58.277.0,44.206.0,51.204.0"}
P.entries["zone:westfall"] = {n="Westfall",s="Westfalls Höfe liegen schutzlos da, und die Bruderschaft der Defias beherrscht weite Teile des Umlands. Einst die Kornkammer von Sturmwind, kommt das Gebiet nun ohne Unterstützung der Krone oder militärische Garnisonen kaum zurecht.",h="Westfalls Höfe liegen schutzlos da, und die Bruderschaft der Defias beherrscht weite Teile des Umlands.",kw={"die todesminen","defias","erntegolem","miliz","mondbruch","saldean","späherkuppe","starkmantel","van cleef","westfall"},ang={["class:Rogue"]="Als Schurke findet Ihr in ganz Westfall einen Schattenkrieg, in dem Spione von SI:7 den gewitzten Spähern, Dieben und Assassinen der Bruderschaft der Defias gegenüberstehen.",["faction:Alliance"]="Als Reisender der Allianz könnt Ihr sehen, wie die Volksmiliz die Späherkuppe hält. Ohne sie würde die Bruderschaft der Defias die südlichen Zugänge zum Wald von Elwynn kontrollieren.",["profession:Cooking"]="Als Koch könnt Ihr erfahren, wie sich die bedrängten Siedler auf Saldeans Farm mit zähen einheimischen Tieren behelfen und Reisenden beibringen, Westfall-Eintopf zuzubereiten.",["race:Human"]="Als Mensch zeigt Westfall den politischen Verfall von Sturmwind. Die Bauern, die im Dreck hungern, wurden von den Edlen im Stich gelassen, für die sie sich abmühten."},sec={{t="Ein zurückgelassenes Land",b="Westfalls Weiden und Weizenfelder versorgten einst das Königreich Sturmwind. Nach dem Zweiten Krieg wurden die Finanzen des Königreichs knapp, und seine Anführer vernachlässigten das Gebiet. Sturmwind schickte seine Ressourcen anderswohin und ließ seine Garnisonen abziehen. Das Land fiel brach.\n\nHeute machen öde Weiden, scharfe Küstenwinde, abtrünnige Erntegolems und Gnolle des Flusspfotenstamms den wenigen Siedlern, die noch geblieben sind, das Überleben schwer."},{t="Der Aufstieg der Bruderschaft",b="Die Ankunft der Bruderschaft der Defias beschleunigte Westfalls Niedergang. Die Banditen tragen rote Masken und folgen einem Anführer, dessen Namen niemand im Umland kennt. Sie machten Westfall zu ihrer Hochburg, verbrannten die Felder der Bauern, versalzten den Boden und bemächtigten sich verlassener Minen.\n\nVon Mondbruch aus, einer Geisterstadt, beherrscht die Bruderschaft fast das gesamte Umland, auch wenn sie es dem Namen nach nicht tut."},{t="Die Volksmiliz",b="Das Haus der Edlen hat Westfalls Notlage ignoriert, also haben die Einheimischen selbst zu ihrer Verteidigung gegriffen. Auf der Späherkuppe stellte Gryan Starkmantel die Volksmiliz auf, eine Freiwilligentruppe, die Gnollen und Banditen die Stirn bietet. Sturmwind schickt weder reguläre Soldaten noch Vorräte.\n\nDie Miliz ist auf umherziehende Abenteurer angewiesen, die die Defias zurückdrängen und die verbliebenen Höfe schützen."},{t="Steinmetze mit roten Masken",b="Edwin van Cleef führt die Bruderschaft an. Er war der Gildenmeister, der Sturmwind wiederaufbaute, doch das Haus der Edlen verweigerte seinen Steinmetzen den Lohn, und Aufstände trieben sie fort. In Westfall griffen sie zur roten Maske. Die Banditen, die seine Felder niederbrennen, sind dieselben Hände, die die Mauern der Hauptstadt errichteten."},{t="Die Verschwörung in den Todesminen",b="Unter Mondbruch hat Edwin van Cleef in den verlassenen Goldstollen der Todesminen Halsabschneider, Goblins und Abtrünnige versammelt. Die Bruderschaft baut dort einen gewaltigen gepanzerten Koloss. Er soll die Küste hinaufsegeln und Sturmwind bombardieren."}},faq={{q="Warum sind so viele Höfe in Westfall verlassen?",a="Sturmwind zog seine Garnisonen ab, als ihr Unterhalt zu teuer wurde, und ließ Westfall ungeschützt zurück. Daraufhin bemächtigte sich die Bruderschaft der Defias großer Teile des Umlands, vertrieb Siedler, brannte Ackerland nieder und programmierte mechanische Erntewächter zu tödlichen Wachen um.",al={"verlassene höfe","warum ist westfall tot","warum liegt westfall brach"}},{q="Warum schickt Sturmwind keine Truppen, um Westfall zu helfen?",a="Die Schatzkammer des Königreichs ist überlastet, und das Haus der Edlen gibt Bedrohungen in anderen Ländern höhere Priorität. Machtspiele am Hof haben Westfall zudem still und leise Aufmerksamkeit und Vorräte entzogen, sodass die Bewohner sich selbst verteidigen müssen.",al={"warum schickt sturmwind keine armee","wo sind die wachen","hilfe aus sturmwind"}},{q="Was ist die Volksmiliz?",a="Gryan Starkmantel stellte auf der Späherkuppe die Volksmiliz auf, um Westfall zu verteidigen. Da die Krone keine Soldaten schickt, schlossen sich Bauern und Siedler zusammen, um gegen die Bruderschaft der Defias und die Gnolle des Flusspfotenstamms zu kämpfen.",al={"volksmiliz","miliz auf der späherkuppe","gryans armee"}},{q="Wer führt die Bruderschaft der Defias in Westfall an?",a="Edwin van Cleef, der frühere Gildenmeister der Stonemasons Guild, führt die Bruderschaft der Defias an. Er beaufsichtigte den Wiederaufbau von Sturmwind, führte dann seine Arbeiter nach Westfall und bewaffnete sie, nachdem ein erbitterter Streit um die Bezahlung in Aufständen geendet hatte.",al={"anführer der defias","wer führt die defias an","van cleef"}},{q="Was ist in Mondbruch verborgen?",a="Unter einer unscheinbaren Scheune in Mondbruch liegt der Eingang zu den Todesminen. Die Bruderschaft der Defias machte aus der verlassenen Goldmine eine unterirdische Festung und Werft für ihren Krieg gegen Sturmwind.",al={"geheimnis von mondbruch","was ist in den todesminen","mine von mondbruch"}},{q="Warum greifen die mechanischen Vogelscheuchen Leute an?",a="Goblinbastler, die mit den Defias verbündet sind, erbeuteten die mechanischen Erntewächter, die ursprünglich für die Feldarbeit und zur Abschreckung von Schädlingen gebaut wurden. Sie rüsteten sie um, damit sie die Felder bewachen und Eindringlinge töten.",al={"erntegolems greifen an","erntewächter","böse vogelscheuchen"}}},fx={cd1e134e={q="Was ist Westfall?",a="Westfall ist das windgepeitschte westliche Territorium des Königreichs Sturmwind, das westlich des Wald von Elwynn und südlich bis zum Meer liegt. Einst die fruchtbare Kornkammer des Königreichs, ernährten seine sanften Hügel und weiten Weiden Sturmwind über Generationen hinweg. Heute, von der Krone vernachlässigt und von Konflikten verwüstet, ist es zu brachliegenden Staubebenen, verfallenen Gehöften und einem Gesetzlosen-Gebiet verkommen.",al={"was ist diese zone","erzähl mir von westfall","westfall lore"}},["44cadea7"]={q="Warum ist es hier so leer?",a="Eine Kombination aus Dürre, Vernachlässigung und Räubertum hat die Landschaft entvölkert. Nach dem Zweiten Krieg konzentrierte Sturmwind seine Soldaten anderswo und ließ die örtlichen Gehöfte schutzlos zurück. Als sich die Bruderschaft der Defias erhob, vertrieben sie Bauern, brannten Ackerland nieder und versalzten die Felder. Ohne königliche Garnisonen, die sie schützen konnten, flohen die meisten Bewohner oder verhungerten.",al={"warum ist westfall unfruchtbar","warum so leer","warum sind hier keine leute"}},["1a97e791"]={q="War Westfall schon immer so arm?",a="Ganz und gar nicht. Über Generationen hinweg war Westfall Sturmwinds stolzes landwirtschaftliches Herzland, berühmt für goldene Weizenfelder, reichen Boden und ertragreiche Goldminen wie Jangolode und die Todesminen. Seine Nahrung ernährte die Hauptstadt, und seine Minen füllten die königlichen Schatzkammern, bevor Kriege und innere Unruhen es unfruchtbar machten.",al={"war westfall schon immer arm","war westfall früher wohlhabend","westfall vergangenheit"}},["1d4a9481"]={q="Wer ist die Bruderschaft der Defias?",a="Die Bruderschaft der Defias ist eine riesige kriminelle Organisation, die sich aus abtrünnigen Steinmetzen, Dieben, Wegelagerern und Ausgestoßenen zusammensetzt. Unter der Führung von Edwin van Cleef besetzten sie die verlassenen Ackerflächen und Minen von Westfall, um einen erbitterten Schattenkrieg gegen das Königreich Sturmwind zu führen, mit der Absicht, Vergeltung für unbezahlte Schulden und vermeintliche Verrate zu üben.",al={"wer sind die defias","was ist die bruderschaft der defias","wer sind diese banditen"}},b6953315={q="Warum tragen die Defias rote Bandanas?",a="Rote Bandanas sind das Markenzeichen der Bruderschaft der Defias, und das Material zeigt den Rang eines Mitglieds an. Red Silk Bandanas kennzeichnen hochrangigere Mitglieder; Späherin Riell bittet Abenteurer, sie als Beweis für deren Tod zu sammeln.",al={"warum rote bandanas","defias rote masken","bedeutung rote masken"}},["908b4fe1"]={q="Was wollen die Defias in Westfall?",a="Sie behandeln Westfall als ihre souveräne Festung und ihren Stützpunkt. Indem sie die Goldminen kontrollieren, Nahrungsmittelvorräte beschlagnahmen und loyale Bauern vertreiben, können sie im Geheimen ihre Streitkräfte und Maschinen abseits von Sturmwinds direktem Blickfeld aufbauen, während sie den Untergang des Königreichs planen.",al={"was wollen die defias","defias ziele westfall","warum sind die defias in westfall"}},d384bc2d={q="Warum wurde ich nach Westfall geschickt?",a="Ihr wurdet hierher geschickt, weil Sturmwinds reguläres Militär sich weigert oder nicht in der Lage ist, Truppen nach Westfall zu entsenden, was das Territorium an den Rand des Zusammenbruchs durch das Räubertum bringt. Die Behörden im Wald von Elwynn leiten fähige Abenteurer nach Westen, um die kämpfenden Einheimischen zu unterstützen, die verzweifelt nach Hilfe suchen.",al={"warum bin ich in westfall","wer hat mich nach westfall geschickt","warum wurde ich hierher geschickt"}},d59f010f={q="Wer ist Gryan Starkmantel?",a="Gryan Starkmantel ist ein Paladin der Silbernen Hand und stammt aus Westfall. Als er nach dem Kampf in Lordaeron während des Dritter Krieg nach Hause zurückkehrte, fand er seine Heimat von Banditen überrannt und vom Militär Sturmwinds verlassen vor. Als Reaktion darauf versammelte er lokale Verteidiger, um die Bürgerwehr bei Späherkuppe zu gründen.",al={"wer ist starkmantel","gryan starkmantel","wer führt späherkuppe"}},af1c3ddb={q="Hat Gryan Starkmantel tatsächlich das Sagen in Westfall?",a="Praktisch gesehen, ja. Während der junge König in Sturmwind rechtlichen Anspruch auf Westfall erhebt, übt die Krone hier so gut wie keine wirkliche Autorität aus. Starkmantel und seine freiwillige Bürgerwehr bei Späherkuppe stellen die einzige funktionierende Verteidigung und Strafverfolgung dar, die im Reich verblieben ist.",al={"wer regiert westfall","ist starkmantel der anführer","wer hat das sagen"}},ec2fd06e={q="Hat Sturmwind sich wirklich geweigert, die Steinmetze zu bezahlen?",a="Ja. Das Haus der Adligen hatte durch die Ausweitung militärischer Expeditionen an anderen Orten erschütternde Schulden angehäuft, was das Königreich fast in den Bankrott trieb. Beeinflusst von Hofintrigen und aristokratischer Arroganz boten die Adligen für die gewaltige Arbeit nur ein Almosen an und weigerten sich schlichtweg, die vollständigen Verträge einzuhalten.",al={"hat sturmwind die steinmetze betrogen","warum haben die adligen nicht bezahlt","bezahlungsstreit der steinmetze"}},cf60f690={q="Warum gibt es so viele Gnolle in Westfall?",a="Die Gnolle des Flusspfotenrudels sind über die Grenze migriert, um das Fehlen von Soldaten aus Sturmwind auszunutzen. Schlimmer noch, die Bruderschaft der Defias heuerte sie aktiv als Söldner an und stationierte sie in den Hügeln und Ebenen, um Reisende zu überfallen und alle überlebenden Gehöfte zu schikanieren.",al={"warum sind hier gnolle","flusspfoten gnolle westfall","danuvin gnolle"}},e40fa3bd={q="Was ist Mondbruch?",a="Mondbruch war einst der primäre Markt und die Bergbaustadt im südlichen Westfall. Über dem alten Eingang zu den Todesminen gelegen, wurde es vollständig von der Bruderschaft der Defias besetzt und geräumt, die nun die leeren Gebäude als perimetrischen Schutz für ihre unterirdische Festung nutzen.",al={"was ist mondbruch","mondbruch lore","erzähl mir von mondbruch"}},["46f1c864"]={q="Wohin führt die Untersuchung der Defias?",a="Eure Ermittlungen decken das geheime Herz der Bruderschaft unter Mondbruch in den Todesminen auf. Dort, tief in den unterirdischen Höhlen, überwacht Edwin van Cleef den Bau eines gewaltigen, eisenbeschlagenen Juggernauts, der Sturmwind vom Meer aus beschießen soll, was zu einem direkten Angriff auf den Gildenmeister selbst führt.",al={"wohin führt die defias-questreihe","wie endet die defias-geschichte","abschluss todesminen"}},["27471424"]={q="Wie bin ich in Westfall gelandet?",a="Ihr seid wahrscheinlich über die Flussbrücke aus dem Wald von Elwynn der Straße nach Westen gefolgt, geschickt von Behörden oder Freunden von Späherkuppe. Da Sturmwind überlastet ist und keine königlichen Truppen entbehren kann, hat sich in den benachbarten Ländern herumgesprochen, dass Gryan Starkmantel und die lokalen Bauern verzweifelt fähige Hände benötigen. Ob Ihr dem Ruf nach Hilfe gefolgt seid oder einfach nur dem Königsweg auf der Suche nach Arbeit gefolgt seid, Ihr seid in ein Reich eingetreten, das die Soldaten des Königreichs so gut wie aufgegeben haben.",al={"wie bin ich hierher gekommen","wie bin ich nach westfall gekommen","wie bin ich hier gelandet"}},["6324593c"]={q="Was soll ich in Westfall tun?",a="Eure Hauptmission ist es, die Bürgerwehr bei Späherkuppe dabei zu unterstützen, die unzähligen Bedrohungen zurückzuschlagen, die die Provinz ersticken. Gryan Starkmantel braucht Freiwillige, um die aggressive Tierwelt auszudünnen, die abtrünnigen Erntebeobachter zum Schweigen zu bringen, die durch brachliegende Felder streifen, und die Gnolle des Flusspfotenrudels zurückzudrängen. Vor allem seid Ihr damit beauftragt, die schwer fassbare Bruderschaft der Defias zu jagen, aufzudecken, wo sie sich verstecken, und ihren Würgegriff auf das zu lösen, was von Westfalls kämpfenden Gehöften übrig geblieben ist.",al={"was sollte ich hier tun","was mache ich in westfall","warum bin ich hier"}},c01912f7={q="Was geschah mit der Stonemasons Guild?",a="Unter Gildenmeister Edwin van Cleef verbrachte die Stonemasons Guild nach dem Ersten Krieg Jahre damit, Sturmwind wiederaufzubauen. Als die Arbeit getan war, weigerte sich das House of Nobles, die vereinbarte Summe zu zahlen. Nachdem friedliche Bitten gescheitert waren, wurde die Gilde gewaltsam aufgelöst, was wütende Aufstände entfachte, die die Steinmetze ins Exil trieben.",al={"was geschah mit den steinmetzen","geschichte der steinmetzgilde","wer waren die steinmetze"}}},fp="8,190,18.391.0,27.355.0,20.380.0,19.294.1,24.254.1,44.264.0,52.230.0,29.199.0,45.227.1,32.204.1,51.187.0"}
P.entries["zone:wetlands"] = {n="Sumpfland",s="Nebel und Kämpfe prägen das Leben im Sumpfland zwischen Khaz Modan und der Baradinbucht. Zwergenkriege und Orc-Invasionen haben dieses Marschland zwischen Eisenschmiede und Lordaeron gezeichnet. Der Hafen von Menethil hält die Allianz mit fernen Küsten verbunden, während Orcs des Drachenmals, Murlocs und Gnolle das Land bedrohen.",h="Nebel und Kämpfe prägen das Leben im Sumpfland zwischen Khaz Modan und der Baradinbucht.",kw={"baradinbucht","drachenmalklan","dun algaz","dun modr","grim batol","menethil","hafen von menethil","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Für die Allianz ist der Hafen von Menethil die wichtigste Tiefwasserroute über das große Meer und verbindet die Östlichen Königreiche mit Außenposten in Kalimdor.",["profession:Mining"]="Als Bergarbeiter könnt Ihr in den Hügeln und Höhlen des Thelgenfelsens reiche Erzadern finden, darunter seltenes Pyrophorerz, das von Zwergenbergleuten und Ingenieuren gesucht wird.",["race:Dwarf"]="Für Zwerge steht das Sumpfland für den Verlust von Dun Modr, die Tragödie von Grim Batol und den andauernden Einsatz zur Verteidigung von König Magnis nördlicher Handelsroute."},sec={{t="Ein Land aus Wasser und Ruinen",b="Unterhalb des Steinwerkdamms liegt kaltes Marschland unter grauem Himmel und dichtem Nebel. Einst standen hier blühende Zwergensiedlungen. Heute füllen versunkene Steinruinen, durchnässte Moore und tückische Sümpfe das Land. Von Loch Modan aus gelangt Ihr durch den engen Pass bei Dun Algaz nach Norden, oder Ihr überquert die Bögen des Thandol-Übergangs aus dem Arathihochland."},{t="Die Narben von Grim Batol",b="Grim Batol ragt über dem östlichen Sumpf auf. Einst hielten die Wildhammerzwerge seine Hallen, doch der Krieg der drei Hämmer entweihte die Festung. Während des Zweiten Krieges machte der Drachenmalklan sie zu seiner Bastion. Dann befreite sich der rote Drachenschwarm aus der Gefangenschaft der Orcs und übte feurige Rache an ihnen. Dabei verwüstete er die Hänge.\n\nRote Wyrmkin bewachen die Tore des Drachenmals. Verwilderte Überlebende des Drachenmalklans leben in verstreuten Hügelcamps und bedrängen Reisende im ganzen Sumpf."},{t="Hafen an der Westküste",b="Der Hafen von Menethil säumt die Baradinbucht und führt Handel und Nachschub der Allianz durch Khaz Modan. Er ehrt König Terenas Menethil II. und verbindet die Östlichen Königreiche mit Kalimdor. Schiffe fahren zur Insel Theramore und über Süderstade nach Auberdine. Zwergische Verteidigungsanlagen schützen den Hafen, doch Küstenmurlocs, Sumpfkreaturen und Räuber bedrohen Schiffe in den felsigen Kanälen."},{t="Bedrohte Grenzen",b="Der Krieg erreicht das Sumpfland aus mehreren Richtungen. Im Norden sabotierten Dunkeleisenzwerge unter der Führung des Hexenmeisters Balgaras the Foul den Thandol-Übergang und nahmen Dun Modr ein. Überland-Nachschubzüge wurden abgeschnitten. Mosshide gnolls durchstreifen die zentralen Moore und bedrohen sogar Rethiel den Sumpfhüter, einen uralten Beschützer.\n\nSchurken-Orc-Kriegstrupps, Dunkeleisen-Infiltratoren und verfluchte Schiffswracks machen den Sumpf gefährlich. Seine Verteidiger müssen wachsam bleiben."}},faq={{q="Wie gelangt Ihr zu Fuß ins Sumpfland?",a="Nehmt von Loch Modan aus den Bergpass durch Dun Algaz nach Norden ins Sumpfland. Reisende aus dem Norden können den Thandol-Übergang aus dem Arathihochland überqueren. Feindliche Orcs des Drachenmals und Dunkeleisenzwerge kämpfen um beide Wege.",al={"wie kommt man ins sumpfland","weg ins sumpfland","zum sumpfland laufen"}},{q="Wohin fahren die Schiffe im Hafen von Menethil?",a="Ein Schiff fährt südwärts zur Insel Theramore in den Düstermarschen. Das andere läuft Süderstade im Vorgebirge des Hügellands an und überquert dann das große Meer nach Auberdine an den Ufern der Dunkelküste.",al={"schiffe in menethil","schiffe im hafen von menethil","wohin fährt das schiff im sumpfland"}},{q="Was ist Grim Batol und warum wird es bewacht?",a="Grim Batol ist eine uralte Zwergenfestung, die nach dem Krieg der drei Hämmer verlassen und später vom Drachenmalklan besetzt wurde. Nach dem Zweiten Krieg vertrieb der befreite rote Drachenschwarm die Orcs und versiegelte den Berg. Rote Drachkin und Wyrmkin patrouillieren an den Toren des Drachenmals, um Eindringlinge von den verfluchten Hallen fernzuhalten.",al={"warum gibt es drachen in grim batol","rote drachen in grim batol","tore des drachenmals"}},{q="Was geschah mit Dun Modr?",a="Dun Modr, eine nördliche Zwergenfestung, die den Thandol-Übergang bewacht, wurde vor Kurzem von Dunkeleisenzwergen unter Balgaras the Foul überrannt. Überlebende unter Rhag Garmason halten ein umkämpftes Lager in der Nähe und kämpfen darum, die Stadt zurückzuerobern.",al={"wer zerstörte dun modr","ruinen von dun modr","dunkeleisenzwerge in dun modr"}},{q="Wer ist Rethiel der Sumpfhüter?",a="Rethiel der Sumpfhüter ist ein uraltes Sumpfbiest, das im Grünen Gürtel des Sumpflands lebt. Er sucht die Hilfe von Reisenden gegen aggressive Mosshide gnolls und kranke Fen Creepers, damit sich das Moor erholen kann.",al={"der grüne gürtel","rethiel im sumpfland","wer ist der sumpfhüter"}},{q="Woher stammen all die Orcs im Sumpf?",a="Die Orcs im Sumpf gehören zum Drachenmalklan, der Grim Batol während des Zweiten Krieges befestigte. Nachdem der befreite rote Drachenschwarm sie verwüstet hatte, flohen Überlebende in den Sumpf und die Hügel. Sie überfallen noch immer Straßen und Reisende.",al={"warum gibt es orcs im sumpfland","drachenmalklan im sumpfland"}}},fx={["4984d286"]={q="Warum ist es hier überall Sumpf?",a="Das Sumpfland liegt in einem tiefen Becken, das an drei Seiten von hoch aufragenden Gebirgszügen begrenzt wird, die den Abfluss aus den Höhen darüber auffangen. Es wird von zahllosen Flüssen, Teichen und Bächen gespeist, die in Richtung der Baradinbucht fließen und die Erde ständig feucht und kalt halten.",al={"warum ist das sumpfland ein sumpf","geografie des sumpflands","warum so viel wasser im sumpfland"}},["60c5b961"]={q="Wer lebt im Sumpfland?",a="Die wichtigste zivilisierte Präsenz ist die Allianz im Hafen von Menethil, zusammen mit zwergischen Bergsteigern, die darum kämpfen, wichtige Außenposten zu halten. Die Wildnis wird jedoch von feindlichen Kräften dominiert: abtrünnige Orcs des Drachenmals, die sich in den östlichen Ausläufern verstecken, Mosshide-Gnolle, die durch die Moore streifen, Murlocs, die an den Küsten kriechen, und gewalttätige Dunkeleisenzwerge, die von Dun Modr aus nach Süden drängen.",al={"wer lebt hier","fraktionen im sumpfland","bewohner des sumpflands"}},["8d21dccb"]={q="Was ist der Hafen von Menethil und wer betreibt ihn?",a="Der Hafen von Menethil ist eine schwer befestigte Hafenstadt auf einer Insel in der Baradinbucht und dient als wichtigstes Küstentor der Allianz in Khaz Modan. Benannt zu Ehren von König Terenas Menethil II. von Lordaeron, wird sie von Zwergen und verbündeten Menschen unterhalten, durch die dicken Steinmauern von Burg Menethil geschützt und von der Garnison von Hauptmann Starkfaust bewacht.",al={"hafen von menethil","wer verwaltet menethil","stadt menethil"}},fd9bb568={q="Warum haben die Zwerge hier einen Hafen gebaut?",a="Während des Zweiten Krieges errichtete Orgrim Schicksalshammer hier eine Werft, um die Horde über die Baradinbucht nach Lordaeron zu übersetzen. Nachdem die Allianz die Orcs vertrieben hatte, beanspruchte sie den Ort für sich und baute ihn zu einem blühenden Hafen aus, wodurch wichtige maritime Versorgungsrouten etabliert wurden, die Khaz Modan sowohl mit menschlichen Verbündeten als auch mit fernen Ländern jenseits des Meeres verbinden.",al={"warum hafen von menethil","warum einen hafen im sumpf bauen","grund für den hafen von menethil"}},["4cff40a7"]={q="Ist der Hafen von Menethil Gebiet der Allianz?",a="Ja. Der Hafen von Menethil ist eine offizielle Festung der Allianz. Obwohl es eine raue, geschäftige Hafenstadt voller Seeleute, Händler, Reisender und grober Hafenarbeiter ist, weht dort das Banner der Allianz und sie wird von den Streitkräften aus Eisenschmiede verteidigt.",al={"ist menethil allianz","fraktion hafen von menethil","wem gehört der hafen von menethil"}},["6dc9c02b"]={q="Wer hat hier das Sagen?",a="Es gibt keinen einzelnen Herrscher über das ungezähmte Marschland. Die Autorität der Allianz konzentriert sich auf den Hafen von Menethil unter Hauptmann Starkfaust und der Garnison innerhalb von Burg Menethil. Außerhalb der Hafenmauern ist der Sumpf ein gesetzloses Grenzland, um das sich Militärpatrouillen, orcische Kriegsherren und urtümliche Bestien streiten.",al={"wer führt das sumpfland","kommandant des sumpflands","wer ist hier der chef"}},b8a9f96f={q="Wer ist Hauptmann Starkfaust?",a="Hauptmann Starkfaust ist der zwergische Kommandant, der die Garnison im Hafen von Menethil befehligt. Von der Sicherheit des Hafens aus koordiniert er Verteidigungsoperationen im gesamten Sumpf und beauftragt fähige Abenteurer damit, die unaufhörlichen Überfälle der nahegelegenen Orcs des Drachenmals einzudämmen.",al={"hauptmann starkfaust sumpfland","starkfaust lore","wer ist starkfaust"}},["38351a9f"]={q="Wer sind die Orcs des Drachenmals und warum sind sie hier?",a="Der Drachenmalclan ist ein brutaler Orcclan, der die Dämonenseele benutzte, um Alexstrasza und den roten Drachenschwarm während des Zweiten Krieges zu versklaven, und der von den Höhen von Grim Batol aus herrschte. Als die Drachenkönigin befreit wurde, zerschlugen die rachsüchtigen Drachen den Clan und zerstreuten die Überlebenden in die Sümpfe und Berge des Sumpflands, wo sie weiterhin eine gewalttätige, anhaltende Bedrohung darstellen.",al={"drachenmal sumpfland","warum sind drachenmal im sumpfland","orcs des drachenmals"}},ecc875bb={q="Wer sind die Dunkeleisenzwerge und warum greifen sie Dun Modr an?",a="Die Dunkeleisen sind ein tückischer, schattenwirkender Zwergenclan, der lange aus Eisenschmiede verbannt war. Sie nutzten aus, dass die Streitkräfte der Allianz im Ausland eingesetzt waren, stießen nach Norden vor, besetzten die Stadt Dun Modr und sabotierten den Thandol-Übergang, um wichtige Kommunikationswege zu kappen und Gebiete in Khaz Modan zurückzuerobern.",al={"dunkeleisen dun modr","warum dunkeleisen im sumpfland","dunkeleisen angriff sumpfland"}},["0f0d7fa8"]={q="Was ist der Thandol-Übergang und warum ist er wichtig?",a="Der Thandol-Übergang ist ein prächtiges Paar massiver steinerner Zwergenbrücken, die die Schlucht zwischen dem nördlichen Khaz Modan und dem Arathihochland überspannen. Er wurde nach dem Krieg der drei Hämmer gebaut, um Handel und Freundschaft mit den Wildhämmern zu erleichtern, und ist die einzige Landverbindung zwischen den südlichen Königreichen und dem nördlichen Lordaeron.",al={"thandol-übergang","thandol brücke","warum ist der thandol-übergang wichtig"}},faff9f74={q="Warum wollen die Dunkeleisen ihn in die Luft jagen?",a="Durch die Zerstörung des Thandol-Übergangs wollen die Dunkeleisen Eisenschmiede und Khaz Modan vollständig von den Verbündeten der Allianz in Lordaeron isolieren. Das Kappen dieser Überland-Lebensader verhindert, dass Verstärkung nach Süden marschiert, um Dun Modr zurückzuerobern oder bei weiteren Einfällen der Dunkeleisen zu helfen.",al={"warum thandol-übergang zerstören","dunkeleisen brückenkomplott","thandol-übergang in die luft jagen"}},eabba297={q="Wie bin ich im Sumpfland gelandet und wohin führt der Weg als Nächstes?",a="Die meisten Reisenden kommen an, indem sie von Loch Modan aus durch den Gebirgspass von Dun Algaz nach Norden marschieren oder die lange Reise mit dem Schiff in den Hafen von Menethil antreten. Von hier aus führt die Straße weiter nach Norden über den Thandol-Übergang in das Arathihochland, während Schiffe, die von den Docks ablegen, Abenteurer westlich über das große Meer tragen.",al={"wohin vom sumpfland aus","nächstes gebiet sumpfland","sumpfland weg"}},["75fb0ece"]={q="Ist das die Straße nach Eisenschmiede?",a="Ja. Wenn Ihr der Straße aus dem Sumpf nach Süden folgt, gelangt Ihr direkt in die engen Tunnel von Dun Algaz. Wenn Ihr das Gebirge durchquert, kommt Ihr nach Loch Modan, von wo aus die Hauptstraße nach Westen durch den Nordtorpass direkt in den Schnee von Dun Morogh und Eisenschmiede führt.",al={"straße nach eisenschmiede sumpfland","wie kommt man von sumpfland nach eisenschmiede","pfad nach eisenschmiede"}},["78aee5e0"]={q="Wie bin ich im Sumpfland gelandet?",a="Die meisten Reisenden der Allianz erreichen das Sumpfland, indem sie von Loch Modan aus nach Norden reisen und die engen Bergtunnel von Dun Algaz trotzen, um in die nebligen Marschlande unterhalb abzusteigen. Andere kommen mit dem Schiff von jenseits des großen Meeres an und segeln von den Küsten von Kalimdor in den Hafen von Menethil. Wer vom Arathihochland aus nach Süden reist, muss stattdessen die gefährlichen Übergänge des zerstörten Thandol-Übergangs meistern.",al={"wie bin ich hierher gekommen","wie kam ich im sumpfland an","woher bin ich gekommen"}},["87ca94d2"]={q="Was soll ich im Sumpfland tun?",a="Das Moor ist ein schwer bedrängtes Grenzland, in dem die Allianz an einem zerbrechlichen Stützpunkt festhält. Vom Hafen von Menethil aus seid Ihr dazu aufgerufen, wichtige Handelsrouten zu sichern und die verbliebenen Orcs des Drachenmals zurückzuschlagen, die das Tiefland überfallen. Weiter östlich und nördlich benötigen zwergische Bergsteiger Euren Stahl, um feindliche Gnollrudel einzudämmen, belagerten Ausgrabungsstätten zu helfen und Dunkeleisenzwerge zurückzudrängen, die drohen, den Thandol-Übergang vollständig zu unterbrechen.",al={"was soll ich hier tun","warum bin ich hier","was ist meine mission im sumpfland"}},["2cd88152"]={q="Was ist das Sumpfland?",a="Das Sumpfland ist ein kaltes, weitläufiges Marschland, eingebettet zwischen den Bergen von Khaz Modan und dem westlichen Meer. In ewigen grauen Nebel gehüllt, liegt es unmittelbar nördlich von Loch Modan und südlich vom Arathihochland. Einst Heimat zahlreicher Zwergensiedlungen, wurde die Region von vergangenen Kriegen verwüstet und dient nun als raue, ungezähmte Wildnis, die die Zwergenkönigreiche von den Ruinen von Lordaeron trennt.",al={"was ist das sumpfland","sumpfland lore","erzähl mir vom sumpfland"}}},fp="8,284,24.340.0,23.473.0,22.380.0,18.430.0,40.227.0,41.185.0,41.317.0,26.225.0,31.198.1,46.224.0"}
P.entries["zone:winterspring"] = {n="Winterquell",s="Schneestürme fegen über Winterquell hinweg, wo alte Gefahren noch immer das Leben prägen. Hoch oben an den nordöstlichen Hängen des Hyjal liegt das Tal oberhalb von Mondlichtung und Teufelswald. Uralte Ruinen der Hochgeborenen und wilde Raubtiere prägen das Land, während die Ewige Warte in seinem Herzen liegt. Blaue Drachen finden hier Zuflucht, und dämonische Verderbnis erfasst die südlichen Höhen.",h="Schneestürme fegen über Winterquell hinweg, wo alte Gefahren noch immer das Leben prägen.",kw={"blaue drachen","die flüsternde schlucht","donova schneeweh","ewige warte","frostsäbler","eiskappe","kel'theril","mazthoril","holzschlund","winterquell"},ang={["class:Druid"]="Hoch über Mondlichtung hat Winterquell für Druiden eine heilige Bedeutung. Während des Dritten Krieges erweckte Malfurion Sturmgrimm hier die Druiden der Klaue aus ihrem uralten Schlaf.",["faction:Alliance"]="Helden der Allianz besuchen Rivern Frostwind am Frostsäblerfelsen, trotzen Winterquells Kälte und verdienen sich die Treue der angesehenen Winterquell-Frostsäbler als Reittiere.",["profession:Herbalism"]="In Winterquell wachsen die Eiskappe, ein alpines Kraut, das es sonst nirgends gibt, sowie Bergsilberweisling und der seltene Schwarze Lotus. Alchemisten suchen Eiskappe für fortgeschrittene Mixturen.",["profession:Mining"]="Winterquells eisige Felsen und Höhlenwände bergen kleine und reiche Thoriumadern sowie seltene Truesilbervorkommen.",["race:NightElf"]="Winterquell ist eng mit der Geschichte der Elfen verbunden. Die Druiden der Klaue ruhten Jahrtausende in seinen Grabhügeln, Kel'Theril liegt in Trümmern und Nordrassils freiliegende Wurzeln tragen Schäden aus der Schlacht am Hyjal."},sec={{t="Ein Reich ewigen Frosts",b="Schneestürme ziehen über Winterquells Hochwälder, Felsklippen und gefrorene Seen. Weit unterhalb des Gipfels erhebt sich das Tal über die umliegende Wildnis, umweht von kalter Bergluft. Gewaltige Wurzeln Nordrassils, des Weltbaums, wölben sich durch die Schneewehen, verdreht von den Kämpfen des Dritten Krieges. Im nördlichen Kalimdor ist es meist warm und dicht bewaldet, doch diese alpinen Wälder bieten Frostsäblern, Chimären, Yetis und Winterbären Zuflucht."},{t="Das Wegekreuz und Außenposten",b="Uralte Passagen durch die Holzschlundfeste verbinden Winterquell mit Teufelswald und Mondlichtung. Unverdorbene Furbolgs bewachen den Weg und mustern Reisende, die ihn passieren. Im Zentrum des Tals betreiben Goblins des Steamwheedle Cartels die Ewige Warte, eine Handelsstadt, die Allianz und Horde offensteht. Handel, Ingenieurskunst und warme Feuer bieten Schutz vor der Kälte der Berge."},{t="Alte Geister und blaue Drachen",b="Die zerstörten Säulen von Kel'Theril ragen neben einem gefrorenen See auf. Die Geister der einst dort lebenden Hochgeborenen spuken zwischen ihnen. Leichtsinnige Zauberer zerschmetterten den verfluchten Kristall von Zin-Malor, und der Wahnsinn ergriff sie. Weiter südlich bergen Mazthorils Höhlen die Festung des blauen Drachenschwarms auf Kalimdor. Haleh, seine schützende Matrone, wacht über Malygos' Brut, während diese arkane Strömungen bewacht und sich nahen Gefahren stellt."},{t="Der drohende Schatten der Schlucht",b="Die Flüsternde Schlucht durchbricht die Ruhe am südlichen Rand Winterquells. Dämonische Streitkräfte, die vom Dritten Krieg zurückgeblieben sind, kriechen durch ihre zerklüfteten Schluchten und versperren die hochgelegenen Zugänge zum Gipfel des Hyjal. Auch die Winterfall-Furbolgs sind übler Verderbnis anheimgefallen. Unabhängige Forscher wie Donova Schneeweh untersuchen die sich ausbreitende Verderbnis, während sie die Tierwelt des Tals bedroht."}},faq={{q="Wie komme ich nach Winterquell?",a="Winterquell liegt hinter der Holzschlundfeste, einem Tunnelsystem im Nordosten des Teufelswalds. Die Holzschlund-Furbolgs greifen Reisende an, die sie für feindselig halten. Ihr müsst also ihr Vertrauen gewinnen, um friedlich hindurchzukommen. Der östliche Ausgang führt auf Winterquells verschneite Hänge.",al={"nach winterquell gelangen","winterquell betreten","winterquell eingang","holzschlund tunnel winterquell"}},{q="Wer betreibt die Stadt Ewige Warte?",a="Das Steamwheedle Cartel betreibt die Ewige Warte. Seine Goblinhändler halten die Stadt neutral, sodass Reisende der Horde und der Allianz ihre Flugmeister, Reparaturhändler, Banktresore und Waren nutzen können, solange sie den Frieden wahren.",al={"wer kontrolliert die ewige warte","fraktion der ewigen warte","ist die ewige warte neutral"}},{q="Was sind die Geister am Kel'Therilsee?",a="Die Geister sind Hochgeborene Nachtelfen, die vor zehntausend Jahren in Kel'Theril lebten. Ihre Zauberer hantierten mit dem gestohlenen Kristall von Zin-Malor. Als er zersplitterte, entfesselte das einen Fluch, der sie in den Wahnsinn trieb. Jahrhunderte später verfielen auch Expeditionen von Hochelfen dem Wahnsinn. Nun spuken sie neben ihren Ahnen in den gefrorenen Ruinen.",al={"geister am kel'therilsee","geister in den ruinen von kel'theril","wer ist in kel'theril"}},{q="Warum sind die Winterfall-Furbolgs feindselig?",a="Die Winterfall-Furbolgs sind einer sich ausbreitenden, unnatürlichen Verderbnis anheimgefallen, die ihren Stamm in feindseligen Wahnsinn getrieben hat. Die nahen Holzschlund-Furbolgs haben ihren Verstand bewahrt, während dunkle Einflüsse die Winterfall-Furbolgs beherrschen. Forscher wie Donova Schneeweh untersuchen die Verderbnis und säubern die Lager des Stammes.",al={"warum sind die winterfall feindselig","verderbnis des winterfall stamms","donova schneeweh furbolgs"}},{q="Was lebt in Mazthoril?",a="Mazthoril ist der wichtigste Rastplatz und Zufluchtsort des blauen Drachenschwarms auf Kalimdor. Unter Halehs Aufsicht bewachen Wyrmkin, Elitewelpen und uralte Drachen in den höhlenartigen Türmen Drachenerbstücke und arkane Geheimnisse. Sie ist die Gefährtin des Aspekts Malygos.",al={"mazthoril drachen","was ist mazthoril","blaue drachen in winterquell"}},{q="Was ist die Flüsternde Schlucht?",a="Die Flüsternde Schlucht ist eine gefährliche Schlucht am südlichen Rand des Tals, die von mächtigen Dämonen aus dem Dritten Krieg gehalten wird. Sie bewachen die gefährlichen Pfade zu den Höhen des Hyjal.",al={"dämonen der flüsternden schlucht","was ist in der flüsternden schlucht","hyjal zugang winterquell"}},{q="Kann man hier Frostsäbler ausbilden oder zähmen?",a="Am Frostsäblerfelsen im hohen Norden Winterquells kümmert sich der Nachtelf Rivern Frostwind um die dort heimischen weißen Katzen. Helft ihm, Vorräte zu sichern und das Rudel zu schützen, dann könnt Ihr Euch als würdig erweisen, einen Frostsäbler aufzuziehen und zu reiten.",al={"frostsäbler reittier","rivern frostwind frostsäbler","wie bekomme ich einen frostsäbler"}}},fp="12,328,26.408.0,23.361.0,26.385.0,31.374.0,29.250.0,30.220.0,45.324.0,43.293.0,28.244.0,26.191.0,39.225.0"}
P.entries["zone:zephras"] = {n="Insel Zephras",s="Auf der Insel Zephras sehen die Skyborne ihrer langsam zerfallenden Heimat entgegen. Einst lebten Luftelementare auf der Insel, doch diese Wächter verschwanden und die Magie, die das Land in der Luft hält, schwindet. Flüchtlinge treffen von Anvilas und Siroccas ein, während diese Inseln zerfallen.",h="Auf der Insel Zephras sehen die Skyborne ihrer langsam zerfallenden Heimat entgegen.",kw={"luftschiffe","anvilas","elementarebene","siroccas","skyborne","der himmelswall","valanaar","windsteine","zephras"},ang={["class:Shaman"]="Als Schamane wisst Ihr, dass die Insel Zephras in der Elementarebene der Luft liegt. Ihre schwindende Elementarkraft zeigt, was geschieht, wenn die Geister verschwinden, die ein Elementarland erhalten.",["race:Skyborne"]="Als Skyborne ist die Insel Zephras Eure Heimat der Ahnen und Euer Ausgangspunkt. Ihre Schönheit bleibt bestehen, während das Land zusammenbricht und die Elementarkraft schwindet."},sec={{t="Ein Reich in den Lüften",b="Im Himmelswall, der Elementarebene der Luft, leben die Skyborne seit Generationen auf der Insel Zephras. Einheimische Luftelementare halfen einst dabei, die magischen Strömungen zu bewahren, die die Insel in der Luft halten. Vor mehreren Jahrhunderten verschwanden diese Elementare. Ohne sie wurden die Verzauberungen unter dem Land allmählich schwächer, und Zephras beginnt zu zerbrechen."},{t="Getrennte Horizonte",b="Anvilas und Siroccas trieben einst neben Zephras durch den Himmelswall, und die Skyborne lebten auf allen drei Inseln. Als die Elementare verschwanden, brach der Kontakt zwischen den Inseln ab. Nun haben Flüchtlinge von den zerfallenden Nachbarinseln Zephras erreicht und suchen Schutz. Sie berichten, dass das Land unter ihnen auf Anvilas und Siroccas auseinanderbricht."},{t="Schwelle nach Azeroth",b="Während Zephras zerfällt, blicken die Skyborne über den Himmelswall hinaus nach Azeroth. Luftschiffe brechen nun von den Himmelsdocks Valanaars auf, um seltene Verbindungen zum Reich der Sterblichen herzustellen. Ihre Reisen führen sie in die Randgebiete von Dalaran im Alteracgebirge und zum Himmelsschauerplateau in Mulgore."}},faq={{q="Wo liegt die Insel Zephras?",a="Die Insel Zephras schwebt im Himmelswall, der Elementarebene der Luft, und nicht auf Azeroth. Wolken und Windströmungen umgeben die Insel in diesem ätherischen Reich.",al={"lage der insel zephras","wo liegt zephras","auf welcher ebene liegt zephras"}},{q="Warum zerfällt die Insel Zephras?",a="Einst lebten einheimische Luftelementare neben den Skyborne und halfen, die Insel Zephras zu erhalten. Sie verschwanden vor mehreren Jahrhunderten, und die magischen Fundamente der Insel sind seither allmählich schwächer geworden.",al={"warum zerfällt zephras","zerstörung der insel zephras","sterbende insel"}},{q="Was sind Anvilas und Siroccas?",a="Anvilas und Siroccas sind benachbarte schwebende Inseln, auf denen die Skyborne im Himmelswall leben. Der Kontakt zu beiden brach ab, als die Elementare verschwanden, und Flüchtlinge berichten nun, dass die Inseln zusammenbrechen.",al={"anvilas","siroccas","andere skyborne-inseln"}},{q="Wie reisen die Bewohner zwischen der Insel Zephras und Azeroth?",a="Die Skyborne lassen Luftschiffe von den Himmelsdocks Valanaars aufsteigen und reisen damit nach Azeroth. Sie erreichen die Randgebiete von Dalaran im Alteracgebirge und das Himmelsschauerplateau in Mulgore.",al={"wie verlässt man zephras","luftschiffe von zephras","reise nach azeroth"}},{q="Wer sind die Skyborne?",a="Die Skyborne leben seit Generationen auf der Insel Zephras und in den Schwesterreichen am Himmel. Ihre Heimatinsel zerbricht langsam, während die Magie schwindet, die sie erhält.",al={"volk der skyborne","wer lebt auf zephras"}},{q="Wer lebt außer den Skyborne auf der Insel Zephras?",a="Auf der Insel Zephras leben örtliche Banditen, in Höhlen hausende Nachtklauen und wilde Tiere. Sie sind an Orten wie dem Kreischlingsbau und der Nachtklauenhöhle zu finden.",al={"bewohner von zephras","feinde auf zephras"}}},fx={["6e14d755"]={q="Werde ich die Insel irgendwann verlassen?",a="Ja. Während Insel Zephras als Euer Zuhause und anfänglicher Trainingsort dient, legen Luftschiffe von den Himmelsdocks in Valanaar ab, die durch dimensionale Risse das Festland von Azeroth erreichen und eine direkte Verbindung zu Dalaran im Alteracgebirge sowie zum Himmelsschauerplateau in Mulgore herstellen.",al={"werde ich zephras verlassen","insel zephras verlassen","können wir nach azeroth reisen"}},["19470e71"]={q="Wie bin ich auf Insel Zephras gelandet?",a="Ihr wurdet in das Volk der Himmelsgeborenen hineingeboren, den Shen'dorei, die auf dieser schwebenden Zuflucht hoch über Der Himmelswall, der Elementarebene der Luft, leben. Vor Jahrtausenden flohen Eure Vorfahren vor der Säuberung durch Prinz Tortheldrin in Eldre'Thalas und schlossen einen Pakt mit Windgeistern, die dieses Heiligtum in den Himmel hoben. Während andere Schwesterinseln wie Anvilas und Siroccas zerbröckeln oder in unerreichbare Ferne rücken, war Insel Zephras von Anfang an Euer Zuhause. Ihr beginnt Eure Reise hier inmitten Eures eigenen Volkes.",al={"wie bin ich hierher gekommen","wie habe ich insel zephras erreicht","warum bin ich hier aufgewacht","woher komme ich"}},["5dae6f41"]={q="Was soll ich auf Insel Zephras tun?",a="Euer Zuhause bröckelt unter Euren Füßen. Vor Jahrhunderten verschwanden die wohlwollenden Luftelementare und die arkanen Pylone, die Insel Zephras zusammenhalten, verlieren an Kraft. Flüchtlinge strömen von den zusammenbrechenden äußeren Inseln herbei, während rivalisierende Fraktionen, darunter Der Hohe Orden, die Windformer und die Al'Aketh, um das streiten, was noch übrig ist. Ihr müsst Eurem Volk helfen, interne Bedrohungen und wilde Bestien bezwingen, dabei helfen, die versagende Magie zu stabilisieren und letztendlich einen Weg hinunter nach Azeroth finden, bevor die Insel stürzt.",al={"was soll ich hier tun","was ist mein ziel hier","was mache ich auf insel zephras","warum bin ich hier"}},["1fd88046"]={q="Was ist die Insel Zephras?",a="Die Insel Zephras ist eine hoch aufragende, schwebende Landmasse innerhalb des Himmelswalls, der Elementarebene der Luft. Vor Jahrtausenden handelten verbannte Nachtelfen, die der Verfolgung in Eldre'Thalas entkamen, mit einheimischen Windgeistern, die die Insel in den Himmel hoben, um sie in Sicherheit zu bringen. Sie dient als angestammtes Heiligtum ihrer Nachkommen, den Himmelsgeborenen.",al={"was ist zephras","über die insel zephras","infos zur insel zephras"}},["7ea7c85c"]={q="Was ist auf der Insel Zephras passiert?",a="Die Insel Zephras wurde in den Himmelswall gehoben, nachdem hochgeborene Vorfahren sich von der blutigen Herrschaft von Prinz Tortheldrin in Eldre'Thalas abwandten. Die Himmelsgeborenen lebten jahrtausendelang in Harmonie mit Luftelementaren, doch vor Jahrhunderten verschwanden jene elementaren Gönner ohne Erklärung. Ohne ihre fortwährende Magie begannen die Pylone, die die Insel verankerten, zu verfallen, und Flüchtlinge von benachbarten, einstürzenden Inseln sind hierher geflohen, während interne Fraktionen um schwindende Ressourcen wetteifern.",al={"zephras geschichte","was ist hier auf zephras passiert","zephras lore"}},["70a3c6ae"]={q="Ist die Insel Zephras gefährlich?",a="Ja. Jenseits der drohenden physischen Gefahr, dass die Insel selbst instabil wird und vom Himmel stürzt, hat das Verschwinden der elementaren Beschützer das Land chaotisch hinterlassen. Banditenlager, feindliche Wildtierbaue und explosive politische Reibereien zwischen dem Hohen Orden, den Windformern und Al'Aketh machen Reisen außerhalb befestigter Siedlungen gefährlich.",al={"ist zephras gefährlich","zephras bedrohungen","gefahren auf zephras"}},b4875d06={q="Wo liegt die Insel im Vergleich zum Rest von Azeroth?",a="Die Insel Zephras ruht nicht auf der Oberfläche von Azeroth; sie treibt innerhalb des Himmelswalls, einer separaten dimensionalen Domäne, die von den Titanengeschmiedeten geschaffen wurde, um chaotische Luftelementare einzudämmen. Die einzigen physischen Verbindungen zwischen der Insel und der sterblichen Welt unterhalb sind spezialisierte Luftschiffe, die in Valanaar anlegen und über die Grenze zu Orten wie Dalaran und Mulgore reisen.",al={"wo liegt zephras zu azeroth","ist zephras in azeroth","zephras standort im vergleich zu azeroth"}},["2c89f95d"]={q="Wer sind die Al'Aketh?",a="Die Al'Aketh sind eine der rivalisierenden Fraktionen, die neben dem Hohen Orden und den Windformern um die Vorherrschaft auf der Insel Zephras kämpfen. Da die Pylone, die die Insel verankern, versagen und das Überleben immer verzweifelter wird, wetteifern die Al'Aketh aktiv um die Vorherrschaft und die Kontrolle über die verbleibenden mystischen Ressourcen der Insel.",al={"was sind die alaketh","fraktion al'aketh","wer ist alaketh"}}},fp="12,263,13.353.0,16.350.0,20.265.0,30.156.0,34.190.0,30.197.0,54.178.0,21.180.0,47.152.0"}
